P.entries["subzone:garren-s-haunt"] = {n="加伦鬼屋",s="加伦鬼屋是一座坐落在提瑞斯法林地北部的荒废农庄。这座农场曾是富饶的人类家园，但在天灾军团屠戮了加伦一家后，农场便陷入了荒芜，杂草丛生的土地也被野蛮的腐皮豺狼人所占据。",h="加伦鬼屋是一座坐落在提瑞斯法林地北部的荒废农庄。这座农场曾是富饶的人类家园，但在天灾军团屠戮了加伦一家后，农场便陷入了荒芜，杂草丛生的土地也被野蛮的腐皮豺狼人所占据。",kw={"农庄","加伦鬼屋","蛆眼","瘟疫","腐皮","提瑞斯法林地"},ang={["race:Undead"]="这座破败的农场是诞生被遗忘者那场大屠杀的冷酷见证，清理掉这些肮脏的腐皮豺狼人有助于为黑暗女王巩固提瑞斯法北部的安全。"},sec={{t="被枯萎的家园",b="在第三次战争之前，这座农庄在洛丹伦王国的治下供养着一家人，并出产丰厚的收成。当亡灵瘟疫席卷这片土地时，天灾军团降临并屠杀了加伦和他的亲人。如今，田地一片灰暗凋零，农舍和谷仓在提瑞斯法永恒的阴霾下腐朽。"},{t="腐皮占领者",b="加伦鬼屋并没有常规的天灾军团巡逻队，而是被腐皮豺狼人占据了——这是一群受亡灵瘟疫感染的拾荒者，由凶残的蛆眼领导。这些拾荒者咄咄逼人地守卫着他们重新占领的领地，搜刮农场仅存的一切，并袭击任何经过提瑞斯法北部的旅行者或被遗忘者巡逻队。"}},faq={{q="加伦是谁？",a="加伦是一位人类农夫，在第三次战争前与家人居住在这里。他们耕作周围的田地，直到天灾军团横扫洛丹伦，在瘟疫蔓延期间屠杀了加伦全家。",al={"加伦背景故事","谁住在这里","加伦的故事"}},{q="现在是什么生物占据了农场？",a="农场里到处都是以蛆眼为首的腐皮豺狼人。它们在田野和建筑物中游荡，攻击靠得太近的人。",al={"加伦鬼屋的怪物","这里有什么生物","谁控制了农场"}},{q="为什么叫加伦鬼屋？",a="它以其被谋杀的主人“加伦”的名字命名，“鬼屋”（Haunt）一词则代表了这片土地在全家被杀、家园在提瑞斯法的阴影下腐烂后的阴森荒凉状态。",al={"为什么叫鬼屋","加伦名字起源"}},{q="为什么被遗忘者不收复它？",a="被遗忘者在加固幽暗城以及对抗血色十字军和活跃的天灾军团残党方面已是兵力捉襟见肘。处理边远农场像腐皮豺狼人这样的拾荒者，大多留给了路过的雇佣兵和冒险者。",al={"为什么被遗忘者不理会","被遗忘者加伦鬼屋"}}},fx={f7a25cdf={q="加伦鬼屋是什么地方？",a="加伦鬼屋是一座广阔而荒废的农场，位于提瑞斯法林地北部。洛丹伦覆灭之前，这里曾是生产兴旺的农庄，有一座大型农舍、一间谷仓、几座筒仓和大片田地。如今，农作物在亡灵瘟疫的侵蚀下枯萎成灰色尘土，这座农场成了王国农业往昔的阴森见证。",al={"什么是加伦鬼屋","加伦鬼屋农场","加伦鬼屋在哪里"}},b3ebc210={q="加伦鬼屋发生过什么事？",a="洛丹伦遭受天灾侵袭期间，天灾军团席卷提瑞斯法林地，将乡间夷为废土。亡灵攻占农庄时，加伦和他的全家惨遭杀害。受污染的土地扼杀了田野中的生机，使这片土地沦为废墟，也让觅食腐肉的怪物占据了空荡荡的建筑。",al={"加伦鬼屋的历史","这里发生过什么","加伦鬼屋是如何被摧毁的"}},["0c808513"]={q="加伦鬼屋为何沦为废墟并被遗弃？",a="亡灵瘟疫席卷洛丹伦时，这座农庄遭到重创，居住在此的家族惨遭杀害，建筑也在被腐化的天空下逐渐腐朽。人类主人已被屠戮，周围土壤也遭到污染，无法再自然耕种，因此没有活着的农民留在此地照料土地，废弃的建筑便在迷雾中日渐破败。",al={"加伦鬼屋为何沦为废墟","加伦鬼屋为何被遗弃","是谁毁了加伦鬼屋"}},["41bc539b"]={q="加伦鬼屋危险吗？",a="是的。腐皮豺狼人及其首领 Maggot Eye 占据着这座废弃农场，会攻击接近其领地的旅人。",al={"加伦鬼屋安全吗","加伦鬼屋的危险","加伦鬼屋有多危险"}}},fp="14,244,20.360.0,22.348.0,15.228.0,35.133.0,32.199.0,38.254.0"}
P.entries["subzone:garrison-armory"] = {n="要塞军械库",s="要塞军械库是位于诅咒之地守望堡西南方山丘中的一处联盟采矿作业点。矿工和工程师们在地下矿脉中劳作，开采珍贵的矿物，以维持这座孤寂要塞的运转，并将初步的矿产资源运回暴风城。它是在这片荒凉的焦土荒野中，一条至关重要的工业命脉。",h="要塞军械库是位于诅咒之地守望堡西南方山丘中的一处联盟采矿作业点。矿工和工程师们在地下矿脉中劳作，开采珍贵的矿物，以维持这座孤寂要塞的运转，并将初步的矿产资源运回暴风城。它是在这片荒凉的焦土荒野中，一条至关重要的工业命脉。",kw={"诅咒之地","要塞军械库","矿井","守望堡","守望堡工程师","守望堡矿工","暴风城"},ang={["faction:Alliance"]="军械库的工人们不停地劳作，以确保守望堡能够获得源源不断的武器、盔甲和贸易物资，从而履行其孤寂的守望职责。",["profession:Mining"]="要塞军械库的矿井中蕴藏着从崎岖的诅咒之地岩层中开采出的珍贵矿脉，这使它成为了一个充满争夺的地下采石场。"},sec={{t="红色荒原中的命脉",b="在干旱荒芜的诅咒之地维持一座常驻军事要塞需要持续的补给，而守望堡无法完全依赖从暴风城出发的长途运输线。要塞军械库便是该要塞主要的工业挖掘点。在工头监督和工程师协助下，守望堡的矿工们在这些地下矿井中劳作，从大地中开采出珍贵的矿产。开采出的矿石直接供守望堡的铁匠锻造及要塞防御所用，或者运回首都，以换取要塞在监视黑暗之门时所需的粮食、工具和给养。"},{t="脆弱的工业",b="由于军械库远离守望堡的主城墙，挖掘作业始终暴露在红色荒漠的严酷威胁之下。恐槌食人魔和野生猛兽在周围的岩壁中徘徊。隧道内的工人们在武装守卫的保护下作业，他们深知任何对军械库的干扰都会直接威胁到守望堡维持其在荒凉前线监视的能力。"}},faq={{q="要塞军械库的用途是什么？",a="要塞军械库是由守望堡运营的联盟采矿设施。工人们在地下开采金属和矿物，以维持要塞的运转，并与暴风城进行贸易，换取必要的食物和装备。",al={"要塞军械库用途","这是什么矿井","为什么这里有矿井"}},{q="谁在军械库工作？",a="矿井由隶属于联盟的守望堡矿工、工程师和工头负责运营。在守望堡指挥部的监督下，他们致力于挖掘矿脉并维护井道。",al={"里面有什么人","军械库npc","要塞矿工"}},{q="为什么守望堡需要这座矿井？",a="守望堡坐落在荒凉的诅咒之地，位置偏远，难以维持定期的补给线。通过自行开采金属，要塞不仅能维修装备、加固防御，还能将多余的原材料运往暴风城，换取维持生存所需的关键物资。",al={"为什么守望堡需要它","军械库重要性","守望堡资源"}},{q="部落玩家可以进入要塞军械库吗？",a="军械库由敌对的联盟工人和守卫占据，但部落冒险者经常冒险深入其中，开采掩埋在矿道里的丰富矿脉。",al={"部落可以去这里吗","部落在要塞军械库","这里对部落安全吗"}}},fp="15,360,28.631.0,19.393.0,37.213.0,24.204.0,41.265.0,44.171.0"}
P.entries["subzone:gates-of-ironforge"] = {n="铁炉堡大门",s="铁炉堡大门是宏伟的主入口，引领旅人从丹莫罗雪山的山谷进入这座矮人首府。大门直接雕凿在险峻的山壁之上，内部矗立着一尊巨大的至高王莫迪姆斯·安威玛尔的雕像，守卫着这里。",h="铁炉堡大门是宏伟的主入口，引领旅人从丹莫罗雪山的山谷进入这座矮人首府。大门直接雕凿在险峻的山壁之上，内部矗立着一尊巨大的至高王莫迪姆斯·安威玛尔的雕像，守卫着这里。",kw={"平民区","丹莫罗","铁炉堡大门","铁炉堡入口","铁炉堡正门","莫迪姆斯·安威玛尔"},ang={["faction:Alliance"]="铁炉堡大门是联盟最坚固的堡垒之一，从丹莫罗寒冷的山谷发动围攻几乎无法撼动它分毫。",["race:Dwarf"]="站在至高王莫迪姆斯·安威玛尔那宏伟的雕像下，每一位矮人都会想起那个所有氏族在同一座山下同为一家的古老时代。"},sec={{t="山脉的门槛",b="沿着丹莫罗中部盘旋而上的防御坡道，即可抵达铁炉堡大门。这道大门气势恢宏，在白雪皑皑的低地平原上随处可见。穿过巨大的闸门，访客便进入了城市内部，首先映入眼帘的是一尊巨大的石像，纪念着至高王莫迪姆斯·安威玛尔——他在三锤之战前统一了各个矮人氏族的传奇统治者。穿过这些大门，便可直接抵达热闹的商业区：平民区。"}},faq={{q="铁炉堡大门通往哪里？",a="它们连接着丹莫罗外部的山区地形与铁炉堡城内。穿过这道门槛，你将直接进入平民区的西南部，那是这座城市繁忙的贸易与银行中心。",al={"铁炉堡入口","大门通往何处","铁炉堡大门位置"}},{q="门内的雕像是谁？",a="大门内侧的宏伟雕像描绘的是至高王莫迪姆斯·安威玛尔。他是一位睿智且受人爱戴的君主，在政治分歧将矮人分裂为铜须、蛮锤和黑铁氏族之前，他曾统治着所有的矮人氏族。",al={"铁炉堡大门雕像","巨大的矮人雕像","大门的雕像是谁"}},{q="如何从丹莫罗抵达大门？",a="从丹莫罗中部出发，向北走，登上开凿在山腰上的宽阔防御石坡道。坡道直通这座山中堡垒的外部入口。",al={"如何进入铁炉堡","铁炉堡大门路径","铁炉堡坡道"}}},fx={d3165cf1={q="铁炉堡大门是什么地方？",a="铁炉堡大门又称铁炉堡主门，是直接开凿在山体上的宏伟入口，连接丹莫罗的雪原与山内的矮人首都。这些巨大的石门雄踞于此，迎接从南面长坡而来的旅人；来客会经过高王 Modimus Anvilmar 的威严雕像，径直进入热闹的公共区。",al={"什么是铁炉堡大门","铁炉堡主门","铁炉堡大门概况"}},d5c3b229={q="铁炉堡大门危险吗？",a="不，铁炉堡大门对联盟成员和和平来客而言完全安全。坚毅的山地之王和铁炉堡卫兵在此严密守卫，这道宏伟的门户设防森严，足以抵御任何敌对势力的入侵，保护地下王国免受丹莫罗峭壁间的穴居人、冰霜巨魔和野兽侵扰。",al={"铁炉堡大门安全吗","铁炉堡大门的危险","大门安全吗"}},["7ab63378"]={q="为什么叫铁炉堡大门？",a="名称直白地说明了它的作用：这座宏伟而坚固的主门是进入铁炉堡的门户。铁炉堡是铜须矮人的古老山中家园。来访者穿过这些巨大的拱门，便从丹莫罗中部的严酷环境进入王国本身的地下炉火与石厅。",al={"为何叫铁炉堡大门","铁炉堡大门名称的含义","铁炉堡主门名称"}}},fp="18,283,29.506.0,37.216.0,45.253.0,43.183.0"}
P.entries["subzone:gates-of-orgrimmar"] = {n="Gates of Orgrimmar",s="Gates of Orgrimmar 是部落主城的雄伟南大门，直接凿刻在杜隆塔尔北部的红岩之中。这座宏伟的入口两侧由厚重的木材和钢铁壁垒环绕，连接着外面的干旱荒野与繁华的 Valley of Strength。它象征着兽人坚韧不拔的意志与强大的军事力量。",h="Gates of Orgrimmar 是部落主城的雄伟南大门，直接凿刻在杜隆塔尔北部的红岩之中。这座宏伟的入口两侧由厚重的木材和钢铁壁垒环绕，连接着外面的干旱荒野与繁华的 Valley of...",kw={"杜隆塔尔","gates of orgrimmar","正门","奥格瑞玛步兵","萨尔","valley of strength"},ang={["faction:Alliance"]="对于联盟的侦察兵和潜入者来说，这道大门是卡利姆多防御最森严的咽喉要道之一，几乎不可能通过正面突袭攻破。",["faction:Horde"]="这扇巨大的大门代表了安全、归属感，以及在萨尔大酋长领导下艰难建立的家园。"},sec={{t="杜隆塔尔堡垒",b="主门以高耸的木质栅栏、巨大的铁钉和坚固的瞭望塔为框架，守护着通往奥格瑞玛的群山中的主要峡谷。对于从剃刀岭和杜隆塔尔灌木丛赶来的旅行者来说，这座入口既是一个欢迎的纪念碑，也是对任何威胁新部落之敌的严厉震慑。全副武装的奥格瑞玛步兵在入口处巡逻，对进入城市的所有往来人员保持警惕。"},{t="通往山谷的门户",b="穿过大门阴影笼罩的拱门，便可直接进入奥格瑞玛的行政和军事中心——Valley of Strength。大门通道起到了声学和战术瓶颈的作用，将使者、商人和战士引导经过警惕的岗哨。它代表了萨尔大酋长的梦想得以实现：一个从严酷沙漠中开辟出来的安全庇护所，让部落各族人民可以在此无所畏惧地团结在一起。"}},faq={{q="Gates of Orgrimmar 通向哪里？",a="大门将杜隆塔尔北部与 Valley of Strength 直接相连，此处是奥格瑞玛的主要入口和中央公共区域。",al={"大门连接哪里","正门位置"}},{q="谁在守护大门？",a="正门由经验丰富的奥格瑞玛步兵守卫，时刻警惕着敌对潜入者和野生猛兽。",al={"谁守卫大门","守门卫兵"}},{q="为什么入口要用木头和铁钉加固？",a="这种建筑风格反映了传统的兽人边境防御工事，利用来自附近地区的坚固木材和铁钉，在峡谷墙壁之间制造出一个令人生畏且易于防守的咽喉要道。",al={"为什么使用木材和铁钉","兽人大门设计"}},{q="联盟玩家可以通过这道门吗？",a="试图穿过正门的联盟成员将立即面对敌对的精锐卫兵，他们随时准备击杀任何部落的敌人。",al={"联盟能否进入","联盟穿过大门"}}},fx={a102033b={q="Gates of Orgrimmar 是什么地方？",a="Gates of Orgrimmar 是进入部落首都的主要入口，设防森严。它直接开凿于杜隆塔尔北部崎岖的赤红峡谷壁上，这道气势逼人的木铁大门标示着贫瘠之地荒野与热闹的 Valley of Strength 之间的边界。",al={"gates of orgrimmar","gates of orgrimmar 是什么","奥格瑞玛大门"}},ecbfa379={q="这处入口为什么危险？",a="对于部落的忠诚勇士而言，这道关口象征着安全与力量。然而，对联盟成员来说，靠近这里就意味着死路一条。坚毅的奥格瑞玛步兵在塔楼和通道中巡逻，随时准备无情地击倒任何胆敢擅自靠近的入侵者。",al={"gates of orgrimmar 危险吗","大门危险吗","大门的危险"}},["86fa8d49"]={q="为什么叫 Gates of Orgrimmar？",a="这道大门以其守护的城市命名。萨尔建立了这座城市，并以旧任大酋长 Orgrim Doomhammer 之名为其命名。作为进出这座要塞城市的首要门户，它是兽人主权和 Doomhammer 不朽传奇的象征。",al={"为何叫 gates of orgrimmar","gates of orgrimmar 名称的含义"}}},fp="18,360,22.468.0,23.436.0,37.143.0,21.132.0,51.208.0,44.156.0"}
P.entries["subzone:gelkis-village"] = {n="吉尔吉斯村",s="吉尔吉斯村是位于凄凉之地西南部的半人马部族——吉尔吉斯部族的主要据点，他们崇尚大地。该定居点围绕着一道崎岖的峡谷而建，以木桥和悬崖小径相连，守卫着通往菲拉斯的南部道路。它占据的高地直接俯瞰着南北向的主干道，对于任何没有获得该部族好感的旅行者来说，穿越此处都是极其危险的。",h="吉尔吉斯村是位于凄凉之地西南部的半人马部族——吉尔吉斯部族的主要据点，他们崇尚大地。该定居点围绕着一道崎岖的峡谷而建，以木桥和悬崖小径相连，守卫着通往菲拉斯的南部道路。它占据的高地直接俯瞰着南北向的主干道，对于任何没有获...",kw={"波尔甘的洞穴","半人马","凄凉之地","菲拉斯","吉尔吉斯","可汗沙卡","玛格拉姆","葬影"},ang={["faction:Horde"]="由于暗矛巨魔的定居点葬影村坐落在正西方的海岸上，吉尔吉斯人筑起的防御工事对附近部落的行动构成了持续的威胁。",["race:Tauren"]="半人马世世代代将牛头人从他们的祖居地驱逐出去；看到吉尔吉斯人在他们的岩石堡垒中建立防御，这痛苦地提醒着人们，他们对卡利姆多构成的威胁依然存在。"},sec={{t="峡谷中的堡垒",b="吉尔吉斯村坐落在一道深邃、崎岖的峡谷中，周围是险峻的峭壁和绳桥。与贫瘠之地的游牧劫掠者不同，吉尔吉斯人将他们的祖居地修筑成了永久性的定居点，并向菲拉斯边界延伸出许多哨站。该部族的权力中心位于波尔甘的洞穴，这是一处在南部悬崖峭壁中开凿出的洞穴，可汗沙卡就在那里统御着他的战士。穿行在凄凉之地南部的旅行者要么必须在峡谷中杀出一条血路，要么就得小心翼翼，因为吉尔吉斯人将不请自来的流浪者视为猎物，这与他们同敌对半人马部族永无止境的战争有关。"}},faq={{q="谁住在吉尔吉斯村？",a="该定居点属于吉尔吉斯部族，这是凄凉之地交战中的半人马部族之一。他们是忠实的大地崇拜者，由居住在被称为波尔甘的洞穴的深处悬崖洞穴中的可汗沙卡统治。",al={"吉尔吉斯居民","谁控制着吉尔吉斯村","南部的半人马村庄"}},{q="为什么吉尔吉斯半人马对外来者充满敌意？",a="半人马文化具有强烈的领土意识，且对外来者十分好战。然而，吉尔吉斯人最痛恨的莫过于他们的敌对部族——玛格拉姆。积极猎杀玛格拉姆战士的冒险者最终可以赢得吉尔吉斯部族的信任，从而安全进入村庄。",al={"为什么吉尔吉斯人会发动攻击","吉尔吉斯人的敌意","我能与吉尔吉斯人友好相处吗"}},{q="吉尔吉斯村位于何处？",a="它位于凄凉之地西南部，在巨魔定居点葬影村的东侧稍偏南一点。它的峡谷与南部山脉接壤，俯瞰着直接通往菲拉斯南部的路径。",al={"吉尔吉斯位置","如何找到吉尔吉斯村","吉尔吉斯在哪里"}},{q="什么是波尔甘的洞穴？",a="波尔甘的洞穴是一处在峡谷南侧岩壁上开凿出的大型洞穴，通过高架桥和峭壁与村庄的其他部分相连。它是吉尔吉斯可汗的内心圣所和权力中心。",al={"波尔甘的洞穴","吉尔吉斯村的洞穴","吉尔吉斯可汗在哪里"}}},fp="14,382,24.642.0,28.207.0,48.264.0,32.221.0,22.223.0"}
P.entries["subzone:ghost-walker-post"] = {n="幽灵岗哨",s="幽灵岗哨是位于凄凉之地中心，紧邻古老的科多兽坟场的一处简朴牛头人定居点。与西海岸的葬影村相比，这里更加直接地暴露在地区的危险之中，是部落对抗半人马氏族和火刃氏族的前线补给基地。",h="幽灵岗哨是位于凄凉之地中心，紧邻古老的科多兽坟场的一处简朴牛头人定居点。与西海岸的葬影村相比，这里更加直接地暴露在地区的危险之中，是部落对抗半人马氏族和火刃氏族的前线补给基地。",kw={"火刃氏族","半人马","凄凉之地","幽灵岗哨","古尔达·蛮鬃","部落","科多兽坟场","葬影村","牛头人","萨尔"},ang={["class:Shaman"]="在古尔达·蛮鬃的带领下，这里的萨满祭司们从事着神圣的工作，与古老的灵魂对话，并引导垂死的巨兽进入灵魂世界。",["race:Tauren"]="这座营地体现了牛头人对自然界所肩负的神圣职责，作为守护者伫立在科多兽祖先的安息之地旁。"},sec={{t="荒野之哨",b="幽灵岗哨矗立在凄凉之地中央尘土飞扬的平原上，为部落在这片充满敌意的领土上提供了一个简陋的立足点。与背靠海岸、环境安逸的渔村葬影村不同，这座岗哨直面着四处游荡的半人马劫掠者和崇拜恶魔的火刃氏族邪教徒。这里的设施非常简陋，仅能为旅行者提供最基本的需求，没有旅店，也没有飞行管理员。尽管条件艰苦，但一支牛头人驻军和一支由萨尔大酋长派遣的兽人部队，始终保持着对这片荒地的警惕守望。"},{t="坟场守护者",b="在牛头人萨满祭司古尔达·蛮鬃的领导下，这座前哨站的精神核心与邻近的科多兽坟场紧密相连。驻扎在此的萨满祭司会照料那些步入此地等待死亡的巨兽，帮助它们安然进入来世，并与它们徘徊不去的灵魂进行交流。在凄凉之地的灰烬中，岗哨的守军通过精神沟通和时刻保持军事警备，以此尊崇牛头人与伟大的科多兽之间古老的羁绊。"}},faq={{q="什么是幽灵岗哨？",a="这是一处位于凄凉之地中央的小型、坚固的部落前哨站，主要由牛头人建立，并有兽人驻军提供支持。",al={"幽灵岗哨信息","这是什么营地","凄凉之地部落营地"}},{q="谁在领导幽灵岗哨？",a="这座岗哨由牛头人萨满祭司古尔达·蛮鬃领导，她负责照料营地的防御以及邻近的科多兽坟场。",al={"谁在负责","幽灵岗哨领导者","古尔达·蛮鬃"}},{q="为什么岗哨选址在科多兽坟场附近？",a="古尔达·蛮鬃和她的牛头人萨满同僚们驻扎在这里，是为了帮助垂死的科多兽安然度过最后的时光，并与这些倒下巨兽的灵魂进行沟通。",al={"为什么在科多兽坟场旁边","科多兽灵魂营地","萨满科多兽坟场"}},{q="幽灵岗哨对抗的是哪些敌人？",a="驻军一直在与当地敌对的半人马部落，以及在凄凉之地各地活动的火刃氏族邪恶势力进行持续的战争。",al={"幽灵岗哨敌人","谁攻击幽灵岗哨","岗哨威胁"}},{q="我可以在这里使用飞行航线或在旅店休息吗？",a="不能。这座前哨站仅能为冒险者提供最基本的必需品，既没有旅店老板，也没有双足飞龙管理员。旅行者必须前往其他地方，例如葬影村，来寻求交通服务。",al={"幽灵岗哨飞行管理员","幽灵岗哨旅店老板","这里有飞行点吗"}},{q="它与葬影村相比如何？",a="葬影村是西海岸的一处受保护的巨魔飞地，而幽灵岗哨位于内陆，直接暴露在周围的威胁之中，主要职能是边境防御和履行精神职责。",al={"葬影村与幽灵岗哨对比","凄凉之地的其他部落营地"}}},fp="17,296,21.553.0,26.464.0,26.134.0,28.119.0,48.152.0,42.144.0,47.188.0,42.198.0"}
P.entries["subzone:gnomeregan"] = {n="诺莫瑞根",s="诺莫瑞根曾是侏儒种族宏伟的地下首都，以其机械天赋和技术奇迹闻名于整个艾泽拉斯。如今，这里已成为一座放射性的坟墓，在一次绝望的防御战以灾难告终后，这里被地底穴居怪、失控的防御自动机和疯狂的麻风侏儒所占据。",h="诺莫瑞根曾是侏儒种族宏伟的地下首都，以其机械天赋和技术奇迹闻名于整个艾泽拉斯。如今，这里已成为一座放射性的坟墓，在一次绝望的防御战以灾难告终后，这里被地底穴居怪、失控的防御自动机和疯狂的麻风侏儒所占据。",kw={"丹莫罗","诺莫瑞根","麻风侏儒","gelbin mekkatorque","麦克尼尔·瑟玛普拉格","tinkers' court","穴居怪"},ang={["profession:Engineering"]="即使被放射性毒素充斥，诺莫瑞根依然是东部王国中图纸、先进备件和功能性工业机械最集中的地方。",["race:Gnome"]="每一个侏儒都背负着诺莫瑞根失陷的创伤。进入那片被辐射侵蚀的大厅，是一场旨在摧毁篡位者瑟玛普拉格并收复遗失的机械传家宝的庄严朝圣之旅。"},sec={{t="工程学的奇迹",b="诺莫瑞根开凿在丹莫罗西部的雪山峭壁之中，是数百年前在铁炉堡矮人的帮助下建成的。城内巨大的蒸汽驱动齿轮、错综复杂的铜管和巨大的装配大厅构成了侏儒族群的思想和工业核心。正是从这些地下大厅中，侏儒的设计、飞行器和复杂的武器装备在第二次战争期间支援了联盟，即使在遭受Orgrim Doomhammer部落围攻时依然屹立不倒。"},{t="陷落与被毒化的殿堂",b="第三次战争期间，一股地底穴居怪从地壳深处涌出，攻破了城市最底层的区域。由于不愿分散联盟军队去应对洛丹伦的屠杀，大工匠Gelbin Mekkatorque试图独自处理这场危机。在首席工程师麦克尼尔·瑟玛普拉格的建议下，Mekkatorque下令将放射性气体排放到下层区域以消灭这些野兽。该计划产生了可怕的后果：气体不仅增强了许多穴居怪的力量，还导致近百分之八十的侏儒人口死亡。幸存下来但暴露在毒气中的人变异成了扭曲的麻风侏儒，而麦克尼尔·瑟玛普拉格则夺取了这些被毒化废墟的统治权。"}},faq={{q="为什么诺莫瑞根充满了辐射？",a="当地底穴居怪占领这座城市时，大工匠Mekkatorque听从了麦克尼尔·瑟玛普拉格的建议，向底部通风口释放了放射性气体。这一绝望的策略旨在彻底消灭这些野兽，但结果却导致成千上万的侏儒丧生，幸存者变异成了麻风侏儒，城市也从此终年笼罩在辐射之中。",al={"为什么会有辐射","诺莫瑞根毒气","是什么毒化了诺莫瑞根"}},{q="所有幸存的侏儒现在在哪里？",a="幸存者逃到了附近的矮人城市铁炉堡。国王麦格尼·铜须在Tinkers' Court为他们提供了庇护，大工匠Gelbin Mekkatorque现在正在那里协调各项工作，以援助他流离失所的人民，并策划收复家园。",al={"侏儒住在哪里","侏儒难民","gelbin mekkatorque在哪里"}},{q="谁现在控制着诺莫瑞根？",a="Mekkatorque的前任首席顾问麦克尼尔·瑟玛普拉格自封为诺莫瑞根之王。因接触毒素和权力狂妄而疯狂的他，从城市核心深处指挥着城中失控的防御自动机、受辐射的麻风侏儒和变异的穴居怪。",al={"谁是诺莫瑞根的首领","诺莫瑞根领袖","瑟玛普拉格"}},{q="为什么联盟在入侵期间没有帮助拯救诺莫瑞根？",a="Mekkatorque刻意选择不向联盟寻求帮助。在第三次战争中，随着人类在天灾军团的重压下崩溃，侏儒们将他们的地下斗争保密，以免将关键的防御力量从洛丹伦吸引走。",al={"为什么联盟没有帮助","为什么人类没有帮助侏儒","第三次战争中的侏儒"}}},fx={["927c35f4"]={q="诺莫瑞根是什么地方？",a="诺莫瑞根是侏儒的地下首都，建在丹莫罗的雪峰之下。这里的锻铁工程、发条机械和蒸汽驱动技术令人惊叹。多代以来，这座城市一直是侏儒文化、创造力和政治力量的繁荣中心，也是他们矮人盟友的重要据点。",al={"什么是诺莫瑞根","诺莫瑞根城市","侏儒首都"}},["702e95d4"]={q="诺莫瑞根危险吗？",a="极其危险。下层深处弥漫着挥之不去的致命辐射，足以扭曲身心。大厅里遍布凶残的穴居人、精神失常的麻风侏儒、失灵的战斗自动机，以及自封国王热砂的致命陷阱。没有充分准备或可靠队伍就贸然进入，必将惨死。",al={"诺莫瑞根危险吗","诺莫瑞根的危险","诺莫瑞根有多危险"}}},fp="10,327,23.491.0,31.666.0,36.342.0,39.260.0,28.260.0,65.251.0"}
P.entries["subzone:go-shek-farm"] = {n="格沙克农场",s="格沙克农场是阿拉希高地东部的一个农业前哨站，由部落占领，并由来自落锤镇的兽人守卫。在它平凡的乡村外表下，被遗忘者药剂师们正在远离窥探目光的地方进行秘密的炼金实验。",h="格沙克农场是阿拉希高地东部的一个农业前哨站，由部落占领，并由来自落锤镇的兽人守卫。在它平凡的乡村外表下，被遗忘者药剂师们正在远离窥探目光的地方进行秘密的炼金实验。",kw={"药剂师乔瑞尔","阿拉希","格沙克农场","格沙克","落锤镇","基恩洛","奎艾","斯威","枯木"},ang={["faction:Alliance"]="该农场为落锤镇提供支持，并安置了被遗忘者药剂师，他们秘密的工作吸引了联盟的注意。",["faction:Horde"]="确保农场的安全对于维持落锤镇的物资供应至关重要，同时也为了维持一道严密的防线，以抵御入侵的枯木巨魔。"},sec={{t="东部的一处部落前哨站",b="格沙克农场由部落控制。它位于落锤镇以南，敌对的枯木巨魔领地以北，这座农场名义上是这座兽人定居点的重要补给和集结中心。落锤镇步兵在田野和马厩中巡逻，确保粮食和牲畜的供应，以维持部落在阿拉希高地岌岌可危的立足点。"},{t="药剂师的工作室",b="在耕种土地和照料牲畜的日常工作之下，隐藏着一个更黑暗的目的。皇家药剂师学会已经在农场建立了一个隐秘的据点，由药剂师乔瑞尔等人领导。信使在格沙克农场和塔伦米尔之间穿梭，运送着笔记、试剂以及关于被遗忘者新瘟疫早期变体的研究资料。联盟已经注意到这一点，并派遣侦察兵拦截这些信使，以揭开正在阿拉希的土地上酝酿的毒药的本质。"}},faq={{q="部落为什么要占领格沙克农场？",a="这座农场为附近的兽人据点落锤镇提供必要的农产品和牲畜。此外，它还为被遗忘者提供了一个隐秘且有守卫的集结地，用于进行敏感的化学和炼金研究。",al={"谁拥有格沙克农场","为什么兽人在格沙克农场","格沙克农场 部落"}},{q="这个农场以前属于谁？",a="农场早期的所有者并无记录。今天它属于部落，由附近的落锤镇兽人耕种和守卫。",al={"格沙克农场历史","阿拉希的人类农场","普里姆威尔·斯凯"}},{q="这里正在进行什么样的实验？",a="被遗忘者药剂师在农场进行秘密的炼金工作。联盟特工正试图通过调查信使往来和存放在那里的记录来查明其本质。",al={"药剂师乔瑞尔","阿拉希瘟疫实验","格沙克被遗忘者研究"}},{q="为什么有联盟特工在监视这个农场？",a="奎艾和基恩洛正在调查农场与塔伦米尔之间的可疑往来。他们正在寻找被遗忘者活动的证据，并需要帮助来获取这些证据。",al={"奎艾 基恩洛","联盟侦察格沙克","新瘟疫的迹象"}}},fp="12,249,27.359.0,25.490.1,40.239.0,26.125.0,44.174.0,48.168.0"}
P.entries["subzone:goblin-foundry"] = {n="Goblin Foundry",s="Goblin Foundry是位于死亡矿井深处的一座工业工坊，地精技工在此为迪菲亚潜行者制造重型金属制品。一个巨大的熔炼大锅占据了该空间，在基尔尼格的领导下，地精工匠和工程师们依然在此忙碌。",h="Goblin Foundry是位于死亡矿井深处的一座工业工坊，地精技工在此为迪菲亚潜行者制造重型金属制品。一个巨大的熔炼大锅占据了该空间，在基尔尼格的领导下，地精工匠和工程师们依然在此忙碌。",kw={"大锅","死亡矿井","迪菲亚","goblin foundry","范克里夫"},ang={["faction:Alliance"]="迪菲亚工坊揭示了该组织在西部荒野地下工业资源的规模。",["profession:Engineering"]="该铸造厂展示了地精的金属加工和机械创造力，工程师们使用遥控傀儡来保卫工坊。"},sec={{t="工业雄心",b="Goblin Foundry开凿在月溪镇的地下深处，为迪菲亚潜行者提供了强大的重工业生产能力。地精工匠和工程师们在熔炉和铁制坡道间工作，制造船锚和炮弹。"},{t="基尔尼格的工坊",b="基尔尼格统领着该铸造厂的地精劳动力。工匠们维持生产，而工程师们则用遥控傀儡保卫工坊，这使得其狭窄的坡道和熔化的金属对入侵者来说十分危险。"}},faq={{q="Goblin Foundry里在制造什么？",a="地精工匠们为迪菲亚潜行者生产重型金属制品，包括船锚和炮弹。",al={"他们在这里制造什么","铸造厂的目的","死亡矿井工厂"}},{q="为什么铸造厂里会有傀儡？",a="地精工程师使用遥控傀儡来保卫他们的工坊，以抵御入侵者。",al={"为什么这里有傀儡","铸造厂机器人","死亡矿井的机械敌人"}},{q="经营这家工坊的地精在哪里？",a="地精工匠和工程师们在熔炉工基尔尼格的领导下，依然在铸造厂内工作。",al={"地精在哪里","铸造厂工程师","基尔尼格的工人"}},{q="房间中央的大型结构是什么？",a="房间中央矗立着一个巨大的工业熔炼大锅，用于熔化从矿井中运出的矿石，以锻造护甲板和机械底盘。",al={"铸造厂中心大锅","熔炼大桶","死亡矿井里的大锅"}}},fx={a84744f8={q="Goblin Foundry 是什么地方？",a="Goblin Foundry 是死亡矿井地下建筑群深处一座洞穴般宽敞的工业作坊。这里由受雇于迪菲亚潜行者的地精雇佣工程师建造和运营，内部设有大型冶炼设备、走道和工坊，旨在为艾德温·范克里夫的隐秘叛乱打造金属制品、工具和战争机械。",al={"什么是 goblin foundry","goblin foundry 的背景","这座铸造厂是什么"}},bbcfa33c={q="Goblin Foundry 发生过什么事？",a="地精工匠和工程师建起这座铸造厂，将其作为迪菲亚潜行者的作坊投入运作。基尔尼格负责管理金属加工，工程师则使用遥控魔像守卫这里。",al={"这里发生过什么","铸造厂的历史","goblin foundry 的故事"}},["60ac21cc"]={q="Goblin Foundry 里进行什么工作？",a="这座铸造厂仍在运作。地精工匠和工程师在基尔尼格的管理下工作，为迪菲亚潜行者生产金属制品。",al={"goblin foundry 里进行什么工作","地精在铸造厂制造什么","goblin foundry 的生产"}},["22e4861d"]={q="Goblin Foundry 危险吗？",a="这座铸造厂对闯入者而言十分危险。地精工匠、工程师及其遥控魔像守卫着巨型熔炼锅周围的狭窄坡道。",al={"goblin foundry 危险吗","铸造厂的危险","goblin foundry 的威胁"}},["11526e87"]={q="为什么叫Goblin Foundry？",a="这间大厅以受雇于迪菲亚潜行者、负责运营这里的地精技师和冶金师命名。它专为地精工程学和冶炼量身打造，配有精巧的坡道、爆破坩埚和工作台，处处体现着他们雄心勃勃的爆炸性工业计划。",al={"为什么叫goblin foundry","goblin foundry名称由来","谁给goblin foundry命名"}}},fp="14,271,20.238.0,17.215.0,43.108.0,36.89.0,44.91.0,54.167.0"}
P.entries["subzone:gol-bolar-quarry"] = {n="古博拉采掘场",s="古博拉采掘场是一处开凿在丹莫罗东南部雪山中的矮人挖掘场。这里盛产石料和矿石，但随着从深处涌出的凶残穴居人泛滥成灾，这座繁忙的采矿场已陷入停滞。",h="古博拉采掘场是一处开凿在丹莫罗东南部雪山中的矮人挖掘场。这里盛产石料和矿石，但随着从深处涌出的凶残穴居人泛滥成灾，这座繁忙的采矿场已陷入停滞。",kw={"丹莫罗","古博拉","矿井","勘探员格恩","采掘场","穴居人"},ang={["profession:Mining"]="裸露的岩层和相邻的隧道中拥有丰富的矿脉，尽管勘探者们必须杀穿那些盘踞其中的穴居人才能接近它们。",["race:Dwarf"]="清理古博拉采掘场既是经济上的必要，也是氏族的荣誉所在，因为铁炉堡无法容忍粗野的穴居人夺取其山中资源。"},sec={{t="被围困的采掘场",b="古博拉采掘场位于卡拉诺斯东南方，由铁炉堡的矮人建立，旨在从群山中开采重要的石料和矿产资源。然而，深层的挖掘工作意外挖穿了地下巢穴，释放出大群充满敌意的穴居人，它们迅速驱逐了矿工。如今，上层营地成了一个饱经战火的集结地，监工、商人和勘探员格恩在此招募矮人和侏儒新兵，试图将这些野兽赶走并夺回矿坑。"}},faq={{q="古博拉采掘场是什么地方？",a="古博拉采掘场是位于丹莫罗东南部的一处露天采矿场。它由铁炉堡矮人维护，既是挖掘现场，也是一个为当地冒险者提供补给和工作的微型前哨站。",al={"古博拉","这是什么地方","采掘场信息"}},{q="为什么这里有这么多穴居人？",a="矮人矿工挖掘得太深，不慎打通了穴居人居住的地下隧道。这些生物蜂拥进入露天矿坑和相邻的矿井，迫使矿工们撤退到了采掘场的上层边缘。",al={"为什么这里有穴居人","穴居人入侵","是谁袭击了采掘场"}},{q="勘探员格恩是谁？",a="勘探员格恩是一位驻扎在采掘场营地的矮人主管。他负责监督确保挖掘场安全的行动，并向愿意猎杀穴居人的冒险者发布悬赏和任务。",al={"格恩是谁","勘探员格恩"}}},fx={e8696793={q="古博拉采掘场发生了什么？",a="古博拉采掘场最初是丹莫罗东南部一处活跃的矮人挖掘场和采矿营地，专门开采石料和珍贵矿物。然而，穴居人在地下突破防线，闯入下层挖掘区和附近矿井后，常规作业骤然停摆。这些凶残的生物迅速击溃矿工，迫使矮人撤退，并在采掘场上方的山脊上建立了设防营地，招募人手夺回此地。",al={"古博拉采掘场的历史","古博拉发生了什么","古博拉的背景"}},["3a8dc0a0"]={q="谁住在古博拉采掘场，或负责管理那里？",a="一群坚韧的矮人矿工、监工和后勤人员驻守在俯瞰矿坑的营地。勘探者格恩和其他挖掘者负责管理这处前哨，其中有武器商人、补给商和专业训练师，为年轻的山地探险者提供支援，助他们击退穴居人的威胁。",al={"谁管理古博拉采掘场","古博拉采掘场营地","谁住在古博拉"}},becb3bb6={q="古博拉采掘场危险吗？",a="危险。当地矮人守护着上层边缘和小营地，但露天矿坑以及下方的采掘场矿井里都挤满了敌对的穴居人。任何旅人若不小心就进入挖掘区，都可能遭到这些凶猛的掘洞者围攻，它们把这里据为己有。",al={"古博拉危险吗","古博拉采掘场的危险","古博拉的威胁"}}},fp="16,238,20.470.0,25.217.0,34.226.0,23.195.0"}
P.entries["subzone:gol-bolar-quarry-mine"] = {n="Gol'Bolar Quarry Mine",s="Gol'Bolar Quarry Mine 是位于丹莫罗东部，深处古博拉采掘场腹地的一处被占领的挖掘坑。这里原本由矮人矿工开采，但隧道意外凿穿了地下的穴居人洞穴，引发了一场猛烈的虫害，整个地点因此沦陷。如今，最深处的矿井已成为由残暴的 Hammerspine 领导的穴居人战团的据点。",h="Gol'Bolar Quarry Mine...",kw={"丹莫罗","古博拉","gol'bolar quarry mine","hammerspine","矿井","采掘场","穴居人"},ang={["profession:Mining"]="这座矿井时刻提醒着人们地下挖掘的危险，在最深处的隧道被肃清之前，它将完全被敌对的穴居人封锁。",["race:Dwarf"]="每一次向山中挥动十字镐都伴随着唤醒地下沉睡之物的风险。夺回 Gol'Bolar Mine 既是出于经济上的必要，也是矮人尊严的象征。"},sec={{t="深处的裂口",b="这座矿井由铁炉堡矮人建立，他们原本是在丹莫罗崎岖的山峰下寻找石料和丰富的矿脉。然而，当矿工们的十字镐凿穿了一堵墙，连接到古老的地下穴居人洞穴系统时，开采工作戛然而止。这些地下野兽从黑暗中蜂拥而出，击溃了施工队并迫使他们仓皇撤退，最终甚至蔓延到外围，占领了整个采掘场。"},{t="Hammerspine 的巢穴",b="虽然年轻而弱小的穴居人在采掘场盆地的露天梯田上游荡，但矿井本身却盘踞着战团中最凶猛的战士。在狭窄且火把摇曳的隧道深处，潜伏着他们残暴的酋长 Hammerspine。夺回这处宝贵的采掘场是当地山地探险队员的当务之急，但想要驱逐这些害虫，必须深入矿井最黑暗的深处，从源头切断这些野兽。"}},faq={{q="为什么矿井里满是穴居人？",a="矮人矿工在挖掘过程中意外凿穿了一个隐藏的地下洞穴。蛰伏在内的穴居人穿过裂口涌出，屠杀或驱逐了挖掘人员，并将矿井占为己有。",al={"为什么古博拉有穴居人","穴居人是怎么来的","谁占领了矿井"}},{q="是谁领导着 Gol'Bolar Quarry Mine 里的穴居人？",a="矿井里的穴居人由 Hammerspine 领导，这是一个身形巨大的蛮汉，他从矿井深处指挥着战团中最强大的成员。",al={"矿井首领","古博拉穴居人领袖","谁是 hammerspine"}},{q="矿井和采掘场的其他部分有什么不同吗？",a="是的。外部的采掘坑是地面作业区，只有弱小的穴居人，而矿井内部则是深邃、幽闭的地下隧道，聚集着最强悍的穴居人和他们的酋长。",al={"采掘场与矿井的区别","矿井里的穴居人更厉害吗"}},{q="矿工还能在这里工作吗？",a="不能。所有的采矿作业已经完全停止。这里现在是一个活跃的战区，矮人山地探险队员和冒险者们正在努力清除穴居人的威胁，而不是开采石料。",al={"矿井还在运作吗","矮人还在采矿吗"}}},fx={["58d8a204"]={q="Gol'Bolar Quarry Mine发生了什么？",a="矮人勘探者一直在矿井中积极开采，直到他们挖通了一个穴居人盘踞的地下洞穴系统。矮人遭到突袭，又被野蛮的攻势压倒，最终被暴力驱逐出地下深处，内层隧道和周围采掘场都落入入侵者手中。",al={"gol'bolar quarry mine的历史","矿井发生了什么","gol'bolar quarry mine的背景故事"}},["2d64c093"]={q="Gol'Bolar Quarry Mine危险吗？",a="这里比外面的采掘场危险得多。较弱的拾荒者在露天矿坑中游荡，而最深处的狭窄隧道里则潜伏着最强大的穴居人，听命于残暴的首领Hammerspine。任何毫无准备的闯入者都将面临致命的地下伏击。",al={"gol'bolar quarry mine危险吗","gol'bolar quarry mine有多危险","gol'bolar quarry mine的穴居人威胁"}}},fp="21,366,20.435.0,19.432.0,31.222.0,50.145.0,50.192.0,27.181.0"}
P.entries["subzone:golakka-hot-springs"] = {n="葛拉卡温泉",s="葛拉卡温泉是安戈洛环形山西部的一个地热盆地，坐落在恐惧小道以北。它那翻涌的池水和喷发的间歇泉是由附近的火羽山强烈的火山活动所驱动的。富含矿物质的水域吸引了古怪的研究者、寻找异域试剂的炼金师，以及被称为Steaming Furies的游荡水元素。",h="葛拉卡温泉是安戈洛环形山西部的一个地热盆地，坐落在恐惧小道以北。它那翻涌的池水和喷发的间歇泉是由附近的火羽山强烈的火山活动所驱动的。富含矿物质的水域吸引了古怪的研究者、寻找异域试剂的炼金师，以及被称为Steaming...",kw={"火羽山","间歇泉","葛拉卡","温泉","krakle","spark nilminer","steaming fury","恐惧小道","安戈洛"},ang={["class:Shaman"]="温泉展现了火与水之间激烈的相互作用，这种元素冲突导致在矿物河岸边诞生了沸腾的Steaming Furies。",["race:Gnome"]="这种极端的地理活动为像Spark Nilminer这样的侏儒提供了无尽的乐趣，他冒着滚烫的压力喷口，近距离观察地热力学现象。"},sec={{t="沸腾的水域与火山蒸汽",b="葛拉卡温泉位于安戈洛环形山的西部，直接源自火羽山散发出的地底热量。滚烫的水不断涌上地表，形成了层叠的矿物梯田和猛烈喷发的间歇泉。这里到处都是Steaming Furies，它们是地底地下水与火山热能汇聚而诞生的元素化身。尽管危险重重，这些温泉还是经常吸引着对环形山独特地质着迷的探险家、草药师和研究者。"},{t="好奇的居民与奇异的化学",b="葛拉卡温泉水的独特属性所吸引的关注早已超出了单纯的观光范畴。炼金师们将这种富含地热的泉水视为一种强效的催化试剂，甚至将其用于爱情药水等精细的调配中。地热喷口还接待了一些古怪的访客，比如栖身在中心间歇泉喷口顶端的Spark Nilminer，以及研究员Krakle，他试图解读这些温泉是如何直接接入环形山的火山之心的。"}},faq={{q="为什么这里的泉水如此炽热？",a="这些温泉是由安戈洛环形山地下的强烈火山系统加热的，并与火羽山直接相连。环形山底部的岩浆使地底水储备过热，迫使沸腾且富含矿物质的水和蒸汽通过间歇泉和梯田状的池塘喷涌而出。",al={"为什么水会沸腾","安戈洛的地热","与火羽山的联系"}},{q="什么样的生物居住在葛拉卡温泉？",a="在岸边和池塘中巡逻的最主要生物是Steaming Furies。它们是活水元素之灵，被火山喷口灼热的高温转化为翻腾且不稳定的蒸汽。",al={"温泉中的元素生物","葛拉卡的生物","steaming fury"}},{q="温泉水有什么用途？",a="这种富含矿物质的水因其独特的化学性质而受到炼金师和古怪酿酒师的推崇。值得注意的是，从泉水中采集的原始样本被视为酿造特殊配方（包括强效爱情药水）的重要试剂而备受追捧。",al={"葛拉卡水的用途","温泉爱情药水","温泉试剂"}},{q="Krakle是谁，他在这里做什么？",a="Krakle是一位研究者，他正在研究葛拉卡温泉与火羽山之间的地热关系，并在温泉周围收集观察数据和温度读数。",al={"krakle与安戈洛","krakle与温泉","温泉研究员"}}},fp="19,367,33.552.0,41.474.0,27.272.0,43.209.0,48.258.0,41.177.0"}
P.entries["subzone:gold-coast-quarry"] = {n="金海岸矿洞",s="金海岸矿洞是一座开凿在西部荒野西南面悬崖上的露天矿场。它曾是暴风城王国极为看重的石料、矿产和黄金来源，如今却已被迪菲亚潜行者占领，成为他们日益增长的反叛势力的补给来源。",h="金海岸矿洞是一座开凿在西部荒野西南面悬崖上的露天矿场。它曾是暴风城王国极为看重的石料、矿产和黄金来源，如今却已被迪菲亚潜行者占领，成为他们日益增长的反叛势力的补给来源。",kw={"迪菲亚","迪菲亚潜行者","金海岸矿洞","矿洞","平民军","采石场","暴风城","西部荒野"},ang={["faction:Alliance"]="收复金海岸矿洞这类地点对于恢复西部荒野的秩序至关重要，那里因为缺乏皇家驻军，迫使当地志愿者不得不拿起武器。",["profession:Mining"]="在西部荒野游荡的矿工会发现矿洞悬崖上分布着丰富的石壁和矿脉，但若想开采它们，就意味着必须杀出重围，对抗那些盘踞在此的迪菲亚巡逻队。"},sec={{t="掠夺而来的资源",b="在王国陷入动荡之前，金海岸矿洞曾提供建筑原材料和贵重的黄金，用于帮助重建暴风城。当皇家部队撤出西部荒野，使这片乡村地区失去保护后，迪菲亚强盗和叛变劳工便控制了这些矿坑。迪菲亚潜行者如今在阶梯状的石坡上巡逻，利用该地点俯瞰海岸的地理优势，并掠夺残余的矿产来资助他们的叛乱。"}},faq={{q="矿洞最初的用途是什么？",a="这座矿洞由暴风城王国建立，旨在从海岸悬崖中开采石料、矿产和黄金。在第二次战争后，西部荒野各地开采的石料在很大程度上支持了暴风城的重建工作。",al={"为什么这里有矿洞","他们在这里开采什么","金海岸的用途"}},{q="现在是谁在控制金海岸矿洞？",a="迪菲亚潜行者控制着这个地点。他们的强盗、掠夺者和劫匪在阶梯状的悬崖和矿洞入口处巡逻，将诚实的定居者拒之门外，并为他们的非法勾当开采资源。",al={"谁在矿洞里","谁拥有金海岸矿洞","矿洞里的敌人"}},{q="为什么暴风城没有派遣卫兵来清理矿洞？",a="由于瓦里安·乌瑞恩国王失踪，且暴风城贵族议会不愿资助在西部荒野驻扎常备军，该地区已被王室抛弃。当地的平民军必须靠自己去争夺矿洞这类地点的控制权。",al={"为什么没有暴风城军队","卫兵在哪里","为什么它被遗弃了"}},{q="金海岸矿洞位于何处？",a="它开凿在西部荒野西南海岸线的悬崖上，位于萨丁农场和亚历克斯顿农场的南面，俯瞰着无尽之海。",al={"矿洞位置","如何找到金海岸矿洞","它在哪里"}}},fx={ddbe2f8b={q="金海岸矿洞是什么地方？",a="金海岸矿洞曾是暴风王国一处重要的露天金矿和矿物矿场。它位于西部荒野西侧的悬崖附近，如今和这片乡野的其他地方一样，已经脱离王室掌控，日渐荒废并落入叛军手中。",al={"什么是金海岸矿洞","金海岸矿洞的传说","西部荒野的金海岸矿洞"}},f837a40e={q="金海岸矿洞后来怎么样了？",a="矿洞曾是为暴风城国库输送财富的高产采掘场，但西部荒野动荡不安、经济崩溃后，王国便将其废弃。失去王室卫兵和资金后，这座利润丰厚的矿场被迪菲亚潜行者夺取，用来支撑他们持续不断的叛乱。",al={"金海岸矿洞的历史","金海岸矿洞发生了什么"}},["0f9583d4"]={q="金海岸矿洞为什么被废弃？",a="石匠暴动、王室权威在西部荒野各地崩溃后，暴风城撤回驻军以保卫首都。由于缺乏士兵和支援来保护矿工免遭强盗和拦路劫匪袭击，合法采矿作业就此停摆，使矿场轻易落入他人之手。",al={"金海岸矿洞为什么被废弃","金海岸矿洞为什么荒废"}},["29652250"]={q="金海岸矿洞危险吗？",a="极其危险。敌对的迪菲亚潜行者和拦路劫匪在矿洞里到处出没，凶狠地保护着他们的矿产和据点，任何路过的旅人或人民军成员都会遭到攻击。",al={"金海岸矿洞的危险","金海岸矿洞安全吗","谁在金海岸矿洞发动袭击"}}},fp="17,251,20.444.0,40.227.0,45.216.0,53.258.0,39.159.0"}
P.entries["subzone:gold-road"] = {n="黄金之路",s="黄金之路是贯穿贫瘠之地干旱荒野的主要南北交通干线。它从灰谷边界的莫尔杉壁垒延伸开来，经过十字路口向南延展，是年轻的部落重要的运输线。",h="黄金之路是贯穿贫瘠之地干旱荒野的主要南北交通干线。它从灰谷边界的莫尔杉壁垒延伸开来，经过十字路口向南延展，是年轻的部落重要的运输线。",kw={"商队","十字路口","黄金之路","公路","莫尔杉","贫瘠之地"},ang={["class:Hunter"]="道路沿线的稀树草原上充满了平原野兽，这使得这条漫长的道路成为追踪和驯服狮子和迅猛龙等早期狩猎伙伴的理想路径。",["faction:Horde"]="黄金之路是部落在卡利姆多后勤补给的中枢，将杜隆塔尔的兽人首都与莫高雷的牛头人领地以及灰谷附近北方的多个前哨营地紧密相连。"},sec={{t="贫瘠之地的动脉",b="黄金之路是一条漫长、被烈日烘烤的土路，穿过贫瘠之地的中心地带。在北方，它始于设防的莫尔杉壁垒和莫尔杉营地附近，这些据点用于抵御来自灰谷的暗夜精灵的入侵。向南行进，它与通往杜隆塔尔的东侧道路相连，随后与繁华的贸易定居点十字路口交汇。继续向南经过当地绿洲的湿润水域和靠近哀嚎洞穴的山麓，这条公路的北段抵达了一条干涸的河床，旅行者由此穿过，进入更为危险的南贫瘠之地。"},{t="一条至关重要且危机四伏的道路",b="尽管黄金之路是部落在卡利姆多中部地区贸易和军事调动的生命线，但它非常危险。四处劫掠的野猪人部落、半人马战团，以及潜行的平原陆行鸟和狮子时刻威胁着补给商队和单独的信使。部落投入了大量资源在沿途部署斥候和战士，但旅行者仍被建议在离开主要前哨站的安全区域时，务必保持武装并提高警惕。"}},faq={{q="黄金之路起止于何处？",a="黄金之路始于贫瘠之地最北端，即灰谷边界的莫尔杉壁垒。其北段向南穿过十字路口，延伸至分隔南、北贫瘠之地的一条干涸河床，在此处南黄金之路继续前行，经过陶拉祖营地向升降梯方向延伸。",al={"黄金之路路线","黄金之路通向哪里","黄金之路长度"}},{q="为什么黄金之路对部落如此重要？",a="这条道路连接了新建立的部落在卡利姆多中部所有的主要领地。它将来自杜隆塔尔和棘齿城港口的补给线，与莫高雷的牛头人故土以及北方对抗灰谷暗夜精灵的军事前线连接了起来。",al={"为什么黄金之路很重要","黄金之路的重要性"}},{q="道路附近有哪些威胁？",a="旅行者经常会遇到钢鬃和刺鬃野猪人的劫掠小队、游荡的科卡尔半人马，以及诸如草原潜行者和雷霆蜥蜴等极具攻击性的野生野兽。在十字路口的防区之外，这条道路远非安全。",al={"黄金之路安全吗","黄金之路上的敌人","黄金之路的危险"}},{q="黄金之路如何连接杜隆塔尔？",a="在十字路口以北，一条向东的分支从黄金之路分出，穿过怒水河上的木桥，直接通往杜隆塔尔。",al={"通往杜隆塔尔的道路","前往杜隆塔尔的岔路"}}},fx={["5bf25b24"]={q="黄金之路危险吗？",a="黄金之路是穿过贫瘠之地的主要通道，但哪怕稍稍偏离道路也会招致危险。北段贴近凶悍的野猪人巢穴、好斗的平原野兽和四处游荡的半人马掠袭者。再往南，道路穿过争夺激烈的地区，那里遍布敌对的剃刀沼泽部族、异种虫巢穴，以及潜伏在绿洲附近的凶猛野兽。紧靠道路行进并结伴而行，才最有希望活下来。",al={"黄金之路危险吗","黄金之路的危险","黄金之路安全吗"}}},fp="9,271,25.633.0,26.464.0,39.318.0,47.263.0,34.250.0,42.153.0"}
P.entries["subzone:golden-plains"] = {n="金色平原",s="金色平原是一片广阔、阳光普照的盆地，位于莫高雷中心地带雷霆崖的东南方。这片一望无际的草原深受牛头人珍视，是绝佳的狩猎场，也是游荡的科多兽群重要的栖息地。",h="金色平原是一片广阔、阳光普照的盆地，位于莫高雷中心地带雷霆崖的东南方。这片一望无际的草原深受牛头人珍视，是绝佳的狩猎场，也是游荡的科多兽群重要的栖息地。",kw={"阿兰卡","金色平原","狩猎场","科多兽","莫高雷","雷霆崖"},ang={["class:Hunter"]="广阔的开放空间和游荡的科多兽群使这些平原成为追踪者们寻找阿兰卡等传奇野兽的最佳试验场。",["race:Tauren"]="对于牛头人而言，金色平原是他们家园富饶的永恒象征，提供了雷霆崖阴影下神圣的狩猎场。"},sec={{t="狩猎之心",b="金色平原在雷霆崖高耸的平顶山下延展，代表着莫高雷未被驯服的核心地带。金色与绿色交织的草海为当地野生动物提供了丰富的庇护所，使其成为游牧的牛头人最珍视的传统狩猎场之一。宽阔的科多兽群在起伏的盆地中漫步，猎人们则在此分享关于传奇猎物的传说，其中最著名的莫过于那头静静穿行在长草丛中的巨大科多兽，阿兰卡。"}},faq={{q="金色平原是什么地方？",a="金色平原是一片开阔的草原盆地，位于莫高雷雷霆崖的东南方。对于牛头人来说，这里是深受欢迎的传统狩猎场，以宽广的视野和繁多的野生动物而闻名。",al={"金色平原 莫高雷","金色平原在哪里"}},{q="金色平原有哪些动物出没？",a="该盆地以其丰富的野生科多兽群以及莫高雷的其他本土生物而闻名。据说在这片草原上游荡的最著名的野兽是那头难以捉摸且备受尊崇的科多兽，阿兰卡。",al={"金色平原野兽","金色平原的科多兽"}},{q="为什么这个区域对牛头人很重要？",a="这片平原是猎物和兽皮的重要来源，为莫高雷各地新建立的定居点提供了给养，同时也弘扬了牛头人追踪和敬畏猎物的传统。",al={"牛头人 金色平原","为什么牛头人在这里狩猎"}}},fx={["977b4a77"]={q="在金色平原游荡危险吗？",a="对粗心的旅人来说，平原确实危机四伏。这里虽然没有成群的敌军，但整个盆地都是荒野，成群的庞大科多兽在此称霸。受到惊扰时，这些巨兽很容易发起致命冲锋；而Arra'chea这类传说中的凶猛生物，也会在起伏的草原上自由游荡。",al={"金色平原危险吗","金色平原的危险","金色平原安全吗"}}},fp="13,248,17.476.0,27.198.0,36.204.0,41.199.0"}
P.entries["subzone:goldshire"] = {n="闪金镇",s="闪金镇是坐落在艾尔文森林中心地带的一个重要人类交通枢纽，连接着暴风城与西部荒野、Redridge以及南部边境。该镇在第一次战争中被毁后重建，作为一个繁忙的休息站，以著名的Lion's Pride Inn为中心，并由一支压力巨大的暴风城卫兵部队负责守卫。",h="闪金镇是坐落在艾尔文森林中心地带的一个重要人类交通枢纽，连接着暴风城与西部荒野、Redridge以及南部边境。该镇在第一次战争中被毁后重建，作为一个繁忙的休息站，以著名的Lion's Pride...",kw={"水晶湖","艾尔文","闪金镇","lion's pride inn","治安官杜汉","鱼人","riverpaw","石碑湖"},ang={["faction:Alliance"]="闪金镇是一个至关重要的交通枢纽，连接着联盟首都与周围的西部荒野、Redridge和暮色森林等边境地区。",["race:Human"]="对于刚从北郡修道院出来的人类来说，闪金镇代表着对修道院围墙之外王国的初次真实体验，让人清醒地认识到暴风城边境所面临的紧张局势。"},sec={{t="承受压力的十字路口",b="闪金镇位于国王大道的交汇处，长期以来一直是艾尔文乡村的民政和商业中心。然而，在这田园牧歌般的景象之下，却掩盖着25年后日益严重的危机。由于暴风城的军事资源捉襟见肘，且瓦里安·乌瑞恩国王神秘失踪，治安官杜汉必须依靠路过的冒险者而非正规军来遏制周边的威胁。富有侵略性的Riverpaw豺狼人正从西面边境向内渗透，而邪恶的鱼人占据了石碑湖和水晶湖的湖岸，不断夺去皇家卫兵的生命，并危险地逼近镇中心。"},{t="大战的创伤",b="闪金镇宁静的氛围掩盖了其残酷的军事历史。在第一次战争中，闪金镇和月溪镇是最后被兽人部落攻陷的据点，当时大酋长黑手切断了莱恩·乌瑞恩一世国王与其领地的联系，随后洗劫了Stormwind Keep。该镇被夷为平地，直到第二次战争后才得以重建。"}},faq={{q="谁负责保卫闪金镇？",a="暴风城卫兵的治安官杜汉负责指挥当地的防御。他在镇中心办公，协调着卫戍部队，但由于缺乏增援，他被迫雇佣自由冒险者来处理边境威胁和怪物悬赏。",al={"谁领导闪金镇","闪金镇治安官","谁保卫闪金镇"}},{q="目前有哪些威胁正在困扰该镇？",a="闪金镇面临多方面的压力：Riverpaw豺狼人向东突袭西泉要塞，成群的敌对鱼人盘踞在石碑湖和水晶湖的水域。当地斥候警告称，如果不进行干预，小规模冲突可能会蔓延到村里的街道上。",al={"闪金镇的问题","为什么闪金镇处于危险中","闪金镇附近的敌人"}},{q="闪金镇在第一次战争期间发生了什么？",a="闪金镇是在暴风城被洗劫前最后陷落的两个人类城镇之一。大酋长黑手将其与月溪镇一同摧毁，以切断莱恩国王的补给线，使该定居点沦为废墟，直到第二次战争后才得以重建。",al={"第一次战争中的闪金镇","闪金镇是否陷落于兽人之手","闪金镇的毁灭"}},{q="为什么Lion's Pride Inn如此出名？",a="Lion's Pride Inn被公认为是艾泽拉斯最受尊敬且最常光顾的酒馆之一。它坐落在几条区域性高速公路的交汇处，是往来王国的旅行者们主要的聚会场所、休息点和训练场。",al={"lion's pride inn","闪金镇旅店","闪金镇的酒馆"}}},fx={["510017eb"]={q="闪金镇是什么地方？",a="闪金镇是艾尔文森林中部一座繁华的人类城镇，坐落在暴风城、北郡山谷、西部荒野和赤脊山之间的十字路口。这里是贸易和旅人的重要驿站，也是离开修道院的新手英雄通常造访的第一个大型聚居点。",al={"什么是闪金镇","关于闪金镇","闪金镇城镇"}},c15b14b9={q="谁住在闪金镇？",a="闪金镇里住着为当地旅人和农夫服务的人类商人、手艺人和工艺训练师。治安官杜汉和他的暴风城卫兵负责治安与管理，他们驻守这处前哨，维护十字路口一带的秩序，并指引前来此地的冒险者前往最需要防守的地方。",al={"谁住在这里","谁住在闪金镇","闪金镇居民"}},d3dbe578={q="闪金镇危险吗？",a="在镇界以内，暴风城卫兵能让你相对安全，但危险已经逼近镇子外围。凶悍的河爪豺狼人徘徊在西部边境，而致命的鱼人已经占据了附近的湖泊和河流，若不加以遏制，它们就会直接威胁村庄。",al={"闪金镇安全吗","闪金镇的危险","这里危险吗"}}},fp="9,343,25.618.0,23.349.0,40.247.0,45.284.0,48.250.0,39.271.0"}
P.entries["subzone:gordok-commons"] = {n="Gordok Commons",s="Gordok Commons构成了古老厄运之槌的高等精灵废墟中设防的北部区域。在戈多克大王的统治下，这片庞大的石制建筑群成为了戈多尼食人魔精英战士阶层的权力中心。",h="Gordok Commons构成了古老厄运之槌的高等精灵废墟中设防的北部区域。在戈多克大王的统治下，这片庞大的石制建筑群成为了戈多尼食人魔精英战士阶层的权力中心。",kw={"厄运之槌北部","埃雷萨拉斯","戈多克","gordok commons","戈多克大王","诺特·希姆布雷","米兹","贡品任务"},ang={["profession:Engineering"]="地精囚犯诺特·希姆布雷依赖Gordok Commons内足智多谋的工程师和工匠来搜集补给、修理损坏的陷阱，并设计巧妙的手段来分散食人魔卫兵的注意力。"},sec={{t="食人魔大王的宝座",b="Gordok Commons占据了曾经的埃雷萨拉斯贵族区，如今已被彻底亵渎并改造成符合食人魔品味的地方。宏伟的暗夜精灵立柱和拱形通道现在成了戈多克的军械库、粗糙的防御工事和训练场——他们是戈多尼部族中最凶猛、纪律最严明的战士。在该区域的最深处是戈多克之座，戈多克大王凭借纯粹的武力和恐吓在此统治着他手下的蛮卒。"},{t="继位法则",b="戈多克的文化完全建立在残酷的先例之上：强者为王。根据部族传统，谁杀死了在位的君主，谁就能获得“戈多克大王”的称号，并立即赢得幸存队长和卫兵的服从。精明的闯入者会通过潜行或计谋绕过大王的副手，而不是直接杀死他们。如果挑战者只处决了大王，幸存的卫兵就会承认胜利者的权威，并献上丰厚的贡品，而不是为了给前任统治者报仇而战。"}},faq={{q="Gordok Commons位于何处？",a="Gordok Commons位于菲拉斯的厄运之槌北部区域。要到达那里，请穿过破碎的公共区进入庞大的废墟，然后穿过巨大的石制走廊前往北部的入口。",al={"gordok commons位置","厄运之槌北部在哪里","如何找到gordok commons"}},{q="戈多克食人魔是谁？",a="戈多克是戈多尼食人魔部族的精英战士阶层。与那些在菲拉斯荒野中徘徊的散兵游勇不同，Gordok Commons内的戈多克组织严密、装备精良，并在他们的大王麾下遵循着严格的军事指挥链。",al={"戈多克是谁","戈多克部族","戈多尼精英"}},{q="Gordok Commons的食人魔领导权是如何运作的？",a="戈多克的统治权由战斗决定。谁杀死了在位的戈多克大王，谁就立刻加冕。一旦大王倒下，其余的食人魔就会投降，并尊奉征服者为合法统治者。",al={"如何成为戈多克大王","戈多克继承权","戈多克大王背景故事"}},{q="为什么冒险者会留下食人魔卫兵的性命？",a="如果闯入者到达戈多克大王面前并击败了他，且没有杀死他的副手，那些幸存的指挥官就会向新大王臣服。作为克制并直接夺取王位的回报，新统治者会获得守军提供的珍贵贡品。",al={"为什么进行贡品任务","饶恕卫兵","戈多克贡品背景故事"}}},fp="14,242,21.464.0,17.535.0,36.205.0,25.258.0,45.204.0,47.271.0"}
P.entries["subzone:gordunni-outpost"] = {n="戈杜尼前哨站",s="戈杜尼前哨站坐落在拉瑞斯小亭北面的崎岖悬崖中，是菲拉斯野蛮的戈杜尼食人魔的设防营地。该氏族那腐化的影响力扼杀了这里曾经生机勃勃的荒野，使得周围的土地变得干枯、萎靡，呈现出一片褐色。",h="戈杜尼前哨站坐落在拉瑞斯小亭北面的崎岖悬崖中，是菲拉斯野蛮的戈杜尼食人魔的设防营地。该氏族那腐化的影响力扼杀了这里曾经生机勃勃的荒野，使得周围的土地变得干枯、萎靡，呈现出一片褐色。",kw={"大拳","引导者","菲拉斯","戈杜尼","丘陵卫士","拉瑞斯小亭","食人魔","前哨站","驯兽师"},ang={["class:Druid"]="戈杜尼的存在是对自然的一种严重冒犯，将肥沃的丛林林冠变成了一片非自然枯萎、荒凉的废土。",["class:Hunter"]="前哨站被食人魔驯兽师占据，他们捕捉并虐待当地的山地野兽，将像伟大的萨斯夸奇“大拳”这样的生物关在笼子里。"},sec={{t="枯萎的据点",b="戈杜尼前哨站开凿在拉瑞斯小亭上方的北部群山之中，像一道刺眼的伤疤，与菲拉斯葱郁的林冠形成了鲜明对比。无论戈杜尼食人魔在哪里定居，他们鲁莽的魔法引导和破坏性习性都会耗尽荒野的生机，导致当地植物死亡，山坡贫瘠荒芜。该前哨站由土路、一个浅层的入口洞穴，以及深挖进后方悬崖的更大食人魔土丘组成。营地由全副武装的丘陵卫士、狡诈的引导者和食人魔驯兽师巡逻，还关押着危险的战利品——包括一只名为“大拳”的被捕获的萨斯夸奇，它被关在深处洞穴附近的简陋笼子里。"}},faq={{q="为什么这个前哨站周围的景观如此枯萎？",a="戈杜尼氏族对周围环境造成了严酷的腐化影响。他们鲁莽的巫术和破坏性的占领行为耗尽了土壤的自然活力，导致原本翠绿的丛林植被萎缩成干枯褐色的灌木丛。",al={"为什么这里是褐色的","菲拉斯枯草","食人魔腐化"}},{q="戈杜尼前哨站里住着哪些种类的食人魔？",a="前哨站由戈杜尼丘陵卫士、使用粗劣进攻魔法的戈杜尼引导者，以及看管营地和圈养野兽的戈杜尼驯兽师进行防卫。",al={"这里有什么怪物","戈杜尼种类","谁住在这里"}},{q="“大拳”是谁？",a="“大拳”是一只巨大的萨斯夸奇，被戈杜尼食人魔关押在他们后方洞穴的入口附近。食人魔驯兽师将其束缚起来，作为战利品或实验对象。",al={"被关在笼子里的萨斯夸奇","大拳是谁","食人魔俘虏"}},{q="戈杜尼前哨站位于哪里？",a="前哨站坐落在菲拉斯东部，拉瑞斯小亭正北方的山脊高处。",al={"戈杜尼前哨站在哪里","前哨站位置","如何前往戈杜尼前哨站"}}},fp="16,279,19.654.0,50.247.0,48.165.0,15.170.0,38.103.0"}
P.entries["subzone:grand-vestibule"] = {n="Grand Vestibule",s="Grand Vestibule是位于提瑞斯法林地血色修道院的宏伟入口大厅。这里排列着深红色的柱子和倒下的十字军的石制雕像，是冒险者准备攻入修道院内部大厅时的必经之地。",h="Grand Vestibule是位于提瑞斯法林地血色修道院的宏伟入口大厅。这里排列着深红色的柱子和倒下的十字军的石制雕像，是冒险者准备攻入修道院内部大厅时的必经之地。",kw={"入口大厅","grand vestibule","血色占卜师","血色修士","血色修道院","血色哨兵","提瑞斯法林地"},ang={["faction:Alliance"]="前厅展示了洛丹伦昔日神圣避难所的悲剧性堕落，展现了对圣光的虔诚是如何演变为盲目而暴力的狂热的。",["race:Undead"]="这个宏伟的入口位于幽暗城的东北方，代表了那些活跃在提瑞斯法并威胁被遗忘者主权的有生狂热分子的前线。"},sec={{t="狂热的门槛",b="穿过修道院厚重的外门，便是Grand Vestibule，这是一座宽敞的大理石大厅，致力于彰显血色十字军的武力与荣耀。身披重甲的勇士雕像守护在拱形石柱旁，狂热的哨兵、修士和占卜师在石板路上巡逻，击杀任何胆敢在未穿戴该组织深红色战袍的情况下闯入的人。对于入侵者而言，这里是他们初次体验十字军坚定纪律与狂热信仰的地方。"},{t="争夺之地",b="由于该前厅直接位于修道院受防卫的内侧翼外部，它是任何闯入者必须穿过的第一个房间。无论是联盟派往北方的勇士，还是从附近的幽暗城出发的部落部队，在进入内侧回廊之前，都必须在高耸的拱门下击败十字军的守卫。"}},faq={{q="什么是Grand Vestibule？",a="它是位于提瑞斯法林地东北部的血色修道院的宏伟入口大厅，连接着外部庭院与四个内部侧翼。",al={"这是什么房间","grand vestibule信息","修道院入口大厅"}},{q="这个区域有哪些敌人防守？",a="该大厅由活跃的血色十字军人员防守，主要是为了阻拦入侵者而驻扎的血色哨兵、血色修士和血色占卜师。",al={"谁在这里巡逻","前厅怪物","前厅里的十字军"}},{q="为什么联盟和部落在这里战斗？",a="两个阵营都会派遣勇士进入修道院——联盟为了打击十字军的狂热分子，部落为了确保提瑞斯法林地处于被遗忘者的掌控之下。尽管双方都必须穿过这个共同的入口大厅，但这里并未记录发生过双方阵营之间的战斗。",al={"前厅里的pvp","为什么玩家在这里战斗","争夺中的前厅"}},{q="前厅里的雕像描绘的是谁？",a="这些雕像描绘的是血色十字军中受人尊敬的战士和英雄，他们被塑造成身披重甲的形象，以此作为他们对抗亡灵的不屈圣战的永恒象征。",al={"这些雕像是谁","前厅雕像","十字军纪念碑"}}},fx={["14cb93f7"]={q="谁控制着Grand Vestibule？",a="血色十字军完全控制着这座宏伟的入口大厅。血色预言师、血色信徒和血色哨兵守在高耸的廊柱与雕像之间，严密把守通往内部圣所的入口，不让他们眼中受污染或不配进入的人靠近。",al={"谁住在grand vestibule","谁管理grand vestibule","grand vestibule的控制权"}},c059d7f1={q="Grand Vestibule危险吗？",a="极其危险。血色十字军的守卫遍布大厅，入侵者还没抵达修道院内翼，就会被他们砍倒。",al={"grand vestibule安全吗","grand vestibule有多危险","grand vestibule的危险"}},["38ab369b"]={q="这座大厅为什么叫Grand Vestibule？",a="Vestibule指通往更大建筑的入口大厅或前厅。作为血色修道院最外侧的大厅，这里规模宏大，廊柱高耸，还装饰着十字军英雄的华丽雕像，其规模与用途都配得上“宏伟”之名。",al={"为什么叫grand vestibule","grand vestibule名称由来","grand vestibule的含义"}}},fp="15,255,25.455.0,26.340.0,28.149.0,29.154.0,41.274.0,44.177.0"}
P.entries["subzone:great-forge"] = {n="Great Forge",s="Great Forge是铁炉堡矮人首都的火热心脏，也是这座城市得名的原因。它位于城市最中心，巨大的熔炉和闻名遐迩的Great Anvil永不停歇，锻造出传奇装备，这里也是城市民生活的繁忙中心。",h="Great Forge是铁炉堡矮人首都的火热心脏，也是这座城市得名的原因。它位于城市最中心，巨大的熔炉和闻名遐迩的Great Anvil永不停歇，锻造出传奇装备，这里也是城市民生活的繁忙中心。",kw={"铸造厂","great anvil","great forge","gryth thurden","铁炉堡","magni bronzebeard","myolor sunderfury"},ang={["profession:Blacksmithing"]="Great Anvil被认为是联盟首屈一指的锻造点，是高级训练师的所在地，也是位于城市中心的传奇Great Anvil的所在地。",["race:Dwarf"]="这座熔炉代表了山下矮人文明的基础，让数百年的锻造传统得以延续，其火焰从未熄灭。"},sec={{t="山脉之心",b="Great Forge是早期矮人在铁炉堡山脉下建造的最早建筑，这座宏伟的首都便是围绕着它呈同心圆向外扩展而建的。熔岩和矿渣不断从巨大的铸造厂涌入发光的通道，将洞穴映照得一片琥珀色。在它的中心矗立着巨大的Great Anvil，由锻造大师Myolor Sunderfury监管。著名的金属工艺大师们聚集在它的边缘，日夜不停地锻造着盔甲、工具和武器。"},{t="联盟的枢纽",b="除了锻造作业外，Great Forge还是整座山城繁忙的十字路口。这里环绕着公会办公室、补给商店，以及由Gryth Thurden维护的城市主要Gryphon Roost，来自联盟各地的旅行者都在锤击声中来往穿梭。"}},faq={{q="为什么这座城市是以这个熔炉命名的？",a="当矮人们最初开凿这座山脉时，Great Forge是他们建造的定居点的第一部分。随着地下大厅从这个中心大厅向外扩展，整座山城被命名为铁炉堡，以纪念位于其中心的巨大熔炉。",al={"为什么铁炉堡叫铁炉堡","城市命名","铁炉堡起源"}},{q="这里锻造过哪些著名的物品？",a="在矮人的历史上，Great Anvil锻造出了许多历史性的杰作。铁炉堡最优秀的铁匠们在它的表面上锤炼出了几代人的武器和盔甲，而熔炉的火焰从未熄灭。",al={"great anvil制造了什么","great forge著名武器"}},{q="谁负责监管熔炉？",a="巨大炉灶的日常运作和维护由Myolor Sunderfury负责，他拥有Great Forge守护者的头衔。",al={"great forge守护者","谁管理熔炉"}},{q="为什么这里总是这么拥挤？",a="熔炉位于铁炉堡的地理中心，直接连接外环和附近的区域。这里设有重要的制造训练师、商业店铺和铁炉堡的中央Gryphon Roost，确保市民、信使和外来的冒险者不断往来。",al={"为什么熔炉那里人很多","为什么熔炉很忙"}}},fx={eab323ad={q="Great Forge是什么地方？",a="Great Forge是铁炉堡的炽热核心，也是这座城市名称的由来。它位于这座地下山城的正中央，以传说中的大铁砧为中心，是一处烟尘弥漫、热闹繁忙的枢纽。四周环绕着轰鸣的熔炉、繁忙的商铺、贸易训练师和城市的狮鹫栖木。这里的锻炉永不停歇，既是经济重地，也是矮人生活的繁华交汇点。",al={"什么是great forge","铁炉堡great forge","关于great forge"}},dc416ec6={q="Great Forge危险吗？",a="在铁炉堡戒备森严的地下城界内，忠诚坚毅的矮人哨兵会保护你免受野兽和敌军侵扰。不过，锻炉本身是一处仍在运作的工业奇观，遍布敞开的熔渣沟、灼人的热浪和重型机械。若不慎翻过栏杆或跌入炽热的熔炉，毫无准备的人很快就会丧命。",al={"great forge危险吗","great forge的危险","会掉进great forge里吗"}}},fp="11,260,21.488.0,19.290.0,39.281.0,42.230.0,23.145.0,33.289.0"}
P.entries["subzone:great-lift"] = {n="升降梯",s="升降梯是一套宏伟的牛头人工程升降系统，坐落在贫瘠之地的南端边缘。它是将旅行者和物资运送至数百英尺下千针石林深邃峡谷盆地的主要通道。尽管其具有极高的战略价值，但从南部荒原入侵的野猪人使得靠近升降梯边缘变得日益危险。",h="升降梯是一套宏伟的牛头人工程升降系统，坐落在贫瘠之地的南端边缘。它是将旅行者和物资运送至数百英尺下千针石林深邃峡谷盆地的主要通道。尽管其具有极高的战略价值，但从南部荒原入侵的野猪人使得靠近升降梯边缘变得日益危险。",kw={"卫兵穆赫·月角","升降梯","瑞什·远行者","野猪人","贫瘠之地","千针石林"},ang={["faction:Horde"]="升降梯是部落的一条重要动脉，连接着卡利姆多中部与千针石林和闪光平原的偏远地区。",["race:Tauren"]="升降梯采用坚固的原木和配重建造，展现了你们族人无需破坏土地就能克服崎岖地形障碍的巧妙能力。"},sec={{t="木绳雕琢出的通道",b="升降梯横跨南贫瘠之地与千针石林峡谷底部之间陡峭的悬崖边缘，是牛头人实用主义建筑的杰作。它由厚重的原木、编织绳索和配重滑轮建成，其配对的平台可以载着大篷车、信使和战士安全地跨越那道如果靠步行几乎无法逾越的垂直悬崖。在上下两个平台上，像卫兵穆赫·月角和瑞什·远行者这样的牛头人坚守在此，告知旅行者前方的路况，并确保货物顺利通过。"},{t="边缘的危险",b="由于上方领土充满敌意，操作升降梯变得越来越危险。南贫瘠之地的野猪人部落大举向南扩张，阻塞了通往升降梯的道路，并威胁要彻底切断千针石林与北方道路的联系。那些进行长途跋涉来到南方的人，在踏上木制平台之前，必须时刻抵御剃刀沼泽的袭击者。"}},faq={{q="谁建造了升降梯？",a="升降梯是由牛头人设计并建造的，旨在连接贫瘠之地干旱的高原与千针石林深处的峡谷底部，跨越巨大的垂直落差。",al={"谁建造了升降梯","升降梯建造者","牛头人升降梯起源"}},{q="为什么前往升降梯的旅途很危险？",a="南贫瘠之地不断入侵的野猪人已经大举向边缘地区扩张。他们的突袭小队在通道附近徘徊，经常骚扰甚至直接伏击前往升降梯平台的补给车队和信使。",al={"为什么这里有野猪人","南贫瘠之地的危险","通往升降梯的路被堵住了"}},{q="谁在看守升降梯？",a="卫兵穆赫·月角和瑞什·远行者驻扎在升降梯处，负责观察路线、协助部落旅行者，并留意周围荒野的动向。",al={"谁在守卫升降梯","升降梯守卫","在升降梯处的牛头人"}},{q="升降梯通往哪里？",a="乘坐平台向下可将旅行者带到千针石林的峡谷底部，而向上则可直达南贫瘠之地。",al={"升降梯通往哪里","升降梯下面是什么","升降梯目的地"}}},fx={["15c17117"]={q="升降梯是什么？",a="升降梯是一座由牛头人设计的巨型电梯，坐落在南贫瘠之地与千针石林峡谷底部之间的峭壁边缘。它是旅人、商人和信使安全下行高耸悬崖的主要通道，让他们无需冒险通过险峻的陡坡。",al={"升降梯是什么","升降梯信息","关于升降梯"}},["9d5e1aa9"]={q="升降梯危险吗？",a="机械平台本身状况良好，但周边道路危机四伏。南贫瘠之地的野猪人部族已将领地扩张至悬崖边，伏击商队，并威胁要切断试图抵达电梯边缘的旅人的去路。",al={"升降梯危险吗","升降梯安全吗","升降梯附近的威胁"}}},fp="10,378,35.548.0,18.430.0,25.180.0,39.252.0,32.153.0,31.143.0"}
P.entries["subzone:greatwood-vale"] = {n="巨木谷",s="巨木谷是一座坐落在石爪山脉东部山麓中的森林峡谷，可以通过危险的蛛网小径抵达。最近，敌对的恐怖图腾氏族占领了这片山谷，并将其作为发动对周边定居点血腥袭击的集结地。",h="巨木谷是一座坐落在石爪山脉东部山麓中的森林峡谷，可以通过危险的蛛网小径抵达。最近，敌对的恐怖图腾氏族占领了这片山谷，并将其作为发动对周边定居点血腥袭击的集结地。",kw={"阿帕拉耶营地","巨木谷","恐怖图腾","格兰迪·暗云","玛卡巴·扁蹄","玛拉卡金","石爪山脉","蛛网小径"},ang={["faction:Horde"]="保卫巨木谷对于保护脆弱的玛拉卡金南部前哨站免受流氓恐怖图腾的突然侧翼袭击至关重要。",["race:Tauren"]="恐怖图腾对阿帕拉耶营地牛头人同胞的背信弃义的屠杀，使肃清巨木谷成为了雷霆崖忠诚子民深沉而悲痛的职责。"},sec={{t="纷争之地",b="巨木谷隐匿于蛛网小径旁，现已成为一个充满暴力的边境地带。在残忍的格兰迪·暗云领导下，恐怖图腾氏族大举进驻山谷，切断了安全的通道，并给周边的山麓地区带来了恐怖。"},{t="阿帕拉耶营地的灾难",b="恐怖图腾氏族不仅仅是占领了巨木谷，他们还利用这里策划了对附近阿帕拉耶营地的大屠杀。暗云的袭击者从森林中倾巢而出，屠杀了营地里几乎所有的牛头人居民。玛卡巴·扁蹄是少数逃脱这场浩劫的幸存者之一，他现在引导着复仇心切的部落勇士直捣巨木谷中心，以除掉这些叛逆的恐怖图腾，并终结格兰迪·暗云的统治。"}},faq={{q="现在是谁控制着巨木谷？",a="该山谷目前由敌对的恐怖图腾氏族占领，当地的首领是格兰迪·暗云。他们以战团和施法者把守着森林，威胁着任何试图穿越该地区的人。",al={"谁住在巨木谷","巨木谷的敌人","巨木谷的恐怖图腾"}},{q="阿帕拉耶营地发生了什么？",a="恐怖图腾氏族从巨木谷对阿帕拉耶营地发动了突然袭击，屠杀了大部分爱好和平的牛头人居民。玛卡巴·扁蹄在屠杀中幸存下来，现在正寻求对袭击者及其首领进行复仇。",al={"阿帕拉耶营地背景故事","阿帕拉耶发生了什么","恐怖图腾为什么要进攻"}},{q="为什么部落要在这里与恐怖图腾作战？",a="尽管玛加萨身在雷霆崖，但恐怖图腾氏族并未正式加入部落。格兰迪·暗云的追随者袭击了阿帕拉耶营地的牛头人同胞，促使幸存者向部落冒险者寻求援助。",al={"为什么要杀死恐怖图腾","玛卡巴·扁蹄任务","为我的村庄复仇"}}},fx={["87537350"]={q="巨木谷是什么？",a="巨木谷是石爪山山麓的一处林木茂密的山谷，可经由蛛网小径抵达。玛拉卡金位于其南面。敌对的蛮槌牛头人已将山谷作为袭击附近定居点的据点。",al={"巨木谷","这里是什么地方","石爪山山谷"}},["3922b097"]={q="巨木谷危险吗？",a="是的，巨木谷极其危险。除了蛛网小径沿途盘踞的有毒林网蜘蛛外，山谷也已落入叛离的蛮槌牛头人手中。这些掠袭者由军阀格伦迪格·暗云率领，会主动猎杀任何闯入林地的外来者。",al={"巨木谷的危险","这里安全吗","巨木谷中的威胁"}}},fp="14,270,18.263.0,27.447.0,38.189.0,30.230.0,45.227.0"}
P.entries["subzone:green-belt"] = {n="绿带草地",s="绿带草地是一片位于湿地东部的荒野沼泽，蔓延在格瑞姆巴托的山脊之下。这里遍布着游荡的泥沼兽、掠食性的鳄鱼和有毒的软泥怪，主要由形单影只的暗夜精灵绿色守卫者雷希耶尔在此守卫。",h="绿带草地是一片位于湿地东部的荒野沼泽，蔓延在格瑞姆巴托的山脊之下。这里遍布着游荡的泥沼兽、掠食性的鳄鱼和有毒的软泥怪，主要由形单影只的暗夜精灵绿色守卫者雷希耶尔在此守卫。",kw={"泥沼兽","龙喉","绿带草地","格瑞姆巴托","软泥怪","雷希耶尔","湿地","幼龙"},ang={["class:Druid"]="沼泽中扭曲的软泥怪和肆虐的泥沼兽破坏了沼泽的自然和谐，使该地区成为自然守护者们关注的焦点。",["race:NightElf"]="在东部王国的沼泽中发现独自驻守的绿色守卫者雷希耶尔是一个意想不到的景象，这提醒了人们塞纳里奥议会和暗夜精灵致力于治愈各处荒野的奉献精神。"},sec={{t="一片狂野且充满争议的沼泽",b="绿带草地横跨湿地东部内陆，是这片潮湿地区中未被驯服的低洼地之一。当地的野生生物——从巨大的鳄鱼到变幻莫测的软泥怪，还有蹒跚而行的泥沼兽——让穿行于这片长满苔藓的水域变得十分危险。在其深处坐落着一个孤独的岗哨，由绿色守卫者雷希耶尔驻守。这位孤独的暗夜精灵致力于研究这片沼泽的生态，并遏制其中敌对生物的扩张。"},{t="第二次战争的残骸",b="在泥泞之中散落着龙喉氏族大篷车的残骸，这是在附近格瑞姆巴托发生灾难性战役后留下的。红龙幼龙仍然在破碎的马车和被压扁的笼子周围徘徊，作为那个兽人氏族过去奴役阿莱克斯塔萨和她的红龙军团的阴森提醒。"}},faq={{q="绿带草地在哪里？",a="绿带草地占据了湿地的东半部，位于主干道和通往格瑞姆巴托的山麓丘陵之间的潮湿低地上。",al={"绿带草地位置","绿带草地在哪里","绿带草地湿地地图"}},{q="绿色守卫者雷希耶尔是谁？",a="雷希耶尔是一位神秘的暗夜精灵，在湿地沼泽中执行守望任务。他远离了自己的祖地卡利姆多，试图维护沼泽中自然的平衡，并招募旅行者来处理那些腐化的野兽和软泥怪。",al={"谁是雷希耶尔","绿色守卫者雷希耶尔","绿带草地中的暗夜精灵"}},{q="为什么这里会有红龙幼龙和破碎的马车？",a="它们是第二次战争结束后龙喉氏族补给车队的遗迹，当时兽人从格瑞姆巴托被击溃，他们对红龙军团的控制也被粉碎了。",al={"龙喉大篷车","为什么湿地里有幼龙","湿地红龙幼龙"}},{q="绿带草地里游荡着什么威胁？",a="穿过这片草地的旅行者经常会遇到危险的湿地鳄鱼、有毒的活体软泥怪，以及完美融入潮湿植被中的高大泥沼兽。",al={"绿带草地怪物","绿带草地的危险","这里生活着什么怪物"}}},fx={b9266860={q="绿带草地是什么？",a="绿带草地是湿地东部一片荒野而杂草丛生的区域。与西部和南部较为干燥的道路及矮人挖掘场不同，这片潮湿的土地大多仍是未经驯服的沼泽地，遍布茂密的沼泽植被和泥潭，只有一位名为绿色守卫者雷希耶尔的神秘守护者独自驻守。",al={"绿带草地是什么","湿地绿带草地","关于绿带草地"}},["453ecde9"]={q="谁住在绿带草地？",a="绿带草地没有任何文明聚居地。除了本地的沼泽掠食者外，这片荒野湿地中唯一值得一提的居民便是绿色守卫者雷希耶尔。他独自在此守望，监视自然平衡，并保护沼泽免遭蔓延的腐化侵袭。",al={"谁住在绿带草地","绿带草地的居民","绿带草地的住户"}},e91fe995={q="绿带草地有多危险？",a="贸然深入绿带草地，会让毫无防备的旅人遭遇严重危险。浑浊的水域中充斥着凶猛的鳄鱼、不断变形的软泥怪和高大的沼泽巨兽。此外，破碎的龙喉兽人货车残骸会吸引野生的红色雏龙，它们会猛烈攻击任何闯入领地的人。",al={"绿带草地危险吗","绿带草地的危险","绿带草地中的威胁"}}},fp="10,257,24.450.0,26.309.0,32.154.0,31.227.0,48.190.0,35.171.0"}
P.entries["subzone:greenpaw-village"] = {n="绿爪村",s="绿爪村是一个位于灰谷中心地带的熊怪定居点，坐落在林中树居和银风避难所之间。它是邪木部族的主要聚居地，由穆尔格特酋长和萨满橡爪领导。由于受到恶魔腐蚀的侵袭并陷入外部势力的交战中，该村庄成为了联盟和部落旅行者的一处活跃冲突点。",h="绿爪村是一个位于灰谷中心地带的熊怪定居点，坐落在林中树居和银风避难所之间。它是邪木部族的主要聚居地，由穆尔格特酋长和萨满橡爪领导。由于受到恶魔腐蚀的侵袭并陷入外部势力的交战中，该村庄成为了联盟和部落旅行者的一处活跃冲突点...",kw={"灰谷","邪木部族","熊怪","绿爪村","穆尔格特","橡爪","林中树居","银风避难所"},ang={["class:Druid"]="德鲁伊们在绿爪村亲眼目睹了这些古老熊人种族的痛苦，那里自然的平衡已经崩溃，沦为猖獗的野性疯狂。",["race:NightElf"]="对于暗夜精灵来说，看着邪木部族在如此靠近林中树居和他们神圣月亮井的地方屈服于腐蚀，是灰谷挥之不去的恶魔创伤的一记悲剧性的提醒。"},sec={{t="受腐蚀的定居点",b="绿爪村位于林中树居以南、银风避难所以东北，曾经是森林中这些熊类居民宁静的家园。第三次大战之后，这里的常驻熊怪——邪木部族——屈服于玷污了灰谷土地和灵魂的阴险腐蚀。在穆尔格特酋长和他们被腐蚀的精神向导、萨满橡爪的统治下，邪木部族变得敌对且不稳定，攻击任何误入其森林领地的旅行者。"},{t="处于交火中心",b="由于其无休止的侵略性以及靠近主要道路，绿爪村招致了各方的敌意。联盟哨兵和暗夜精灵德鲁伊试图清洗这些疯狂的熊怪，以保护他们附近的哨所和神圣的月亮井。与此同时，推进到灰谷的部落部队在穿越这片古老林地时，也与邪木部族发生了血腥的冲突。"}},faq={{q="绿爪村位于何处？",a="绿爪村位于灰谷中心地带，林中树居正南方，银风避难所以东北，南部月亮井的西北方。",al={"绿爪村位置","绿爪村在哪里","寻找绿爪村"}},{q="谁居住在绿爪村？",a="该定居点居住着邪木熊怪部族，由穆尔格特酋长和他们被腐蚀的精神导师萨满橡爪共同管理。",al={"这里是谁","绿爪村怪物","绿爪村熊怪"}},{q="为什么绿爪村的熊怪如此敌对？",a="和卡利姆多北部许多其他的熊怪部族一样，邪木部族成为了燃烧军团入侵灰谷后留下的恶魔腐蚀的受害者，这使他们的心智陷入了疯狂的侵略性之中。",al={"为什么熊怪会发疯","绿爪村熊怪是否受到腐蚀"}},{q="为什么联盟和部落在这里战斗？",a="双方阵营都将富有侵略性的邪木部族视为对其道路和定居点的威胁。暗夜精灵试图在他们的月亮井附近净化或遏制这种疯狂，而部落军队在穿过灰谷时也与这些熊怪发生冲突。",al={"绿爪村任务","谁在攻击绿爪村"}}},fx={["44cbc3fb"]={q="绿爪村是什么？",a="绿爪村是位于灰谷中部的一处熊怪聚居地，坐落在林中树居以南、银风避难所以东北。它曾是古老森林中的宁静居所，如今则是污林部族的家园营地，茂密的林冠下有质朴的木屋、图腾和火坑。",al={"绿爪村是什么","绿爪村传说","介绍绿爪村"}},e6fbac57={q="绿爪村发生了什么？",a="与灰谷各地的许多熊怪部族一样，绿爪村的居民也屈服于第三次战争期间侵染森林的恶魔腐化。污林部族被黑暗能量逼至疯狂，开始暴力攻击外来者，使宁静的村落变成了敌意四伏的巢穴，引来了暗夜精灵和附近部落哨站的干预。",al={"绿爪村的历史","绿爪村发生了什么","绿爪村历史"}},["303ee734"]={q="绿爪村危险吗？",a="毫无准备地闯入绿爪村极其危险。污林熊怪十分好斗，会一见到入侵者便发动攻击，战斗时力大如野兽。部族中有橡爪这样的强大萨满，也有酋长穆尔古特这样的凶悍首领，因此独自在森林腹地穿行的旅人会面临极大危险。",al={"绿爪村有多危险","绿爪村危险吗","绿爪村的危险"}}},fp="16,367,22.495.0,24.405.0,34.157.0,30.152.0,49.210.0,45.239.0"}
P.entries["subzone:greymane-wall"] = {n="格雷迈恩之墙",s="格雷迈恩之墙是一座宏伟的石质壁垒，横跨银松森林的南端边界。在第二次战争后，吉恩·格雷迈恩国王下令建造了这道城墙，将吉尔尼斯王国与外界隔绝在坚不可摧的紧闭大门之后。",h="格雷迈恩之墙是一座宏伟的石质壁垒，横跨银松森林的南端边界。在第二次战争后，吉恩·格雷迈恩国王下令建造了这道城墙，将吉尔尼斯王国与外界隔绝在坚不可摧的紧闭大门之后。",kw={"阿鲁高","吉恩·格雷迈恩","吉尔尼斯","格雷迈恩之墙","焚木村","银松森林"},ang={["faction:Alliance"]="格雷迈恩之墙是吉尔尼斯人遗弃盟友的苦涩见证。当洛丹伦沦陷于天灾军团时，格雷迈恩对昔日的盟友充耳不闻，任由他们在门外腐烂。",["faction:Horde"]="对于如今占据银松森林的被遗忘者来说，这道墙构成了一道无法逾越的南部边界，将一个意图和内部实力完全未知的人类王国封锁在内。"},sec={{t="孤立的丰碑",b="第二次战争结束后，吉恩·格雷迈恩国王对洛丹伦联盟愈发不满，特别是对维持兽人收容所所需缴纳的税款感到愤慨。格雷迈恩认定吉尔尼斯已经为外邦的纠纷投入了足够的金钱和鲜血，于是决定退出联盟，并下令在半岛的顶端筑起一道巨大的屏障。当第三次战争带来亡灵天灾和无数走投无难的难民在墙外求援时，这道大门依然冷酷地紧闭着。"},{t="避世的代价",b="虽然这道城墙将天灾军团的军队阻挡在半岛之外，但墙外的土地却未能幸免。在银松森林，达拉然的大法师阿鲁高召唤了野性的狼人来对抗亡灵，但这些野兽最终失控，如今正游荡在静默的墙外森林中。城墙后究竟发生了什么，外界一无所知。"}},faq={{q="格雷迈恩之墙后方是什么？",a="墙后是吉尔尼斯半岛王国。在第三次战争前，吉恩·格雷迈恩国王统治下的吉尔尼斯将自身与洛丹伦及世界其他地区完全隔绝，断绝了一切商业往来与沟通。",al={"墙后是什么","格雷迈恩之墙通向哪里","墙后的王国是什么"}},{q="你能打开格雷迈恩之墙的大门吗？",a="不能。巨大的闸门和铁箍大门从南侧被牢牢锁死。吉尔尼斯切断了与外界的一切联系，任何人和物都无法进出。",al={"如何通过格雷迈恩之墙","你能打开格雷迈恩之墙吗","打开大门"}},{q="为什么城墙建在这里，而不是更南边的地方？",a="关于它确切选址的原因并无记录。这道城墙横跨银松森林南缘，位于吉尔尼斯半岛的顶端，将焚木村和安伯米尔等村庄留在了城墙北侧。",al={"为什么建在这里","为什么要切断焚木村","克罗雷家族领地被切断"}},{q="在第三次战争期间逃难到此的难民遭遇了什么？",a="当亡灵天灾蹂躏洛丹伦时，大量逃亡的人类难民聚集在墙外乞求进入。格雷迈恩国王为了保护自己的王国拒绝开启大门，这些走投无路的难民最终在墙外遭到了亡灵的屠戮。",al={"天灾难民与城墙","格雷迈恩之墙外的难民"}}},fx={["29630d52"]={q="格雷迈恩之墙是什么？",a="格雷迈恩之墙是一道横贯银松森林南部边境的巨大石墙。第二次战争后，吉恩·格雷迈恩国王下令修建此墙，以高大而坚不可摧的大门将吉尔尼斯王国与洛丹伦及世隔绝。",al={"格雷迈恩之墙是什么","格雷迈恩之墙","银松森林的巨墙"}},["18f5ff7d"]={q="为什么叫格雷迈恩之墙？",a="这道墙以吉尔尼斯统治者吉恩·格雷迈恩国王的名字命名，他下令建造了它。格雷迈恩厌倦了为联盟的兽人收容营承担高额税赋，也厌烦了外国战争，于是修筑这道巨型屏障，将自己的国家彻底隔绝起来。",al={"为什么叫格雷迈恩之墙","谁给格雷迈恩之墙命名","格雷迈恩名称的由来"}},e1e9af4d={q="谁控制着格雷迈恩之墙？",a="这道墙完全属于奉行孤立政策的吉尔尼斯王国，由吉恩·格雷迈恩国王统治。吉尔尼斯人哨兵在高大城墙的安全一侧守望，而外侧区域则彻底荒废，任由荒野以及银松森林中徘徊的阴影占据。",al={"谁控制格雷迈恩之墙","谁守卫这道墙","谁住在格雷迈恩之墙"}},["6b007fab"]={q="格雷迈恩之墙危险吗？",a="城墙本身是一道无法逾越的石墙，但城门外的土地危机四伏。银松森林中遍布野性狼人、复仇的灵魂和凶猛野兽，它们会捕食任何逗留在那扇沉寂而紧闭的大门附近的旅人。",al={"格雷迈恩之墙安全吗","城墙附近危险吗","格雷迈恩之墙的威胁"}}},fp="13,242,23.478.0,22.366.1,35.216.0,44.176.0,53.212.0,65.257.0"}
P.entries["subzone:grim-batol"] = {n="格瑞姆巴托",s="格瑞姆巴托是一座古老而残破的矮人山中堡垒，矗立在湿地的东侧边缘。它由蛮锤部族建造，在三锤之战中遭受黑暗诅咒而被废弃，后来被龙喉兽人占领并作为培育巨龙的巢穴。那紧闭的大门至今仍是高地上一个不祥的污点。",h="格瑞姆巴托是一座古老而残破的矮人山中堡垒，矗立在湿地的东侧边缘。它由蛮锤部族建造，在三锤之战中遭受黑暗诅咒而被废弃，后来被龙喉兽人占领并作为培育巨龙的巢穴。那紧闭的大门至今仍是高地上一个不祥的污点。",kw={"阿莱克丝塔萨","恶魔之魂","龙喉","格瑞姆巴托","莫德古德","耐克鲁斯","湿地","蛮锤"},ang={["faction:Horde"]="这座山脉象征着第二次战争中严酷的巅峰，龙喉氏族曾在这里利用被奴役的巨龙征服天空，最终却走向了毁灭。",["race:Dwarf"]="对于矮人来说，格瑞姆巴托是三锤之战留下的苦涩见证——曾经是铁炉堡引以为傲的姐妹城市，却因黑铁的巫术而永远无法居住。"},sec={{t="饱受两次诅咒的堡垒",b="在三锤之战后，卡德罗斯·蛮锤领主在沼泽以东的险峻山脉中开凿出了格瑞姆巴托。在随后的三锤之战中，黑铁部族的莫德古德女巫围攻了这座堡垒。尽管卡德罗斯击杀了她，但莫德古德在死前给这些岩石留下了邪恶的阴影。残留的腐化使得大厅无法居住，幸存的蛮锤矮人被迫放弃了他们宏伟的王国，向北迁徙到了辛特兰。"},{t="龙后的锁链",b="几个世纪后的第二次战争期间，当奥格瑞姆·毁灭之锤派遣龙喉氏族占据此处时，这座堡垒迎来了一个更黑暗的用途。在术士耐克鲁斯·碎颅者的带领下，兽人们利用名为“恶魔之魂”的远古神器，将红龙女王阿莱克丝塔萨禁锢在山脉深处。阿莱克丝塔萨被迫为部落的战争努力孵化龙蛋，直到一群英雄击碎了神器，她才得以解脱。重获自由后，愤怒的龙王将兽人焚烧殆尽，格瑞姆巴托从此成了一片阴燃、荒凉的废墟，时刻受到幸存红龙的严密监视。"}},faq={{q="玩家可以进入格瑞姆巴托吗？",a="不可以。山路尽头那巨大的石门依然紧闭，旅人无法进入。玩家只能前往湿地东部山区的入口，参观它那雄伟的大门和外围城墙。",al={"我能进入格瑞姆巴托吗","格瑞姆巴托开放吗","格瑞姆巴托大门"}},{q="为什么蛮锤矮人会放弃它？",a="在三锤之战期间，黑铁女巫莫德古德在被杀前将一种邪恶的暗影诅咒注入了这座要塞。留下的腐化使得堡垒不再适宜蛮锤矮人居住，迫使他们将其放弃，并前往辛特兰建立了鹰巢山。",al={"为什么矮人离开格瑞姆巴托","蛮锤诅咒","莫德古德诅咒"}},{q="这里曾经的龙喉兽人发生了什么？",a="当大法师罗宁和他的同伴击碎了恶魔之魂后，被俘的红龙女王阿莱克丝塔萨从锁链中解脱出来。因为残酷的囚禁而怒不可遏的她，与她的族群一道焚烧了耐克鲁斯·碎颅者，并终结了龙喉氏族在堡垒中的存在。",al={"龙喉格瑞姆巴托","这里的兽人发生了什么","耐克鲁斯·碎颅者"}},{q="谁现在控制着格瑞姆巴托？",a="目前，格瑞姆巴托是一处废弃的遗迹。虽然龙喉氏族的残党和野兽在周围的峭壁中徘徊，但红龙军团一直在严密监视这座受诅咒的山脉，以确保其黑暗的历史不再重演。",al={"谁拥有格瑞姆巴托","谁现在住在格瑞姆巴托"}}},fx={["7aeea9cc"]={q="格瑞姆巴托是什么？",a="格瑞姆巴托是一座古老而广阔的山中要塞，凿建于湿地以东的群山之中。高耸的城门和城垛俯瞰着沼泽，但要塞绝大部分区域都深入地下。蛮锤氏族被逐出铁炉堡后建立了这座要塞，它曾是他们引以为傲的都城；后来黑暗魔法腐化了其中的厅堂，使它变成一座阴森可怖的堡垒，历经数百年的悲伤、占领与战争。",al={"格瑞姆巴托是什么","格瑞姆巴托要塞","关于格瑞姆巴托"}},["06dc57c0"]={q="格瑞姆巴托危险吗？",a="格瑞姆巴托极其危险，并且严禁旅人进入。三锤之战遗留的黑暗魔法至今仍污染着内部，而巨型城门周围的天空与道路则由精锐的敌对红龙巡逻，它们警惕着任何擅自闯入者。内部残留的腐化与外部致命的守卫，使任何接近要塞的行为都危机重重。",al={"格瑞姆巴托有多危险","格瑞姆巴托安全吗","格瑞姆巴托的威胁"}}},fp="10,331,23.518.0,26.609.0,29.218.0,42.280.0,51.264.0,34.242.0"}
P.entries["subzone:grimesilt-dig-site"] = {n="煤渣挖掘场",s="煤渣挖掘场是灼热峡谷内的一处考古挖掘点，最初由铁炉堡的矮人动工。该矿坑已被敌对的黑铁矮人占领，目前完全处于敌方控制之下，而最初探险队的幸存成员只能躲藏起来艰难求生。",h="煤渣挖掘场是灼热峡谷内的一处考古挖掘点，最初由铁炉堡的矮人动工。该矿坑已被敌对的黑铁矮人占领，目前完全处于敌方控制之下，而最初探险队的幸存成员只能躲藏起来艰难求生。",kw={"考古学","黑铁","杜里奥斯·裂石","挖掘","煤渣挖掘场","铁炉堡","灼热峡谷"},ang={["faction:Alliance"]="这处挖掘场象征着铁炉堡的一项努力被黑铁矮人无情地破坏，导致受困的联盟成员在险恶的领土中等待撤离。",["race:Dwarf"]="对于铜须矮人来说，煤渣挖掘场是一个苦涩的提醒，时刻警示着山脉另一侧阴魂不散的黑铁威胁，也凸显了矮人文物和考古学家在敌对领土所面临的危险。"},sec={{t="一场被争夺的挖掘场",b="煤渣挖掘场坐落于烟尘弥漫的灼热峡谷荒地，最初是由铁炉堡学者批准的一项探险活动，旨在发掘岩层下的遗物。然而，当本土的黑铁矮人驱逐了挖掘人员并夺取了设备后，这一冒险行动便以惨剧告终。如今，挖掘坑中充斥着黑铁哨兵，导致最初铁炉堡探险队的伤员和幸存者被困在坑内及其周边地区。"}},faq={{q="谁最初建立了煤渣挖掘场？",a="这项挖掘工作由铁炉堡的铜须矮人发起。他们的团队被派往灼热峡谷地下发掘古代文物，但在遭遇伏击后被赶出了那里。",al={"谁挖掘了煤渣挖掘场","谁建立了煤渣挖掘场","煤渣挖掘场建立者"}},{q="谁现在控制着挖掘场？",a="黑铁部族夺取了挖掘场。他们目前占据着矿坑，守卫着剩余的工具和领土，防范铁炉堡夺回该地区的任何企图。",al={"谁拥有煤渣挖掘场","煤渣挖掘场的敌人","谁在煤渣挖掘场"}},{q="最初的探险队有幸存者吗？",a="有的。有少数工人设法活了下来，包括躺在矿坑底部附近受伤的挖掘者杜里奥斯·裂石，以及另一名躲在附近厕所里的不幸船员。",al={"煤渣挖掘场的幸存者","杜里奥斯·裂石","谁被困在煤渣挖掘场"}}},fp="18,279,22.463.0,50.183.0,30.171.0,47.184.0"}
P.entries["subzone:grimtotem-compound"] = {n="恐怖图腾营地",s="恐怖图腾营地是一处位于菲拉斯中部荒野的坚固部落定居点，位于厄运之槌精灵遗迹的正东方。这里由极具侵略性且排外的恐怖图腾氏族占据，该营地是他们在该地区进行神秘且破坏性行动的基地。",h="恐怖图腾营地是一处位于菲拉斯中部荒野的坚固部落定居点，位于厄运之槌精灵遗迹的正东方。这里由极具侵略性且排外的恐怖图腾氏族占据，该营地是他们在该地区进行神秘且破坏性行动的基地。",kw={"营地","厄运之槌","菲拉斯","豺狼人","恐怖图腾","小精龙","牛头人"},ang={["faction:Alliance"]="恐怖图腾对暗夜精灵及其盟友怀有持续的敌意，使得该定居点成为了菲拉斯中心地带的一处危险障碍。",["race:Tauren"]="恐怖图腾氏族名义上向凯恩·血蹄表示敬意，但像这样的营地揭示了他们远离雷霆崖监视之下的真正野心，这种野心是不受约束的。"},sec={{t="黑色部落的堡垒",b="恐怖图腾营地横跨厄运之槌以东的两个营地，为恐怖图腾氏族在菲拉斯建立了稳固的立足点。与雷霆崖中效忠于凯恩·血蹄的牛头人不同，这里的恐怖图腾独立行动，并对外来者充满敌意。在定居点的南半部，他们将捕获的小精灵龙关在巨大的木笼中，意图不明；而在他们北部边界的边缘，潜伏着流浪的豺狼人。"}},faq={{q="谁住在恐怖图腾营地？",a="该定居点属于恐怖图腾氏族，这是一个以排外和冷酷手段闻名的好斗且神秘的牛头人部落。他们的行动独立于莫高雷的部落联盟部族之外。",al={"这里的人","恐怖图腾营地怪物","谁控制了恐怖图腾营地"}},{q="为什么营地里关着小精灵龙？",a="恐怖图腾捕获了当地的小精灵龙，并将它们关在南部村庄的一个巨大笼子里。他们为何要囚禁这些生物尚未有记录。",al={"为什么囚禁精灵龙","被囚禁的小精灵龙","恐怖图腾的小精灵龙"}},{q="恐怖图腾营地位于哪里？",a="该营地位于菲拉斯中部，就在古老的上层精灵遗迹厄运之槌的东侧，东北方有野生的豺狼群驻扎。",al={"恐怖图腾营地位置","恐怖图腾营地在哪"}}},fp="18,289,28.472.0,36.203.0,45.155.0,40.153.0"}
P.entries["subzone:grizzled-den"] = {n="灰色洞穴",s="灰色洞穴是位于卡拉诺斯西南方雪山中一处隐蔽的洞穴。这里是丹莫罗本土凶猛的霜寒温迪戈的著名巢穴。",h="灰色洞穴是位于卡拉诺斯西南方雪山中一处隐蔽的洞穴。这里是丹莫罗本土凶猛的霜寒温迪戈的著名巢穴。",kw={"洞穴","丹莫罗","冰霜","灰色洞穴","卡拉诺斯","温迪戈"},ang={["profession:Mining"]="洞穴的内外隧道都有裸露的铜矿矿床，如果你能抵御温迪戈的攻击，这里是早期挖掘矿石的可行地点。",["race:Dwarf"]="清理灰色洞穴对于在卡拉诺斯周围训练的年轻矮人登山者来说，几乎是一种成人礼。"},sec={{t="冰冷的巢穴",b="灰色洞穴深凿于卡拉诺斯西南方的岩壁之中，在当地的探险登山者中作为丹莫罗温迪戈群的巢穴而闻名。这些好斗的类人猿野兽能对入侵者喷出冰霜，并成群结队地保护它们的栖息地。尽管危机四伏，勇敢的猎人们仍定期深入洞穴，猎取厚实的温迪戈鬃毛，这些鬃毛在需要用隔热毛皮为寒冷的椅子和马车座垫衬里的工匠手中能卖个好价钱。"},{t="隐藏的宝藏",b="除了可怕的居民之外，灰色洞穴蜿蜒的隧道也吸引着寻找天然财富的投机者。探矿者经常冒险深入外入口，开采从冻结石壁中突出的铜矿脉，而爱冒险的侦察兵则常在更黑暗的角落搜寻被遗弃的储物箱。然而，如果你深入内部，必然会面对潜伏在阴影中的洞穴里体型最大、最凶猛的捕食者。"}},faq={{q="灰色洞穴位于哪里？",a="灰色洞穴位于丹莫罗的卡拉诺斯西南方，隐藏在积雪覆盖的山脊中。",al={"灰色洞穴位置","灰色洞穴在哪里","如何前往灰色洞穴"}},{q="什么生物居住在灰色洞穴中？",a="洞穴中挤满了凶猛的温迪戈。这些好斗的白毛野兽可以吐出冰霜，并且会迅速围攻任何闯入者。",al={"灰色洞穴里有什么","灰色洞穴怪物","灰色洞穴内部生物"}},{q="人们为什么要冒险进入灰色洞穴？",a="猎人和冒险者冒险进入洞穴，主要是为了猎杀温迪戈以获取它们厚实的鬃毛，这些鬃毛是制作保暖座垫的上等材料。其他人则冒着严寒进入隧道，从洞穴石壁中开采生铜矿石。",al={"为什么要前往灰色洞穴","灰色洞穴任务","温迪戈鬃毛"}}},fx={["4377d186"]={q="灰色洞穴是什么？",a="灰色洞穴是一片广阔的洞穴系统，隐匿于丹莫罗卡拉诺斯西南方的雪山之中。它是自然形成的山中巢穴，以寒冷的内部环境以及栖息在岩石深处的野兽而闻名当地。",al={"灰色洞穴是什么","灰色洞穴概况","关于灰色洞穴"}},["44a06046"]={q="灰色洞穴危险吗？",a="是的，它确实会给独行旅人和初出茅庐的冒险者带来危险。洞穴中盘踞着凶猛的温迪戈，它们能够施放寒冰法术。更糟的是，这些野兽常常成群结队地围攻入侵者，而洞穴深处还潜伏着一只异常凶悍的个体。",al={"灰色洞穴有多危险","灰色洞穴的危险","灰色洞穴安全吗"}}},fp="12,183,20.488.0,16.464.0,34.113.0,40.158.0,44.225.0"}
P.entries["subzone:grizzlepaw-ridge"] = {n="灰爪山",s="灰爪山是一处崎岖嶙峋的山坡，位于洛克莫丹的塞尔萨玛以南。当地登山者对这里印象深刻，因为这里栖息着大量的野生熊，并由传说中的野兽“老烟鬼”统领。",h="灰爪山是一处崎岖嶙峋的山坡，位于洛克莫丹的塞尔萨玛以南。当地登山者对这里印象深刻，因为这里栖息着大量的野生熊，并由传说中的野兽“老烟鬼”统领。",kw={"熊","灰爪山","洛克莫丹","老烟鬼","烟鬼","塞尔萨玛"},ang={["class:Hunter"]="这座山脊是追踪野生野兽和对抗像“老烟鬼”这样的顶级掠食者的经典试炼场。",["race:Dwarf"]="由于紧邻塞尔萨玛，山脊上的熊群对当地登山者和补给路线构成了持续的困扰。"},sec={{t="熊的家园",b="灰爪山俯瞰着塞尔萨玛以南的道路，西接碎石怪之谷，是一片由掠食性野生动物统治的粗犷土地。山坡上被领地意识极强的熊所占据，给往来的旅人造成了威胁。在山脊深处居住着“老烟鬼”，这是一头体型巨大、异常凶猛的熊，令当地猎人闻风丧胆。在矮人定居点之间往来的旅客必须时刻警惕树线和上方的岩石台地。"}},faq={{q="灰爪山位于哪里？",a="灰爪山位于洛克莫丹的中心丘陵地带，正处于塞尔萨玛镇的南面，碎石怪之谷的东面。",al={"灰爪山在哪里","灰爪山位置","如何前往灰爪山"}},{q="灰爪山上居住着哪些危险的生物？",a="山脊上到处都是具有攻击性的熊。这里最臭名昭著的居民是“老烟鬼”，这头异常庞大且凶残的野兽偶尔会潜行到山脚下。",al={"灰爪山的熊","老烟鬼是谁","洛克莫丹的老烟鬼"}}},fx={["57fe1f79"]={q="灰爪山是什么？",a="灰爪山是洛克莫丹一处崎岖的山区，位于塞尔萨玛以南、碎石怪之谷以东。这里是未经驯服的矮人荒野，密林与岩石嶙峋的山峰遍布其间，最为人所知的是它作为狩猎场和危险山熊领地的名声。",al={"灰爪山是什么","灰爪山传说","关于灰爪山"}},["09913c6a"]={q="灰爪山危险吗？",a="毫无防备的旅人若在此行走，会遭遇相当大的危险。山脊上有一大群凶猛的熊出没。其中最凶悍的当属老黑炭，这头恶名昭彰的凶熊在高处筑巢，偶尔会游荡到山谷底部，袭击任何挡路的人。",al={"灰爪山有多危险","灰爪山的危险","灰爪山中的威胁"}},d9ee2216={q="灰爪山为什么叫这个名字？",a="这座山脊因盘踞在山坡和岩石高地上的大群凶猛山熊而得名。它们将此地视为自己的领地，其中尤以像老煤灰这样的野兽最为凶悍。",al={"灰爪山名称由来","灰爪山为何得名","灰爪山是如何得名的"}}},fp="16,205,17.468.0,34.150.0,50.184.0"}
P.entries["subzone:grol-dom-farm"] = {n="格罗多姆农场",s="格罗多姆农场是一个朴实的兽人宅地，坐落于北贫瘠之地，位于连接杜隆塔尔和十字路口的道路旁。格罗多姆农场由卡纳尔·菲斯和他的家人居住，尽管当地好斗的野猪人不断骚扰，他们仍在干旱的平原上饲养猪只。",h="格罗多姆农场是一个朴实的兽人宅地，坐落于北贫瘠之地，位于连接杜隆塔尔和十字路口的道路旁。格罗多姆农场由卡纳尔·菲斯和他的家人居住，尽管当地好斗的野猪人不断骚扰，他们仍在干旱的平原上饲养猪只。",kw={"贫瘠之地","火焰图腾","格罗多姆农场","格罗多姆","卡纳尔·菲斯","养猪场","刺鬃","猪"},ang={["class:Shaman"]="对于行走在元素之路上修行者来说，格罗多姆农场是一个至关重要的里程碑，卡纳尔·菲斯会指引你完成与火焰之灵沟通所需的危险仪式。",["faction:Horde"]="像格罗多姆农场这样的宅地，展现了早期部落定居者在严酷、未开化的贫瘠之地开辟可持续生活所需的勇气。"},sec={{t="萨凡纳草原上的养猪场",b="格罗多姆农场建立于杜隆塔尔定居之后，代表了部落在贫瘠之地这片干旱广袤土地上进行耕作的早期努力。该小型宅地由兽人卡纳尔·菲斯和他的孩子们照料，主要负责养猪，同时还要应对恶劣的野生环境和在附近山脊游荡的好斗的刺鬃野猪人袭击者。这是一个偏僻而艰苦的前哨站，为新兴的兽人国家提供了重要的食物来源。"},{t="年轻萨满的指路明灯",b="除了作为养猪场的世俗功能外，该宅地对于处于修行之路上部落新兵来说具有安静的重要意义。卡纳尔·菲斯掌握着关于元素仪式的深厚知识，并在引导年轻萨满完成试炼方面扮演着关键角色。从奥格瑞玛出发向西旅行的求道者经常会被指引到这个简陋的农场，去学习与火焰原始灵魂沟通所需的秘密。"}},faq={{q="什么是格罗多姆农场？",a="格罗多姆农场是一个位于北贫瘠之地的兽人养猪场。它建立于奥格瑞玛建成之后，作为一个偏远的宅地，由兽人卡纳尔·菲斯和他的孩子们进行劳作。",al={"格罗多姆农场信息","贫瘠之地这个地方是什么","兽人养猪场"}},{q="谁住在格罗多姆农场？",a="该农场由一名叫卡纳尔·菲斯的兽人及其子女打理。他们一同维护围栏，放牧猪群，并保护他们微薄的生计免受四处游荡的野兽和野猪人袭击者的侵害。",al={"谁在格罗多姆农场","谁住在这里","卡纳尔·菲斯的家"}},{q="萨满为何要来格罗多姆农场？",a="卡纳尔·菲斯掌握着元素仪式的知识。兽人和牛头人萨满在早期的训练中经常被派去与他交谈，以进行获得“火焰的召唤”并显现“火焰图腾”所需的试炼。",al={"萨满火焰任务","为什么要去格罗多姆","萨满卡纳尔·菲斯"}},{q="农场面临着什么威胁？",a="周围的草原上盘踞着刺鬃野猪人部落。这些好斗的袭击者不断骚扰农场，威胁着牲畜，并危及卡纳尔一家的安全。",al={"为什么这里有野猪人","谁攻击格罗多姆","农场敌人"}}},fx={["571c8690"]={q="格罗多姆农场有何历史？",a="格罗多姆农场是奥格瑞玛和杜隆塔尔建立后，在北贫瘠之地开设的几座兽人养猪场之一。卡纳尔·菲斯希望在这片干旱平原上谋得一份正当生计，于是带着孩子在此定居，养猪度日，在新部落的庇护下过着平静的生活。",al={"格罗多姆农场历史","格罗多姆农场如何建立","格罗多姆农场发生过什么"}}},fp="13,269,28.427.0,25.401.0,22.195.0,27.198.0,37.222.0,27.187.0"}
P.entries["subzone:grom-gol-base-camp"] = {n="格罗姆高营地",s="格罗姆高营地是部落在荆棘谷的主要坚固据点，坐落于北荆棘谷的西海岸。该定居点由指挥官阿格罗戈什指挥，在东部王国的南部地区确立了一个关键的落脚点和补给线。这里有直接通往奥格瑞玛和幽暗城的飞艇塔，是针对当地丛林巨魔部落和敌对联盟势力的武装集结地。",h="格罗姆高营地是部落在荆棘谷的主要坚固据点，坐落于北荆棘谷的西海岸。该定居点由指挥官阿格罗戈什指挥，在东部王国的南部地区确立了一个关键的落脚点和补给线。这里有直接通往奥格瑞玛和幽暗城的飞艇塔，是针对当地丛林巨魔部落和敌对联...",kw={"阿格罗戈什","格罗姆高","奥格瑞玛","斯通纳德","荆棘谷","幽暗城","飞艇"},ang={["faction:Alliance"]="格罗姆高是一个防御森严的敌对堡垒，为部落在东部王国南部深处提供了一个直接的立足点和快速的飞艇交通。",["faction:Horde"]="格罗姆高是部落冒险者在荆棘谷险恶丛林和充满争议的道路上穿行时的主要安全港湾和后勤集结区。"},sec={{t="丛林中的堡垒",b="格罗姆高营地开凿于荆棘谷西北部的茂密丛林之中，是一座由指挥官阿格罗戈什指挥的坚固军事堡垒。营地周围环绕着防御栅栏，并有装备精良的步兵驻守，不断承受着血顶猎头者、潜伏的娜迦以及四处徘徊的野兽的骚扰。尽管面临这些威胁，其重要的战略位置不仅保障了通往悲伤沼泽中斯通纳德的安全补给路线，还时刻监视着从暮色森林南下或从藏宝海湾北上的联盟动向。"},{t="部落的空中桥梁",b="格罗姆高引人注目的木质飞艇塔是东部王国最重要的后勤枢纽之一。系泊于此的地精飞艇维持着通往奥格瑞玛和幽暗城主城的定期航线。这条不间断的空中桥梁使部落军队能够快速将增援部队和资源直接部署到荆棘谷的中心地带，而无需冒险穿越由联盟控制的公路或深海。"}},faq={{q="格罗姆高营地的目的是什么？",a="格罗姆高是部落在荆棘谷的坚固军事集结地。在指挥官阿格罗戈什的指挥下，它建立了一条通往悲伤沼泽中斯通纳德前哨站的后勤生命线，并保护部落利益免受敌对丛林巨魔和联盟入侵的侵害。",al={"为什么格罗姆高在这里","格罗姆高的目的","什么是格罗姆高"}},{q="如何往返格罗姆高？",a="格罗姆高拥有大型飞艇塔，提供直达卡利姆多的奥格瑞玛和提瑞斯法林地的幽暗城的航班。它还维护着一个双足飞龙管理员站点，与连接卡加斯、斯通纳德和藏宝海湾的飞行网络相连。",al={"格罗姆高飞艇","格罗姆高飞行点","如何前往格罗姆高"}},{q="谁负责领导格罗姆高营地？",a="该前哨站由兽人指挥官阿格罗戈什指挥，负责监管这座要塞的防御，抵御敌对的当地巨魔部落、凶猛的野蛮迅猛龙和联盟侦察兵。",al={"格罗姆高领导人","谁管理格罗姆高","格罗姆高指挥官"}},{q="营地面临什么威胁？",a="格罗姆高四面受敌，面临着危险的对手。血顶丛林巨魔在边境附近频繁狩猎，野蛮的迅猛龙在北部的原野上徘徊，而联盟士兵则不断从暮色森林向下或从藏宝海湾港口向上进犯。",al={"格罗姆高敌人","谁攻击格罗姆高"}}},fp="18,439,23.542.0,22.430.0,42.300.0,39.245.0,29.177.0,32.262.0"}
P.entries["subzone:grommash-hold"] = {n="Grommash Hold",s="Grommash Hold是大酋长萨尔的要塞，坐落在奥格瑞玛智慧谷的红色峭壁高处。这座要塞以纪念格罗玛什·地狱咆哮的牺牲而命名，是新部落的Command Center和政治中心。",h="Grommash Hold是大酋长萨尔的要塞，坐落在奥格瑞玛智慧谷的红色峭壁高处。这座要塞以纪念格罗玛什·地狱咆哮的牺牲而命名，是新部落的Command Center和政治中心。",kw={"伊崔格","grommash hold","玛诺洛斯","奥格瑞玛","萨尔","萨尔的要塞","智慧谷"},ang={["faction:Horde"]="这是部落主权的核心所在，在这里制定条约，并指挥针对卡利姆多和东部王国各地威胁的战役。",["race:Orc"]="对于兽人来说，这座要塞和外面的玛诺洛斯遗骸，是他们因格罗姆·地狱咆哮的牺牲而从恶魔之血诅咒中解放出来的终极证明。"},sec={{t="大酋长的驻地",b="Grommash Hold坐落在宁静的智慧谷中，是部落的王室法庭和战略圣所。它建在巍峨的峡谷峭壁之中，其厚实的石质内部显得格外阴暗凉爽——这是大酋长萨尔刻意为之，为的是让特使、请愿者和军阀在觐见时保持清醒和警觉。在这里，萨尔在伊崔格等资深顾问的指引下商讨卡利姆多的防御事宜，并会见沃金等各族首领。"},{t="自由的丰碑",b="在要塞外，深渊领主玛诺洛斯的破碎盔甲和长角的头骨被安装在一棵古树的树干上。这里是为了纪念格罗姆·地狱咆哮而设立的，他在灰谷以生命为代价杀死了这只恶魔。这座纪念碑既是兽人从恶魔之血诅咒中解放出来的骄傲象征，也是对重蹈鲁莽野蛮覆辙的永久、庄严的警示。"}},faq={{q="Grommash Hold里都有谁？",a="大酋长萨尔在这里举行朝会，随行的还有包括兽人长者伊崔格、暗矛部族领袖沃金和战士纳兹格雷尔在内的部落重要领导人和顾问。",al={"要塞里的人","谁住在grommash hold","这里的统治者"}},{q="为什么它叫Grommash Hold？",a="它以战歌氏族传奇酋长格罗玛什·“格罗姆”·地狱咆哮的名字命名。格罗姆在第三次战争中击杀了深渊领主玛诺洛斯，并以生命为代价，使兽人种族永远摆脱了恶魔的奴役。",al={"为什么叫grommash hold","格罗玛什是谁","以谁命名"}},{q="外面陈列的巨大骨头是什么？",a="这个头骨和盔甲属于玛诺洛斯，正是这只恶魔领主的血液最初奴役了德拉诺的兽人。这些遗骸是从灰谷运来，安装在要塞外的一棵树干上，作为部落自由的纪念碑。",al={"外面的恶魔头骨","玛诺洛斯头骨","前面的骨头"}},{q="为什么有些城市路标称它为萨尔的要塞？",a="许多兽人卫兵和旧的路标仍将这座建筑称为萨尔的要塞，因为在里面举行朝会的大酋长正是萨尔。",al={"萨尔的要塞","要塞与堡垒的区别"}}},fx={ce374a3d={q="Grommash Hold发生过什么事？",a="这座要塞与奥格瑞玛一同建于智慧谷，作为新部落的中枢。杜隆塔尔建立期间，萨尔在此接待了半食人魔兽王雷克萨，两人携手保卫这个初生的疆域。第三次战争结束以来，萨尔及其顾问一直在这座冰冷的石厅中治理部落、筹划防御以应对逼近的威胁，并接见来自盟友部族与国家的使者。",al={"grommash hold的历史","grommash hold的事件","grommash hold发生过什么"}},["84f3c4ab"]={q="Grommash Hold危险吗？",a="如果你忠于部落，Grommash Hold完全安全，也欢迎你向其领袖请愿。对联盟成员而言，这里是卡利姆多最致命的地方之一。精锐库卡隆卫兵严密把守，酋长萨尔本人也与久经沙场的勇士驻守于此；任何擅闯者只要踏入智慧谷，便会遭到迅速而无情的处决。",al={"grommash hold安全吗","grommash hold的危险","联盟能进入grommash hold吗"}}},fp="13,255,24.481.0,23.405.0,28.165.0,30.233.0,43.229.0,49.140.0"}
P.entries["subzone:grove-of-the-ancients"] = {n="古树之林",s="古树之林是位于黑海岸东南部，坐落在古老神殿遗迹中的一处神圣暗夜精灵庇护所。这座宁静的港湾毗邻急弯河，不仅是自然之灵的聚集地，还由受人尊敬的知识古树奥努守护着。",h="古树之林是位于黑海岸东南部，坐落在古老神殿遗迹中的一处神圣暗夜精灵庇护所。这座宁静的港湾毗邻急弯河，不仅是自然之灵的聚集地，还由受人尊敬的知识古树奥努守护着。",kw={"知识古树","古树议会","黑海岸","古树之林","奥努","急弯河"},ang={["class:Druid"]="这片树林是一处备受尊崇的自然庇护所，为德鲁伊提供了与知识古树奥努和森林之灵的智慧直接连接的途径。",["race:NightElf"]="树林被古老的神殿遗迹所环绕，并由自然之灵照料，是卡多雷与土地长期和谐共处的庄严象征。"},sec={{t="急弯河庇护所",b="古树之林隐藏在黑海岸东南部的山脉附近，是一处被古老神殿石块环绕的宁静避风港。急弯河穿林而过，在这片逐渐受到腐蚀和狂暴野生动物侵扰的海岸线上提供了一处安静的避难所。这片树林是古树议会的聚会场所，自然之灵和卡多雷在此维护森林的微妙平衡。"},{t="守护者与观察者",b="树林中的核心存在是奥努，这是一棵高大的知识古树，他观察着这片土地的兴衰变化，并为路过的旅人提供古老的智慧。除了奥努，流浪商人和沉睡的德鲁伊也会在树枝下休憩。虽然这里很安静，但树林东南面靠近熊怪的领地，使其成为联盟哨兵和德鲁伊监控黑海岸南部的重要前哨站。"}},faq={{q="古树之林在哪里？",a="古树之林位于黑海岸东南部，坐落在急弯河岸边的山脚下。",al={"古树之林位置","古树之林在哪里","奥努位置"}},{q="奥努是谁？",a="奥努是居住在树林中的一位睿智的知识古树。他作为一位长者向导，守护着东南部森林，并为试图修复黑海岸平衡的德鲁伊和旅行者提供建议。",al={"奥努是谁","古树之林中的古树","黑海岸的树人"}},{q="什么是古树议会？",a="古树议会是一个由伟大的自然之灵和古老的树精组成的集会，他们聚集在树林中进行交流、分享知识并讨论荒野之地的福祉。",al={"古树议会","黑海岸的古树聚会"}},{q="树林附近有危险吗？",a="虽然树林本身是一个有着友善守护者和商人的安全庇护所，但在河对岸和东南部有敌对的野生生物和具有领地意识的熊怪营地。",al={"古树之林威胁","古树之林安全吗","古树之林附近的怪物"}}},fx={b540280c={q="古树之林是什么地方？",a="古树之林是位于黑海岸东南部急弯河畔的一处暗夜精灵圣地遗迹。它围绕一座古老神殿的残垣而建，是一处隐秘的庇护所，远古守护者议会在此集会，受人敬仰的树木守护者和沉睡的自然守护者则守望着这里。",al={"古树之林","古树之林是什么","关于古树之林"}},a4149ac4={q="古树之林为什么叫这个名字？",a="这片圣地的名字既源于居住于此的巨大、有灵智的远古守护者，也源于这片土地上深厚的暗夜精灵古老传承。这里是远古守护者议会的集会之地，也是德高望重的知识古树欧努的家园，因而成为森林太古守护者的永恒纪念地。",al={"古树之林为何得名","它是如何得名的","古树之林名称含义"}},f8aa7b2c={q="古树之林为何沦为废墟？",a="散布在林地各处的石质建筑，是一座古老暗夜精灵神殿历经数千年后衰败留下的遗迹。建筑早已任由风雨侵蚀，也被不断扩张的林木吞没；这片土地依旧十分神圣，由自然之灵悉心照料，而非重建石制建筑。",al={"古树之林为何成为废墟","古树之林神殿遗迹","是谁摧毁了古树之林"}}},fp="21,274,25.440.0,20.434.0,35.138.0,11.195.0,31.177.0,33.182.0"}
P.entries["subzone:growless-cave"] = {n="无草洞",s="无草洞是开凿在奥特兰克山脉岩壁中的一处寒冷洞穴，被凶猛的山地雪人占据。它最广为人知的原因是这里存放着乌泽尔之焰，这是一座与赫尔库拉的黑暗死灵法术相关的邪恶仪式火堆。",h="无草洞是开凿在奥特兰克山脉岩壁中的一处寒冷洞穴，被凶猛的山地雪人占据。它最广为人知的原因是这里存放着乌泽尔之焰，这是一座与赫尔库拉的黑暗死灵法术相关的邪恶仪式火堆。",kw={"奥特兰克","乌泽尔之焰","霜牙","无草洞","赫尔库拉","斯考尔","雪人"},ang={["class:Mage"]="乌泽尔之焰的残迹是一个严酷的警示，提醒人们当肯瑞托的魔法被误用在死灵法术追求上时会发生什么。",["race:Undead"]="对于协助赫尔库拉复仇的被遗忘者来说，这座洞穴具有阴森的意义。赫尔库拉的黑暗仪式和圣物至今仍散落在奥特兰克这个覆灭的国度各处。"},sec={{t="野兽与黑魔法的巢穴",b="无草洞隐藏在俯瞰山麓的积雪高处，主要是奥特兰克地区领地意识极强的山地雪人的巢穴。穿越险峻山坡的旅者往往会避开洞口，尤其是当臭名昭著的雪人斯考尔在外面徘徊时。除了野兽带来的原始危险外，这座洞穴还隐藏着一段阴暗的过去：里面存放着乌泽尔之焰，这是野心勃勃的人类法师赫尔库拉留下的一个奥术火盆。在死前，赫尔库拉打算利用这座火堆进行一场黑暗仪式，以达成巫妖转化，而其邪恶的热量曾将巨大的掠食者霜牙从冰封荒原中吸引出来。"}},faq={{q="无草洞中居住着哪些生物？",a="这座洞穴被奥特兰克土生土长的野生山地雪人所占据。偶尔，一只危险的稀有雪人名为斯考尔会在洞口外徘徊。",al={"这里居住着谁","无草洞怪物","无草洞内有什么"}},{q="乌泽尔之焰是什么？",a="乌泽尔之焰是赫尔库拉建立的一座仪式火堆，他曾是达拉然的一名法师，后来变成了死灵法师。他创造这座火堆是为了一个被禁止的仪式的一部分，旨在将自己转化为永生的巫妖。",al={"乌泽尔之焰","无草洞中的火堆","赫尔库拉之焰"}},{q="霜牙是谁？",a="霜牙是一只漫游在奥特兰克山峰的巨大且异常凶猛的雪人。过去，在乌泽尔之焰上焚烧鲜肉会将这头贪婪的野兽直接引诱到洞穴中。",al={"雪人霜牙","霜牙"}},{q="旅者为何会冒险来此？",a="冒险者深入洞穴通常是为了猎杀危险的雪人以获取毛皮，或者追寻与赫尔库拉在奥特兰克的遗产相关的残留死灵法术制品。",al={"为什么要前往无草洞","无草洞任务"}}},fx={ae5edb73={q="无草洞是什么地方？",a="无草洞是奥特兰克山脉寒冷山坡中的一处洞穴。它远离文明聚居地，主要是凶猛山地雪人的巢穴，可为它们挡住高地上肆虐的寒风。",al={"无草洞是什么","无草洞信息","关于无草洞"}},["719f5ae4"]={q="无草洞发生过什么事？",a="过去，野心勃勃的人类法师赫尔库拉选中这处偏僻巢穴，建立了乌泽尔之焰。他打算将这座黑暗的仪式火堆用作通灵仪式的工具，以晋升为巫妖。",al={"无草洞历史","这里发生过什么","赫尔库拉与无草洞"}},["1fe34e74"]={q="无草洞危险吗？",a="危险。洞里到处都是凶猛的山地雪人，它们会凶狠地守卫巢穴。游荡的野兽斯考尔偶尔会在洞口外徘徊，而强大的雪人霜喉也常出没于洞穴之中。",al={"无草洞有多危险","无草洞的危险","无草洞安全吗"}}},fp="13,244,30.657.0,37.146.0,26.207.0,16.187.0,33.171.0"}
P.entries["subzone:gryphon-roost"] = {n="Gryphon Roost",s="Gryphon Roost坐落在暴风城Trade District东侧的城墙上，是这座都城主要的空中交通枢纽。它由人类狮鹫管理员Dungar Longdrink管理，这里栖息着雄伟的狮鹫，它们负责将信使、士兵和冒险者运送到东部王国的各个角落。",h="Gryphon Roost坐落在暴风城Trade District东侧的城墙上，是这座都城主要的空中交通枢纽。它由人类狮鹫管理员Dungar...",kw={"dungar longdrink","飞行管理员","gryphon roost","暴风城飞行","trade district","蛮锤部族"},ang={["faction:Alliance"]="从该栖木起飞的空中信使线路，对于协调联盟在西部荒野和赤脊山等动荡地区的应对行动至关重要。",["race:Dwarf"]="Gryphon Roost不仅是矮人航空传统与人类都城之间的重要纽带，还通过训练有素的狮鹫让暴风城与卡兹莫丹保持着紧密联系。"},sec={{t="通往天空的门户",b="Gryphon Roost位于俯瞰Trade District运河的防御工事之上，将这座都城与东部王国各地的联盟岗哨和定居点连接了起来。飞行网络由经验丰富的管理员Dungar Longdrink负责，他协调着前往铁炉堡、湖畔镇、哨兵岭及其他地区的航线。"},{t="来自鹰巢山的风情",b="虽然暴风城主要是一个人类王国，但狮鹫及其驯养员的出现，将一部分辛特兰的传统直接带入了城墙之内。狮鹫长期以来一直被蛮锤部族视为尊贵的伙伴，正是他们在第二次战争期间将空中作战和运输引入了更广泛的联盟体系中。在这处栖木上，皮革、饲料和新鲜空气混合而成的独特气息，在城市石砌建筑的包围中营造出一种别样的边境氛围。"}},faq={{q="Gryphon Roost在暴风城的什么位置？",a="该栖木位于东侧城墙上，可以通过从Trade District直接通往上方的楼梯抵达，可以俯瞰Trade District和Old Town之间的运河。",al={"栖木位置","暴风城飞行管理员位置","寻找gryphon roost"}},{q="谁负责管理这里的飞行事务？",a="人类飞行管理员Dungar Longdrink负责管理该栖木。他负责规划路线，并将训练有素的狮鹫租给前往大陆各地联盟定居点的旅行者。",al={"谁是飞行管理员","暴风城飞行管理员","dungar longdrink"}},{q="为什么矮人在人类城市里经营栖木？",a="暴风城的飞行管理员Dungar Longdrink是人类。蛮锤部族的矮人虽然有骑乘狮鹫的悠久传统，但这里栖木的飞行事务是由Dungar负责管理的。",al={"为什么暴风城栖木有矮人","蛮锤部族在暴风城","矮人狮鹫"}},{q="狮鹫可以从这里飞往哪里？",a="该栖木将暴风城与诸如哨兵岭、湖畔镇、夜色镇和铁炉堡等联盟目的地连接起来。进一步的航线还可以通往东部王国的其他定居点。",al={"暴风城的飞行航线","狮鹫去往哪里","栖木飞行连接"}}},fx={c47c3c58={q="Gryphon Roost是什么地方？",a="Gryphon Roost是暴风城的空中交通枢纽，坐落在繁忙的Trade District旁。这里既是王国飞行坐骑的马厩，也是它们的栖息地，信使、士兵和旅人可以乘坐受过训练的狮鹫，迅速穿行于联盟领地。",al={"gryphon roost是什么","gryphon roost的用途","暴风城gryphon roost"}},["4cbfa62c"]={q="Gryphon Roost危险吗？",a="完全不危险。Gryphon Roost坐落在暴风城戒备森严的腹地，受到城卫兵的严密保护。这里饲养的狮鹫都经过充分驯化，早已习惯旅人往来。",al={"gryphon roost安全吗","gryphon roost的危险","gryphon roost的威胁"}},["5a6ce60b"]={q="为什么叫Gryphon Roost？",a="这个设施的名字直接体现了它的用途：它是城中有翼狮鹫专用的巢穴和栖息处，让这些野兽能在长途飞行之间休息、进食和栖息。",al={"gryphon roost为何得名","gryphon roost名称由来","gryphon roost的含义"}}},fp="13,308,20.342.0,20.457.0,48.179.0,32.175.0,50.165.0,37.190.0"}
P.entries["subzone:gunther-s-retreat"] = {n="冈瑟尔的居所",s="冈瑟尔的居所是一座位于提瑞斯法林地中心澈水湖上的与世隔绝的岛屿避难所。这里是冈瑟尔·阿坎努斯的藏身处，他是一位凭借纯粹的意志力从天灾军团中挣脱出来的亡灵法师。这位隐士不信任任何外人，他用忠诚的亡灵仆从环绕着自己的营地，以抵御入侵者。",h="冈瑟尔的居所是一座位于提瑞斯法林地中心澈水湖上的与世隔绝的岛屿避难所。这里是冈瑟尔·阿坎努斯的藏身处，他是一位凭借纯粹的意志力从天灾军团中挣脱出来的亡灵法师。这位隐士不信任任何外人，他用忠诚的亡灵仆从环绕着自己的营地，以...",kw={"澈水湖","冈瑟尔·阿坎努斯","冈瑟尔的居所","巫妖","lillith's dinner table","提瑞斯法林地","亡灵"},ang={["class:Mage"]="奥术师们会赞赏冈瑟尔的非凡壮举；他的魔法意志力极其强大，足以在没有任何帮助的情况下完全切断巫妖王的精神控制。",["race:Undead"]="冈瑟尔·阿坎努斯映照出了被遗忘者自身的悲剧：摆脱了巫妖王的控制，却对一个他认为仍然受制于天灾军团的世界持怀疑和防备态度。"},sec={{t="澈水湖中的隐士",b="冈瑟尔的居所坐落在澈水湖的烟波之中，是一个容易被误认为是天灾军团又一据点的平凡岛屿营地。它的主人冈瑟尔·阿坎努斯做到了很少有凡人施法者能做到的事：当他在亡灵状态下复活时，他凭借自己的奥术造诣，无需任何外力帮助就将自己的灵魂从巫妖王的铁腕中撕裂出来。由于不信任任何人，冈瑟尔认为在洛丹伦徘徊的其他亡灵仍然是天灾军团的傀儡。他隐居在这座孤岛上安静地研习技艺，并派出了僵尸哨兵来撕碎任何渡水而来的人。"}},faq={{q="谁住在冈瑟尔的居所？",a="这座岛屿上住着强大的亡灵法师冈瑟尔·阿坎努斯，他凭借自己的力量摆脱了巫妖王的控制。他与一队看守营地的亡灵仆从居住在那里。",al={"冈瑟尔岛","岛上住着谁","冈瑟尔的居所主人"}},{q="为什么岛上的亡灵具有敌意？",a="冈瑟尔·阿坎努斯认为提瑞斯法的所有其他亡灵生物仍然受到天灾军团的奴役。由于他将自己的独立性看得高于一切，他的仆从被命令攻击任何靠近岛屿的人。",al={"冈瑟尔为何攻击","为何充满敌意","冈瑟尔是天灾军团吗"}},{q="冈瑟尔与被遗忘者结盟了吗？",a="起初并没有。虽然从技术上讲，他像被遗忘者一样是拥有自由意志的亡灵，但冈瑟尔完全将自己孤立了起来。幽暗城的当局试图向他证明他们也摆脱了巫妖王的控制，并希望招募他的才能为他们效力。",al={"冈瑟尔在部落吗","冈瑟尔 被遗忘者","冈瑟尔 幽暗城"}},{q="居所西南方的小岛是什么？",a="在冈瑟尔的居所西南边缘外，坐落着一座名为Lillith's Dinner Table的袖珍无名小岛，这是澈水湖中一处安静而又诡异的奇特地标。",al={"lillith's dinner table","冈瑟尔附近的小岛","餐桌岛"}}},fx={dc3ef5e2={q="冈瑟尔的居所是什么地方？",a="冈瑟尔的居所是一座孤岛，坐落在提瑞斯法林地中部的澈水湖里。四周湖水将其环绕，为自由意志强大的巫妖冈瑟尔·阿坎努斯提供了一处隐秘的庇护所。岛屿与洛丹伦其他地区隔绝，摇摇晃晃的亡灵仆从巡逻四周，守卫着他们隐居的主人。",al={"冈瑟尔的居所是什么","冈瑟尔的居所背景","澈水湖岛屿"}},["2d8f9787"]={q="冈瑟尔的居所危险吗？",a="危险，毫无准备地靠近此地会非常危险。冈瑟尔·阿坎努斯误以为洛丹伦的其他亡灵全都是天灾军团的无意识奴仆。为了保护自己的圣所，他命令僵尸爪牙攻击任何踏上岛岸的人。",al={"冈瑟尔的居所危险吗","冈瑟尔的居所安全吗","冈瑟尔的居所的危险"}},["721e4715"]={q="为什么叫冈瑟尔的居所？",a="这座岛以冈瑟尔·阿坎努斯命名。他是一名自由意志的巫妖，将澈水湖化作自己的私人庇护所。冈瑟尔脱离天灾军团、在死亡后仍保有独立意志，随后退居于此，逃避天灾军团的势力，并与外界隔绝。",al={"为何叫冈瑟尔的居所","冈瑟尔的居所名称由来","谁给冈瑟尔的居所命名"}}},fp="17,338,29.608.0,31.204.0,41.230.0,37.249.0,49.191.0"}
P.entries["subzone:gurubashi-arena"] = {n="古拉巴什竞技场",s="古拉巴什竞技场是一座古老的石制斗兽场，坐落在荆棘谷南部，最初由强大的古拉巴什帝国所建。在今天，它已成为一处混乱的混战试炼场，海盗和流浪的斗士们在这里为了锁住财宝的宝箱而流血厮杀。",h="古拉巴什竞技场是一座古老的石制斗兽场，坐落在荆棘谷南部，最初由强大的古拉巴什帝国所建。在今天，它已成为一处混乱的混战试炼场，海盗和流浪的斗士们在这里为了锁住财宝的宝箱而流血厮杀。",kw={"竞技场","战利品争夺战","宝箱","古拉巴什","小个子约翰·米斯瑞尔","荆棘谷","大竞技场"},ang={["class:Warrior"]="这片沙地提供了艾泽拉斯最纯粹的武力熔炉之一，剥离了宏大的战争政治，一切还原为个人的勇气与原始的生存之道。",["race:Troll"]="对于巨魔来说，这座竞技场是神圣的土地，而非单纯的海盗运动场，它是古老的古拉巴什帝国的丰碑，勇士们曾在这里的沙地上挥洒热血。"},sec={{t="血的遗产",b="早在人类或兽人踏足荆棘谷之前，古拉巴什竞技场——也被称为大竞技场——就已作为庞大的古拉巴什巨魔帝国武力实力的丰碑而建。在古代，勇士们在这片沙地上殊死搏斗，直到大地被巨魔的鲜血染透。"},{t="战利品争夺战",b="虽然古拉巴什帝国早已分崩离析成多个交战的部落，但竞技场的地面却从未保持过长久的整洁。如今，无法无天的海盗和恶棍们在这里上演着另一番血腥的盛景。一个名叫小个子约翰·米斯瑞尔的海盗负责监管这片场地，每隔几小时，就会有一箱劫掠来的战利品被拖到竞技场中央。任何踏入场地的人都可能成为攻击目标——阵营忠诚不复存在，参赛者必须杀出一条血路，从所有挑战者手中夺取奖品。"}},faq={{q="是谁建造了古拉巴什竞技场？",a="它是由古拉巴什帝国在数世纪前统治东部王国南部地区时建造的。它被设计成一座巨大的体育场，用于致命的格斗试炼和祭祀洛阿神的古老巨魔仪式。",al={"谁建造了古拉巴什竞技场","竞技场起源","巨魔竞技场背景故事"}},{q="人们现在为什么还要在这里战斗？",a="当地的海盗利用这座竞技场进行非法娱乐。每隔几小时，一名海盗船长就会将一个藏宝箱拖到沙地中央，引诱任何有胆量踏入竞技场并争夺它的人展开一场血腥的混战。",al={"为什么在古拉巴什战斗","古拉巴什宝箱","战利品争夺战背景"}},{q="小个子约翰·米斯瑞尔是谁？",a="小个子约翰·米斯瑞尔是一名海盗，负责监管竞技场和定期的宝箱投送。他会奖励那些能在混乱的乱斗中不断生存下来并回收他竞技场财宝的参赛者。",al={"小个子约翰·米斯瑞尔","竞技场监管者"}},{q="为什么我所在阵营的成员可以在这里攻击我？",a="竞技场的地面处于完全无法无天的状态。一旦你踏上沙地，所有的阵营条约和军事同盟都会暂停——只有和你身处同一个战斗小队的人才不会受到你的攻击。",al={"为什么古拉巴什是混战模式","古拉巴什误伤","竞技场pvp规则"}}},fp="15,286,17.301.0,13.484.0,30.229.0,29.242.0,26.186.0,49.233.0"}
P.entries["subzone:haldarr-encampment"] = {n="哈达尔营地",s="哈达尔营地是一处被腐蚀的萨特前哨站，坐落于艾萨拉西部，位于影歌神殿东北方，瓦罗莫克西南方。营地中盘踞着凶残的哈达尔萨特，在古老的精灵遗迹中构成了一块危险的毒瘤。这里也是受伤的暗夜精灵哨兵克达拉·阳刃被发现的地方。",h="哈达尔营地是一处被腐蚀的萨特前哨站，坐落于艾萨拉西部，位于影歌神殿东北方，瓦罗莫克西南方。营地中盘踞着凶残的哈达尔萨特，在古老的精灵遗迹中构成了一块危险的毒瘤。这里也是受伤的暗夜精灵哨兵克达拉·阳刃被发现的地方。",kw={"艾萨拉","营地","哈达尔","克达拉·阳刃","萨特","影歌神殿","瓦罗莫克"},ang={["faction:Horde"]="这个恶魔巢穴位于瓦罗莫克西南方，对在艾萨拉悬崖间推进的部落侦察兵和补给线构成了直接威胁。",["race:NightElf"]="对于卡多雷来说，哈达尔萨特是古代上层精灵堕落入恶魔疯狂深渊的一个可耻且持久的提醒。"},sec={{t="恶魔之巢",b="哈达尔营地栖身于艾萨拉西部破碎的石块之间，是哈达尔萨特氏族的聚集地。这些扭曲的生物是天崩地裂时受恶魔腐蚀的上层精灵的古老残余，他们会主动猎杀并骚扰任何穿越这片秋之森林的人。这个人口稠密的定居点对驻扎在附近瓦罗莫克的部落军队以及试图监视该地区的暗夜精灵哨兵们构成了持续的威胁。"},{t="被俘的哨兵",b="在营地那群邪恶的居民之中，哨兵克达拉·阳刃身受重伤，被困在敌人的领地深处。关于她为何逗留在萨特之中，并无记载。"}},faq={{q="哈达尔营地是什么？",a="哈达尔营地是位于艾萨拉西部的一个被腐蚀的定居点，由哈达尔萨特氏族所控制。它位于部落前哨站瓦罗莫克的西南方，影歌神殿的东北方。",al={"哈达尔营地背景故事","哈达尔是什么","谁住在哈达尔营地"}},{q="哈达尔是谁？",a="哈达尔是栖息在艾萨拉的一群凶残的萨特。像所有萨特一样，他们是古代暗夜精灵的后裔，在上古之战中接受了恶魔契约，被诅咒成了服从燃烧军团残余意志的山羊腿恶魔。",al={"哈达尔萨特","这里的萨特是谁"}},{q="哨兵克达拉·阳刃是谁？",a="哨兵克达拉·阳刃是一名受伤的暗夜精灵哨兵，被发现身处哈达尔营地内，周围环绕着敌对的萨特。关于她为何会在那里，并无记载。",al={"克达拉·阳刃","受伤的暗夜精灵","这里的俘虏是谁"}},{q="为什么这个营地对附近的旅行者来说很危险？",a="营地中聚集了大量好战的萨特，他们会积极巡逻并威胁周边道路，危及从瓦罗莫克出发的部落行动以及该地区任何游荡的侦察兵。",al={"哈达尔危险吗","为什么要清理哈达尔"}}},fp="18,342,20.474.0,21.165.1,31.196.0,20.256.0,33.158.0,47.194.0"}
P.entries["subzone:hall-of-arms"] = {n="Hall of Arms",s="Hall of Arms是铁炉堡军事力量的总部，也是矮人王国的首席军械库。这座防御严密的设施位于Military Ward内，负责训练矮人战斗人员，并统筹重型装甲和空中作战机器的部署。",h="Hall of Arms是铁炉堡军事力量的总部，也是矮人王国的首席军械库。这座防御严密的设施位于Military Ward内，负责训练矮人战斗人员，并统筹重型装甲和空中作战机器的部署。",kw={"战场指挥官","矮人军队","飞行器","hall of arms","铁炉堡","military ward","蒸汽坦克"},ang={["class:Warrior"]="该设施是首都矮人军械员和退伍军人的主要聚集地，提供指导和战场指挥官的领导。",["race:Dwarf"]="对矮人而言，Hall of Arms体现了Khaz Modan军事纪律与机械创造力的结合，容纳了保卫这个山脉王国的坦克和空中中队。"},sec={{t="山脉军械库之心",b="Hall of Arms位于Military Ward的东南角，是铁炉堡武装部队的Command Center。除了驻有为战士和猎人提供指导的资深训练师外，这座宽敞的设施还是机械化战争的大型补给站和集结地。重型蒸汽坦克在这里组装和维护，以支援Alliance的战场；而旋翼机和飞行器则通过工业传送带运送，并直接穿过洞穴顶部的垂直通道发射，飞往上方的Ironforge Airfield。"}},faq={{q="Hall of Arms的用途是什么？",a="它是铁炉堡军队的总部和Command Center。它既是战士和猎人的训练场，也是维护和部署蒸汽坦克、旋翼机等战争机器的重要补给站。",al={"hall of arms是什么","hall of arms的作用","hall of arms的由来"}},{q="从天花板发射的飞行器飞向哪里？",a="矮人的飞行器通过传送系统升起，并穿过天花板的垂直通道，直接飞往上方山坡上的Ironforge Airfield。除了正门之外，这个烟囱式通道是山脉中为数不多的直接通往地表的出口之一。",al={"铁炉堡天花板通道","飞行器通道","旋翼机飞往哪里"}},{q="在大厅内可以找到谁在进行训练？",a="该设施驻有战士和猎人的导师，以及负责组织部队调动和征募，以支援大陆各地更广阔战线的Alliance战场指挥官。",al={"hall of arms的训练师","这里有什么导师"}},{q="Hall of Arms位于何处？",a="它位于铁炉堡的东南象限，坐落在Military Ward的后方。",al={"hall of arms的位置","如何前往hall of arms"}}},fx={b2a6f890={q="Hall of Arms是什么地方？",a="Hall of Arms是铁炉堡军事力量的指挥中心和主要总部。它位于这座山城的Military Ward，既是重要军械库，也是训练兵营和机械工场；矮人的攻城器械与飞行器都在此建造、维护，并为联盟各地的战争做好准备。",al={"hall of arms是什么","hall of arms信息","关于hall of arms"}},db189d23={q="Hall of Arms危险吗？",a="对铁炉堡的居民和盟友而言并不危险。这里虽遍布矮人武器、攻城机械和全副武装的士兵，却是王国最安全的据点之一。只有那些愚蠢到威胁城市或与联盟为敌的人，才需要畏惧这里集结的火力。",al={"hall of arms安全吗","hall of arms的危险"}},["15a89202"]={q="为什么叫Hall of Arms？",a="这座建筑群因作为王国的中央军械库和军事核心而得名。铁炉堡在此汇集各种兵器，从用于训练战士和猎人的个人武器与护甲，到蒸汽坦克和旋翼机等重型机械战争机器，皆可在此找到。",al={"hall of arms为何得名","hall of arms名称由来","hall of arms的含义"}}},fp="12,275,31.579.0,40.244.0,58.272.0,40.179.0,34.97.0"}
P.entries["subzone:hall-of-arms-northshire"] = {n="Hall of Arms (Northshire)",s="Hall of Arms是北郡修道院的军事侧翼，位于主厅南侧。在这里，经验丰富的教官对暴风城军队的新兵进行剑术、盾牌和圣光战斗的训练。",h="Hall of Arms是北郡修道院的军事侧翼，位于主厅南侧。在这里，经验丰富的教官对暴风城军队的新兵进行剑术、盾牌和圣光战斗的训练。",kw={"艾尔文森林","hall of arms","北郡修道院","北郡山谷","圣骑士训练师","暴风城军队","战士训练师"},ang={["class:Paladin"]="Hall of Arms平衡了神圣的奉献与军事的坚毅，为初出茅庐的圣骑士提供了在挥舞圣光的同时运用武力的基础指导。",["class:Warrior"]="对于投身服务的人类战士来说，这里是你接受关于姿态、武器操控和暴风城军队军事纪律的第一课的地方。"},sec={{t="卫兵的基石",b="当教士和学者们在庭院对面的图书馆侧翼研读古籍时，Hall of Arms里回荡着钝钢交锋的声音和沉重的军事训练节奏。这个房间位于北郡修道院的南侧，是人类战士新兵和为了暴风城军队而武装起来的虔诚追求者们的主要训练站。在这里，经验丰富的战斗教官和圣骑士导师教授基本的姿态、准则和基础知识，以保护艾尔文森林免受入侵的狗头人、迪菲亚兄弟会强盗和豺狼人的侵害。"}},faq={{q="Hall of Arms的用途是什么？",a="Hall of Arms是北郡修道院内的初级军事训练场。它为新入伍的士兵、雇佣兵和圣骑士提供基础武器训练和战斗技巧，让他们在进入更广阔的王国之前做好准备。",al={"这是什么房间","hall of arms的用途","这里发生了什么"}},{q="这个侧翼里有哪些人？",a="该侧翼由经验丰富的战士和圣骑士训练师组成，他们代表暴风城军队指导新兵进行军事准则、盾牌运用和基础战斗机动训练。",al={"hall of arms里有什么人","hall of arms的训练师","谁在这里教导"}},{q="Hall of Arms在北郡修道院的什么位置？",a="Hall of Arms位于北郡修道院的南侧，可直接从中央主厅进入，与庭院对面的图书馆侧翼相呼应。",al={"hall of arms的位置","hall of arms在哪里","修道院布局"}}},fx={c5e01713={q="为什么它被称为Hall of Arms？",a="这座侧翼因其作为北郡修道院军事训练中心的职能而得名。与另一侧翼的图书馆专用于研习和圣典不同，这座大厅专供武备之事，设有武器教官、军械和武术训练师，为暴风城军队培养新的战士与圣骑士。",al={"为什么叫hall of arms","hall of arms名称含义","hall of arms的含义"}},["1c4cb7f4"]={q="Hall of Arms危险吗？",a="完全不危险。Hall of Arms是北郡修道院内一处安全的庇护所，不受在外面山谷中游荡的迪菲亚匪徒和狗头人侵扰。经验丰富的圣骑士和老练的士兵在安静的石室中看护新兵。除非有麻烦闯过修道院大门，否则你可以在这里安心休息和训练，无须担心受到威胁。",al={"hall of arms的危险","hall of arms安全吗","hall of arms中的敌人"}}},fp="25,215,23.586.0,40.248.0,34.184.0,58.171.0"}
P.entries["subzone:hall-of-arms-tyr-s-hand"] = {n="Hall of Arms (Tyr's Hand)",s="Hall of Arms是位于东瘟疫之地东南部Tyr's Hand Abbey内一个防卫森严的侧厅。它作为驻扎在该要塞的血色十字军军事先遣队的集结地和兵营。它位于修道院内与图书馆相对的位置，安置着十字军中一些最狂热、装备最精良的战士。",h="Hall of Arms是位于东瘟疫之地东南部Tyr's Hand...",kw={"修道院","军械库","东瘟疫之地","hall of arms","血色十字军","提尔之手"},ang={["class:Paladin"]="对于白银之手骑士团的骑士来说，踏入Hall of Arms是一种痛苦的景象，因为他们目睹了神圣的武术战斗传统被扭曲为狂热的孤立主义。",["class:Warrior"]="Hall of Arms内的军备和纪律严明的战备状态代表了人类军国主义的巅峰，即使它是为狂热服务的。"},sec={{t="钢铁堡垒",b="Hall of Arms位于修道院主大厅的南侧，作为提尔之手好战势力的军械库和营房。尽管对面的一侧侧厅存放着档案和圣典，但这侧侧厅完全致力于战争之道。驻扎在这里的血色防卫者身披重甲，誓要铲除亡灵和任何被视为不洁之徒，他们对自己的东方堡垒保持着不懈的警戒，磨砺武器、擦亮盾牌，以抵御瘟疫之地周围的恐怖威胁。"}},faq={{q="Hall of Arms位于何处？",a="Hall of Arms位于Tyr's Hand Abbey内，这是一座位于东瘟疫之地东南角的提尔之手内的大型大教堂要塞。它是修道院建筑群的南侧厅，与图书馆侧厅相对。",al={"hall of arms位置","hall of arms在哪里","tyr's hand abbey hall of arms"}},{q="谁占据了Hall of Arms？",a="该侧厅完全由血色十字军的精英军事力量把守。经验丰富的战士、圣骑士和卫兵在此集结，维护军械，并为与天灾军团以及任何进入他们圣所的外来者作战做好准备。",al={"谁住在hall of arms","hall of arms敌人","血色十字军hall of arms"}},{q="与修道院的其他部分相比，该侧厅的用途是什么？",a="虽然修道院的对面侧厅专注于学习、沉思和研读经文，但Hall of Arms是专门为物理防御、部队驻扎和武器维护而建造的。它确保了这座圣洁的堡垒在军事上依然强大，能够抵御天灾军团的入侵。",al={"hall of arms的用途","hall of arms是做什么的"}},{q="联盟成员可以和平进入吗？",a="不能。尽管有着共同的人类血统并崇拜圣光，但提尔之手的血色十字军完全陷入了狂热。他们将所有外来者视为瘟疫的潜在携带者或邪恶的同情者，对联盟和部落的旅行者一律见即发起攻击。",al={"血色十字军对联盟友好吗","联盟可以访问hall of arms吗","提尔之手会攻击我吗"}}},fp="25,342,18.520.0,34.239.0,30.242.0,67.268.0,45.262.0"}
P.entries["subzone:hall-of-champions"] = {n="Hall of Champions",s="Hall of Champions是血色修道院军械库侧厅的内殿。它是血色勇士赫洛德的驻地，也是血色十字军精英的试炼场。",h="Hall of Champions是血色修道院军械库侧厅的内殿。它是血色勇士赫洛德的驻地，也是血色十字军精英的试炼场。",kw={"步兵军械库","hall of champions","赫洛德","血色十字军","血色修道院"},ang={["class:Paladin"]="对于圣光的骑士们来说，在自己的大厅中面对血色勇士赫洛德，是对于纯粹的美德与信仰如何因狂热而扭曲的一次沉重警示。",["race:Human"]="来自洛丹伦的人类旅行者可能会认出，在十字军的勇士中，有不少人曾是北方王国的保卫者，后来投身于这个狂热的十字军组织。"},sec={{t="血色勇士的驻地",b="Hall of Champions位于步兵军械库之后，坐落在修道院军械库侧厅的核心地带。在这里，血色勇士赫洛德统率着十字军最凶猛的战士，而血色的受训者们也在此磨砺意志，立誓清除洛丹伦所有的亡灵和外来者。"}},faq={{q="Hall of Champions的目的是什么？",a="这座大厅是修道院军械库的内殿，血色勇士赫洛德在此统领着十字军的精锐战士，受训者们也在此为对抗亡灵的战争磨练技艺。",al={"什么是hall of champions","hall of champions的用途","为什么这里有雕像"}},{q="雕像中纪念的人是谁？",a="此处纪念的勇士并未记载于那个时代的档案中。这座大厅里最著名的人物是一位活人：镇守此处的血色勇士赫洛德。",al={"雕像是谁","hall of champions的雕像名字","修道院雕像"}},{q="这座大厅与暴风城的勇士大厅有何不同？",a="尽管名字相似，但此厅位于提瑞斯法林地的血色修道院深处，致力于纪念受人尊敬的血色人物。而暴风城的勇士大厅是一处留给联盟军官和PvP军需官使用的军事驻地。",al={"这是暴风城pvp大厅吗","hall of champions与勇士大厅的区别","pvp大厅混淆"}}},fx={c3492897={q="Hall of Champions是什么地方？",a="Hall of Champions是血色修道院军械库翼区深处的一处内殿，位于步兵军械库之外。这里是血色勇士赫洛德的驻地，也是十字军最强悍的战士严阵以待、抵御入侵者的地方。",al={"hall of champions是什么","血色修道院hall of champions"}},["379bd11f"]={q="谁负责看守Hall of Champions？",a="血色勇士赫洛德驻守在修道院的军械库中的Hall of Champions。他是当地十字军的重要领袖之一。",al={"谁管理hall of champions","hall of champions里有哪些人","hall of champions首领"}},["91532869"]={q="Hall of Champions危险吗？",a="是的。赫洛德和血色守卫会敌视擅闯者。进入这间大厅，就意味着要在十字军自己的据点中与他们交锋。",al={"hall of champions安全吗","hall of champions有危险吗"}},["9eb683e4"]={q="为什么它被称为Hall of Champions？",a="这间大厅因其作为十字军勇士驻地的职能而得名。血色勇士赫洛德在此统领着骑士团的精锐战士。",al={"为什么叫hall of champions","hall of champions名称"}}},fp="17,190,28.280.0,45.189.0,47.168.0,59.252.0"}
P.entries["subzone:hall-of-explorers"] = {n="Hall of Explorers",s="Hall of Explorers是铁炉堡庞大的考古区，也是矮人探险者协会的繁忙总部。这里集博物馆、档案馆和探险指挥中心的功能于一身，汇集了来自艾泽拉斯各个角落的文物、化石和古籍，旨在拼凑出矮人种族被遗忘的起源。",h="Hall of Explorers是铁炉堡庞大的考古区，也是矮人探险者协会的繁忙总部。这里集博物馆、档案馆和探险指挥中心的功能于一身，汇集了来自艾泽拉斯各个角落的文物、化石和古籍，旨在拼凑出矮人种族被遗忘的起源。",kw={"考古学","探险者协会","hall of explorers","铁炉堡图书馆","magellas","博物馆"},ang={["race:Dwarf"]="对于矮人冒险者来说，该大厅是你种族遗产的终极宝库，馆藏旨在揭示你们古老的起源以及与泰坦的联系。"},sec={{t="探险者协会总部",b="Hall of Explorers位于铁炉堡的东北洞穴中，有时也被称为探险者议会，是所有联盟批准的考古活动的枢纽。在高阶探险家Muninn Magellas的领导下，学者和外勤人员协调着远方的挖掘工作，将神秘的文物、古老的泰坦机械和史前骨骼运回这里。位于其中心的大型图书馆既作为公共博物馆，也是受限的史料仓库。"}},faq={{q="Hall of Explorers有什么用途？",a="它是探险者协会的全球总部和档案博物馆。学者们在这里分析实地报告，对挖掘出的文物进行编目，并组织考古挖掘以揭示矮人和古代艾泽拉斯的起源。",al={"hall of explorers用途","这里发生什么","探险者协会基地"}},{q="这里由谁负责指挥？",a="高阶探险家Muninn Magellas在该区内负责监督大厅的探险、博物馆的藏品管理和研究档案。",al={"谁管理hall of explorers","探险者协会领袖","高阶探险家"}},{q="这个地方如何与铁炉堡的其他区域连接？",a="Hall of Explorers位于城市的东北部。拱门将其与西南方向的Great Forge、西侧的Forlorn Cavern以及南侧的Tinker Town直接相连。",al={"如何到达这里","hall of explorers出口","hall of explorers在哪里"}}},fx={f8b05ac5={q="Hall of Explorers是什么地方？",a="Hall of Explorers有时也称为探险者协会，是铁炉堡东北部一处重要区域，也是矮人探险者协会的世界总部。这里不仅设有办公室和研究档案室，还是一座宏伟的博物馆和图书馆，陈列着从艾泽拉斯各地发掘出的古代遗物、巨型骸骨和历史典籍。",al={"hall of explorers是什么","铁炉堡hall of explorers","探险者协会"}},["4a4e8160"]={q="Hall of Explorers危险吗？",a="完全不危险。这座大厅位于铁炉堡戒备森严的腹地，十分安全。派往荒野的探险队会面对险境重重的废墟、敌对野兽和古老诅咒，但这片区域本身是安静的学术圣所，聚集着档案管理员、考古学家以及研究发现的联盟要员。",al={"hall of explorers危险吗","hall of explorers有危险吗","这里安全吗"}},eaed4071={q="为什么它被称为Hall of Explorers？",a="这片区域直接以其创立者和领导者——矮人探险者协会命名。探险者协会成立的目的是探寻矮人族的起源、拼凑泰坦历史；他们将这座山城的侧翼改建为无畏探险者的中央集结地和档案馆。",al={"为什么叫hall of explorers","为什么命名为hall of explorers","hall of explorers名称由来"}}},fp="17,327,26.517.0,39.239.0,30.127.0,53.195.0"}
P.entries["subzone:hall-of-gears"] = {n="Hall of Gears",s="Hall of Gears是一个位于堕落城市诺莫瑞根内部的多层工业大厅，就在Clockwerk Run之后。这里曾是一个繁忙的机械运转中心，如今已沦为废墟，充斥着有毒淤泥、游荡的软泥怪和受到辐射的穴居人。",h="Hall of Gears是一个位于堕落城市诺莫瑞根内部的多层工业大厅，就在Clockwerk Run之后。这里曾是一个繁忙的机械运转中心，如今已沦为废墟，充斥着有毒淤泥、游荡的软泥怪和受到辐射的穴居人。",kw={"clean zone","clockwerk run","宿舍区","诺莫瑞根","hall of gears","launch bay","放射性","穴居人"},ang={["profession:Engineering"]="自动化齿轮和高架平台的巨大规模展现了陷落前侏儒工程学的巅峰，尽管如今已被放射性尘埃严重腐蚀。",["race:Gnome"]="看到淹没在放射性淤泥中的巨大齿轮和猫道，令人痛苦地回想起那个毒害了城市并将侏儒种族驱逐流亡的绝望决定。"},sec={{t="破损的机器",b="Hall of Gears位于Clockwerk Run之外，展示了侏儒首都灾难性的崩塌。该大厅分为两个主要层级，上层的猫道被好斗、受到辐射的穴居人占据，它们正从坍塌的检修井中不断涌入。底层地板浸泡在放射性尘埃的积液中，腐蚀性的粘液怪和活体毒素元素在有毒的径流中肆虐。"},{t="废料中的通道",b="该大厅是诺莫瑞根运作区深处的一个关键交汇点。从其上层的走道出发，路径可通往受污染的死胡同，以及相对安全的Clean Zone和宿舍区。下降到下方的放射性深处，最终会引导旅行者穿过蜿蜒的维护通道到达Launch Bay，不过无论走哪一层，都需要突破麦克尼尔·瑟玛普拉格毁灭性通风计划所留下的恐怖事物。"}},faq={{q="Hall of Gears在哪里？",a="Hall of Gears位于诺莫瑞根地下城深处，直接连接在Clockwerk Run之后。它向内连接着Clean Zone、宿舍区和Launch Bay。",al={"hall of gears位置","hall of gears在哪里","如何前往hall of gears"}},{q="为什么底层充满了放射性淤泥？",a="当大工匠梅卡托克下令排放放射性气体以击退穴居人入侵时，受污染的径流汇集到了城市低洼的机械大厅中，将Hall of Gears的底层变成了一片有毒荒地。",al={"为什么这里是绿色的","hall of gears放射性废料","淤泥是什么"}},{q="这里栖息着什么生物？",a="上层被通过裂隙隧道涌入的变异、受辐射的穴居人所侵扰。底层则充斥着放射性沉降物粘液、软泥怪，以及由工业径流形成的极不稳定的毒素元素。",al={"hall of gears敌人","hall of gears里有什么","hall of gears怪物"}},{q="这里的出口通向哪里？",a="上层走道通往西南方向的Clean Zone和宿舍区，以及东南方向的一条死胡同维护走廊。被辐射的底层设有一条通往西方的蜿蜒通道，可直接进入Launch Bay。",al={"hall of gears出口","从hall of gears去哪里"}}},fx={d9a40d55={q="Hall of Gears是什么地方？",a="Hall of Gears是诺莫瑞根地下城市中的一座巨大多层大厅，位于Clockwerk Run之外。它曾是侏儒首都繁荣的工业与精密机械中心，展现了这座城市的大部分科技奇观。如今，这里已成为危险的通道，上层遍布受辐射污染的走道，下层则深陷有毒污泥。",al={"hall of gears简介","这是什么地方","诺莫瑞根hall of gears"}},["3f6f0027"]={q="Hall of Gears发生了什么？",a="野蛮的穴居人攻入城市后，高阶工匠试图用放射性尘埃淹没大厅，以清除入侵者。然而，有毒气体没有赶走穴居人，反而使他们发生变异，并污染了整个区域。侏儒被迫撤离，Hall of Gears就此废弃，留给受辐射污染的怪物和蔓延的有毒废料。",al={"hall of gears历史","这里发生了什么","诺莫瑞根灾难 hall of gears"}},ad0af20b={q="Hall of Gears危险吗？",a="这里极其危险。上层遍布敌视入侵者的狂暴受辐射污染的穴居人。下层地面则被积聚的放射性尘埃淹没，栖息着酸性软泥怪和不稳定的毒元素。穿越这座大厅时，必须避开毒池，并应对这座城市毁灭后滋生的扭曲怪物。",al={"hall of gears危险吗","hall of gears中的威胁","hall of gears有多危险"}}},fp="13,267,19.407.0,26.482.0,35.184.0,50.240.0,36.227.0,34.242.0"}
P.entries["subzone:hall-of-legends"] = {n="传说大厅",s="传说大厅是部落的精英军事庇护所和军官营房，坐落在奥格瑞玛的Valley of Strength中。在其受护卫的门槛后，部落的勇士们聚集在作战计划周围，并用从艾泽拉斯及其他地区冲突中获得的顶级武器武装自己。",h="传说大厅是部落的精英军事庇护所和军官营房，坐落在奥格瑞玛的Valley of Strength中。在其受护卫的门槛后，部落的勇士们聚集在作战计划周围，并用从艾泽拉斯及其他地区冲突中获得的顶级武器武装自己。",kw={"传说大厅","军官营房","奥格瑞玛","pvp","战争的战利品","石卫士","valley of strength"},ang={["class:Warrior"]="对于前线战士来说，进入传说大厅代表了战斗荣誉的巅峰，可以获得部落所能提供的最好的装备。",["faction:Horde"]="传说大厅是部落军事成就的终极证明，为那些为大酋长流血牺牲的人们提供认可、战略建议和珍贵的装备。"},sec={{t="部落勇士的圣所",b="传说大厅位于Valley of Strength熙熙攘攘的街道旁，是部落受勋军官的私人堡垒。在其守卫森严的入口后，来自各阵营的战略家和代表——包括雷霆崖的Earthbind酋长、暗矛部族的血卫士Hini'wana以及幽暗城的Willington顾问——在这里查阅争议地区的地图，并商讨双方阵营的军事地位。在这里，只有经过考验并达到石卫士或更高军衔的战士才被允许进入，以获取与其地位相符的战利品和装备。"},{t="战争的战利品",b="这座大厅不仅仅是一个军官休息室，它还设有军械库，为部落受勋的军官提供经过战斗考验的装备。对于那些在军阶上不断攀升的人来说，它是部落荣誉、战斗实力和来之不易的胜利的物理化身。"}},faq={{q="谁被允许进入传说大厅？",a="只有在军事荣誉系统中达到石卫士（6级）或更高军衔的部落勇士才被准许进入。低阶士兵和普通公民会被拒之门外。",al={"我可以进入传说大厅吗","传说大厅要求","传说大厅所需的军衔"}},{q="传说大厅位于哪里？",a="传说大厅位于奥格瑞玛的Valley of Strength，靠近城市的主要营房和行政中心。",al={"传说大厅在哪里","传说大厅位置","如何前往传说大厅"}},{q="传说大厅里有什么？",a="大厅内有一张中央战略桌，两侧是部落各族的军事代表，周围环绕着艾泽拉斯的地图和军事记录。军需官也在此维护军械库，为功勋卓著的军官分发享有盛誉的武器、护甲和坐骑。",al={"传说大厅里有什么","传说大厅内部"}},{q="联盟有对应的地方吗？",a="有。联盟的对应地点是勇士大厅，位于暴风城的Old Town区，它同样作为受尊崇的联盟战斗人员的军官营房和军械库。",al={"联盟的勇士大厅","联盟对应地点"}}},fx={e332bf32={q="Hall of Legends是什么地方？",a="Hall of Legends是部落精锐军官的军营和军械库，坐落在奥格瑞玛的力量谷。久经沙场的勇士在这里聚集，制定军事策略、查看遍布艾泽拉斯的战争地图，并装备在世界各地的战役中锻造或缴获的特制武器和护甲。",al={"hall of legends是什么","hall of legends的用途","这是什么地方"}},e6163205={q="谁负责管理Hall of Legends？",a="大厅里有军需官和部落各核心阵营的代表，他们聚集在中央的战争议事桌旁。雷霆崖的酋长地缚、代表被遗忘者的顾问威灵顿，以及暗矛巨魔的血卫士希尼瓦娜等军官，会在此商议战略地图并检查军械库的物资。",al={"谁管理hall of legends","hall of legends里有哪些人","hall of legends军官"}},["5e706ae3"]={q="Hall of Legends危险吗？",a="对于有资格踏入此地的忠诚部落勇士而言，Hall of Legends没有任何人身危险。这座圣所位于奥格瑞玛腹地，戒备森严，专为军事老兵和为他们配备装备的军需官而设。",al={"hall of legends安全吗","hall of legends有危险吗","这里有敌意吗"}}},fp="15,300,28.609.0,17.258.0,42.231.0,37.129.0,35.273.0,46.196.0"}
P.entries["subzone:hall-of-masks"] = {n="Hall of Masks",s="Hall of Masks是位于悲伤沼泽中沉没的神庙内部的一间不祥之厅。这里排列着巨大的颅骨面具，并且有一条散落着骸骨的沟壑，标志着进入阿塔莱要塞深处的早期关口之一。",h="Hall of Masks是位于悲伤沼泽中沉没的神庙内部的一间不祥之厅。这里排列着巨大的颅骨面具，并且有一条散落着骸骨的沟壑，标志着进入阿塔莱要塞深处的早期关口之一。",kw={"阿塔莱","broken hall","hall of masks","沉没的神庙","悲伤沼泽","阿塔哈卡神庙"},ang={["class:Priest"]="令人毛骨悚然的建筑风格和充满骸骨的沟壑暗示了阿塔莱的黑暗行径，尽管这间厅堂的具体用途尚不得而知。",["race:Troll"]="对于暗矛巨魔来说，这间厅堂代表了阿塔莱狂热者为了绝望地追寻夺灵者哈卡所愿意采取的邪恶手段。"},sec={{t="恐怖的门槛",b="Hall of Masks位于从Broken Hall下来的楼梯之后，是沉没的神庙内部的一个中心枢纽。这间厅堂因其石墙上安装的巨大、风格化的颅骨面具而得名。在面具下方有一条深沟，里面塞满了丢弃的骸骨，暗示了一种具体的性质尚不可知的可怕用途。在这座阴森的厅堂之外，通道通往屠宰场、血之厅以及召唤者之穴。"}},faq={{q="Hall of Masks位于哪里？",a="Hall of Masks是阿塔哈卡神庙的一个内部侧厅，位于悲伤沼泽的泪水之池的水面之下。你可以通过经过沉没建筑群入口附近的Broken Hall往下走来到这里。",al={"hall of masks位置","hall of masks在哪里","寻找hall of masks"}},{q="为什么它被称为Hall of Masks？",a="它得名于装饰着厅堂墙壁的巨大雕刻颅骨面具，这些面具俯视着每一个穿过神庙走廊的人。",al={"hall of masks名称含义","为什么有面具"}},{q="地板上的沟壑有什么用途？",a="沟壑中散落着骸骨，暗示了一种可怕的功能。其确切用途尚不得而知。",al={"为什么地板上有骸骨","hall of masks骸骨坑","骸骨沟壑"}},{q="从这个厅堂出去的通道通向哪里？",a="走出Hall of Masks会通向神庙更深处的低层区域，直接连接到诸如屠宰场、血之厅以及召唤者之穴等区域。",al={"hall of masks出口","hall of masks通向哪里"}}},fp="13,242,20.470.0,35.230.0,35.154.0,48.95.0,42.183.0"}
P.entries["subzone:hall-of-mysteries"] = {n="Hall of Mysteries",s="坐落于铁炉堡Mystic Ward的Hall of Mysteries，是这座城市在奥术与神圣领域中的精神与学术核心。在其幽蓝的光照下，矮人和侏儒修行者们研究着古老的典籍，修习圣光的奥秘，并在此处远离Great Forge的叮当打铁声，编织奥术附魔。",h="坐落于铁炉堡Mystic Ward的Hall of Mysteries，是这座城市在奥术与神圣领域中的精神与学术核心。在其幽蓝的光照下，矮人和侏儒修行者们研究着古老的典籍，修习圣光的奥秘，并在此处远离Great...",kw={"hall of mysteries","铁炉堡","法师","mystic ward","圣骑士","牧师","洛汉","白银之手","tome of divinity"},ang={["class:Paladin"]="对于白银之手的矮人勇士来说，这座大厅是他们使命的基石，导师们会在此布置美德试炼并准许他们查阅神圣的Tome of Divinity。",["class:Priest"]="高阶牧师洛汉在此引导圣光侍僧进行精神课程的学习，随后会将那些有前途的牧师送往南方，与暴风城的领袖们会晤。"},sec={{t="魔法与信仰的神殿",b="Hall of Mysteries沐浴在独特的蓝色与紫色光辉之中，在铁炉堡内显得格外醒目。尽管整座城市建立在石头、钢铁与重甲之上，这座大厅内耸立的五根柱子却庇护着身披柔软长袍的学者。它连接着奥术魔法与神圣信仰，是卡兹莫丹境内矮人牧师与白银之手骑士团的总部。在此处，年轻的牧师和骑士们研读如Tome of Divinity之类的圣书，在踏上前往暴风城Cathedral of Light的旅程之前，接受教导。"}},faq={{q="Hall of Mysteries的用途是什么？",a="Hall of Mysteries是铁炉堡最重要的神圣信仰与奥术学习中心。它既是一座圣光神殿，也是一间研习室，供矮人和侏儒牧师、圣骑士及法师们聚在此处修习技艺、钻研古老经文并训练新晋成员。",al={"这是什么地方","hall of mysteries的目的","为什么要访问hall of mysteries"}},{q="谁领导着这里的神职人员？",a="高阶牧师洛汉负责管理厅内的神职人员，作为矮人圣光修行者的精神向导，同时还有如Valgar Highforge之类的圣骑士导师，负责指导城内的白银之手骑士。",al={"谁管理hall of mysteries","铁炉堡牧师领袖","谁是高阶牧师洛汉"}},{q="它与暴风城的Cathedral of Light相比如何？",a="暴风城的Cathedral of Light纯粹致力于神圣信仰和盛大的礼仪崇拜，而Hall of Mysteries则将神圣研习与奥术学术无缝地融合在同一屋檐下。这里的氛围更偏向学术与安静，而非单纯的礼拜。",al={"cathedral of light与hall of mysteries的区别","它和暴风城大教堂一样吗"}},{q="圣骑士可以在这里完成他们的训练试炼吗？",a="可以。矮人圣骑士会被派往大厅，在白银之手的指导下研读Tome of Divinity，接受旨在考验其同情心、虔诚和勇气的教导与神圣试炼。",al={"铁炉堡圣骑士任务","tome of divinity铁炉堡","矮人圣骑士任务"}}},fx={["1847c72f"]={q="Hall of Mysteries是什么地方？",a="Hall of Mysteries是一座宏伟的神殿与圣所，位于铁炉堡的Mystic Ward。这里笼罩在柔和的蓝紫色光辉之中，耸立着高大的几何形石柱，是首都中信仰崇拜与奥术研习的中心。矮人和侏儒学者、牧师、圣骑士与法师在此聚集，研习、实践各自的技艺，并指导新学徒。",al={"hall of mysteries是什么","铁炉堡hall of mysteries","mystic ward神殿"}},e1807a94={q="Hall of Mysteries里住着谁？",a="大厅里主要是身着飘逸长袍的矮人和侏儒学者，与铁炉堡其他地方常见的厚重板甲形成鲜明对比。这里的教士和导师包括光明教会的高阶牧师洛汉、白银之手骑士团的瓦尔加·高锻，以及指导学生研习奥术知识的资深法师教官。",al={"谁住在hall of mysteries","hall of mysteries里的居民","hall of mysteries里有哪些人"}},["68d8f867"]={q="Hall of Mysteries危险吗？",a="完全不危险。Hall of Mysteries是铁炉堡腹地一处戒备森严的圣所，由王国最优秀的圣骑士、牧师和法师守卫。对于寻求治疗、静心祈祷或学术研究的联盟居民而言，这里是安全的避难所。",al={"hall of mysteries安全吗","hall of mysteries有危险吗","hall of mysteries里的敌人"}}},fp="17,341,27.605.0,45.289.0,26.230.0,59.266.0,49.211.0"}
P.entries["subzone:hall-of-the-brave"] = {n="Hall of the Brave",s="Hall of the Brave是位于奥格瑞玛Valley of Honor东部高地的宏伟战士兵营。它是部落前线战斗人员、教官和战场军官的主要训练场所和公会会所。",h="Hall of the Brave是位于奥格瑞玛Valley of Honor东部高地的宏伟战士兵营。它是部落前线战斗人员、教官和战场军官的主要训练场所和公会会所。",kw={"兵营","战场军官","hall of the brave","奥格瑞玛","valley of honor","战士训练师","战士公会"},ang={["class:Warrior"]="Hall of the Brave是你在这座首都的武术家园，这里有训练师，随着你实力的增长，他们会解锁进阶姿态和战斗策略。",["faction:Horde"]="这座兵营是部落前线纪律的活生生的体现，驻扎着召集部队在整个大陆作战的战场军官。"},sec={{t="战士之垒",b="Hall of the Brave俯瞰着Valley of Honor宁静的水域和训练场，是新兴部落重要的军事枢纽。在内部，老兵军官和经验丰富的战士向新兵传授近战、姿态掌控和纪律等残酷的基础知识。大厅里排满了训练假人和武器装备，驻扎着为艾泽拉斯各地的重大军事行动组织战斗人员的战场军官。"}},faq={{q="Hall of the Brave的目的是什么？",a="它是奥格瑞玛战士的主要兵营和公会大厅。在这里，战士们向经验丰富的训练师学习技巧，在练习假人上磨练打击技术，并向战场军官咨询在各争议领土的军事部署事宜。",al={"什么是hall of the brave","这栋建筑是什么","hall of the brave的用途"}},{q="该大厅在奥格瑞玛的什么位置？",a="Hall of the Brave位于Valley of Honor的东侧，坐落在红色峡谷的岩壁旁，俯瞰着山谷的中心池塘。",al={"hall of the brave在哪里","hall of the brave的位置","寻找奥格瑞玛的战士训练师"}},{q="在大厅里可以找到谁？",a="大厅里有各种战士职业训练师、协调大规模冲突的战场军官，以及在执勤间隙休息的部落步兵。",al={"hall of the brave里有什么人","hall of the brave的npc"}}},fx={["3fba9d5a"]={q="Hall of the Brave是什么地方？",a="Hall of the Brave是奥格瑞玛宏伟的军营和战士公会会所，位于城市的荣誉谷。这里是部落老兵聚集、训练和处理军事事务的中心。战士们在坚固的墙垣内对着训练假人磨砺技艺，向资深军官请教，并为保卫杜隆塔尔和部落边境而进行准备。",al={"hall of the brave是什么","奥格瑞玛hall of the brave","奥格瑞玛战士大厅"}},["1f330543"]={q="Hall of the Brave安全吗？",a="对部落的忠诚成员而言，Hall of the Brave完全安全，是一个充满情谊、传授技艺并弘扬纪律与武勇的地方。然而，胆大或愚蠢到敢踏入此地的联盟潜伏者，将被驻守军营的部落精锐战士教官、战斗大师和老兵迅速残忍地杀死。",al={"hall of the brave安全吗","hall of the brave危险吗","hall of the brave有什么危险"}}},fp="17,246,21.443.0,45.254.0,39.151.0,33.146.0"}
P.entries["subzone:hammerfall"] = {n="落锤镇",s="落锤镇是部落在阿拉希高地的主要防御前哨，它建立在一座臭名昭著的联盟拘留营遗址之上。落锤镇是为了纪念传奇的前任大酋长Orgrim Doomhammer，他在附近为了解放被俘的族人而英勇牺牲。如今，兽人和被遗忘者驻扎于此，共同抵御敌对的石拳食人魔、枯木巨魔以及阿拉索联军。",h="落锤镇是部落在阿拉希高地的主要防御前哨，它建立在一座臭名昭著的联盟拘留营遗址之上。落锤镇是为了纪念传奇的前任大酋长Orgrim...",kw={"阿拉希高地","石拳食人魔","污染者","落锤镇","拘留营","orgrim doomhammer","萨尔","枯木巨魔"},ang={["faction:Horde"]="落锤镇被敌对的食人魔、森林巨魔和残余的联盟所包围，它是部落确保控制阿拉希高地中部地区唯一的堡垒。",["race:Orc"]="落锤镇是兽人的一片圣地，它标志着Orgrim Doomhammer为了解放被俘的族人并向萨尔交接大酋长之位而献出生命的地方。"},sec={{t="解放的遗产",b="第二次战争结束后，人类联盟在洛丹伦各地建立了庞大的拘留营，以关押战败的兽人。曾经矗立在此的营地是其中规模最大的一座。多年后，萨尔和Orgrim Doomhammer突袭了该营地，解放了那些萎靡不振的俘虏。在撤退的混乱中，一名冲锋的联盟骑士将长矛刺穿了Doomhammer的背甲，这位传奇大酋长因此受了致命伤。第三次战争后，新部落收复了这片荒废的土地并在此建立了前哨站，以他们牺牲的领袖之名将其命名为落锤镇。"},{t="高地上的立足点",b="如今，落锤镇是部落在阿拉希的生命线。身处充满敌意的环境中，驻军必须对抗来自博德戈尔和石拳大厅的侵略性石拳食人魔，以及当地的枯木巨魔。此外，被遗忘者污染者将此作为前哨基地，以在阿拉希盆地争夺对抗联盟阿拉索联军的关键资源。"}},faq={{q="为什么这个基地叫落锤镇？",a="它是为了纪念前任大酋长Orgrim Doomhammer，他在解放兽人拘留营的过程中，在此地被联盟骑士的长矛刺中，伤重身亡。",al={"为什么叫落锤镇","落锤镇名称由来","谁在落锤镇牺牲"}},{q="部落重建之前，落锤镇是什么？",a="它是洛丹伦联盟最大的拘留营之一，建于第二次战争之后，用于关押被俘的兽人。",al={"落锤镇历史","落锤镇的前身","阿拉希拘留营"}},{q="谁目前负责指挥落锤镇的防御？",a="兽人Drum Fel统治着落锤镇并协调前哨站的防御，指挥部落勇士对抗不断侵袭的石拳食人魔和枯木森林巨魔。塔伦米尔的被遗忘者战士Tallow会首先派遣新兵去打击博德戈尔的石拳食人魔。",al={"落锤镇指挥官","谁负责落锤镇","塔洛 杜拉姆法尔"}},{q="为什么被遗忘者会驻扎在这里？",a="被遗忘者污染者以落锤镇为基地开展行动，以确保从阿拉希盆地获得重要补给，并对抗联盟的阿拉索联军。",al={"落锤镇被遗忘者","为什么不死族在落锤镇","污染者 阿拉希"}}},fp="10,390,22.578.0,27.405.0,35.178.0,48.124.0,46.285.0,36.140.0"}
P.entries["subzone:harborage"] = {n="避难营",s="避难营是一处安静的定居点，由一群被放逐的德拉诺原住民组成，坐落于悲伤沼泽的北部边缘。虽然许多同样遭受苦难的族人在周围的沼泽中徘徊，已经陷入了疯狂和原始的敌意中，但这里的居民却设法保持了理智和清醒。他们小心翼翼地生活在水边，在这片严酷且无情的荒野中寻求安宁。",h="避难营是一处安静的定居点，由一群被放逐的德拉诺原住民组成，坐落于悲伤沼泽的北部边缘。虽然许多同样遭受苦难的族人在周围的沼泽中徘徊，已经陷入了疯狂和原始的敌意中，但这里的居民却设法保持了理智和清醒。他们小心翼翼地生活在水边...",kw={"破碎者","德拉诺水晶","避难营","失落者","玛格图尔","悲伤沼泽"},ang={["faction:Alliance"]="对于从赤脊山安全区进入危险沼泽地带的联盟旅行者来说，避难营是北部沼泽中为数不多能提供非敌对接触而非直接流血冲突的地方之一。",["faction:Horde"]="部落在斯通纳德的存在在很大程度上主导着这片沼泽，但这些隐居的幸存者保持着自己与世隔绝的生活方式，他们独善其身，不参与区域性的冲突。"},sec={{t="泥沼中的避风港",b="避难营隐藏在悲伤沼泽北部的山脉之下，与在附近水域游荡的野蛮部落形成了鲜明对比。这个小营地由粗糙的皮革棚屋搭建而成，并装饰着神秘的悬挂水晶，为那些拒绝放弃理智的被放逐的德拉诺幸存者提供了庇护所。在玛格图尔等长者的引导下，他们维持着一片脆弱而文明的聚居地，同时时刻警惕着敌对的荒野、原生掠食者，以及潜伏在他们领地之外那些堕落同胞的野蛮部落。"}},faq={{q="避难营里住着什么人？",a="避难营是德拉诺流亡者群体的家园——这些受苦难折磨的人形生物穿过传送门来到艾泽拉斯，并设法保存了他们的思想和文化，这与沼泽其他地方的野蛮部落截然不同。",al={"避难营居民","避难营里有谁","谁住在这里"}},{q="为什么这里的人是和平的，而沼泽里的其他部落却会攻击人？",a="这里的居民尽管经历了悲惨的身体变形和流离失所，但依然保持了理智和理性思维。虽然他们身处沼泽各处的受苦同胞因与世隔绝和创伤而丧失了心智，但避难营的居民团结一致，维护着他们的尊严。",al={"为什么他们友好","失落者友好","避难营敌对"}},{q="谁领导着避难营？",a="这个社区仰仗玛格图尔等受人尊敬的长者来提供领导和指导，引领他们在陌生的沼泽中求生。",al={"避难营领袖","玛格图尔","避难营酋长"}},{q="避难营位于哪里？",a="它隐藏在悲伤沼泽的北侧悬崖下，就在连接沼泽与赤脊山的山道以东。",al={"避难营位置","避难营在哪里","找到避难营"}}},fp="9,401,19.591.0,27.199.0,65.274.0,24.125.0,31.154.0"}
P.entries["subzone:hearthglen"] = {n="壁炉谷",s="壁炉谷坐落在西瘟疫之地的北部群山之中，是一处防守严密的定居点。在洛丹伦陷落期间，这里奇迹般地躲过了彻底的毁灭。如今，它坚固的石墙、塔楼和周边的农田已成为了狂热的血色十字军在北方的主要据点和训练场。",h="壁炉谷坐落在西瘟疫之地的北部群山之中，是一处防守严密的定居点。在洛丹伦陷落期间，这里奇迹般地躲过了彻底的毁灭。如今，它坚固的石墙、塔楼和周边的农田已成为了狂热的血色十字军在北方的主要据点和训练场。",kw={"andorhal","壁炉谷","玛登霍尔德","血色十字军","泰兰·弗丁","提里奥·弗丁","西瘟疫之地"},ang={["class:Paladin"]="壁炉谷曾是提里奥·弗丁的家园，而现在他的儿子在这里掌控着血色十字军。走在通往这里的路上，让人不禁感叹该骑士团分裂为狂热的血色十字军是多么悲惨的一件事。",["race:Undead"]="对于被遗忘者来说，壁炉谷是北方的一根致命芒刺。驻扎在这里的十字军对亡灵怀有绝对、炽热的仇恨，并积极进行巡逻，旨在铲除任何从Andorhal向北冒险的侦察兵。"},sec={{t="瘟疫之地中的堡垒",b="尽管邻近的Andorhal早已化为满目疮痍的废墟，但壁炉谷依然像是一座活着的洛丹伦城镇，拥有锯木厂、哨塔、马厩和还在运作的矿井。在历史上，壁炉谷由提里奥·弗丁领主在玛登霍尔德城堡管理，并以其在第二次战争期间的繁荣和坚固的防御而闻名。当亡灵瘟疫在第三次战争期间席卷洛丹伦时，阿尔萨斯·米奈希尔王子曾在此截获了受污染的谷物，与光明使者乌瑟尔一同净化了受感染的镇民，并击退了天灾军团的大规模围攻。正是通过那次孤注一掷的干预，壁炉谷宏伟的城墙才得以保存完好。"},{t="血色旗帜之下",b="在王国覆灭后，白银之手陷入了混乱，提里奥的儿子泰兰·弗丁放弃了该骑士团并加入了血色十字军。催生了血色十字军的悲痛与狂热很快便吞噬了这座要塞。如今的壁炉谷已是一座宗教极端主义的堡垒。血色十字军巡逻在通往这里的路上，把守着城墙，残酷地处决任何闯入他们领地的外来者，无论生者还是亡灵。大领主泰兰·弗丁在玛登霍尔德城堡进行统治，他是十字军在瘟疫之地进行不妥协战争的虔诚信徒。"}},faq={{q="为什么壁炉谷看起来比瘟疫之地的其他地方干净这么多？",a="壁炉谷在第三次战争中幸免于难，这要归功于阿尔萨斯王子和光明使者乌瑟尔。他们及时赶到，杀死了早期的瘟疫受害者并击退了天灾军团的大规模围攻。此后，血色十字军重兵把守了山口和山谷，不断清除任何入侵的天灾军团，从而在腐烂侵蚀城镇之前将其阻挡在外。",al={"壁炉谷为何完好","壁炉谷未被摧毁","壁炉谷现状"}},{q="现在是谁在控制壁炉谷？",a="血色十字军控制着壁炉谷。它由前任领主、著名圣骑士提里奥·弗丁之子，大领主泰兰·弗丁在玛登霍尔德城堡指挥。",al={"谁统治壁炉谷","壁炉谷领袖","谁负责壁炉谷"}},{q="壁炉谷对联盟或部落的访客友好吗？",a="不友好。血色十字军以极端的敌意和偏执看待所有外来者。部落成员被视为可怕的怪物，而未结盟的联盟旅行者则被斥为瘟疫携带者或异教徒，一旦发现即刻处决。",al={"我能去壁炉谷吗","壁炉谷是敌对的吗","壁炉谷安全吗"}},{q="提里奥·弗丁发生了什么事？",a="在第三次战争开始的前几年，提里奥因保护一位名为伊崔格的荣耀兽人而被联盟剥夺了头衔并逐出教门。流放荒野的提里奥被迫离开了壁炉谷，而玛登霍尔德的指挥权最终传给了他的儿子泰兰。",al={"提里奥在哪里","提里奥与壁炉谷的历史","为什么提里奥不在这里"}}},fp="10,343,23.652.0,24.567.0,74.349.0,34.165.0,53.253.0,33.273.0"}
P.entries["subzone:helm-s-bed-lake"] = {n="盔枕湖",s="盔枕湖是一片结冰的水域，坐落在丹莫罗东南部的群山之中。厚厚的冰层上有一个人工凿开的冰洞，为当地的登山者和旅行者提供了至关重要的淡水。然而，湖岸周边因出没的野生动物、不断逼近的穴居人以及敌对的黑铁矮人渗透者而变得险象环生。",h="盔枕湖是一片结冰的水域，坐落在丹莫罗东南部的群山之中。厚厚的冰层上有一个人工凿开的冰洞，为当地的登山者和旅行者提供了至关重要的淡水。然而，湖岸周边因出没的野生动物、不断逼近的穴居人以及敌对的黑铁矮人渗透者而变得险象环生。",kw={"黑铁矮人","丹莫罗","盔枕湖","冰洞","narm faulk","穴居人"},ang={["faction:Alliance"]="前往洛克莫丹的联盟侦察兵在此处必须保持警惕，因为向南的道路离黑铁矮人的凶猛伏击点靠得过近。",["race:Dwarf"]="对于铁炉堡的矮人来说，盔枕湖既是一个至关重要的淡水水源，也是一个令人恼火的安全漏洞，因为黑铁矮人破坏者和穴居人正不断向丹莫罗的核心地带深入。"},sec={{t="危险的湖岸",b="盔枕湖静静地躺在丹莫罗东南部厚厚的冬日冰层之下。当地的矮人们在冰层上凿开了一个缺口，以获取清澈的淡水。虽然穿越冰面尚算稳妥，但在岸边徘徊却变得越来越危险。野兽在湖岸边游荡，流离失所的穴居人在山脊上觅食，而一伙怀有敌意的黑铁矮人占领了水域南边的一座废弃小屋，疯狂伏击着每一个路过的旅人。"}},faq={{q="为什么冻结的湖中心有一个冰洞？",a="这个厚冰层上的缺口是当地矮人特意维护的，以便在丹莫罗零度以下的气候中能够持续获取未结冰的淡水。",al={"冰洞","水源获取","为什么冰层破裂"}},{q="盔枕湖附近潜伏着什么危险？",a="虽然湖面本身很坚实，但湖泊周边却充斥着掠食野兽和流窜的穴居人。在南面，一个敌对的黑铁矮人营地占据了一座旧建筑，并暴力驱赶任何靠近的人。",al={"盔枕湖的威胁","谁在袭击这里","附近的敌人"}},{q="Narm Faulk 是谁？",a="Narm Faulk 是一位不幸的矮人，他的尸体可以在盔枕湖的岸边找到，他是该地区敌对威胁和黑铁矮人渗透者突然激增的残酷受害者。",al={"narm faulk 的尸体","湖边的矮人尸体","盔枕湖的尸体"}},{q="黑铁矮人是正式占领了该湖泊吗？",a="他们并没有完全占领该湖泊，但一队武装人员占据了南边的一座废弃建筑，将其作为向丹莫罗中心地带发动小规模冲突的前哨阵地。",al={"湖边的黑铁矮人","黑铁矮人小屋"}}},fx={ba815d26={q="盔枕湖是什么地方？",a="盔枕湖是丹莫罗东南部一座小型、几乎完全冰封的湖泊。厚厚的冰层上留有一个洞口，以便取用新鲜饮用水。冰封的湖面本身提供了稳固的立足点，但湖泊周围的荒野远不那么宜人，遍布掠食者、游荡的穴居人和敌对的黑铁潜伏者。",al={"盔枕湖","盔枕湖在哪里","这是什么湖"}}},fp="15,328,23.514.0,59.157.0,41.227.0,18.193.0,56.188.0"}
P.entries["subzone:heroes-vigil"] = {n="英雄哨岗",s="英雄哨岗位于艾尔文森林东部的石碑湖中心岛屿上，是一片宁静而神圣的空地。它以名为“纪念之石”的纪念碑为中心，旨在缅怀那些在第一次战争中阵亡的人们。然而，如今这座圣地已被暴风城基本遗忘，并被危险的叛逃法师所占据。",h="英雄哨岗位于艾尔文森林东部的石碑湖中心岛屿上，是一片宁静而神圣的空地。它以名为“纪念之石”的纪念碑为中心，旨在缅怀那些在第一次战争中阵亡的人们。然而，如今这座圣地已被暴风城基本遗忘，并被危险的叛逃法师所占据。",kw={"艾尔文森林","亨兹·法奥克","英雄哨岗","流氓法师","石碑湖","纪念之石"},ang={["class:Mage"]="在这些神圣土地上驻扎的叛逃法师在没有奥术科学学院的约束或许可的情况下，练习危险且不受管制的法术。",["race:Human"]="对于暴风城的人类来说，这座神圣的石环令人痛苦地想起第一次战争的血腥代价，也提醒着人们王国如今未能保护好自己的遗产。"},sec={{t="一座被遗忘的纪念碑",b="英雄哨岗建于第一次战争后，以纪念之石为中心。这是一座刻有铭文的石环，旨在纪念在旧部落洗劫闪金镇及其周边山谷时惨遭屠杀的士兵和平民。虽然它曾被视为信仰与牺牲的神圣堡垒，但这座哨岗已逐渐淡出了暴风城现任统治者的视线，导致其神圣的土地杂草丛生，无人守护。"},{t="被叛逃者占据",b="由于王国没有在岛上驻扎守军，被放逐者们夺取了这座纪念碑。一群流氓法师现在控制着石碑湖和纪念碑所在地，他们远离肯瑞托和奥术科学学院的监管，在此练习狂野且缺乏约束的魔法。石碑附近留下的惨烈伤亡让这种亵渎行为显得更加令人痛心，其中包括亨兹·法奥克的遗体，这不禁让路人怀疑这座圣地是否还能重归宁静。"}},faq={{q="什么是英雄哨岗？",a="英雄哨岗是一座位于艾尔文森林东部石碑湖岛上的纪念碑。它由一个石环和一座纪念碑组成，旨在缅怀第一次战争中的阵亡者。",al={"英雄哨岗","什么是英雄哨岗","艾尔文森林岛屿圣地"}},{q="纪念之石是为了纪念什么？",a="纪念之石是为了缅怀在第一次战争期间，兽人部落洗劫闪金镇并蹂躏艾尔文森林东部时阵亡的平民和守卫者。",al={"纪念之石","纪念碑含义","什么是纪念之石"}},{q="谁控制着现在的英雄哨岗？",a="这座岛屿和哨岗已被敌对的流氓法师占据。这些流氓施法者游离于暴风城王国的法律和正统魔法机构的监管之外。",al={"谁在英雄哨岗","英雄哨岗的敌人","湖上的法师"}},{q="为什么暴风城会忽视这座哨岗？",a="随着瓦里安·乌瑞恩国王失踪，王国忙于应对内部纷争、强盗和怪物入侵，像英雄哨岗这样偏远的圣地已无人守护，并被摄政政府基本遗忘。",al={"为什么这里被废弃了","为什么暴风城遗忘了它","被遗忘的圣地"}},{q="亨兹·法奥克是谁？",a="亨兹·法奥克是一名矮人，他的遗体就躺在纪念碑附近。他在拯救朋友贾森·坦诺姆时被迪菲亚潜行者杀害。",al={"亨兹·法奥克的遗体","岛上的死者是谁"}}},fx={e301b338={q="英雄哨岗危险吗？",a="是的，对粗心的人来说尤其危险。石碑湖中的岛屿已完全落入流亡的邪恶法师和施法者手中，他们修习禁忌法术。任何人一靠近纪念碑，他们便会立刻发动攻击，使这处本应供人追思的宁静圣地变成了旅行者的致命陷阱。",al={"英雄哨岗安全吗","英雄哨岗危险吗","英雄哨岗敌对势力"}},c198f6a4={q="为什么叫英雄哨岗？",a="这里是为纪念第一次战争中阵亡的守卫者而建立的长久哨所和纪念地。中心矗立着纪念之石，用以缅怀那些在旧部落横扫艾尔文森林、洗劫闪金镇时惨遭杀害的士兵和平民。",al={"为何叫英雄哨岗","英雄哨岗名称含义","这里缅怀哪些英雄"}}},fp="13,356,20.458.0,20.488.0,22.195.0,47.190.0,33.201.0,38.225.0,19.144.0"}
P.entries["subzone:hetaera-s-clutch"] = {n="赫塔拉的巢穴",s="赫塔拉的巢穴是一座沉没的暗夜精灵神庙，原本用于供奉艾露恩，如今坐落在艾萨拉风暴海湾那波涛汹涌的海底深处。这座被淹没的遗迹曾经是一处神圣的祈祷之地，如今却被巢母赫塔拉孵化出的致命多头蛇所占据。潜入深海的冒险者们会发现，这些古老的石造建筑已被凶猛的水生掠食者所盘踞。",h="赫塔拉的巢穴是一座沉没的暗夜精灵神庙，原本用于供奉艾露恩，如今坐落在艾萨拉风暴海湾那波涛汹涌的海底深处。这座被淹没的遗迹曾经是一处神圣的祈祷之地，如今却被巢母赫塔拉孵化出的致命多头蛇所占据。潜入深海的冒险者们会发现，这些...",kw={"艾萨拉","风暴海湾","艾露恩","赫塔拉","赫塔拉的巢穴","多头蛇","沉没的神庙","艾露恩神庙"},ang={["class:Druid"]="探索风暴海湾深处的水生德鲁伊必须保持警惕，因为占据这座古老圣殿的多头蛇对入侵者极具敌意。",["race:NightElf"]="对于暗夜精灵来说，看到一座神圣的艾露恩圣殿被淹没，并沦为野生多头蛇的巢穴，是文明在大分裂中被撕裂的痛苦记忆。"},sec={{t="一座沉没的圣殿",b="在大分裂将古老的卡利姆多大陆撕裂之前，这座建筑曾是一座供奉月神艾露恩的宏伟神庙。它坠入风暴海湾的深处后，其石柱和神圣的大厅已经在海底沉寂了一万年。如今，一切神圣崇拜的迹象都已被潮汐吞噬，只留下这座纪念失落的卡多雷帝国的肃穆遗迹。"},{t="巢母的领地",b="这座沉没的圣殿如今有了更致命的身份，它成为了赫塔拉的巢穴。赫塔拉是一只巨大的多头蛇，常在附近的海域和岩石岛屿出没。它的无数后代，即赫塔拉的子嗣，潜伏在沉没神庙那破损的拱门和走廊中，攻击任何敢于潜入海湾的陆地生物。"}},faq={{q="赫塔拉的巢穴最初的建造目的是什么？",a="在沉入海底之前，这座建筑曾是一座宏伟的月神艾露恩神庙。它建于古老暗夜精灵帝国的鼎盛时期，随后在大分裂期间坠入海洋。",al={"什么是赫塔拉的巢穴","这座神庙原本是什么","赫塔拉的巢穴背景故事"}},{q="赫塔拉的巢穴位于哪里？",a="赫塔拉的巢穴位于风暴海湾的水下深处，在艾萨拉崎岖的南海岸附近。",al={"赫塔拉的巢穴在哪里","赫塔拉的巢穴位置","如何找到赫塔拉的巢穴"}},{q="赫塔拉是谁？",a="赫塔拉是一只凶猛的三头多头蛇，常在艾萨拉的海域游荡。虽然它的孩子们栖息在沉没的神庙中，但赫塔拉通常出现在巢穴以北的水域，或是在附近的近海岛屿上休憩。",al={"赫塔拉是谁","赫塔拉在哪里","什么是赫塔拉"}},{q="沉没的遗迹中栖息着哪些生物？",a="淹没的大厅里挤满了赫塔拉的后代，这些凶猛的水生多头蛇以守卫巢穴闻名，会攻击任何游得太近的入侵者。",al={"赫塔拉的巢穴里有什么怪物","什么生物住在赫塔拉的巢穴"}}},fp="16,357,19.389.0,25.356.0,47.240.0,34.108.0,15.238.0,43.152.0"}
P.entries["subzone:hidden-grove"] = {n="隐秘小林",s="隐秘小林坐落在冬泉谷东北部高耸悬崖后的隐蔽处，是一座与世隔绝的环形山盆地。这里曾经是北极兔平静的避风港，如今却已被领地意识极强的野生枭兽所占据。",h="隐秘小林坐落在冬泉谷东北部高耸悬崖后的隐蔽处，是一座与世隔绝的环形山盆地。这里曾经是北极兔平静的避风港，如今却已被领地意识极强的野生枭兽所占据。",kw={"陨坑","兔子","隐秘小林","枭兽","冬泉谷"},ang={["class:Druid"]="栖息在陨坑中的枭兽是野生、未驯化的自然变得极度充满防御性的阴沉缩影，对于平衡之道的修行者来说，这里有着深厚的精神意义。"},sec={{t="一处与世隔绝的避难所",b="隐秘小林隔绝了冬泉谷凛冽的狂风，形成了一座沉降的、覆盖着白雪的森林陨坑，从外围悬崖几乎无法进入。发现其隐秘边缘的旅者，要么需要冒着危险进行惊险的垂直下降，要么必须穿过东南侧山脊中隐藏的狭窄洞穴通道。虽然这片山谷曾长期是无害白兔们不受打扰的家园，但好斗的野生枭兽已经占据了这片林地，将这一天然的隐秘乐园变成了一处伏击不慎闯入者的陷阱。"}},faq={{q="如何进入隐秘小林？",a="进入小林最安全的路线是穿过周围悬崖墙东南侧面内隐藏的一处洞穴。虽然从理论上讲，可以从上方陡峭的悬崖边缘攀爬并跳下，但这样做有极高的致命坠落风险。",al={"如何进入隐秘小林","隐秘小林入口","洞穴在哪里"}},{q="隐秘小林里生活着什么生物？",a="陨坑中遍布着野生且充满敌意的枭兽，它们严密地守卫着这片与世隔绝的山谷。在枭兽迁入之前，这片林地曾因几乎完全由无害的白兔聚居而闻名，被誉为一片宁静的避风港。",al={"隐秘小林里有什么","隐秘小林怪物","这里居住着谁"}},{q="这座小林位于冬泉谷的什么位置？",a="隐秘小林位于冬泉谷的最东北角，完全被包裹在一处由高耸石崖形成的独立盆地中。",al={"隐秘小林位置","隐秘小林在哪里"}}},fp="12,228,20.519.0,37.262.0,40.222.0,44.136.0"}
P.entries["subzone:hidden-path"] = {n="秘道",s="秘道是一条隐蔽的山路，蜿蜒在杜隆塔尔试炼谷上方的岩架之间。对于渴望寻找神圣灵魂石地的萨满学徒来说，这是一场必经的试炼仪式，同时它也提供了一个俯瞰贫瘠之地崎岖边界的绝佳隐蔽据点。",h="秘道是一条隐蔽的山路，蜿蜒在杜隆塔尔试炼谷上方的岩架之间。对于渴望寻找神圣灵魂石地的萨满学徒来说，这是一场必经的试炼仪式，同时它也提供了一个俯瞰贫瘠之地崎岖边界的绝佳隐蔽据点。",kw={"贫瘠之地","杜隆塔尔","秘道","萨满","灵魂石地","试炼谷"},ang={["class:Shaman"]="秘道是你真正意义上的第一次身体与精神上的攀登，在你在灵魂石地与大地之灵沟通之前，考验着你的感知力。",["faction:Horde"]="虽然这对萨满来说是神圣的，但这条未设防的通道代表了试炼谷上方的一个安全盲点，值得警惕。"},sec={{t="神圣的攀登",b="秘道开凿在毗邻试炼谷的红色山峰之中，从峡谷底部很难发现它。年轻的萨满会被导师指引到这里，在前往灵魂石地与灵魂沟通之前，证明他们的感知力和纪律性。沿着小径的最高处前行，旅行者可以饱览向西延伸至贫瘠之地起伏草原的广阔全景。"},{t="战略上的易受攻击性",b="除了其精神上的重要性之外，这条小径还在环绕山谷的天然防御工事中切开了一个危险的缺口。沿途的一个低洼通道提供了一条通往棘齿城和奥格瑞玛道路的直接后门。由于它避开了常规的峡谷检查点，警惕的守军担心大胆的联盟渗透者可能会利用这条安静的小径直接溜进部落的主要试炼场。"}},faq={{q="秘道通往何处？",a="这条小径从试炼谷向上攀登，一直到达灵魂石地，这是一个萨满与元素沟通的神圣地点。它还沿着连接贫瘠之地和海岸线的山口蜿蜒延伸。",al={"秘道目的地","秘道通往哪里","秘道通向"}},{q="为什么这条小径对萨满很重要？",a="试炼谷的萨满学徒被要求找到这条隐蔽的小径，作为他们早期元素试炼的一部分。攀登这条小径可以让他们到达灵魂石地，并饮下与灵魂沟通所需的萨普塔。",al={"萨满试炼谷小径","灵魂石地小径","萨满任务小径"}},{q="敌人会利用秘道攻击试炼谷吗？",a="会。沿途的低洼缺口绕过了山谷常规的守卫入口。一支来自棘齿城或海岸的狡猾联盟突击部队理论上可以使用这条小径绕过部落侦察兵，在不被察觉的情况下进入训练场。",al={"秘道联盟入侵","试炼谷是否易受攻击","试炼谷后门"}},{q="在小径顶端可以看到什么？",a="在最高点，这条小径提供了一个清晰的、高处的视野，可以向西眺望贫瘠之地的广袤平原，以及杜隆塔尔红色峡谷的全景。",al={"秘道视野","秘道瞭望点"}}},fx={d2b4f0e1={q="什么是秘道？",a="秘道是一条隐蔽的山间小径，蜿蜒穿过杜隆塔尔试炼谷边缘的峭壁。它大多藏于视线之外，是一条通往灵魂石地的秘密通道。灵魂石地是一处圣地，新晋萨满会在那里与元素之灵交流。从高处的山脊望去，可以俯瞰一直延伸至贫瘠之地的崎岖边境。",al={"杜隆塔尔秘道","什么是秘道","秘道简介"}},["46af627a"]={q="为什么叫秘道？",a="这条路因隐蔽难寻而得名。它藏在环绕试炼谷的峭壁之间，并非显眼的大道或有标记的路线，而是穿过岩壁屏障的一条隐秘通路。按照传统，找到它是入门试炼的一部分，考验受训者的观察力，之后他们才能抵达灵魂石地。",al={"为何叫秘道","秘道名称含义","秘道名称由来"}},a83f5cf6={q="秘道安全吗？",a="这条路本身十分僻静，没有常驻定居点或怪物营地，但它的偏僻位置带来了战略隐患。由于小径下方有一处缺口，可无人看守地通往海岸、棘齿城，甚至北面的奥格瑞玛，这里形成了一处未设防的侧翼，联盟渗透者理论上可以由此潜入试炼谷。",al={"秘道安全吗","秘道危险吗","秘道的敌人"}}},fp="11,276,15.419.0,23.422.0,32.217.0,38.238.0,65.250.0,42.174.0"}
P.entries["subzone:high-rise"] = {n="High Rise",s="High Rise是雷霆崖中心台地的最顶层，也是这座牛头人主城的最高点。这里设有一个以公共篝火为中心的繁华露天剧场，周围聚集了经验丰富的工匠、武器商和烹饪大师。与较低的台地不同，这里完全依赖悬挂式绳桥和双足飞龙管理员站点进行通行。",h="High...",kw={"露天剧场","阿斯卡厨房","篝火","high rise","莫高雷","雷霆崖","双足飞龙管理员站点"},ang={["profession:Cooking"]="High Rise是阿斯卡厨房和著名烤肉大师的所在地，使其成为雷霆崖中在明火上磨练烹饪技能的首选之地。",["race:Tauren"]="作为主城的顶点，High Rise代表了各部族之间的团结，将猎人、萨满祭司和长者聚集在高耸的公共篝火旁。"},sec={{t="台地之巅",b="High Rise高居于雷霆崖核心台地的顶部，在莫高雷那片草海平原的高空之上迎接着开阔的风。作为联合部族的中心聚集点，这里以一个露天剧场和火坑为核心，市民们在此聆听重要的部族公告和决定。周围的帐篷和木制摊位入驻了知名的商人、军械库和烹饪训练师，包括阿斯卡厨房和山顶渔具店。虽然较低的台地通过巨大的木制升降梯与莫高雷的平原地面直接相连，但High Rise则保持高耸，主要通过双足飞龙管理员站点以及连接邻近长者高地和猎人高地的宽阔绳桥出入。"}},faq={{q="如何到达High Rise？",a="你可以通过下层通往的双足飞龙管理员站点到达High Rise，或者穿过连接长者高地和猎人高地的悬索桥。没有从莫高雷平原直达该台地的升降梯。",al={"如何前往high rise","high rise通行","登上high rise"}},{q="High Rise有哪些服务？",a="该台地以其贸易商和户外聚集地而闻名。著名的设施包括提供烹饪指导的阿斯卡厨房、提供钓鱼装备的山顶渔具店，以及怒蹄武器店和雷蹄枪械店等各类武器商。",al={"high rise训练师","high rise商店","high rise有什么"}},{q="High Rise上的露天剧场有什么用途？",a="露天剧场环绕着一座中心篝火，作为一个公共聚集区。在这里，牛头人聚集在开阔的天空下，聆听新闻、商讨部族事务，并见证在台地之巅发布的重要宣告。",al={"high rise篝火","high rise剧场","牛头人聚会场所"}}},fx={c9070a2e={q="什么是High Rise？",a="High Rise是雷霆崖中央台地的最高层。它高踞莫高雷的风蚀平原之上，是牛头人首都的政务与仪式中心。这里设有一座环绕中央篝火的露天圆形剧场、各类贸易商铺，以及通往猎人高地和长者高地的绳桥。",al={"什么是high rise","雷霆崖high rise","介绍一下high rise"}},b703b2f4={q="谁住在High Rise，或由谁管理？",a="High Rise是雷霆崖内牛头人领袖的驻地。凯恩·血蹄大酋长和长老议会在这处高地处理部族事务，民众可以聚集于此，聆听重要法令，见证关乎命运的决策。这里也住着备受尊敬的工匠、武器匠、厨师和渔夫，他们在中央区域周围经营摊位并居住。",al={"谁领导high rise","谁负责管理high rise","high rise的居民"}},["8703b6d5"]={q="High Rise危险吗？",a="不危险。High Rise一片祥和，并由雷霆崖警觉的崖卫严密守护。你可能遇到的唯一真正危险，是从台地边缘或狭窄绳桥上失足坠落。",al={"high rise安全吗","high rise的危险","high rise的威胁"}},e2f731cc={q="为什么叫High Rise？",a="雷霆崖的台地分为多层，High Rise位于中央高原的顶端。它高于下层和中层高地，因此得名，意为城市中央支柱的最高层。",al={"为何叫high rise","high rise名称含义","high rise的由来"}}},fp="9,350,18.713.0,31.224.0,41.258.0,51.248.0"}
P.entries["subzone:high-seat"] = {n="High Seat",s="High Seat是铁炉堡宏伟的王座大厅，坐落于平民区和Great Forge之间。国王麦格尼·铜须就在这个高耸的厅堂中，与他的皇家顾问和历史学家们一起统领着矮人王国。大厅内还有一条通往Old Ironforge古老深处的封闭通道。",h="High Seat是铁炉堡宏伟的王座大厅，坐落于平民区和Great Forge之间。国王麦格尼·铜须就在这个高耸的厅堂中，与他的皇家顾问和历史学家们一起统领着矮人王国。大厅内还有一条通往Old...",kw={"阿克瑟努斯","巴林·红石","铜须","high seat","铁炉堡","麦格尼","王座"},ang={["faction:Alliance"]="作为矮人权力的中心，该大厅对联盟的后勤和高层战略至关重要，汇聚了使节、顾问和颁布皇室法令。",["race:Dwarf"]="High Seat象征着卡兹莫丹主权的不断传承，国王麦格尼·铜须在此继续以钢铁般的意志领导着他的人民。"},sec={{t="矮人统治的中心",b="High Seat俯瞰着充满活力、熙熙攘攘的铁炉堡，是卡兹莫丹王国的权力中枢。在这间穹顶大厅里，国王麦格尼·铜须接见请愿者，与顾问们召开会议，并指挥联盟北方堡垒的防御工作。在皇家历史学家阿克瑟努斯和参议员巴林·红石等皇室显贵的簇拥下，High Seat依然是铜须一族权威和矮人坚韧精神的象征，在艾泽拉斯动荡不安的时代屹立不倒。"},{t="通往Old Ironforge的门户",b="在王座大厅雄伟的石质装潢后面，是一扇沉重的大门，通向Old Ironforge阴暗广阔的区域。这些下层的废墟代表了在铁炉堡围绕Great Forge重新规划之前，矮人们最初开凿的祖先大厅。这扇大门对普通行人关闭并严加看守，提醒着访客们，在这座现代都城的基石之下，还沉睡着一段悠久而庞大的历史。"}},faq={{q="谁在High Seat统治着这里？",a="国王麦格尼·铜须在High Seat的王座上统治着铁炉堡。他指挥铜须氏族的事务，倾听臣民的诉求，并协调与大联盟之间的军事和外交事宜。",al={"谁坐在王座上","铁炉堡国王","麦格尼王座大厅"}},{q="High Seat在铁炉堡的什么位置？",a="该大厅位于铁炉堡的中心位置，直接与平民区和Great Forge之间的外环相连，方便到访的市民和使节进出。",al={"high seat在哪里","寻找high seat","王座大厅位置"}},{q="王座大厅后方的封闭走廊是什么？",a="High Seat后方的大拱门通往Old Ironforge，那是位于这座现代山中之城正下方的巨大祖先遗迹。通往这些下层通道的路径目前仍处于限制状态。",al={"麦格尼身后的门","old ironforge之门","high seat地下室"}},{q="还有谁会在这里为国王提供建议？",a="国王麦格尼身边有许多杰出的矮人人物，包括负责守护铜须王朝记录与遗物的皇家历史学家阿克瑟努斯，以及参议员巴林·红石。",al={"high seat npc","麦格尼的顾问"}}},fx={dcfee083={q="什么是High Seat？",a="High Seat也称High Throne，是铁炉堡王国宏伟的王座大厅。它位于这座山城的正中心，紧邻Great Forge。这座壮丽的石厅是矮人君主处理朝政、接见使者、听取来自卡兹莫丹各地臣民请愿的地方。",al={"什么是high seat","铁炉堡王座大厅","铁炉堡high seat"}},e56e0189={q="High Seat危险吗？",a="只要你是联盟的朋友，就不危险。这里是矮人政务的中心，由国王的亲卫和经验丰富的矮人卫兵严密把守。除非入侵的部落军队攻破铁炉堡深处的山地防线，否则在国王庇护下到访的人无须担心这座大厅中的危险。",al={"high seat安全吗","high seat的危险","high seat内的威胁"}}},fp="9,328,21.515.0,24.426.0,29.218.0,44.179.0,59.205.0,45.184.0"}
P.entries["subzone:high-wilderness"] = {n="高原荒野",s="高原荒野是一片广袤、未被驯服的原始森林，覆盖了菲拉斯西部的大部分地区。它东临沃丹提斯河，西接被遗忘的海岸，在参天的翡翠树冠下庇护着种类繁多的野生动物、游荡的树妖和危险的野兽。",h="高原荒野是一片广袤、未被驯服的原始森林，覆盖了菲拉斯西部的大部分地区。它东临沃丹提斯河，西接被遗忘的海岸，在参天的翡翠树冠下庇护着种类繁多的野生动物、游荡的树妖和危险的野兽。",kw={"菲拉斯","被遗忘的海岸","高原荒野","角鹰兽","树妖","沃丹提斯河","雪人"},ang={["class:Druid"]="高原荒野中古老的树妖和充满活力的野生动物展现了卡利姆多原始的自然力量，未受东方大陆文明的影响。",["class:Hunter"]="高原荒野中密集分布着凶猛的熊、狼和野生角鹰兽，使其成为追踪和驯服强大野兽的绝佳试炼场。"},sec={{t="原始树冠",b="高原荒野横跨菲拉斯西部，代表了卡利姆多南部最典型的荒野之地。茂密的枝叶和巨大的树木遮蔽了大部分天空，形成了一片生机勃勃的广阔区域，狼、熊、角鹰兽和雪人在此栖息。古老的树妖在树根间徘徊，而好斗的食人魔氏族则在阴凉的林间空地上建立了据点。在这片广袤的绿色地带中穿行需要保持警惕，因为茂密的灌木丛中既隐藏着自然界的捕食者，也潜伏着原始的危险。"}},faq={{q="高原荒野位于何处？",a="高原荒野涵盖了菲拉斯西部广阔的林地。它位于沃丹提斯河以西，一直延伸到与被遗忘的海岸接壤的悬崖和海岸线。",al={"高原荒野位置","高原荒野在哪里","高原荒野 菲拉斯"}},{q="什么生物在高原荒野中出没？",a="这片森林里栖息着大量的熊、狼、角鹰兽和野生的雪人。除了自然界的野兽，旅行者还经常会在树冠下遇到游荡的树妖和好斗的食人魔。",al={"高原荒野野生动物","高原荒野生物","菲拉斯野兽"}}},fp="15,303,21.521.0,37.188.0,40.211.0"}
P.entries["subzone:highperch"] = {n="风巢",s="风巢是位于千针石林西部的一处高地，高耸在峡谷底部之上。它以野生双足飞龙和风骑士的主要筑巢地而闻名。在这片风吹日晒的岩架之间，凶猛的群落守护着它们的幼崽。",h="风巢是位于千针石林西部的一处高地，高耸在峡谷底部之上。它以野生双足飞龙和风骑士的主要筑巢地而闻名。在这片风吹日晒的岩架之间，凶猛的群落守护着它们的幼崽。",kw={"巢穴","风巢","窝","波卡·雨山","千针石林","风骑士","双足飞龙"},ang={["class:Hunter"]="这座广阔的巢穴让经验丰富的猎人们有机会近距离观察野生双足飞龙在其自然、未受驯化的栖息地中狩猎并守护巢穴。",["faction:Horde"]="筑巢于风巢的风骑士，与搭载部落成员穿越卡利姆多的高贵飞行坐骑同属一脉，这使得这处保护区对部落勇士而言是一个令人心生敬畏的地方。"},sec={{t="双足飞龙巢穴",b="风巢从峡谷底部陡然升起，是卡利姆多本地双足飞龙的天然避难所。这处高地为它们提供了抵御掠食者的天然屏障，也是它们在千针石林上空进行狩猎飞行的理想起飞点。在这些山岩深处，双足飞龙群落在警惕的族长和配偶的保护下繁衍生息，守护着它们的巢穴。这些野兽会凶猛地捍卫自己的领地，抵御任何敢于攀爬到它们高空领域的不速之客。"},{t="高处的避难所",b="虽然对外界怀有敌意，但这些高耸的悬崖偶尔也会吸引那些愿意冒险攀登的旅行者和猎人。牛头人斥候波卡·雨山被困在这处危险的高地上，需要帮助才能抵达白沙岗哨。对于穿越峡谷的冒险者来说，攀登通往风巢的坡道意味着要面对无数锋利的爪子和带有剧毒的尾巴。"}},faq={{q="风巢里生活着什么生物？",a="风巢中只居住着野生的双足飞龙和风骑士。你会遇到保护巢穴的族长、配偶以及在悬崖上方盘旋并保卫巢穴的成年双足飞龙。",al={"风巢野兽","风巢有什么","风巢怪物"}},{q="风巢在哪里？",a="风巢位于千针石林西部，可以通过从峡谷底部南壁向上延伸的蜿蜒坡道抵达。",al={"风巢位置","如何找到风巢","风巢在哪里"}},{q="为什么风巢对部落如此重要？",a="双足飞龙，也就是风骑士，是部落的重要飞行坐骑，它们在第三次战争期间与兽人结成了同盟。像风巢这样的天然栖息地代表了这些忠诚野兽的野生血统和繁茂种群。",al={"部落与风巢的联系","双足飞龙与部落","为什么兽人关心风巢"}},{q="谁是波卡·雨山？",a="波卡·雨山是一位牛头人斥候，他被困在风巢致命的双足飞龙巢穴之中。他需要护送前往白沙岗哨。",al={"波卡·雨山","风巢的牛头人","谁被困在了风巢"}}},fx={["0cf6e9b4"]={q="什么是风巢？",a="风巢是一座高耸的台地和筑巢地，位于千针石林西部峡谷上方。它是当地自豪的野生双足飞龙最重要的天然栖息地之一，遍布它们的巢穴和翱翔的群落。",al={"什么是风巢","风巢信息","风巢简介"}},a95be4dc={q="风巢发生过什么事？",a="几代以来，野生双足飞龙一直在这处悬崖庇护所的高处筑巢。牛头人斥候波卡·雨山被困在峭壁间，正寻求帮助返回白沙岗哨。",al={"风巢历史","这里发生过什么","风巢往事"}},b4e36f31={q="风巢危险吗？",a="是的。筑巢于峭壁各处的野生双足飞龙会凶猛地护卫自己的幼崽和领地。任何从峡谷底部爬上来、靠近它们巢穴的闯入者，都会遭到配偶和强壮的雄性首领俯冲攻击。",al={"风巢危险吗","风巢的危险","风巢危险"}}},fp="9,260,20.471.0,23.391.0,33.166.0,27.138.0,42.232.0,28.131.0"}
P.entries["subzone:hillsbrad-fields"] = {n="希尔斯布莱德农场",s="希尔斯布莱德农场包含了位于希尔斯布莱德丘陵西部的耕地和希尔斯布莱德的乡间定居点。作为洛丹伦旧地为数不多幸存的人类社区之一，这里的居民拒绝向天灾军团投降，也没有加入狂热的血色十字军，而现在的农夫和民兵正面临来自附近塔伦米尔的被遗忘者的持续攻击。",h="希尔斯布莱德农场包含了位于希尔斯布莱德丘陵西部的耕地和希尔斯布莱德的乡间定居点。作为洛丹伦旧地为数不多幸存的人类社区之一，这里的居民拒绝向天灾军团投降，也没有加入狂热的血色十字军，而现在的农夫和民兵正面临来自附近塔伦米尔...",kw={"希尔斯布莱德之战","达萨利亚","盖兹农夫","雷农夫","希尔斯布莱德","希尔斯布莱德农场","伯恩赛德镇长","南海镇","塔伦米尔","沃林坦"},ang={["faction:Alliance"]="希尔斯布莱德农场是重要的粮仓，也是洛丹伦不屈精神的深刻象征，理应受到保护以抵御被遗忘者的灭绝式攻击。",["faction:Horde"]="高级执行官达萨利亚要求系统性地拆除希尔斯布莱德的农场和民兵力量，以巩固被遗忘者在南方的边境。"},sec={{t="洛丹伦的坚韧堡垒",b="希尔斯布莱德农场横跨达隆山和碧玉矿洞之间的果园、南瓜地与牧场，为南海镇和幸存的联盟抵抗力量提供了必要的物资。当洛丹伦的大部分土地沦陷于亡灵瘟疫时，希尔斯布莱德的人民却坚持了下来，自豪地保留了他们覆灭王国的皇家战袍和纹章。在伯恩赛德镇长和希尔斯布莱德议会的领导下，这个城镇作为一个独立的民政机构，正处于不断的围攻之中。当地铁匠沃林坦和他的学徒们为民众装备武器，确保每一位农夫和劳动者都做好了保卫家园的准备。"},{t="亡灵进军的前线",b="这些肥沃的农场是高级执行官达萨利亚和盘踞在塔伦米尔的被遗忘者军队的主要目标。幽暗城将这个繁荣的人类定居点视为其南部侧翼的生存威胁，因此策划了针对该社区基础设施的持续袭击，目标包括农作物、牲畜、议员以及平民农夫。作为回应，希尔斯布莱德的守卫者们组建了一支坚毅的民兵队伍。雷农夫和盖兹农夫等当地地主不再是手无寸铁的农民，他们组织伏击并奋力抗击亡灵的入侵，以保卫他们的家园。"}},faq={{q="为什么这里还有活着的农民在耕种？",a="希尔斯布莱德和邻近的南海镇是洛丹伦极少数在第三次战争中未被天灾军团彻底摧毁的定居点。与其他逃往南方或加入狂热的血色十字军的幸存者不同，这些居民选择留下重建生活并坚守家园。",al={"为什么人类会留在希尔斯布莱德","谁居住在希尔斯布莱德农场","农夫们还活着吗"}},{q="谁统治着这个城镇和农场？",a="这个城镇和农田由伯恩赛德镇长管辖，并在霍拉斯·白骏文书和希尔斯布莱德议会的协助下从当地市政厅进行治理。雷农夫和盖兹农夫等地主管理着周边的庄园，而当地铁匠沃林坦则负责为城镇卫队提供装备。",al={"谁领导希尔斯布莱德","希尔斯布莱德的领导层","希尔斯布莱德镇长"}},{q="为什么被遗忘者要攻击这些农场？",a="塔伦米尔的高级执行官达萨利亚认为希尔斯布莱德是联盟在被遗忘者边境的一个危险立足点。幽暗城的命令要求士兵通过摧毁粮食储备、屠宰牲畜和消灭城镇领导人来切断人类的补给线，从而为被遗忘者在丘陵地区的统治扫清障碍。",al={"为什么被遗忘者攻击希尔斯布莱德","希尔斯布莱德之战的原因","塔伦米尔的袭击"}},{q="第二次战争期间希尔斯布莱德发生了什么？",a="在第二次战争期间，大酋长Orgrim Doomhammer下令对希尔斯布莱德发动毁灭性攻击，旨在通过Show of Force挫败人类的士气，同时在南海镇地区集结部落军队。希尔斯布莱德在一场残酷的武力展示中被摧毁，但联盟随后将兽人赶走，城镇也因此得以重建。",al={"希尔斯布莱德与第二次战争","兽人摧毁了希尔斯布莱德","希尔斯布莱德农场的历史"}}},fx={["253bd91d"]={q="什么是希尔斯布莱德农场？",a="希尔斯布莱德农场是希尔斯布莱德镇周边的肥沃农业腹地，位于西部山麓。广阔的果园、南瓜地和牧场不仅为当地居民提供食物，也供应附近的南海镇港口以及该地区各处的联盟哨站。与洛丹伦北部的大部分地区不同，这里的农田基本完好地躲过了天灾军团的侵袭，成为少数仍有活着的人类农夫在已覆灭王国旗帜下耕种作物的地方之一。",al={"什么是希尔斯布莱德农场","希尔斯布莱德农场概况","希尔斯布莱德农场简介"}},c30a4664={q="希尔斯布莱德农场危险吗？",a="危险至极，具体要看你是什么人。希尔斯布莱德的活人类与塔伦米尔的被遗忘者驻军正在此地交战，农场目前是主要战场。农夫、农民和城镇卫兵全副武装、组织严密，并时刻警惕亡灵袭击者，还会对闯入者发动凶狠的伏击。对于奉高级执行官达萨利亚之命前来的被遗忘者勇士而言，攻下这些设防的农庄是一场血腥而激烈的战役。",al={"希尔斯布莱德农场安全吗","希尔斯布莱德农场危险吗","希尔斯布莱德农场有多危险"}}},fp="16,358,30.630.0,32.592.0,47.312.0,35.283.0,41.315.0,49.299.0"}
P.entries["subzone:hive-ashi"] = {n="亚什虫巢",s="亚什虫巢是一座庞大的其拉虫群聚居地，占据了希利苏斯北部的沙地。作为该地区三大主要虫巢之一，其蜿蜒的隧道和高耸的土丘中翻涌着无数充满敌意的工虫、守卫和毒刺虫。",h="亚什虫巢是一座庞大的其拉虫群聚居地，占据了希利苏斯北部的沙地。作为该地区三大主要虫巢之一，其蜿蜒的隧道和高耸的土丘中翻涌着无数充满敌意的工虫、守卫和毒刺虫。",kw={"塞纳里奥","亚什虫巢","其拉虫","希利苏斯","虫群之柱"},ang={["class:Druid"]="当塞纳里奥议会注视着希利苏斯被腐蚀的沙地时，德鲁伊们被召集起来研究并压制从亚什虫巢涌出的昆虫威胁，以免其吞噬自然生态系统。",["faction:Alliance"]="在希利苏斯行动的联盟特工协助收集有关亚什虫巢的情报，以确保这些具有侵略性的虫群不会威胁到整个卡利姆多南部的邻近领土。"},sec={{t="北部土丘",b="亚什虫巢坐落于希利苏斯北部，是重新涌现的其拉虫群的主要虫巢建筑群。其甲壳质的尖塔在沙丘中划出了一块独特的领地，派遣着觅食的工虫和剧毒的守卫向南和向东前往虫群之柱。任何试图了解沙漠荒原中那股奇异且协调的智慧的人，最终都会发现自己的道路直接通向这些土丘下危险且嗡嗡作响的隧道。"},{t="被揭露的威胁",b="驻扎在希利苏斯各处的塞纳里奥侦察兵密切监视着亚什虫巢，委托勇敢的战斗者去削减它们的数量，并从虫巢深处取回侦察报告。在亚什记录下的符文和协调行为表明，这些看起来毫无思想的昆虫共享着一种令人毛骨悚然的单一意志。随着它们的数量不断膨胀，虫巢正威胁着要完全蔓延出希利苏斯北部，这使得消灭其虫群成为了那些关注南部边界的人的首要任务。"}},faq={{q="什么是亚什虫巢？",a="亚什虫巢是一座活跃的其拉虫群建筑群，位于希利苏斯北部。这里栖息着数以千计穴居的昆虫类生物，它们将沙漠的沙地挖掘成相互连接的隧道和土丘。",al={"亚什虫巢","亚什虫巢位置","什么是亚什"}},{q="亚什虫巢里生活着什么样的其拉虫？",a="这个聚居地居住着分工明确的其拉虫阶级，包括亚什工虫、沙行者、剧毒毒刺虫以及重甲守卫。",al={"亚什怪物","亚什虫巢生物","这里有什么其拉虫"}},{q="亚什虫巢与虫群之柱有什么关系？",a="在附近的虫群之柱周围蜂拥而至的其拉虫源自亚什虫巢，代表了该虫巢的虫群正向沙漠地面进行扩张。",al={"虫群之柱的联系","亚什和虫群之柱"}},{q="为什么塞纳里奥侦察兵要研究这个虫巢？",a="塞纳里奥议会试图了解其拉虫的迅速复苏以及它们的虫巢是如何协调运作的。侦察兵们监视着亚什，以破译奇怪的符文并追踪虫巢扩张的速度。",al={"为什么侦察亚什虫巢","亚什虫巢侦察报告"}}},fp="9,240,18.472.0,18.495.0,18.204.0,41.151.0,49.155.0,43.200.0"}
P.entries["subzone:hive-regal"] = {n="雷戈虫巢",s="雷戈虫巢是位于希利苏斯南部的巨大异种虫虫巢。作为统治这片干旱荒漠的三大主要虫群聚落之一，这里挤满了富有侵略性的异种虫阶级，随时威胁着要吞没周围的沙漠。",h="雷戈虫巢是位于希利苏斯南部的巨大异种虫虫巢。作为统治这片干旱荒漠的三大主要虫群聚落之一，这里挤满了富有侵略性的异种虫阶级，随时威胁着要吞没周围的沙漠。",kw={"掘地虫","虫巢","雷戈虫巢","雷戈","异种虫","希利苏斯","奴隶主","喷火者"},ang={["class:Druid"]="塞纳里奥议会密切监视着雷戈虫巢的扩张，他们认为这种具有侵略性的异种虫腐化是对沙漠生态系统的一种生存威胁。"},sec={{t="南部虫巢",b="雷戈虫巢横跨希利苏斯南部，是卡利姆多境内异种虫活动最集中的区域之一。这里高耸的树脂尖塔和地下的洞穴网络中，涌动着危险的虫群，从剧毒的喷火者、掘地虫到掠食性的奴隶主，应有尽有。该虫巢是一个协调统一的巢穴，积极防守其边界，并从任何不幸靠近其领地的旅行者身上收割有机物质。"},{t="地下网络",b="在红色的沙土之下，雷戈虫巢那迷宫般的通道深入地底。入口附近和深处隧道中刻画的奇异符文表明，引导这些虫群的并非仅仅是野性的本能，而是某种有组织的智慧。研究异种虫威胁的学者和斥候们认为，雷戈虫巢及其姊妹虫巢，是希利苏斯荒漠之下正在酝酿的一股更庞大且正在崛起的势力的一部分。"}},faq={{q="雷戈虫巢在哪里？",a="雷戈虫巢位于希利苏斯南部，以其高耸的异种虫土丘和被虫群侵蚀的红色沙地为标志。",al={"雷戈虫巢位置","雷戈虫巢在哪里","寻找雷戈虫巢"}},{q="雷戈虫巢里生活着什么样的生物？",a="巢穴中栖息着各种带有敌意的异种虫品种，包括掘地虫、伏击者、喷火者和奴隶主，它们会积极地守卫虫巢。",al={"雷戈虫巢怪物","雷戈虫巢内部","雷戈虫巢敌人"}},{q="为什么研究人员对雷戈虫巢感兴趣？",a="斥候和学者们研究该虫巢是为了解读墙上那些奇异的交流符文，并监测异种虫群在整个卡利姆多南部日益严重的威胁。",al={"为什么要前往雷戈虫巢","雷戈虫巢研究","雷戈虫巢符文"}},{q="雷戈虫巢与其他希利苏斯的虫巢有何不同？",a="雷戈虫巢是希利苏斯三大主要虫群聚落中最南端的一个，其余两个是亚什虫巢和佐拉虫巢。每个聚落都拥有专门的异种虫阶级，尽管它们似乎都怀揣着同一个阴险的目的。",al={"希利苏斯的其它虫巢","三大虫巢","虫巢之间的区别"}}},fp="10,250,17.465.0,20.428.0,28.126.0,43.151.0,45.176.0,60.214.0"}
P.entries["subzone:hive-zora"] = {n="佐拉虫巢",s="佐拉虫巢是希利苏斯干旱荒原上占据主导地位的三大其拉虫人巢穴之一。这座充满活力的地下巢穴位于沙漠西缘，无数好战的虫族阶级在其中爬行，侍奉着庞大的虫群。",h="佐拉虫巢是希利苏斯干旱荒原上占据主导地位的三大其拉虫人巢穴之一。这座充满活力的地下巢穴位于沙漠西缘，无数好战的虫族阶级在其中爬行，侍奉着庞大的虫群。",kw={"塞纳里奥议会","巢穴姐妹","佐拉虫巢","掠夺者","其拉虫人","希利苏斯","守望者"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，佐拉虫巢代表了一种可怕的非自然激增，破坏了沙漠荒野的自然平衡。",["profession:Mining"]="像佐拉虫巢这样的其拉虫人巢穴，其扭曲的隧道和外围区域经常会暴露出珍贵的富瑟银矿脉和稀有的被软泥覆盖的矿物沉积。"},sec={{t="西部虫群",b="佐拉虫巢从希利苏斯西部的荒凉沙丘中崛起，是虫族活动繁忙的中心。高大、多孔的石质尖塔和土丘标志着其拉掘地虫挖掘出的深邃地下隧道的入口。守望者和掠夺者不知疲倦地巡逻着外围，而挖掘阶级和巢穴姐妹则在下方的深处繁衍。对于塞纳里奥议会以及其他监视沙漠的侦察兵来说，这座巢穴代表了虫族威胁正在稳步夺回这片古老边境的可怕迹象。"}},faq={{q="佐拉虫巢是什么？",a="佐拉虫巢是位于希利苏斯西部的一个活跃的其拉虫人巢穴建筑群。它由地表巨大的虫族尖塔组成，并与蔓延的地下隧道相连。",al={"佐拉虫巢","佐拉虫巢是什么","希利苏斯佐拉虫巢"}},{q="佐拉虫巢里居住着什么生物？",a="该巢穴完全被其拉虫群占据。巢穴中栖息着不同的阶级，包括在外巡逻的佐拉虫巢守望者、防御地面的重装掠夺者、挖掘大地的掘地虫，以及有毒的巢穴姐妹。",al={"佐拉虫巢怪物","佐拉虫巢里有什么怪物","谁住在佐拉虫巢"}},{q="为什么塞纳里奥议会要调查这个巢穴？",a="驻扎在希利苏斯的侦察兵和研究人员观察佐拉虫巢，以追踪其拉虫人威胁的增长和动向。使者们研究它们的行为，破译它们的符文，并在虫群淹没该地区之前削减它们不断扩张的数量。",al={"为什么侦察佐拉虫巢","塞纳里奥议会佐拉虫巢"}},{q="佐拉虫巢与其他希利苏斯的巢穴有何不同？",a="佐拉虫巢是三大巢穴中最西边的一个，亚什虫巢坐落在北部，雷戈虫巢占据南部。每个巢穴都由各自不同的虫群运作，尽管它们都有着同样的捕食本能，想要在沙漠中扩张。",al={"希利苏斯其他巢穴","巢穴之间的区别","雷戈虫巢亚什虫巢"}}},fp="9,243,17.539.0,18.174.0,33.238.0,51.254.0,59.245.0"}
P.entries["subzone:horizon-scout"] = {n="Horizon Scout",s="Horizon Scout是一艘沉没的船只，静静地躺在艾萨拉南海岸外的废墟海岸海底。尽管船长仍然被困在岸上，但几名船员仍被困在淹没的船体中，靠着一种奥术水下呼吸附魔在波涛之下维持生命。",h="Horizon Scout是一艘沉没的船只，静静地躺在艾萨拉南海岸外的废墟海岸海底。尽管船长仍然被困在岸上，但几名船员仍被困在淹没的船体中，靠着一种奥术水下呼吸附魔在波涛之下维持生命。",kw={"艾萨拉沉船","azsharite","horizon scout","roland geardabbler","废墟海岸","spitelash","vanessa beltis"},ang={["faction:Alliance"]="Horizon Scout代表了一次进入艾萨拉危险水域的灾难性的联盟海上探险，使其船员分成了岸上和水墓两个部分。",["race:Gnome"]="全体幸存船员的呼吸都归功于Roland Geardabbler，他不停施放的法术将深海阻挡在被淹没的船体之外。"},sec={{t="困于海底",b="Horizon Scout躺在废墟海岸险恶的浅滩波涛之下，在艾萨拉嶙峋的海岸外遭遇了惨烈的结局。虽然Vanessa Beltis船长设法到达了附近半岛的陆地上，但部分船员随船体沉没。奇迹般的是，内部的幸存者并没有溺亡；一名叫Roland Geardabbler的侏儒维持着一个持续的水下呼吸魔法气泡，将他们保存在残骸中。在充满敌意的海洋捕食者和捕食性的纳迦环伺下，剩余的水手们在昏暗的前舱内等待着，无法自行浮出水面。"},{t="纳迦伏击",b="船上的证据暗示了其毁灭背后的邪恶势力。在前楼梯间里有一小块原始的Azsharite，这是一种这些海岸特有的神秘矿物。在废墟海岸周围水域徘徊的Spitelash纳迦很可能袭击了Horizon Scout，以掠夺探险队携带的任何文物或资源，并将船只拖入水中，以确保没有幸存者能带着海岸的秘密或宝藏逃脱。"}},faq={{q="Horizon Scout位于何处？",a="Horizon Scout的残骸沉没在废墟海岸的海湾底部，位于艾萨拉南海岸外。",al={"horizon scout位置","horizon scout在哪里","寻找horizon scout"}},{q="船员如何在水下存活？",a="一位名叫Roland Geardabbler的侏儒工程师或法师在沉没的船体内持续引导着一种水下呼吸光环，让被困的船员在持续的可呼吸空气中存活下来。",al={"他们如何呼吸","船员为什么没死","roland geardabbler光环"}},{q="Vanessa Beltis船长是谁？",a="Vanessa Beltis船长是Horizon Scout的指挥官。与困在船体里的水手不同，她设法与其他几名被困的幸存者一起到达了艾萨拉南半岛的安全地带。",al={"vanessa beltis","horizon scout船长","船长"}},{q="是什么导致Horizon Scout沉没的？",a="该船几乎肯定是被当地的Spitelash纳迦伏击并击沉的。下层甲板上的一块原始Azsharite表明，纳迦发起攻击是为了夺取探险队收集的任何矿产财富或文物。",al={"horizon scout为什么沉没","是谁击沉了horizon scout","船发生了什么事"}}},fp="13,293,26.598.0,15.449.0,35.136.0,39.204.0,30.201.0,38.229.0"}
P.entries["subzone:howling-vale"] = {n="狼嚎谷",s="狼嚎谷坐落在灰谷中北部，临近费伍德森林的边界，是一处被被称为恐惧狼人这一野蛮异界狼兽所占据的阴暗幽谷。在它深处的洞穴中，隐藏着古老的梅丽桑德里斯神殿，这是一处受艾露恩祝福的遗迹，与卡利姆多狼人诅咒的悲剧起源有着密切的联系。",h="狼嚎谷坐落在灰谷中北部，临近费伍德森林的边界，是一处被被称为恐惧狼人这一野蛮异界狼兽所占据的阴暗幽谷。在它深处的洞穴中，隐藏着古老的梅丽桑德里斯神殿，这是一处受艾露恩祝福的遗迹，与卡利姆多狼人诅咒的悲剧起源有着密切的联系...",kw={"灰谷狼人","狼嚎谷","梅丽桑德里斯","艾露恩之镰","恐惧狼人","维琳德·星歌"},ang={["class:Druid"]="在洞穴中游荡的野蛮狼人是德鲁伊变形术的黑暗镜像，这些野蛮的野兽在灰谷的出现对于哨兵们来说依然是一个谜。",["race:NightElf"]="梅丽桑德里斯神殿的亵渎是卡多雷的一道伤疤，这个原本属于艾露恩的神圣之地如今却被野蛮的狼人所占据。"},sec={{t="一处闹鬼的避难所",b="在通往费伍德森林的道路以北，灰谷那宁静而威严的景象让位于令人毛骨悚然的掠食者嗥叫声。这座峡谷中不仅有古老的树木，还盘踞着被腐化的恐惧狼人狼王和凶猛的野生动物。在峡谷中心，坐落着一座供奉着古老暗夜精灵女祭司梅丽桑德里斯的洞穴。虽然这座神殿曾是人们静心祈祷的圣地，但它那宁静的大厅如今已破败不堪，被一群起源不明、令驻守附近的哨兵们困惑不已的野蛮狼人所亵渎。"},{t="镰刀与星歌的遗产",b="《梅丽桑德里斯之书》揭示了神殿中近期发生的事件：暗夜精灵维琳德·星歌获得了一件宿命般的神器——艾露恩之镰。她试图引导这股力量对抗恶魔，却无意中将狼人释放到了周边的森林中，使得这座峡谷被她所召唤出的野兽所困扰。"}},faq={{q="为什么它被称为狼嚎谷？",a="这座峡谷因占据此地的恐惧狼人那令人胆寒的叫声而得名。它们持续不断的、回荡的嗥叫声在峡谷和洞穴中反复回响，掩盖了灰谷林冠中自然的声响。",al={"狼嚎谷得名原因","狼嚎谷的名字起源","为什么有嗥叫声"}},{q="什么是梅丽桑德里斯神殿？",a="这是一座古老的暗夜精灵圣殿，致力于供奉艾露恩，并以梅丽桑德里斯的名字命名。存放在那里的《梅丽桑德里斯之书》记录了可能解释为何狼人会来到这里的事件。",al={"梅丽桑德里斯神殿","梅丽桑德里斯是谁"}},{q="这里的狼人是从哪里来的？",a="它们的起源让哨兵们感到困惑。哨兵梅丽瑞亚·霜影派遣联盟侦察兵前往神殿研究《梅丽桑德里斯之书》，该书的历史记录掌握着这些狼人来历的关键。",al={"狼人是如何来到灰谷的","恐惧狼人的起源","为什么狼人在灰谷"}},{q="什么是《梅丽桑德里斯之书》？",a="这是一部神圣的历史文献，安放在洞穴深处的神殿中。哨兵梅丽瑞亚·霜影派遣联盟侦察兵去研读这本书，以了解困扰森林的神秘狼人的起源。",al={"梅丽桑德里斯之书","狼嚎谷中的书"}}},fx={["8276f532"]={q="什么是狼嚎谷？",a="狼嚎谷是灰谷中北部一处阴暗的洼地和洞穴，位于费伍德森林边界的西南方。它曾是暗夜精灵的宁静圣地，中心是古老的梅尔·坦德里斯神殿。如今，神圣的树林已陷入黑暗，被凶暴的野兽和非自然的恐怖生物占据。",al={"什么是狼嚎谷","狼嚎谷信息","狼嚎谷简介"}},aa8b1a44={q="狼嚎谷发生过什么事？",a="很久以前，梅尔·坦德里斯神殿在此建起，作为伊露恩的圣地。近来，暗夜精灵维琳德·星歌得到了月神镰刀；其令人不安的力量释放后，凶残的狼人涌现并占领了山谷，玷污了这片曾经神圣的土地。",al={"狼嚎谷历史","狼嚎谷发生过什么","狼嚎谷的历史"}},["17e899ac"]={q="谁住在狼嚎谷？",a="这里已不再有文明种族居住。山谷落入了泰罗狼狼人手中。这群凶残的狼形野兽在首领的统治下徘徊于废弃的神殿周围。他们还与敌对的鬼爪狼，以及被灰谷北部蔓延的腐化扭曲、陷入疯狂且枯萎的古树共同盘踞在这片洼地中。",al={"谁住在狼嚎谷","狼嚎谷的居民","谁控制着狼嚎谷"}},af0435d5={q="狼嚎谷为何化为废墟？",a="凶暴的狼人到来后，山谷便沦为废墟。暗夜精灵看守者不是被杀害，就是被迫离开，梅尔·坦德里斯神殿因此年久失修、破败不堪。随着周围森林被疯狂与蔓延的腐化侵蚀，这片圣林逐渐沦为凶残掠食野兽的巢穴。",al={"狼嚎谷为何化为废墟","狼嚎谷为何被遗弃","梅尔·坦德里斯神殿为何毁坏"}},["2daeb8a3"]={q="狼嚎谷危险吗？",a="这里极其危险。山谷中遍布嗜血的特罗沃尔夫狼人，它们成群协作狩猎，还有凶猛的头狼。更糟的是，守护这片土地的古老树妖已经枯萎发狂，任何人若不小心靠近神殿遗迹，都会遭到它们攻击。",al={"狼嚎谷危险吗","狼嚎谷有多危险","狼嚎谷的威胁"}}},fp="12,330,15.486.0,34.328.1,34.221.0,35.179.0,36.196.1,33.222.0"}
P.entries["subzone:hunter-rise"] = {n="猎人高地",s="猎人高地是构成雷霆崖城市的众多高地台地之一，位于中央台地的正南侧。它是牛头人战士、猎人、追踪者和剥皮师的主要训练和聚集地。在其饱经风霜的平台上，年轻的勇士们磨练着他们的武艺，为战斗做准备。",h="猎人高地是构成雷霆崖城市的众多高地台地之一，位于中央台地的正南侧。它是牛头人战士、猎人、追踪者和剥皮师的主要训练和聚集地。在其饱经风霜的平台上，年轻的勇士们磨练着他们的武艺，为战斗做准备。",kw={"战场军官","猎人高地","猎人大厅","莫高雷","雷霆崖","追踪者"},ang={["class:Hunter"]="对于年轻的牛头人猎人来说，这座高地就是你在主城中天职的核心所在，它提供训练、宠物补给，并有追踪大师提供指导。",["class:Warrior"]="猎人高地的场地提供练习假人、战斗导师以及渴望在部落持续的防御战中考验你实力的战场军官。"},sec={{t="勇士集会",b="猎人高地通过摇晃的绳桥与邻近的台地相连，致力于弘扬牛头人的尚武传统。这里以猎人大厅为核心，经验丰富的神射手、追踪者和战士们在这里将他们的纪律传授给年轻一代。在大厅周围设有配有练习假人、武器架和剥皮台的练习场，使这里成为了那些以长矛、弓箭和兽皮为生的人们的热闹中心。"},{t="武道职责与防御",b="除了在莫高雷的平原上狩猎野兽外，猎人高地的居民还协助确保雷霆崖及整个部落的防御。驻扎在高地上的战场军官招募身经百战的战士，以响应号召，对抗联盟在各个交战战场上的入侵。对于任何誓言保卫族群的人来说，这里仍然是一个重要的集结地。"}},faq={{q="猎人高地位于何处？",a="猎人高地位于雷霆崖的南侧。通过连接城市下层台地和High Rise台地的木制绳桥即可到达。",al={"猎人高地位置","猎人高地所在","如何前往猎人高地"}},{q="谁居住在猎人高地并在此训练？",a="这座台地是牛头人猎人、战士、追踪者、陷阱制作者和制皮师的家园。除了职业和专业训练师外，部落的战场军官也驻扎于此，为阵营的战争招募战士。",al={"谁在猎人高地","猎人高地训练师","猎人高地有什么"}},{q="什么是猎人大厅？",a="猎人大厅是高地上主要的木屋，也是经验丰富的猎人和战士们聚集的地方。它既是军械库、学校，也是学习追踪、射击和近战技巧的人们的家园。",al={"猎人大厅","雷霆崖猎人小屋","雷霆崖猎人大厅"}},{q="联盟成员可以访问猎人高地吗？",a="不可以。雷霆崖是部落的主要主城之一，猎人高地有经验丰富的牛头人勇士把守。任何试图穿过桥梁的联盟冒险者都会立即受到城市卫兵的攻击。",al={"联盟在猎人高地","联盟可以去猎人高地吗"}}},fx={fb082e53={q="什么是猎人高地？",al={"什么是猎人高地","猎人高地介绍","猎人高地传说"}},["328a4c07"]={q="猎人高地危险吗？",a="对部落成员和友善访客而言，猎人高地十分安全。这里秩序井然，是老兵、武器大师和经验丰富的追踪者汇聚之处。然而，对部落的敌人或胆敢登上台地的联盟成员来说，这里则是致命之地：警觉的哨兵和技艺娴熟的战士严加守卫，随时准备一发现入侵者便将其击倒。",al={"猎人高地安全吗","猎人高地的危险","猎人高地危险吗"}},["5f696981"]={q="为什么叫猎人高地？",a="这座台地因其核心使命而得名：尊崇并精进牛头人的古老狩猎传统。这里是著名的猎人大厅所在地，追踪大师、制皮师和神射手在此传授平原生活所必需的生存技能，确保狩猎始终融入族人的生存方式与精神之中。",al={"猎人高地为何得名","猎人高地名称由来","猎人高地是如何得名的"}}},fp="11,329,23.447.0,24.382.0,29.178.0,36.217.0,26.218.0,46.203.0"}
P.entries["subzone:hushed-bank"] = {n="寂静河岸",s="寂静河岸是暮色森林阴影笼罩的西侧河岸，与分隔森林和西部荒野的河流接壤。它从靠近三角路口的交汇处向南延伸至荆棘谷，是一片寂静却危险重重的林地，潜伏着徘徊的野兽，并笼罩在黑暗的谜团之中。",h="寂静河岸是暮色森林阴影笼罩的西侧河岸，与分隔森林和西部荒野的河流接壤。它从靠近三角路口的交汇处向南延伸至荆棘谷，是一片寂静却危险重重的林地，潜伏着徘徊的野兽，并笼罩在黑暗的谜团之中。",kw={"廊桥","暮色森林","寂静河岸","拉尔斯","河岸","斯温·约根","西部荒野"},ang={["class:Hunter"]="潜伏在河岸茂密枝叶中的狼和蜘蛛为那些探索森林黑暗区域的追踪者提供了典型的荒野野兽。",["faction:Alliance"]="河岸上的廊桥是连接西部荒野农田和暮色森林受困前哨站的关键战略通道。"},sec={{t="河畔前线",b="寂静河岸沿着暮色森林和西部荒野之间的河流边界延伸，标志着从开阔平原和阳光明媚的农场到弥漫着非自然暮色的过渡。木制廊桥横跨于此，为离开这片阴森森林向西行进的旅人提供了通道。浓密的灌木丛和蔓延的迷雾笼罩着河岸，巨大的蜘蛛和饥饿的森林狼在那些偏离大道的粗心旅客身边徘徊。"},{t="流放者与隐士",b="在河岸的北端附近，一些孤独的灵魂在远离夜色镇猜忌目光的地方过着贫瘠的生活。斯温·约根和他的同伴拉尔斯在这片茂密的森林中扎营，注视着林线，心中怀揣着与困扰该地区的黑暗悲剧相关的苦涩怨恨。他们与世隔绝的避难所是这片荒凉海岸上仅存的少数人类生存迹象之一。"}},faq={{q="寂静河岸位于哪里？",a="寂静河岸构成了暮色森林的西侧边缘，沿着将森林与西部荒野隔开的河流延伸。它从北部的三角路口附近的岔路口一直向下延伸至通往荆棘谷的南部边界。",al={"寂静河岸位置","寂静河岸在哪里","寂静河岸地图"}},{q="什么连接着寂静河岸和西部荒野？",a="一座木制廊桥跨越了寂静河岸的河流，使行人和车辆能够安全地往返于西部荒野阳光明媚的平原和暮色森林被诅咒的阴霾之间。",al={"通往西部荒野的桥梁","西部荒野桥梁暮色森林","如何过河去西部荒野"}},{q="谁住在寂静河岸沿线？",a="斯温·约根和他的同伴拉尔斯在河岸的北角建立了一个营地。两人都像隐士一样与世隔绝地生活，因为他们逃离了摧毁斯温附近农场的恐怖事件。",al={"寂静河岸营地","谁在寂静河岸","寂静河岸npc"}},{q="在这片海岸线上能发现什么威胁？",a="寂静河岸栖息着凶猛的林地野兽，包括巨大的蛛网森林蜘蛛和掠食性的暮色狼，它们捕食丛林中移动的一切生物。",al={"寂静河岸怪物","寂静河岸的危险","寂静河岸魔物"}}},fp="11,301,26.442.0,20.405.1,33.232.0,42.177.0,32.190.0,44.166.0"}
P.entries["subzone:ice-thistle-hills"] = {n="冰蓟岭",s="冰蓟岭是一处覆盖着白雪的高地，位于地精前哨站永望镇的东南部。该区域被一个崎岖的洞穴系统所占据，凶猛的冰蓟雪人宣称这里是它们的领地，这威胁到了任何偏离主路的旅行者。",h="冰蓟岭是一处覆盖着白雪的高地，位于地精前哨站永望镇的东南部。该区域被一个崎岖的洞穴系统所占据，凶猛的冰蓟雪人宣称这里是它们的领地，这威胁到了任何偏离主路的旅行者。",kw={"永望镇","冰蓟岭","冰蓟雪人","冰盖草","原始雪人角","厚雪人毛皮","冬泉谷","雪人洞穴"},ang={["profession:Herbalism"]="围绕在丘陵周围的冰冻斜坡是采集冰盖草等耐寒植物的最佳场所，在洞穴入口附近偶尔也能发现稀有的花朵。",["profession:Mining"]="钻入山丘的黑暗洞穴是一个危险但回报丰厚的地方，老练的矿工可以在这里寻找由雪人群守护的丰富瑟银矿脉。"},sec={{t="白毛之穴",b="冰蓟岭从冬泉谷中央的积雪中陡然升起，是山谷中极具攻击性的冰蓟雪人的主要狩猎场和筑巢地。这些庞大的野兽以深入岩壁的巨大洞穴为中心，在岩石斜坡和蜿蜒的隧道中徘徊。由于离永望镇很近，这些雪人对地精的商业活动以及来访的探矿者造成了持续的骚扰和危险，因此探矿者经常委托勇敢的猎人去猎杀这些野兽，以获取它们珍贵的厚实毛皮和原始尖角。"}},faq={{q="冰蓟岭位于哪里？",a="冰蓟岭位于冬泉谷中部，永望镇地精贸易站的东南方。",al={"冰蓟岭位置","冰蓟岭在哪里","雪人洞穴位置"}},{q="这里生活着什么生物？",a="斜坡和丘陵洞穴中几乎只居住着冰蓟雪人，它们是长着白色皮毛的怪物，会极具攻击性地保卫自己的领地。",al={"冰蓟怪物","冰蓟岭有什么","雪人类型"}},{q="为什么冒险者要在冰蓟岭狩猎？",a="以永望镇为基地的旅行者和商人们经常雇佣冒险者来收集冰蓟雪人的厚实毛皮和原始尖角，这些材料在寒冷的山谷中是制作工艺品和生存装备的珍贵原料。",al={"为什么要杀雪人","冬泉谷雪人毛皮","冰蓟任务"}},{q="在丘陵周围可以采集到什么资源？",a="户外的斜坡上生长着冰盖草等稀有的高山草药，而雪人洞穴的深处则蕴藏着丰富的矿藏，包括瑟银矿脉。",al={"冰蓟草药","冰蓟洞穴采矿"}}},fp="17,255,18.572.0,40.116.0,25.157.0,49.211.0,48.164.0"}
P.entries["subzone:iceflow-lake"] = {n="涌冰湖",s="涌冰湖是一片寒冷、部分结冰的水域，位于丹莫罗西部，烈酒村正北。尽管有着无情的严寒，当地的矮人仍会在冰层上凿开冰洞，以获取淡水和鱼类。湖中心的雪覆盖岛屿上有好斗的冬狼及其首领，也就是Timber在徘徊。",h="涌冰湖是一片寒冷、部分结冰的水域，位于丹莫罗西部，烈酒村正北。尽管有着无情的严寒，当地的矮人仍会在冰层上凿开冰洞，以获取淡水和鱼类。湖中心的雪覆盖岛屿上有好斗的冬狼及其首领，也就是Timber在徘徊。",kw={"烈酒村","丹莫罗","结冰的湖泊","冰钓","涌冰湖","帕克斯顿·甘特","timber"},ang={["class:Hunter"]="湖泊的雪岸和中心岛屿是耐寒冬季野兽的主要追踪地，尤其是那头可怕的座狼首领，Timber。",["race:Dwarf"]="对于烈酒村的登山者来说，涌冰湖既是至关重要的淡水生命线，也是一种持续的威胁，因为他们需要时刻警惕穿过冰面的掠食性狼群。"},sec={{t="冰封深处与岛屿掠食者",b="涌冰湖横跨丹莫罗西部，就在烈酒村外，常年与卡兹莫丹严酷的气候作斗争。厚厚的冰层不断在湖面蔓延，迫使帕克斯顿·甘特等当地居民定期清理出冰洞，以进行冰钓和获取饮用水。虽然岸边能提供补给，但湖中心升起的岛屿却远没有那么友好。一群凶猛的野狼将这些冰丘变成了它们的领地，由那头臭名昭著、凶残的灰狼Timber统治。"}},faq={{q="为什么结冰的湖面上有一个开口的洞？",a="丹莫罗刺骨的寒冷将湖面冻得结结实实，所以附近烈酒村的矮人们特意开辟了一块没有冰的地方。这个洞口提供了未结冰的饮用水，也为当地渔民提供了一个垂钓的地点。",al={"冰洞","为什么冰层破裂","烈酒村钓鱼点"}},{q="帕克斯顿·甘特是谁？",a="帕克斯顿·甘特是一位矮人渔夫兼钓鱼训练师，可以在涌冰湖边找到。他帮助旅行者学习如何在丹莫罗钓鱼。",al={"帕克斯顿·甘特","涌冰湖的矮人","湖泊矮人"}},{q="湖中的岛屿上有什么威胁？",a="中心岛屿上到处都是饥饿的冬狼，其首领是一头凶猛的座狼，名叫Timber。试图穿过冰面到达湖中心的旅行者经常会遭到狼群的伏击。",al={"timber","湖中的狼","丹莫罗岛屿狼群"}}},fx={["26667757"]={q="什么是涌冰湖？",a="涌冰湖是一片中等大小的冰封水域，位于丹莫罗西部，就在烈酒村外。山地的严寒高海拔使湖水常年封冻在厚冰之下，只有当地矮人为捕鱼和取用淡水而维护的一处冰洞例外。湖心的岛屿上盘踞着凶猛的捕食者，因此这里既是重要的本地资源，也是旅人穿越雪峰时必须谨慎通过的险地。",al={"什么是涌冰湖","丹莫罗涌冰湖","涌冰湖在哪里"}},d98fd8f9={q="涌冰湖危险吗？",a="是的，穿越涌冰湖风险很大。湖冰足够厚实，可以在上面行走，但湖心突起的大岛上栖息着一群凶残贪婪的冬狼，由可怕的座狼“木材”率领。任何人若不留意周围便踏上冰面，都可能引来这些饥饿捕食者的注意。",al={"涌冰湖危险吗","涌冰湖的危险","涌冰湖的威胁"}}},fp="12,361,34.523.0,45.245.0,21.131.0,40.220.0"}
P.entries["subzone:infectis-scar"] = {n="魔刃之痕",s="魔刃之痕是一道深邃、非自然的裂隙，刻在考林路口附近的东瘟疫之地的凋零大地之上。与自然的峡谷不同，这道大地的伤口是在一把被诅咒的符文之刃撞击矮人盾牌而破碎时，由死灵之力撕裂开来的。裂隙底部腐烂的瘟疫至今仍是天灾军团黑暗巫术的有力见证。",h="魔刃之痕是一道深邃、非自然的裂隙，刻在考林路口附近的东瘟疫之地的凋零大地之上。与自然的峡谷不同，这道大地的伤口是在一把被诅咒的符文之刃撞击矮人盾牌而破碎时，由死灵之力撕裂开来的。裂隙底部腐烂的瘟疫至今仍是天灾军团黑暗巫术...",kw={"裂隙","考林路口","达隆郡","魔刃之痕","marduk blackpool","瘟疫之痕","符文剑"},ang={["class:Paladin"]="这道裂隙散发着死灵巫术的腐蚀性残渣，展示了被诅咒的符文在脱离使用者后，会对大地造成多么严重的亵渎。",["race:Dwarf"]="这道伤痕是矮人坚韧不拔的纪念碑：它之所以会被刻下，仅仅是因为一位无名矮人队长的盾牌在面对死亡骑士的黑暗符文之刃时坚守住阵地，震碎了那被诅咒的钢铁。"},sec={{t="黑暗魔法的伤痕",b="虽然像瘟疫之痕这样邻近的峡谷起源于被瘟疫毒化的自然地形，但魔刃之痕却是完全人为的。它是在第三次战争期间，考林路口附近的激烈冲突中产生的。当臭名昭著的死亡骑士Marduk Blackpool与一位坚定的矮人队长交战时，Marduk那把被诅咒的符文剑在队长的盾牌上撞得粉碎。Marduk丢弃了断掉的武器，只留下了剑柄，但断裂的符文之刃深深地陷入了土壤之中。它那邪恶的附魔猛烈地撕开了地壳，创造了今天盘踞在瘟疫之地、不断腐烂的锯齿状裂隙。"}},faq={{q="魔刃之痕是如何形成的？",a="它是在考林路口附近的一场战斗中形成的，当时死亡骑士Marduk Blackpool的符文剑撞在了一位矮人队长的盾牌上而破碎。当破碎的刀刃撞击地面时，其黑暗魔法钻入大地深处，撕裂出了一道巨大的裂痕。",al={"魔刃之痕起源","魔刃之痕如何发生","谁制造了魔刃之痕"}},{q="它与瘟疫之痕有什么不同？",a="瘟疫之痕原本是一道被天灾军团的瘟疫所腐蚀的天然峡谷。而魔刃之痕并非自然存在；它完全是由从Marduk Blackpool破碎的符文之刃中泄露出的恶意巫术轰击而成的。",al={"魔刃之痕与瘟疫之痕的区别","瘟疫之痕比较"}},{q="Marduk Blackpool是谁？",a="Marduk Blackpool，被称为“黑色者”，是效忠于天灾军团的一名死亡骑士，他参与了洛丹伦各地的屠杀，包括对达隆郡的突袭以及考林路口周围的冲突。",al={"marduk blackpool","marduk是谁"}},{q="那把剑现在在哪里？",a="破碎的符文剑的刀刃沉入了它所创造的裂隙底部，而Marduk Blackpool在冲突后只带走了剑柄。",al={"符文之刃位置","刀刃在哪里"}}},fp="13,383,21.624.0,33.262.0,44.251.0,25.211.0,23.155.0"}
P.entries["subzone:iris-lake"] = {n="伊瑞斯湖",s="伊瑞斯湖是一片位于灰谷中北部、阿斯特兰纳以东的受污染水域。它曾经清澈见底，如今却因费伍德森林渗透出的恶魔腐蚀而变成了令人作呕的黄绿色，敌对的沼泽兽在湖岸边徘徊游荡。",h="伊瑞斯湖是一片位于灰谷中北部、阿斯特兰纳以东的受污染水域。它曾经清澈见底，如今却因费伍德森林渗透出的恶魔腐蚀而变成了令人作呕的黄绿色，敌对的沼泽兽在湖岸边徘徊游荡。",kw={"灰谷","沼泽兽","月神之泪","费伍德森林腐蚀","伊瑞斯湖","莎尔蒂恩"},ang={["class:Druid"]="扭曲的沼泽兽和死气沉沉的受污染水域证明了如果置之不理，恶魔能量会对自然造成毁灭性的打击。",["race:NightElf"]="伊瑞斯湖是一个令人心碎的例子，展示了威胁着灰谷的蔓延性腐蚀，但从其受污染的岸边回收艾露恩之泪为净化森林带来了一线希望。"},sec={{t="被玷污的避难所",b="伊瑞斯湖坐落在阿斯特兰纳和莎尔蒂恩照料的月井之间，它严酷地提醒着人们第三次战争所造成的创伤。从费伍德森林的高处向南蔓延的邪能已经毒害了整个盆地，使其曾经清澈的水域变成了恶臭、病态的黄绿色泥沼。这种腐蚀扭曲了当地的植物和水元素，催生出好斗的沼泽兽，它们会猛烈攻击任何靠近的旅行者。"},{t="艾露恩之泪",b="尽管湖水受到严重污染，但过去神圣的遗迹仍残存在湖岸边。人们有时能在泥泞的岸边找到被称为“艾露恩之泪”的稀有结晶石。莎尔蒂恩等坚守精灵传统的守护者们正在寻找这些圣石，以帮助净化受污染的月井，并抵御恶魔腐蚀在灰谷的蔓延。"}},faq={{q="为什么伊瑞斯湖的水是绿色且浑浊的？",a="伊瑞斯湖受到了从邻近的费伍德森林蔓延而下的恶魔腐蚀的影响。黑暗魔法污染了地下水，将湖泊变成了一潭黄绿色的死水，并将附近的野生动物扭曲成了好斗的怪物。",al={"为什么伊瑞斯湖是绿色的","伊瑞斯湖水","为什么伊瑞斯湖被污染了"}},{q="伊瑞斯湖周围游荡着什么生物？",a="湖泊及其岸边到处都是受腐蚀的沼泽兽。这些植物和泥土元素受到邪能的侵蚀而变得疯狂，会猛烈攻击任何靠近水边的人。",al={"伊瑞斯湖怪物","伊瑞斯湖生物","伊瑞斯湖有什么攻击性生物"}},{q="什么是艾露恩之泪？",a="艾露恩之泪是在伊瑞斯湖岸边发现的神圣发光蓝色宝石。暗夜精灵的祭司和守护者利用其神圣本质进行净化仪式，主要用于净化受腐蚀的月井。",al={"艾露恩之泪","什么是艾露恩之泪"}},{q="伊瑞斯湖在哪里？",a="伊瑞斯湖位于灰谷的中北部。它位于暗夜精灵定居点阿斯特兰纳的正东方，莎尔蒂恩的月井以西。",al={"伊瑞斯湖在哪里","伊瑞斯湖位置","如何前往伊瑞斯湖"}}},fx={["8ae92a66"]={q="什么是伊瑞斯湖？",a="伊瑞斯湖是一片遭到腐化的水域，位于灰谷中北部，阿斯特兰纳以东、莎尔蒂恩的月亮井以西。这座湖曾是古老暗夜精灵林地中宁静而纯净的一隅，如今却受到从费伍德森林蔓延而来的邪恶污染，湖水变成了浑浊的黄绿色泥沼。",al={"什么是伊瑞斯湖","伊瑞斯湖传说","伊瑞斯湖简介"}},["4294757e"]={q="伊瑞斯湖发生了什么？",a="伊瑞斯湖遭到了从费伍德森林向南渗透的恶魔邪秽侵害。弥漫的腐化污染了曾经纯净的湖水，也扭曲了当地的动植物，将昔日神圣的自然憩所变成了腐朽而危险的沼泽。",al={"伊瑞斯湖历史","这里发生了什么","伊瑞斯湖如何遭到腐化"}},b432431a={q="伊瑞斯湖危险吗？",a="是的，伊瑞斯湖相当危险。除了污秽的毒水，扭曲的沼泽兽也在岸边和浅水处徘徊。这些遭到腐化的植物生物极具攻击性，会袭击任何为寻找稀有草药或艾露恩之泪而靠近湖水的旅人。",al={"伊瑞斯湖的危险","这里安全吗","伊瑞斯湖的威胁"}}},fp="9,251,16.450.0,20.376.0,46.237.0,37.183.0,23.211.0,27.149.0"}
P.entries["subzone:ironband-s-compound"] = {n="铁环营地",s="铁环营地是一座防御严密的哨站，隐藏在丹莫罗东部盔枕湖以南的雪山之中。这里曾是探矿者斯特吉·铁环的家，如今已被充满敌意的黑铁矮人占领，他们会攻击任何过于靠近的冒险者。",h="铁环营地是一座防御严密的哨站，隐藏在丹莫罗东部盔枕湖以南的雪山之中。这里曾是探矿者斯特吉·铁环的家，如今已被充满敌意的黑铁矮人占领，他们会攻击任何过于靠近的冒险者。",kw={"黑铁矮人","丹莫罗","矮人","盔枕湖","铁环营地","铁炉堡","斯特吉·铁环"},ang={["class:Warrior"]="铁炉堡的老兵训练师会派遣渴望成长的战士来到这里，通过援助阵亡的战友并搜集黑铁矮人存在的证据来证明自己的实力。",["race:Dwarf"]="对于铜须矮人来说，看到背信弃义的黑铁矮人在丹莫罗境内扎根，不仅是一种直接的侮辱，更是对其家园持续存在的威胁。"},sec={{t="沦陷于黑铁之手",b="这个位于盔枕湖以南的营地最初由斯特吉·铁环建立，曾是丹莫罗冰雪荒野中的一个补给站。但在黑铁渗透者深入铜须领地并夺取了此地之后，情况便发生了改变。现在，营地里满是怀有敌意的矮人，这里成了威胁旅行者和附近定居点的敌方前进基地，而位置就在铁炉堡的眼皮底下。"},{t="对铁炉堡的威胁",b="一个防御严密的黑铁矮人营地出现在丹莫罗境内，这是严重的挑衅行为。铁炉堡始终密切监视着该营地，派遣经验丰富的战士去回收阵亡斥候的尸体，并获取至关重要的情报，以证实黑铁矮人对这座山中王国的威胁程度。"}},faq={{q="谁最初建造了铁环营地？",a="该哨站最初由斯特吉·铁环居住和使用，后来敌对势力将他赶走并占领了此地。",al={"谁建造了这个营地","斯特吉·铁环","谁拥有铁环营地"}},{q="现在是谁控制着铁环营地？",a="这个营地被一群充满敌意的黑铁矮人占领，他们会毫不犹豫地攻击任何接近的流浪者或铁炉堡巡逻队。",al={"谁在这里","这里有什么敌人","丹莫罗的黑铁矮人"}},{q="铁环营地在哪里？",a="你可以在丹莫罗东部的雪山中找到它，就在盔枕湖的正南方。",al={"铁环营地在哪里","如何找到铁环营地","铁环位置"}},{q="为什么这个营地对铁炉堡的领袖们如此重要？",a="敌对氏族在如此靠近矮人首都的地方建立防御基地，是令人震惊的安全漏洞。铁炉堡当局派遣战士前往此处，搜集黑铁矮人渗透的确凿证据。",al={"为什么要在意这个营地","铁炉堡的反应","黑铁矮人威胁"}}},fx={["18d4f4e7"]={q="什么是铁环营地？",a="铁环营地是一处设有防御工事的营地，位于丹莫罗东部、盔枕湖以南。这里最初是矮人斯图吉·铁环驻守的前哨站，最近却被一伙敌对的黑铁矮人攻占并占据。",al={"什么是铁环营地","丹莫罗铁环营地","介绍一下铁环营地"}},ea846983={q="铁环营地发生了什么？",a="这处偏远前哨站原本由斯图吉·铁环和平驻守，后来遭到潜入的黑铁矮人猛烈突袭并夺取。入侵者驱逐了合法驻守者，并在丹莫罗境内直接建立起一处稳固的集结地，令铁炉堡当局深感不安。",al={"铁环营地的历史","铁环营地发生了什么","铁环营地如何失守"}},be9cbc3a={q="铁环营地为什么被遗弃了？",a="这处前哨站并非单纯被遗弃，而是遭到了暴力夺取。黑铁矮人潜伏者发动突然袭击，迫使斯图吉·铁环和他的盟友撤离，矮人营地就此变成了戒备森严的敌方据点。",al={"铁环营地为何被遗弃","铁环营地是否已成废墟","斯图吉·铁环怎么了"}},c49e4d1f={q="铁环营地危险吗？",a="独自旅行者在此处境极其危险。驻扎于此的黑铁矮人敌意明显、武装精良，会袭击任何靠近营地的人，以守住他们在丹莫罗的据点。",al={"铁环营地危险吗","铁环营地的威胁","可以去铁环营地吗"}},["8089f1d9"]={q="为什么叫铁环营地？",a="这座营地以矮人斯图吉·铁环命名。他最初建立并驻守此地，直到敌对的黑铁势力将其夺走。",al={"铁环营地为何得名","铁环是谁","铁环营地名称由来"}}},fp="19,261,24.428.0,21.297.0,41.128.0,37.133.0,37.96.0,55.201.0"}
P.entries["subzone:ironband-s-excavation-site"] = {n="铁环挖掘场",s="铁环挖掘场是一处位于洛克莫丹东南部的大型矮人挖掘点，就在洛克湖以南、旅行者营地西南方。在勘察员基恩萨·铁环的领导下，由于充满攻击性且反复无常的穴居人占领了战壕，考古工作被迫突然中断。",h="铁环挖掘场是一处位于洛克莫丹东南部的大型矮人挖掘点，就在洛克湖以南、旅行者营地西南方。在勘察员基恩萨·铁环的领导下，由于充满攻击性且反复无常的穴居人占领了战壕，考古工作被迫突然中断。",kw={"挖掘场","挖掘点","探险者协会","铁环","洛克莫丹","勘察员基恩萨·铁环","穴居人"},ang={["profession:Mining"]="采石场和露天矿坑展示了典型的矮人重型挖掘技术，但持续的穴居人敌意使得任何勘察工作都充满了危险。",["race:Dwarf"]="这次挖掘场被占领对探险者协会来说是一个惨痛的挫折，他们认为找回这里的古代文物对于了解矮人文化遗产至关重要。"},sec={{t="发掘过去",b="出于矮人想要揭开泰坦起源之谜的渴望，勘察员基恩萨·铁环在洛克莫丹东南部崎岖的悬崖边建立了这处庞大的挖掘场。原本充满希望的挖掘工作在触及一种异常凶猛且体型巨大的地下穴居人后，迅速变成了一场灾难。这些生物从地底涌出，击退了矿工，并在散落的工具、损坏的货车和半挖掘出来的文物之间建立了营地。"},{t="红土中的遗迹",b="正如在荒芜之地、湿地和奥达曼进行的考古工作一样，该地点处于危险的边缘。幸存的勘察员们坚守在挖掘场外围，拼命想要夺回被偷走的装备，并保护那些暴露在外的文物——包括被早已被遗忘的建造者留下的奇异古代雕像——免受贪婪的穴居人侵害，防止它们被破坏或带走。"}},faq={{q="铁环挖掘场位于何处？",a="该挖掘场位于洛克莫丹的东南部区域，就在洛克湖的正南方，旅行者营地的西南方。",al={"铁环挖掘场位置","铁环挖掘场在哪里","铁环挖掘场地图"}},{q="勘察员基恩萨·铁环是谁？",a="勘察员基恩萨·铁环是一名考古学家和探险家，他代表矮人探险者协会负责此次挖掘工作，试图抢救文物并驱逐当地的穴居人。",al={"铁环是谁","勘察员基恩萨·铁环背景故事"}},{q="为什么挖掘场会被穴居人占领？",a="随着矮人矿工在洛克莫丹的土地上越挖越深，他们的隧道开凿到了居住着一种大型且具有攻击性穴居人的地下洞穴，这些生物迅速压制了工人并夺取了挖掘场。",al={"为什么这里有穴居人","谁袭击了挖掘场","铁环挖掘场穴居人"}},{q="矮人们希望在这里找到什么？",a="就像卡兹莫丹各地的许多矮人考古挖掘点一样，矿工们正在寻找能够揭示矮人种族祖先起源的古代泰坦文物和石质遗迹。",al={"他们要挖掘什么","铁环挖掘场文物","为什么在这里挖掘"}}},fx={e2620dfb={q="什么是铁环挖掘场？",a="铁环挖掘场是一处规模宏大的矮人考古发掘地，位于洛克莫丹东南部，坐落在洛克湖以南、旅行者营地西南。铁炉堡的探险者协会考古学家在勘察员基恩萨·铁环的带领下设立营地，发掘泰坦古代遗迹，却不幸惊醒了沉睡的地下恐怖生物。",al={"这处挖掘场是什么","铁环挖掘场介绍","铁环挖掘场简介"}},ade9a17c={q="铁环挖掘场发生了什么？",a="与卡兹莫丹及更远地区的其他矮人挖掘场相似，勘察员们在地下挖得太深，触及了更深层的地层。他们因此闯入了一窝体型格外庞大、性情极其暴烈的穴居人巢穴。这些凶猛的生物蜂拥而出，占据了整个挖掘坑道，迫使矿工和研究人员放弃工作，并奋力夺回这片土地。",al={"铁环挖掘场历史","挖掘场发生了什么"}},["2d8b70cf"]={q="铁环挖掘场危险吗？",a="这里极其危险。挖掘坑道和阶地上遍布凶暴的穴居人，它们会猛烈攻击任何闯入自己夺回的领地的人。在探险者协会组织起协同反攻之前，独行旅人应有重兵护卫，或远远避开挖掘场。",al={"铁环挖掘场安全吗","铁环挖掘场有多危险"}},a83f1173={q="为什么叫铁环挖掘场？",a="这处遗址以首席监督者勘察员基恩萨·铁环命名。他代表铁炉堡探险者协会创立了这项发掘行动，旨在挖掘埋藏在洛克莫丹红色丘陵下的泰坦古代遗物。",al={"铁环挖掘场为何得名","谁给铁环挖掘场命名"}}},fp="26,280,19.480.0,22.380.0,44.134.0,27.187.0,47.223.0,42.191.0"}
P.entries["subzone:ironbeard-s-tomb"] = {n="铁须之墓",s="铁须之墓是一处位于湿地北向通往丹莫德的道路西侧的矮人墓穴，现已遭到亵渎。这里有一处露天墓地和一座以其命名的石像，由于酸性软泥怪成群结队地占据了此地，这座地下室已被废弃。除非是为了寻找被软泥怪吞噬的失物，否则很少有旅行者会踏足这个洞穴。",h="铁须之墓是一处位于湿地北向通往丹莫德的道路西侧的矮人墓穴，现已遭到亵渎。这里有一处露天墓地和一座以其命名的石像，由于酸性软泥怪成群结队地占据了此地，这座地下室已被废弃。除非是为了寻找被软泥怪吞噬的失物，否则很少有旅行者会...",kw={"墓穴","丹莫德","墓地","铁须","铁须之墓","软泥怪","塞达","湿地"},ang={["race:Dwarf"]="看到一位氏族英雄的安息之所被毫无思想的沼泽软泥怪所侵扰，对于任何行进在前往萨多尔大桥路上的矮人来说，都是一种沉痛的耻辱。"},sec={{t="一处受玷的安息之所",b="铁须之墓俯瞰着通往丹莫德的北向道路沿线的沼泽，它是矮人在湿地存在的见证。一座巨大的石像，据推测是铁须本人的雕像，守护着周围的墓地。然而，这里不再有肃穆的安宁。地下墓穴已经被各种黑色和深红色的软泥怪完全占领，导致墓穴受到了污染。矮人们不再将死者安葬在这个破败的圣所，而那些胆敢闯入墓穴的人，主要也是为了搜寻被潜伏的软泥怪消化后的遗物。"}},faq={{q="铁须是谁？",a="关于铁须本人的记载极少，尽管巨大的雕像和墓地规模表明，他曾是湿地一位受人尊敬且颇具声望的矮人。为他竖立的雕像守护着墓地之上的山坡。",al={"铁须背景故事","铁须是谁","雕像身份"}},{q="墓穴为何被废弃？",a="地下墓穴已被酸性的黑色和深红色软泥怪完全占领。由于墓地遭到亵渎且遍布危险的软泥怪，哀悼的家庭已经停止将死者安葬在此。",al={"为何废弃","墓穴中的软泥怪","墓穴发生了什么"}},{q="为什么冒险者要探索铁须之墓？",a="除了击退污秽的侵扰外，旅行者经常会在墓穴的软泥怪中搜寻，希望能找回被吞下的物品，其中最引人注目的是塞达丢失的背包。",al={"为何要去这里","塞达的背包","墓穴任务"}},{q="铁须之墓位于何处？",a="墓穴坐落在湿地中北部，位于通往矮人据点丹莫德的主路以西的山坡上。",al={"墓穴位置","如何前往铁须之墓","铁须湿地地图"}}},fx={["0a492c86"]={q="铁须之墓为何以此命名？",a="这处安息之地以长眠于墓穴中的矮人铁须命名。一尊醒目的矮人雕像守望着墓地，纪念着他的生平，尽管墓穴本身已年久失修，日渐荒废。",al={"铁须之墓为何得名","墓地以谁命名","铁须之墓名称由来"}},["7c55bc22"]={q="什么是铁须之墓？",a="铁须之墓是一处古老的矮人墓地，位于湿地北部，就在通往丹莫德的道路以西。这里包括一座地下墓穴、一片杂草丛生的墓园，以及一尊为纪念铁须本人而竖立的石像。",al={"这是什么地方","铁须之墓传说","铁须之墓简介"}},["6532c17b"]={q="铁须之墓危险吗？",a="这里极其危险。神圣的墓穴和周围的墓园已被污秽的软泥怪彻底亵渎，其中既有黑色和深红色的黏液怪，也有会吞噬沿途一切的巨型种类。由于这些污秽的野兽，活人已不再前来此地祭奠逝者。",al={"铁须之墓有多危险","铁须之墓的怪物","铁须之墓的威胁"}}},fp="16,359,24.600.0,18.241.0,26.196.0,44.153.0,34.143.0"}
P.entries["subzone:ironclad-cove"] = {n="铁甲湾",s="铁甲湾是一个隐藏在西部荒野地下的巨大地下洞穴，里面设有一个地下船厂和码头。它是迪菲亚潜行者建造战争巨舰的秘密船坞，并直接与海洋相连。",h="铁甲湾是一个隐藏在西部荒野地下的巨大地下洞穴，里面设有一个地下船厂和码头。它是迪菲亚潜行者建造战争巨舰的秘密船坞，并直接与海洋相连。",kw={"曲奇","死亡矿井战舰","迪菲亚海湾","艾德温·范克里夫","铁甲湾","重型战舰","船厂"},ang={["class:Rogue"]="海湾代表了艾德温·范克里夫在工艺、工程技术和地下后勤方面的巅峰造诣，使之在盗贼和不法之徒中极具传奇色彩。",["faction:Alliance"]="在西部荒野地下发现一艘全尺寸战舰，标志着迪菲亚兄弟会从一个区域性的土匪帮派转变成了对暴风城王国构成生存威胁的军事力量。"},sec={{t="隐秘船坞",b="铁甲湾深埋于死亡矿井的最底层，是一个被改造成坚固码头的巨大海蚀洞。艾德温·范克里夫和迪菲亚潜行者在这里建造了一艘名为“重型战舰”的巨大军舰。洞穴内布满了木制脚手架、小岛和装货栈桥，由迪菲亚海盗、甲板水手和监工把守。它的存在揭示了迪菲亚威胁的真实规模：范克里夫的目的不仅仅是劫掠西部荒野的农场，而是要组建一支足以轰炸暴风城海岸的私人海军。"},{t="通往海洋的门户",b="这个洞穴中矗立着巨大的铁制海闸，它们嵌入岩壁之中。一旦开启，这些闸门便能直接通往无尽之海，出口位于荆棘谷北部海岸。海湾避开了暴风城海军舰队的视线，为迪菲亚潜行者提供了一条无人监管的航道，用于运输违禁品、策划海上突袭以及准备他们的海军突击。"}},faq={{q="铁甲湾里的那艘船是用来做什么的？",a="这艘重型战舰是艾德温·范克里夫军事野心的核心。迪菲亚潜行者在地下深处组装这艘巨大的军舰，以便它能通过地下水道悄无声息地出航，并从海上对暴风城发起攻击。",al={"为什么这里会有船","什么是重型战舰","死亡矿井战舰的目的"}},{q="海湾里的大金属门通向哪里？",a="巨大的闸门直接通向海洋；它们的外侧可以在荆棘谷北部的海岸线上看到。一旦闸门打开，重型战舰便能直接驶入无尽之海。",al={"海闸通向哪里","死亡矿井铁门","通往海洋的出口"}},{q="谁控制着铁甲湾？",a="迪菲亚潜行者在艾德温·范克里夫的指挥下控制着海湾，利用这个隐秘的码头确保重型战舰的建造全程保密。",al={"谁在经营海湾","谁住在铁甲湾"}},{q="船上的那个鱼人是谁？",a="那是曲奇，迪菲亚战舰的厨师。他手持擀面杖和烹饪锅，在人类和地精叛军中是一个不同寻常的盟友，他已将船上的厨房据为己有。",al={"鱼人曲奇","为什么会有鱼人海盗","厨师曲奇"}}},fx={dba05414={q="铁甲湾是什么地方？",a="铁甲湾是死亡矿井深处的一座巨大地下洞窟，已被改造成秘密船坞。这里被高耸的石壁和天然水道环绕，内部设有码头和脚手架，迪菲亚潜行者正借此建造庞大的战争巨舰。一扇巨大的加固石门封住了洞窟通往南方海域的出口，将他们的海上行动隐瞒起来，直到船只准备就绪、扬帆出航。",al={"铁甲湾简介","死亡矿井里的这个地方是什么","死亡矿井船坞洞窟"}},["63b814e0"]={q="铁甲湾发生过什么事？",a="艾德温·范克里夫和他的迪菲亚潜行者占据死亡矿井后，将这处隐蔽的海底洞窟改造成了秘密船坞。他们在巨大的海门后建造一艘名为“juggernaught”的巨大战舰，避开暴风王国的视线。",al={"铁甲湾历史","铁甲湾曾由谁占据","死亡矿井船坞的往事"}},["3987b29d"]={q="铁甲湾危险吗？",a="这里极其危险。铁甲湾是艾德温·范克里夫叛乱势力的内层据点和核心中枢。水道、栈道和脚手架上遍布全副武装的迪菲亚窃贼、雇佣来的海盗、地精工程师和致命的战士，他们都在守卫这艘珍贵的战舰。任何潜入矿井深处的人，都将面对迪菲亚潜行者最强悍的指挥官；他们不惜一切代价也要保护首领的宏图大计。",al={"铁甲湾安全吗","铁甲湾的威胁","死亡矿井船坞的危险"}}},fp="13,235,19.576.0,20.400.1,50.256.0,49.196.0,27.154.0,34.197.0"}
P.entries["subzone:ironforge"] = {n="铁炉堡",s="铁炉堡是矮人的地下都城，深入丹莫罗的铁炉堡山岩层之中。它以轰鸣的Great Forge为中心，是卡兹莫丹王国的政治与商业中心，也是联盟的坚实堡垒。",h="铁炉堡是矮人的地下都城，深入丹莫罗的铁炉堡山岩层之中。它以轰鸣的Great Forge为中心，是卡兹莫丹王国的政治与商业中心，也是联盟的坚实堡垒。",kw={"铜须","矿道地铁","丹莫罗","great forge","high seat","铁炉堡","卡兹莫丹","麦格尼","tinker town"},ang={["race:Dwarf"]="铁炉堡是铜须部族的祖传都城和核心，矮人的技艺、勇气和历史都被刻在了活着的山岩之中。",["race:Gnome"]="由于诺莫瑞根被穴居人和辐射所侵占，侏儒们将Tinker Town作为了临时的避难所，并以此作为他们收复家园计划的集结地。"},sec={{t="山脉要塞",b="这座城市开凿在铁炉堡山的地下深处，以雄伟的Great Forge为核心，呈同心圆状向外辐射。它始建于数千年前，当时矮人们在觉醒后从奥达曼迁徙而来。它历经了漫长的历史岁月，包括那场最终确立了铜须部族统治地位的远古三锤之战。这座洞穴城市以流淌的熔岩为动力，并拥有巨大的石门防御，既是工业重镇，也是坚不可摧的堡垒。除了矮人工匠和战士，在诺莫瑞根陷落后，这里还居住着大量流亡的侏儒。"},{t="联盟贸易中心",b="在25 ADP，铁炉堡可以说是联盟中最繁忙的商业和工业中心。国王麦格尼·铜须在High Seat统治着卡兹莫丹，而矮人勘探员、矿工和工程师们正与定居在Tinker Town的侏儒难民们通力合作。地下的矿道地铁建立了一条从山下直通暴风城的全天候高速交通线，通过贸易、军队调动和共同防御将两座都城紧密相连。"}},faq={{q="目前铁炉堡的统治者是谁？",a="铁炉堡由国王麦格尼·铜须统治，他在High Seat主持朝政。这座城市作为铜须部族统领下的卡兹莫丹王国的首府。",al={"铁炉堡国王是谁","铁炉堡领袖","谁领导铁炉堡"}},{q="为什么有这么多侏儒住在铁炉堡？",a="在邻近的都城诺莫瑞根遭遇灾难性的陷落并遭受辐射后，幸存的侏儒逃到了铁炉堡。铜须矮人欢迎了他们长期的盟友，并为他们在Tinker Town提供了避难所。",al={"为什么侏儒在铁炉堡","侏儒 避难区","侏儒来自哪里"}},{q="铁炉堡是如何连接到暴风城的？",a="铁炉堡通过矿道地铁直接连接到暴风城，这是一项由侏儒建造的工程奇迹，从Tinker Town地下一直延伸到暴风城的Dwarven District。",al={"前往暴风城的地铁","如何前往暴风城","去往暴风城的通道"}},{q="市中心的Great Forge是什么？",a="Great Forge是一座巨大的熔炉，其燃料来自于直接穿过山脉核心的天然岩浆河流。它是卡兹莫丹王国的主要锻造和冶炼中心。",al={"铁炉堡的大熔炉","great forge是什么","铁炉堡中心的熔岩"}}},fx={["492ad021"]={q="铁炉堡是什么地方？",a="铁炉堡是矮人的地下首都，也是卡兹莫丹王国的王都。这座城市完全在丹莫罗最高峰下凿石而建，是一座坚不可摧的地下要塞，也是联盟的工业中心。城中各区围绕着巨大的Great Forge呈同心圆分布，遍布熔炉、铁匠铺、热闹的酒馆和军营。",al={"铁炉堡是什么地方","铁炉堡背景","铁炉堡简介"}},f6c71775={q="铁炉堡发生过什么事？",a="数千年前，古代矮人离开奥达曼，在此建立了Great Forge，以纪念泰坦卡兹格罗斯。数个世纪后，三锤之战引发的内乱席卷了整座山脉。高王莫迪姆斯·安威玛尔去世后，铜须、蛮锤和黑铁氏族为争夺控制权展开激战，最终铜须氏族驱逐了对手，独占了这座山中要塞。",al={"铁炉堡历史","这里发生过什么","铁炉堡往事"}},["9692900f"]={q="铁炉堡安全吗？",a="在厚重的石门之内，铁炉堡是东部王国最安全的庇护所之一。矮人山地卫兵和王室哨兵严密守卫着这里，厚实的山壁也将地表的危险隔绝在外。只要不掉进Great Forge的熔岩河，也不属于部落，在这座繁华而舒适的城市中行走便几乎不会遇到危险。",al={"铁炉堡安全吗","铁炉堡的危险","铁炉堡面临的威胁"}},ea3b645e={q="这座城市为何叫铁炉堡？",a="这座城市的名字源自洞窟中央的Great Forge，也与它所凿建于下方的巍峨山峰有关。早期矮人最初凿开山峰并建起宏伟的冶炼设施后，整座地下城市便围绕这座巨炉不断向外扩展。",al={"铁炉堡为何得名","铁炉堡名称由来","铁炉堡名称起源"}}},fp="9,278,21.676.0,23.498.0,30.189.0,49.238.0,45.194.0,50.210.0"}
P.entries["subzone:ironforge-airfield"] = {n="Ironforge Airfield",s="这座遥远的矮人简易机场位于铁炉堡东北方向白雪皑皑的群峰之巅，是侏儒飞行器和矮人山地巡逻队的试验场与集结地。它远离主路，坐落于高原之上，俯瞰着丹莫罗崎岖的峭壁，下方则是通往湿地的陡峭斜坡。",h="这座遥远的矮人简易机场位于铁炉堡东北方向白雪皑皑的群峰之巅，是侏儒飞行器和矮人山地巡逻队的试验场与集结地。它远离主路，坐落于高原之上，俯瞰着丹莫罗崎岖的峭壁，下方则是通往湿地的陡峭斜坡。",kw={"机场","简易机场","丹莫罗","飞行器","霜鬃","铁炉堡","山地巡逻队"},ang={["profession:Engineering"]="对于技师来说，这个简易机场展示了侏儒航空技术的巅峰，这里停放着在极端零度条件下依然完好的飞行器。",["race:Dwarf"]="作为矮人领土警戒能力的证明，该机场证实了铁炉堡的山地巡逻队即使在卡兹莫丹最难以抵达的高地，依然坚守着岗位。"},sec={{t="峭壁之中的隐秘要塞",b="这座高海拔机场栖息在丹莫罗人迹罕至的小径上方，是联盟合作的静谧奇迹。在四周群山的环抱下，矮人的石工技术加固了狂风肆虐的山脊线，而侏儒飞行器则停泊在开阔的跑道旁。山地巡逻队员守护着外围，而工程师们则在严寒中忙于修理齿轮、检修喷射着蒸汽的引擎。"},{t="边境冲突与冰封山谷",b="尽管位置偏僻，机场却并不安宁。周围的山谷布满了冰封的水域和峭壁，霜鬃巨魔盘踞在附近的洞穴中，不断袭扰着矮人哨兵。在群峰的阴影下，矮人守卫和雷矛巡逻队经常在冰面上与巨魔袭击者发生冲突，使这个偏远的据点始终处于一种静默而警惕的对峙状态。"}},faq={{q="如何前往机场？",a="没有任何道路、航线或维护良好的隧道将这个山谷与铁炉堡或丹莫罗的低地连接起来。抵达这里需要徒步攀登陡峭的山坡，通常是通过从洛克莫丹出发或靠近丹莫罗山口的一些崎岖的山脊攀爬路径。",al={"前往机场","如何攀爬到机场","机场位置","机场路径"}},{q="这个地方有什么用？",a="它作为一个高海拔飞行测试点和军事哨所，矮人山地巡逻队和侏儒工程师在此维护飞行器，并侦察分隔丹莫罗、洛克莫丹和湿地的高山边境地带。",al={"为什么这里有简易机场","ironforge airfield的作用"}},{q="是谁在攻击此地的矮人守卫？",a="当地的霜鬃巨魔居住在山谷南部的悬崖洞穴中。矮人山地巡逻队经常为了跑道下方那片冰封的湖泊与他们发生冲突。",al={"谁在攻击机场","谁在湖上战斗"}},{q="机场有相关任务吗？",a="在日常冒险中，没有标准的任务会指引冒险者前往此简易机场。它仍然是一个偏远而隐蔽的高原，基本上不参与矮人王国的核心后勤事务。",al={"这里有任务吗","机场任务"}}},fx={d601e954={q="Ironforge Airfield是什么地方？",a="Ironforge Airfield也称丹莫罗简易机场，是一处位于铁炉堡东北方向高山之中的基地。那里修建了跑道、矮人堡垒和机械机库，作为地精飞行器的试验场，以及矮人在雪峰之上的空中行动集结地。",al={"ironforge airfield","丹莫罗简易机场是什么","这个机场是什么地方"}},ef0ab7f8={q="谁住在Ironforge Airfield，或负责管理这里？",al={"谁控制着ironforge airfield","谁管理机场","简易机场有哪些人"}},["74586b0d"]={q="Ironforge Airfield危险吗？",a="机场本身有矮人哨兵和地精飞行员守卫，但周围的山谷确实危机四伏。敌对的霜鬃巨魔居住在南方冰湖边的洞穴中，经常与矮人巡逻队发生冲突，附近的冰冷山脊上还有野熊出没。",al={"ironforge airfield危险吗","机场面临的威胁","简易机场的危险"}}},fp="18,304,29.419.0,38.403.0,34.276.0,34.225.0,41.167.0,44.184.0"}
P.entries["subzone:ironstone-camp"] = {n="铁石营地",s="铁石营地是部落在千针石林的闪光平原西侧边界建立的前哨站。该营地最初部署的目的是驱逐在附近挖掘场工作的联盟矮人挖掘者，但现在营地军队面临着严重的威胁，因为地下的其拉虫人已经占领了挖掘场。",h="铁石营地是部落在千针石林的闪光平原西侧边界建立的前哨站。该营地最初部署的目的是驱逐在附近挖掘场工作的联盟矮人挖掘者，但现在营地军队面临着严重的威胁，因为地下的其拉虫人已经占领了挖掘场。",kw={"部落前哨站","铁石营地","摩克塔·克林","锈槌挖掘场","闪光平原","其拉虫人","千针石林"},ang={["faction:Alliance"]="前往闪光平原的联盟探险者应与该营地保持距离，该营地最初建立的目的就是专门骚扰并清除锈槌挖掘场的矮人挖掘者。",["faction:Horde"]="在前往开阔的盐滩之前，该营地提供了一个战略性的落脚点，尽管当地指挥官正竭尽全力消除威胁他们阵地的其拉虫人虫群。"},sec={{t="改变任务",b="铁石营地位于千针石林的高大石柱与闪光平原炽热盐滩的交界处。驻扎在这里的部落分遣队最初被派往此地，目标明确而单一：驱逐在锈槌挖掘场进行挖掘的矮人挖掘者。然而，就在一场成群结队的贪婪其拉虫人从附近的洞穴中涌出，暴力吞噬了挖掘场并袭击了双方之后，他们的军事对抗被迫中断。在摩克塔·克林的带领下，幸存的营地守军已经将精力转向打击这些虫群，防止虫灾在整个地区蔓延开来。"}},faq={{q="铁石营地的目的是什么？",a="铁石营地是作为部落的前进集结地而建立的，旨在将联盟的矮人挖掘者从锈槌挖掘场驱逐出去。然而，一群意料之外的地底其拉虫人突袭了该地区，迫使营地将重心转向生存，并遏制这种昆虫威胁。",al={"为什么会有铁石营地","铁石营地的目的","闪光平原的部落营地"}},{q="谁领导着铁石营地的部队？",a="摩克塔·克林指挥着驻扎在此的部落战士。由于原定任务因虫灾而中断，他负责协调巡逻，并指派旅行者清除在邻近挖掘场出没的具攻击性的其拉虫人。",al={"铁石营地的首领","摩克塔·克林","谁在管理铁石营地"}},{q="铁石营地位于何处？",a="营地坐落在千针石林，位于闪光平原的西侧边缘，紧靠着从峡谷底部通往刺眼盐滩的路径。",al={"铁石营地的位置","铁石营地在哪里","如何找到铁石营地"}}},fx={["219f846c"]={q="铁石营地是什么地方？",a="铁石营地是部落在千针石林与闪光平原交界处设立的一座小型前哨。最初，部队奉命进入盐碱平原，对付并驱逐在附近锈槌挖掘场作业的矮人挖掘者。然而，斥候们没有迎来与联盟的一场普通冲突，反倒遭遇了从地下涌出的致命梦魇。",al={"铁石营地是什么地方","铁石营地背景","铁石营地简介"}},["48968e37"]={q="铁石营地发生过什么事？",a="部落建立这座营地，是为了监视并摧毁矮人在锈槌挖掘场的行动。部落部队尚未完成任务，贪婪的其拉虫族便从附近的洞穴系统中涌出，席卷了这一带。虫群屠杀并驱散了挖掘者，很快又将攻击目标转向营地，迫使部落斥候放弃原计划，为生存而战。",al={"铁石营地历史","铁石营地发生过什么","铁石营地的背景"}},["72b09178"]={q="谁住在铁石营地？",a="营地里驻扎着一支部落士兵、斥候和监工组成的分队，其中包括摩克塔·克林。其拉虫族突然现身后，他们被困在此地，承受着巨大压力，只能固守平原边缘，并寻求部落冒险者协助抵御逼近的虫族威胁。",al={"铁石营地有哪些人","铁石营地的居民","谁住在铁石营地"}},b6eea169={q="铁石营地危险吗？",a="在营地范围内，部落旅者可以在盟友中找到安全的落脚处，但联盟成员会立刻遭到敌视。然而，周围地带危机四伏。来自附近地下巢穴的好斗其拉虫族在挖掘场周围成群出没，足以压倒任何毫无准备的闯入者。",al={"铁石营地安全吗","铁石营地的危险","铁石营地面临的威胁"}}},fp="14,306,19.652.0,38.286.0,39.229.0,32.181.0"}
P.entries["subzone:irontree-woods"] = {n="铁木森林",s="铁木森林是位于费伍德森林北部的一片枯萎的树林，曾经是暗夜精灵珍视的宁静森林保护区。在第三次战争中，它遭到了恶魔腐化的蹂躏，古老的守护者被石化，而扭曲的树人和元素在废墟中徘徊。",h="铁木森林是位于费伍德森林北部的一片枯萎的树林，曾经是暗夜精灵珍视的宁静森林保护区。在第三次战争中，它遭到了恶魔腐化的蹂躏，古老的守护者被石化，而扭曲的树人和元素在废墟中徘徊。",kw={"古树","费伍德森林","哈斯塔特","铁木森林","月亮井","石化树木","斯托玛","树人","瓦特鲁斯"},ang={["class:Druid"]="扭曲的沼泽兽和石化的古树展现了恶魔枯萎病造成的毁灭性后果，急需纯净的月亮井水来在受污染的土壤中激发新生。",["race:NightElf"]="站在哈斯塔特、斯托玛和瓦特鲁斯的石化躯壳之间，这令人痛心地提醒着人们第三次战争对神圣林地所造成的惨重代价。"},sec={{t="化为石头的森林",b="铁木森林曾是一片由卡多雷照料的宁静林地，但在第三次战争期间，燃烧军团的恶魔污染扼杀了这里的土壤生机。树林中的古树守护者——哈斯塔特、斯托玛和瓦特鲁斯——屈服于黑暗魔法，石化成了毫无生气的石碑，至今仍矗立在被腐化的灌木丛中。如今，疯狂的树人、邪恶的沼泽兽和被污染的水元素在扭曲的森林地面上游荡，疯狂地攻击任何胆敢靠近的旅行者。"}},faq={{q="这里的巨树发生了什么事？",a="暗夜精灵的伟大生命之树——特别是名为哈斯塔特、斯托玛和瓦特鲁斯的古树——屈服于第三次战争期间吞噬了费伍德森林的恶魔腐化。黑暗能量将它们石化，使它们冻结成了毫无生气的石碑。",al={"为什么树木变成了石头","石化的古树","铁木森林的石树"}},{q="为什么森林里的生物如此敌对？",a="燃烧军团弥漫的邪能腐化已经让森林的原住民陷入了疯狂。树人、沼泽兽和水元素的思想和形态都遭到了扭曲，使它们对任何外来者都表现出极强的攻击性。",al={"费伍德森林的愤怒树人","铁木森林的被腐化元素"}},{q="铁木森林有可能从腐化中恢复吗？",a="这片树林已经彻底扭曲，它的古树守护者也已死亡并石化。任何恢复的希望都寄托在那些致力于净化笼罩整个费伍德森林的恶魔腐化的德鲁伊身上。",al={"治愈铁木森林","费伍德森林能被拯救吗","铁木森林的新古树"}},{q="过去是谁照料这片树林的？",a="暗夜精灵和他们结盟的古树曾经保护并照料这片林地，散落在费伍德森林北部的卡多雷石制品、遗迹以及石化的守护树就是最好的证明。",al={"暗夜精灵与铁木森林","是谁建造了这些雕像"}}},fp="14,296,24.509.0,38.267.0,43.239.0,52.193.0,32.207.0"}
P.entries["subzone:isle-of-dread"] = {n="恐怖之岛",s="恐怖之岛是一座荒凉、布满悬崖的岛屿，坐落于无尽之海中，位于菲拉斯西南海岸外，萨尔多岛的南面。岛上栖息着可怕的双头奇美洛克，地下海穴中还潜藏着一群怀有敌意的娜迦，这使它臭名昭著。",h="恐怖之岛是一座荒凉、布满悬崖的岛屿，坐落于无尽之海中，位于菲拉斯西南海岸外，萨尔多岛的南面。岛上栖息着可怕的双头奇美洛克，地下海穴中还潜藏着一群怀有敌意的娜迦，这使它臭名昭著。",kw={"奇美洛克","羽月","菲拉斯","恐怖之岛","拉卡玛兰","娜迦","萨尔多岛","沙尔扎鲁","萨拉"},ang={["faction:Alliance"]="附近羽月要塞的暗夜精灵哨兵时刻注视着这座岛屿，寻求勇士打击沙尔扎鲁领主，阻止娜迦在他们岸边作乱。",["profession:Cooking"]="恐怖之岛的奇美洛克是迪尔格·奎克里弗制作传奇“迪尔格的超美味奇美洛克大餐”的关键原料——奇美洛克的腰肋肉的唯一已知来源。"},sec={{t="怪物与潮汐之地",b="恐怖之岛从南海汹涌的波涛中拔地而起，正如其名，令人望而生畏。岛屿四周环绕着陡峭的悬崖，唯一的入口位于其东南海岸的一条狭窄小径。在这片封闭的高地上，游荡着一群致命的奇美洛克——这些贪婪的双头野兽受到周围奥术能量的强化。这些野兽由恐怖的拉卡玛兰领主领导，使得这座岛屿成为了从萨尔多岛横渡海峡而来的大意探险家们的致命陷阱。"},{t="北部洞穴",b="虽然内陆高原属于奇美洛克，但该岛的北岸隐藏着一个被怒鳍娜迦占据的洞穴系统。在沙尔扎鲁领主的领导下，这些蛇形生物潜伏在深邃的水下洞穴中，密谋对抗驻扎在附近羽月要塞的暗夜精灵哨兵。他们的地下巢穴包含通往僻静石窟的隐秘水下通道，作为远离大陆监视的重兵据点。"}},faq={{q="如何到达恐怖之岛的内部？",a="这座岛屿被高耸陡峭的悬崖包围，几乎阻断了从所有海岸线攀登的可能。进入中央高原的唯一步行路径位于岛屿的东南侧。",al={"恐怖之岛入口","如何登上恐怖之岛","攀爬恐怖之岛"}},{q="岛上居住着哪些生物？",a="高地上居住着凶猛的奇美洛克，包括奥术奇美洛克和由顶级掠食者拉卡玛兰领主领导的巨大吞噬者。沿北海岸的深海洞穴则被充满敌意的怒鳍娜迦所占据。",al={"恐怖之岛怪物","恐怖之岛上的怪物","菲拉斯奇美洛克"}},{q="谁在领导海穴中的娜迦？",a="占据北部洞穴群的娜迦族群由沙尔扎鲁领主领导。他们的存在对附近羽月要塞的暗夜精灵构成了直接威胁。",al={"恐怖之岛娜迦首领","沙尔扎鲁领主洞穴","菲拉斯岛屿娜迦首领"}},{q="是什么让奇美洛克肉如此出名？",a="奇美洛克能产出极好的腰肋肉，深受美食大师们的青睐。像迪尔格·奎克里弗这样的烹饪大师会寻找来自岛上的肉类——包括拉卡玛兰领主珍贵的尸体——来制作传奇盛宴。",al={"奇美洛克的腰肋肉","迪尔格的超美味奇美洛克大餐","恐怖之岛食物"}}},fp="13,283,28.512.0,20.463.0,51.217.0,43.224.0,36.169.0,36.222.0"}
P.entries["subzone:itharius-s-cave"] = {n="伊萨里奥斯的洞穴",s="伊萨里奥斯的洞穴是一个隐藏在悲伤沼泽最西南端悬崖里的隐秘洞窟。它是神秘的伊萨里奥斯的避难所，他看起来像是一位高等精灵，负责照料居住在周围沼泽地中的绿色龙族后代。",h="伊萨里奥斯的洞穴是一个隐藏在悲伤沼泽最西南端悬崖里的隐秘洞窟。它是神秘的伊萨里奥斯的避难所，他看起来像是一位高等精灵，负责照料居住在周围沼泽地中的绿色龙族后代。",kw={"龙族","绿色幼龙","高等精灵","伊萨里奥斯","伊萨里奥斯的洞穴","悲伤沼泽"},ang={["class:Druid"]="沼泽中绿色龙族的存在使得这个洞穴引起了德鲁伊的特别关注，他们的传统与绿龙军团和翡翠梦境紧密相连。"},sec={{t="龙崽中的隐士",b="这个潮湿的洞穴位于悲伤沼泽西南部那些险峻且布满苔藓的岩壁中，它是隐居者伊萨里奥斯的住所。在洞口外，顽皮的绿色龙崽在泥沼中徘徊。虽然他看起来像是一位高等精灵——这个种族很少独自深入南方如此荒凉的沼泽——但伊萨里奥斯在他们成长过程中一直注视着这些年幼的龙族，与他们一同安静地隐居于此。"}},faq={{q="谁住在这个洞穴里？",a="这个洞穴是伊萨里奥斯的家，他是一位神秘的隐士，看起来像是一位高等精灵。他远离文明世界，照看当地的龙族。",al={"伊萨里奥斯是谁","洞穴主人","谁住在这里"}},{q="伊萨里奥斯的洞穴位于哪里？",a="它深藏在悲伤沼泽的西南角，紧靠主路南侧的山脊。",al={"伊萨里奥斯的洞穴位置","伊萨里奥斯在哪里","如何找到洞穴"}},{q="为什么洞穴外会有绿色幼龙？",a="周围的沼泽中栖息着绿色幼龙。伊萨里奥斯承担起了照看和保护这些顽皮的幼龙，看着它们成长的责任。",al={"为什么有幼龙在这里","悲伤沼泽的绿龙","外面的幼龙"}},{q="为什么一位高等精灵会住在沼泽里？",a="伊萨里奥斯看起来像是一位高等精灵，这个种族在这些南部沼泽中十分罕见，但他之所以留在这里，是为了专门保护沼泽中的绿色龙族，并在他偏僻的巢穴中过着隐居生活。",al={"沼泽中的高等精灵","伊萨里奥斯为什么在这里"}}},fp="15,257,21.400.0,23.151.0,33.121.0,44.153.0,43.195.0"}
P.entries["subzone:ivar-patch"] = {n="伊瓦农场",s="伊瓦农场是一片位于银松森林北部的被瘟疫侵蚀的南瓜田。这里曾经是洛丹伦一处繁荣的农耕家园，但在第三次战争期间，其居民惨遭屠戮，并被转化成了贪婪且毫无理智的食尸鬼。",h="伊瓦农场是一片位于银松森林北部的被瘟疫侵蚀的南瓜田。这里曾经是洛丹伦一处繁荣的农耕家园，但在第三次战争期间，其居民惨遭屠戮，并被转化成了贪婪且毫无理智的食尸鬼。",kw={"死亡猎手","食尸鬼","伊瓦农场","邪恶的伊瓦","南瓜田","奎恩·尤瑞克","兰妮·尤瑞克","银松森林"},ang={["faction:Horde"]="清除农场里那些贪婪的食尸鬼，对于保障银松森林与幽暗城之间的北部道路安全至关重要。",["race:Undead"]="这座荒废的农场就像是一个痛苦的警示，时刻提醒着人们那场将洛丹伦撕裂的亡灵瘟疫，并展示了被遗忘者们千钧一发才逃脱的、那种可怕且毫无理智的命运。"},sec={{t="毁灭的收成",b="在第三次战争席卷洛丹伦之前，这片南瓜田曾经是一个由名为伊瓦的农夫所拥有的富庶家园，他雇佣了一群充满活力的农工和仆人。当天灾军团在乡村散布亡灵瘟疫时，这座农场被彻底吞噬。伊瓦、他的家人和工人们并没有像获得自由意志的被遗忘者那样保留神智，而是沦为腐烂、野蛮的食尸鬼，被束缚在这片废土上徘徊。"},{t="死亡猎手伏击",b="当被遗忘者开始稳固银松森林北部时，三名死亡猎手——兰妮·尤瑞克、奎恩·尤瑞克和Erland McKree——在侦查该区域以评估当地威胁。当他们在经过亡者农场时，这支巡逻队遭到了农场内野蛮群体的伏击。奎恩被伊瓦本人（现在被称为“邪恶的伊瓦”）重伤。由于奎恩伤势严重，尤瑞克夫妇在农场那栋破旧的废屋中据守，而McKree则独自继续前往玛尔丁果园。"}},faq={{q="农场及其主人遭遇了什么？",a="这座农场在第三次战争期间遭受了亡灵瘟疫的打击。伊瓦农夫、他的家人和工人们全都未能幸免，在天灾军团残留的控制下重新站起，变成了野蛮、腐烂的食尸鬼。",al={"伊瓦农场历史","伊瓦是谁","伊瓦遭遇了什么"}},{q="为什么屋子里藏着死亡猎手？",a="死亡猎手兰妮·尤瑞克和奎恩·尤瑞克是奉命评估银松森林地区威胁的侦察小队成员。在经过此地时，他们遭到了食尸鬼的伏击，奎恩被邪恶的伊瓦严重打伤，迫使他们躲进破旧的农舍中避难。",al={"伊瓦农场的死亡猎手","为什么被遗忘者在这里","奎恩·尤瑞克农舍"}},{q="这里的食尸鬼是被遗忘者的一员吗？",a="不。在南瓜田里游荡的食尸鬼是由亡灵瘟疫创造的、毫无理智的天灾军团残党。他们没有自由意志，一见到活着的旅行者或被遗忘者就会发起攻击。",al={"这些食尸鬼是被遗忘者吗","伊瓦农场的天灾军团","为什么食尸鬼充满敌意"}},{q="伊瓦农场位于哪里？",a="伊瓦农场位于银松森林北部，亡者农场以北，通往玛尔丁果园的大路以南。",al={"伊瓦农场位置","伊瓦农场在哪里"}}},fx={b4d2b280={q="伊瓦农场是什么地方？",a="伊瓦农场曾是银松森林北部一处繁荣的南瓜农场，田间劳作繁忙，农工和仆役往来其间。如今，这里已成废墟，杂草丛生；第三次战争毁坏了肥沃的土壤，野蛮的亡灵也占据了此地。",al={"伊瓦农场是什么地方","伊瓦农场背景","伊瓦农场"}},ef89f0e6={q="伊瓦农场为何以此命名？",a="这片土地以昔日的主人伊瓦命名。他曾管理这座庄园，雇用许多仆役照料南瓜；但在第三次战争期间，他染上瘟疫，变成了如今徘徊在庄园中的邪恶食尸鬼。",al={"伊瓦是谁","伊瓦农场为何得名","伊瓦之名的由来"}},a1ef5b14={q="伊瓦农场危险吗？",a="这里极其危险。无知无觉、饥肠辘辘的食尸鬼在被疫病侵蚀的南瓜田中游荡，攻击任何擅闯此地的生者或亡灵。就连受过训练的被遗忘者斥候——Deathstalkers，也曾在试图穿过这里时遭到伏击，身负重伤。",al={"伊瓦农场的危险","伊瓦农场安全吗","伊瓦农场面临的威胁"}}},fp="10,241,16.461.0,23.475.1,40.206.0,52.307.0,41.184.0,32.134.0"}
P.entries["subzone:jadefire-run"] = {n="碧火小径",s="碧火小径是位于费伍德森林北部的一处守备森严的萨特营地。这里盘踞着该地区最强大、最狡诈的萨特，作为这片被腐蚀的森林深处的一座恶魔腐化堡垒。",h="碧火小径是位于费伍德森林北部的一处守备森严的萨特营地。这里盘踞着该地区最强大、最狡诈的萨特，作为这片被腐蚀的森林深处的一座恶魔腐化堡垒。",kw={"被腐蚀的","恶魔","费伍德森林","碧火","碧火小径","萨特","xavaric"},ang={["class:Druid"]="德鲁伊们将碧火小径中滋生的邪恶仪式和邪能存在视为毒害费伍德森林自然灵魂的开放性伤口。",["race:NightElf"]="对于暗夜精灵来说，碧火小径是对远古背叛和恶魔亵渎的一种怪诞提醒，必须将其从神圣的卡利姆多大地上清除。"},sec={{t="欺诈堡垒",b="碧火小径坐落在费伍德森林北部荒凉的林木之中，是碧火萨特的主要据点。与散布在山谷中的小型哨站不同，这座营地拥有坚固的恶魔建筑，并庇护着强大的施法者和诡计多端的萨特。这里的萨特正积极谋划，企图利用黑暗魔法和邪恶诡计，将腐化散播到整个卡利姆多，并对抗任何敢于闯入其领地的人。"}},faq={{q="什么是碧火小径？",a="碧火小径是位于费伍德森林北部的一处大型萨特聚居点。它是盘踞在森林中一些最危险且精锐的萨特的核心堡垒。",al={"碧火小径信息","这是费伍德森林的什么地方"}},{q="谁统治或居住在碧火小径？",a="这个营地由碧火萨特占据——他们是燃烧军团被腐化的仆从，利用邪能魔法和欺骗性的幻象来恐吓周围的森林。",al={"谁住在这里","碧火小径怪物"}},{q="为什么碧火小径如此危险？",a="此处的萨特明显比费伍德森林南部的同类更强大、组织更严密。在恶魔建筑和强大施法者的支持下，他们可以轻易压制准备不足的冒险者。",al={"碧火小径很难吗","碧火小径危险"}}},fp="12,226,19.452.0,21.170.0,35.173.0,33.190.0"}
P.entries["subzone:jaedenar"] = {n="加德纳尔",s="加德纳尔是费伍德森林中心地带的一处被污染的洼地，建立在古老的暗夜精灵遗迹和德鲁伊兽穴之上。它的名字是为了向恶魔领主基尔加丹致以卑劣的敬意，它是暗影议会在北卡利姆多进行运作的主要基地。邪教徒、术士和被召唤的恶魔在这片堕落的洼地中徘徊，守护着通往暗影堡的地下入口。",h="加德纳尔是费伍德森林中心地带的一处被污染的洼地，建立在古老的暗夜精灵遗迹和德鲁伊兽穴之上。它的名字是为了向恶魔领主基尔加丹致以卑劣的敬意，它是暗影议会在北卡利姆多进行运作的主要基地。邪教徒、术士和被召唤的恶魔在这片堕落的...",kw={"兽穴","欺诈者","费伍德森林","加德纳尔","基尔加丹","暗影议会","暗影堡"},ang={["class:Druid"]="加德纳尔是对圣地的悲剧性亵渎；它的兽穴曾经是与翡翠梦境沟通的宁静避难所，现在却淹没在恶魔的污秽之中。",["class:Warlock"]="加德纳尔的术士们代表了暗影议会在艾泽拉斯持久的存在，他们公开召唤强大的恶魔，并挥舞着不稳定的邪能魔法。"},sec={{t="邪能崇拜的堡垒",b="很久以前，这些洼地曾是暗夜精灵的圣地，也是与翡翠梦境相连的沉睡德鲁伊的栖息之所。在第三次战争的浩劫之后，暗影议会的残党占据了这片山谷，并以恶魔领主基尔加丹的名字将其命名为加德纳尔。术士们——主要是叛逃的兽人和被遗忘者——与萨特、魅魔和邪卫们聚集于此。他们占据了地表的废墟和更深处的兽穴，将曾经神圣的林地扭曲成了一个阴森恐怖的恶魔召唤中心。"},{t="暗影堡的大门",b="在地表上，邪教徒们聚集在像欺诈者神祠这样的亵渎之地，燃烧着邪能火焰的火盆，并进行各种仪式以进一步腐蚀这片林地。地表之下是暗影堡的入口，那是一座地下要塞，议会真正的首领们在那里指挥着他们在费伍德森林的行动。翡翠圣地怀着深深的忧虑注视着这片溃烂的飞地，经常招募勇敢的漫游者去扰乱他们的召唤法阵，并熄灭封锁他们隧道的黑暗火焰。"}},faq={{q="加德纳尔是以什么命名的？",a="加德纳尔是由暗影议会命名的，旨在崇拜燃烧军团的最高指挥官之一，“欺诈者”基尔加丹。",al={"加德纳尔名字起源","为什么要叫加德纳尔","加德纳尔命名缘由"}},{q="谁控制着加德纳尔？",a="这座要塞由暗影议会把持，这是一个由凡人术士——主要是兽人和被遗忘者——组成的阴险组织，他们与被召唤的恶魔和堕落的萨特一起，服从于燃烧军团的恶魔意志。",al={"谁在管理加德纳尔","加德纳尔阵营","加德纳尔的敌人"}},{q="恶魔到来之前这里是什么样子的？",a="在第三次战争之前，该地区由古老的暗夜精灵建筑和宁静的德鲁伊兽穴组成，德鲁伊们曾在此安息，同时漫游于翡翠梦境之中。",al={"加德纳尔历史","谁曾经住在加德纳尔","加德纳尔兽穴"}},{q="什么是暗影堡？",a="暗影堡是加德纳尔之下的地下洞穴系统。它曾是德鲁伊的兽穴，如今却成为了暗影议会在费伍德森林的领导层的坚固总部。",al={"什么是暗影堡","加德纳尔洞穴","加德纳尔地下"}}},fp="8,370,24.534.0,28.529.0,29.132.0,22.210.0,40.165.0,24.191.0"}
P.entries["subzone:jagged-reef"] = {n="锯齿暗礁",s="锯齿暗礁构成了艾萨拉崎岖的北海岸，那里沙滩与嶙峋的岩石突起和翻腾的浪花交汇。暗礁潜伏在浅水之下，使得海上航行成为不可能。这片荒凉的海岸主要居住着游荡的多头蛇、食腐的纳迦、以及领地意识极强的鱼人部落。",h="锯齿暗礁构成了艾萨拉崎岖的北海岸，那里沙滩与嶙峋的岩石突起和翻腾的浪花交汇。暗礁潜伏在浅水之下，使得海上航行成为不可能。这片荒凉的海岸主要居住着游荡的多头蛇、食腐的纳迦、以及领地意识极强的鱼人部落。",kw={"艾萨拉","沙滩","海岸","多头蛇","锯齿暗礁","纳迦","鱼人","浅滩"},ang={["class:Hunter"]="裸露的北海岸为研究或驯服多头蛇和海岸甲壳类动物等原生两栖野兽提供了充足的机会。"},sec={{t="危险的海岸线",b="锯齿暗礁横跨艾萨拉的北缘，这是一片严酷的沿海地带，破碎的悬崖和突出的岩石将沙滩分割成一个个隐秘的小湾。在破碎的波浪之下，隐藏着淹没的礁石和变幻莫测的浅滩，使这里的水域成为了任何胆敢冒险靠近的船只的坟墓。在陆地上，这片狂野的海岸也无法提供多少安宁；覆盖着盐霜的野兽、掠食性的多头蛇和极具攻击性的纳迦在浪花线附近游荡，同时还有盘踞在此的鱼人，在潮汐中搜寻残羹和不留神的猎物。"}},faq={{q="锯齿暗礁位于哪里？",a="锯齿暗礁涵盖了艾萨拉的北海岸线，横跨该地区北岸的一系列沙滩、岩石突起和小海湾。",al={"锯齿暗礁位置","锯齿暗礁在哪里"}},{q="哪些生物栖息在锯齿暗礁？",a="海岸上到处都是危险的水生生物，包括具有攻击性的鱼人、贪婪的多头蛇，以及在浅水区和沙滩上游荡的披甲纳迦。",al={"这里有什么生物","锯齿暗礁怪物","锯齿暗礁里的野兽"}},{q="船只可以在锯齿暗礁周围的水域航行吗？",a="不能。该区域因其大量危险的水下岩石和不规则的浅滩而得名，对于任何船只来说，在此处通过礁石进行海上航行几乎等同于自杀。",al={"船只可以航行吗","锯齿暗礁航运"}},{q="暗礁沿岸有定居点吗？",a="锯齿暗礁沿岸没有任何文明定居点。除了路过的探险者或猎人外，这里唯一的有组织的存在就是散布在海岸各处的野生鱼人营地。",al={"锯齿暗礁附近的城镇","谁住在锯齿暗礁"}}},fp="11,320,20.546.0,33.162.0,39.183.0,53.183.0,41.191.0"}
P.entries["subzone:jaggedswine-farm"] = {n="野猪农场",s="野猪农场是一处简朴的牲畜养殖场，位于杜隆塔尔北部，就在奥格瑞玛正门南侧。它包含一座木制储藏棚、一个宽敞的围栏和一个泥泞的水坑，是为附近的部落首都饲养耐寒猪只的关键食物来源。",h="野猪农场是一处简朴的牲畜养殖场，位于杜隆塔尔北部，就在奥格瑞玛正门南侧。它包含一座木制储藏棚、一个宽敞的围栏和一个泥泞的水坑，是为附近的部落首都饲养耐寒猪只的关键食物来源。",kw={"野猪","杜隆塔尔","部落补给","野猪农场","奥格瑞玛","猪圈","猪","猪只"},ang={["faction:Horde"]="在杜隆塔尔干旱的荒地上建立稳定的肉类供应是关乎生存的大事，这使得像野猪农场这样的前哨站对于维持奥格瑞玛的军事实力至关重要。",["profession:Cooking"]="对于在杜隆塔尔学习厨艺的部落厨师来说，野猪农场周围大量的猪只使这里成为了获取鲜嫩排骨、猪肉块和烹饪用油的主要当地来源。"},sec={{t="首都的补给",b="野猪农场开垦于杜隆塔尔那片无情、被烈日烘烤的土地上，代表了维持像奥格瑞玛这样的城市堡垒所面临的严酷现实。该地区贫瘠的红土地产出的农作物很少，因此，强壮的牲畜对于养活数以千计的兽人战士和劳工至关重要。农场以一座木制仓库、一个宽大的木制围栏和一个天然水塘为中心，猪只在这里被放牧、繁育和屠宰，以确保部落的粮仓充足。"},{t="安静的边境",b="虽然在干燥炎热的气候下，这里显得安静且常年无人照看，但农场是当地牧猪人和巡逻的奥格瑞玛卫兵经常出没的地方。野生和成熟的猪只在围栏内外漫游，偶尔会考验附近守卫的耐心。该地块位于通往首都峡谷的入口处，在杜隆塔尔的日常后勤中是一个不起眼却不可或缺的前哨站。"}},faq={{q="野猪农场的作用是什么？",a="该农场负责饲养和管理猪只，为部落提供肉类和猪油，主要是为了供养附近奥格瑞玛的居民和驻军。",al={"什么是野猪农场","为什么杜隆塔尔会有猪农场","野猪农场用途"}},{q="野猪农场具体位于哪里？",a="它位于杜隆塔尔北部，就坐落在通往奥格瑞玛力量谷的南部入口和宏伟的大门外。",al={"野猪农场在哪里","如何前往野猪农场","猪农场杜隆塔尔位置"}},{q="为什么农场看起来有些荒凉？",a="在杜隆塔尔的兽人畜牧业讲究实用且不讲究排场。除了四处游荡的野猪和稀疏的木制结构外，这个养殖场没有宏伟的宅邸，但它仍在为部落的补给线积极运作。",al={"野猪农场被废弃了吗","谁住在野猪农场","为什么没有农民"}},{q="这里的猪对旅行者危险吗？",a="虽然圈内的家猪很温顺，但在郊外游荡的野生和成熟的野猪如果受到年轻旅行者或粗心采集者的惊扰，可能会具有攻击性。",al={"猪有敌意吗","这里的猪会攻击人吗","猪危险吗"}}},fx={["62544dd9"]={q="野猪农场是什么地方？",a="野猪农场是几处养猪农庄之一，位于杜隆塔尔北部、奥格瑞玛大门以南不远处。它的建立是为了向兽人首都提供必需的补给。这个简朴的聚居点包括一处牲畜围栏、一间储藏室和附近的一方水塘。这里为部落提供了生活所需，却暴露在城墙外干燥严酷的地带中。",al={"野猪农场是什么地方","野猪农场简介","介绍一下野猪农场"}},["00bf6885"]={q="野猪农场为何以此命名？",a="农场的名字源自这里饲养的独特鬃刺野猪，它们为日益壮大的奥格瑞玛人口提供食物。和杜隆塔尔严酷环境中生存的许多野兽一样，这些健壮的野兽长着粗糙的皮肤和尖锐的特征，适应峡谷平原贫瘠的黏土与岩石地貌。",al={"为何叫野猪农场","野猪农场名称由来"}}},fp="16,287,26.461.0,16.432.0,40.145.0,42.139.0,41.213.0,41.171.0"}
P.entries["subzone:jaguero-isle"] = {n="哈圭罗岛",s="哈圭罗岛是一座与世隔绝、覆盖着丛林的岛屿，坐落在荆棘谷蛮荒海岸的东海岸外。岛上遍布着凶猛的野生猎豹和大猩猩，因是被称为穆克拉大王的巨型银背大猩猩的领地而臭名昭著。",h="哈圭罗岛是一座与世隔绝、覆盖着丛林的岛屿，坐落在荆棘谷蛮荒海岸的东海岸外。岛上遍布着凶猛的野生猎豹和大猩猩，因是被称为穆克拉大王的巨型银背大猩猩的领地而臭名昭著。",kw={"大猩猩","哈圭罗","哈圭罗岛","穆克拉大王","猎豹","普巴尔公主","荆棘谷","蛮荒海岸"},ang={["class:Hunter"]="哈圭罗岛上充满异域风情的掠食者，从潜行的猎豹到强大的穆克拉大王本人，为经验丰富的猎人带来了不可抗拒的追踪挑战。",["race:Tauren"]="发现一位同胞牛头人被困在远离卡利姆多的地方，身陷凶猛野兽之中，这使得解救普巴尔公主成为了一件关乎个人荣誉的事情。"},sec={{t="原始领域",b="哈圭罗岛位于荆棘谷东南海岸外，远离大陆上的海盗营地和巨魔废墟。这座岛屿完全被未驯服的动物所占据，主要是猎豹和极具攻击性的大猩猩。在它们之上统治着的是巨大的类人猿穆克拉大王，他对岛屿岩石嶙峋的内陆拥有绝对的、排外的统治权。很少有水手愿意靠近其暗礁，尽管偶尔在大陆海滩上冲刷上岸的漂流瓶会承载着那些不幸被困在此岛上的人们发出的绝望求救信息。"},{t="被俘的公主",b="岛上最特殊也最危险的情况与普巴尔公主有关，这是一位被穆克拉大王囚禁的牛头人遇难者。她在漂流并被困在这个充满掠食者的岛屿上后，设法将装有求救信的瓶子投进蛮荒海岸的潮汐中，希望能有路过的冒险者敢于面对穆克拉的愤怒，帮助她逃出生天。"}},faq={{q="哈圭罗岛位于哪里？",a="哈圭罗岛坐落在无尽之海中，位于荆棘谷东南海岸外，蛮荒海岸的正东方。",al={"哈圭罗岛位置","哈圭罗在哪里","寻找哈圭罗岛"}},{q="穆克拉大王是谁？",a="穆克拉大王是一只统治着哈圭罗岛的巨大而强大的大猩猩。他领地意识极强且具有攻击性，统治着岛屿的内陆。",al={"穆克拉","穆克拉大王大猩猩","荆棘谷猩猩首领"}},{q="普巴尔公主是谁？",a="普巴尔公主是一名被困在哈圭罗岛上的牛头人，远离家乡。她将漂流瓶扔进大海，希望能获救。",al={"牛头人俘虏","普巴尔是谁","普巴尔公主"}},{q="如何开启前往该岛的任务？",a="冒险者们通常会通过发现冲刷在蛮荒海岸大陆海滩上的半掩在沙子里的瓶子来了解她的困境，瓶子里装有一封折叠整齐的求援信。",al={"漂流瓶任务","哈圭罗岛任务","如何前往哈圭罗"}}},fp="12,249,15.540.0,20.355.1,30.120.0,18.136.0,23.149.0,47.179.0"}
P.entries["subzone:janeiro-s-point"] = {n="加尼罗哨站",s="加尼罗哨站是一座小巧多岩的岛屿，位于荆棘谷南部的藏宝海湾港口外。岛上矗立着一座巨大的未知地精石像，它张开双臂，欢迎着过往的船只。岛屿周边水域和海岸由可怕的海巨人“切肉者”莫克拉什所占据。",h="加尼罗哨站是一座小巧多岩的岛屿，位于荆棘谷南部的藏宝海湾港口外。岛上矗立着一座巨大的未知地精石像，它张开双臂，欢迎着过往的船只。岛屿周边水域和海岸由可怕的海巨人“切肉者”莫克拉什所占据。",kw={"藏宝海湾","地精雕像","加尼罗哨站","切肉者莫克拉什","海巨人","荆棘谷"},sec={{t="海湾灯塔",b="加尼罗哨站是通往藏宝海湾的标志性门户，迎接每一艘驶入荆棘谷南部海域的船只。礁石顶端矗立着一座巨大的地精石像，它张开双臂，展现出一种宏大的欢迎姿态，同时也象征着毫无节制的商业野心。尽管数英里外的水手和海盗都能看见它，但由于“切肉者”莫克拉什（一位将该岛据为己有的恐怖海巨人）的存在，登岛探险极度危险。"}},faq={{q="加尼罗哨站是什么地方？",a="加尼罗哨站是一座位于荆棘谷藏宝海湾港口外海的小型岩石岛屿。它不仅是地精港口的视觉地标，也为靠近的船只提供了指引。",al={"加尼罗哨站","这座岛是什么","藏宝海湾雕像岛"}},{q="岛上的巨大雕像是什么人？",a="这座巨型雕像描绘了一位张开双臂的未知地精。它的建立旨在欢迎前往藏宝海湾这一商业避风港的贸易船只和疲惫的水手。",al={"雕像身份","地精雕像是谁","雕像是谁"}},{q="什么危险的生物居住在加尼罗哨站？",a="这座岛屿及其周边的浅滩是“切肉者”莫克拉什的领地，这是一位强大的海巨人，对于任何试图接近雕像的冒险水手或游泳者来说，他都是极大的威胁。",al={"海巨人岛屿","谁住在加尼罗哨站","莫克拉什"}}},fp="15,342,17.496.0,24.178.0,38.163.0,49.205.0"}
P.entries["subzone:jangolode-mine"] = {n="詹戈洛德矿洞",s="詹戈洛德矿洞是一处位于西部荒野连绵丘陵中的富矿开采点。这里曾是暴风城矿石和原材料的重要来源，但现在已被迪菲亚潜行者盗贼团所占据。",h="詹戈洛德矿洞是一处位于西部荒野连绵丘陵中的富矿开采点。这里曾是暴风城矿石和原材料的重要来源，但现在已被迪菲亚潜行者盗贼团所占据。",kw={"迪菲亚潜行者","詹戈洛德","詹戈洛德矿洞","狗头人","暴风城","西部荒野"},ang={["faction:Alliance"]="收复西部荒野的资源对稳定王国至关重要，而将盗贼从詹戈洛德驱逐出去，是恢复该地区繁荣的一步。",["profession:Mining"]="詹戈洛德矿洞依然富含基础的铜矿和锡矿，对于愿意杀退那些地下害虫的勘探者来说，这里依然是一个有利可图的去处。"},sec={{t="被掠夺的资源",b="在西部荒野衰落之前，詹戈洛德矿洞曾稳定地为暴风城提供重建和补给所需的关键金属。随着社会秩序的恶化以及王国撤回了驻军，迪菲亚潜行者夺取了该矿洞的控制权，以维持他们自己的运作。盗贼们现在独自开采着这些富矿脉，并顽强地保卫着他们的地下战利品。"}},faq={{q="詹戈洛德矿洞是什么？",a="它是西部荒野的一处开采点，在历史上曾为暴风城提供过必需的矿物和金属矿石。随着区域防御力量的削弱，它落入了敌对势力之手。",al={"詹戈洛德矿洞信息","詹戈洛德是什么","詹戈洛德西部荒野"}},{q="目前是谁控制着这座矿洞？",a="迪菲亚潜行者掌控着底下的矿井，他们驱逐了原来的矿工，以此来为自己的运作提供资源。",al={"谁在詹戈洛德矿洞","詹戈洛德怪物","谁住在詹戈洛德"}},{q="为什么暴风城不收复这座矿洞？",a="暴风城深陷政治动荡之中，甚至难以保护其核心疆域。王国缺乏足够的部队来驻守西部荒野的外围矿洞，只能任由人民民兵和当地冒险者来应对这一威胁。",al={"为什么暴风城不清理詹戈洛德","暴风城驻军西部荒野","为何放弃矿洞"}}},fx={["18816b92"]={q="詹戈洛德矿洞发生了什么？",a="詹戈洛德矿洞曾是暴风王国重要的矿产来源，为首都提供石料和矿石。西部荒野的王国势力开始瓦解后，迪菲亚潜行者夺取了矿区，如今占据矿井，不让任何人和平采矿。",al={"詹戈洛德矿洞历史","詹戈洛德矿洞发生了什么","詹戈洛德矿洞往事"}},dff54742={q="詹戈洛德矿洞危险吗？",a="是的，那里极其危险。迪菲亚强盗占据矿井，凶狠地守卫着富饶的矿脉，任何靠近的人都会遭到攻击；粗心的冒险者很容易被困在地下。",al={"詹戈洛德矿洞危险吗","詹戈洛德矿洞的危险","詹戈洛德安全吗"}}},fp="14,217,20.391.0,27.177.0,32.120.0,40.228.0"}
P.entries["subzone:jansen-stead"] = {n="贾森农场",s="贾森农场是西部荒野最北端的农场，位于通往艾尔文森林的桥梁路旁。像周边大部分粮仓一样，这个宅地已经不再由农民所有，而是被失控的机械收割傀儡和游荡的迪菲亚潜行者强盗所占据。",h="贾森农场是西部荒野最北端的农场，位于通往艾尔文森林的桥梁路旁。像周边大部分粮仓一样，这个宅地已经不再由农民所有，而是被失控的机械收割傀儡和游荡的迪菲亚潜行者强盗所占据。",kw={"迪菲亚","农场","法布隆","收割傀儡","贾森","西部荒野"},ang={["faction:Alliance"]="这个农场的沦陷突显了暴风城领导层在保卫自身边境方面的失败，使毫无防备的农民在离艾尔文森林视线可及的地方任由不法之徒摆布。",["race:Human"]="对于从北郡和艾尔文森林相对和平的环境中跨界而来的人类来说，贾森农场的废墟为他们带来了残酷的警醒，让他们看到了导致暴风城农村腹地陷入瘫痪的经济危机和强盗行径。"},sec={{t="沦陷的农场",b="贾森农场位于艾尔文边界处，代表了任何向西进入西部荒野的旅行者所面临的残酷现实。这里曾经是一个为王国提供食物的繁荣家庭农场，但其合法的居住者已被日益增长的动乱驱逐。取而代之的是，充满敌意的收割傀儡——与迪菲亚潜行者有关的机械构装体——与强盗一同巡视着荒废的田野。它靠近主路的地理位置，使它成为往返于闪金镇和哨兵岭之间的信使和旅行者面临的首要隐患。"}},faq={{q="贾森农场在哪里？",a="当你从艾尔文森林穿过河上的桥梁进入西部荒野东北部时，它就在道路右侧的第一个农场。",al={"贾森农场位置","贾森农场在哪里","西部荒野贾森农场"}},{q="现在是谁住在贾森农场？",a="农场最初的居民已被驱逐。如今，杂草丛生的田野和破旧的农舍已被充满敌意的收割傀儡和效忠于迪菲亚潜行者的盗匪所占据。",al={"贾森农场里有什么人","贾森农场的居民","贾森农场的怪物"}},{q="为什么这里的机械稻草人会攻击人？",a="收割傀儡是攻击西部荒野居民的机械构装体。它们与迪菲亚潜行者的爪牙一起巡视农场。它们的确切起源尚不清楚。",al={"为什么收割傀儡会攻击人","西部荒野机械傀儡","迪菲亚稻草人"}},{q="附近有谁在寻求帮助？",a="在桥梁以南，靠近贾森农场入口处，农夫法布隆和他的妻子维尔娜在他们损坏的马车旁扎了营，他们被迫离开了自己位于路下方的南瓜田。",al={"贾森农场附近的任务","法布隆的位置","艾尔文桥附近谁提供任务"}}},fx={["333dbf90"]={q="贾森农场是什么地方？",a="贾森农场是西部荒野最北端的农庄，位于通往艾尔文森林的桥梁外侧不远处。它曾是宁静的农庄，为暴风王国提供粮食，如今却杂草丛生，合法主人早已离去。和这片地区的大部分地方一样，它也因席卷整个省份的动乱而遭到侵占。",al={"贾森农场是什么地方","西部荒野贾森农场","关于贾森农场"}},["49f2e125"]={q="贾森农场发生了什么？",a="迪菲亚潜行者在西部荒野各地起事后，当地农民失去了王室的保护。迪菲亚把土地所有者赶出田地，贾森农场就此荒废，落入盗贼和失控的收割傀儡之手。",al={"贾森农场发生了什么","贾森农场历史","贾森农场如何沦为废墟"}},["2506f287"]={q="贾森农场为何沦为废墟？",a="迪菲亚潜行者控制乡野后，这座农场便被遗弃了。失去暴风城军队的保护，耕种这些田地的家族别无选择，只能逃离，任由农庄在亡命之徒和失控机械的控制下日渐荒废。",al={"贾森农场为何被遗弃","是谁毁了贾森农场","贾森农场为何荒废"}},["159e6b3b"]={q="为什么叫贾森农场？",a="这座农场名为贾森农场，但其昔日主人的身份和名称由来均未见记载。",al={"为什么叫贾森农场","贾森是谁","贾森农场名称由来"}}},fp="12,287,18.552.0,30.142.0,36.188.0,52.162.0,30.196.0"}
P.entries["subzone:jasperlode-mine"] = {n="玉石矿洞",s="玉石矿洞是艾尔文森林中北部的一处铁矿和矿石开采场，曾经为暴风城提供过重要的资源。如今，矿井中挤满了狗头人和致命的巨型蜘蛛，使得资源匮乏的王国无法将其收复。",h="玉石矿洞是艾尔文森林中北部的一处铁矿和矿石开采场，曾经为暴风城提供过重要的资源。如今，矿井中挤满了狗头人和致命的巨型蜘蛛，使得资源匮乏的王国无法将其收复。",kw={"艾尔文森林","法戈第矿洞","金砂","闪金镇","玉石矿洞","狗头人","治安官杜汉","牙母"},ang={["faction:Alliance"]="在王国边境时刻面临危险的时期，从玉石矿洞获取原始金属对于维持暴风城的装备补给至关重要。",["profession:Mining"]="玉石矿洞矿脉丰富，对于那些愿意冲破狗头人的矿镐和蜘蛛网来宣示所有权的勘探者来说，它仍然是一个诱人的目标。"},sec={{t="艾尔文森林中丢失的资源",b="玉石矿洞在历史上曾是暴风城产量最高的矿区之一，与附近的法戈第矿洞一同提供了稳定的矿产财富。由于王国的军队因抵御外部威胁和动荡而兵力吃紧，当地驻军无力保护矿井。狗头人趁机钻入矿洞，赶走了人类矿工，并囤积了偷来的金子和牛脂蜡烛。"},{t="深处的危险",b="玉石矿洞内的虫患不仅仅是害虫那么简单。在木质支撑结构下最深、最黑暗的走廊里，一群凶猛的矿洞蜘蛛在此扎根。在当地人称为“牙母”的巨大母蛛带领下，这些蜘蛛将闯入的狗头人——以及任何不慎的勘探者——视为轻而易举的猎物，这使得任何尝试回收矿洞的行动都变得异常危险。"}},faq={{q="为什么玉石矿洞会被占领？",a="暴风城的常备军在王国各地兵力分散，导致闪金镇这样的乡村哨所人手不足。一旦人类矿工失去了守卫的保护，投机的狗头人便迅速涌入了挖掘现场。",al={"为什么会有狗头人","谁控制着玉石矿洞","为什么会被废弃"}},{q="玉石矿洞和法戈第矿洞有什么区别？",a="法戈第矿洞位于南部，靠近马科伦农场和斯通菲尔德农场，而玉石矿洞则坐落在北部的河流附近山脚下。两者都是艾尔文森林主要的矿区，现已被狗头人侵占。",al={"玉石矿洞与法戈第矿洞的区别","艾尔文森林的其他矿洞"}},{q="矿洞深处潜伏着什么？",a="最深处的矿井中充斥着掠食性的矿洞蜘蛛，由一只被称为“牙母”的巨大蛛形生物领导。即便是占据此地的狗头人也会避开它们的蛛网洞穴。",al={"玉石矿洞里的蜘蛛","牙母","矿洞底部有什么"}},{q="为什么治安官杜汉没有清理这个矿洞？",a="治安官杜汉缺乏足够的兵力来进行长期的地下清理行动。面对迪菲亚兄弟会的河流巡逻、豺狼人的入侵以及驻军职责，当地民兵必须依靠游历的冒险者来侦察并清除内部的威胁。",al={"为什么没有暴风城守卫","治安官杜汉派遣士兵"}}},fx={ae82ecd7={q="玉石矿洞是什么地方？",al={"玉石矿洞是什么","关于玉石矿洞","艾尔文森林玉石矿洞"}},d5d7dec2={q="玉石矿洞发生了什么？",a="玉石矿洞曾在暴风城的监管下稳定运作，为王国的战争提供新开采的矿石。当王国军力捉襟见肘，又忙于应对其他地区的威胁时，大群伺机而动的狗头人涌入隧道，赶走矿工，将矿脉据为己有。",al={"玉石矿洞历史","玉石矿洞发生了什么","玉石矿洞背景故事"}},["6ca2598d"]={q="玉石矿洞危险吗？",a="粗心的旅人若进入玉石矿洞，将面临极大危险。洞中不仅到处都是领地意识极强的狗头人，它们会凶狠地守护自己的蜡烛和挖掘地点，最深处的洞穴还栖息着一群掠食性矿洞蜘蛛，由凶残的蛛后“毒牙母蛛”率领。没有武器又不留神就闯入黑暗之中，很容易丧命。",al={"玉石矿洞有多危险","玉石矿洞安全吗","玉石矿洞的威胁"}}},fp="15,272,25.414.0,19.391.0,31.218.0,56.215.0,35.162.0,43.235.0"}
P.entries["subzone:jerod-s-landing"] = {n="杰罗德码头",s="杰罗德码头是一处朴素的河岸码头，坐落在纳兹费雷提河的艾尔文森林一侧。目前它已被迪菲亚潜行者占领，这处前哨站成为了他们走私非法货物通过王国水路的秘密转运点。",h="杰罗德码头是一处朴素的河岸码头，坐落在纳兹费雷提河的艾尔文森林一侧。目前它已被迪菲亚潜行者占领，这处前哨站成为了他们走私非法货物通过王国水路的秘密转运点。",kw={"迪菲亚码头主管","杰罗德码头","klaven's tower","mathias shaw","纳兹费雷提河","走私","抢夺货物"},ang={["class:Rogue"]="受军情七处委派的潜行者会被派遣到杰罗德码头测试他们的潜行能力，从迪菲亚码头主管身上扒窃，并找回敏感的贸易账簿。",["faction:Alliance"]="杰罗德码头的被占领凸显了迪菲亚已经彻底控制了连接艾尔文森林与赤脊山的内陆水路，而且这一切就发生在暴风城的眼皮底下。"},sec={{t="走私者的中转站",b="杰罗德码头隐藏在纳兹费雷提河的东岸，提供连接艾尔文森林与周边领地的水路通道。虽然最初只是一个普通的船坞，但现在该地点已完全落入迪菲亚潜行者手中。在一名迪菲亚码头主管的严密监视下，这些不法之徒将码头作为枢纽，接收从赤脊山劫掠而来的货物，并将河运货物悄悄向下游运送，直至西部荒野的Klaven's Tower等地。"},{t="暗影之眼",b="由于其在河流上的战略位置，杰罗德码头引起了暴风城秘密情报组织——军情七处的注意。监控迪菲亚行动的特工们视该码头为这个犯罪集团补给线上的关键环节，他们会派遣足智多谋的潜行者潜入码头，窃取河运货物的账簿，并揭开那条扼杀王国的巨大阴谋。"}},faq={{q="杰罗德码头位于何处？",a="杰罗德码头位于艾尔文森林东部，坐落在纳兹费雷提河的西岸，那里是艾尔文森林与赤脊山的分界线。",al={"杰罗德码头位置","杰罗德码头在哪里","杰罗德码头地图"}},{q="谁控制着杰罗德码头？",a="该码头已被迪菲亚潜行者占据，由一名迪菲亚码头主管领导，他负责与守卫岸边的武装强盗协调货物运输。",al={"谁在杰罗德码头","杰罗德码头的迪菲亚","杰罗德码头怪物"}},{q="迪菲亚利用这个码头有什么目的？",a="兄弟会利用这个码头作为走私中转站，将从赤脊山截获的被盗货物和武器运往西部荒野的Klaven's Tower等暴徒据点。",al={"迪菲亚为何使用杰罗德码头","迪菲亚河流走私"}},{q="为什么军情七处对杰罗德码头感兴趣？",a="马迪亚斯·肖尔大师和他的情报特工通过这个码头追踪迪菲亚违禁品的流动，以揭露连接西部荒野、艾尔文森林和赤脊山的网络。",al={"军情七处杰罗德码头","潜行者杰罗德码头任务"}}},fx={d69927bb={q="杰罗德码头是什么地方？",a="杰罗德码头是位于纳菲瑞提河艾尔文森林一侧岸边的一座小型船坞。它曾只是个简单的渡口和码头，如今却落入罪犯之手。他们利用这里偏僻的河岸位置，在暴风城卫兵的视线之外策划秘密行动。",al={"杰罗德码头是什么","艾尔文森林杰罗德码头","关于杰罗德码头"}},["096cd4eb"]={q="谁住在杰罗德码头，或负责管理那里？",a="杰罗德码头由迪菲亚潜行者占据，并由他们的码头管理员及其手下在当地看守。这些强盗控制着滨水地带，凭借武力和警戒看管运来的货物，并阻止外人接近他们的河上贸易。",al={"谁管理杰罗德码头","杰罗德码头码头管理员","杰罗德码头有哪些人"}},["51e45e55"]={q="杰罗德码头危险吗？",a="危险。码头上到处都是全副武装的迪菲亚走私犯和暴徒，任何徘徊在他们走私活动附近的旅人或联盟斥候都可能遭到杀害。若不加提防地靠近岸边，立刻就会招来暴力袭击。",al={"杰罗德码头安全吗","杰罗德码头有多危险","杰罗德码头的敌人"}}},fp="15,255,21.490.0,19.384.1,33.175.0,29.163.0,48.194.0,42.163.0"}
P.entries["subzone:karazhan"] = {n="卡拉赞",s="卡拉赞是一座不祥且与世隔绝的塔楼，矗立在逆风小径的南端。这里曾是提瑞斯法最后一位守护者麦迪文的密室，这座城堡坐落在一处强大的魔法脉络交汇点之上，扭曲了周围的时间、空间和现实。尽管麦迪文在第一次战争中被杀，但这座废弃的要塞中依然回荡着不稳定的奥术能量、不安的灵魂以及潜藏的危险。",h="卡拉赞是一座不祥且与世隔绝的塔楼，矗立在逆风小径的南端。这里曾是提瑞斯法最后一位守护者麦迪文的密室，这座城堡坐落在一处强大的魔法脉络交汇点之上，扭曲了周围的时间、空间和现实。尽管麦迪文在第一次战争中被杀，但这座废弃的要塞...",kw={"艾格文","黑暗骑手","逆风小径","守护者","卡拉赞","卡德加","麦迪文","莫罗斯","萨格拉斯","提瑞斯法"},ang={["class:Mage"]="卡拉赞是凡人巫术巅峰与危险的纪念碑。它收藏了一系列无与伦比的神器和著作，这些曾经被肯瑞托拒之门外的宝藏，虽然其不稳定的魔法脉络威胁着任何粗心的施法者。",["faction:Alliance"]="这座塔对于暴风城王国具有悲剧性的意义。它是麦迪文的家——莱恩·乌瑞恩国王和安度因·洛萨的儿时好友——他在这些围墙内的背叛将第一次战争引向了人类。"},sec={{t="守护者之塔",b="早在第一次战争之前，卡拉赞之塔就建立在一块形状如人类颅骨的土地上，位于一个巨大的神秘魔法脉络枢纽之上。它曾是守护者麦迪文的隐居之所，也是无数魔法秘密的藏宝库。在弯曲的走廊内，麦迪文与他忠诚的管家莫罗斯一起生活，接待贵客，并收藏了海量的奥术文献和文物，其藏书甚至超过了肯瑞托的图书馆。然而，这座塔也成为了艾泽拉斯最大背叛的舞台，因为麦迪文陷入了萨格拉斯的恶魔附身，并暗中策划了黑暗之门的开启。"},{t="闹鬼的门槛",b="在安度因·洛萨和他的学徒卡德加联手击杀麦迪文后，卡拉赞便封锁了大门，任其荒废。然而，这座塔从未真正沉睡。其交汇的强大魔法脉络继续扭曲着现实的结构，在逆风小径上投射出幽灵般的幻影、幻象和时间扭曲。一直有传言称，某种邪恶的存在再次在安静的要塞中苏醒，而奇怪的实体——包括搜寻周围土地以寻找遗忘文物的阴影黑暗骑手——正不可抗拒地被吸引到这座高耸的建筑旁。"}},faq={{q="谁建造了卡拉赞？",a="卡拉赞的起源笼罩在神秘之中，但它最广为人知的是作为提瑞斯法最后一位守护者麦迪文的塔楼。它是在第一次战争很久之前建立在一块形状如人类颅骨的土地上的，坐落在逆风小径的一个强大的魔法脉络枢纽之上。",al={"谁建造了卡拉赞","卡拉赞的创造者","卡拉赞的起源"}},{q="麦迪文是谁，他为什么要住在这里？",a="麦迪文是艾格文之子，也是提瑞斯法最后一位守护者，肩负着保卫艾泽拉斯免受恶魔威胁的使命。他将卡拉赞作为自己的主要住所和避难所，周围环绕着大量的奥术知识储备、像莫罗斯这样的仆人，并举办奢华的聚会，以掩盖他走向疯狂的过程。",al={"谁住在卡拉赞","麦迪文背景故事","最后一位守护者"}},{q="麦迪文在塔里发生了什么事？",a="世人不知的是，麦迪文从出生起就被黑暗泰坦萨格拉斯的灵魂附身。在这一恶魔影响下，他利用塔内的魔法联系了术士古尔丹并开启了黑暗之门。在发现他的背叛后，他的学徒卡德加、安度因·洛萨爵士和半兽人迦罗娜潜入了卡拉赞并击杀了这位守护者，终结了他的腐化。",al={"麦迪文是怎么死的","麦迪文之死","麦迪文的堕落"}},{q="我现在能进入卡拉赞吗？",a="不能。塔楼的正门和门槛仍然紧紧关闭，并设有防止入侵者的结界。虽然旅行者可以在废弃的村庄、坍塌的教堂和周围阴暗的地下室中游荡，但塔楼本身是紧闭的。",al={"我可以进入卡拉赞吗","卡拉赞开放了吗","进入卡拉赞"}},{q="为什么卡拉赞周围的地区如此腐败和荒凉？",a="卡拉赞坐落在一个巨大的魔法脉络枢纽之上，其原始能量扭曲了周围的地区。再加上麦迪文在内部释放的黑暗恶魔邪术，周围的峡谷枯萎成了被称为逆风小径的荒凉之地。",al={"为什么逆风小径是荒凉的","卡拉赞的诅咒","为什么逆风小径空无一人"}},{q="与这座塔有关的黑暗骑手是谁？",a="黑暗骑手是一群冷酷无情的文物猎人，出没于暮色森林和逆风小径周围的土地上，猎杀强大的神器。他们究竟是谁，以及什么东西将他们与这座塔联系在一起，仍然是一个谜。",al={"什么是黑暗骑手","逆风小径的骑手","卡拉赞的骑手"}}},fp="8,395,20.638.0,19.587.0,19.254.0,41.302.0,37.380.0,33.255.0,54.242.0,47.214.0"}
P.entries["subzone:kargath"] = {n="卡加斯",s="卡加斯是位于荒芜之地西部的一座坚固的部落前哨站，也是部落在卡兹莫丹唯一的立足点。该定居点由卡加斯远征军在萨尔大酋长的命令下建立，是连接东部王国各地的关键交通枢纽，同时也是向黑石山和奥达曼挖掘场发起行动的基地。",h="卡加斯是位于荒芜之地西部的一座坚固的部落前哨站，也是部落在卡兹莫丹唯一的立足点。该定居点由卡加斯远征军在萨尔大酋长的命令下建立，是连接东部王国各地的关键交通枢纽，同时也是向黑石山和奥达曼挖掘场发起行动的基地。",kw={"荒芜之地","黑石山","远征军","卡加斯","卡加斯·刃拳","碎手氏族","萨尔","奥达曼"},ang={["faction:Horde"]="卡加斯是部落在整个卡兹莫丹唯一的友好堡垒，提供必要的补给、飞行连接以及打击黑石山的出发点。",["race:Orc"]="该前哨站承载着酋长卡加斯·刃拳的名字，直接推进了萨尔铲除雷德·黑手腐化的黑石氏族的战役。"},sec={{t="敌对领土上的堡垒",b="为了纪念碎手氏族酋长卡加斯·刃拳，这座前哨站被命名为卡加斯，它是部落在整个卡兹莫丹山脉地区唯一的定居点。在荒凉的土地、充满攻击性的野生生物和敌对的矮人派系包围下，这座驻军点为横跨大陆的旅行者提供了重要的中转避难所。其飞行管理员连接着北方的幽暗城和落锤镇，以及南方的斯通纳德和格罗姆高营地，架起了跨越长距离的桥梁。"},{t="远征任务",b="受萨尔大酋长的直接命令派遣，卡加斯远征军在这一地区执行双重目标。部队经常深入奥达曼的古代泰坦大厅，探究铁炉堡的探矿者为何如此看重这个挖掘场。与此同时，侦察兵们正努力在灼热峡谷开辟一条通往黑石山的道路，试图打击雷德·黑手伪造的“黑石氏族”，同时与根深蒂固的黑铁矮人作战。"}},faq={{q="为什么这座部落城镇会建在荒芜之地的中间？",a="萨尔大酋长命令卡加斯远征军建立该前哨站，旨在巩固区域据点，探寻奥达曼矮人挖掘场的秘密，并开辟一条针对黑石氏族的入侵通道，直指黑石山。",al={"卡加斯为什么在这里","卡加斯的目的","谁建立了卡加斯"}},{q="卡加斯是以谁的名字命名的？",a="该前哨站以兽人碎手氏族的著名酋长卡加斯·刃拳的名字命名。",al={"卡加斯名称由来","卡加斯是谁","卡加斯·刃拳前哨站"}},{q="为什么从卡加斯出发的飞行航线如此重要？",a="卡加斯是连接洛丹伦北部（如幽暗城和落锤镇）的部落前哨站与南部（如荆棘谷和悲伤沼泽）领土的重要后勤枢纽。",al={"卡加斯飞行航线","为什么飞往卡加斯"}},{q="卡加斯的驻军正在准备对付什么威胁？",a="驻军经常与当地的黑铁矮人交战，调查铁炉堡在奥达曼的存在，并准备对盘踞在黑石山内的雷德·黑手及其敌对的黑石氏族发动进攻。",al={"卡加斯的敌人","卡加斯与谁作战"}}},fp="7,349,30.500.0,25.467.0,57.240.0,27.97.0,52.206.0,58.221.0"}
P.entries["subzone:kargathia-keep"] = {n="卡加希亚要塞",s="卡加希亚要塞是一座加固的部落据点，位于灰谷战歌伐木营地的东部前线。作为该前哨站监工的指挥部，它守卫着河流边界，并确保直接通往奥格瑞玛的快速增援路线。",h="卡加希亚要塞是一座加固的部落据点，位于灰谷战歌伐木营地的东部前线。作为该前哨站监工的指挥部，它守卫着河流边界，并确保直接通往奥格瑞玛的快速增援路线。",kw={"灰谷","卡加斯·刃拳","卡加希亚要塞","卡加希亚前哨站","监工格萨克","怒水河","战歌伐木营地"},ang={["faction:Horde"]="对于部落的防御者来说，卡加希亚要塞是灰谷前线上不可或缺的避难所，确保了对奥格瑞玛建设至关重要的珍贵木材运输。",["race:NightElf"]="对暗夜精灵来说，这座布满尖刺的据点代表了部落对他们神圣的祖先森林进行的激进且根深蒂固的入侵。"},sec={{t="怒水河上的堡垒",b="卡加希亚要塞坐落在战歌伐木营地的东缘，怒水河以西，是部落在灰谷进行伐木作业的Command Center。这座加固的前哨站升级了沉重的尖刺路障，驻扎着监工格萨克和他的军官。它在河流边界的战略位置使得战歌氏族能够监视入侵行动，并在暗夜精灵散兵发起袭击时，直接从邻近的杜隆塔尔和奥格瑞玛获得快速增援。"},{t="向刃拳致敬",b="就像荒芜之地的卡加斯要塞和杜隆塔尔海岸边的刃拳海湾一样，这座前哨站以著名的酋长卡加斯·刃拳的名字命名。对于在灰谷充满敌意的林地中冒险的战歌兽人来说，要塞宏伟的经典建筑是他们在暗夜精灵声称拥有的领土上保持军事韧性和部落反抗精神的持久象征。"}},faq={{q="卡加希亚要塞位于哪里？",a="卡加希亚要塞位于灰谷东部，在战歌伐木营地的东缘，怒水河以西。",al={"卡加希亚要塞位置","卡加希亚要塞在哪里","卡加希亚前哨站位置"}},{q="谁领导这座要塞？",a="监工格萨克在卡加希亚要塞内指挥战歌伐木营地，负责指导伐木作业并协调针对联盟攻击的防御。",al={"谁负责卡加希亚要塞","卡加希亚要塞领袖","监工格萨克"}},{q="为什么这座要塞被命名为卡加希亚？",a="这座据点是为了纪念碎手氏族的传奇酋长卡加斯·刃拳而命名的，与荒芜之地的卡加斯和杜隆塔尔的刃拳海湾共享这一命名传统。",al={"卡加希亚要塞以谁命名","卡加斯·刃拳","为什么叫卡加希亚"}},{q="这座据点的战略目的是什么？",a="该要塞控制着沿怒水河的伐木营地东部边界，确保了重要的补给路线，并使军队能够从奥格瑞玛快速跨河增援。",al={"为什么要有卡加希亚要塞","卡加希亚要塞的目的","卡加希亚要塞的重要性"}}},fx={["95145ea7"]={q="卡加希亚要塞是什么地方？",al={"卡加希亚要塞是什么","卡加希亚要塞传说","关于卡加希亚要塞"}},["30f293af"]={q="谁住在卡加希亚要塞，或负责管理那里？",a="这座要塞是战歌氏族军官的总部。其中最重要的是监工戈萨克，这名兽人指挥官负责管理战歌伐木营地，并指挥该地区的部落劳工和防卫力量。",al={"谁住在卡加希亚要塞","卡加希亚要塞有哪些人","谁控制卡加希亚要塞"}},feb769b0={q="卡加希亚要塞危险吗？",a="对部落旅人来说，卡加希亚要塞是安全的庇护所，厚重的尖刺路障能提供保护。对联盟闯入者而言，这里则是险地：要塞驻守着大量久经沙场的战歌战士，一旦遭到攻击，还能迅速从奥格瑞玛调集援军。",al={"卡加希亚要塞危险吗","卡加希亚要塞安全吗","卡加希亚要塞面临的威胁"}}},fp="14,261,26.521.0,22.373.0,32.129.0,19.158.0,33.195.0,49.185.0"}
P.entries["subzone:kharanos"] = {n="卡拉诺斯",s="卡拉诺斯是位于丹莫罗雪山中心的一处繁华山地聚落，距离铁炉堡仅一步之遥。作为从寒脊山谷出发的旅行者的主要枢纽，镇上设有一座锻炉、侏儒工坊以及著名的雷酒酿制厂。",h="卡拉诺斯是位于丹莫罗雪山中心的一处繁华山地聚落，距离铁炉堡仅一步之遥。作为从寒脊山谷出发的旅行者的主要枢纽，镇上设有一座锻炉、侏儒工坊以及著名的雷酒酿制厂。",kw={"酿制厂","丹莫罗","霜鬃","卡拉诺斯","闪光岭","雷酒"},ang={["race:Dwarf"]="对于离开寒脊山谷避风岩壁的矮人来说，卡拉诺斯是他们初次领略广阔王国风情的起点，这里充满了冒着热气的锻炉和雷酒氏族传说中的烈性啤酒。",["race:Gnome"]="来自诺莫瑞根的难民和工匠经常以卡拉诺斯及其周边地区为基地，与当地铁匠合作，并在附近的补给站开展工作。"},sec={{t="充满活力的边境避风港",b="卡拉诺斯坐落在丹莫罗的中轴大道旁，是迎接从安威玛尔远道而来的新兵们的第一个真正意义上的城镇。尽管这里寒风凛冽，但凭借当地矮人的坚韧和侏儒的奇思妙想，聚落依然欣欣向荣。城镇的中心是一座火光熊熊的公共锻炉和雷酒酿制厂，该酿制厂因生产卡兹莫丹最顶级的麦芽酒而在东部山脉享有盛誉。这里不仅汇集了忙碌的工匠，还有寻找温暖的疲惫旅人，是经营低海拔山峰地区业务的必经之地。"},{t="低地守卫者",b="在温暖的炉火背后，卡拉诺斯也是一个至关重要的军事前哨，肩负着确保山路安全的重任。凶猛的本土温迪戈在正西方的冰冻洞穴中潜行，而好斗的霜鬃巨魔则盘踞在西北方的闪光岭上。由于铁炉堡的正规军兵力分散在王国各地，小镇主要依靠往来的冒险者和当地哨兵来击退突袭者、清除危险的捕食者，并确保贸易路线畅通无阻。"}},faq={{q="卡拉诺斯是什么地方？",a="卡拉诺斯是丹莫罗中部主要的矮人和侏儒聚落。它连接着寒脊山谷、铁炉堡和外围荒野，是一个交通枢纽，提供必要的贸易、训练服务和旅店。",al={"卡拉诺斯概览","卡拉诺斯在哪里","卡拉诺斯城镇"}},{q="卡拉诺斯提供哪些服务和设施？",a="镇上设有著名的雷酒酿制厂，兼作旅店和酒馆，此外还有一座大型公共锻炉，以及职业和专业训练师。附近的工坊（如钢架补给站）则提供机械工程补给。",al={"卡拉诺斯训练师","卡拉诺斯有什么","卡拉诺斯旅店"}},{q="有哪些威胁危及小镇？",a="卡拉诺斯时刻面临着盘踞在西北方闪光岭上的好斗霜鬃巨魔部落的压力，此外，在正西方的冰冻洞穴中出没的食肉温迪戈也是一大威胁。",al={"卡拉诺斯敌人","卡拉诺斯的霜鬃巨魔","卡拉诺斯的温迪戈"}}},fx={["2ba82cf7"]={q="谁住在卡拉诺斯？",a="卡拉诺斯是一座繁荣的聚居地，居民以铜须矮人为主，也有侏儒难民和工程师。工匠、铁匠、酿酒师和新兵在此往来，常去当地的熔炉、侏儒工坊以及著名的雷酒酿制厂。这里没有公开统治一切的领主，却是铁炉堡驻扎在丹莫罗的军队不可或缺的本地枢纽和驻军据点。",al={"谁住在卡拉诺斯","谁管理卡拉诺斯","卡拉诺斯居民"}},d56d3e20={q="卡拉诺斯危险吗？",a="城镇本身有矮人巡逻队严密守卫，十分安全，但周边荒野始终危机四伏。凶暴的温迪戈在西边的洞穴中出没，敌对的霜鬃巨魔则在西北方闪光岭的要塞据点盘踞。城镇始终保持高度戒备，定期派遣新兵抵御丹莫罗的掠食者和步步逼近的巨魔。",al={"卡拉诺斯安全吗","卡拉诺斯的危险","卡拉诺斯的威胁"}}},fp="8,268,23.544.0,21.508.0,17.221.0,45.237.0,31.190.0"}
P.entries["subzone:kodo-graveyard"] = {n="科多兽坟场",s="科多兽坟场位于凄凉之地的中部，是一片广袤的区域，遍布着远古巨兽硕大且泛白的遗骸。出于本能或传统，年老垂死的科多兽会进行最后的朝圣之旅，来到这个荒凉的洼地，在祖先的肋骨间倒下。",h="科多兽坟场位于凄凉之地的中部，是一片广袤的区域，遍布着远古巨兽硕大且泛白的遗骸。出于本能或传统，年老垂死的科多兽会进行最后的朝圣之旅，来到这个荒凉的洼地，在祖先的肋骨间倒下。",kw={"凄凉之地","幽灵岗哨","墓地苔","科多兽骨","科多兽坟场","科多兽之灵"},ang={["profession:Herbalism"]="坟场中腐朽的遗骸和灵魂共鸣，使得大型骸骨周围的区域成为采集墓地苔的沃土。",["race:Tauren"]="科多兽是牛头人受人尊敬的伙伴和精神伴侣，因此亵渎这些祖先的安息之地是一件严重的事情。"},sec={{t="泰坦的安息地",b="科多兽坟场横跨在凄凉之地灰色的土地上，保留着远古巨兽的巨大骨架，其中一些远比今天任何活着的科多兽都要庞大。垂死的科多兽徘徊于此，在数个世纪积累的遗骸中度过最后的时光。这种神圣的平静非常脆弱：食腐动物在周边徘徊，而任何干扰钙化肋骨和头骨的人，都有可能从尘土中惊动愤怒的科多兽之灵。"},{t="灵魂之地",b="在这些骸骨荒原上，生与死的界限变得异常薄弱。窥探灵魂位面的旅行者会发现，躁动不安、高大的科多兽幽灵在沙尘暴中静静地游荡。附近，部落设有幽灵岗哨，守护着这片神圣的土地，并时刻警惕着骸骨周围游荡的兽群和幽灵显现。"}},faq={{q="为什么科多兽会来这里死去？",a="这是一种本能的仪式。当科多兽变得衰老、生病或濒临死亡时，一种天生的冲动驱使它们穿过荒野，来到凄凉之地的这个特定角落，躺在祖先的骸骨之中。",al={"为什么这里有骨头","科多兽死亡之地","为什么科多兽聚集于此"}},{q="为什么有些骸骨如此巨大？",a="有些骸骨比附近见到的活体科多兽要大得多。它们的确切年龄和起源尚不明确。",al={"巨型科多兽骨","巨大的科多兽肋骨","凄凉之地的大型骨架"}},{q="如果有人干扰这些骸骨会怎样？",a="干扰遗骸往往会激怒死者的灵魂。复仇心切的科多兽幽灵会迅速现身，攻击任何试图拾取或亵渎这片安息之地的人。",al={"搜刮科多兽骨","科多兽幽灵","拾骨者任务"}},{q="幽灵岗哨是什么？",a="幽灵岗哨是部落驻扎在骸骨荒原旁的一个小型营地，方便部落旅行者休息，观察该地区的灵魂活动，并引导流浪者穿过凄凉之地中部。",al={"骸骨附近的部落营地","幽灵岗哨"}}},fp="14,267,23.417.0,17.401.0,34.212.0,42.121.0,43.180.0,26.205.0"}
P.entries["subzone:kodo-rock"] = {n="科多石",s="科多石是一座天然的石碑，坐落在红云台地的平原上，位于纳拉其营地和刺刃峡谷之间。它静静地伫立在莫高雷的草丛中，是年轻的牛头人萨满在学习与大地之灵沟通时的早期朝圣地点。由于它在连绵的景观中轮廓并不显眼，旅行者必须留心观察才能发现它。",h="科多石是一座天然的石碑，坐落在红云台地的平原上，位于纳拉其营地和刺刃峡谷之间。它静静地伫立在莫高雷的草丛中，是年轻的牛头人萨满在学习与大地之灵沟通时的早期朝圣地点。由于它在连绵的景观中轮廓并不显眼，旅行者必须留心观察才能...",kw={"刺刃峡谷","纳拉其营地","科多石","纪念碑","莫高雷","红云台地","萨满试炼","牛头人萨满"},ang={["class:Shaman"]="对于在纳拉其营地开启精神之旅的牛头人萨满新手来说，科多石是一个至关重要的地标，用于与元素世界协调。",["race:Tauren"]="这座石碑是红云台地平原上一个熟悉的地标，反映了舒哈鲁人与莫高雷野兽之间神圣的纽带。"},sec={{t="台地上的路标",b="科多石位于连接纳拉其营地和充满敌意的野猪人领地——刺刃峡谷——的道路中段，其基座处有一片磨损的土地作为标记。虽然它不像红云台地周围高耸的悬崖那样宏伟，但其独特的轮廓酷似游荡在草原上的受人尊敬的科多兽。对于游牧的族人来说，它是莫高雷多风平原上一个安静的天然灯塔。"},{t="精神意义",b="对于舒哈鲁人来说，自然形态往往具有精神上的重要意义。对于开始其精神之旅的年轻牛头人萨满来说，科多石具有特殊的崇敬意义。新手们在早期的成人礼中会被指引到这里，将这座孤立的石碑作为圣地，在前往大陆更危险的区域之前，与元素力量沟通并向自然世界致敬。"}},faq={{q="科多石在哪里？",a="科多石位于莫高雷的红云台地上。你可以在纳拉其营地和刺刃峡谷之间的直路中段找到它，地面上有一小块裸露的土地作为标记。",al={"科多石位置","科多石在哪里","寻找科多石"}},{q="为什么科多石很难找到？",a="这座纪念碑与台地的连绵丘陵和草丛自然地融为一体。只有在相对较近的距离内才能清楚地看到它，因此旅行者需要密切注意地形，并留意其下方那片裸露的土地。",al={"找不到科多石","科多石隐藏"}},{q="为什么科多石对牛头人萨满很重要？",a="牛头人萨满在离开纳拉其营地进行最初的试炼时会拜访这块石头。对于学习将自己的精神与大地以及莫高雷的元素力量调和的新手来说，这是一个宁静、神圣的地标。",al={"萨满任务科多石","为什么要前往科多石"}},{q="科多石附近有什么危险？",a="虽然科多石周围的区域通常很平静，但继续向东北方向前进会直接进入刺刃峡谷，那里布满了充满攻击性的刺鬃野猪人。",al={"科多石安全吗","科多石附近的敌人"}}},fx={["5880b9c2"]={q="科多石是什么地方？",a="科多石是一处小型自然纪念地，坐落在莫高雷的红云台地，位于纳拉其营地和荆棘丛生的刺刃峡谷之间。它远看并不起眼，很容易被草海平原的景色掩映，但对开始与元素大地沟通的年轻牛头人萨满而言，却有着深厚的精神意义。",al={"科多石是什么","莫高雷科多石","科多石地标"}}},fp="9,395,22.443.0,22.386.0,27.206.0,30.240.0,45.214.0,32.197.0"}
P.entries["subzone:kolkar-crag"] = {n="科卡尔峭壁",s="科卡尔峭壁是杜隆塔尔南部的一处被烈日炙烤、崎岖不平的峡谷，被充满敌意的科卡尔半人马占据。在科尔卡尼斯督军的领导下，这处据点成为了对附近的部落定居点进行协同突袭的集结地。",h="科卡尔峭壁是杜隆塔尔南部的一处被烈日炙烤、崎岖不平的峡谷，被充满敌意的科卡尔半人马占据。在科尔卡尼斯督军的领导下，这处据点成为了对附近的部落定居点进行协同突袭的集结地。",kw={"半人马","杜隆塔尔","科尔卡尼斯","科卡尔","科卡尔峭壁","森金村","试炼谷","科尔卡尼斯督军"},ang={["faction:Horde"]="保障杜隆塔尔南部免受半人马入侵，能够保护森金村与通往奥格瑞玛的道路之间的补给线。",["race:Orc"]="半人马在靠近试炼谷的地方出没，威胁着年轻兽人的试炼，因此平定科卡尔峭壁已成为领土防御的当务之急。"},sec={{t="杜隆塔尔的眼中钉",b="科卡尔峭壁隐藏在杜隆塔尔南部的崎岖峡谷中，是极具侵略性的科卡尔氏族的作战基地。尽管这里地形干旱且环境恶劣，但这些半人马已经加固了峡谷的天然关隘。从这个深谷中，他们的侦察兵和掠夺者密切监视着周围的平原，试图寻找兽人和暗矛氏族领地的弱点。对于在试炼谷受训或在南部海岸巡逻的年轻战士来说，科卡尔峭壁是他们面对的最邻近的半人马敌对阵线。"},{t="入侵阴谋",b="在科尔卡尼斯督军的指挥下，盘踞在峭壁的半人马怀有远超小规模冲突的野心。缴获的进攻计划显示，他们企图袭击试炼谷、森金村、剃刀岭，并直接针对Gates of Orgrimmar发起大胆突袭。要阻止这些计划，就必须深入峡谷发起果断的先发制人打击，刺杀科尔卡尼斯，在他们的战争分队席卷山谷之前瓦解其兵力。"}},faq={{q="谁住在科卡尔峭壁？",a="科卡尔峭壁由科卡尔半人马氏族把守，由科尔卡尼斯督军现场指挥。他们利用这座易守难攻的峡谷作为营地，并以此为据点袭击整个杜隆塔尔的部落哨所。",al={"谁在科卡尔峭壁","科卡尔峭壁的居民","谁拥有科卡尔峭壁"}},{q="部落为何担心这处峡谷？",a="峡谷内的半人马已经起草了对杜隆塔尔重要定居点发动协同攻击的计划，其中包括试炼谷的训练场、森金村、剃刀岭以及奥格瑞玛本身。",al={"为什么要关心科卡尔峭壁","科卡尔峭壁危险吗","科卡尔威胁"}},{q="是谁在领导这里的半人马？",a="这个营地由科尔卡尼斯督军指挥，这是一位凶猛的半人马督军，负责指导他们的侦察机动并制定针对兽人和巨魔的战斗计划。",al={"科卡尔峭壁首领","谁领导科卡尔峭壁","科尔卡尼斯督军"}}},fx={e91c2682={q="科卡尔峭壁是什么地方？",a="科卡尔峭壁是杜隆塔尔南部一处崎岖的峡谷。敌对的科卡尔半人马在此建立了坚固据点，并在天然峡谷中开辟出一处基地，距离部落的重要聚居地近在咫尺。",al={"科卡尔峭壁位置","科卡尔峭壁是什么","科卡尔峭壁概况"}},b1f68783={q="科卡尔峭壁发生了什么？",a="第三次战争结束后，科卡尔半人马在这处峡谷中筑起防御工事，并将其作为集结地，策划对杜隆塔尔各处聚居地发动协同袭击，其中包括森金村、剃刀岭、试炼谷，甚至奥格瑞玛。",al={"科卡尔峭壁历史","科卡尔峭壁的历史","科卡尔峭壁发生的事件"}},a74eb943={q="科卡尔峭壁危险吗？",a="是的，那里极其危险。峡谷中挤满了由军阀科尔卡尼斯率领的好斗科卡尔半人马，他们组织严密，正准备袭击附近的定居点。毫无戒心的旅人若误入峡谷，很快就会遭到伏击，陷入寡不敌众的境地。",al={"科卡尔峭壁有多危险","科卡尔峭壁安全吗"}},["86a855ff"]={q="为什么叫科卡尔峭壁？",a="这处峡谷直接以科卡尔半人马氏族命名，他们占据了这片岩石峡谷，并在其中建立了据点。",al={"科卡尔峭壁名称含义","为何叫科卡尔峭壁"}}},fp="11,219,25.544.0,19.461.1,25.181.0,45.217.0,27.170.0"}
P.entries["subzone:kormek-s-hut"] = {n="考米克小屋",s="考米克小屋是一座坐落在凄凉之地中北部荒原之中的偏僻破败住所。尽管周围一片荒凉，且命名者身份神秘，但这里目前住着一对奇怪的同伴：一名异常平静的教徒和一名痴迷于收集科多兽骨头的地精。",h="考米克小屋是一座坐落在凄凉之地中北部荒原之中的偏僻破败住所。尽管周围一片荒凉，且命名者身份神秘，但这里目前住着一对奇怪的同伴：一名异常平静的教徒和一名痴迷于收集科多兽骨头的地精。",kw={"比布里·弗斯巴克","凄凉之地","科多兽骨头","考米克","考米克小屋","暮光之锤","薇洛"},sec={{t="一处奇异的怪异绿洲",b="这间小屋坐落在凄凉之地中北部干旱的荒原上，以一个身份和下落完全不明的人的名字命名。来到这里的旅行者遇见的并不是考米克，而是一对住在荒郊野外的奇怪组合：薇洛和比布里·弗斯巴克。小屋里住着薇洛，她是通常带有敌意且虚无主义的暮光之锤的一员，却以平静和好客的态度对待外来者。小屋外的围栏里散落着被太阳晒白的科多兽骨头，那里是比布里个人的舞池和活动场地，这个兴奋的地精迷恋于骨头清道夫的商业潜力。"}},faq={{q="考米克是谁？",a="没人知道。小屋冠以考米克之名，但无论是外面的地精还是里面的教徒都没有解释考米克是谁，而在荒原上也找不到这个名字的主人。",al={"考米克是谁","考米克的身份","考米克在哪里"}},{q="为什么这里会有一个友好的暮光之锤教徒？",a="薇洛住在小屋里，她是暮光之锤的一员，这个教派通常对所有凡人生命怀有敌意。但出于她自己的原因，她对路过这座偏僻住所的旅行者保持着非敌对的态度。",al={"薇洛暮光之锤","为什么薇洛是友好的","薇洛小屋"}},{q="外面的地精在做什么？",a="比布里·弗斯巴克整天兴奋地在堆满科多兽骨头的围栏周围跳舞。和许多精明的地精一样，他热衷于将古老的沙漠遗骸转化为纯粹的利润。",al={"比布里·弗斯巴克","凄凉之地跳舞的地精","为什么地精在跳舞"}},{q="考米克小屋位于哪里？",a="小屋位于凄凉之地中北部，坐落在中央十字路口和墓地以北干旱且狂风肆虐的平原上。",al={"考米克小屋位置","考米克小屋在哪里","考米克凄凉之地"}}},fp="12,278,27.652.0,14.176.0,55.212.0,33.211.0,30.130.0"}
P.entries["subzone:kurzen-s-compound"] = {n="库尔森的营地",s="库尔森的营地是一处位于荆棘谷北部山丘中、戒备森严的人类定居点。该前哨站由暴风城派遣库尔森上校率领的一支远征队建立，但在指挥官陷入疯狂后，它堕落成了一个由暴徒和野兽组成的流氓营地。",h="库尔森的营地是一处位于荆棘谷北部山丘中、戒备森严的人类定居点。该前哨站由暴风城派遣库尔森上校率领的一支远征队建立，但在指挥官陷入疯狂后，它堕落成了一个由暴徒和野兽组成的流氓营地。",kw={"上校","营地","库尔森","反抗军","储备库","荆棘谷"},ang={["class:Hunter"]="该营地展示了将野生的荆棘谷豹和虎驯化为前线战争野兽的粗鲁且暴力的尝试。",["faction:Alliance"]="库尔森的远征队是在联盟的旗帜下被派出的，这使得该前哨站的堕落成为了一桩可耻的丑闻，附近的起义者正拼命试图纠正这一错误。"},sec={{t="黑暗之心",b="这场最初旨在进入荆棘谷未开化丛林的官方远征，在库尔森上校失去理智后变成了一场噩梦。驻军没有完成暴风城的任务，而是脱离了王国的管辖，切断了与王室的联系，陷入了暴政之中。如今，该营地就像一个雇佣兵据点，配备了功能完善的伐木场、用于驯养被捕获的荆棘谷豹和虎作为战争武器的马厩，以及一个被称为“储备库”的广阔洞穴群，流氓士兵们将掠夺来的补给藏匿在那里。"},{t="分裂的军团",b="并非远征队的所有原始成员都跟随他们的指挥官堕落为野蛮人。当库尔森陷入疯狂时，他的一批手下发动叛变并向西逃亡，建立了反抗军营地，在茂密的林冠下引发了痛苦而血腥的仇恨。库尔森和他的忠实追随者们从他们戒备森严的营地出发，无情地追杀逃兵，将任何踏入他们丛林领地的外人视为远征队的敌人。"}},faq={{q="谁住在库尔森的营地里？",a="该定居点被库尔森远征队的流氓残部占据。这些人类士兵、丛林战士和雇佣兵追随库尔森上校和他的副官，而不是暴风城的法律。",al={"这里是谁","库尔森的士兵","谁住在营地里"}},{q="为什么这里的人类具有敌意？",a="库尔森上校在丛林深处陷入疯狂，抛弃了他最初对联盟的效忠。现在，他和他的部下将所有入侵者（包括联盟军队和附近反抗军营地的逃兵）都视为致命威胁。",al={"为什么要攻击","库尔森的敌意","库尔森友善吗"}},{q="营地后面的洞穴是什么？",a="营地后的洞穴系统被称为“储备库”。库尔森的手下将其用作加固的补给仓库，以储存武器、粮草和违禁品，防止丛林食腐动物和反抗军的袭击。",al={"库尔森营地的洞穴","储备库","库尔森的洞穴"}},{q="为什么这里有被关在笼子里的老虎和豹子？",a="战士们捕获当地的荆棘谷虎和豹，并将它们关在马厩附近。他们将这些捕食者训练成凶猛的库尔森战争豹和战争虎，用于守卫营地并巡逻周围的丛林。",al={"库尔森的野兽","笼中的豹子","战争虎"}}},fp="17,311,17.583.0,18.424.0,31.204.0,32.243.0,41.200.0,45.226.0"}
P.entries["subzone:lake-al-ameth"] = {n="奥拉密斯湖",s="奥拉密斯湖坐落于泰达希尔的枝叶高处，是该地区最大的淡水水域之一，位于多兰纳尔的正南方。曾经这里是一片宁静的避风港，仅有一个简易的木制码头，但由于当地植物发生剧烈异动，湖岸如今已变得危机四伏。",h="奥拉密斯湖坐落于泰达希尔的枝叶高处，是该地区最大的淡水水域之一，位于多兰纳尔的正南方。曾经这里是一片宁静的避风港，仅有一个简易的木制码头，但由于当地植物发生剧烈异动，湖岸如今已变得危机四伏。",kw={"多兰纳尔","卡多雷","奥拉密斯湖","橡木之爪","泰达希尔","树妖","树妖种子"},ang={["class:Druid"]="湖周围的野生树妖为德鲁伊们提供了一个亲身研究的机会，以探究正在侵蚀泰达希尔动植物的异常腐蚀。",["race:NightElf"]="对于多兰纳尔的卡多雷来说，奥拉密斯湖是一个令人担忧的信号，预示着他们刚建立的新家园正饱受病痛折磨，这也迫使年轻的守卫者们必须保护周围的道路。"},sec={{t="不安的湖岸",b="奥拉密斯湖位于多兰纳尔村的正南面，是泰达希尔中心地带至关重要的天然蓄水池。尽管这里水波平静、人迹罕至，但往日的宁静已经荡然无存。成群狂躁的树妖和树妖嫩苗在水边徘徊，受困于正在这棵世界之树中蔓延的一种异常病痛，变得疯狂起来。多兰纳尔的德鲁伊和研究人员经常派遣旅行者前往湖岸收集种子，并清除这些具有攻击性的生物，以免腐蚀扩散到周围的森林深处。"},{t="愤怒之根",b="奥拉密斯湖周边的敌意，直接归因于林地灵魂失去了平衡。橡木之爪（Oakenscowl）曾是一只高贵的树妖，如今长出了巨大的瘤，并从湖东南岸的一个洞穴中散播腐蚀，而其他的天然树妖则对任何靠近者发起攻击。对于塞纳里奥议会而言，诊断并治疗奥拉密斯湖周围的腐烂，是一项紧迫的测试，以验证泰达希尔这片未经祝福创造出的土地是否真的能够维持下去。"}},faq={{q="奥拉密斯湖在哪里？",a="奥拉密斯湖位于泰达希尔东部，多兰纳尔暗夜精灵定居点的正南方。",al={"奥拉密斯湖位置","奥拉密斯湖在哪里","寻找奥拉密斯湖"}},{q="为什么奥拉密斯湖周围的生物具有攻击性？",a="湖岸沿线的树妖和植物已沦为泰达希尔所受腐蚀性疾病的受害者，这使得原本无害的林地小精灵和树人陷入了领地狂暴之中。",al={"树妖为什么愤怒","奥拉密斯湖敌人","狂躁的树妖"}},{q="湖上有什么建筑或地标？",a="湖区基本处于野生未开发状态，仅在靠近多兰纳尔道路的北岸有一个简易的木制垂钓码头。",al={"奥拉密斯湖码头","奥拉密斯湖停靠点"}},{q="橡木之爪是谁？",a="橡木之爪是一只受到腐蚀的树妖，潜伏在奥拉密斯湖南岸的一个洞穴中。他曾是其族群中伟大的领袖，如今却因长出巨大的瘤而中毒，并向以该湖为家的生物散播腐蚀。",al={"什么是橡木之爪","橡木之爪奥拉密斯湖"}}},fx={a360f287={q="奥拉密斯湖是什么地方？",a="奥拉密斯湖是泰达希尔枝叶间的一片大型淡水水域。它位于多兰纳尔以南，湖水宁静，岸边林木葱郁，曾是一处静谧的天然避风港，湖岸边只有一座简朴的木栈桥。近来，日益加剧的动乱却掩去了这里的宁静美景。",al={"奥拉密斯湖是什么地方","奥拉密斯湖简介","奥拉密斯湖传说"}},["3493d075"]={q="奥拉密斯湖危险吗？",a="如今若不做好准备，就不该在湖岸闲逛。躁动的木爪、狂暴的幼苗已遍布湖岸。除了这些好斗的林地精魂，附近还潜伏着橡树之心这类堕落的巨兽，任何来到水边的旅人都必须保持警惕。",al={"奥拉密斯湖安全吗","奥拉密斯湖的危险","奥拉密斯湖有哪些危险"}}},fp="13,291,20.551.0,18.452.0,31.96.0,51.198.0,45.136.0,18.248.0"}
P.entries["subzone:lake-elune-ara"] = {n="月神湖",s="月神湖是一片波光粼粼、神圣的水域，坐落于月光林地的中心。这片湖泊受到月光女神艾露恩的眷顾，是塞纳里奥议会进行精神反思的圣地，尽管在它浑浊的湖底深处，沉睡着被腐蚀的半神欧穆。",h="月神湖是一片波光粼粼、神圣的水域，坐落于月光林地的中心。这片湖泊受到月光女神艾露恩的眷顾，是塞纳里奥议会进行精神反思的圣地，尽管在它浑浊的湖底深处，沉睡着被腐蚀的半神欧穆。",kw={"塞纳里奥议会","黑暗水域","艾露恩","月神湖","月光林地","永夜港","欧穆"},ang={["class:Druid"]="该湖泊是德鲁伊仪式和测试的重要场所，其深水中藏有神圣的遗物，可帮助初学者踏上修行之路。",["race:NightElf"]="因艾露恩而得名，该湖泊代表了一个神圣的安宁之所，同时也承载着远古之战的历史记忆。"},sec={{t="神圣山谷之心",b="月神湖被月光林地月色朦胧的树林所环绕，其宁静的水域据传受到白女士本人的祝福。湖泊位于这座德鲁伊避难所的精神中心，北邻永夜港，边缘则是塞纳里奥议会的圣坛所在地。初学者们长期以来一直深入其平静的深处搜寻遗失已久的圣物，在寻求与大地和谐共处的过程中，让自己与自然的潮流协调一致。"},{t="欧穆的沉睡",b="尽管水面平静如初，但在柔和的涟漪之下却潜藏着古老的危机。百年的传说诉说着双头狼半神欧穆的故事，这是一位在远古之战期间被燃烧军团腐蚀的受人尊敬的古神。欧穆在很久以前战败并被抛入湖床，至今仍沉睡在黑暗的湖底，成为自然创伤的永恒警示。"}},faq={{q="什么是月神湖？",a="它是位于月光林地中心的大型圣湖。深受暗夜精灵和德鲁伊的尊崇，以月之女神艾露恩的名字命名，并被塞纳里奥议会的庇护所环绕。",al={"月神湖","月光林地湖泊","月神湖在哪里"}},{q="湖底潜伏着什么？",a="堕落的半神欧穆沉睡在湖泊的黑暗深处。他曾经是一位高贵的古神，在远古战争期间被燃烧军团驱使陷入疯狂，战败后被抛入湖中。",al={"月神湖里有什么","月光林地的欧穆","湖中的怪物"}},{q="德鲁伊为何来到这个湖泊？",a="该湖泊与德鲁伊的试炼以及与自然之灵的交流有着深厚的联系。年轻的德鲁伊经常深入水中搜寻神圣的遗物，作为他们成年礼的一部分。",al={"德鲁伊湖泊任务","水栖形态湖泊"}}},fp="14,278,24.429.0,19.359.0,23.198.0,37.187.0,32.192.0"}
P.entries["subzone:lake-everstill"] = {n="止水湖",s="止水湖是赤脊山中心地带那片广阔的蔚蓝水域，紧邻着湖畔镇。这里曾因宁静的垂钓环境和清澈的山间流水而闻名，但由于好战的鱼人部落和湖中的掠食野兽，它的岸边和水域近期已变得危机四伏。",h="止水湖是赤脊山中心地带那片广阔的蔚蓝水域，紧邻着湖畔镇。这里曾因宁静的垂钓环境和清澈的山间流水而闻名，但由于好战的鱼人部落和湖中的掠食野兽，它的岸边和水域近期已变得危机四伏。",kw={"止水湖大桥","止水湖","湖畔镇","鱼人","赤脊山"},ang={["class:Mage"]="路过湖畔镇的法师会发现，湖中的麻烦并非奥术问题，而是世俗困扰：鱼人营地挤满了浅滩，而长鳍鱼则在深水区巡逻。",["faction:Alliance"]="控制湖泊及其渡口对于湖畔镇来说至关重要，这是其在赤脊山鱼人和附近黑石兽人的协同入侵下生存下去的关键。"},sec={{t="山谷之心",b="止水湖横跨赤脊山中央盆地，为湖畔镇提供了优美的背景和重要的水道。其清澈见底的湖水向东流去，汇向高耸的石堡。湖上架着小镇的中心桥梁，长期以来支撑着当地的贸易和安静的垂钓者。然而，今天任何走在湖边的人都会发现，这里曾经宁静的名声已经被不断侵蚀的荒野威胁彻底摧毁。"},{t="深处的麻烦",b="近来，充满敌意的鱼人在北部和东部的浅滩建立了营地，破坏了贸易并骚扰渔民。水面之下也潜藏着水生危险，包括在深水区巡游的危险长鳍鱼。"}},faq={{q="止水湖中生活着哪些危险生物？",a="浅滩上爬满了充满敌意的鱼人部落，包括斥候、潮汐祭司和噬肉者。游向深处则有另外的危险，因为巨型长鳍鱼和好战的泥潭居者正在水下巡游。",al={"湖里有什么","止水湖怪物","赤脊山湖泊怪物"}},{q="止水湖的水流向哪里？",a="湖水由一条东向的河流排出，流经黑石兽人占据的石堡下方的山坡。",al={"止水湖河流","湖水流向哪里"}},{q="可以在止水湖安全地钓鱼吗？",a="虽然湖中盛产鲶鱼和鼠尾鱼，但钓鱼已经变得极其危险。鱼人袭击队就驻扎在水边，而大型长鳍鱼会攻击任何游得太远的人。",al={"在止水湖钓鱼","在湖畔镇钓鱼安全吗"}}},fx={f0f5bd2b={q="止水湖是什么地方？",a="止水湖是赤脊山腹地的一片广阔蔚蓝水域。清澈见底的湖水环绕着湖畔镇；湖畔镇坐落在湖的北岸，通过止水湖大桥与东岸相连。湖水由山间溪流汇入，最终在石堡要塞附近向东流去。",al={"止水湖概况","这片湖是什么地方","止水湖简介"}}},fp="14,307,19.444.0,21.247.0,48.215.0,46.123.0,38.212.0"}
P.entries["subzone:lake-falathim"] = {n="法拉希姆湖",s="法拉希姆湖是一片宁静的水域，坐落在灰谷西部的森林丘陵之中，位于迈斯特拉岗哨的西南方。这里因为终日被艾露恩的月光照耀而备受尊崇，曾是暗夜精灵钟爱的休憩之所。然而最近，好斗的鱼人占领了湖岸，将这片神圣的避风港变成了一处危险之地。",h="法拉希姆湖是一片宁静的水域，坐落在灰谷西部的森林丘陵之中，位于迈斯特拉岗哨的西南方。这里因为终日被艾露恩的月光照耀而备受尊崇，曾是暗夜精灵钟爱的休憩之所。然而最近，好斗的鱼人占领了湖岸，将这片神圣的避风港变成了一处危险之...",kw={"灰谷","艾露恩","法拉希姆","法拉希姆湖","迈斯特拉岗哨","月光","鱼人","泰罗尼斯"},ang={["faction:Alliance"]="来自迈斯特拉岗哨的联盟侦察兵密切关注着法拉希姆湖，警惕着鱼人的入侵，并寻找着像泰罗尼斯这样失踪学者的消息。",["race:NightElf"]="对于卡多雷来说，法拉希姆湖是荒野圣地遭到侵犯的写照，这片被艾露恩永恒月光照耀的田园诗般的湖泊，如今却被野蛮的鱼人部落所亵渎。"},sec={{t="月光沐浴",b="法拉希姆湖隐藏在佐拉姆海岸的东南方，长久以来被卡多雷视为游泳和垂钓的宁静圣地。据当地传说，艾露恩柔和的光芒时刻笼罩着这片水域，无论昼夜。尽管拥有这一神圣的祝福，凶猛的鱼人还是涌入内陆，占据了湖岸，它们在这里大量筑巢，驱逐了当地的行人和学者。"},{t="学者的失踪",b="鱼人的突然入侵使得这片湖泊对独行的旅者来说变得极其致命。暗夜精灵学者泰罗尼斯最近在水边执行研究任务时失踪了。考虑到潜伏在湖岸和浅滩上的两栖生物极其凶残，哨兵们担心任何独自前往那片月光照耀的池塘的人都凶多吉少。"}},faq={{q="法拉希姆湖在哪里？",a="法拉希姆湖位于灰谷西部，坐落在迈斯特拉岗哨西南方和佐拉姆海岸东南方的丘陵中。",al={"法拉希姆湖位置","法拉希姆湖在哪里","寻找法拉希姆湖"}},{q="为什么法拉希姆湖对暗夜精灵来说很特别？",a="这座湖具有重要的精神意义，因为据说月神艾露恩的月光会永久地照耀着这里的湖水，无论白天还是黑夜。在历史上，暗夜精灵常会造访其宁静的湖岸进行垂钓和游泳。",al={"为什么法拉希姆湖很重要","法拉希姆湖传说","灰谷月光湖"}},{q="湖里栖息着什么生物？",a="这座湖已经被从附近海岸区域迁移而来的敌对鱼人所占据，这使得湖岸对旅者来说变得十分危险。",al={"法拉希姆湖怪物","法拉希姆湖有什么"}},{q="泰罗尼斯是谁？",a="泰罗尼斯是一位暗夜精灵学者，他在法拉希姆湖附近探险时失踪了，人们认为他的失踪与栖息在该地区的凶残鱼人有关。",al={"泰罗尼斯 法拉希姆湖","泰罗尼斯是谁","失踪学者 法拉希姆湖"}}},fx={ede2002d={q="法拉希姆湖是什么地方？",a="法拉希姆湖是灰谷西部森林中的一片宁静水域，位于佐拉姆海岸东南方、迈斯特拉岗哨西南方。传说这里承载着艾露恩的神圣祝福，无论昼夜、无论时辰，月光总会洒在波光粼粼的湖面上。",al={"法拉希姆湖是什么地方","法拉希姆湖概况","法拉希姆湖简介"}},["1b39db00"]={q="法拉希姆湖发生了什么？",a="数代以来，这里一直是宁静的避风港，暗夜精灵常聚集于此捕鱼、游泳，在艾露恩祝福的月光下休憩。直到好斗的鱼人侵占湖水，这份安宁才戛然而止；精灵被迫离开，任何靠近湖边的人也会受到威胁。",al={"法拉希姆湖的历史","法拉希姆湖发生了什么","法拉希姆湖的过往"}},f94ff24b={q="法拉希姆湖为何被遗弃？",a="曾在此游泳、捕鱼的暗夜精灵被凶暴的鱼人赶走，后者占据了湖面。鱼患让这处受人敬仰的灵修胜地变成了敌对之地，旅人纷纷避开此处，学者特罗尼也因此遭遇大祸。",al={"法拉希姆湖为何被遗弃","暗夜精灵为何离开法拉希姆湖","法拉希姆湖的衰败"}},["019a1e1b"]={q="法拉希姆湖危险吗？",a="危险。尽管湖水受到祝福，看起来十分诱人，但湖中遍布凶猛的鱼人，它们会无情地攻击闯入者。就连谨慎的访客和前来调查神圣湖岸的学者，也曾消失在湖水中，再未归来。",al={"法拉希姆湖有多危险","法拉希姆湖安全吗","法拉希姆湖面临的威胁"}}},fp="13,369,19.413.0,27.352.0,31.125.0,48.215.0,32.146.0,16.163.0"}
P.entries["subzone:lake-kel-theril"] = {n="凯斯利尔湖",s="凯斯利尔湖是坐落在冬泉谷中心的一片广阔冰封湖泊。在其冰封的湖岸边，伫立着古老的卡多雷废墟，那些自大分裂以来就徘徊于此的躁动灵魂依然萦绕不去。",h="凯斯利尔湖是坐落在冬泉谷中心的一片广阔冰封湖泊。在其冰封的湖岸边，伫立着古老的卡多雷废墟，那些自大分裂以来就徘徊于此的躁动灵魂依然萦绕不去。",kw={"上层精灵","凯斯利尔","凯斯利尔湖","凯斯利尔废墟","幽灵","冬泉谷"},ang={["race:NightElf"]="行走在凯斯利尔湖上的悲剧幽灵，以一种令人不寒而栗的方式提醒着世人，古代上层精灵的鲁莽傲慢所带来的毁灭。"},sec={{t="上层精灵的冰封之墓",b="凯斯利尔湖笼罩在永恒的寒冷之中，湖水被封锁在厚厚的冰层之下。散落在湖面和雪岸上的是古代精灵建筑破碎的立柱和拱门。这些是凯斯利尔的遗迹，在大分裂将卡利姆多撕裂之前，这里曾是古代上层精灵文明的前哨站。死去的贵族们的灵魂并未在死亡中得到安息，而是作为备受折磨的鬼魂和幽灵在冰面上徘徊，永远被束缚在他们昔日辉煌的悲惨残骸之上。"}},faq={{q="为什么湖中会有暗夜精灵的鬼魂？",a="在凯斯利尔湖游荡的灵魂是古代上层精灵备受折磨的鬼魂。当大分裂在万年前将卡利姆多撕裂时，他们文明的灾难性崩溃使得这些灵魂被束缚在他们曾经定居点的冰冷废墟之中。",al={"凯斯利尔湖 鬼魂","为什么这里有灵魂","冬泉谷 湖泊 鬼魂"}},{q="湖岸边矗立着什么遗迹？",a="这些坍塌的立柱和石制品属于凯斯利尔废墟，这是一个在古树之战前上层精灵统治时期繁荣昌盛的古代卡多雷定居点。",al={"湖中遗迹","什么是凯斯利尔废墟"}}},fp="15,206,30.526.0,39.269.0,41.182.0"}
P.entries["subzone:lake-mennar"] = {n="门纳尔湖",kw={"艾萨拉","艾索雷葛斯","蓝龙军团","龙人","门纳尔湖","麦索瑞尔","幼龙"},ang={["class:Mage"]="作为世界奥术能量的守护者，驻守在门纳尔湖的蓝龙让这片盆地成为了奥术魔法修行者们既充满好奇又必须保持谨慎的地方。"},sec={{t="蓝龙军团的圣所",b="门纳尔湖坐落在古老而破碎的艾萨拉大地上，是蓝龙军团一处隐秘的聚集地。除了冬泉谷北部的麦索瑞尔之外，在整个卡利姆多几乎从未听说过有如此数量的蓝龙出现。蓝龙人不知疲倦地巡视着环绕盆地的山脊和通道，严密守护着这片水域。然而，对于任何敢于穿过这道警惕防线的流浪者来说，平静的湖水提供了一种意想不到的宁静，远离了半岛其他地区常见的奥术混乱和游荡的兽群。"}},faq={{q="为什么门纳尔湖会有蓝龙？",a="门纳尔湖对蓝龙军团有着宁静而特殊的意义，使它成为他们在卡利姆多除了冬泉谷的麦索瑞尔之外极少数的聚集地之一。龙人警惕地巡逻着外围，以保护盆地并让闯入者远离他们的龙巢。",al={"为什么这里有蓝龙","谁住在门纳尔湖","蓝龙军团 门纳尔湖"}},{q="去门纳尔湖会有危险吗？",a="周围的山脊和通道上有好斗的蓝龙类生物和幼龙严密巡逻。然而，如果你能溜过外围的守卫，盆地内部的水域和湖岸却异常宁静。",al={"门纳尔湖安全吗","门纳尔湖的敌人"}},{q="门纳尔湖与其他蓝龙巢穴有什么联系？",a="在卡利姆多大陆上，门纳尔湖和冬泉谷的麦索瑞尔是蓝龙军团所守护的主要已知领地。这两个地点都是蓝龙军团在远离其位于诺森德祖居地以南的罕见前哨站。",al={"与麦索瑞尔的联系","门纳尔湖 冬泉谷"}}},fp="11,338,37.610.0,42.284.0,34.239.0,57.234.0"}
P.entries["subzone:lake-mereldar"] = {n="米雷达尔湖",s="米雷达尔湖是一片广阔、被污染的水域，坐落在东瘟疫之地考林路口以南。这里曾经是洛丹伦田园牧歌般的核心地带的一部分，如今却因天灾军团残留的污秽，导致腐化的水体滋生出扭曲的元素，并在腐烂中不断蔓延。",h="米雷达尔湖是一片广阔、被污染的水域，坐落在东瘟疫之地考林路口以南。这里曾经是洛丹伦田园牧歌般的核心地带的一部分，如今却因天灾军团残留的污秽，导致腐化的水体滋生出扭曲的元素，并在腐烂中不断蔓延。",kw={"枯萎涌动者","考林路口","东瘟疫之地","元素","渡船","米雷达尔湖","瘟疫掠夺者"},ang={["class:Shaman"]="米雷达尔湖中枯萎涌动者的存在，有力地证明了天灾军团的邪恶魔法如何将自然的元素灵魂腐化为失去理智的暴力怪物。"},sec={{t="一片受污染的避风港",b="米雷达尔湖位于考林路口镇以南，曾经是北洛丹伦乡村宁静的一处景致。湖岸边散落着古老农舍的残垣断壁，有一间废弃的小屋，还有一艘破旧的渡船，过去常载着当地的农夫和旅人横渡这片温柔的水域。随着天灾军团的入侵和亡灵瘟疫的肆虐，湖泊彻底荒废。周围的土壤枯萎，湖水变得恶臭且带有剧毒。"},{t="扭曲的居民",b="渗入米雷达尔湖的非自然枯萎病彻底感染了当地的生态系统以及与之相连的灵魂。枯萎涌动者——这些被死灵残渣腐蚀并陷入疯狂的水元素——潜伏在浅滩中，毫无预兆地浮出水面。在杂草丛生的岸边，凶猛的野兽，如瘟疫掠夺者，在泥泞中徘徊，捕食任何误入死寂湖岸附近的活物。"}},faq={{q="米雷达尔湖位于何处？",a="米雷达尔湖坐落在东瘟疫之地中南部，位于废弃的考林路口镇正南方。",al={"米雷达尔位置","米雷达尔湖在哪里","寻找米雷达尔湖"}},{q="为什么湖里会有水元素？",a="这里的水元素被称为枯萎涌动者，在洛丹伦陷落期间，因渗入湖泊的弥漫性死灵枯萎病而被扭曲，变得极具敌意。",al={"枯萎涌动者","米雷达尔的水元素","腐化的元素"}},{q="岸边的小屋和渡船属于谁？",a="它们属于第三次战争前建立的一处当地农场。当瘟疫蹂躏东威尔德时，农场主们要么丧生，要么逃离，留下了他们的房子和渡船任其腐烂。",al={"渡船遗迹","米雷达尔房屋","废弃码头"}},{q="湖里的水可以饮用或游泳吗？",a="不可以。湖泊被亡灵瘟疫严重污染，饮用、游泳或从中捕捞都具有危险性，而且其水域中栖息着具有攻击性的枯萎生物。",al={"可以喝湖里的水吗","米雷达尔湖有毒吗"}}},fp="13,275,16.486.0,19.409.0,31.133.0,43.181.0,43.188.0,38.166.0"}
P.entries["subzone:lake-nazferiti"] = {n="纳菲瑞提湖",s="纳菲瑞提湖是一座广阔的淡水湖，坐落在荆棘谷北部的茂密丛林之中。它由延伸至北方群山的巨大河流系统供水，湖中栖息着凶猛的鳄鱼和撕咬者，而其湖岸上则坐落着由地精荆棘谷地精运营的工业营地。",h="纳菲瑞提湖是一座广阔的淡水湖，坐落在荆棘谷北部的茂密丛林之中。它由延伸至北方群山的巨大河流系统供水，湖中栖息着凶猛的鳄鱼和撕咬者，而其湖岸上则坐落着由地精荆棘谷地精运营的工业营地。",kw={"鳄鱼","撕咬者","纳菲瑞提湖","纳菲瑞提","河流","荆棘谷","荆棘谷地精"},ang={["class:Hunter"]="纳菲瑞提湖的湖岸和深水区提供了丰富的猎物，从凶猛的河兽到在芦苇丛中潜行的危险鳄鱼，应有尽有。",["race:NightElf"]="荆棘谷地精在纳菲瑞提湖留下的工业伤痕，展示了肆无忌惮的地精贪婪所造成的原始环境破坏。"},sec={{t="丛林水道之心",b="纳菲瑞提湖位于纳菲瑞提河畔，这是东部王国南部最长的连续水道之一。这条河流发源于北方的深处，从赤脊山的瀑布倾泻而下，其源头可能远至内陆的逆风小径。在荆棘谷内，水流汇聚成了这座浑浊的湖泊，里面挤满了凶残的掠食者，如河里的撕咬者和埋伏捕食的鳄鱼，让在此随意游泳变得极其危险。"},{t="荆棘谷地精的侵蚀",b="纳菲瑞提湖的自然平衡正受到荆棘谷地精的围攻。这些无情的掠夺者在湖岸边建立了大规模的作业区，利用机械锯、钻机和砍伐队来开采丛林的木材和资源。他们庞大的基地污染了水道，并不断与当地的野生生物以及在谷中闯荡的猎人们发生冲突。"}},faq={{q="纳菲瑞提湖的水源来自哪里？",a="该湖由纳菲瑞提河供水，这是一条发源于北方高山的庞大河流网络。其已确认的源头是赤脊山倾泻而下的瀑布，而未确认的源头可能延伸至逆风小径的峭壁。",al={"纳菲瑞提河源头","纳菲瑞提湖的源头","纳菲瑞提湖水源"}},{q="谁控制着纳菲瑞提湖的湖岸？",a="由地精运营的荆棘谷地精在湖泊边缘占据了一个主要基地。他们利用这个立足点剥削周围丛林的木材和矿产资源，并在水边部署了武装监工和地精机械。",al={"谁在纳菲瑞提湖","纳菲瑞提湖的地精","荆棘谷地精湖区"}},{q="在纳菲瑞提湖游泳安全吗？",a="在该湖游泳很危险。浑浊的水域中潜伏着成群具有攻击性的河边撕咬者和潜行的鳄鱼，任何离开浅滩的人都会迅速遭到它们的攻击。",al={"纳菲瑞提湖怪物","纳菲瑞提湖有什么生物","纳菲瑞提湖生物"}},{q="纳菲瑞提湖位于哪里？",a="纳菲瑞提湖位于荆棘谷北部，就在与暮色森林接壤的边界以南，祖尔格拉布废墟以西，沿主河流航道而建。",al={"纳菲瑞提湖位置","纳菲瑞提湖在哪里","寻找纳菲瑞提湖"}}},fp="14,333,28.480.0,28.393.0,40.270.0,42.234.0,37.178.0,32.159.0"}
P.entries["subzone:lakeridge-highway"] = {n="湖边大道",s="湖边大道是一条古老的通商大道，沿着赤脊山的止水湖南岸延伸。在第一次战争之前，这里曾是一条繁忙且至关重要的动脉，但如今已破败荒废。今天，成群结队的豺狼人和黑石兽人在道路上游荡，使得过往的旅人险象环生。",h="湖边大道是一条古老的通商大道，沿着赤脊山的止水湖南岸延伸。在第一次战争之前，这里曾是一条繁忙且至关重要的动脉，但如今已破败荒废。今天，成群结队的豺狼人和黑石兽人在道路上游荡，使得过往的旅人险象环生。",kw={"豺狼人","大道","止水湖","湖边","赤脊山","道路","石堡"},ang={["faction:Alliance"]="这条大道是暴风城边境被忽视的写照，由于缺乏增援，湖畔镇外的当地道路已沦陷，被豺狼人和兽人占据。"},sec={{t="陨落的动脉",b="在第一次战争的浩劫之前，湖边大道是赤脊山一条繁忙的贸易通道，承载着货物与民众沿着止水湖南岸通行。在那些和平的日子里，旅人们可以在暴风王国的庇护下往返于山谷定居点与东部高地之间。当部落大军行进至该地区时，这种安全便不复存在，赤脊山东部也因此成为了充满纷争的荒凉之地。"},{t="道路上的危险",b="在黑石兽人占领石堡要塞后，这条大道的日常维护和巡逻便完全停止了。道路迅速退化成了一条被野蛮的豺狼人部族争夺的杂草丛生的小径。由于暴风城的军力捉襟见肘，无法增援湖畔镇，这条大道在官方层面被列为危险地带。任何想要前往东部山脊的旅人都必须在豺狼人的伏击中杀出一条路来。"}},faq={{q="湖边大道通向哪里？",a="这条道路沿着止水湖南缘延伸，从湖畔镇地区向东，通往石堡要塞周边的丘陵和赤脊山东部山区。",al={"湖边大道通向哪里","湖边大道路线","湖边大道的位置"}},{q="为什么这条大道被废弃了？",a="这条大道在第一次战争后逐渐废弃，特别是当黑石兽人加固了石堡要塞之后。由于缺乏足够的人手来保障道路安全，暴风城无法对其进行维护，导致敌对的豺狼人得以侵入并切断了平民的通行。",al={"为什么被废弃","为什么湖边大道荒无人烟","湖边大道为何荒废"}},{q="今天在路上徘徊的威胁有哪些？",a="这条大道主要受到好斗的豺狼人的威胁，它们会伏击任何从湖畔镇走出来的旅人，此外还有从东部据点出没的零星黑石兽人斥候。",al={"湖边大道的危险","湖边大道的怪物","谁控制着湖边大道"}},{q="这条大道一直都很危险吗？",a="不。在第一次战争前的和平时期，湖边大道是一条维护良好且交通繁忙的路线，安全地连接着赤脊山的腹地与其东部的哨站。",al={"湖边大道历史","战前的大道"}}},fx={d838b935={q="湖边大道是什么路？",a="湖边大道是一条古老的大道，沿着赤脊山止水湖南岸延伸。在第一次战争前的和平时期，它曾是连接当地各处定居点的重要繁忙道路。如今，道路荒废失修，争夺不断，连接着饱受围困的湖畔镇与危机四伏的东部高地。",al={"湖边大道是什么路","湖边大道传说","湖边大道"}},["79cf79b5"]={q="为什么叫湖边大道？",a="这条大道的名字直接源自其地形：它沿着俯瞰赤脊山止水湖南岸的高脊延伸，在湖岸与逐渐升高的南部峭壁之间开辟出一条道路。",al={"湖边大道名称含义","为何叫湖边大道","湖边大道名称由来"}}},fp="17,320,15.451.0,17.420.0,38.189.0,29.249.0,35.187.0,33.181.0"}
P.entries["subzone:lakeshire"] = {n="湖畔镇",s="湖畔镇是赤脊山主要的人类定居点，坐落在止水湖北岸。该镇由所罗门镇长领导，治安官马瑞斯负责保卫，这座如画的小镇目前因黑石兽人、好斗的豺狼人部落以及湖岸鱼人的无休止袭击而濒临崩溃。",h="湖畔镇是赤脊山主要的人类定居点，坐落在止水湖北岸。该镇由所罗门镇长领导，治安官马瑞斯负责保卫，这座如画的小镇目前因黑石兽人、好斗的豺狼人部落以及湖岸鱼人的无休止袭击而濒临崩溃。",kw={"黑石兽人","止水湖大桥","止水湖","湖畔镇","所罗门镇长","治安官马瑞斯","赤脊山","石堡"},ang={["faction:Alliance"]="湖畔镇是暴风城的东方屏障；如果它落入黑石氏族之手，艾尔文森林的核心地带将直接面临兽人的入侵。",["race:Human"]="湖畔镇在对抗部落的战争后重建，对于那些拒绝第二次逃离家园的暴风城难民来说，它象征着历经磨难后的坚韧。"},sec={{t="被围困的城镇",b="湖畔镇曾经是暴风城以东山麓中一片宁静的避风港，如今却已沦为王国最前线的战场。石堡要塞的守军被从北方席卷而下的黑石氏族兽人残酷击溃，黑暗魔法也驱使当地的影皮豺狼人集结成有组织的劫掠团伙。黑石破坏者甚至摧毁了止水湖大桥的部分路段，迫使工头奥斯洛和他的工人们在时刻面临袭击威胁的情况下，艰难地修缮桥梁。随着鱼人占据了湖岸，豺狼人潜伏在山路高处，湖畔镇的守军已到了崩溃的边缘。"},{t="被王室抛弃",b="尽管所罗门镇长多次向山脉彼端发出绝望的恳求，暴风城实际上并未提供任何军事援助。王国的资源因内乱而耗尽，皇家议员们也以边境冲突夸大其词为由，对赤脊山的困境置之不理。从铁炉堡派出的矮人援军在燃烧平原遭到伏击后失踪，只留下治安官马瑞斯和少数残存的卫兵独自坚守防线。湖畔镇现在只能依靠从市政厅直接雇佣的流浪佣兵和自由冒险者来苟延残喘。"}},faq={{q="谁在治理湖畔镇？",a="市政权力由所罗门镇长掌握，他在市政厅指挥镇上的行政事务。当地的防卫和治安工作则由治安官马瑞斯和残破的城镇卫队负责。",al={"湖畔镇领袖","谁负责湖畔镇","湖畔镇镇长"}},{q="为什么暴风城不派兵支援湖畔镇？",a="暴风城的兵力因应对区域动乱而捉襟见肘，而以女伯爵卡特拉娜·普瑞斯托为首的皇家议员们也积极游说伯瓦尔·弗塔根公爵，反对向赤脊山派遣常驻部队，迫使王室只能依赖受委托的冒险者。",al={"为什么没有暴风城援军","暴风城军队 湖畔镇","为什么湖畔镇被遗弃"}},{q="止水湖大桥发生了什么事？",a="黑石兽人在横穿湖泊的袭击中破坏了这座巨大的石桥，严重干扰了贸易和运输。工头奥斯洛负责监督修复工作，但由于工具丢失和持续不断的袭击，工程进展缓慢。",al={"破损的桥梁 赤脊山","谁破坏了止水湖大桥","工头奥斯洛 桥梁"}},{q="目前有哪些威胁包围着该镇？",a="该镇面临着三线围困：盘踞在东方石堡要塞的黑石兽人、由流亡巫师莫甘斯在北部山丘指挥的影皮豺狼人，以及侵扰止水湖水域和岸线的凶猛鱼人。",al={"谁在袭击湖畔镇","赤脊山威胁","湖畔镇敌人"}}},fx={["4f49b93e"]={q="湖畔镇是什么地方？",a="湖畔镇是赤脊山主要的人类聚居地，沿着风景秀丽的止水湖岸而建。作为暴风王国的一处前哨，它为当地的手艺人、渔民和劳工提供了栖身之所。镇上有政务大厅、供旅人歇脚的旅店、马厩，以及一座横跨湖面的醒目石桥。随着这片地区日益陷入困境，湖畔镇已成为文明生活的重要枢纽。",al={"湖畔镇是什么地方","湖畔镇在哪里","湖畔镇"}},cfd70950={q="湖畔镇发生了什么？",a="湖畔镇在与部落的战争中饱受创伤，并于战后的岁月里重建。近来，黑石兽人、暗皮豺狼人以及湖边的敌对鱼人再次对小镇展开了持续不断的围攻。",al={"湖畔镇历史","第一次战争与湖畔镇","湖畔镇发生了什么"}},["7f095f38"]={q="湖畔镇危险吗？",a="治安官马瑞斯和当地的暴风城卫兵仍守卫着镇中心，但周边地区极其危险。黑石兽人频繁发动袭击，已经占领了石堡要塞并摧毁了止水湖大桥。就在镇区外围，凶残的赤脊山豺狼人、被黑暗魔法强化的暗皮豺狼人，以及湖岸边好斗的鱼人，都在不断威胁着守军，随时可能将他们击溃。",al={"湖畔镇有多危险","湖畔镇安全吗","湖畔镇的危险"}}},fp="9,330,18.631.0,22.599.1,22.196.0,52.283.1,38.230.0,41.243.0"}
P.entries["subzone:lakeshire-inn"] = {n="Lakeshire Inn",s="Lakeshire Inn是处于困境中的湖畔镇的社交中心和主要避难所。它坐落在赤脊山的中心地带，为当地居民和与周边危险抗争的疲惫旅人们提供温暖、麦芽酒和安全的住所。",h="Lakeshire Inn是处于困境中的湖畔镇的社交中心和主要避难所。它坐落在赤脊山的中心地带，为当地居民和与周边危险抗争的疲惫旅人们提供温暖、麦芽酒和安全的住所。",kw={"酒吧老板丹尼尔","达希·帕克","旅店老板布丽安娜","止水湖","lakeshire inn","赤脊山旅店","黑衣威利","约鲁斯·巴雷布鲁"},ang={["faction:Alliance"]="Lakeshire Inn是联盟热情好客的典范，不可或缺，它是任何致力于保卫暴风城脆弱东翼的勇士们的大本营。",["profession:Cooking"]="当你在群山中旅行时，公共休息室是一个热闹的地方，你可以从酒吧老板丹尼尔那里购买主食、当地食谱和新鲜的饮料。"},sec={{t="温暖的灯塔",b="Lakeshire Inn坐落在止水湖畔，为人们提供了一个短暂的休憩之所，以躲避不断压向小镇的豺狼人团伙和黑石兽人。尽管湖畔镇的军事形势日益严峻，但酒馆内依然保持着舒适、热闹的氛围。酒吧老板丹尼尔和旅店老板布丽安娜照料着当地人和旅人们，供应着成桶的麦芽酒、葡萄酒和热腾腾的饭菜。这里是一个至关重要的聚会点，镇民们在这里交换消息、消愁解闷，并寻找雇佣兵来保卫王国的东部边境。"},{t="常客与私语",b="除了在柜台边喝闷酒的普通顾客外，旅店还吸引了各种各样的人物。黑衣威利坐在一张桌子旁观察着房间里的一切，他守口如瓶，并密切关注着区域内的危险。像约鲁斯·巴雷布鲁这样的旅行酿酒师会在这里停留，而达希·帕克和其他镇民也是公共休息室的常客。对于那些要深入崎岖山峰或向南前往暮色森林的冒险者来说，这里是进入充满争端的荒野前最后的一座文明与安全的堡垒。"}},faq={{q="Lakeshire Inn提供哪些服务？",a="这家旅店是赤脊山的主要休息站。旅店老板布丽安娜为疲惫的旅人绑定炉石并出租房间，而酒吧老板丹尼尔则为路人提供茶点、食物和饮料。",al={"湖畔镇旅店服务","我能在湖畔镇旅店做什么","湖畔镇旅店老板"}},{q="为什么尽管附近有袭击，旅店还是如此拥挤？",a="随着来自黑石氏族的兽人从北方的山崖涌下，加上豺狼人袭击当地农场，镇民和流离失所的定居者都在寻求小镇中心的庇护。酒馆既提供了物质上的避难所，也是一个分享防御情报的地方。",al={"为什么湖畔镇旅店人满为患","湖畔镇难民旅店","赤脊山酒馆人群"}},{q="黑衣威利是谁？",a="黑衣威利是一名人类潜行者，他在旅店里独来独往。西部荒野的格里安·斯托曼曾经救过他的命，作为回报，威利会向格里安派来的冒险者分享他所知道的关于迪菲亚潜行者的情报。",al={"黑衣威利","湖畔镇酒馆里的人","威利npc"}},{q="旅店位于湖畔镇的什么位置？",a="旅店坐落在湖畔镇西入口附近，紧邻止水湖北岸，就在从艾尔文森林进入小镇的主路旁。",al={"湖畔镇旅店在哪里","湖畔镇酒馆位置","寻找湖畔镇旅店"}}},fx={["4b6fa18d"]={q="湖畔镇旅店是什么地方？",a="湖畔镇旅店是赤脊山湖畔镇的社交中心，也是旅人的避风港。尽管黑石兽人和豺狼人仍不断侵入这片地区，旅店依旧保持着温馨热闹的氛围。这里既是中心酒馆，也是庇护所，旅人、当地居民和疲惫的守军会聚集于此，交流消息、畅饮麦酒与葡萄酒，并找一张安全的床铺休息。",al={"湖畔镇旅店是什么地方","lakeshire inn","湖畔镇旅店简介"}},["13161e3b"]={q="谁在经营湖畔镇旅店？",a="旅店老板布里安娜负责旅店的日常接待和住宿安排，酒吧老板丹尼尔和酒保温塔尔则在酒馆吧台为客人斟上葡萄酒和麦酒。公共休息室里通常坐满当地居民、旅人，以及黑衣威利这类有名的常客。",al={"谁在经营湖畔镇旅店","湖畔镇旅店老板","谁在湖畔镇旅店工作"}},["583be7e3"]={q="湖畔镇旅店危险吗？",a="旅店内部可以为旅人提供庇护和休息之处。湖畔镇周边仍持续受到豺狼人和黑石兽人战团的威胁。",al={"湖畔镇旅店安全吗","湖畔镇旅店的危险","湖畔镇旅店危险吗"}}},fp="13,263,18.532.0,20.514.0,45.203.0,53.255.0,23.232.0,42.161.0"}
P.entries["subzone:lakeshire-town-hall"] = {n="Lakeshire Town Hall",s="Lakeshire Town Hall是赤脊山的行政中心，屹立在湖畔镇的中心地带。所罗门镇长在镇政厅内负责管理当地事务，同时还要应对黑石兽人和豺狼人带来的不断威胁。",h="Lakeshire Town Hall是赤脊山的行政中心，屹立在湖畔镇的中心地带。所罗门镇长在镇政厅内负责管理当地事务，同时还要应对黑石兽人和豺狼人带来的不断威胁。",kw={"黑石","豺狼人","湖畔镇","所罗门镇长","赤脊山","暴风城","镇政厅"},ang={["faction:Alliance"]="Lakeshire Town Hall代表了联盟在赤脊山的东部防线，它像是一座饱经战火的前哨站，在缺乏暴风城王室支持的情况下，绝望地坚守着阵地。",["race:Human"]="对于暴风城的人类来说，这座修缮过的大厅既反映了乡村定居点坚韧不拔的精神，也折射出当首都视而不见时，地方官员所感受到的那种令人沮丧的被遗弃感。"},sec={{t="赤脊山的行政枢纽",b="Lakeshire Town Hall是一座古老的石质建筑，多年来经过多次修缮。它坐落在湖畔镇的显著位置，也是所罗门镇长的办公地点。所罗门是一位和善且敬业的民政领袖，负责维持暴风城王国东部边境的秩序。由于暴风城的军事资源紧张且王室援助匮乏，这座大厅已经从一个安静的行政办公室转变成了一个繁忙的Command Center，每天都在处理招募志愿者和雇佣兵的迫切请求。"},{t="身陷重围，捉襟见肘",b="豺狼人的入侵和黑石兽人的步步紧逼让所罗门陷入了绝望。由于缺乏援助，镇长不得不接受那些走进镇政厅的独立冒险者们的帮助。"}},faq={{q="谁负责Lakeshire Town Hall？",a="所罗门镇长负责管理镇政厅。他是一位和善且心怀好意的管理者，是湖畔镇及周边赤脊山谷的主要行政长官。",al={"谁领导湖畔镇","所罗门镇长","镇政厅里是谁"}},{q="为什么镇政厅寻求那么多外界帮助？",a="湖畔镇面临着当地豺狼人部族和敌对的黑石兽人战帮日益严重的威胁。由于暴风城提供的军事增援极少，所罗门镇长必须雇佣路过的冒险者来保卫这一地区。",al={"为什么所罗门需要帮助","湖畔镇的问题","为什么这里有这么多任务"}},{q="为什么所罗门接受旅行者的帮助？",a="镇上面临的豺狼人和黑石兽人问题让所罗门陷入了绝境。他非常乐意接受那些乐于助人的冒险者所提供的帮助。",al={"为什么所罗门接受援助","湖畔镇的冒险者","镇政厅求助"}},{q="Lakeshire Town Hall存在很久了吗？",a="是的，这是一座经历过动荡岁月的老建筑，为了维持其作为赤脊山行政中心的功能，它经过了多次细致的修缮和翻新。",al={"镇政厅的年代","lakeshire town hall有多古老","镇政厅历史"}}},fx={["21ea7658"]={q="湖畔镇政务大厅是什么地方？",al={"湖畔镇政务大厅是什么地方","湖畔镇政务大厅的用途","湖畔镇政务大厅简介"}},["87431e4d"]={q="湖畔镇政务大厅危险吗？",a="不危险。湖畔镇政务大厅是联盟成员的安全之所。它稳稳地坐落在湖畔镇中心，由当地哨兵守卫；镇长所罗门和忧心忡忡的居民则在此组织地区防御。不过，部落的擅闯者会遭到镇卫兵当场攻击。",al={"湖畔镇政务大厅安全吗","湖畔镇政务大厅里危险吗","湖畔镇政务大厅的危险"}}},fp="19,255,27.550.0,27.207.0,40.183.0,50.234.0,44.141.0,46.170.0"}
P.entries["subzone:lakkari-tar-pits"] = {n="拉卡利油沼",s="拉卡利油沼是位于安戈洛环形山北部一系列散发着恶臭、不断冒泡的黑色粘稠泥浆池。它们坐落在马绍尔营地的悬崖下方，对于毫无防备的野兽来说是天然的死亡陷阱，也是敌对焦油元素生物的温床。",h="拉卡利油沼是位于安戈洛环形山北部一系列散发着恶臭、不断冒泡的黑色粘稠泥浆池。它们坐落在马绍尔营地的悬崖下方，对于毫无防备的野兽来说是天然的死亡陷阱，也是敌对焦油元素生物的温床。",kw={"爬行者","拉卡利","马绍尔营地","焦油兽","油沼","安戈洛"},ang={["class:Hunter"]="在拉卡利附近时，请让宠物待在坚实的地面上；任何陷入粘稠泥浆的生物都会成为掠食性焦油潜伏者的固定目标。"},sec={{t="危险的陷阱",b="拉卡利油沼占据了安戈洛环形山北部的低洼地带，就在马绍尔营地的正南方。粘稠、恶臭的沥青池会困住任何不小心踏入其中的生物，迅速让野兽和冒险者寸步难行。数百只史前生物裸露的骨头从黑色的表面伸出，见证了数代动物被吸入泥潭的惨状。机会主义的食腐动物在边缘徘徊，等待被困的猎物精疲力竭，而活生生的焦油兽、潜伏者和爬行者会直接从淤泥中升起，攻击入侵者。"}},faq={{q="踏入焦油会发生什么？",a="这种沥青极其粘稠且具有吸附性。涉入焦油会使移动速度瞬间降至龟速，让人极其难以躲避在表面巡逻的具有攻击性的焦油元素生物。",al={"油沼效果","焦油减速","踩入焦油"}},{q="拉卡利油沼里居住着什么生物？",a="这些泥沼中栖息着有知觉的软泥和元素生命体，被称为焦油兽、焦油爬行者、焦油潜伏者和焦油领主，还有在池塘边徘徊寻找被困猎物的当地食腐动物。",al={"焦油兽","油沼怪物","焦油爬行者"}},{q="拉卡利油沼在哪里？",a="它们位于安戈洛环形山北部，坐落在马绍尔营地悬崖哨所下方的盆地中。",al={"油沼位置","拉卡利在哪里","如何找到油沼"}}},fp="16,264,15.573.0,38.211.0,44.205.0,39.125.0"}
P.entries["subzone:land-s-end-beach"] = {n="天涯海滩",s="天涯海滩是塔纳利斯最南端一片荒凉的海岸线，实际上标志着卡利姆多的南端边缘。它被高耸的山脊和广阔的海洋环绕，是大陆上最隐蔽、最难以到达的海岸之一。",h="天涯海滩是塔纳利斯最南端一片荒凉的海岸线，实际上标志着卡利姆多的南端边缘。它被高耸的山脊和广阔的海洋环绕，是大陆上最隐蔽、最难以到达的海岸之一。",kw={"海滩","海岸","卡利姆多","天涯海滩","岸边","南海","塔纳利斯","奥丹姆"},sec={{t="世界之极",b="天涯海滩隐藏在塔纳利斯南部山脉和通往奥丹姆的泰坦封印大门后，代表着卡利姆多大陆最南端的尽头。由于陆路无法跨越沙漠沙丘，要到达这片饱受风霜的海岸，必须沿着南海危险且令人疲惫的开阔水域游过去。这片海滩是一处荒芜的边境，只有汹涌的海浪、流动的沙丘和静谧的孤寂，很少受到居住在北方加基森附近的财团或沙漠探险家的染指。"},{t="近海之谜",b="海滩的碎浪之外，是一些孤独、无名的岛屿，它们与大陆隔着广阔且令人筋疲力尽的深水区。航行前往这些遥远的岩礁点十分危险，足以将经验丰富的游泳者推向体能极限。几乎没有凡人有理由去探索卡利姆多尽头的寂静水域，使得这片海滩及其周围的浅滩在烈日当空下保持着不被打扰的状态。"}},faq={{q="天涯海滩位于哪里？",a="天涯海滩位于塔纳利斯的最南端海岸，就在隔绝了卡利姆多最南端古老奥丹姆泰坦之门的山脉以南。",al={"天涯海滩在哪里","天涯海滩位置","如何找到天涯海滩"}},{q="如何到达天涯海滩？",a="由于巨大的山脉阻挡了从沙漠内部出发的陆路通道，旅行者通常必须沿着塔纳利斯东部的南海岸游过去，或者绕过危险的开阔水域，注意不要在深海中因疲劳而溺亡。",al={"我该如何前往天涯海滩","前往塔纳利斯天涯海滩","到达天涯海滩"}},{q="海滩外的岛屿上有什么？",a="遥远且无名的岛屿坐落在远离海岸线的地方，中间隔着宽阔的深海航道，令人疲惫不堪。它们是荒凉的岩石礁，几乎没有旅行者到达或探索过。",al={"天涯海滩无名岛屿","塔纳利斯近海岛屿","天涯海滩附近的岛屿"}},{q="有人居住在天涯海滩吗？",a="这条海岸线上没有任何大型定居点。由于与贸易和文明隔绝，它依然是一片饱受海风吹拂的荒凉自然海岸。",al={"谁住在天涯海滩","天涯海滩居民","天涯海滩有人吗"}}},fp="16,276,21.525.0,18.420.0,34.184.0,34.261.0,50.189.0,37.154.0"}
P.entries["subzone:lariss-pavilion"] = {n="拉瑞斯小亭",s="拉瑞斯小亭是一座古老的精灵建筑，坐落在菲拉斯的荒野之中，就在莫沙彻营地以北。虽然它曾经是暗夜精灵古典建筑风格的宁静休憩之所，但周围的森林因受腐蚀的树妖而变得危险，一位被流放的上层精灵法师如今在它的阴影中等待时机。",h="拉瑞斯小亭是一座古老的精灵建筑，坐落在菲拉斯的荒野之中，就在莫沙彻营地以北。虽然它曾经是暗夜精灵古典建筑风格的宁静休憩之所，但周围的森林因受腐蚀的树妖而变得危险，一位被流放的上层精灵法师如今在它的阴影中等待时机。",kw={"阿兹托里恩","莫沙彻营地","厄运之槌","树妖","菲拉斯","上层精灵","拉瑞斯小亭","普希林","克拉什·火刃"},ang={["class:Mage"]="对于奥术修行者来说，孤独的上层精灵阿兹托里恩代表了埃雷萨拉斯古老、不受约束的法术技艺的活遗迹。",["race:NightElf"]="对于暗夜精灵来说，小亭是一处令人苦涩的景象——不仅因为它的美丽被上层精灵的傲慢遗风所掩盖，还因为周围的树妖同胞正饱受黑暗腐蚀的折磨。"},sec={{t="上层精灵的废墟",b="拉瑞斯小亭静静地矗立在莫沙彻营地以北的峭壁上，展示着古老卡多雷帝国优美的石雕工艺和高耸的拱门。在全盛时期，它曾服务于伟大的埃雷萨拉斯城，即现在的厄运之槌。如今，它为菲拉斯茂密的树冠提供了一处隐蔽的瞭望点，但这里的宁静十分脆弱：曾经在周围林地漫步的温顺树妖已陷入疯狂和腐蚀，对任何靠近的人都变得极其敌视。"},{t="阿兹托里恩与隐藏通道",b="小亭中最引人注目的住客是行踪隐秘的精灵阿兹托里恩。他脱离了托塞德林王子在厄运之槌的腐朽统治，通过一条直接连接该亭与古城腹地的秘密通道逃出了废墟。然而，他平静的流放生活已被打破：一个名叫普希林的顽劣小鬼偷走了他珍贵的咒语书，这让这位流放者不得不寻求外界的帮助以找回它。"}},faq={{q="拉瑞斯小亭位于哪里？",a="拉瑞斯小亭位于菲拉斯东部的高地森林地形中，就在部落据点莫沙彻营地以北。",al={"拉瑞斯小亭位置","拉瑞斯小亭在哪里","如何前往拉瑞斯小亭"}},{q="阿兹托里恩是谁？",a="阿兹托里恩是一位古老的上层精灵术士，他逃离了厄运之槌内暴虐的托塞德林王子。他现在在小亭安营扎寨，寻找冒险者帮他从一个恶作剧的小鬼那里找回一本被偷走的咒语书。",al={"阿兹托里恩","拉瑞斯小亭的精灵是谁","拉瑞斯小亭任务发放者"}},{q="为什么小亭周围的树妖如此敌视？",a="在小亭附近林中徘徊的树妖已经屈服于蔓延在菲拉斯荒野中的腐蚀，将原本深居简出的自然守护者变成了凶残的攻击者。",al={"愤怒的树妖","为什么树妖会攻击","菲拉斯受腐蚀的树妖"}},{q="小亭如何与厄运之槌相连？",a="拉瑞斯小亭底部有一条隐蔽的后门，直通厄运之槌，这也是阿兹托里恩用来从他的族人中溜走的逃生路线。",al={"厄运之槌后门","厄运之槌捷径","秘密通道"}}},fp="15,312,23.484.0,33.435.0,33.129.0,18.220.0,47.190.0,43.158.0"}
P.entries["subzone:launch-bay"] = {n="Launch Bay",s="Launch Bay是一座位于诺莫瑞根深处的地下机场和机库，坐落在Hall of Gears之外。它曾是侏儒飞行器和轰炸机的集结地，如今已完全被充满敌意的麻风侏儒和腐化的机械装置所控制。",h="Launch Bay是一座位于诺莫瑞根深处的地下机场和机库，坐落在Hall of Gears之外。它曾是侏儒飞行器和轰炸机的集结地，如今已完全被充满敌意的麻风侏儒和腐化的机械装置所控制。",kw={"轰炸机","黑铁矮人","engineering labs","飞行器","诺莫瑞根","机库","launch bay","麻风侏儒"},ang={["profession:Engineering"]="机库展示了顶尖的侏儒航空技术和载具底盘，不过拾荒者必须应对敌对的机械装置才能近距离观察它们。",["race:Gnome"]="看到侏儒航空业的瑰宝——飞行器和轰炸机——被废弃并爬满了受辐射的麻风侏儒，让人不禁感到这座城市悲剧性没落的苦涩。"},sec={{t="停飞的机场",b="作为诺莫瑞根空中舰队的主要机库，Launch Bay分为两层。其中心平台可以通过从上层走廊延伸出的坡道到达，那里至今仍停放着在城市撤离前未能起飞的侏儒飞行器和重型轰炸机。现在，飞行甲板上并没有技术高超的飞行员，取而代之的是成群结队、陷入疯狂的麻风侏儒，他们负责维护并守卫着这些处于闲置状态的战争机器。"},{t="深渊之城的十字路口",b="除了军事作用外，Launch Bay还是这座综合体内的重要交汇点。东南走廊的坡道向下通往Engineering Labs，而下层甲板的一条南向通道则被入侵的黑铁矮人堵塞。那条南侧隧道是前往城市中心Tinkers' Court的一条危险路径。"}},faq={{q="Launch Bay有什么用途？",a="它最初被设计为侏儒飞行器和轰炸机的地下机场和维护机库。如今，它已被遗弃，并被栖息在废墟中的麻风侏儒挪作他用。",al={"诺莫瑞根机库","什么是launch bay","launch bay用途"}},{q="现在谁控制着Launch Bay？",a="上层和下层被麻风侏儒和极具攻击性的机械装置所占据。在更深处的南侧出口附近，充满敌意的黑铁矮人也建立了自己的据点。",al={"谁在launch bay","launch bay敌人","谁住在这里"}},{q="Launch Bay通向哪里？",a="上层的东侧隧道通回Hall of Gears。东南侧的坡道向下连接到Engineering Labs，而下层的一条南向隧道则继续向诺莫瑞根深处延伸，通往Tinkers' Court。",al={"launch bay出口","如何离开launch bay","launch bay方向"}},{q="这里的飞行机器还能用吗？",a="几架侏儒飞行器和轰炸机仍然停放在中心平台上，但随着城市的沦陷，它们一直闲置且无人照看，处于混乱之中。",al={"我能驾驶飞机吗","诺莫瑞根飞行器","机库飞机"}}},fx={["7077c2fc"]={q="Launch Bay是什么地方？",a="Launch Bay又称机库，是诺莫瑞根地下城市中的一座大型多层设施。它可经由与Hall of Gears相连的隧道抵达，分为上下两层，用于存放、维护和派遣侏儒飞行器与空中轰炸机。",al={"launch bay是什么地方","诺莫瑞根的launch bay","诺莫瑞根机库"}},["618f410c"]={q="Launch Bay发生了什么？",a="穴居人入侵诺莫瑞根时，大工匠梅卡托克下令排放放射性废料，整座城市因此陷入灾难。Launch Bay也随着首都的其他区域一同沦陷，飞行器被困在停机坪上，侏儒技师则陆续死于辐射中毒或陷入疯狂。",al={"launch bay的历史","launch bay发生了什么","launch bay为何被遗弃"}},cbaccda1={q="Launch Bay危险吗？",a="是的，这里极其危险。舱区里到处都是充满敌意、遭受辐射的麻风侏儒和不稳定的机械装置。此外，下面的出口通往隧道，隧道中潜伏着黑铁矮人渗透者；他们已经深入这座沦陷的城市，企图将其中的奇珍异宝据为己有。",al={"launch bay危险吗","launch bay的危险","launch bay的威胁"}},c8b4c6a3={q="为什么叫Launch Bay？",a="它因曾是诺莫瑞根空军的主要集结地和机库而得名。过去，侏儒飞行员会在这里的平台上驾驶飞行器和实验型轰炸机，经由地下排气道和发射通道升空。",al={"launch bay为何得名","launch bay名称由来","launch bay名称含义"}}},fp="10,302,19.415.0,27.339.0,32.191.0,32.198.0,31.201.0,41.149.0"}
P.entries["subzone:lethlor-ravine"] = {n="莱瑟罗峡谷",s="莱瑟罗峡谷是一条蜿蜒在荒芜之地东部的崎岖岩石峡谷。这里是黑龙军团一处危险的栖息地和繁殖场，到处都是充满攻击性的幼龙和成年幼龙。",h="莱瑟罗峡谷是一条蜿蜒在荒芜之地东部的崎岖岩石峡谷。这里是黑龙军团一处危险的栖息地和繁殖场，到处都是充满攻击性的幼龙和成年幼龙。",kw={"荒芜之地","黑龙军团","成年幼龙","莱瑟罗峡谷","方尖碑","幼龙"},ang={["class:Hunter"]="莱瑟罗峡谷的天空和山脊是对抗高速移动的龙人和带翼掠食者，考验射击技术的绝佳场所。"},sec={{t="龙族堡垒",b="莱瑟罗峡谷深深地刻在荒芜之地东部那被灼烧的高原上，是这片沙漠中最危险的地段之一。险峻的峡谷岩壁为黑龙军团提供了天然的巢穴，这里布满了凶猛的幼龙巢穴，并由体型更大、能喷火的成年幼龙守卫。很少有旅行者敢靠近谷底，因为头顶上方不断有在岩石尖塔间盘旋的带翼掠食者，它们的影子时刻提醒着人们这里的危险。"},{t="尘土中的谜团",b="除了占据此地的鳞片族群外，莱瑟罗峡谷的显著特征是散布在岩石间的奇特水晶方尖碑。这些水晶构造与当地的一条任务线有关。其起源尚未确定。"}},faq={{q="莱瑟罗峡谷是什么地方？",a="莱瑟罗峡谷是一条深邃、崎岖的峡谷，位于荒芜之地东侧，主要作为黑龙的筑巢地。",al={"莱瑟罗峡谷在哪里","这条峡谷是什么","莱瑟罗峡谷信息"}},{q="为什么这里有这么多黑龙？",a="黑龙军团利用莱瑟罗峡谷隐蔽而荒凉的岩石地貌进行栖息和繁育后代，将峡谷变成了一个远离主要文明城市的坚固育婴室。",al={"为什么荒芜之地有龙","莱瑟罗巨龙","荒芜之地的黑龙军团"}},{q="峡谷里的水晶方尖碑是什么？",a="这些水晶方尖碑是散布在峡谷各处的构造物，与当地的一条任务线有关。其起源尚未确定。",al={"莱瑟罗水晶塔","莱瑟罗峡谷的石柱","荒芜之地方尖碑"}},{q="莱瑟罗峡谷对旅行者来说安全吗？",a="不安全。这个峡谷极其危险，到处都是飞行的成年幼龙和充满攻击性的幼龙，它们会一见到入侵者就发起攻击。",al={"我能穿过莱瑟罗峡谷吗","莱瑟罗峡谷危险吗"}}},fp="14,222,24.440.0,21.226.0,23.145.0,41.198.0,44.141.0,37.120.0"}
P.entries["subzone:library-ironforge"] = {n="Library (Ironforge)",s="图书馆位于Hall of Explorers的东翼，是铁炉堡最重要的历史知识、考古文物和古代传说的宝库。它由探险者协会勤勉地维护，收藏了大量的历史典籍以及从艾泽拉斯各地的发掘工作中回收的珍贵文物。",h="图书馆位于Hall of Explorers的东翼，是铁炉堡最重要的历史知识、考古文物和古代传说的宝库。它由探险者协会勤勉地维护，收藏了大量的历史典籍以及从艾泽拉斯各地的发掘工作中回收的珍贵文物。",kw={"书籍","索里奥斯馆长","探险者协会","hall of explorers","铁炉堡","图书馆","梅·尘灰","博物馆"},ang={["faction:Alliance"]="图书馆是联盟极其宝贵的战略档案库，保存着来自洛丹伦联盟的关键记录以及第二次和第三次战争的目击报告。",["race:Dwarf"]="对于矮人来说，这个大厅代表了国王麦格尼·铜须探索他们泰坦起源的努力，这里收藏着关于觉醒和三锤之战的原始记载。"},sec={{t="探险者协会的心脏",b="图书馆占据了Hall of Explorers内的一个巨大房间，是矮人学者们筛选来自世界各地的冒险者带回的文物和实地报告的地方。这里由探险者协会管理，书架上摆满了基础编年史，详细记载了三锤之战、古老的巨魔战争以及矮人种族的起源。有关Rare Books或档案位置的咨询，请找图书管理员梅·尘灰。"},{t="博物馆陈列",b="在成排的密集书架之外，图书馆还兼作一个由索里奥斯馆长监督的职能博物馆。在这里，从深层挖掘、废弃遗迹和遥远海岸线收集到的实物标本都会经过分析、保存和展示。协会的馆长们会保存从粗糙的鱼人雕像和雕刻刀，到在北方冰原中发现的神秘遗迹等各种物品，并将每一件发现编目，以拼凑出泰坦和早期艾泽拉斯隐藏的历史。"}},faq={{q="铁炉堡图书馆的目的是什么？",a="它是探险者协会的主要研究档案库和博物馆。协会成员将回收的文物、典籍和实地笔记带到这里进行编目、破译，并为矮人人民和联盟进行保存。",al={"铁炉堡图书馆用途","这是什么地方","探险者大厅图书馆"}},{q="这里的藏品由谁管理？",a="图书馆的文字藏品和档案检索由图书管理员梅·尘灰协助，而博物馆区域及其相关的历史文物则由索里奥斯馆长负责策展和维护。",al={"谁管理图书馆","铁炉堡图书管理员","博物馆馆长"}},{q="这里可以读到什么样的书？",a="图书馆收藏了涵盖古代和现代事件的基础历史著作，包括上古之神、巨龙军团、巨魔战争、三锤之战、部落的崛起以及洛丹伦联盟的组建。",al={"铁炉堡书籍","可阅读典籍","这里有什么传说"}},{q="图书馆在铁炉堡的什么位置？",a="图书馆位于Hall of Explorers的东翼，坐落在铁炉堡的东北象限。",al={"铁炉堡图书馆位置","如何找到图书馆"}}},fx={["0caa8ddd"]={q="铁炉堡的图书馆是什么地方？",a="图书馆是一处规模宏大的知识、历史与古代文物收藏地，位于铁炉堡探险者大厅的东翼。它可以说是这座山城中最大的单体建筑，既是收藏大量历史典籍的档案馆，也是开放中的博物馆。这里还是矮人学者和探险者协会外勤人员的主要行动基地。",al={"图书馆是什么地方","铁炉堡图书馆信息","铁炉堡图书馆"}},["8f38528b"]={q="铁炉堡图书馆危险吗？",a="图书馆位于铁炉堡内，十分安全。学者、档案管理员和探险者协会成员在此忙碌地研究回收的遗物与历史记录。",al={"图书馆危险吗","铁炉堡图书馆的危险","图书馆里的威胁"}}},fp="19,321,30.465.0,19.470.0,48.230.0,33.202.0,36.239.0,42.115.0"}
P.entries["subzone:library-wing-northshire"] = {n="Library Wing (Northshire)",s="图书室是位于艾尔文森林北郡修道院南侧的一处安静的区域，书架林立。它是学者们的避风港，为投身于保卫暴风城事业的初级牧师和法师提供早期指导。",h="图书室是位于艾尔文森林北郡修道院南侧的一处安静的区域，书架林立。它是学者们的避风港，为投身于保卫暴风城事业的初级牧师和法师提供早期指导。",kw={"艾尔文森林","凯尔登·布雷门","图书室","法师训练师","北郡","北郡修道院","牧师训练师","女牧师安妮塔"},ang={["class:Mage"]="凯尔登·布雷门在这安静的大厅内指导新晋法师，传授火焰与冰霜的基础学科。",["class:Priest"]="女牧师安妮塔在此常驻，为初级牧师传授引导圣光来治愈伤口和打击敌人的第一课。"},sec={{t="奥术与神圣研究的殿堂",b="图书室从北郡修道院的主厅向南延伸，这里摆满了积尘的书架、阅读台和安静的小隔间，专门用于智力和精神层面的训练。当武艺新兵在修道院对面的Hall of Arms进行操练时，有志成为法师和牧师的学徒们会聚集在此，掌握奥术和圣光的基本原理。目前，女牧师安妮塔在这里引导新晋牧师学习信仰与治疗之道，而凯尔登·布雷门则教导初出茅庐的法师如何塑造原始的元素能量。"}},faq={{q="图书室位于何处？",a="图书室占据了北郡修道院的南侧区域，紧邻主厅。它正对着用于武艺训练的Hall of Arms。",al={"图书室在哪里","如何找到北郡图书馆","北郡图书馆位置"}},{q="这个侧厅的用途是什么？",a="它是北郡修道院的学术与精神中心，专门致力于学术研究、魔法教学以及为训练效力于暴风城王国的新兵们提供祈祷场所。",al={"为什么北郡修道院有图书馆","图书室用途"}}},fx={["43e724fe"]={q="图书馆侧翼是什么地方？",a="图书馆侧翼是北郡修道院的南翼，与兵器大厅和中央大厅的军事喧嚣隔开。这里专供静心研习、秘法修习与疗愈，为年轻的施法者和侍僧提供一处圣所，让他们学习圣光与奥术的基础教义。",al={"图书馆侧翼是什么地方","北郡图书馆侧翼","关于图书馆侧翼"}},cc13243a={q="谁住在图书馆侧翼，或在这里授课？",a="女牧师安妮塔和法师训练师凯尔登·布雷门住在这里，负责指导响应暴风城号召的新兵。你还会在书架间和学习隔间里看到他们的学员以及受伤的学员；他们正在修道院治疗者的悉心照料下休养。",al={"谁在图书馆侧翼","图书馆侧翼的训练师","谁在图书馆侧翼授课"}},["240ac0ef"]={q="图书馆侧翼危险吗？",a="侧翼本身十分安全，北郡修道院坚固的石墙和警戒森严的守卫会保护这里。然而，正在休养的伤员提醒着人们，周围的山谷并不太平：那里有凶猛的野生动物出没，也有迪菲亚暴徒不断侵扰。",al={"图书馆侧翼安全吗","图书馆侧翼的危险","图书馆侧翼的威胁"}}},fp="25,224,32.508.0,34.152.0,33.189.0"}
P.entries["subzone:library-wing-tyr-s-hand"] = {n="Library Wing (Tyr's Hand)",s="图书馆侧厅是Tyr's Hand Abbey内的一处僻静大厅，坐落于东瘟疫之地中血色十字军戒备森严的堡垒深处。这里曾经致力于神圣的研究与沉思，如今书架上却充斥着这个狂热组织僵化的教条和宣传。十字军的成员聚集于此研读经文，并守卫着密室中的宗教圣物。",h="图书馆侧厅是Tyr's Hand...",kw={"修道院","东瘟疫之地","图书馆侧厅","宣传","血色十字军","典籍","提尔之手"},ang={["class:Paladin"]="圣骑士们认为该侧厅是对白银之手原始学术传统的扭曲，对圣光的虔诚已被激进的狂热所取代。",["class:Priest"]="对于圣职修行者来说，图书馆侧厅是一个苦涩的展示，表明了神圣的沉思是如何腐化为狭隘的极端主义和妄想的。"},sec={{t="狂热之学密室",b="图书馆侧厅位于Tyr's Hand Abbey中央大殿侧翼，与武备区相对，反映了血色十字军的思想核心。在这些安静的石制拱廊内，牧师和十字军沉浸在神学论文、激进教义以及被多年对抗天灾军团的无情战争所扭曲的著作中。这里收藏的文献并没有传承开放的学术精神，反而助长了十字军的妄想，强化了他们认为所有外来者都带有腐化污点的信念。"},{t="圣光容器",b="除了收藏党派卷轴和经文外，图书馆侧厅还由血色修道士严密把守。想要到达其内室，必须突破精英血色防卫者的防线，他们将图书馆视为信仰的堡垒和坚不可摧的要塞。"}},faq={{q="图书馆侧厅位于哪里？",a="图书馆侧厅位于Tyr's Hand Abbey内部，地处东瘟疫之地东南部的提尔之手血色十字军飞地。在修道院内，它位于主入口大厅的南侧，与Hall of Arms相对。",al={"图书馆侧厅位置","图书馆侧厅在哪里","如何找到提尔之手的图书馆侧厅"}},{q="这里存放着什么样的书籍？",a="书架上摆放着圣光的神学文本，以及血色十字军为了证明他们针对亡灵和外来者的无尽十字军东征是合理的，而狂热编纂的激进教义和文学作品。",al={"图书馆里有什么书","提尔之手图书馆典籍","图书馆侧厅存放着什么"}},{q="谁控制着修道院的这一部分？",a="图书馆侧厅由血色十字军的精锐部队牢牢掌控，包括教士、学者以及全副武装、驻守在此以保护其教条文献和圣化补给的防卫者。",al={"谁在图书馆侧厅","谁控制着图书馆侧厅"}},{q="参观图书馆侧厅危险吗？",a="是的，非常危险。图书馆位于提尔之手深处，这是一个由高等级狂热分子驻守的血色十字军精英据点，他们会对入侵者发起攻击。",al={"图书馆侧厅安全吗","提尔之手图书馆难度"}}},fp="25,379,23.516.0,20.273.0,34.235.0,34.213.0,36.198.0,39.175.0"}
P.entries["subzone:light-s-hope-chapel"] = {n="圣光之愿礼拜堂",s="圣光之愿礼拜堂是位于东瘟疫之地东部边缘的一座神圣避难所，也是银色黎明的主要堡垒和总部。它曾经是东维尔德圣光教会的一座偏僻神殿，如今已成为抵御天灾军团的持久屏障。",h="圣光之愿礼拜堂是位于东瘟疫之地东部边缘的一座神圣避难所，也是银色黎明的主要堡垒和总部。它曾经是东维尔德圣光教会的一座偏僻神殿，如今已成为抵御天灾军团的持久屏障。",kw={"银色黎明","圣地","东维尔德","圣光","圣光之愿","瘟疫之地","泰罗索斯"},ang={["class:Paladin"]="对于圣光战士来说，圣光之愿礼拜堂是死亡之海中的一座神圣灯塔，是银色黎明守卫的一座古老的圣光神殿。",["faction:Horde"]="虽然礼拜堂位于人类领地的深处，并由前白银之手骑士团的成员管理，但它欢迎所有证明了自己铲除亡灵决心的部落战士。"},sec={{t="瘟疫之地中的堡垒",b="圣光之愿礼拜堂最初是位于郁郁葱葱的东维尔德圣光教会的一座礼拜堂，在洛丹伦陷落后，它成为了这片受腐蚀土地上至关重要的避难所。当幸存者中狂热的极端分子分裂并组建了血色十字军时，更多温和的骑士和牧师联合起来建立了银色黎明。黎明选择这个偏僻而神圣的地方作为他们的前进基地，向所有种族和阵营敞开了大门——无论是联盟还是部落——他们团结一致，共同投身于铲除天灾军团并收复北方领土的圣战。"}},faq={{q="为什么联盟和部落会在圣光之愿礼拜堂合作？",a="银色黎明认为天灾军团是对所有生物生存的威胁，这种威胁超越了联盟和部落之间激烈的政治分歧。与狂热且推崇人类至上的血色十字军不同，银色黎明积极招募愿意对抗亡灵的各种族的能工巧匠、萨满祭司、德鲁伊和牧师。",al={"为什么部落被允许进入这里","银色黎明中立","跨阵营基地"}},{q="谁在这里领导防御者？",a="玛克斯韦尔·泰罗索斯男爵在圣光之愿礼拜堂领导银色黎明，指挥该组织在整个瘟疫之地对抗天灾军团的战争。",al={"谁负责圣光之愿礼拜堂","银色黎明领袖","泰罗索斯男爵"}},{q="为什么这座礼拜堂如此神圣？",a="圣光之愿礼拜堂是东维尔德圣光教会的一座神圣礼拜堂。它神圣的土地如今庇护着银色黎明的总部，是深陷天灾军团控制下的瘟疫之地中罕见的一座圣光灯塔。",al={"礼拜堂下面有什么","为什么天灾军团想要圣光之愿礼拜堂","礼拜堂下的圣所"}},{q="这座礼拜堂与血色十字军有什么关系？",a="尽管银色黎明是由拒绝了血色十字军疯狂狂热和孤立主义的圣骑士和牧师组成的，但这两个组织在对抗天灾军团这一共同敌人上立场一致。银色黎明以自己的方式在礼拜堂抗击天灾，并向所有愿意对抗亡灵的人敞开大门。",al={"他们和血色十字军是朋友吗","血色十字军圣光之愿礼拜堂","银色黎明与血色十字军"}}},fp="19,293,28.585.0,67.327.0,29.138.0,29.224.0,64.289.0"}
P.entries["subzone:lion-s-pride-inn"] = {n="Lion's Pride Inn",s="Lion's Pride Inn是艾尔文森林闪金镇繁忙的酒馆和社区中心。由旅店老板法雷经营，它是旅客在暴风城以南冒险时的主要休息处、聚会厅和雇佣场所。",h="Lion's Pride Inn是艾尔文森林闪金镇繁忙的酒馆和社区中心。由旅店老板法雷经营，它是旅客在暴风城以南冒险时的主要休息处、聚会厅和雇佣场所。",kw={"艾尔文森林","法雷","闪金镇","闪金镇旅店","旅店老板法雷","lion's pride inn","lions pride"},ang={["faction:Alliance"]="作为暴风城门外的主要旅店，它是一个繁忙的中转站，联盟旅客在此协调巡逻并在这片中心地带进行贸易。",["race:Human"]="对于从北郡修道院出发的人类来说，Lion's Pride Inn是他们初次接触修道院围墙之外王国广阔生活与纷扰的地方。"},sec={{t="闪金镇的核心",b="Lion's Pride Inn位于艾尔文森林的十字路口，是闪金镇热闹的中心地带。在旅店老板法雷的管理下，秉承着酒馆的传统座右铭——“为疲惫和寒冷之人提供休息与放松”——这家旅店为刚离开北郡的疲惫冒险者提供了温暖的炉火、烈酒和客房。由于闪金镇位于暴风城、西部荒野、赤脊山和暮色森林之间的重要贸易路线上，这家酒馆成为了不可或缺的集结地，镇上的治安官、当地工匠和经验丰富的训练师们聚集于此，分享消息并雇佣过往的雇佣兵。"}},faq={{q="谁拥有并经营Lion's Pride Inn？",a="这家旅店由旅店老板法雷经营，他以“为疲惫和寒冷之人提供休息与放松”的座右铭欢迎疲惫的旅客。",al={"旅店老板","谁拥有lions pride","谁经营闪金镇旅店"}},{q="旅店里有哪些服务？",a="除了食物、饮料和住宿，Lion's Pride Inn还设有各种职业训练师、到访的商人以及寻求帮助以解决困扰艾尔文森林的豺狼人、狗头人和强盗问题的当地任务发布者。",al={"训练师","里面有什么","设施"}},{q="为什么这家旅店是艾尔文森林的核心枢纽？",a="旅店坐落在暴风城以南的闪金镇十字路口，是往返于首都、西部荒野和赤脊山之间的旅客的主要休息站。它是年轻冒险者离开北郡山谷后自然而然造访的第一个主要枢纽。",al={"为什么这么受欢迎","闪金镇十字路口","lions pride的重要性"}},{q="Lion's Pride Inn的座右铭是什么？",a="根据旅店老板法雷的说法，这家旅店的创立座右铭是“为疲惫和寒冷之人提供休息与放松”。",al={"旅店座右铭","座右铭"}}},fx={["3778d523"]={q="狮王之傲旅店是什么地方？",a="狮王之傲旅店也称闪金镇旅店，是艾尔文森林闪金镇里热闹的中心。它是当地居民、镇卫和沿着暴风城大道旅行的疲惫旅人主要的聚集地、酒馆和住宿场所。",al={"狮王之傲旅店是什么地方","艾尔文森林的狮王之傲旅店","闪金镇旅店的传说"}},["4a999086"]={q="狮王之傲旅店有什么历史？",a="这家旅店长期以来一直是闪金镇的中心庇护所。旅店老板法雷经营着这里，旅店以“让疲惫寒冷的旅人休息放松”为宗旨，为路途中的人们提供诚实而热情的炉边款待。",al={"狮王之傲旅店的历史","闪金镇旅店背景","法雷家旅店的历史"}},b8029b33={q="狮王之傲旅店危险吗？",a="旅店本身十分安全，有驻扎在闪金镇的暴风城卫戍部队严密守卫。外面的道路上偶尔会发生喧闹的斗殴和小规模冲突，周围的树林里则遍布狗头人、迪菲亚暴徒和豺狼人；但在旅店之内，你只会得到休息与庇护。",al={"狮王之傲旅店安全吗","狮王之傲旅店的危险","闪金镇旅店危险吗"}}},fp="16,246,18.588.0,39.131.0,43.208.0,44.279.0,42.104.0"}
P.entries["subzone:loading-room"] = {n="Loading Room",s="Loading Room是诺莫瑞根庞大机械综合设施内的一间工业装载室。在当今时代，这个地下的中转区位于受损的废弃首都深处，极其靠近像Techbot这样的失控构造体。",h="Loading Room是诺莫瑞根庞大机械综合设施内的一间工业装载室。在当今时代，这个地下的中转区位于受损的废弃首都深处，极其靠近像Techbot这样的失控构造体。",kw={"丹莫罗","诺莫瑞根","loading room","techbot","工匠镇","train depot"},ang={["profession:Engineering"]="失控的构造体Techbot以及留在Loading Room里的机械组件，为工程师们提供了一个严酷的教训：当自动化防御系统在缺乏维护的情况下发生故障时，会造成什么样的后果。",["race:Gnome"]="对于诺莫瑞根的收复者来说，Loading Room痛苦地提醒着人们，在石腭怪入侵和有毒灾难期间，日常城市基础设施是如何被暴力遗弃的。"},sec={{t="围城中的工业仓库",b="在诺莫瑞根陷落之前，Loading Room曾是连接这座工匠首都地下交通网络的繁忙中转点和货物装卸区。如今，和这座废墟城市的其他部分一样，这里已经陷入了混乱。放射性尘埃、入侵的石腭怪以及故障的机械使得该区域变得极度危险。失控的机械构造体Techbot守卫着附近区域，对任何试图稳固防线的诺莫瑞根幸存者或大胆的联盟收复者构成了严重的威胁。"}},faq={{q="Loading Room有什么用途？",a="历史上，它是连接诺莫瑞根内部交通和列车设施的工业装载区和货物中转点。自城市陷落以来，它已沦为另一个被各种危险所占据的失落区域。",al={"loading room用途","什么是loading room","loading room过去是什么"}},{q="在Loading Room里会遇到什么威胁？",a="Loading Room是失控机械防御构造体Techbot的所在地，此外还有城市深处残留的放射性污染和不稳定的机械。",al={"谁在loading room里","loading room首领","techbot位置"}},{q="Loading Room可以安全探索吗？",a="不可以。整个区域都是诺莫瑞根废墟内的争夺地。任何冒险进入这部分设施的联盟突击小队都必须面对敌对的构造体和有毒的环境。",al={"这里安全吗","联盟可以去这里吗"}}},fx={["3f72b894"]={q="装载室是什么地方？",a="装载室是诺莫瑞根这座沦陷的科技奇迹中的一处工业舱室，位于城市错综复杂的基础设施深处。城市被穴居人占领并遭受辐射污染之前，这里曾承担机械运输和货物装卸功能。在如今这个时代，穿行于这座受辐射污染的地下都市、躲避重重危险的人们会直接经过这里。",al={"装载室是什么地方","诺莫瑞根装载室","关于装载室"}},a3501e82={q="装载室发生了什么？",a="和诺莫瑞根的其他区域一样，装载室在穴居人入侵以及随后爆发的灾难性放射性尘埃中沦陷。大工匠Gelbin Mekkatorque及其顾问为了阻止地下野兽，下令排放放射性气体；剧毒辐射却失控扩散，使守军发生变异，并让这类曾经繁忙的工业区遭到遗弃，或被Techbot之类的失控构造体占据。",al={"装载室的历史","装载室发生了什么","装载室为何沦陷"}},["6c9ce16b"]={q="装载室为什么会沦为废墟？",a="灾难性的放射性排放没能消灭穴居人入侵者，装载室便和下层城市的其他区域一同被遗弃。辐射非但没有拯救城市，反而毒害了居民，使幸存的侏儒变成麻风侏儒，还让自动防御系统和机械看护者在无人监管的情况下狂暴失控。",al={"装载室为何沦为废墟","装载室遭到遗弃","它为何被毁"}}},fp="12,252,28.525.0,34.220.0,46.194.0,36.199.0"}
P.entries["subzone:long-wash"] = {n="长桥码头",s="长桥码头是黑海岸一片凄凉且风大的海滩，从奥伯丁南侧一直延伸至亚米萨兰废墟。这片海岸阴郁沉闷，遍布海洋生物的残骸和漂浮物，最近由于敌对鱼人的势力增长，此处变得愈发危险。",h="长桥码头是黑海岸一片凄凉且风大的海滩，从奥伯丁南侧一直延伸至亚米萨兰废墟。这片海岸阴郁沉闷，遍布海洋生物的残骸和漂浮物，最近由于敌对鱼人的势力增长，此处变得愈发危险。",kw={"亚米萨兰","奥伯丁","黑海岸","长桥码头","鱼人","潮汐爬行者","迷雾之海"},ang={["race:NightElf"]="对于奥伯丁的卡多雷来说，长桥码头附近不断逼近的鱼人是另一种令人不安的不平衡迹象，它们正蔓延到这个主要港口的家门口。"},sec={{t="阴郁的海岸线",b="尽管名字里带有“长”字，长桥码头其实是黑海岸最短的一段独立海岸线。它终年笼罩在黑海岸阴沉的天空下，潮湿的沙滩上散落着漂浮物、搁浅的浮木，以及被迷雾之海冲上岸的海洋生物残骸。虽然当地的螃蟹在浪花中觅食，但从奥伯丁南下的旅者必须小心谨慎：鱼人部落已经在水边建立了营地，会猛烈攻击任何侵入它们领地的人。"}},faq={{q="长桥码头位于哪里？",a="长桥码头沿着黑海岸的海岸线延伸，位于奥伯丁的正南方，一直延伸到古老的亚米萨兰废墟西侧附近。",al={"长桥码头位置","长桥码头在哪里","如何找到长桥码头"}},{q="为什么叫长桥码头？",a="“Wash”（冲刷区）是一个古老的词汇，指的是海岸边被海浪冲刷和覆盖的部分。讽刺的是，尽管它被命名为长桥码头（Long Wash），它实际上是黑海岸最短的一段独立海滩。",al={"为什么叫长桥码头","长桥码头含义","冲刷区是什么意思"}},{q="在长桥码头能遇到什么威胁？",a="长桥码头的主要威胁来自于聚集在海岸线上的大量好战鱼人部族，此外还有极具领地意识的潮汐爬行者和其他沿海野生动物。",al={"长桥码头的危险","长桥码头的怪物","长桥码头有什么生物"}},{q="为什么沙滩上有这么多死去的生物？",a="迷雾之海汹涌的浪涛，加上正在侵蚀黑海岸沿海水域的腐蚀力量，经常将碎片、船骸和垂死的海洋生物冲刷到潮湿的沙滩上。",al={"长桥码头的死动物","黑海岸沙滩搁浅生物","海岸漂浮物"}}},fp="9,278,18.515.0,31.166.0,31.216.0,46.198.0,50.199.0"}
P.entries["subzone:longshore"] = {n="长滩",s="长滩是绵延整个西部荒野西侧边缘的广阔沙滩海岸线。尽管它辽阔而风景优美，但由于聚集了大量好斗的鱼人，且海岸外散布着大量沉船残骸，这里向来以危险著称。",h="长滩是绵延整个西部荒野西侧边缘的广阔沙滩海岸线。尽管它辽阔而风景优美，但由于聚集了大量好斗的鱼人，且海岸外散布着大量沉船残骸，这里向来以危险著称。",kw={"水栖形态","达芙妮·斯迪威尔","长滩","鱼人","老瞎眼","沉船","西部荒野","西部荒野灯塔"},ang={["class:Druid"]="联盟德鲁伊必须勇闯长滩西北部的深水区，找到隐藏在沉船附近的保险箱，以拼凑出他们获取水栖形态所需的坠饰。",["class:Paladin"]="追随暴风城达索瑞恩·拉尔指引的圣骑士会被派往南部的长滩，前往达芙妮·斯迪威尔的宅地，通过保护这位无辜的农夫免受迪菲亚强盗的侵害来证明他们的英勇。"},sec={{t="危险的海岸线",b="长滩贯穿了西部荒野的整个西海岸，是东部王国最宽阔、连续的沙滩之一。然而，它却很难让旅行者感到安宁。海岸鱼人在浪潮中横行霸道，其中以老瞎眼这样的恶名昭彰的恐怖生物为首，而沉船的残骸——包括被毁的精灵驱逐舰——则散落在浅滩上。在南部区域附近，像达芙妮·斯迪威尔这样孤立的定居者在迪菲亚强盗的劫掠下苦苦挣扎，而在水域对岸，西部荒野灯塔清晰可见。"}},faq={{q="为什么长滩如此危险？",a="海岸线上到处都是好斗的鱼人部落，它们在沙滩上横行无忌，伏击任何靠近浪潮的人。除了鱼人之外，沙滩南端还深受劫掠沿海宅地的迪菲亚强盗的困扰。",al={"为什么有这么多鱼人","长滩的危险","长滩安全吗"}},{q="达芙妮·斯迪威尔是谁？",a="达芙妮·斯迪威尔是一位独自一人在长滩西南部经营着孤立农场的定居者。她脆弱的处境使她成为了迪菲亚潜行者频繁劫掠的目标，这也促使白银之手骑士团派遣圣骑士新兵去保护她。",al={"达芙妮·斯迪威尔","斯迪威尔农场","海滩上的女人"}},{q="海岸外的那些沉船是什么？",a="长滩外水域沉没着许多船只残骸，从商船到过去海战中遗失的精灵驱逐舰应有尽有。这些水下遗迹吸引了拾荒者、鱼人和寻求海浪之下失落遗物的冒险者。",al={"西部荒野的精灵驱逐舰","长滩沉船","沉船"}},{q="为什么德鲁伊会来到长滩？",a="联盟的德鲁伊会进行一项被称为海狮试炼的仪式，以掌握他们的水栖形态。这项试炼的一部分要求前往长滩西北部的一处近海沉船附近，寻找一个沉没的箱子，以取回水兽耐力坠饰的另一半。",al={"长滩德鲁伊任务","西部荒野的奇怪保险箱","水兽耐力坠饰"}}},fx={f7eb1386={q="长滩是什么地方？",a="长滩是绵延广阔的海岸线，构成西部荒野的西部和南部边缘。这里沙滩绵长，遍布岩石浅滩，是艾泽拉斯面积最大的连续海滩之一。尽管风景优美，这里大多仍是荒野，危机四伏；一侧是无尽之海，另一侧则是西部荒野未开垦的平原。",al={"长滩是什么地方","西部荒野长滩","长滩海滩"}},ae612e51={q="为什么叫长滩？",a="它的名字直截了当地道出了海滩绵延广阔的特点。海滩沿着西部荒野整个西部和西南部边界延伸，形成一片巨大的海岸线，是艾泽拉斯最长的连续海岸地带之一。",al={"为何叫长滩","长滩名称由来","长滩含义"}}},fp="9,255,23.513.0,34.260.0,23.284.0,44.239.0,34.262.0"}
P.entries["subzone:lordamere-internment-camp"] = {n="洛丹米尔收容所",s="洛丹米尔收容所是第二次战争时期的一处拘留设施，坐落在俯瞰达拉然的高地上。该营地最初用于关押昏睡的兽人，现在则被达拉然的幸存法师和卫兵，以及一群背叛的被遗忘者所占据。",h="洛丹米尔收容所是第二次战争时期的一处拘留设施，坐落在俯瞰达拉然的高地上。该营地最初用于关押昏睡的兽人，现在则被达拉然的幸存法师和卫兵，以及一群背叛的被遗忘者所占据。",kw={"奥特兰克","贝拉莫尔","血石","达拉然","收容","基根·达克玛","洛丹米尔","兽人"},ang={["race:Orc"]="对于兽人来说，造访这座营地会让他们痛苦地想起第二次战争后的那段岁月，那时数以千计的族人在囚禁中日渐衰弱，直到萨尔集结了他们的人民。",["race:Undead"]="躲藏在洛丹米尔的叛逃者是对黑暗女王的直接背叛。追捕基根·达克玛并收回血石，对于防止被遗忘者的秘密落入人类之手至关重要。"},sec={{t="从监狱到研究前哨",b="第二次战争结束后，联盟在北方王国各地建立了收容所，以关押战败的兽人部落。洛丹米尔是一个独特的收容所，它是唯一设在奥特兰克山脉内的营地，归达拉然管辖。随着兽人早已被解放或逃离，如今该营地在典狱官贝拉莫尔的领导下，作为达拉然残部研究危险魔法遗物的前哨站运作。"},{t="被遗忘者叛逃者",b="该营地已卷入了洛丹伦亡灵的政治漩涡之中。四名被遗忘者变节者——基根·达克玛和他的同伙——从幽暗城窃取了强大的血石神器并逃到这里，将其交给典狱官贝拉莫尔，以换取在达拉然防线后的庇护。法师们欣然接受了这些用于奥术研究的神器，而塔伦米尔的执行官们则派遣忠诚的部落特工去追捕这些叛逃者，并在达拉然解锁其力量之前收回被窃的血石。"}},faq={{q="这个营地最初是用来做什么的？",a="它由联盟在第二次战争后建立，旨在关押那些因失去恶魔之血的嗜血欲望而陷入昏睡的被俘兽人。由于该营地靠近法师之城，达拉然负责驻守瞭望塔并对营地实施监管。",al={"收容所历史","这里为什么会有营地","这里是什么地方"}},{q="现在是谁在控制这个营地？",a="典狱官贝拉莫尔以及一支达拉然卫兵和法师小队控制着该营地。尽管达拉然本身已遭受重创，但这些幸存者仍在设防的山顶上继续他们的研究。",al={"谁住在这里","谁在管理营地","典狱官贝拉莫尔是谁"}},{q="为什么营地里会有被遗忘者亡灵？",a="他们是由基根·达克玛领导的幽暗城逃兵。在背叛了希尔瓦娜斯女王并窃取了神圣的血石神器后，他们将这些遗物交给典狱官贝拉莫尔，以换取达拉然的保护，从而躲避被遗忘者的报复。",al={"这里的亡灵","基根·达克玛","被遗忘者叛逃者"}}},fp="25,263,31.413.0,18.501.1,40.265.0,32.186.0,46.240.0"}
P.entries["subzone:lordamere-lake"] = {n="洛丹米尔湖",s="洛丹米尔湖是东部王国最大的淡水水域之一，其边缘由提瑞斯法林地、银松森林和奥特兰克山脉环绕。这里曾是北部人类文明繁华的水上中心，如今，其冰冷的水域和岛屿上却盘踞着天灾军团的死灵法师、野蛮的鱼人，以及蔓延的亡灵阴影。",h="洛丹米尔湖是东部王国最大的淡水水域之一，其边缘由提瑞斯法林地、银松森林和奥特兰克山脉环绕。这里曾是北部人类文明繁华的水上中心，如今，其冰冷的水域和岛屿上却盘踞着天灾军团的死灵法师、野蛮的鱼人，以及蔓延的亡灵阴影。",kw={"奥特兰克山脉","黎明岛","芬里斯岛","洛丹米尔湖","银松森林","图勒·鸦爪","提瑞斯法林地","邪鳍鱼人"},ang={["race:Human"]="洛丹米尔那宁静而多雾的水域，让人沉重地回想起北方人类王国曾经辉煌的往事，那时，人们曾自由地在湖岸间进行贸易。",["race:Undead"]="对于被遗忘者而言，洛丹米尔湖既是保护提瑞斯法的防御护城河，也是一处活跃的前线，必须清除芬里斯岛上残留的天灾军团。"},sec={{t="陨落王国的中心",b="在洛丹伦联盟的黄金时代，洛丹米尔湖处于人类权力的交汇处。洛丹伦王城守卫着它的北岸，魔法城邦达拉然在它的南端升起，而奥特兰克王国则坐落在它东部崎岖的山脊旁。商船和渔船曾毫无畏惧地穿梭于其广阔且雾气缭绕的水面上。第三次战争的浩劫过后，这座湖泊从商业枢纽变成了一道天然屏障，将由被遗忘者控制的提瑞斯法和银松森林地区与奥特兰克险峻的高地分离开来。"},{t="争夺之地",b="如今，航行在洛丹米尔的漆黑水域上危机四伏。湖中心坐落着芬里斯岛，天灾军团的死灵法师图勒·鸦爪和他的腐皮豺狼人在此负隅顽抗，抵御被遗忘者的进攻。再往东是黎明岛，那里已被好战的邪鳍鱼人完全占据。从达拉然周围的废墟到幽暗城的岸边，这座湖泊不再是一条平静的航道，而是一片被残余怪物和亡灵大军争夺的没顶前线。"}},faq={{q="历史上哪些王国曾与洛丹米尔湖接壤？",a="在洛丹伦联盟鼎盛时期，洛丹米尔湖与三个主要的人类王国接壤：北面和西面的洛丹伦王国、南面的达拉然，以及东面山脊旁的奥特兰克。",al={"洛丹米尔湖的居民","洛丹米尔湖历史","洛丹米尔周边的王国"}},{q="谁控制着湖中心的芬里斯岛？",a="芬里斯岛目前由天灾军团死灵法师图勒·鸦爪指挥的腐皮豺狼人控制，但他们正面临着来自被遗忘者的持续猛攻。",al={"芬里斯岛上的势力","洛丹米尔湖芬里斯岛","芬里斯岛统治者"}},{q="黎明岛是什么？",a="黎明岛是位于洛丹米尔湖东部、芬里斯岛以东的一群小岛。它们已被充满敌意的邪鳍鱼人占领并占据。",al={"黎明岛位置","洛丹米尔湖中的岛屿","黎明岛的怪物"}},{q="这座湖泊是如何得名的？",a="这座湖泊的名字呼应了周围的洛丹伦王国，因为其王城就在附近；关于它命名的详情，记录中并没有提及更多信息。",al={"洛丹米尔命名由来","为什么叫洛丹米尔"}}},fx={dc0bda98={q="洛丹米尔湖是什么地方？",a="洛丹米尔湖是东部王国最大的淡水湖泊之一，只有东边的达隆米尔湖能与之比肩。湖泊横跨提瑞斯法林地、银松森林和奥特兰克山脉的交界处，其水域曾连接洛丹伦、达拉然和奥特兰克这几个人类大国。如今，它成为被遗忘者领地与有争议的山地高原之间的一道天然分界线。",al={"洛丹米尔湖是什么地方","关于洛丹米尔湖","洛丹米尔湖概况"}},a5470736={q="洛丹米尔湖危险吗？",a="是的，湖水与湖岸都潜藏着严重危险。邪鳍鱼人已经占据了湖泊东部水域的黎明岛，会攻击任何靠近的人。再往远处，芬里斯岛已落入天灾军团和黑暗魔法之手，使得毫无防备的旅人若想横渡湖面、往来银松森林与奥特兰克山麓之间，就会面临危险。",al={"洛丹米尔湖安全吗","洛丹米尔湖的危险","洛丹米尔湖的威胁"}}},fp="14,349,28.598.0,19.489.1,51.222.0,51.166.1,27.184.0,30.154.0"}
P.entries["subzone:lost-fleet"] = {n="失落的舰队",s="失落的舰队由库尔提拉斯第三舰队的残骸组成，它们沉没在湿地北部海岸的巴拉丁海湾旁。在第二次战争期间，被Dragonmaw奴役的红龙摧毁了这支舰队，现在这些沉船残骸受到了不安的、被诅咒的不死水手的骚扰，他们被一种神秘的诅咒束缚在残骸上。",h="失落的舰队由库尔提拉斯第三舰队的残骸组成，它们沉没在湿地北部海岸的巴拉丁海湾旁。在第二次战争期间，被Dragonmaw奴役的红龙摧毁了这支舰队，现在这些沉船残骸受到了不安的、被诅咒的不死水手的骚扰，他们被一种神秘的诅咒束...",kw={"巴拉丁海湾","蓝腮沼泽","被诅咒的舰队","帕雷斯之眼","菲兹莫斯","halyndor","intrepid","失落的舰队","snellig","第三舰队","wave mistress","湿地"},ang={["faction:Alliance"]="这些残骸沉重地提醒着人们，库尔提拉斯和联盟在第二次战争中付出了惨痛的代价，我们应当尊重阵亡者，并终结他们被诅咒的折磨。",["profession:Blacksmithing"]="联盟的铁匠经常听说关于沉没舰队的传说，因为同一分队的另一艘船只Flying Osprey在沉没时携带着稀有的Lightforge iron。"},sec={{t="第二次战争中的悲惨结局",b="在第二次战争期间的最后一次航行中，库尔提拉斯第三舰队遭到了被Dragonmaw部族奴役的红龙从空中的伏击。龙焰瞬间吞没了整个舰队，像Wave Mistress和Intrepid这样引以为傲的船只撞向了蓝腮沼泽北部的浅滩和礁石。几乎所有船员都淹死或烧死，只有大副菲兹莫斯成为了这场灾难中唯一的幸存者。"},{t="帕雷斯之咒",b="水葬并不是第三舰队水手们的终点。在Intrepid沉没的货舱深处，藏着一件被称为被诅咒的帕雷斯之眼的禁忌神器，它是该船贪婪的指挥官Captain Halyndor私藏的。这件黑暗圣物腐蚀了溺亡的船员，将他们的灵魂束缚在破碎的木材上，使他们变成了狂乱、被诅咒的不死生物。只有First Mate Snellig的鬼魂还保留着一丝理智，在沼泽海岸徘徊，而他曾经的船员们则会猛烈攻击任何靠近残骸的入侵者。"}},faq={{q="什么是失落的舰队？",a="失落的舰队是来自第三舰队的几艘库尔提拉斯战舰的残骸，它们静静地躺在巴拉丁海湾湿地的北部海岸外。它们在第二次战争中被摧毁，现在被它们的不死船员所缠绕。",al={"失落的舰队","这里是什么地方","湿地沉船","第三舰队"}},{q="这些船只是如何被摧毁的？",a="在第二次战争期间，这支舰队遭到了兽人Dragonmaw部族所控制的被奴役的红龙的伏击和焚烧。猛烈的龙焰将这些船只化为燃烧的残骸，沉没在海岸边。",al={"谁击沉了这些船","它们是如何沉没的","是什么摧毁了舰队"}},{q="为什么这里的水手是不死生物？",a="他们的灵魂因为一种诅咒而被束缚在残骸上。大副菲兹莫斯正在寻求帮助，调查他们为何无法安息。",al={"为什么它们是幽灵","不死水手","帕雷斯之咒"}},{q="有人在舰队的毁灭中幸存下来吗？",a="来自Wave Mistress的大副菲兹莫斯是这场灾难中唯一已知的幸存者。他设法到达了安全地带，目前居住在米奈希尔港。",al={"有幸存者吗","有人活下来吗","菲兹莫斯"}}},fx={["8b2f2e55"]={q="失落的舰队危险吗？",a="是的，接近这些废墟极其危险。浸在水中的残骸里爬满了敌对的不死水手和海军陆战队员，他们毫不留情地发动攻击，还能让任何活着的闯入者染上虚弱的疾病。",al={"失落的舰队安全吗","失落的舰队有哪些危险","失落的舰队的威胁"}},["0a869193"]={q="为什么叫失落的舰队？",a="这些船只最初名为库尔提拉斯第三舰队。在第二次战争期间，它们遭遇龙喉氏族奴役的巨龙并全军覆灭，此后便得名“失落的舰队”，也称“毁灭舰队”。它们沉没在远离故土的地方，被巴拉丁海湾的沼泽水域吞没；这场悲剧让它们成为沉入海底、也被现世遗忘的船只。",al={"为什么叫失落的舰队","失落的舰队名称由来","毁灭舰队是什么意思"}},c633bffd={q="失落的舰队发生了什么？",a="第二次战争期间，库尔提拉斯第三舰队在最后一次航行中遭到龙喉氏族奴役的红龙袭击。龙焰吞没了木制船只，数艘燃烧的舰船——包括Wave Mistress号和Intrepid号——沉没在巴拉丁海湾蓝腮沼泽北岸近海。Wave Mistress号的大副菲兹莫斯是唯一的幸存者。",al={"失落的舰队历史","第三舰队发生了什么","失落的舰队背景"}},e2b996c0={q="谁在失落的舰队徘徊？",a="破碎的船体上全是躁动的亡灵。受诅咒的水手和海军陆战队员在腐朽的甲板上游荡，听命于沉没的Intrepid号指挥官Captain Halyndor。岸边唯一还保持理智的灵体，是大副Snellig的幽灵；活人则避开整个海湾。",al={"谁住在失落的舰队","失落的舰队幽灵","失落的舰队亡灵"}}},fp="10,323,30.446.0,19.546.1,23.230.0,31.209.0,32.122.0,48.160.0"}
P.entries["subzone:lost-point"] = {n="废弃哨塔",s="废弃哨塔是一座位于尘泥沼泽西部的破旧木制瞭望塔，最初由塞拉摩的部队建造，作为前哨侦察站。此后它因年久失修而脱离了吉安娜·普罗德摩尔的守卫控制，现在成了流氓逃兵的藏身处。",h="废弃哨塔是一座位于尘泥沼泽西部的破旧木制瞭望塔，最初由塞拉摩的部队建造，作为前哨侦察站。此后它因年久失修而脱离了吉安娜·普罗德摩尔的守卫控制，现在成了流氓逃兵的藏身处。",kw={"巴鲁斯·加科因","尘泥沼泽","废弃哨塔","侦察塔","塞拉摩逃兵"},ang={["faction:Alliance"]="对于联盟忠诚者来说，废弃哨塔是塞拉摩队伍中纪律涣散的苦涩象征，也是隐藏着军事叛国阴暗秘密的叛徒窝点。"},sec={{t="一个被遗弃的哨所",b="废弃哨塔由塞拉摩的远征军建立，旨在监视从贫瘠之地出现的交通和威胁，但它早已失去了最初的军事作用。在沼泽无情的潮湿环境下，哨所已经腐朽，木材开始腐烂，防御设施也被正规军遗弃。现在的塔楼及其周边地区没有驻守哨兵，而是被一群脱离了塞拉摩服役的人类逃兵所占据，他们在远离城市指挥官纪律的偏远荒野中寻求庇护。"},{t="逃兵巢穴",b="盘踞在废弃哨塔的逃兵听命于巴鲁斯·加科因，这是一名心怀不满的前士兵，他将这些流氓聚集在一起。他们的存在不仅仅是军事违抗命令那么简单。加科因和他的同伙掌握着有关塞拉摩队伍中叛徒的重要证词，包括列兵亨德尔参与了一场波及联盟高层的重大阴谋。"}},faq={{q="什么是废弃哨塔？",a="废弃哨塔是塞拉摩的人类在尘泥沼泽西部建造的一座破旧瞭望塔。虽然它最初旨在作为前哨侦察塔，但已被军队遗弃，并被逃兵接管。",al={"废弃哨塔概览","这座塔是什么","关于废弃哨塔"}},{q="现在谁住在废弃哨塔？",a="塔楼和周围的营地目前由塞拉摩的逃兵居住。这些叛变的人类士兵放弃了对塞拉摩的誓言，并在巴鲁斯·加科因的领导下行动。",al={"废弃哨塔里有什么人","废弃哨塔的敌人","废弃哨塔的怪物"}},{q="巴鲁斯·加科因是谁？",a="巴鲁斯·加科因是躲藏在废弃哨塔的塞拉摩逃兵的首领。尽管他有犯罪前科，但他掌握着有关塞拉摩内部令人不安的问题的关键情报。",al={"巴鲁斯·加科因","逃兵领袖","谁领导废弃哨塔"}},{q="塞拉摩为什么要废弃这座塔？",a="尘泥沼泽环境恶劣，补给困难。随着驻军士气低落，纪律松懈，这个孤立的哨所陷入了破败，成为了士兵们想要逃避职责又不想逃入部落领地的理想避难所。",al={"为什么被废弃","为什么废弃哨塔破败不堪","为什么荒废"}}},fp="10,298,18.537.0,16.431.1,19.221.0,34.198.0,20.194.1,36.246.0"}
P.entries["subzone:lost-rigger-cove"] = {n="落帆海湾",s="落帆海湾坐落在塔纳利斯东部的悬崖边，是南海海盗在该地区的主要行动基地。这个隐蔽的港口三面环绕着高耸的沙漠山脉，拥有码头、防御营地，还有一个正在建造新海盗船只的活跃造船厂。",h="落帆海湾坐落在塔纳利斯东部的悬崖边，是南海海盗在该地区的主要行动基地。这个隐蔽的港口三面环绕着高耸的沙漠山脉，拥有码头、防御营地，还有一个正在建造新海盗船只的活跃造船厂。",kw={"自由之刃","加基森","落帆海湾","造船厂","南海海盗","塔纳利斯"},ang={["class:Rogue"]="这个庞大的海盗营地里挤满了可以偷窃的口袋、私人的保险箱，以及精通各种海上打斗下作手段的恶棍。",["race:Gnome"]="对于侏儒技师来说，海盗的干船坞是拼凑机械和赃物零件的粗糙但却明显的展示，也是对南部海域每一艘商船的持续威胁。"},sec={{t="海盗与高山壁垒",b="由于几乎四面都被陡峭的岩壁所环绕，天然的防御优势使落帆海湾成为了南海自由之刃在卡利姆多东南边缘的理想海上据点。在这里，海盗恶棍、码头工人和强盗们在加基森当局的眼皮底下打捞物资并组装新的船体。海湾使南海海盗能够向无尽之海投射力量，同时劫掠棘齿城、藏宝海湾和沿海定居点之间的贸易航线。"},{t="近在咫尺的竞争对手",b="海盗们并不是毫无阻碍地占据着这片海湾。加基森和附近热砂港的地精们对家门口的这些劫掠者感到愤恨，并雇佣佣兵来屠杀南海海盗，削弱他们的兵力，破坏他们的行动。"}},faq={{q="谁控制着落帆海湾？",a="该海湾由南海海盗控制，这是一个在卡利姆多和南海各处活动的臭名昭著的海上集团。他们利用这个天然良港来修理舰队并建造新的战舰。",al={"谁拥有落帆海湾","谁住在落帆海湾","落帆海湾阵营"}},{q="谁在这里与海盗作战？",a="加基森和热砂港的地精们对家门口的劫掠者深恶痛绝，他们雇佣过往的冒险者突袭海盗据点，并削弱南海海盗的实力。",al={"塔纳利斯的侏儒地精营地","为什么侏儒会在这里","为什么要与海盗作战"}},{q="落帆海湾位于哪里？",a="它位于塔纳利斯东海岸，加基森东南方。可以通过穿过沿海山脉屏障的一条蜿蜒峡谷小径进入。",al={"落帆海湾在哪里","如何前往落帆海湾","落帆海湾地图"}},{q="海盗们在海湾里建造什么？",a="南海海盗在海湾中心运营着一个活跃的干船坞和造船厂，木匠和强盗们正在那里忙于组装一艘大型远洋战舰的船体。",al={"落帆海湾造船厂","海盗船建造"}}},fp="16,310,26.461.0,22.235.0,30.201.0,33.178.0,34.154.0,42.180.0"}
P.entries["subzone:lower-wilds"] = {n="低地荒野",s="低地荒野构成了菲拉斯的东部门户，潮湿的森林在此与千针石林的干旱峡谷交汇。穿过这片树林的主干道将边界处的萨兰纳尔与更西边的定居点连接起来，沿途布满了古老的绿植和难以预料的林地生物。",h="低地荒野构成了菲拉斯的东部门户，潮湿的森林在此与千针石林的干旱峡谷交汇。穿过这片树林的主干道将边界处的萨兰纳尔与更西边的定居点连接起来，沿途布满了古老的绿植和难以预料的林地生物。",kw={"莫沙彻营地","菲拉斯东部","菲拉斯","低地荒野","萨兰纳尔","千针石林","树人"},ang={["faction:Alliance"]="对于离开千针石林的联盟旅行者来说，低地荒野是他们看到的第一个菲拉斯景观，并以萨兰纳尔的暗夜精灵边境前哨站作为锚点。",["faction:Horde"]="部落信使和前往莫沙彻营地的补给线在从边界峡谷下来后，必须穿过整个低地荒野。"},sec={{t="东部边境",b="低地荒野横跨菲拉斯的东部区域，是千针石林被阳光灼烤的峡谷与西部深邃原始丛林之间的自然过渡地带。进入该区域的旅行者必须沿着主干道穿过这段森林，经过守卫着山口的精灵前哨站萨兰纳尔。这里茂密的树冠栖息着古老的树人，还有那些使偏离道路变得十分危险的本土野生动物。"},{t="一条充满纷争的公路",b="由于它连接了南部荒野和东部领土，低地荒野上经常有旅行者、侦察兵和信使往来。虽然暗夜精灵把守着萨兰纳尔的关口，但部落在更内陆的地方设有莫沙彻营地。因此，穿过低地荒野的道路是任何在卡利姆多南部运送物资的人的关键生命线，不仅充满了自然的危险，也伴随着阵营间的紧张局势。"}},faq={{q="低地荒野位于何处？",a="低地荒野构成了菲拉斯最东部的广阔地带。它们直接与千针石林接壤，从萨兰纳尔的山区门户向西延伸至丛林内部。",al={"低地荒野位置","低地荒野在哪里","如何前往低地荒野"}},{q="低地荒野里生活着哪些生物？",a="这片林地栖息着古老的森林守护者，包括树人，以及游荡在野性森林地面上的本土掠食野兽。",al={"低地荒野怪物","低地荒野有什么","低地荒野敌人"}},{q="有哪些定居点靠近低地荒野？",a="在最东边的边界坐落着暗夜精灵前哨站萨兰纳尔，它是联盟进入菲拉斯的主要入口。沿路向西则是部落的定居点莫沙彻营地。",al={"低地荒野城镇","低地荒野附近的营地","低地荒野的部落与联盟城镇"}},{q="穿过低地荒野的道路安全吗？",a="这条路本身是穿过该区域最安全的路线，但旅行者仍需保持警惕。偏离道路会引来具有攻击性的森林动物和领地守护者的袭击，敌对阵营间的冲突偶尔也会波及到公路上。",al={"低地荒野安全吗","低地荒野道路安全"}}},fp="11,295,20.464.0,19.428.0,34.197.0,39.148.0,47.194.0,41.250.0"}
P.entries["subzone:lushwater-oasis"] = {n="甜水绿洲",s="甜水绿洲是贫瘠之地中三处维持着生命的水源之一，坐落在十字路口南侧。尽管这里看起来生机盎然，但绿洲内充满了危险，这里不仅盘踞着极具攻击性的考尔克半人马，还是哀嚎洞穴的入口所在地。这里的池水受到污染，对于那些寻找奇特变异鱼的钓鱼者来说可谓尽人皆知。",h="甜水绿洲是贫瘠之地中三处维持着生命的水源之一，坐落在十字路口南侧。尽管这里看起来生机盎然，但绿洲内充满了危险，这里不仅盘踞着极具攻击性的考尔克半人马，还是哀嚎洞穴的入口所在地。这里的池水受到污染，对于那些寻找奇特变异鱼的...",kw={"十字路口","变异鱼","考尔克","甜水绿洲","贫瘠之地","哀嚎洞穴"},ang={["class:Druid"]="甜水绿洲呈现出一种令人不安的、非自然的过度生长，这是受附近哀嚎洞穴中散发出的扭曲能量所驱动。",["profession:Cooking"]="这里的池塘是少数几个钓鱼者能够钓到变异鱼的水域之一，这是一种在卡利姆多各地都备受推崇的重要食材，用于烹制美味风蛇。"},sec={{t="一处不稳定的避难所",b="甜水绿洲坐落于十字路口以南一段路程处，为这片被烈日炙烤的贫瘠之地提供了一处看似安宁的休憩之所。虽然棕榈树冠和清澈的泉水吸引了来自大草原各处的口渴野兽，但考尔克半人马占据了湖岸，潜伏在那里，伺机屠杀猎物和毫无防备的旅人。这座绿洲也是哀嚎洞穴的门户，那庞大的地下网络将腐化能量渗入上方的水潭，滋生出非自然的野生生物和怪异的变异体。"}},faq={{q="哀嚎洞穴的入口在哪里？",a="哀嚎洞穴洞穴系统的入口开凿在俯瞰甜水绿洲东侧的天然岩壁上。",al={"哀嚎洞穴在哪里","哀嚎洞穴入口"}},{q="谁控制着甜水绿洲？",a="考尔克半人马在整个绿洲内保持着绝对的统治地位，他们利用茂密的植被伏击路过的野生动物，并袭击从十字路口出发的旅人。",al={"谁住在甜水绿洲","甜水绿洲敌人","绿洲半人马"}},{q="为什么这里的鱼很奇怪？",a="从哀嚎洞穴泄漏出的深层能量腐蚀了绿洲内的水道，导致当地的鱼类变异成了不寻常的变异鱼。",al={"变异鱼地点","为什么有变异鱼","绿洲变异鱼"}},{q="萨尔的部落曾经过这里吗？",a="在兽人与牛头人穿越贫瘠之地的“长途跋涉”期间，萨尔带领他的军队穿过了该地区的各个绿洲，以获取维持生命的水源，同时还要抵御半人马无休止的伏击。",al={"萨尔长途跋涉绿洲","贫瘠之地绿洲兽人"}}},fx={cb9dfd73={q="什么是甜水绿洲？",a="甜水绿洲是贫瘠之地干旱平原上的三大绿洲之一，位于十字路口以南。深层地下泉水滋养着这里，为周围干旱的稀树草原提供了重要的水源和植被。这里也因哀嚎洞穴的入口而闻名，令人畏惧；那是一座神秘的地下迷宫。",al={"什么是甜水绿洲","甜水绿洲的背景","关于甜水绿洲"}},fd829a06={q="甜水绿洲危险吗？",a="是的，旅人应当小心接近水域。凶悍的科卡尔半人马在棕榈树间游荡，猎杀聚集饮水的野兽，并会一见外来者便发动攻击。此外，遭到腐化的哀嚎洞穴近在咫尺，对周边区域产生了异乎寻常的影响，在岸边催生出凶猛的生物和变异野兽。",al={"甜水绿洲有哪些危险","甜水绿洲安全吗","甜水绿洲有哪些威胁"}}},fp="15,364,22.501.0,53.138.0,29.174.0,30.153.0,39.206.0"}
P.entries["subzone:maclure-vineyards"] = {n="马科伦农场",s="马科伦农场是一处位于艾尔文森林南部，由马科伦家族拥有的广阔农业庄园。虽然这里以向暴风城提供葡萄和葡萄酒而闻名，但该农场也因其与邻近的斯通菲尔德家族之间持续不断的激烈仇怨而臭名昭著。",h="马科伦农场是一处位于艾尔文森林南部，由马科伦家族拥有的广阔农业庄园。虽然这里以向暴风城提供葡萄和葡萄酒而闻名，但该农场也因其与邻近的斯通菲尔德家族之间持续不断的激烈仇怨而臭名昭著。",kw={"野猪","艾尔文","杰拉德","马科伦","梅贝尔","斯通菲尔德","葡萄园","葡萄酒"},ang={["faction:Alliance"]="该庄园是重要的粮仓和葡萄园，为附近的闪金镇和暴风城提供食物和烈酒。",["race:Human"]="对于暴风城的人类来说，农场之间的争斗是乡村顽固观念的典型案例，提醒着旅人们，即便是在核心领土，邻居们也常因围栏问题争吵不休，而更大的威胁却在暗处伺机而动。"},sec={{t="苦涩的收成",b="马科伦农场坐落在艾尔文森林南部郁郁葱葱的山丘中，本应是一个酿酒和耕作的宁静天堂。然而，日常的劳作却被与马路对面斯通菲尔德家族之间长期存在的恶劣竞争所笼罩。两个家庭之间关于偷窃和血海深仇的指控根深蒂固，即便在饥饿的野猪和入侵的狗头人等共同威胁着双方家园时，双方的怒火依然难以平息。"},{t="禁忌之恋",b="尽管两个族长之间有着激烈的敌意，年轻的爱情却跨越了界限。梅贝尔·马科伦和托米·乔·斯通菲尔德坠入了爱河，他们在避开父母猜忌目光的隐秘树林中秘密幽会。经过农场的旅人常常发现自己卷入其中，帮他们传递秘密信息、解决琐碎争端，并试图帮助这对年轻情侣逃离家族怨恨的阴影。"}},faq={{q="马科伦家族和斯通菲尔德家族为什么在争斗？",a="这场竞争是一场长期存在的乡村争端，建立在多年的猜忌、琐碎的指责和固执的自尊之上。两家人互不信任，互相指责对方导致了货物和牲畜的损失，尽管双方都没有对方犯下恶行的确凿证据。",al={"马科伦 斯通菲尔德 仇怨","他们为什么互相憎恨","家族争斗"}},{q="谁是梅贝尔·马科伦？",a="梅贝尔是马科伦家的女儿。她秘密地爱上了托米·乔·斯通菲尔德，不顾家人对邻居的深仇大恨，希望能找到一种让他们在一起的方法。",al={"梅贝尔","马科伦的女儿"}},{q="农场面临着什么威胁？",a="除了家庭纠纷外，农场还深受糟蹋庄稼和葡萄藤的饥饿野猪的困扰，以及从附近金矿出没并洗劫周边田地的狗头人的威胁。",al={"葡萄园的危险","马科伦的野猪"}},{q="马科伦家族在这里生产什么？",a="马科伦家族种植葡萄藤，为整个艾尔文森林和暴风城的酒馆老板及商人们供应葡萄酒和新鲜水果。",al={"这里种植什么","马科伦的庄稼"}}},fx={["7abbd722"]={q="什么是马科伦农场？",a="马科伦农场是位于艾尔文森林南部的一处农庄。马科伦家族耕种并经营这片土地，为暴风城王国种植葡萄、酿造美酒。农场除了葡萄架，还设有家族宅院和开阔的田地，不过如今正受横行的野猪侵扰，也与邻居关系紧张。",al={"什么是马科伦农场","艾尔文森林的马科伦农场","马科伦农场"}},d4181dc3={q="谁住在马科伦农场？",a="这座葡萄园由马科伦家族拥有并经营。几代马科伦家族成员住在宅院里，其中包括杰拉德·马科伦和年幼的梅贝尔·马科伦。他们一起照料葡萄藤，抵御侵扰作物的野生动物，并在与附近石野家族持续不和的情况下管理庄园。",al={"谁住在这里","马科伦家族成员","谁经营马科伦农场"}},["6b11f938"]={q="马科伦农场危险吗？",a="农场本身是联盟一处宁静的庄园，但葡萄藤间潜伏着危险。凶猛的野猪不断在田地里拱土，毁坏作物，还会攻击任何靠得太近的人。此外，附近矿井里的狗头人偶尔会游荡到农场边缘，因此农场工人和旅人都必须保持警惕。",al={"马科伦农场安全吗","马科伦农场的危险","马科伦农场的威胁"}},["5a643901"]={q="为什么叫马科伦农场？",a="这座庄园直接以马科伦家族命名，是他们开垦土地并种下大片葡萄藤的。数代以来，这个家族的名字一直与当地的收成，以及就在艾尔文森林酿造的甜美葡萄酒紧密相连。",al={"为什么叫马科伦农场","马科伦农场名称由来","马科伦农场的名称"}}},fp="17,281,16.441.0,19.440.1,46.246.0,23.216.0,35.187.0,34.148.0"}
P.entries["subzone:maestra-s-post"] = {n="迈斯特拉岗哨",s="迈斯特拉岗哨是位于灰谷西部的一个小型联盟定居点，坐落在阿斯特兰纳西北方向和奥迪拉兰废墟以南的道路沿线。这里由暗夜精灵哨兵守卫，同时也接纳了在卡利姆多这片古老森林中罕见的人类，作为防范入侵威胁的前哨站。",h="迈斯特拉岗哨是位于灰谷西部的一个小型联盟定居点，坐落在阿斯特兰纳西北方向和奥迪拉兰废墟以南的道路沿线。这里由暗夜精灵哨兵守卫，同时也接纳了在卡利姆多这片古老森林中罕见的人类，作为防范入侵威胁的前哨站。",kw={"灰谷","净化者德尔格伦","费罗·艾隆汉","迈斯特拉岗哨","奥迪拉兰","哨兵"},ang={["faction:Alliance"]="对于离开黑海岸安全区域的联盟旅行者来说，这座岗哨代表着你在灰谷这片争夺激烈的森林中遇到的第一个友好的欢迎点和堡垒。",["race:NightElf"]="这座岗哨展示了新联盟日益发展的伙伴关系，哨兵们与东部王国的年轻种族共享炉火和守卫职责。"},sec={{t="前哨站",b="迈斯特拉岗哨坐落在灰谷西部的树冠之下，由一座细长的暗夜精灵哨塔和一间开放式小屋组成。它是往来于黑海岸海岸线和阿斯特兰纳大型枢纽之间的旅行者的重要中转站。尽管建筑风格宁静，但这座岗哨始终处于警戒状态。当地的哨兵密切注视着周围的荒野，那里的腐化熊怪蠢蠢欲动，附近部落的行动也时刻威胁着联盟的补给线。"},{t="联盟的聚集地",b="与森林深处许多封闭的暗夜精灵聚居地不同，迈斯特拉岗哨因容纳了少量人类盟友而引人注目。费罗·艾隆汉和净化者德尔格伦等人物与哨兵们住在一起，他们贡献自己的武力，并侍奉圣光，为更广阔的联盟效力。他们的存在使这个偏远的营地成为了东部王国与卡利姆多古老守护者之间最早的交汇点之一。"}},faq={{q="迈斯特拉岗哨在哪里？",a="它位于灰谷西部，坐落在阿斯特兰纳西北方向的道路沿线，就在奥迪拉兰废墟的南边。",al={"迈斯特拉岗哨位置","迈斯特拉岗哨在哪里","寻找迈斯特拉岗哨"}},{q="迈斯特拉是谁？",a="岗哨里没有任何记录说明迈斯特拉是谁。这座岗哨以此命名，但驻扎在这里的哨兵中并没有这位同名者。",al={"迈斯特拉是谁","月之女祭司迈斯特拉"}},{q="为什么精灵岗哨里会有人类？",a="在第三次战争之后，随着暗夜精灵加入联盟，像费罗·艾隆汉和净化者德尔格伦这样的旅行者和战士冒险来到卡利姆多，提供援助并加强与暗夜精灵盟友的关系。",al={"为什么人类会出现在灰谷","费罗·艾隆汉为什么在这里","净化者德尔格伦为什么在这里"}},{q="迈斯特拉岗哨面临哪些威胁？",a="岗哨必须应对潜伏在周围林地中的腐化熊怪部族，以及从附近进入灰谷的部落侦察队和入侵部队。",al={"谁在攻击迈斯特拉岗哨","迈斯特拉岗哨的危险"}}},fx={["3452376e"]={q="什么是迈斯特拉岗哨？",a="迈斯特拉岗哨是联盟位于灰谷西部的一座小型哨站，处于奥迪拉兰废墟以南、阿斯特兰纳西北方。这里以一座精灵高塔和一处露天暗夜精灵小屋为中心建成，是往返黑海岸与灰谷中部的旅人的集结地和中途站。尽管规模不大、驻守者稀少，这里仍是森林中少数暗夜精灵与人类并肩巡林的地方之一。",al={"什么是迈斯特拉岗哨","迈斯特拉岗哨信息","关于迈斯特拉岗哨"}},a14cd342={q="迈斯特拉岗哨危险吗？",al={"迈斯特拉岗哨安全吗","迈斯特拉岗哨的危险","迈斯特拉岗哨的威胁"}}},fp="14,306,15.496.0,21.462.0,32.125.0,16.140.0,41.223.0,33.186.0"}
P.entries["subzone:mage-quarter"] = {n="Mage Quarter",s="法师区是暴风城的奥术核心，坐落于首都西南角，横跨运河。在鹅卵石街道和各种奥术专卖店上方，耸立着巫师圣殿，王国的施法者们在此磨练技艺。在这个充满学术气息的街区表面之下，还隐藏着幽暗的角落，包庇着那些钻研更黑暗魔法的施法者。",h="法师区是暴风城的奥术核心，坐落于首都西南角，横跨运河。在鹅卵石街道和各种奥术专卖店上方，耸立着巫师圣殿，王国的施法者们在此磨练技艺。在这个充满学术气息的街区表面之下，还隐藏着幽暗的角落，包庇着那些钻研更黑暗魔法的施法者。",kw={"奥术","蓝隐士","运河","mage quarter","slaughtered lamb","暴风城","巫师圣殿"},ang={["class:Mage"]="该街区是你在暴风城的核心家园，在巫师圣殿内提供高级训练师和法术材料。",["class:Warlock"]="在屠宰羔羊旅店的公众伪装下，隐藏着一个隐秘的集会，黑暗艺术的修行者们在此秘密聚会，训练并召唤爪牙。"},sec={{t="奥术圣殿",b="你可以从大教堂广场或贸易区跨越运河上的桥梁抵达法师区，这里完全满足联盟对于神秘学的所有需求。以巫师圣殿的高塔为中心，人类和盟友种族的施法者们聚集在这里，研究奥术编织，并训练学徒。周边的街道挤满了出售布匹、材料、炼金用品和附魔长袍的商人，构成了一个专门用于研究和王国防御的封闭街区。"},{t="表面之下的秘密",b="并非该区所施展的所有法术都得到了王国高等施法者的批准。虽然像蓝隐士旅店这样的场所为学者们提供了安静的避难所，但臭名昭著的屠宰羔羊旅店却在其地下墓穴中隐藏着一个隐秘的术士集会。在那里，远离城市卫兵的视线和圣光大教堂广场的注视，恶魔学者们钻研被禁止的邪能仪式并束缚异界生物，以此伪装在街区对神秘异常现象的普遍容忍之中。"}},faq={{q="什么是巫师圣殿？",a="巫师圣殿是法师区内最为显眼的塔楼。它是暴风城法师的主要学院、图书馆和训练场，也是学者、神秘学训练师和负责保卫首都的防御性施法者的驻地。",al={"法师塔","巫师圣殿","暴风城法师圣殿"}},{q="在法师区哪里可以训练术士？",a="术士们秘密地聚集在屠宰羔羊旅店下方，那是一家位于该区不引人注目的旅店。在其地穴和隐藏的地窖里，邪能魔法的修行者们可以研究黑暗仪式，召唤恶魔，并在不受城市卫兵监视的情况下进行训练。",al={"术士训练师位置","屠宰羔羊地下室","暴风城术士训练师"}},{q="法师区里有什么样的商店？",a="该区遍布着满足施法者和工匠需求的专卖店。游客们可以找到像邓肯的纺织品店和拉尔森服装店这样的裁缝店，以及炼金与草药商人、附魔供应商、烟火供应处和长袍商人。",al={"法师区商人","这里有什么商店","法师区店铺"}},{q="如何前往法师区？",a="法师区位于暴风城的西南角。你可以直接从贸易区或大教堂广场穿过横跨运河的桥梁进入。",al={"法师区在哪里","如何前往法师区","去往法师区的路线"}}},fx={cffe9f84={q="什么是Mage Quarter？",a="Mage Quarter是暴风城西南角的奥术中心，隔着运河与Cathedral Square和Trade District相望。这里以巍峨的巫师圣所尖塔为标志，是王国各地的学者、炼金师、裁缝和神秘技艺从业者的主要聚集地。",al={"什么是mage quarter","暴风城mage quarter","法师区"}},["4d297df6"]={q="谁住在Mage Quarter，或由谁管理？",a="这里主要居住着王国的法师、奥术研究者、学者，以及炼金师和制衣匠等相关行业的从业者。巫师圣所中的法师团体负责处理魔法事务，并致力于保障首都及周边土地的安全；不过，当地酒馆下方也有黑暗的施法者暗中聚集。",al={"谁住在mage quarter","谁管理mage quarter","mage quarter的居民"}},["1c00796e"]={q="Mage Quarter危险吗？",a="表面上，Mage Quarter是宁静的学术与商业中心，并由城卫严密看守。然而，在Slaughtered Lamb酒馆欢快的表象之下，藏着一个秘密的术士集会。他们在阴影中施展黑暗的恶魔召唤术，却不受上方城中当局的干涉。",al={"mage quarter安全吗","mage quarter的危险","mage quarter有哪些危险"}},ddf0f180={q="为什么叫Mage Quarter？",a="这里被定为暴风城施法者的聚集地，因此得名。城区围绕巫师圣所建立，城中的法师在此居住、学习并精进奥术技艺。",al={"为什么叫mage quarter","mage quarter名称由来"}}},fp="12,378,21.510.0,27.491.1,29.257.0,45.246.0,43.254.0,34.193.0"}
P.entries["subzone:magic-quarter"] = {n="Magic Quarter",s="魔法区是幽暗城的东北城区，是遗忘者进行奥术研究和钻研黑暗法术的中心。该区域由一座阴森恐怖的诅咒神庙所主宰，汇集了各种奥术和邪能的修行者。",h="魔法区是幽暗城的东北城区，是遗忘者进行奥术研究和钻研黑暗法术的中心。该区域由一座阴森恐怖的诅咒神庙所主宰，汇集了各种奥术和邪能的修行者。",kw={"遗忘者","法师","magic quarter","传送门训练师","裁缝","诅咒神庙","幽暗城","术士"},ang={["class:Mage"]="魔法区是遗忘者法术研究的核心，提供奥术艺术的训练，以及将幽暗城与更广阔的部落连接起来的传送网络。",["class:Warlock"]="在诅咒神庙黑暗的壁龛中，术士们召唤恶魔仆从并磨练暗影魔法，远离联盟评判的目光。"},sec={{t="黑暗艺术的汇聚地",b="魔法区位于这座地下城市的东北象限，是遗忘者们保存奥术遗产并深入研究黑暗法术的地方。该区的核心是一座高耸的诅咒神庙，这是一种天灾军团风格的建筑遗迹，现已被获得自由意志的亡灵重新利用。在它穹顶之下阴影笼罩的大厅里，法师们在这里操纵微妙的魔法能量，术士们则在此与恶魔实体沟通，使这里成为了洛丹伦知识力量和神秘研究的枢纽。"},{t="学者、织法者与召唤师",b="除了对原始塑能和召唤的研究外，魔法区还是施法者们不可或缺的民用中心。传送门训练师在这里维护着连接部落领地的运输网络，而裁缝大师则利用附魔织物制作长袍和寿衣。与达拉然对学院派法术和禁忌魔法的严格隔离不同，遗忘者在这里公开地融合了奥术的好奇心与邪能的力量，以巩固他们对抗众多敌人的地位。"}},faq={{q="魔法区的目的是什么？",a="魔法区是遗忘者进行奥术和恶魔研究的中心。这里有法师和术士的职业训练师、连接其他城市的传送门大师，以及编织附魔布料的裁缝专业人士。",al={"什么是魔法区","魔法区的目的","幽暗城魔法区"}},{q="为什么幽暗城里会有诅咒神庙？",a="当幽暗城在洛丹伦王城废墟下被天灾军团挖掘出来时，他们建造了诅咒神庙这样的建筑。当希尔瓦娜斯和她拥有自由意志的遗忘者夺取了这座地下建筑群后，他们接管了这些现有的设施，并将其重新用于他们自己的施法者。",al={"幽暗城诅咒神庙","为什么有诅咒神庙","幽暗城的天灾建筑"}},{q="谁可以在魔法区接受训练？",a="法师、术士和恶魔训练师负责指导该区的修行者，而传送门专家和裁缝技师则提供运输和制作方面的训练。",al={"魔法区的训练师","谁在这里训练","魔法区的职业"}},{q="魔法区位于哪里？",a="它位于幽暗城的东北象限，穿过中心环形区域与炼金区相对。",al={"魔法区在哪里","魔法区位置","寻找魔法区"}}},fx={f984761d={q="什么是Magic Quarter？",a="Magic Quarter是幽暗城东北部的区域，也是被遗忘者进行奥术与秘法研究的核心地带。一座阴森的诅咒神庙耸立在这片区域之上，它由天灾军团的建筑改造而成，供效忠女妖之王的黑暗施法者、学者和织工使用。",al={"什么是magic quarter","幽暗城magic quarter","幽暗城的magic quarter"}},cec11eb0={q="为什么叫Magic Quarter？",a="这个区域的名字直接源于它在幽暗城中的主要职能：这里是被遗忘者施展魔法的领地。奥术施法者、恶魔能量的召唤者和魔法织物的织工聚集于此，精进黑暗技艺，并为希尔瓦娜斯女王进行奥术实验。",al={"为什么叫magic quarter","magic quarter名称由来","magic quarter名称含义"}},["8725bde7"]={q="Magic Quarter危险吗？",a="对于被遗忘者的忠诚臣民及其部落盟友而言，Magic Quarter很安全。然而，这里充斥着不稳定的奥术能量、被召唤的邪能生物和阴森的仪式。鲁莽的外来者或黑暗女士的敌人若擅闯诅咒神庙下方，很快就会被这里的术士和法师制服。",al={"magic quarter危险吗","magic quarter的危险","幽暗城magic quarter安全吗"}}},fp="13,245,23.561.0,32.481.0,41.233.0,53.301.0,40.165.0,35.117.0"}
P.entries["subzone:magram-village"] = {n="玛格拉姆村",s="玛格拉姆村是玛格拉姆半人马氏族的定居点，坐落在凄凉之地东南部污浊的黄色池塘之间。这是玛格拉姆氏族对他们痛恨的宿敌吉尔吉斯氏族发动无休止战争的主要基地。",h="玛格拉姆村是玛格拉姆半人马氏族的定居点，坐落在凄凉之地东南部污浊的黄色池塘之间。这是玛格拉姆氏族对他们痛恨的宿敌吉尔吉斯氏族发动无休止战争的主要基地。",kw={"半人马","凄凉之地","吉尔吉斯","玛格拉姆","玛格拉姆村","池塘"},ang={["race:Tauren"]="半人马的野蛮行径几代以来一直困扰着卡利姆多的部落，使得这些游牧掠夺者的任何定居点都令人不安地提醒着人们过去的流血冲突。"},sec={{t="泥潭中的据点",b="玛格拉姆村绵延分布在凄凉之地东南部的停滞硫磺池塘周边的岛屿和岸边，是一个由粗糙木桥和兽皮帐篷拼凑而成的简陋定居点。玛格拉姆半人马在这里时刻保持警惕，防备邻近的氏族。玛格拉姆人以残暴和对南部的吉尔吉斯氏族根深蒂固的敌意而闻名，他们愿意容忍外来者，前提是这些旅行者能通过屠杀吉尔吉斯敌人来证明自己的价值。"}},faq={{q="谁住在玛格拉姆村？",a="该村庄是玛格拉姆氏族的家园，这是凄凉之地土生土长的多个交战半人马部落之一。他们住在由简陋的人行桥连接的岛屿上的粗糙兽皮天棚下。",al={"谁在这里","玛格拉姆居民","半人马村庄"}},{q="我能在不被攻击的情况下进入玛格拉姆村吗？",a="起初，玛格拉姆半人马对所有外来者都怀有敌意。然而，旅行者可以通过追杀他们的誓敌——吉尔吉斯半人马——来赢得他们的信任，从而提升在该氏族的声望。",al={"玛格拉姆友好吗","玛格拉姆敌对","如何访问玛格拉姆村"}},{q="为什么村庄周围的池塘是黄色的？",a="村庄内外及周边的池塘被凄凉之地荒芜土地典型的硫磺和矿物径流所污染，导致它们停滞、变色且遭受污染。",al={"黄色的水","受污染的池塘","玛格拉姆的水"}},{q="为什么玛格拉姆要与吉尔吉斯开战？",a="凄凉之地的半人马氏族之间有着传说中的血腥宿怨。特别是玛格拉姆氏族和吉尔吉斯氏族，为了争夺荒原南部的统治权，已经进行了几代人的苦战。",al={"玛格拉姆对阵吉尔吉斯","半人马血仇","半人马战争"}}},fp="14,232,24.482.0,28.176.0,50.201.0,44.169.0,39.210.0"}
P.entries["subzone:main-hall-northshire"] = {n="Main Hall (Northshire)",s="主厅是艾尔文森林中北郡修道院的中央入口大厅。它是连接修道院庭院与上方塔楼、Hall of Arms以及图书馆侧翼的主要枢纽。在这里，新招募的人类冒险者们会进行报到，并领取他们效忠暴风城王国的首个任务。",h="主厅是艾尔文森林中北郡修道院的中央入口大厅。它是连接修道院庭院与上方塔楼、Hall of Arms以及图书馆侧翼的主要枢纽。在这里，新招募的人类冒险者们会进行报到，并领取他们效忠暴风城王国的首个任务。",kw={"修道院","艾尔文","hall of arms","图书馆侧翼","主厅","北郡","暴风城"},ang={["race:Human"]="对于王国的人类而言，北郡修道院的主厅标志着他们开始踏上效忠暴风城和圣光的旅程。"},sec={{t="修道院之心",b="穿过北郡修道院宏伟的拱门，访客便直接进入了主厅。作为这座建筑的中心枢纽，它将抵达的受训者和牧师人员引导至修道院的各个区域：一侧是用于军事训练的Hall of Arms，另一侧是充满学术气息的图书馆侧翼，还有通往修道院塔楼的阶梯。大厅原本宁静的庇护所氛围，因山谷中持续不断的冲突而显得有些紧迫，军官们在此召集身强力壮的新手，以保卫王国的边境。"}},faq={{q="主厅的用途是什么？",a="主厅是北郡修道院的中央接待大厅和交通枢纽。它将新兵、牧师和访客引导至Hall of Arms、图书馆侧翼以及修道院的上方塔楼。",al={"什么是主厅","北郡主厅的作用"}},{q="谁在这里引导新兵？",a="驻守在主厅的暴风城防卫军官和牧师会对到来的冒险者进行评估，并为他们提供清除威胁修道院领地之敌的最初指令。",al={"谁在这里发放任务","修道院指挥官"}}},fx={["23c998e2"]={q="北郡修道院的主大厅是什么？",a="主大厅是北郡修道院的中央入口大厅，坐落在艾尔文森林中受到庇护的北郡山谷。它是连接修道院高塔、图书馆侧翼和Hall of Arms的主要通道，也是初来乍到、肩负保卫王国职责的守卫们活动的中心。",al={"什么是主大厅","北郡主大厅","这座大厅是什么"}},c47795b4={q="主大厅危险吗？",a="大厅有守卫把守，能让人避开山谷中的危险，在此获得庇护。修道院外的凶猛野生动物和迪菲亚暴徒威胁着周围区域。",al={"主大厅安全吗","主大厅的危险","主大厅里有敌人吗"}}},fp="22,334,18.494.0,37.202.0,30.208.0"}
P.entries["subzone:maker-s-terrace"] = {n="造物者遗迹",s="造物者遗迹是一处绵延的户外挖掘场，位于荒芜之地北部，正对着古老的泰坦金库——奥达曼的入口。从洛克莫丹向南探险的旅行者必须穿越其崎岖的外围，这里目前被黑铁矮人强硬地占据着。这个挖掘场是地表荒原与埋藏在下方的泰坦秘密之间的一道充满纷争的门槛。",h="造物者遗迹是一处绵延的户外挖掘场，位于荒芜之地北部，正对着古老的泰坦金库——奥达曼的入口。从洛克莫丹向南探险的旅行者必须穿越其崎岖的外围，这里目前被黑铁矮人强硬地占据着。这个挖掘场是地表荒原与埋藏在下方的泰坦秘密之间的一...",kw={"荒芜之地","黑铁矮人","挖掘","造物者遗迹","泰坦","奥达曼"},ang={["profession:Mining"]="凿刻在砂岩悬崖上的广阔采石场和土方工程显示出矮人挖掘者进行大规模矿石开采的明显迹象。",["race:Dwarf"]="对于铁炉堡的矮人来说，看到造物者遗迹掌握在阴险的黑铁氏族手中是一件令人痛苦的事，因为奥达曼深藏着矮人起源的终极秘密。"},sec={{t="金库的门槛",b="Sprawling across the northern bluffs of the Badlands, the Maker's Terrace serves as the exterior staging ground for the subterranean halls of Uldaman. Long before travelers delve into the subterranean ruins, they must contend with the sun-scorched earthworks, scaffolding, and stone trenches of this grand excavation. It sits right along the pass coming down from Loch Modan, making it the first landmark greeting any traveler daring to venture into the arid wastes. The Terrace buzzes with violent industry as rival factions seek a way into the ancient secrets buried beneath the rock."},{t="黑铁矮人的占领",b="该遗址牢牢地处于黑铁氏族的掌控之下，他们带着充满敌意的警惕巡视着遗迹的沟渠和外围。被泰坦遗物和地下统治权的诱惑所吸引，这些穴居矮人不断向山坡深处挖掘，搜寻远古造物者留下的任何武器、记录或大地遗物。任何试图在不清理这些防御哨兵的情况下进入奥达曼深处大厅的人，很快就会发现自己难以应对。"}},faq={{q="造物者遗迹在哪里？",a="造物者遗迹位于荒芜之地的极北端，就在连接该区域与洛克莫丹的峡谷山口附近。它环绕着通往奥达曼远古建筑群的外部入口。",al={"造物者遗迹位置","造物者遗迹在哪里","如何找到造物者遗迹"}},{q="谁控制着造物者遗迹？",a="该遗址被怀有敌意的黑铁矮人占领并巡逻，他们在此进行积极的挖掘作业，并严密防守奥达曼的外部入口，抵御外来者。",al={"谁在造物者遗迹","造物者遗迹的敌人","谁控制了造物者遗迹"}},{q="挖掘的目的是什么？",a="黑铁矮人正在挖掘古老的泰坦建筑群奥达曼。他们试图在敌对势力抢先夺取之前，找出埋藏在地底金库中的遗物、强大的机械和古老的泰坦秘密。",al={"为什么他们在这里挖掘","造物者遗迹挖掘场","黑铁矮人在寻找什么"}},{q="造物者遗迹是奥达曼的一部分吗？",a="是的，造物者遗迹是通往奥达曼地下城和洞穴的外部露天挖掘坑。",al={"这是奥达曼吗","造物者遗迹与奥达曼的区别","遗迹与地下城的连接"}}},fp="15,402,22.586.0,20.471.0,37.203.0,33.169.0,38.225.0,35.127.0"}
P.entries["subzone:malaka-jin"] = {n="玛拉卡金",s="玛拉卡金是一个坐落在石爪山脉低矮丘陵地带的小型部落营地，位于恐怖图腾岗哨的正南方。这里主要居住着暗矛巨魔猎人，作为从贫瘠之地进入崎岖山峰的旅人们的一处乡村驿站和狩猎前哨。",h="玛拉卡金是一个坐落在石爪山脉低矮丘陵地带的小型部落营地，位于恐怖图腾岗哨的正南方。这里主要居住着暗矛巨魔猎人，作为从贫瘠之地进入崎岖山峰的旅人们的一处乡村驿站和狩猎前哨。",kw={"暗矛","恐怖图腾","部落","猎人","玛拉卡金","前哨站","石爪山脉","巨魔"},ang={["faction:Horde"]="玛拉卡金是部落在石爪山脉的最南端门户，是在贫瘠之地和北部山地要塞之间的道路上的一处重要驿站。",["race:Troll"]="对于暗矛巨魔来说，玛拉卡金是巨魔自力更生和追踪技巧的骄傲证明，他们在远离卡利姆多热带海岸的崎岖高地上开辟了一个家园。"},sec={{t="猎人的避难所",b="玛拉卡金隐藏在通往石爪山脉的主路附近，为冒险进入这一争夺中高地的部落漫游者提供了一个受欢迎的避难所。这个村庄是一群粗犷的巨魔猎人的家园，他们依靠岩脊和灌木丛艰难度日。虽然生活简朴，但这些猎人提供补给，与疲惫的冒险者交换新鲜猎物，并时刻警惕着敌对的山地野生动物，以及潜伏在更远山路上的好战的恐怖图腾牛头人。"},{t="高地上的立足点",b="玛拉卡金险要地坐落在贫瘠之地的边界附近，标志着部落在石爪山脉建立的最早的据点之一。虽然与北面更大的要塞烈日石居相比，这里既小又安静，但它起到了至关重要的后勤枢纽作用，使部落追踪者能够监控部落动乱，并保护蜿蜒的道路免受迫近威胁的侵扰。"}},faq={{q="什么是玛拉卡金？",a="玛拉卡金是位于石爪山脉南部的一个小型部落村庄和前哨站。这里住着一群暗矛巨魔猎人，他们为从贫瘠之地爬上来的旅行者提供庇护、贸易和补给。",al={"玛拉卡金在哪里","这是什么地方","玛拉卡金 石爪山脉"}},{q="谁住在玛拉卡金？",a="这个定居点几乎完全由巨魔猎人居住。他们靠狩猎山里的野味，并与过往的冒险者交易肉类和皮革来维持生计。",al={"玛拉卡金的npc","这里有什么人","石爪山脉的巨魔"}},{q="营地面临什么威胁？",a="除了凶猛的山地掠食者外，村庄直接位于敌对的恐怖图腾岗哨南面，这使得这个小型巨魔营地必须时刻警惕来自那个怀有敌意的牛头人部族的侵犯。",al={"玛拉卡金的敌人","谁在攻击玛拉卡金"}},{q="这里有飞行管理员吗？",a="没有。在这个时代，玛拉卡金没有飞行管理员。穿越石爪山脉的冒险者必须依靠西北方向更远处的烈日石居的飞行管理员，或者步行穿过道路。",al={"玛拉卡金的飞行点","飞往玛拉卡金"}}},fp="10,305,17.479.0,25.373.0,19.227.0,24.169.0,27.211.0,30.203.0"}
P.entries["subzone:malden-s-orchard"] = {n="玛尔丁果园",s="玛尔丁果园是银松森林北部的一处废弃农场，以在洛丹伦天灾军团入侵期间逃离的人类主人命名。这里早已荒废，黑暗的常青树在杂草丛生中矗立，凶残的黑狼在场地上徘徊。果园里摇摇欲坠的小屋曾作为一个与部队失散的被遗忘者斥候的临时避难所。",h="玛尔丁果园是银松森林北部的一处废弃农场，以在洛丹伦天灾军团入侵期间逃离的人类主人命名。这里早已荒废，黑暗的常青树在杂草丛生中矗立，凶残的黑狼在场地上徘徊。果园里摇摇欲坠的小屋曾作为一个与部队失散的被遗忘者斥候的临时避难所...",kw={"小屋","埃兰德·麦克里","伊瓦农场","玛尔丁","玛尔丁果园","银松森林","狼"},ang={["faction:Horde"]="从瑟伯切尔或提瑞斯法林地边界向南移动的旅行者在经过果园时必须小心，因为农场里栖息着极具攻击性的狼群。",["race:Undead"]="对于被遗忘者来说，这座果园是人类毁灭的遗迹，也是银松森林北部的一块争议之地，亡灵哨兵必须从野兽手中将其夺回。"},sec={{t="枯萎的收获",b="在第三次战争之前，这个农场由一位名叫玛尔丁的农夫照料，曾为洛丹伦的城镇供应新鲜水果。当天灾军团席卷王国时，玛尔丁为了逃避瘟疫抛弃了自己的土地。在此后的岁月里，果园在银松森林黑暗弥漫的雾气下窒息。常青树无人修剪，果实在枯萎的枝头腐烂，这片土地已完全被野生掠食者所占据。"},{t="困于小屋",b="杂草丛生的果园已成为领地性黑狼的猎场，使其成为穿过银松森林北部的一条危险路线。在为亡灵哨兵执行侦察任务期间，斥候埃兰德·麦克里被派往该地区进行调查，却发现自己被这些野兽包围。埃兰德在玛尔丁破旧的小屋中被困了数天，直到被遗忘者的增援部队冲破狼群并将他护送回伊瓦农场的斥候同伴身边，他才得以生还。"}},faq={{q="玛尔丁是谁？",a="玛尔丁是一位人类农夫，在洛丹伦陷落前住在这里。在第三次战争期间天灾军团入侵王国时，他抛弃了果园并为逃命而逃离。",al={"玛尔丁背景故事","谁拥有这个果园","玛尔丁是谁"}},{q="为什么果园里满是狼？",a="由于没有活人来保卫农场，在银松森林徘徊的野生黑狼将茂密的树林和废弃的庭院据为它们的狼群领地。",al={"为什么这里有狼","玛尔丁果园的狗","狼群出没"}},{q="谁被困在小屋里？",a="亡灵哨兵埃兰德·麦克里被困在小屋里。他受被遗忘者派遣执行侦察任务，却遭到了果园里狼群的伏击，只能躲在屋内直到救援到来。",al={"被困小屋的斥候","谁在屋子里","小屋里的亡灵哨兵"}},{q="现在还有人从这个果园采摘水果吗？",a="没有。这些黑暗的树木多年来无人照料，它们的果实在银松森林蔓延的腐朽中在枝头烂掉。",al={"水果能吃吗","玛尔丁果园的收获","能采摘水果吗"}}},fx={ad803607={q="玛尔丁果园发生了什么？",a="天灾席卷洛丹伦时，果园原来的主人被迫放弃小屋，逃命而去。农庄逐渐荒废，陷入死寂，直到凶猛的黑色座狼占据了树林，把这座曾经宁静的果园变成了野兽巢穴。",al={"玛尔丁果园的历史","玛尔丁果园的背景故事","玛尔丁果园这里发生了什么"}},["87e05548"]={q="玛尔丁果园为何被遗弃？",a="第三次战争期间，亡灵瘟疫和天灾入侵洛丹伦，农场主人被迫逃离，农场因此荒废。无人照料后，荒野重新吞没了这片土地，饥饿的掠食者也占据了这里。",al={"玛尔丁果园为何废弃","玛尔丁果园为何被遗弃","是谁毁了玛尔丁果园"}},a9b40d5a={q="玛尔丁果园危险吗？",a="危险。一大群饥饿的黑色座狼已经彻底占据果园。它们凶残至极，就连一名训练有素的被遗忘者死亡猎手也被困在唯一的小屋里好几天，不敢踏出屋外，否则必死无疑。",al={"玛尔丁果园的危险","玛尔丁果园安全吗","玛尔丁果园的威胁"}},a14ed0b8={q="玛尔丁果园为何得名？",a="果园以曾经的人类主人玛尔丁命名。他在天灾席卷王国之前曾在此照料树木，住在这座小农舍里。",al={"玛尔丁果园为何得名","玛尔丁果园名称由来","谁给玛尔丁果园命名"}},b372998e={q="什么是玛尔丁果园？",a="玛尔丁果园是一片杂草丛生的果园兼农庄，坐落在银松森林北部。它曾是一座由活着的人类经营的宁静农庄，如今深色的常青树无人照料，树上的果实无人采摘，任其在阴森的林间腐烂。",al={"什么是玛尔丁果园","银松森林的玛尔丁果园","关于玛尔丁果园"}}},fp="16,362,18.448.0,22.486.1,15.174.0,33.159.0,34.186.0,48.140.0"}
P.entries["subzone:mannoroc-coven"] = {n="玛诺洛克集会所",s="玛诺洛克集会所是位于凄凉之地南部的一处被恶魔占据的废墟，以深渊领主玛诺洛斯命名。它坐落在古老的暗夜精灵建筑群中，是燃烧军团在卡利姆多中部最大的据点。火刃氏族的邪教徒在这里维持着活跃的召唤传送门，用邪犬、魅魔和地狱火充斥着这片布满灰烬的土地。",h="玛诺洛克集会所是位于凄凉之地南部的一处被恶魔占据的废墟，以深渊领主玛诺洛斯命名。它坐落在古老的暗夜精灵建筑群中，是燃烧军团在卡利姆多中部最大的据点。火刃氏族的邪教徒在这里维持着活跃的召唤传送门，用邪犬、魅魔和地狱火充斥着...",kw={"阿兹雷索克","火刃氏族","集会所","凄凉之地","邪犬","地狱火","朱格卡尔·格里姆罗德","玛诺洛克"},ang={["class:Warlock"]="浓缩的邪能和活跃的军团召唤裂隙使该集会所成为了重要的战术目标，提供了对原始恶魔显现的第一手观察机会。",["race:NightElf"]="看着你远古先祖的石砌建筑被恶魔入侵者亵渎和践踏，玛诺洛克集会所成为了对上古之战令人痛苦的回忆。"},sec={{t="魔火堡垒",b="玛诺洛克集会所坐落于幽灵岗哨以南、葬影村以东，笼罩在压抑、受邪能污染的阴霾之中，覆盖了古老的暗夜精灵废墟。该集会所由领主阿兹雷索克与火刃氏族术士朱格卡尔·格里姆罗德在地面指挥。他们共同利用活跃的召唤传送门将恶魔增援部队直接拉入卡利姆多，其中包括末日守卫、地狱火和邪犬。尽管部落阵营的旅者试图利用伊鲁索斯之手这样的圣物切断这些连接，但新的裂隙仍在伤痕累累的大地上不断撕裂开来。"}},faq={{q="为什么这个地方被称为玛诺洛克集会所？",a="这座营地的命名是为了向毁灭者玛诺洛斯致敬，这位臭名昭著的深渊领主曾通过血之诅咒奴役了兽人，并最终死于灰谷。",al={"谁是玛诺洛斯","玛诺洛克名称起源","为什么叫玛诺洛克"}},{q="谁在统治这座集会所？",a="这里的恶魔军队由恶魔领主阿兹雷索克率领。凡人的事务则由火刃氏族邪教的代表，术士朱格卡尔·格里姆罗德负责。",al={"谁领导玛诺洛克集会所","玛诺洛克集会所首领","阿兹雷索克"}},{q="这座集会所建立在什么废墟之上？",a="这座恶魔营地占据了一个古老暗夜精灵定居点的破碎石基，早在恶魔用邪能魔法淹没该地区之前，这里就已经荒废很久了。",al={"这里有什么废墟","玛诺洛克古代废墟","凄凉之地的精灵废墟"}},{q="恶魔是如何抵达凄凉之地的？",a="火刃氏族的邪教徒在废墟各处维持着魔法召唤传送门。这些传送门不断地从扭曲虚空直接吸入增援部队，使得外界试图彻底净化该地点的努力受挫。",al={"恶魔从哪里来","凄凉之地的火刃氏族传送门"}}},fp="14,360,21.572.1,40.165.0,25.152.1,36.169.0,40.217.0"}
P.entries["subzone:manor-mistmantle"] = {n="密斯特曼托庄园",s="密斯特曼托庄园是一处腐朽的庄园，坐落在暮色森林东北部的阴影丘陵中，位于夜色镇以北。这里曾经是一个体面的家庭宅邸，如今已沦为废墟和恐怖之地，爬满了受其臭名昭著的主人驱使的亡灵食尸鬼。",h="密斯特曼托庄园是一处腐朽的庄园，坐落在暮色森林东北部的阴影丘陵中，位于夜色镇以北。这里曾经是一个体面的家庭宅邸，如今已沦为废墟和恐怖之地，爬满了受其臭名昭著的主人驱使的亡灵食尸鬼。",kw={"乞丐鬼屋","夜色镇","暮色森林","食尸鬼","密斯特曼托庄园","斯塔文","斯塔文·密斯特曼托","蒂罗亚之泪"},ang={["faction:Alliance"]="对于追踪斯塔文受害者悲惨命运的联盟调查者来说，密斯特曼托庄园是斯塔文传说悲剧性的终点。"},sec={{t="一处荒废的宅邸",b="密斯特曼托庄园位于乞丐鬼屋以西，是凶杀与疯狂的阴森纪念碑。庄园内充斥着腐烂的气息，凶残的食尸鬼徘徊其中，守护着这座破败的建筑。在腐烂和枯萎的植被中，这片土地上唯一的生命美景是那朵生长在无人照料的花园里、孤独而忧伤的花朵：名为蒂罗亚之泪的花。"},{t="庄园的主人",b="这座庄园属于斯塔文·密斯特曼托，他曾是一名教师和私人导师。他对自己的学生蒂罗亚一家犯下的骇人罪行，已成为王国里广为流传的黑暗传说。如今，身为亡灵代理人的斯塔文潜伏在自家宅邸的二楼，周围环绕着他所屠杀的受害者的残骸，并有蹒跚的恐怖生物守卫。来自夜色镇的旅人和调查者常常发现，这位暮色森林中最臭名昭著的幽灵的踪迹，最终都指向了这座血迹斑斑的庄园。"}},faq={{q="密斯特曼托庄园在哪里？",a="密斯特曼托庄园位于暮色森林的东北部，坐落在夜色镇的正北方，乞丐鬼屋的西侧。",al={"密斯特曼托庄园位置","密斯特曼托庄园在哪里","如何找到密斯特曼托庄园"}},{q="谁住在密斯特曼托庄园？",a="该庄园属于斯塔文·密斯特曼托，他曾是一名导师，如今已变成一个被食尸鬼环绕的亡灵生物。",al={"密斯特曼托庄园里的人","密斯特曼托庄园首领","斯塔文之屋"}},{q="什么是蒂罗亚之泪？",a="蒂罗亚之泪是盛开在密斯特曼托庄园花园中的一朵孤独而娇嫩的花，是腐朽的庄园中唯一的自然生命迹象。",al={"蒂罗亚之泪花朵","密斯特曼托花园花朵","蒂罗亚之花"}},{q="为什么这里有亡灵守卫？",a="在庄园里游荡的食尸鬼是受斯塔文·密斯特曼托驱使的爪牙，它们负责保护主人，并屠杀任何胆敢闯入这片荒芜庄园的人。",al={"为什么密斯特曼托有食尸鬼","密斯特曼托亡灵","密斯特曼托庄园敌人"}}},fx={["9fd71122"]={q="密斯特曼托庄园是什么地方？",a="密斯特曼托庄园是一处僻静的地产，坐落在夜色镇以北、乞丐鬼屋以西的幽暗树林中。它曾是体面人家的宅邸，如今却沦为亡灵盘踞的凄惨鬼地。庄园土地腐烂，死寂阴森，唯有一朵诡异的花孤零零地开在荒败的花园中。",al={"密斯特曼托庄园是什么地方","密斯特曼托庄园","关于密斯特曼托庄园"}},["592aed39"]={q="密斯特曼托庄园发生了什么？",a="这处庄园属于密斯特曼托家族，曾是前任校长兼家庭教师斯塔尔文·密斯特曼托的家。随着时间流逝，斯塔尔文背弃了文明生活的光明，陷入黑暗的疯狂，变成了不死生物的爪牙。他的堕落将整座庄园拖入毁灭，污染了土地，也引来了腐朽的怪物，在这位绅士曾经居住之处盘踞。",al={"密斯特曼托庄园的历史","密斯特曼托庄园发生了什么"}},["2075468e"]={q="密斯特曼托庄园为何破败荒废？",a="庄园随着主人斯塔尔文·密斯特曼托一同衰败。当死亡与腐化吞噬斯塔尔文后，活着的看守纷纷消失，正常生活的痕迹也逐渐凋零。亡灵亵渎之力污染了土壤，使庄园腐朽、荒废，并被邪恶的阴影吞没。",al={"密斯特曼托庄园为何破败","密斯特曼托庄园被遗弃","为何沦为废墟"}},["136a4555"]={q="密斯特曼托庄园危险吗？",a="这里极其危险。腐朽的庄园由斯塔尔文的食尸鬼爪牙严密看守，他们会残忍地杀死任何擅闯主人腐朽领地的人。若未做好充分准备便贸然接近，很可能会被躁动的亡灵迅速血腥地夺去性命。",al={"密斯特曼托庄园有多危险","密斯特曼托庄园的威胁","密斯特曼托庄园安全吗"}},a2b55f99={q="密斯特曼托庄园为何得名？",a="庄园以斯塔尔文·密斯特曼托及其家族血脉命名。在他堕入恐怖与腐化之前，这里曾是他的私人住宅和家族庄园；此后，家族之名便永远与这片噩梦之地联系在一起。",al={"密斯特曼托庄园为何得名","密斯特曼托庄园名称由来","谁给密斯特曼托庄园命名"}}},fp="16,239,20.393.0,24.505.1,34.132.0,30.115.1,27.177.0,42.173.1"}
P.entries["subzone:mardenholde-keep"] = {n="玛登霍尔德城堡",s="玛登霍尔德城堡是西瘟疫之地北端俯瞰壁炉谷的雄伟石制堡垒。它曾是提里奥·弗丁领主的祖传宅邸，如今在提里奥之子——泰兰·弗丁大领主的统治下，成为了狂热的血色十字军在该地区的Command Center。",h="玛登霍尔德城堡是西瘟疫之地北端俯瞰壁炉谷的雄伟石制堡垒。它曾是提里奥·弗丁领主的祖传宅邸，如今在提里奥之子——泰兰·弗丁大领主的统治下，成为了狂热的血色十字军在该地区的Command Center。",kw={"达索汉","壁炉谷","玛登霍尔德","血色十字军","白银之手","泰兰·弗丁","提里奥·弗丁"},ang={["class:Paladin"]="玛登霍尔德代表了圣骑士历史上悲剧性的一章：这里曾是白银之手高尚的圣所，而其大厅正是该组织在狂热的血色十字军与警惕的银色黎明之间分崩离析的地方。",["race:Human"]="对于洛丹伦的人类来说，玛登霍尔德是一个苦涩的提醒：他们家园中最引以为傲的堡垒在挺过了兽人战争后，却在天灾军团入侵期间沦为了疯狂与狂热的牺牲品。"},sec={{t="弗丁家族的领地",b="玛登霍尔德城堡最初是作为壁炉谷公国的行政中心而建，长期以来一直被洛丹伦的人民所称颂，因为在第二次战争期间它从未被攻破。提里奥·弗丁领主曾在议事大厅与其信任的顾问一同治理周边山谷，维持着和平，直到他因为捍卫兽人伊崔格而遭到了充满争议的审判与流放。在提里奥失势后，治理权先是落入了他那充满野心的学徒巴瑟拉斯手中，最终传给了提里奥之子泰兰，他在洛丹伦毁灭前夕继承了父亲的领地。"},{t="十字军的摇篮",b="当天灾军团横扫洛丹伦时，这座城堡归入了血色十字军的旗帜之下。然而，内部的偏执与黑暗的颠覆很快在其队伍中扎根，而达索汉和最狂热的信徒则将壁炉谷作为了十字军的坚固堡垒。"}},faq={{q="现在是谁在控制玛登霍尔德城堡？",a="这座城堡由血色十字军控制，是他们在西瘟疫之地的主要军事指挥中心。它直接由泰兰·弗丁大领主治理，他居住在主大厅中，周围环绕着精锐的血色十字军卫士。",al={"玛登霍尔德的领导者是谁","谁负责壁炉谷","玛登霍尔德的首领"}},{q="为什么这座要塞对提里奥·弗丁如此重要？",a="玛登霍尔德是提里奥·弗丁的祖居，也是他作为联盟圣骑士统治该地区的权力中心。他在这座城墙内抚养家人，直到他为了捍卫一位可敬的敌人而被剥夺头衔并遭到流放。",al={"提里奥与玛登霍尔德的联系","提里奥住在这里吗"}},{q="血色十字军是如何接管玛登霍尔德的？",a="在提里奥被流放以及第三次战争期间洛丹伦陷落后，提里奥之子泰兰放弃了白银之手，加入了血色十字军，从此城堡及其驻军开始为十字军效力。",al={"血色十字军如何占领壁炉谷","为什么血色十字军在这里"}},{q="玩家可以安全进入玛登霍尔德城堡吗？",a="不能。血色十字军认为所有外来者都是潜在的瘟疫携带者或他们事业的敌人。任何靠近城堡的冒险者都会被立即攻击，除非通过强大的幻象魔法进行伪装。",al={"玛登霍尔德是友好的吗","联盟可以进入玛登霍尔德吗","部落可以进入玛登霍尔德吗"}}},fp="16,302,21.577.0,21.278.1,40.234.0,53.235.0,50.199.0,42.225.0"}
P.entries["subzone:marris-stead"] = {n="玛瑞斯农场",s="玛瑞斯农场坐落在东瘟疫之地西南部的一座山脊上，曾是洛丹伦一处宁静的宅邸。在第三次战争的浩劫过后，它现在成了被遗忘者勇士纳萨诺斯·凋零者那座孤寂且防守严密的堡垒。",h="玛瑞斯农场坐落在东瘟疫之地西南部的一座山脊上，曾是洛丹伦一处宁静的宅邸。在第三次战争的浩劫过后，它现在成了被遗忘者勇士纳萨诺斯·凋零者那座孤寂且防守严密的堡垒。",kw={"凋零犬","东瘟疫之地","玛瑞斯农场","纳萨诺斯","纳萨诺斯·凋零者","纳萨诺斯·玛瑞斯","拉姆斯登","军情七处"},ang={["faction:Alliance"]="由于军情七处的特工失踪，这个由被遗忘者把持的农场成了联盟调查员在瘟疫之地的一个令人不安的焦点。",["faction:Horde"]="对于被遗忘者及其部落盟友来说，这个农场是他们与天灾军团和血色十字军作战时不可或缺的、防守严密的作战基地。"},sec={{t="游侠破碎的家园",b="在第三次战争之前，这座农场属于纳萨诺斯·玛瑞斯，他是一位著名的人类神射手，也是唯一被远行者接纳的人类游侠领主。当斯坦索姆陷落，天灾军团横扫洛丹伦时，恐怖的憎恶拉姆斯登在纳萨诺斯的家中将其逼入绝境并残忍杀害。他被复活成为效忠于巫妖王的无脑傀儡，但后来被Sylvanas Windrunner亲手解放，摆脱了天灾军团的控制，并在被遗忘者中占据了一席之地。"},{t="勇士的堡垒",b="如今，这位勇士自称为纳萨诺斯·凋零者，带着一群凶猛的凋零犬回到了他祖辈的农场。在女妖之王的命令下，他协调着瘟疫之地各处的打击行动，矛头直指天灾军团和血色十字军。这座农场也引起了暴风城情报部门阴森的注视：被派往此处调查被遗忘者活动的军情七处特工遭到了屠杀，这促使联盟发现了纳萨诺斯那可怕的转变，并对他发出了高额悬赏。"}},faq={{q="谁住在玛瑞斯农场？",a="这座农场目前被纳萨诺斯·凋零者所占据。他与他的凋零犬群居住于此，作为前线指挥官和女妖之王的勇士在此驻守。",al={"谁在玛瑞斯农场","谁住在这里","农场的npc","纳萨诺斯的位置"}},{q="纳萨诺斯是如何成为亡灵的？",a="第三次战争期间，天灾军团蹂躏了洛丹伦，将许多受害者复活为亡灵。纳萨诺斯的个人经历以及他如何摆脱天灾军团的控制，在相关部分有详细介绍。",al={"纳萨诺斯是怎么死的","纳萨诺斯之死","谁杀了纳萨诺斯"}},{q="联盟为何对这个农场感兴趣？",a="军情七处军情大师Mathias Shaw收到了关于被遗忘者异常活动的干扰报告，并派遣特工前去调查。当只有一名特工返回后，联盟又派遣了更多的调查员去探明其他人的下落。",al={"联盟与玛瑞斯农场","军情七处瘟疫之地","为什么要杀纳萨诺斯"}}},fp="12,267,22.490.1,22.543.1,26.176.0,31.188.0,44.210.1"}
P.entries["subzone:marshal-s-refuge"] = {n="马绍尔营地",s="马绍尔营地是安戈洛环形山北侧悬崖上一个摇摇欲坠的中立避难所。它由威利德·马绍尔及其探险队建立，在盆地中的原始野兽摧毁了他们低处的营地后，这里成为了应急的堡垒。",h="马绍尔营地是安戈洛环形山北侧悬崖上一个摇摇欲坠的中立避难所。它由威利德·马绍尔及其探险队建立，在盆地中的原始野兽摧毁了他们低处的营地后，这里成为了应急的堡垒。",kw={"洞穴","探险队","霍兰妮","马绍尔营地","安戈洛环形山","威利德·马绍尔"},ang={["class:Hunter"]="营地高悬在火山口地面之上，为猎人们提供了一个有利位置，使他们能在进入追踪区域前，深入研究安戈洛最稀有、最致命的野兽。",["race:Gnome"]="侏儒学者和现场工程师们发现，营地是一个理想的前哨站，可以用来测试在环形山奇异的能量水晶和不稳定的喷泉上使用的各种仪器。"},sec={{t="险峻的栖身之所",b="当威利德·马绍尔和霍兰妮·马绍尔带领探险队进入安戈洛环形山时，他们严重低估了这里史前生物的凶猛程度。在最初的基地营地屡次被横冲直撞的野兽摧毁后，伤痕累累的幸存者爬上了北部洞穴密布的悬崖，才得以逃脱屠戮。重整旗鼓后，这里被称为马绍尔营地，高悬在丛林地面之上，为安戈洛环形山北部的疲惫探险者提供了唯一稳定的休息点、基础补给和飞行管理员。"},{t="好奇心的交汇点",b="由于安戈洛环形山拥有古老的生物奇观和神秘的水晶构造，马绍尔营地吸引了一群形形色色的研究者、寻宝者和古怪的流浪者。来自各地的博物学家，包括矮人学者和侏儒技师，与幸存的马绍尔探险队员们共享着这片拥挤的崖架。以此为据点，侦察兵们向火羽山这样的火山峰顶，或葛拉卡温泉那样的沸腾地标进发，希望能在被这片原始荒野吞噬前将其记录在册。"}},faq={{q="为什么马绍尔营地要建在悬崖那么高的地方？",a="马绍尔探险队最初在盆地低处建立了营地，但安戈洛凶猛的恐龙和极具攻击性的生物不断践踏并摧毁了这些营地。幸存者们撤退到了北部的岩壁上，以此获得了一个安全且易守难攻的制高点，避开了大型野兽的威胁。",al={"为什么它在洞穴里","马绍尔营地位置","为什么建在悬崖边"}},{q="马绍尔营地对部落和联盟都友好吗？",a="是的。它作为一个中立前哨站运作。安戈洛环形山的原始危机使得阵营对抗成为一种无法承担的奢侈，因此双方阵营的成员在此和平共处，进行补给和学术交流。",al={"马绍尔营地是中立的吗","部落可以去这里吗","联盟可以去这里吗"}},{q="谁在领导这个营地？",a="这个前哨站由威利德·马绍尔和霍兰妮·马绍尔领导，他们正是组织了那次命运多舛的安戈洛环形山马绍尔探险队的领头人。",al={"谁在负责","谁经营马绍尔营地","营地领袖"}},{q="营地提供哪些服务？",a="该营地在偏远的盆地中提供基本的生存必需品，包括为两个阵营提供服务的飞行管理员、基础贸易商人、修理服务，以及供研究者交流情报、悬赏任务和环形山调查工作的聚集点。",al={"飞行路线","修理","商人"}}},fp="16,250,18.523.0,25.526.0,52.295.0,56.206.0,25.138.0,42.253.0"}
P.entries["subzone:marshlands"] = {n="沼泽地",s="沼泽地是一片广阔且潮湿的湿地，占据了安戈洛环形山东南部的区域。它位于从塔纳利斯蜿蜒而下的斜坡尽头，往往是新来者进入这片原始盆地时见到的第一处荒野。",h="沼泽地是一片广阔且潮湿的湿地，占据了安戈洛环形山东南部的区域。它位于从塔纳利斯蜿蜒而下的斜坡尽头，往往是新来者进入这片原始盆地时见到的第一处荒野。",kw={"蓝色能量水晶","沼泽地","莫维克","迅猛龙","拉瓦萨龙","塔纳利斯","托尔瓦·寻路者","安戈洛"},ang={["class:Hunter"]="沼泽地是检验荒野生存能力的试金石，这里遍布着敏捷的迅猛龙、剧毒的掠食者，还有像托尔瓦·寻路者这样经验丰富的追踪者所指引的罕见野兽。",["profession:Herbalism"]="沼泽的北缘被具有攻击性的血瓣花幼苗和潮湿的植被所覆盖，是观察敌对、可移动植物生命的绝佳地点。"},sec={{t="通往环形山的大门",b="从塔纳利斯的干旱地带沿着陡峭的小径向下，旅行者会直接进入沼泽地潮湿的泥沼中。安戈洛环形山的其他区域边缘都是绝壁，攀爬极易坠亡，这使得这片险恶的湿地成为了进入安戈洛的主要通道。茂密的植被、积水和泥地里潜伏着大量凶猛的迅猛龙，其中还包括在芦苇丛中潜行的剧毒品种。在潮湿的空地上，探险者可以发现散落在地面的蓝色能量水晶，这是该区域特有的资源。"},{t="沼泽中的营地",b="尽管时刻面临掠食者的威胁，几位孤独的荒野专家仍在这里维持着据点。牛头人猎人托尔瓦·寻路者驻扎在一处显眼的土丘上，观察着此地的原始生物。在湿地的另一端，巨魔莫维克正在研究和训练当地的拉瓦萨龙。"}},faq={{q="为什么沼泽地通常是人们进入安戈洛后看到的第一片区域？",a="安戈洛环形山四周环绕着陡峭的悬崖，除了塔纳利斯的东南通道外，从其他任何地点进入几乎都会导致死亡。这条坡道直通沼泽地，迫使所有陆路旅行者必须穿过这片潮湿的区域。",al={"如何进入安戈洛","进入安戈洛环形山","沼泽地入口"}},{q="这里最常见的生物是什么？",a="这片沼泽以拥有大量迅猛龙而闻名。其中包括普通的狩猎型迅猛龙和致命的剧毒品种，它们能够在茂密的灌木丛中对粗心的探险者发起围攻。",al={"沼泽地野兽","沼泽地迅猛龙","这里有什么生物"}},{q="沼泽地里能找到什么独特的资源？",a="沼泽地是安戈洛环形山中唯一自然形成蓝色能量水晶的地方。这些发光的矿石碎片受到那些研究散布在盆地各处的神秘水晶塔的学者们的珍视。",al={"蓝色能量水晶","沼泽地水晶","安戈洛蓝色水晶"}},{q="托尔瓦·寻路者是谁？",a="托尔瓦·寻路者是一位经验丰富的牛头人猎人，驻扎在沼泽地内的一座高土丘上。他观察着环形山的生态系统，并指引有能力的冒险者对抗安戈洛最凶猛的野兽。",al={"托尔瓦","托尔瓦·寻路者营地"}},{q="这里的拉瓦萨龙可以被驯服或训练吗？",a="可以。住在沼泽地的巨魔莫维克专门负责处理和饲养当地的拉瓦萨龙，他能提供关于这些生物攻击性本能和习性的深刻见解。",al={"拉瓦萨龙训练师","莫维克","训练拉瓦萨龙"}}},fp="10,248,21.540.0,22.301.0,67.252.0,36.190.0,50.222.0,24.202.0,43.162.0"}
P.entries["subzone:mast-room"] = {n="Mast Room",s="Mast Room是一处巨大的地下伐木场，深藏于死亡矿井之中。这里由地精工头斯尼德及其木匠负责监管，专门加工从西部荒野掠夺来的木材。",h="Mast Room是一处巨大的地下伐木场，深藏于死亡矿井之中。这里由地精工头斯尼德及其木匠负责监管，专门加工从西部荒野掠夺来的木材。",kw={"死亡矿井","地精木匠","伐木场","mast room","收割机","斯尼德"},ang={["faction:Alliance"]="在这个洞穴中加工的木材表明，迪菲亚在西部荒野的劫掠并非简单的土匪行径，而是一场协调一致的工业生产行动。",["profession:Engineering"]="斯尼德在洞穴中操作的地精收割机是原始蒸汽与齿轮技术的奇迹，它原本用于森林伐木，如今被改装用来碾碎入侵者。"},sec={{t="地下锯木厂",b="穿过死亡矿井深处的矿道，便可抵达Mast Room。这是一个巨大的洞穴，已被改建成了一座功能齐全的伐木场。堆积如山的木材、锯末以及巨大的切割设备充斥着整个空间。地精木匠们正是在这里加工制造巨大的桅杆、龙骨和木板，以组装隐藏在铁甲湾深处的巨型战舰。在斯尼德的严密监视下，迪菲亚潜行者将西部荒野砍伐的木材转化为战争机器的零件。"},{t="工业劳作",b="这个洞穴展示了地精工业最冷酷的一面。斯尼德坐在一台机械收割机上监督生产，确保木匠们完成繁重的配额。巨大的圆木被源源不断地吊起并刨平，将曾经死寂的金矿变成了一个轰鸣作响、烟尘弥漫的造船厂。"}},faq={{q="为什么地下矿井里会有伐木场？",a="迪菲亚潜行者正在秘密建造一艘巨大的战舰，位置就在矿井下方的海湾里。Mast Room作为该船只的桅杆、骨架和船壳板的组装与塑形场所，所用的木材均是从西部荒野地表走私而来的。",al={"为什么这里有木材","为什么死亡矿井里有木头","mast room的用途"}},{q="谁负责管理Mast Room？",a="这个洞穴由斯尼德负责监管，他是一位地精工艺大师，在驾驶致命的机械伐木机指挥地精木匠们工作。",al={"mast room的首领","谁领导mast room","斯尼德是谁"}},{q="为什么地精会为迪菲亚效力？",a="艾德温·范克里夫雇佣了地精工程师和工匠，以提供人类石匠所缺乏的技术专长。地精们用重型机械、爆炸物和造船技术来换取金钱和利润。",al={"为什么地精在死亡矿井","迪菲亚地精"}}},fx={["7bd4bec3"]={q="Mast Room是什么地方？",a="Mast Room是死亡矿井深处的一座地下伐木场和木工工坊，位于第二矿道稍远处。这里由受雇的地精工匠经营，负责把木材加工成关键部件，尤其是重型桅杆和结构木料，供艾德温·范克里夫停泊在洞穴更深处的秘密战船使用。",al={"mast room是什么地方","死亡矿井的mast room","关于mast room"}},b5fbae6b={q="Mast Room为何得名？",a="它因主要用途而得名：加工迪菲亚潜行者秘密战舰所需的巨型木材和高耸桅杆。在这片地下大厅深处，地精木雕师将运入矿井的原木锯切并加工，用来建造迪菲亚潜行者秘密舰队的装备船只。",al={"mast room为何得名","mast room名称含义","为何叫mast room"}},["31a4c95c"]={q="Mast Room危险吗？",a="危险。勤劳的地精木雕师严密看守着这间工坊，斯尼德则驾驶致命的地精碎木机监视闯入者。旋转的锯片、沉重的伐木机械，以及全副武装的迪菲亚雇佣兵，让任何打扰木工活计的人都难以安全穿过这里。",al={"mast room危险吗","mast room的危险","mast room里的威胁"}}},fp="9,203,23.487.1,16.324.1,54.252.1,23.146.0,44.217.1"}
P.entries["subzone:master-s-cellar"] = {n="主宰的庇护所",s="主宰的庇护所是一处庞大的地下建筑群，位于逆风小径中卡拉赞南部的废弃定居点下方。这里曾是麦迪文庄园的酒窖和储藏室，如今已沦为一座闹鬼的废墟，到处都是昔日仆人和看守者那不安的幽灵。",h="主宰的庇护所是一处庞大的地下建筑群，位于逆风小径中卡拉赞南部的废弃定居点下方。这里曾是麦迪文庄园的酒窖和储藏室，如今已沦为一座闹鬼的废墟，到处都是昔日仆人和看守者那不安的幽灵。",kw={"逆风小径","卡拉赞","下层地窖","主宰的庇护所","麦迪文","不死的看守者"},ang={["class:Mage"]="守护者庄园下方徘徊的幽灵遗迹证明了麦迪文倒下时所引发的严重奥术反噬，将普通的家政储藏室变成了一处挥之不去的幽灵能量枢纽。",["class:Priest"]="被困在潮湿地窖中的受折磨的幽灵，是那些普通的看守者和仆人的悲惨灵魂，他们因逆风小径上挥之不去的诅咒而无法获得安宁。"},sec={{t="卡拉赞闹鬼的腹地",b="在宏伟的卡拉赞高塔以南，坐落着一片废弃村落的遗迹，这里曾住着维护麦迪文庄园的仆人、园丁和侍从。主宰的庇护所就位于这些坍塌房屋的下方。该建筑群可以通过地表废墟中的两个独立入口进入，并在地下向远处延伸。一个入口通向宽敞的拱顶酒窖，另一个则穿过坍塌的石块，通往深邃的天然洞穴。无论卡拉赞及其主人遭遇了怎样的黑暗结局，这片地下室也未能幸免，昔日的看守者化作了不死生物，哀嚎的幽灵和受诅咒的灵魂被困在这里，永世不得解脱。"},{t="下层洞穴",b="该建筑群的最深处被称为下层地窖，这里展示了地窖地板如何塌陷进逆风小径的天然岩层中。地窖的地基坍塌进了这些洞穴系统，形成了一座回荡着鬼哭狼嚎的崎岖迷宫。虽然探索小径的冒险者在这里几乎找不到活人，但从附近高塔渗出的弥漫性魔法腐蚀已将这些幽灵牢牢地束缚在岩石上，使得这些洞穴与上方的废墟一样危险。"}},faq={{q="主宰的庇护所最初的用途是什么？",a="它曾是卡拉赞高塔的主要储藏室和酒窖。上方的村庄安置着负责维护守护者麦迪文庞大家产的家政人员和园丁，他们利用这些地下金库来存放物资和陈年酒桶。",al={"主宰的庇护所的用途","这是什么地窖","为什么这里有酒窖"}},{q="为什么地窖里到处都是幽灵？",a="没有人确切知道他们遭遇了什么。无论卡拉赞及其主人遭遇了怎样的黑暗命运，这片村落也未能幸免，曾经居住在那里的仆人和村民如今化作了不安的暗影、哀嚎的幽灵和不死的看守者，在废墟中徘徊。",al={"为什么有幽灵","地窖里的不死生物是谁","为什么主宰的庇护所会闹鬼"}},{q="如何进入地窖下方的洞穴系统？",a="在卡拉赞南部的废墟建筑中，有两个不同的地窖入口。东侧的入口通向结构完整的酒窖，而西侧的入口则通向一段坍塌的石工结构，由此可以进入下层地窖的天然地下洞穴。",al={"如何进入下层地窖","主宰的庇护所入口","洞穴入口在哪里"}},{q="主宰的庇护所与卡拉赞内部直接相连吗？",a="不。尽管它靠近高塔底部，并且在历史上承担着为守护者庄园提供物资的任务，但这些地下房间并没有通往卡拉赞内部的通道。地窖依然是独立存在于村庄废墟之下的。",al={"主宰的庇护所通向卡拉赞吗","从地窖进入卡拉赞的入口"}}},fp="15,302,30.662.0,17.508.0,49.272.0,33.256.0,52.288.0,70.251.0"}
P.entries["subzone:master-s-glaive"] = {n="主宰之剑",s="主宰之剑是一处古老且令人不安的地标，位于黑海岸西南部，一把巨大的精金武器深深地插在一个巨大的石化头骨中。长期以来，当地的暗夜精灵一直将其视为神圣的谜团，而现在，受某种古老实体残留的邪恶力量吸引，暮光之锤的邪教徒们蜂拥至此。",h="主宰之剑是一处古老且令人不安的地标，位于黑海岸西南部，一把巨大的精金武器深深地插在一个巨大的石化头骨中。长期以来，当地的暗夜精灵一直将其视为神圣的谜团，而现在，受某种古老实体残留的邪恶力量吸引，暮光之锤的邪教徒们蜂拥至此...",kw={"黑海岸","主宰之剑","上古之神","暮光之锤"},ang={["race:NightElf"]="几代以来，暗夜精灵一直将这座奇怪的石化纪念碑视为神圣的场所，因此暮光之锤邪教最近的入侵是对黑海岸这片神圣土地令人无法容忍的亵渎。"},sec={{t="古代冲突的纪念碑",b="主宰之剑从黑海岸的土地上拔地而起，那是一把巨大的精金之刃，深深地埋在一个巨大的石化头骨中。没有任何记录记载死在这里的生物，也没有记录记载是谁将这把利刃插入其中。知识古树欧努只说，一位古老得可怕的大地之主倒在了这里，而暗夜精灵们长期以来一直认为，只有泰坦才能挥舞如此巨大的武器。今天，这块被贯穿的巨石作为那场被遗忘的斗争的见证，矗立在那里，成为一座石化的纪念碑。"},{t="黑暗发掘",b="虽然这个地点几代以来一直受到暗夜精灵的肃穆崇敬，但最近邪恶势力占领了这里。暮光之锤邪教的狂热分子在沉没的尸骸周围建立了营地，开凿出战壕，并挖掘出石化的肋骨。受到石头下方低语的吸引，邪教徒们痴迷地研究着这些遗骸，并与仍然依附在这些古老残骸上的邪恶力量进行沟通，试图复活或利用沉睡在大地之中的某种邪恶本质。"}},faq={{q="插在头骨上的巨型武器是什么？",a="没人能确定。那把巨大的精金之刃正是主宰之剑本身，它是在某个被遗忘的时代被插入头骨之中的。暗夜精灵们相信，只有泰坦才能挥舞如此巨大尺寸的武器。",al={"主宰之剑是什么","主宰之剑","谁把剑插在那里的"}},{q="这里埋着什么生物的头骨？",a="它的名字已经失传了。知识古树欧努只说，一位古老得可怕的大地之主倒在了这里，而暮光之锤相信这些石化的遗骸属于上古之神的仆从。",al={"什么生物死在这里","主宰之剑下埋葬的是谁"}},{q="暮光之锤邪教为什么聚集在这里？",a="暮光之锤邪教崇拜上古之神。他们占领了主宰之剑并开始挖掘那些石化的遗骸，因为受到了残留的黑暗力量的吸引，并希望让那个倒下的生物复活。",al={"邪教徒为什么在这里","黑海岸的暮光之锤","邪教徒在挖掘什么"}},{q="谁了解这个地点的历史？",a="居住在黑海岸的知识古树欧努认出这里是一位古老的大地之主的安息之地，并指示调查者们去一探究竟。",al={"谁在研究主宰之剑"}}},fx={ce9b9209={q="主宰之剑是什么地方？",a="主宰之剑是一处古老而宏伟的遗迹，坐落在黑海岸西南部。这里最引人注目的是一颗巨大的石化头骨，头骨顶部被一把巨大的精金利刃刺穿。暗夜精灵曾将此地视为神圣之地，如今这里却成了一处笼罩在黑暗崇拜阴影下的邪恶发掘现场。",al={"主宰之剑是什么地方","黑海岸的主宰之剑","这个地方是什么"}},["0f8799c2"]={q="主宰之剑发生过什么？",a="没有记载讲述完整的故事。知识古树奥努只说，一位极其古老的大地领主曾在此陨落，被一把巨大无比的利刃杀死。暗夜精灵认为，只有泰坦才能挥舞如此巨刃。它石化的头骨仍留在陨落之处，长柄刀依旧刺在头骨顶端。",al={"主宰之剑的历史","这里发生过什么战斗","索格斯的历史"}},["1f2acdb9"]={q="谁控制着主宰之剑？",a="如今，此地落入暮光之锤教派的掌控。狂热的教徒遍布盆地，在石化遗骸周围进行挖掘；他们受疯狂预言驱使，想要挖出并唤醒这头陨落的生物。",al={"谁住在主宰之剑","主宰之剑里有哪些人","主宰之剑的教徒"}},f9a41c7d={q="主宰之剑危险吗？",a="这里极其危险。狂热的暮光之锤教徒积极看守发掘现场，一发现入侵者便会发动攻击。除了这些狂热的凡人之外，沉睡遗骸散发的残余邪恶气息也让盆地成为一处险地，粗心大意者很容易遭殃。",al={"主宰之剑危险吗","这里安全吗","主宰之剑的威胁"}},["5be20272"]={q="主宰之剑为何得名？",a="此地因嵌入大地的巨型武器而得名。在遥远的遗忘年代，这把巨刃刺入一头早已陨落的生物头骨，后来便在传说中被称为主宰之剑。",al={"主宰之剑为何得名","主宰之剑名称由来","这个名字从何而来"}}},fp="15,333,30.490.0,16.506.0,46.219.0,37.192.0,48.207.0,41.160.0"}
P.entries["subzone:maul-subzone"] = {n="Maul (subzone)",s="巨槌竞技场是一座位于菲拉斯的厄运之槌遗迹外破碎平原中的下沉式角斗场。这里曾是古老的暗夜精灵城市埃雷萨拉斯的宏伟场地，如今却变成了一个无法无天的血腥运动场，流浪者们在此为了荣耀或生存，与凶猛的野兽和敌对的勇士厮杀。",h="巨槌竞技场是一座位于菲拉斯的厄运之槌遗迹外破碎平原中的下沉式角斗场。这里曾是古老的暗夜精灵城市埃雷萨拉斯的宏伟场地，如今却变成了一个无法无天的血腥运动场，流浪者们在此为了荣耀或生存，与凶猛的野兽和敌对的勇士厮杀。",kw={"破碎平原","厄运之槌竞技场","埃雷萨拉斯","菲拉斯","自由混战pvp","穆什戈格","不可撼动者斯卡尔","巨槌竞技场","拉扎"},ang={["class:Warrior"]="对于那些在有组织的战场之外寻求纯粹战斗的战士来说，巨槌竞技场提供了原始、未经修饰的血腥运动，只有个人的实力和坚硬的护甲才能决定生死。",["race:NightElf"]="看着古老埃雷萨拉斯骄傲的建筑被贬为食人魔出没的处决坑，这令人痛苦地回想起上层精灵文明已经没落到了何种地步。"},sec={{t="沉没的深坑",b="巨槌竞技场深凿于破碎平原的岩石之中，曾作为埃雷萨拉斯的上层精灵的剧院或仪式竞技场。在大分裂之后，随着戈多克食人魔的入侵，这里沦为了一个野蛮的角斗场。就像远在荆棘谷臭名昭著的古拉巴什竞技场一样，一旦踏入巨槌竞技场的沙地，所有的效忠关系都会被暂停，战斗者被卷入一场无法无天的混战，派系界限荡然无存，生存完全取决于个人的武力。"},{t="野兽与杀戮",b="进入竞技场的挑战者必须谨慎行事。虽然勇敢的斗士经常从平原的高处直接跳下，但坠落会造成巨大的伤害。从西侧的拱门穿过隧道是更安全的选择，那里有沉睡的戈多克鬣狗，这也是离开竞技场地面唯一的步行出口。危险的野兽和臭名昭著的角斗士会不定期地出现在坑中，使每一次进入都成为对钢铁意志和本能的不可预测的考验。"}},faq={{q="为什么我可以在这里攻击我同阵营的成员？",a="巨槌竞技场是一个无法无天的战斗坑，就像荆棘谷的古拉巴什竞技场一样。当你踏入它的沙地时，标准的阵营条约和停火协议将不再适用，这会将战斗者标记为可以与非队友的任何人进行混战。",al={"自由混战pvp 厄运之槌","自由混战竞技场","为什么我可以攻击部落"}},{q="我该如何安全地进出巨槌竞技场？",a="虽然你可以直接从破碎平原跳下去，但这样会造成严重的坠落伤害。最安全的路径是穿过平原西侧的一道拱门，沿着隧道绕过沉睡的戈多克鬣狗。这条隧道也是步行攀爬出来的唯一途径。",al={"如何进入巨槌竞技场","巨槌竞技场入口","离开巨槌竞技场"}},{q="竞技场里会出现什么样的敌人？",a="除了敌对的冒险者之外，据闻还有异域且凶残的威胁会潜入竞技场坑中，包括巨大的真菌巨人穆什戈格、被称为“拉扎”的奇美拉，以及凶猛的角斗士“不可撼动者”斯卡尔。",al={"竞技场稀有精英","巨槌竞技场刷新怪物","巨槌竞技场首领"}},{q="这个竞技场最初是做什么用的？",a="在大分裂破碎古老的卡利姆多之前，这座石制角斗场属于伟大的上层精灵城市埃雷萨拉斯。入侵的戈多克食人魔将这座古老的精灵建筑改造成了适合他们野蛮口味的血腥竞技场。",al={"巨槌竞技场背景","谁建造了巨槌竞技场","埃雷萨拉斯竞技场"}}},fp="14,297,14.496.0,20.468.0,48.270.0,41.288.0,42.219.0,40.240.0"}
P.entries["subzone:mazthoril"] = {n="麦索瑞尔",s="麦索瑞尔是一座位于冬泉谷中心地带的巨大冰封洞穴，它是蓝龙军团在卡利姆多北部的核心据点。洞穴由龙人、施法巨龙和奥术哨兵重重把守，蜿蜒的冰冻隧道中隐藏着强大的魔法，并通往隐居的蓝龙族母海蕾的巢穴。",h="麦索瑞尔是一座位于冬泉谷中心地带的巨大冰封洞穴，它是蓝龙军团在卡利姆多北部的核心据点。洞穴由龙人、施法巨龙和奥术哨兵重重把守，蜿蜒的冰冻隧道中隐藏着强大的魔法，并通往隐居的蓝龙族母海蕾的巢穴。",kw={"蓝龙军团","科尔巴坦","海蕾","玛里苟斯","麦索瑞尔","奥妮克希亚钥匙","斯佩尔莫","冬泉谷"},ang={["class:Mage"]="作为玛里苟斯仆从的领域，麦索瑞尔充满了浸润在纯粹奥术能量中的生物，这使它成为了奥术学者们极为关注的地点。",["faction:Alliance"]="调查黑龙军团的联盟英雄会前往麦索瑞尔寻找族母海蕾。"},sec={{t="蓝龙的堡垒",b="麦索瑞尔开凿在永望镇南部的冰冻山脉中，栖息着一大群效忠于织法者玛里苟斯的蓝龙。洞穴及其周围的峭壁由警觉的龙人把守，包括斯佩尔莫、阿祖罗斯和科尔巴坦将军，而精锐的守卫则监视着内部洞穴。任何闯入麦索瑞尔的人都将面对完全受奥术能量浸润的龙兽，若无充分准备，深入其中将极为危险。"},{t="传送符文与族母",b="在冰封迷宫的深处，有一枚由幼龙法力之爪和斯克里尔严密看守的神奇地面符文。踏上这枚符文会将旅行者传送到洞穴上方一个孤立的山顶巢穴。蓝龙军团的族母海蕾居住于此，并维持着高等精灵的伪装。尽管海蕾对凡人天生保持警惕，但她拥有关于龙族血统的深厚知识，并在破解保护奥妮克希亚的巢穴的隐藏结界中扮演着关键角色。"}},faq={{q="谁统治着麦索瑞尔？",a="麦索瑞尔由强大的蓝龙族母海蕾管辖。她居住在洞穴建筑群上方高处的孤立巢穴中，只能通过位于隧道深处的魔法传送符文进入。当她接待凡人访客时，会幻化成一位高等精灵女性的形象。",al={"谁领导麦索瑞尔","麦索瑞尔的首领是谁","麦索瑞尔族母"}},{q="为什么蓝龙会居住在冬泉谷？",a="蓝龙军团受泰坦委派守护艾泽拉斯的奥术魔法，他们密切监视着世界各地残留的古老能量之源。冬泉谷拥有凯斯利尔湖周围上层精灵古老文明的遗迹，这使得麦索瑞尔成为他们哨兵在卡利姆多的天然据点。",al={"为什么冬泉谷有龙","为什么蓝龙军团在这里","冬泉谷的玛里苟斯龙群"}},{q="如何到达海蕾那里？",a="要到达海蕾那里，你必须在麦索瑞尔内部洞穴中杀出一条血路，穿过重重龙人。在那里，在幼龙法力之爪和斯克里尔的侧翼护卫下，地面上有一枚发光的奥术符文。踏入符文中心即可将你传送到她位于山顶的高处栖息地。",al={"到达海蕾","找到海蕾","传送到海蕾处","海蕾在哪里"}},{q="麦索瑞尔在进入奥妮克希亚的巢穴中扮演什么角色？",a="正在调查奥妮克希亚保护结界的联盟英雄会被派去咨询海蕾。她在这一旅程中的作用将在受保护的部分进行探讨。",al={"奥妮克希亚钥匙麦索瑞尔","奥妮克希亚开门任务海蕾","龙火护符海蕾"}}},fp="9,330,25.462.0,40.462.1,20.292.0,44.320.0,23.273.0,56.140.2"}
P.entries["subzone:menethil-bay"] = {n="米奈希尔海湾",s="米奈希尔海湾是湿地西海岸一片受庇护的水域，坐落在米奈希尔港和丹莫罗北部的陡峭悬崖之间。这片水域向外通往更广阔的巴拉丁海湾，栖息着凶猛的鳄鱼，还有沉船的残骸。这里是联盟往返于东部王国和卡利姆多之间的主要海上航道。",h="米奈希尔海湾是湿地西海岸一片受庇护的水域，坐落在米奈希尔港和丹莫罗北部的陡峭悬崖之间。这片水域向外通往更广阔的巴拉丁海湾，栖息着凶猛的鳄鱼，还有沉船的残骸。这里是联盟往返于东部王国和卡利姆多之间的主要海上航道。",kw={"巴拉丁海湾","鳄鱼","丹莫罗","飞鹰号","米奈希尔海湾","米奈希尔港","湿地"},ang={["faction:Alliance"]="米奈希尔海湾是通往米奈希尔港的重要海上通道，保障了连接铁炉堡、暴风城与卡利姆多之间脆弱的海上航线。"},sec={{t="湿地的庇护水域",b="作为无尽之海沿岸更广阔的巴拉丁海湾的一部分，米奈希尔海湾形成了一个天然的入口，北接米奈希尔港，东临黑水沼泽，南靠丹莫罗高耸的海岸断崖。其浅滩边缘和沼泽海岸爬满了各种年龄和体型的鳄鱼，使得这些浅水区对于没有向导的旅行者来说危机四伏，尽管该海湾是联盟海上交通的命脉。在海湾入口附近躺着飞鹰号的残骸，无声地提醒着人们水面下潜藏的危险。"}},faq={{q="米奈希尔海湾具体在哪里？",a="米奈希尔海湾位于湿地的西海岸。它坐落在巴拉丁海湾更广阔的区域内，北侧是米奈希尔港，东侧是黑水沼泽，南侧是丹莫罗北部的山崖。",al={"米奈希尔海湾在哪里","米奈希尔海湾位置","湿地海湾"}},{q="米奈希尔海湾里生活着什么生物？",a="海湾的沼泽海岸和浅水入口栖息着大量各种体型的鳄鱼。它们以伏击毫无防备的游泳者而闻名，经常被寻找珍贵毛皮的制皮师猎杀。",al={"米奈希尔海湾怪物","海湾里有什么","米奈希尔海湾的鳄鱼"}},{q="海湾里的沉船是什么？",a="位于米奈希尔海湾入口附近的残骸属于飞鹰号，这是一艘沉没在港口航道附近沿海水域的船只。",al={"米奈希尔海湾沉船","飞鹰号","湿地沉船"}},{q="为什么这个海湾对联盟很重要？",a="该海湾庇护着米奈希尔港，这是连接铁炉堡和卡兹莫丹北部土地与卡利姆多及南方的主要海军门户。往返于塞拉摩和黑海岸的运输船必须经过这片水域。",al={"米奈希尔海湾的重要性","湿地的联盟港口","米奈希尔港水域"}}},fx={["9552f6cb"]={q="米奈希尔海湾危险吗？",a="危险。海湾水域栖息着具有攻击性的野生生物，会严重威胁毫无防备的旅行者和潜水者。湾中到处都是不同年龄、体型各异的鳄鱼，它们皮糙肉厚，撕咬凶狠。穿过海湾入口或探索“飞翔的鱼鹰号”之类的沉船时，必须时刻提防这些掠食者。",al={"米奈希尔海湾安全吗","米奈希尔海湾的危险","米奈希尔海湾里的威胁"}}},fp="12,405,32.571.0,38.247.0,36.200.0,35.161.0,41.241.0"}
P.entries["subzone:menethil-harbor"] = {n="米奈希尔港",s="米奈希尔港是一座戒备森严的矮人港口城镇，坐落在湿地西海岸外的一座岛屿上。它以泰瑞纳斯·米奈希尔二世国王的名字命名，是连接东部王国与遥远的卡利姆多大陆的主要海上生命线。在巨大的石质城墙和米奈希尔城堡坚固塔楼的庇护下，这里成为了商人们、休假的士兵们以及粗犷冒险者们熙熙攘攘的中心。",h="米奈希尔港是一座戒备森严的矮人港口城镇，坐落在湿地西海岸外的一座岛屿上。它以泰瑞纳斯·米奈希尔二世国王的名字命名，是连接东部王国与遥远的卡利姆多大陆的主要海上生命线。在巨大的石质城墙和米奈希尔城堡坚固塔楼的庇护下，这里成...",kw={"奥伯丁","船","深水","码头","渡轮","港口","米奈希尔","斯托菲","塞拉摩","湿地"},ang={["faction:Alliance"]="对于任何向西旅行的联盟旅者来说，米奈希尔港是至关重要的中转站，也是连接东部王国与塞拉摩的唯一海上桥梁。",["race:Dwarf"]="虽然冠以人类国王的名字，但这处港口主要由矮人的石艺建筑维护，并由把守着卡兹莫丹外部防线的铁炉堡卫兵驻守。"},sec={{t="一座堡垒避风港",b="为了向洛丹伦的泰瑞纳斯·米奈希尔二世国王致敬，米奈希尔港成为了联盟在湿地海岸的一座重要避风港。尽管地处偏远的沼泽地带，它依然是一座防守严密的堡垒，有着巨大的城墙、一条连通的栈桥，以及米奈希尔城堡的四座石质瞭望塔的加固。"},{t="横跨无尽之海的门户",b="如今，这座港口是联盟的交通大枢纽。船只不断地横跨大洋，驶向尘泥沼泽的塞拉摩岛，或是经由南海镇前往黑海岸的奥伯丁，运载着贸易物资、外交官，以及在深水旅店挥霍薪水的休假库尔提拉斯海军陆战队士兵。然而，这里的和平十分脆弱：通往丹奥加兹的内陆补给线经常受到龙喉氏族的袭扰，而北面沼泽地带潜伏的黑铁矮人突袭者也给港口带来了巨大压力，这使得斯托菲队长和港口守卫队必须时刻保持警惕。"}},faq={{q="米奈希尔港的船只驶向哪里？",a="从米奈希尔港码头出发的船只将横跨无尽之海前往卡利姆多大陆。定期的客轮不仅有前往尘泥沼泽塞拉摩岛的航线，还会向北前往希尔斯布莱德丘陵的南海镇，并从那里继续航行至暗夜精灵的避风港奥伯丁。",al={"米奈希尔港船只","船去哪里","米奈希尔渡轮","卡利姆多船只"}},{q="谁在统治米奈希尔港？",a="米奈希尔港是以铁炉堡为权威的联盟定居点。斯托菲队长指挥着城镇守卫队，并负责米奈希尔城堡的港口防务工作，保护码头免受沼泽野兽、叛逃兽人以及内陆突袭者的侵扰。",al={"谁负责米奈希尔","米奈希尔港领导者","谁领导米奈希尔"}},{q="为什么这座城镇被命名为米奈希尔？",a="这座港口是以洛丹伦的泰瑞纳斯·米奈希尔二世国王的名字命名的，他的领导力将人类、矮人和精灵王国联合成了最初的洛丹伦联盟。",al={"为什么叫米奈希尔港","米奈希尔名字由来","谁是米奈希尔"}},{q="这座港口目前面临着哪些威胁？",a="港口面临着潜伏在湿地丘陵中的龙喉氏族持续不断的威胁，他们经常试图切断通往丹奥加兹的通道，以切断港口的增援。北面靠近丹莫德的黑铁矮人入侵以及四处游荡的迅猛龙也让守卫们倍感头疼。",al={"米奈希尔港有危险吗","米奈希尔威胁","湿地兽人米奈希尔"}}},fx={["0f75d9a0"]={q="米奈希尔港是什么地方？",a="米奈希尔港是一座设防的矮人港口城镇，坐落在湿地西缘的一座岛上。这里背靠厚重的石墙和高耸的米奈希尔城堡，是联盟横渡无尽之海前往卡利姆多的主要门户，连接着东部王国、塞拉摩岛和奥伯丁。港口里水手、商人、士兵和旅行者云集，是一处繁忙而坚固的避风港。",al={"这个城镇是什么地方","米奈希尔城镇","关于米奈希尔港"}},["13315efd"]={q="米奈希尔港发生过什么？",a="长期以来，米奈希尔港一直是联盟在湿地海岸设防的港口。近来，龙喉氏族推进至丹奥加兹，威胁切断港口与洛克莫丹之间的联系；与此同时，黑铁矮人占据了北方的丹莫德，使斯托菲队长的守军时刻保持戒备。",al={"米奈希尔的历史","米奈希尔历史","米奈希尔港的过往"}},f08a7377={q="米奈希尔港危险吗？",a="城门以内，坚固的城墙、矮人卫兵和米奈希尔城堡的火炮守护着这座城镇。然而，城墙之外的湿地危机四伏。龙喉兽人在山丘间密谋，迅猛龙在沼泽地中徘徊，走私者和好斗的水手则常出没于当地酒馆。这里适合诚实的旅人歇脚和交易，但每当你靠近沼泽或码头的阴影处，都应保持谨慎。",al={"米奈希尔安全吗","米奈希尔港的危险","米奈希尔的威胁"}}},fp="15,423,17.314.0,28.539.0,46.292.0,26.258.0,31.175.0,44.285.0"}
P.entries["subzone:menethil-keep"] = {n="米奈希尔城堡",s="米奈希尔城堡是矗立在湿地米奈希尔港天际线上的石质要塞。它以四座坚固的瞭望塔为标志，是这座联盟港口的行政中心和防御堡垒，当地民兵指挥官斯托菲队长就在此坐镇。",h="米奈希尔城堡是矗立在湿地米奈希尔港天际线上的石质要塞。它以四座坚固的瞭望塔为标志，是这座联盟港口的行政中心和防御堡垒，当地民兵指挥官斯托菲队长就在此坐镇。",kw={"斯托菲队长","米奈希尔港","米奈希尔城堡","民兵","塔楼","湿地"},ang={["faction:Alliance"]="对于乘坐船只从卡利姆多抵达，或向北前往铁炉堡和阿拉希的联盟旅行者来说，米奈希尔城堡是确保这一重要交通枢纽安全的主要军事要塞。"},sec={{t="港口堡垒",b="米奈希尔城堡高耸于湿地的木制码头和泥泞沼泽之上，是米奈希尔港的核心军事据点。凭借四座俯瞰全镇与海湾的石质瞭望塔，这座要塞拥有绝佳的视野，可以抵御海上的掠夺者、叛军以及不断侵蚀周边的沼泽野兽。在城堡内部，斯托菲队长负责监管港口的防御工作，指挥城镇民兵并组织巡逻队，以保卫联盟在该地区的利益。"}},faq={{q="米奈希尔城堡有什么用？",a="米奈希尔城堡是米奈希尔港城镇民兵的总部，也是联盟在湿地的主要指挥哨所。斯托菲队长在这座石墙内指挥当地驻军，负责调度防御工作并组织冒险者解决遍布沼泽的威胁。",al={"米奈希尔城堡的用途","米奈希尔城堡的作用","这座城堡是什么"}},{q="谁负责管理米奈希尔城堡？",a="斯托菲队长指挥着这座城堡和米奈希尔民兵。他负责协调港口防御，以应对黑铁矮人掠夺者、沼泽野兽和海盗等当地威胁。",al={"谁领导米奈希尔城堡","城堡指挥官","斯托菲队长"}},{q="城堡位于哪里？",a="这座城堡坐落在湿地西海岸的米奈希尔港内，地理位置十分显眼，四座高耸的石塔直接俯瞰着整个定居点。",al={"米奈希尔城堡在哪里","米奈希尔城堡的位置","如何找到米奈希尔城堡"}}},fx={["12a246c3"]={q="米奈希尔城堡是什么地方？",a="米奈希尔城堡是坐落于湿地、俯瞰米奈希尔港的石砌要塞。四座高塔耸立在港口城镇上方，如同严厉的守卫，俯视着码头和周围的沼泽。它是联盟驻军在该地区的主要军事堡垒和避难所。",al={"米奈希尔城堡是什么地方","米奈希尔城堡信息","关于米奈希尔城堡"}},["6cd22f9e"]={q="米奈希尔城堡危险吗？",a="在城墙之内，米奈希尔城堡对联盟成员而言绝对安全，斯托菲队长和当地民兵驻守于此。真正的危险就在城堡外湿地的迷雾泥沼中，那里有鱼人、黑铁矮人和凶猛野兽威胁着旅人。",al={"米奈希尔城堡安全吗","米奈希尔城堡的危险","米奈希尔城堡的威胁"}}},fp="13,269,21.473.0,31.297.0,34.184.0,26.160.0"}
P.entries["subzone:merchant-coast"] = {n="商旅海岸",s="商旅海岸是贫瘠之地东部海岸线的一段，毗邻无尽之海。这里由繁忙的地精港口棘齿城占据，海岸因其繁荣的海洋贸易而得名，尽管它一直受到海盗的骚扰。",h="商旅海岸是贫瘠之地东部海岸线的一段，毗邻无尽之海。这里由繁忙的地精港口棘齿城占据，海岸因其繁荣的海洋贸易而得名，尽管它一直受到海盗的骚扰。",kw={"贫瘠之地","无尽之海","商旅海岸","棘齿城","南海海盗","热砂港"},ang={["faction:Alliance"]="联盟在附近的北方城堡保持着海军存在，密切监视着通过棘齿城的地精贸易以及沿岸横行霸道的南海海盗。",["faction:Horde"]="商旅海岸是部落在贫瘠之地通往海洋的主要商业生命线，因此保障棘齿城的安全和压制当地海盗对于地区补给线至关重要。"},sec={{t="商业与冲突的门户",b="商旅海岸沿贫瘠之地的东部边缘延伸，是连接卡利姆多中部与东部王国及塞拉摩的重要海上动脉。其名称是为了纪念热砂港勤劳的地精商人，他们建立的中立港口棘齿城为所有付得起金币的人提供货运服务。然而，广阔的海路吸引的不只是商船：南海海盗在沙滩和附近水域徘徊，掠夺商船并在沿岸建立非法营地。"}},faq={{q="为什么这里被称为商旅海岸？",a="这条海岸线因通过地精港口棘齿城进行的利润丰厚的贸易而得名。热砂港的商人将货物从这片海岸通过无尽之海运往艾泽拉斯各地的港口。",al={"商旅海岸名称由来","为什么叫商旅海岸"}},{q="商旅海岸有哪些主要定居点？",a="最显著的定居点是棘齿城，这是一座由加兹鲁维管理的中立地精港口城市。在海岸线更南端坐落着联盟的要塞北方城堡，而勇士岛则位于离岸不远处。",al={"商旅海岸上的城镇","商旅海岸有什么"}},{q="是谁在控制这一带的沙滩？",a="虽然棘齿城控制着港口本身，但南海海盗在周围的沙滩上建立了营地。这些海盗积极干扰贸易、抢劫地精车队，并挑战棘齿城的权威。",al={"商旅海岸的海盗","谁在攻击商旅海岸"}}},fx={bb3cbd28={q="商旅海岸是什么地方？",a="商旅海岸是贫瘠之地干旱地带与无尽之海交汇处的一段东部海岸线。北面是繁忙的地精港口棘齿城，南面则是高耸的北方城堡城墙。这片海岸是重要的海上贸易通道，连接着卡利姆多中部与东部王国。",al={"商旅海岸是什么地方","商旅海岸概况","贫瘠之地海岸"}},c3eb7a38={q="商旅海岸危险吗？",a="棘齿城港口维持着戒备森严的中立，但周边海岸危机四伏。地精码头以南的海滩遍布南海海盗——这些残暴的海盗会袭击过往船只，并打捞沉船残骸。继续向南，你便会来到北方城堡的阴影下，塞拉摩士兵正严密守卫着他们的驻地。",al={"商旅海岸的危险","这里安全吗","商旅海岸的威胁"}}},fp="14,248,35.506.0,36.200.0,49.201.0,37.222.0"}
P.entries["subzone:military-ward"] = {n="Military Ward",s="Military Ward是铁炉堡的军事核心，驻扎着城市的指挥机构、武器大师和兵营。这里悬挂着醒目的红色旗帜，矮人战士、猎人和攻城工程师与机械攻城车和飞行器一同在此进行训练。",h="Military Ward是铁炉堡的军事核心，驻扎着城市的指挥机构、武器大师和兵营。这里悬挂着醒目的红色旗帜，矮人战士、猎人和攻城工程师与机械攻城车和飞行器一同在此进行训练。",kw={"buliwyf stonehand","飞行机器","hall of arms","铁炉堡","military ward","蒸汽坦克","timberline arms"},ang={["class:Hunter"]="游侠和山地卫兵可以在Hall of Arms找到兽王和补给品，旁边还有供应弹药和装备的Goldfury's Hunting Supplies。",["class:Warrior"]="Military Ward是铁炉堡主要的军事枢纽，提供战士训练师、用于实战练习的训练假人以及武器大师，以扩充你的战场武器库。"},sec={{t="矮人力量之砧",b="Military Ward坐落在山中要塞的北侧，将铁炉堡的防御力量集中在一个繁忙的集结地。中央建筑Hall of Arms容纳了战士和猎人训练师、战场军官，以及存放矮人飞行器和蒸汽坦克的机库。在演武场和训练假人周围，分布着如Craghelm's Plate and Chain、Goldfury's Hunting Supplies和Timberline Arms等补给商店，使这里成为了山地卫兵和城市守卫的主要集结点。"},{t="战旗之下的驻地",b="与公共区的淡蓝色和Great Forge的炽热橙色不同，Military Ward装饰着象征军事的红色旗帜。在操练和武器检查的间隙，士兵和下班的卫兵会聚集在Bruuk's Corner喝上一杯麦芽酒，而武器大师Buliwyf Stonehand则在向新兵传授古老的矮人武技。"}},faq={{q="Military Ward是什么地方？",a="它是铁炉堡的军事区，作为矮人军队、战士和猎人训练师、武器商人和攻城器械的中央基地。",al={"military ward ironforge","铁炉堡兵营","铁炉堡战士区"}},{q="我在铁炉堡哪里可以进行武器训练？",a="武器大师Buliwyf Stonehand驻扎在Military Ward的Timberline Arms，为联盟战士提供各种武器的训练。",al={"铁炉堡武器大师","buliwyf stonehand在哪里","学习武器铁炉堡"}},{q="Hall of Arms里存放着什么？",a="Hall of Arms作为军事指挥部，驻有战斗导师、战场军官，并设有存放蒸汽坦克和矮人飞行机的大型机库。",al={"hall of arms ironforge","hall of arms里有什么","铁炉堡攻城坦克"}},{q="为什么这个区的旗帜是红色的？",a="铁炉堡的各个区域使用特定的纹章颜色以用于导航和传统；Military Ward悬挂着醒目的红色旗帜，代表了这座山中之城的军事力量。",al={"military ward颜色","红色旗帜铁炉堡"}}},fx={f3d6c901={q="军事区危险吗？",a="对你或任何联盟盟友来说，这里都不危险。军事区是整个山地王国中设防最严密、最安全的区域之一。这里是铁炉堡武装力量的主要驻地和集结地，聚集着经验丰富的战士、战斗大师以及正在服役的蒸汽坦克。除非敌军攻破山门，否则这里始终完全由矮人军方掌控。",al={"军事区安全吗","军事区的危险"}},ba2db6a3={q="为什么叫军事区？",a="这片区域因其作为铁炉堡常备军指挥中心和总部的职责而得名。这里的一切都服务于战争，从武器大厅和武器商店，到储备补给的前哨站，以及停放着攻城器械和旋翼机的车辆库。",al={"军事区名称由来","军事区为何得名","军事区名称的由来"}}},fp="13,282,26.548.0,31.342.0,26.158.0,42.150.0,37.166.0,41.179.0"}
P.entries["subzone:mirage-flats"] = {n="雾气平原",s="雾气平原是位于荒芜之地中部荒原的一片贫瘠、被烈日灼烧的广阔地带。这片干燥的高原位于火山洞穴以东，因其闪烁的热浪和饥饿的捕食者而臭名昭著。",h="雾气平原是位于荒芜之地中部荒原的一片贫瘠、被烈日灼烧的广阔地带。这片干燥的高原位于火山洞穴以东，因其闪烁的热浪和饥饿的捕食者而臭名昭著。",kw={"荒芜之地","岩石郊狼","龙喉","火山洞穴","巨型秃鹫","雾气平原","山脊潜伏者"},ang={["class:Hunter"]="雾气平原开阔的平原提供了大量可供追踪、研究或驯服的攻击性野兽，特别是那些凶猛的山脊潜伏者和久经沙漠生存考验的强韧郊狼。"},sec={{t="焦灼的荒原",b="雾气平原位于火山洞穴以东，这片土地向旅人们展现着一片无情的、布满裂纹的红土地，以及使其得名的闪烁热浪。很少有文明种族在此驻足；相反，这片开阔的平原被伺机而动的食腐动物和致命的野兽所占据。成群的巨型秃鹫在热气流中懒散地盘旋，俯视着下方。它们在等待着凶猛的山脊潜伏者和成群结队的岩石郊狼留下的残羹剩饭，这些野兽在灌木丛中搜寻着易得的猎物。"}},faq={{q="雾气平原位于哪里？",a="平原位于荒芜之地中部，在火山洞穴以东。往返于西部悬崖和东部峡谷之间的旅行者经常会穿过这片被太阳炙烤的土地。",al={"雾气平原位置","雾气平原在哪里","雾气平原地图"}},{q="为什么这个地区叫雾气平原？",a="这个名字来源于刺眼的沙漠烈日和从平坦的岩石地面辐射出的压抑热浪，这些热浪制造了持久的视觉错觉和热晕，常常使口渴的旅行者在荒原中迷失方向。",al={"为什么叫雾气平原","雾气平原名字含义","荒芜之地热浪"}},{q="什么生物在平原上出没？",a="该地区居住着适应了严酷荒地的强韧捕食者和食腐动物。成群结队的狂犬岩石郊狼和游荡的山脊潜伏者首领在灌木丛中捕猎，而巨型秃鹫则在头顶盘旋，等待着享用任何倒在尘土中的猎物。",al={"雾气平原怪物","雾气平原有什么生物","雾气平原野兽"}}},fp="12,203,20.473.0,35.189.0,36.216.0,31.268.0"}
P.entries["subzone:mirage-raceway"] = {n="沙漠赛道",s="沙漠赛道是一处位于千针石林闪光平原上的临时工程试验场。它的诞生源于地精技师普兹克和侏儒工程师菲兹尔·铜栓之间激烈的竞争，两人的高速火箭车在干涸的土地上进行着较量。这条赛道是一个中立的聚集地，联盟和部落的成员都可以在此下注、修理机械并为他们支持的赛车加油助威。",h="沙漠赛道是一处位于千针石林闪光平原上的临时工程试验场。它的诞生源于地精技师普兹克和侏儒工程师菲兹尔·铜栓之间激烈的竞争，两人的高速火箭车在干涸的土地上进行着较量。这条赛道是一个中立的聚集地，联盟和部落的成员都可以在此下注...",kw={"菲兹尔·铜栓","沙漠赛道","普兹克","火箭车","闪光平原","千针石林"},ang={["profession:Engineering"]="对于任何阵营的技师来说，沙漠赛道代表了地精冒险精神与侏儒严谨设计之间的终极碰撞，为测试纯粹的速度、不稳定的燃料和实验性车辆部件提供了实地演练的机会。",["race:Gnome"]="菲兹尔·铜栓在此高举诺莫瑞根的旗帜，依靠同族侏儒和盟友来证明，严谨的创新可以轻松胜过鲁莽的地精燃烧技术。"},sec={{t="速度、盐地与较量",b="沙漠赛道横跨闪光平原广袤的白色荒漠，它源于两位工程大师之间旷日持久的怨恨：地精普兹克和侏儒菲兹尔·铜栓。为了彻底分出到底哪个种族拥有更卓越的工程天赋，两人制造了定制的火箭动力加速车，并招募了各自的车队，每天进行高速对决。无休止的竞争将这片荒芜的平原变成了一个充满了发明、破坏与测试的热闹中心，每一个车队都在拼命寻找任何机械上的优势。"},{t="中立的十字路口",b="这条赛道吸引了来自部落和联盟的支持者。来自卡利姆多的观众聚集在此，要么为侏儒的精密机械喝彩，要么为地精的强大火力欢呼，而赌徒和投机分子则在各种下注中获利。在火箭引擎的轰鸣声之外，这些营地也是往来于千针石林和塔纳利斯炽热沙地之间的旅行者们进行贸易的繁忙中转站。"}},faq={{q="什么是沙漠赛道？",a="沙漠赛道是一条横跨千针石林盐碱地的露天火箭车赛道。它由相互竞争的工程师建造，旨在证明地精机械和侏儒机械究竟孰优孰劣。",al={"什么是沙漠赛道","赛道目的","闪光平原赛道"}},{q="这里是谁在组织比赛？",a="这条赛道由侏儒工程师菲兹尔·铜栓和地精技师普兹克共同维护。双方都在赛道旁经营着各自的专属车队和车间，以派遣参赛的火箭车。",al={"谁领导赛道","菲兹尔与普兹克","谁建造了这条赛道"}},{q="部落和联盟都能使用这个区域吗？",a="是的。来自两个阵营的支持者都会聚集在赛道旁为他们喜爱的赛车加油、投注，并协助竞争对手的工程团队。",al={"沙漠赛道是中立的吗","联盟可以访问吗","部落可以访问吗"}},{q="为什么要在盐碱地上赛车？",a="闪光平原平坦宽阔，为需要数英里距离来达到最高时速并安全减速的火箭动力车辆提供了理想的平滑、无障碍的场地。",al={"为什么在千针石林","为什么在盐地上赛车","为什么在闪光平原"}}},fx={df07332a={q="沙漠赛道的历史是什么？",a="赛道源于地精普兹克与侏儒菲兹尔·铜栓之间激烈的技术竞争。两人决心证明各自种族的工程技术更胜一筹，于是建造了高速火箭赛车，并组建了专属车队。随着时间推移，这场私人较量演变成有组织的赛事，吸引了联盟和部落各地的观众与地下赌徒，每天前来观看两方赛车在盐地上激烈角逐。",al={"沙漠赛道的历史","沙漠赛道如何建立","沙漠赛道的起源"}},["2d853a10"]={q="沙漠赛道危险吗？",a="沙漠赛道吸引着联盟和部落的支持者前来下注和观看比赛。不过，赛车本身是性能不稳定的实验性机械，容易发生灾难性的故障。此外，越过赛营外围，你就会进入蛮荒的闪光平原，那里到处都是具有攻击性的石化蜥蜴、蝎子和敌对的拾荒者。",al={"沙漠赛道安全吗","沙漠赛道的危险","沙漠赛道的威胁"}}},fp="14,445,24.616.0,20.409.0,27.200.0,24.197.0,42.139.0,31.191.0"}
P.entries["subzone:mirkfallon-lake"] = {n="暗色湖",s="暗色湖位于石爪山脉中央的一处高地盆地中，坐落在狂风峭壁的险峻悬崖之下。湖水及其周边岸边充斥着各种原生生物，包括极具攻击性的软泥怪、游荡的雷霆蜥蜴以及盘旋的翼龙。",h="暗色湖位于石爪山脉中央的一处高地盆地中，坐落在狂风峭壁的险峻悬崖之下。湖水及其周边岸边充斥着各种原生生物，包括极具攻击性的软泥怪、游荡的雷霆蜥蜴以及盘旋的翼龙。",kw={"暗色湖","石爪山脉湖泊","石爪山脉雷霆蜥蜴","狂风峭壁湖泊"},ang={["class:Druid"]="暗色湖周围的野生兽群代表了石爪山脉荒野中脆弱的平衡，而上方峭壁中不断侵入的机械伐木机正让这一切变得岌岌可危。"},sec={{t="高地盆地",b="暗色湖位于石爪山脉的地理中心，坐落在通往南边蛛网小径和北边石爪峰的山路之间。得益于高地的径流补给，这座湖泊成为了群山峻岭中一片肥沃的绿洲，吸引着雷霆蜥蜴前来饮水，也将翼龙从高处的巢穴引向此处。湖中还栖息着奇特的、不断冒泡的软泥怪，使得这片宁静的高山湖泊成为了独行旅客眼中的危险之地。"},{t="峭壁十字路口",b="湖泊盆地四通八达。向东，岩石小径蜿蜒而上，直通狂风峭壁以及深入森林峡谷的伐木作业区。向北经过湖泊的旅行者会攀向暗夜精灵的圣所和牛头人的高地，而向南绕行的旅行者则必须应对毒蛛遍布的洞穴。因此，暗色湖的湖岸往往成为探险家和斥候穿越这片纷争山脉时一个充满变数的交汇点。"}},faq={{q="暗色湖周围生活着哪些生物？",a="湖泊及其岸边栖息着游荡的雷霆蜥蜴、浅水区有害的软泥怪，以及在周围盆地狩猎并在上方高处筑巢的山地翼龙。",al={"暗色湖野兽","暗色湖野生动物","暗色湖有什么"}},{q="湖泊通向哪里？",a="向北攀爬可通往石爪峰。向南下行会穿过蛛网小径，而向东的岩石坡路则蜿蜒通向狂风峭壁。",al={"暗色湖路径","暗色湖通向哪里","暗色湖方向"}},{q="在暗色湖钓鱼安全吗？",a="湖中盛产鼠尾鱼和漂浮的残骸，这让垂钓者十分心动。然而，软泥怪和翼龙等具有攻击性的野兽经常出没于湖岸，这使得在此安静垂钓变得十分困难。",al={"暗色湖钓鱼","能在暗色湖钓鱼吗"}}},fx={["402ec74a"]={q="暗色湖是什么地方？",a="暗色湖是石爪山脉中部附近一片醒目的水域。它坐落在峭壁与山道之间，这些山道连接着石爪峰和周围的山峰。湖泊是这片崎岖土地腹地的一处野外水源和盆地。",al={"暗色湖是什么地方","暗色湖概况","暗色湖背景"}},a8300c3c={q="暗色湖危险吗？",a="是的，旅人应保持警惕。湖泊及其岸边栖息着具有攻击性的野生动物，包括四处游荡的雷霆蜥蜴、在浅滩爬行的污秽软泥怪，以及在周围高处筑巢、随后俯冲捕猎的野生双足飞龙。",al={"暗色湖安全吗","暗色湖的危险","暗色湖的怪物"}}},fp="15,267,16.492.0,22.484.0,43.200.0,25.156.0,35.200.0"}
P.entries["subzone:mirror-lake"] = {n="明镜湖",s="明镜湖是位于艾尔文森林西北部果园旁的一处风景如画的水域。它由暴风城悬崖下的一道柔和瀑布汇聚而成，其平静的水面之下却潜藏着岸边的危险，从四处游荡的迪菲亚潜行者到当地魔网线中奇怪的干扰，无所不包。",h="明镜湖是位于艾尔文森林西北部果园旁的一处风景如画的水域。它由暴风城悬崖下的一道柔和瀑布汇聚而成，其平静的水面之下却潜藏着岸边的危险，从四处游荡的迪菲亚潜行者到当地魔网线中奇怪的干扰，无所不包。",kw={"迪菲亚","艾尔文森林","明镜湖","暴风城","瀑布","法师区"},ang={["class:Mage"]="在暴风城法师区学习的初学者们被派往此处收集水样，亲身学习动荡的奥术通道是如何渗入自然生态系统的。",["faction:Alliance"]="尽管离首都高耸的城墙很近，但这片湖泊却提醒着人们，王国守卫在面对迪菲亚不法之徒时显得多么捉襟见肘。"},sec={{t="不安的田园",b="明镜湖坐落在暴风城高耸的城墙之下，本应是渔夫和疲惫旅人的宁静休憩之所。然而，迪菲亚潜行者的强盗们却在周围的果园中潜行，使得任何在此停留过久的当地人都面临危险。更糟糕的是，艾泽拉斯各地发生的神秘干扰已经开始扭曲整个森林中奥术能量的自然流向。法师区的法师们正密切注视着这片湖泊，派遣修行者取样其水流，以确保下游社区不会受到混乱奥术外溢的毒害。"}},faq={{q="明镜湖为什么危险？",a="尽管风景优美，但湖泊周边区域有大量迪菲亚强盗出没，他们以路人和农夫为目标。此外，近期区域魔法的波动也引发了人们对湖水安全性的担忧。",al={"明镜湖安全吗","明镜湖的敌人","明镜湖的迪菲亚"}},{q="为什么法师要研究明镜湖？",a="艾泽拉斯各地的大规模魔法冲突破坏了整个艾尔文森林和暴风城的魔网流向。法师区派遣初学者对湖水进行采样，检测是否存在不稳定的奥术残余，以免其影响饮用湖水的人们。",al={"法师区与明镜湖","明镜湖任务","明镜湖的魔法"}},{q="明镜湖的瀑布从哪里来？",a="瀑布从环绕暴风城外围的高耸悬崖和水道倾泻而下，汇入湖泊，随后水流蜿蜒流经艾尔文森林的河流系统。",al={"明镜湖瀑布","明镜湖水源"}}},fx={["80ec8f44"]={q="明镜湖是什么地方？",a="明镜湖是艾尔文森林西部一处风景秀丽的小湖，坐落在一座果园附近。湖水源自一条湍急的瀑布，瀑布从暴风城下方的山间倾泻而下。若不是迪菲亚潜行者目前控制着湖岸，这里本会是钓鱼和游泳的清静之所。",al={"艾尔文的明镜湖","明镜湖是什么地方","关于明镜湖"}},e8bd98e7={q="谁控制着明镜湖？",a="迪菲亚潜行者目前占据着这座湖泊。这些亡命之徒在湖岸和周围的果园里游荡，赶走当地渔民和旅人，并将这片偏僻隐蔽的水域用作基地，就在暴风城城墙之外。",al={"谁住在明镜湖","明镜湖的匪徒","谁控制着明镜湖"}}},fp="11,296,15.590.0,29.236.0,35.262.0,50.177.0"}
P.entries["subzone:mirror-lake-orchard"] = {n="明镜湖果园",s="明镜湖果园是位于艾尔文森林西部、明镜湖南岸的一处安静的树林和农舍。这里曾是雷霆瀑布附近的一处宁静家园，如今却落入了迪菲亚潜行者的手中。在暴风城的卫兵无暇顾及之时，他们正在此处肆意劫掠乡间。",h="明镜湖果园是位于艾尔文森林西部、明镜湖南岸的一处安静的树林和农舍。这里曾是雷霆瀑布附近的一处宁静家园，如今却落入了迪菲亚潜行者的手中。在暴风城的卫兵无暇顾及之时，他们正在此处肆意劫掠乡间。",kw={"迪菲亚潜行者","艾尔文森林","明镜湖","明镜湖果园","暴风城强盗","雷霆瀑布"},ang={["class:Rogue"]="这座果园展示了典型的迪菲亚战略：夺取水边和悬崖旁易守难攻且被忽视的房产，以便在监视道路的同时躲避城市巡逻队的搜查。",["faction:Alliance"]="对于联盟的旅行者来说，这座被占领的果园是迪菲亚潜行者在王国腹地大胆扩张的又一个苦涩证明。"},sec={{t="被占据的果园",b="明镜湖果园隐匿于雷霆瀑布的奔流附近，曾是一处得益于明镜湖清澈水源的富饶农庄。如今，这座宁静的农舍已被那些打着迪菲亚潜行者旗号的投机窃贼和强盗所侵占。随着王国的军队兵力吃紧，且瓦里安·乌瑞恩国王失踪，像这样的乡村产业已成为那些试图在艾尔文森林乡间寻找藏身处的歹徒眼中的软柿子。"}},faq={{q="现在是谁控制着明镜湖果园？",a="目前迪菲亚潜行者占据了明镜湖果园及其附属的农舍。他们赶走了曾经照料果树的诚实平民，现在将这片隐蔽的场地当作他们在艾尔文森林西部的据点。",al={"谁在明镜湖果园","谁住在这里","果园敌人"}},{q="明镜湖果园在哪里？",a="果园坐落在艾尔文森林西部的明镜湖南岸，位于雷霆瀑布正东方，通往西部荒野的主路以北。",al={"明镜湖果园位置","果园在哪里","查找艾尔文森林果园"}},{q="为什么暴风城没有收复果园？",a="由于政治僵局和瓦里安·乌瑞恩国王的神秘失踪，暴风城的正规军大多不在艾尔文森林的乡村地区驻扎。由于当地驻军人手不足，偏远的农庄和果园常常不得不独自面对迪菲亚潜行者的侵扰。",al={"为什么迪菲亚在这里","卫兵在哪里"}},{q="果园和雷霆瀑布有什么联系？",a="明镜湖的水流直接注入雷霆瀑布，这使得果园刚好位于咆哮的瀑布之上。它靠近悬崖的隐蔽位置使其成为强盗们理想且易于防守的据点。",al={"雷霆瀑布的联系","果园和瀑布"}}},fx={["9fb3552d"]={q="明镜湖果园是什么地方？",a="明镜湖果园是一座宁静的小农场，坐落在艾尔文森林西部明镜湖的南岸。这里曾是一片果树园，旁边还有一间小屋，如今却和周围大部分乡野一样陷入了混乱。",al={"这是什么地方","明镜湖果园背景","关于明镜湖果园"}},fc4dc36b={q="明镜湖果园发生了什么？",a="随着艾尔文森林各地动荡蔓延，曾经照料这些树木的平静农夫被赶走，或是自行离开了家园。迪菲亚潜行者的亡命徒趁机占据此地，将被遗弃的小屋和果园变成了又一个隐蔽的行动据点。",al={"明镜湖果园的历史","这里发生了什么","果园背景"}},d58df7ba={q="明镜湖果园为什么被遗弃？",a="暴风城分身乏术，当地卫兵也疲于应付，艾尔文各地的乡间农庄因此成了流窜匪徒的首要目标。果园被逼近的迪菲亚匪徒占据，他们将小屋和土地据为己有。",al={"果园为什么被遗弃","农夫为何离开","谁遗弃了果园"}},["90c4a3ea"]={q="明镜湖果园危险吗？",a="是的。这里目前遍布敌对的迪菲亚匪徒，他们在树林中巡逻，并占据了附近的房屋。任何未加防备地穿行林间的人，都有可能当场遭到伏击。",al={"这里安全吗","明镜湖果园的危险","明镜湖果园的敌人"}},["626e53a6"]={q="为什么叫明镜湖果园？",a="果园因其位置而得名：它坐落在明镜湖的南岸，果树就种在平静如镜的湖水旁。",al={"明镜湖果园为何得名","明镜湖果园名称含义","果园名称的由来"}}},fp="19,281,21.494.0,43.208.0,37.161.0,43.283.0,61.185.0"}
P.entries["subzone:mist-s-edge"] = {n="薄雾海",s="薄雾海是沿着黑海岸西岸从奥伯丁向北延伸的一条漫长而多风的海岸线。在这片被潮湿的海雾笼罩的灰色沙滩上，散落着沉船残骸、巨大的海洋生物遗骸，以及成群游荡的螃蟹和鱼人。",h="薄雾海是沿着黑海岸西岸从奥伯丁向北延伸的一条漫长而多风的海岸线。在这片被潮湿的海雾笼罩的灰色沙滩上，散落着沉船残骸、巨大的海洋生物遗骸，以及成群游荡的螃蟹和鱼人。",kw={"奥伯丁","沙滩","海岸","螃蟹","黑海岸","薄雾海","鱼人","沉船"},ang={["race:NightElf"]="对于奥伯丁的暗夜精灵来说，薄雾海既是一个重要的海上边界，也是一个遭受鱼人入侵和卑劣食腐者困扰的未驯化边境。"},sec={{t="迷雾笼罩的海岸",b="薄雾海位于黑海岸的西缘，以潮湿的沙滩、岩石潮池和终年不断的沿海迷雾为特征。这片海滩是一座海洋坟场，布满了腐烂的海洋巨兽残骸、漂流木以及破碎的船只龙骨。虽然看起来荒凉，但海岸线上遍布着岸边食腐生物，尤其是极具攻击性的螃蟹和在浪花中筑巢的领地意识极强的鱼人部落。"},{t="沉船与食腐者",b="黑海岸附近危险的水域吞噬了无数船只，将破碎的船体和丢弃的货物堆满了沙滩。暗夜精灵哨兵和当地的食腐者对这条海岸线保持着警惕，投机取巧的鱼人营地经常威胁着那些沿着海岸往返于奥伯丁的旅人。"}},faq={{q="什么是薄雾海？",a="薄雾海是沿着黑海岸西岸从奥伯丁向北延伸的一片广阔海岸线，以寒冷的海雾、沉船残骸和搁浅的海洋生物而闻名。",al={"薄雾海","黑海岸沙滩","什么是薄雾海"}},{q="什么威胁在这片海岸徘徊？",a="海岸线上居住着大量的敌对沿海螃蟹和好战的鱼人族群，它们在水边建立原始的营地。",al={"薄雾海怪物","沙滩上的袭击者","黑海岸沿岸危险"}},{q="为什么这里有这么多沉船和骨骸？",a="黑海岸附近险恶的洋流、暗礁和浓雾使得航行充满危险，导致船只触礁。同样，洋流也经常将巨大的利维坦和海洋生物的残骸冲上岸。",al={"黑海岸搁浅鲸鱼","薄雾海沉船","黑海岸巨型骨骸"}}},fx={e5f03abb={q="薄雾海危险吗？",a="是的，旅人沿着这片荒凉的沙滩行进时必须保持警惕。海岸上到处都是具有攻击性的海蟹，成群结队的鱼人则沿水边扎营，并袭击任何闯入它们捕鱼地盘的人。四处游荡、以搁浅海兽尸体为食的拾荒者，加上潜伏的鱼人，独自在海岸徘徊始终危机重重。",al={"薄雾海安全吗","薄雾海的危险","薄雾海有多危险"}}},fp="11,248,20.407.0,21.337.0,20.187.0,31.141.0,52.216.0"}
P.entries["subzone:misty-pine-refuge"] = {n="雾松避难所",s="雾松避难所是银色黎明在丹莫罗中部冰天雪地中建立的一处小型哨所。",h="雾松避难所是银色黎明在丹莫罗中部冰天雪地中建立的一处小型哨所。",kw={"银色黎明","丹莫罗","加文神父","雾松避难所"},ang={["class:Priest"]="加文神父那简朴的哨所证明了圣光的侍奉往往在于远离战场、默默的警惕之中。"},sec={{t="雪中庇护所",b="雾松避难所坐落在丹莫罗风雪肆虐的山丘之间，是银色黎明在矮人领地内一处毫不起眼的哨所。尽管周遭的岩壁有铁炉堡的登山者巡逻，但这座避难所仍是加文神父（银色黎明在此地的唯一特工）的驻地，在严酷的天气和威胁着山路的危险面前，他为路人提供了一处宁静的炉火。"}},faq={{q="雾松避难所是什么地方？",a="它是银色黎明在丹莫罗中部的一处哨所，由该组织的一名特工，加文神父负责看守。",al={"这是什么地方","雾松","雾松避难所概览"}},{q="银色黎明为什么会出现在丹莫罗？",a="虽然银色黎明的重点主要在于北方的不死族威胁，但像加文神父这样的特工也在联盟领地的僻静角落进行着监视。",al={"为什么银色黎明在这里","加文神父银色黎明","银色黎明矮人领地"}},{q="谁待在避难所里？",a="银色黎明特工加文神父是该组织驻扎在避难所的唯一成员。",al={"雾松避难所里有什么人","雾松避难所npc"}}},fx={f4fbb46a={q="雾松避难所危险吗？",a="不，避难所本身是丹莫罗寒冷荒野中的安全港湾。这里是银色黎明的前哨站，由加文神父悉心看守；不过，周围的雪野依然有野兽和穴居人出没，危险如常。",al={"雾松避难所安全吗","雾松避难所的危险","雾松避难所的威胁"}}},fp="17,118,19.366.0,26.118.0,42.164.0,24.99.0"}
P.entries["subzone:misty-reed-post"] = {n="芦苇哨岗",s="芦苇哨岗是一个粗犷的部落营地，位于悲伤沼泽东部的雄鹿沼泽和芦苇海滩之间。它作为斯通纳德管辖下的前哨阵地而建立，旨在监视这片危险的湿地和凶险的海岸线。",h="芦苇哨岗是一个粗犷的部落营地，位于悲伤沼泽东部的雄鹿沼泽和芦苇海滩之间。它作为斯通纳德管辖下的前哨阵地而建立，旨在监视这片危险的湿地和凶险的海岸线。",kw={"卡塔尔","芦苇哨岗","芦苇海滩","雄鹿沼泽","斯通纳德","悲伤沼泽","托克卡尔"},ang={["class:Hunter"]="这里主要由熟悉周边沼泽生态的斯通纳德猎人驻守，代表了在充满敌意的湿地掠食者中追踪与生存所需的坚韧。",["faction:Horde"]="对于在沼泽危险的东部边缘航行的部落斥候来说，该营地提供了一个受欢迎的安全避风港和当地向导。"},sec={{t="孤寂的前哨",b="芦苇哨岗掩映在雄鹿沼泽与东海岸之间潮湿阴郁的环境中，不过是一个斯通纳德旗下的简陋营地。驻守在此的有几名斯通纳德猎人、一名萨满祭司卡塔尔，以及负责监管该哨岗的托克卡尔。这里的环境十分恶劣，没有坚固的掩体来抵御沼泽中充满敌意的野生生物和长久不散的潮气。托克卡尔怀揣着一个安静的愿望，希望斯通纳德的部落指挥部终有一天能用坚固的兽人地洞或瞭望塔来加强这一阵地，但就目前而言，斥候们必须依靠帐篷、篝火烟雾和锋利的钢铁来守住这片沼泽。"}},faq={{q="芦苇哨岗的目的是什么？",a="它作为斯通纳德部落驻军的次要前哨营地。它位于雄鹿沼泽的湿地和芦苇海滩的海岸之间，哨兵们负责监视海岸威胁和沼泽原生野兽。",al={"为什么芦苇哨岗在这里","芦苇哨岗的目的","这个营地是什么"}},{q="这里由谁负责？",a="该哨岗由托克卡尔领导，这是一名兽人，他的任务是与斯通纳德萨满祭司卡塔尔以及几名斯通纳德猎人一起守住这个脆弱的营地。托克卡尔希望该定居点最终能获得建造永久防御工事的资源。",al={"谁领导芦苇哨岗","托克卡尔"}},{q="芦苇哨岗有飞行管理员吗？",a="没有。芦苇哨岗是一个简朴的野战营地，没有双足飞龙设施。需要飞行航线的旅行者必须沿着道路向西前往斯通纳德。",al={"芦苇哨岗飞行航线","这里有飞行航线吗","芦苇哨岗飞行管理员"}}},fp="15,285,16.597.0,39.226.0,22.247.0,44.166.0"}
P.entries["subzone:misty-reed-strand"] = {n="芦苇海滩",s="芦苇海滩是悲伤沼泽东部一片雾气笼罩、荒凉的海岸线。这里布满了参差不齐的礁石、冲上岸的残骸和蔓延的沼泽迷雾，是凶猛的螃蟹、鳄鱼人和沿海鱼人部落的家园。前往岸边的旅者常常发现自己必须与当地的野生生物争夺冲上岸的资源。",h="芦苇海滩是悲伤沼泽东部一片雾气笼罩、荒凉的海岸线。这里布满了参差不齐的礁石、冲上岸的残骸和蔓延的沼泽迷雾，是凶猛的螃蟹、鳄鱼人和沿海鱼人部落的家园。前往岸边的旅者常常发现自己必须与当地的野生生物争夺冲上岸的资源。",kw={"海滩","海岸","鳄鱼人","浮木","无尽之海","芦苇海滩","鱼人","悲伤沼泽"},ang={["faction:Alliance"]="从守望堡向南行进或穿越沼泽地的联盟侦察兵经常在海滩上搜集丰富的浮木和资源，同时还要抵御那里凶猛的野生生物。",["faction:Horde"]="斯通纳德的守卫者将海滩上的鱼人部落视为一种失控的威胁，经常命令作战巡逻队去清除它们在岸边的营地。"},sec={{t="雾气弥漫的海岸线",b="芦苇海滩沿着悲伤沼泽的整个东部边界延伸，构成了深层泥沼和无尽之海之间的一道潮湿屏障。浓雾不断从水面上涌来，模糊了视线，也掩盖了当地野生生物的叫声。海滩上散落着海洋碎片、浮木和从内陆沼泽冲出来的腐烂植被。由于其地理位置偏远且气候恶劣，海岸线上没有任何正式的永久定居点，沙滩上尽是好斗的甲壳类生物、潜行的鳄鱼人和暴力捍卫其觅食领地的领土鱼人。"},{t="纷争水域",b="联盟和部落的侦察兵都会定期指引冒险者前往芦苇海滩，尽管没有任何一方宣称这片海滩是其主权领土。联盟经常在这里收集浮木和海滩残骸，同时试图削减横行的蟹群数量。与此同时，内陆的部落哨所时刻警惕着海岸线上的鱼人营地，派遣经验丰富的战士去减少它们的数量，以免这些两栖掠夺者向斯通纳德方向深入或威胁到沼泽地的通行。"}},faq={{q="芦苇海滩位于哪里？",a="芦苇海滩沿着悲伤沼泽的最东端延伸，与无尽之海接壤。从斯通纳德或周围的沼泽小径向东穿过湿地，即可到达这里。",al={"芦苇海滩在哪里","芦苇海滩位置","如何前往芦苇海滩"}},{q="海滩上栖息着哪些生物？",a="海岸线上居住着大量的巨型沿海螃蟹、沼泽鳄鱼人和各种在潮汐线附近搜寻食物的敌对鱼人部落。",al={"芦苇海滩的怪物","芦苇海滩有什么生物","芦苇海滩的敌人"}},{q="海滩上有定居点吗？",a="海滩上没有永久的友好城镇或现成的军事哨所。最近的定居点位于悲伤沼泽的更内陆地区。",al={"芦苇海滩附近的城镇","芦苇海滩基地","芦苇海滩的友好营地"}},{q="为什么双方阵营会派遣冒险者前往芦苇海滩？",a="联盟和部落偶尔都会派遣雇佣兵前往海岸。联盟使者通常会寻找可回收的浮木和沿海材料，而部落军队则会派遣战士去清理生活在岸边的凶猛鱼人部落。",al={"为什么要前往芦苇海滩","芦苇海滩任务"}}},fp="17,365,17.603.0,16.494.0,39.221.0,34.141.0,39.173.0,62.242.0"}
P.entries["subzone:misty-shore"] = {n="雾气湖岸",s="雾气湖岸是奥特兰克山脉的一处静谧湖岸，沿着洛丹米尔湖的东岸延伸。它位于达伦德农场与达拉然周边区域之间，由此处可以开阔地眺望雾气蒙蒙的黎明岛，以及芬里斯城堡那阴森的剪影。",h="雾气湖岸是奥特兰克山脉的一处静谧湖岸，沿着洛丹米尔湖的东岸延伸。它位于达伦德农场与达拉然周边区域之间，由此处可以开阔地眺望雾气蒙蒙的黎明岛，以及芬里斯城堡那阴森的剪影。",kw={"奥特兰克山脉","达伦德农场","黎明岛","芬里斯城堡","洛丹米尔湖","雾气湖岸","乌龟"},ang={["faction:Horde"]="这片雾气蒙蒙的河岸提供了一条自然通道，连接着塔伦米尔附近的被遗忘者控制区和北部的湖岸，使旅客能够避开巡逻队的视线。",["profession:Cooking"]="洛丹米尔湖岸是鳄龟丰富的狩猎场，能为穿行于奥特兰克的厨师提供鲜嫩的肉食。"},sec={{t="雾气笼罩的水岸",b="雾气湖岸沿着洛丹米尔湖延伸，横跨达伦德农场与达拉然之间。湖面上经常漂浮着又厚又湿的雾气，遮蔽了鳄龟和偶尔从附近据点溜达下来的狂热信徒。"},{t="注视湖面",b="从雾气湖岸的岸边，旅客们可以眺望水域对面的黎明岛，以及芬里斯城堡那令人望而生畏的阴影。由于此处横跨洛丹米尔湖，且邻近达拉然和血色十字军控制的区域，沿岸的旅客往往会保持低调，以避免引起不必要的注意。"}},faq={{q="雾气湖岸位于哪里？",a="雾气湖岸位于奥特兰克山脉，沿着洛丹米尔湖的东岸，介于达伦德农场和达拉然外围之间。",al={"雾气湖岸位置","雾气湖岸在哪里","雾气湖岸地图"}},{q="从这里隔水可以看见什么？",a="隔着洛丹米尔湖的水域望去，你可以看到雾气中的黎明岛以及芬里斯城堡那巍峨的轮廓。",al={"水对面有什么","雾气湖岸景观","湖景"}},{q="岸边通常会有什么威胁？",a="湖岸边栖息着鳄龟之类的湖中野兽，但旅客也有可能遭遇血色十字军的狂热信徒，或者从邻近农场和废墟中游荡出来的斥候。",al={"雾气湖岸的危险","雾气湖岸的敌人","雾气湖岸的生物"}}},fx={["140433c1"]={q="雾气湖岸是什么地方？",a="雾气湖岸是奥特兰克山脉中沿洛丹米尔湖东岸延伸的一片静谧海岸，常年笼罩在雾气之中。它大致位于达伦德农场与达拉然外围之间，从这里可以清楚地眺望湖对岸的黎明岛，以及远处的芬里斯城堡塔楼。",al={"雾气湖岸是什么","雾气湖岸介绍","雾气湖岸概况"}},fbe1f33b={q="雾气湖岸危险吗？",a="乍看之下，这里平静安宁，实则绝不安全。水中和岸边满是凶猛的钳嘴龟，旅人还得提防附近巡逻的血色十字军敌对人类。他们会攻击任何被视为受到污染或擅闯领地的人。",al={"雾气湖岸有多危险","雾气湖岸的危险","雾气湖岸安全吗"}}},fp="11,263,24.244.0,17.332.0,33.142.0,44.131.0,49.198.0"}
P.entries["subzone:misty-valley"] = {n="迷雾谷",s="迷雾谷隐藏在悲伤沼泽的西北边缘，是一处被阴影笼罩、终年浓雾弥漫的山谷，位于通往逆风小径的隘口以北。这片幽静的盆地中挤满了原始的沼泽野兽、游荡的沼泽漫步者和纠缠的恐怖怪。在山谷最深处的洞穴中，居住着巨大而恐怖的泥沼之王。",h="迷雾谷隐藏在悲伤沼泽的西北边缘，是一处被阴影笼罩、终年浓雾弥漫的山谷，位于通往逆风小径的隘口以北。这片幽静的盆地中挤满了原始的沼泽野兽、游荡的沼泽漫步者和纠缠的恐怖怪。在山谷最深处的洞穴中，居住着巨大而恐怖的泥沼之王。",kw={"逆风小径","泥沼之王","迷雾谷","悲伤沼泽","沼泽漫步者","纠缠恐怖怪"},ang={["class:Druid"]="栖息在这个幽静山谷中的笨重沼泽漫步者和纠缠恐怖怪，代表了与沼泽原始本性深度交织的沼泽元素的狂野与未驯化的愤怒。"},sec={{t="雾气笼罩的峡谷",b="迷雾谷坐落在将悲伤沼泽与逆风小径隔开的高耸悬崖之下，终年被浓厚的沼泽水汽所笼罩。与东部开阔的湿地不同，这个与世隔绝的小区域内密布着巨大的沼泽元素，包括高耸的沼泽漫步者、古老的沼泽漫步者长者以及蔓延的纠缠恐怖怪。在迷雾峡谷的最深处有一个洞穴，那是泥沼之王的巢穴，它是困扰这片沼泽的最强大的自然威胁之一。"}},faq={{q="迷雾谷位于哪里？",a="迷雾谷位于悲伤沼泽的最西北角，紧邻通往逆风小径的道路以北。",al={"迷雾谷位置","迷雾谷在哪里","悲伤沼泽迷雾谷"}},{q="这里栖息着什么生物？",a="山谷中到处都是巨大的植物元素和沼泽恐怖怪，特别是沼泽漫步者、沼泽漫步者长者以及在浓雾中游荡的纠缠恐怖怪。",al={"迷雾谷怪物","迷雾谷里的生物","迷雾谷的敌人"}},{q="山谷后面的洞穴里有什么？",a="在迷雾谷后方的洞穴深处居住着泥沼之王，这是一个巨大而强大的沼泽元素，统治着这片幽静的山谷。",al={"迷雾谷洞穴","泥沼之王洞穴","谁在迷雾谷洞穴里"}},{q="迷雾谷适合穿行吗？",a="一点也不。游荡在浓雾中的高大沼泽漫步者和纠缠恐怖怪充满敌意且极具侵略性，对于偏离主路不慎闯入的旅行者来说，这里非常危险。",al={"迷雾谷危险吗","迷雾谷等级"}}},fp="12,324,19.487.0,34.145.0,35.171.0,50.151.0,37.187.0"}
P.entries["subzone:mizjah-ruins"] = {n="米扎废墟",s="米扎废墟是坐落在荆棘谷北部的一处古老石制遗迹，位于格罗姆高营地东南方。这些破败的建筑早已被其最初的巨魔建造者所遗弃，现在已被蛮力惊人的莫什奥格食人魔所占据。食人魔以此为据点，对往来于悲伤沼泽的补给车队发动破坏性的伏击。",h="米扎废墟是坐落在荆棘谷北部的一处古老石制遗迹，位于格罗姆高营地东南方。这些破败的建筑早已被其最初的巨魔建造者所遗弃，现在已被蛮力惊人的莫什奥格食人魔所占据。食人魔以此为据点，对往来于悲伤沼泽的补给车队发动破坏性的伏击。",kw={"蛮兵","格罗姆高","米扎","米扎废墟","莫什奥格","斯通纳德","荆棘谷","巫医"},ang={["faction:Horde"]="莫什奥格在米扎的存在直接威胁到了部落的关键后勤，迫使格罗姆高营地派遣战士去保护通往斯通纳德的补给路线。"},sec={{t="食人魔的巢穴",b="和散布在荆棘谷各处的许多古老石制废墟一样，米扎废墟由古拉巴什帝国在现代文明崛起很久之前所建。如今，长满苔藓的拱门和开裂的石板被莫什奥格氏族所占据，其中主要是粗野的蛮兵和粗鄙的巫医。这些食人魔并没有安分守己地待在他们窃取的领地里，而是经常袭击前往斯通纳德部落定居点的补给车队，让这些古老的遗迹成为了格罗姆高指挥官们眼中一根持续作痛、血迹斑斑的肉中刺。"}},faq={{q="谁建造了米扎废墟？",a="和散布在荆棘谷北部的大多数石制建筑一样，米扎废墟最初是由古拉巴什帝国的丛林巨魔所建造的，在经历数世纪的战争与衰败后才被废弃。",al={"谁建造了米扎","米扎起源","米扎巨魔遗迹"}},{q="现在是谁住在米扎废墟？",a="这些废墟目前被莫什奥格食人魔占据，主要是莫什奥格蛮兵和莫什奥格巫医，他们已将这些石制建筑加固，作为当地的营地。",al={"谁住在这里","米扎怪物","莫什奥格营地"}},{q="为什么部落有兴趣清理这些废墟？",a="居住在米扎的莫什奥格食人魔积极猎食部落的补给线，伏击往返于格罗姆高营地和位于悲伤沼泽的斯通纳德前哨站之间的车队。",al={"为什么要杀莫什奥格","格罗姆高防御","斯通纳德补给任务"}}},fp="12,387,14.535.0,27.229.0,34.175.0,50.184.0"}
P.entries["subzone:mo-grosh-stronghold"] = {n="莫格罗什要塞",s="莫格罗什要塞是位于洛克莫丹东北部山丘中一处被食人魔占据的堡垒。这些野蛮的巨人栖息在古老而风化的遗迹之中，对山下的矮人定居点构成了持续不断的威胁。",h="莫格罗什要塞是位于洛克莫丹东北部山丘中一处被食人魔占据的堡垒。这些野蛮的巨人栖息在古老而风化的遗迹之中，对山下的矮人定居点构成了持续不断的威胁。",kw={"洛克莫丹","莫格罗什","山地巡逻队","食人魔","遗迹","要塞"},ang={["faction:Alliance"]="保卫洛克莫丹需要压制莫格罗什食人魔，以确保铁炉堡与北部山路之间的通行安全。",["race:Dwarf"]="莫格罗什食人魔不断威胁着矮人的巡逻队和旅行者，因此铲除它们的要塞成为了洛克莫丹山地巡逻队的一项公民防卫任务。"},sec={{t="迫在眉睫的威胁",b="莫格罗什要塞隐匿在洛克莫丹东北部的岩脊之中，是莫格罗什食人魔氏族在该地区的主要据点。潜伏在洞穴和外围营地中的蛮力部队经常劫掠往来的矮人补给车队，并对塞尔萨玛的和平造成了长久的威胁。营地周围散落的粗糙石制品暗示着这里在笨重的食人魔占据领地并建立他们独特的土丘之前，曾属于一个更古老的定居点。"}},faq={{q="莫格罗什要塞是什么？",a="它是一处建在洛克莫丹东北部山丘里的食人魔据点。莫格罗什食人魔居住在洞穴和周边地区，组成了该领地上最大的敌对食人魔飞地。",al={"莫格罗什要塞","洛克莫丹食人魔营地","莫格罗什洞穴"}},{q="在食人魔占据这里之前，谁曾居住在此？",a="古老的石制品表明在食人魔到来之前这里曾有过一个定居点，但其最初的居民是谁尚不得而知。",al={"洛克莫丹古代遗迹","谁建造了莫格罗什","洛克莫丹的巨魔"}},{q="为什么这些食人魔对矮人来说是个问题？",a="它们靠近关键的交通路线，对当地交通和在洛克莫丹穿行的贸易商队构成了严重的危险。矮人当局经常呼吁冒险者削减它们的数量，以保障山路的通行安全。",al={"为什么要击杀莫格罗什食人魔","铁炉堡面临的莫格罗什威胁"}}},fx={c213ae8d={q="莫格罗什要塞里住着谁？",a="要塞由莫格罗什食人魔占据。这个野蛮的氏族盘踞在洛克莫丹东北部的丘陵和土丘之上，成员中有蛮兵、萨满和其他强悍的打手。他们住在粗陋的土丘和深邃的洞穴中，凶狠地抵御任何擅自闯入的外来者或矮人巡逻队。",al={"莫格罗什要塞里住着谁","莫格罗什要塞食人魔","谁领导莫格罗什要塞"}},c4467cb6={q="莫格罗什要塞危险吗？",a="极其危险。莫格罗什食人魔是整个洛克莫丹最致命的威胁之一。与附近零散的穴居人和野兽不同，这些食人魔身形庞大、组织严密，既有骇人的蛮力，也会使用萨满法术。冒失的探险者独自闯入营地往往难逃一死，塞尔萨玛的巡山人也警告人们，除非有大批援手，否则不要进入。",al={"莫格罗什要塞危险吗","莫格罗什要塞有多危险","莫格罗什要塞的危险"}}},fp="19,211,16.489.0,28.192.0,39.110.0,44.235.0"}
P.entries["subzone:molsen-farm"] = {n="摩尔森农场",s="摩尔森农场是位于西部荒野粮仓地区的一处废弃宅地。这里曾是一片肥沃的农田，为暴风城提供粮食，但在迪菲亚潜行者崛起，以及随之而来的机械收割傀儡肆虐之后，这里已是一片荒凉。",h="摩尔森农场是位于西部荒野粮仓地区的一处废弃宅地。这里曾是一片肥沃的农田，为暴风城提供粮食，但在迪菲亚潜行者崛起，以及随之而来的机械收割傀儡肆虐之后，这里已是一片荒凉。",kw={"废弃农场","迪菲亚","收割傀儡","宅地","摩尔森农场","西部荒野"},ang={["faction:Alliance"]="摩尔森农场杂草丛生的田野，严酷地提醒着人们暴风城对其农村领地日益衰弱的控制力，以及迪菲亚潜行者带来的紧迫威胁。"},sec={{t="一处废弃的宅地",b="和西部荒野各地许多宅地一样，摩尔森农场也成为了王国忽视和犯罪起义的牺牲品。当迪菲亚潜行者控制了乡村地区时，当地的农夫们被赶走，甚至遭遇了更糟的命运，不得不放弃了他们的作物和建筑。如今，这里不再有辛勤劳作的农夫，取而代之的是充满敌意的机械收割傀儡和游荡的暴徒，他们在那片荒芜的田野中横行，使得这座农场对于途径该地区的任何人来说都充满了危险。"}},faq={{q="摩尔森农场为何会被废弃？",a="当迪菲亚潜行者横扫西部荒野时，这座农场被废弃了。由于得不到来自暴风城的军事保护，农场主们无法抵御强盗和失控的收割傀儡，被迫逃离了自己的家园。",al={"为什么它是空的","谁住在这里","摩尔森农场发生了什么"}},{q="现在是谁控制着农场？",a="田野里到处都是发生故障的收割傀儡和与迪菲亚潜行者结盟的暴徒。目前没有合法的公民居住或耕作于此。",al={"摩尔森农场的敌人","谁在摩尔森农场"}},{q="摩尔森是谁？",a="在最近的动乱导致西部荒野的农业人口流离失所或陷入贫困之前，该农场因最初在此定居并耕种土地的当地家族而得名。",al={"谁是摩尔森","摩尔森家族"}}},fx={b4e71629={q="摩尔森农场是什么地方？",a="摩尔森农场是散布在西部荒野平原上的众多农庄之一。它曾是一座运作中的农庄，为王国提供谷物和农产品；后来，随着动荡与困苦席卷这片地区，它也和周边乡村一同衰败。",al={"摩尔森农场是什么","西部荒野的摩尔森农场","摩尔森农场介绍"}},f96eccd7={q="摩尔森农场发生了什么？",a="与西部荒野的许多地方一样，第二次战争后的动乱令摩尔森农场沦为废墟。农场主被迫离开土地，迪菲亚潜行者夺取了这片领地，机械收割机也在此横行。",al={"摩尔森农场发生了什么","摩尔森农场历史","摩尔森农场故事"}},["977abee8"]={q="摩尔森农场危险吗？",a="是的，普通旅人身处此地极其危险。田地里有失控的机械收割机巡逻，还有隶属迪菲亚潜行者的亡命之徒四处游荡。他们会凶狠地攻击任何擅闯其领地的人。",al={"摩尔森农场危险吗","摩尔森农场的威胁","摩尔森农场的危险"}}},fp="11,268,18.458.0,29.243.0,26.164.0,15.174.0"}
P.entries["subzone:moon-horror-den"] = {n="惨月洞穴",s="惨月洞穴是一处偏僻且布满冰霜的洞穴，位于冬泉谷中永望镇这座地精贸易站的东北方。洞穴坐落在参差不齐的山腰上，是狂暴枭兽的筑巢地。旅行者在靠近其冰冷的洞口时必须小心，因为这些领地意识极强的枭兽会激烈地保卫它们的庇护所。",h="惨月洞穴是一处偏僻且布满冰霜的洞穴，位于冬泉谷中永望镇这座地精贸易站的东北方。洞穴坐落在参差不齐的山腰上，是狂暴枭兽的筑巢地。旅行者在靠近其冰冷的洞口时必须小心，因为这些领地意识极强的枭兽会激烈地保卫它们的庇护所。",kw={"洞穴","永望镇","惨月洞穴","枭兽","狂暴枭兽","冬泉谷"},ang={["class:Druid"]="作为艾露恩神圣生物的守护者，德鲁伊们发现洞穴中栖息的枭兽处于暴力狂乱状态，这令人感到警醒，反映出冬泉谷正受到狂暴力量的侵袭。",["class:Hunter"]="该洞穴为追踪凶猛的枭兽提供了一个狭窄而危险的场地，在这里，与皮糙肉厚的枭兽进行近距离战斗将考验任何追踪者的胆量。"},sec={{t="羽毛与冰霜之穴",b="惨月洞穴位于距离永望镇守卫森严的大门东北方向不远处，深入山岩之中。这座洞穴是强大的狂暴枭兽的家园——这种凶猛的枭兽以其蛮力和在冬泉谷严寒雪地中的野性天性而闻名。尽管它在地理位置上靠近南面的寒水村熊怪定居点，但陡峭的山壁形成了一道不可逾越的天然屏障，确保了该洞穴依然是枭兽与世隔绝的避难所，而非交通要道。"}},faq={{q="惨月洞穴里住着什么生物？",a="这座洞穴栖息着狂暴枭兽，这是一种适应了冬泉谷严寒气候的大型且具有攻击性的枭兽。这些领地意识极强的野兽会猛烈攻击任何误入其地下巢穴的人。",al={"惨月洞穴里有什么","惨月洞穴怪物","洞穴里的枭兽"}},{q="惨月洞穴位于哪里？",a="它位于冬泉谷东部，就在地精城镇永望镇东北方不远处。洞口坐落在北面的岩壁中。",al={"惨月洞穴位置","如何找到惨月洞穴","惨月洞穴在哪里"}},{q="你能从洞穴到达寒水村吗？",a="不能。尽管在地图上寒水村就在正南方，但高耸的山脊在洞穴后方形成了一道不可逾越的天然墙壁。前往该村庄需要绕过山坡，穿过开阔的山谷。",al={"去寒水村的路径","去寒水村的捷径","从洞穴到寒水村"}},{q="为什么旅行者要冒险进入这个洞穴？",a="冒险者通常进入该洞穴狩猎狂暴枭兽，以协助那些研究冬泉谷中受到腐蚀或具有攻击性的枭兽种群的自然学家和研究人员。",al={"为什么要去惨月洞穴","惨月洞穴任务"}}},fp="15,356,27.526.0,43.211.0,37.160.0,46.228.0,40.182.0"}
P.entries["subzone:moonbrook"] = {n="月溪镇",s="月溪镇曾经是西部荒野西南部一个熙熙攘攘的农业中心和采矿小镇，如今却成了一座无法无天的鬼城。这座小镇已被迪菲亚潜行者完全占领，他们将其作为坚固的屏障，用来掩盖他们位于死亡矿井底下的总部。",h="月溪镇曾经是西部荒野西南部一个熙熙攘攘的农业中心和采矿小镇，如今却成了一座无法无天的鬼城。这座小镇已被迪菲亚潜行者完全占领，他们将其作为坚固的屏障，用来掩盖他们位于死亡矿井底下的总部。",kw={"死亡矿井","迪菲亚","月溪镇","学校","哨兵岭","范克里夫","西部荒野"},ang={["class:Rogue"]="月溪镇的小巷和被洗劫一空的房屋，直观地展现了一个犯罪集团在大白天明目张胆地运作的景象。",["faction:Alliance"]="月溪镇是一个痛苦的提醒，时刻警示着人们王国的疏忽，在这里，守法的臣民被遗弃给了迪菲亚潜行者。"},sec={{t="沦陷的城镇",b="第一次战争爆发前，月溪镇是西部荒野粮仓中心的重要聚居地，为当地农耕家庭和死亡矿井利润丰厚的金矿矿道提供支持。尽管它被旧部落夷为平地，并在第二次战争后经过艰苦重建，但和平并未长久。暴风城的贵族议会对这里疏于照管，又撤走了军事保护，这片聚居地无力抵御迁入此地的红面罩匪徒。他们赶走了诚实的垦荒者，迫使市民和教师一同逃往哨兵岭和艾尔文森林。"},{t="迪菲亚要塞",b="如今，月溪镇实际上成了艾德温·范克里夫叛乱势力的地面驻军基地。头戴红面罩的暴徒和流氓法师在街道和被洗劫的房屋中巡逻，而收割机则在周围杂草丛生的田野里巡逻。宁静的住宅街道掩盖了通往死亡矿井的入口，入口就位于镇子边缘一座不起眼的谷仓下面，这使得月溪镇成为了王国中最危险的叛乱温床。"}},faq={{q="为什么月溪镇被废弃了？",a="当迪菲亚潜行者夺取了对西部荒野的控制权后，月溪镇的居民便被迫废弃了这里。由于没有暴风城军队驻扎该地区，镇民们被迫离开，而强盗们将整个小镇据为己有，当作他们的要塞。",al={"月溪镇发生了什么","为什么月溪镇有强盗","谁占领了月溪镇"}},{q="月溪镇里面的矿洞通向哪里？",a="月溪镇边缘谷仓下的矿洞入口通往死亡矿井。这里曾经是暴风城巨大的黄金来源，如今这些错综复杂的隧道已成为迪菲亚潜行者的秘密堡垒和集结地。",al={"死亡矿井在哪里","月溪镇下面有什么","月溪镇矿洞入口"}},{q="在强盗占领之前，这里住着什么人？",a="月溪镇曾经居住着支持西部荒野农业的矿工、农民和手工业者。著名的前居民包括斯塔文·密斯特曼托，在强盗 overrun 该镇之前，他曾短暂担任过当地Moonbrook Schoolhouse的校长。",al={"月溪镇居民","谁住在月溪镇","斯塔文·密斯特曼托学校"}},{q="暴风城有计划收复这座小镇吗？",a="暴风城的宫廷一再拒绝派遣皇家军队去解放月溪镇或周围的农场，声称资源捉襟见肘。当地的防御工作完全留给了驻扎在哨兵岭的志愿者人民民兵。",al={"暴风城会拯救月溪镇吗","为什么军队不帮助月溪镇"}}},fx={["2fd23d69"]={q="月溪镇是什么地方？",a="月溪镇是西部荒野西南部的一处废弃聚居地，坐落在死亡矿井所在山丘的正下方。它曾是繁荣的采矿和农业社区，为暴风城提供粮食，如今却已沦为废墟，彻底被迪菲亚潜行者占据。",al={"这座镇是什么地方","月溪镇信息","月溪镇介绍"}},ef8d3ecf={q="月溪镇发生过什么？",a="第一次战争期间，月溪镇落入兽人部落之手，第二次战争后得以重建。后来，遭受排挤的石匠成立了迪菲亚潜行者并夺取西部荒野，他们驱逐镇民，占领月溪镇，以便将镇下废弃的金矿据为总部。",al={"月溪镇历史","月溪镇的历史","这里发生了什么"}},["4b3385a0"]={q="谁住在月溪镇或掌管这里？",a="迪菲亚潜行者完全控制着月溪镇。艾德温·范克里夫手下的匪徒、拦路强盗和扒手占据了镇上破败的房屋，在街道周围游荡，并利用此地守卫通往死亡矿井地下要塞的秘密入口。",al={"谁控制月溪镇","谁住在月溪镇","月溪镇居民"}},["00d0c34b"]={q="月溪镇危险吗？",a="危险。月溪镇到处都是全副武装的迪菲亚匪徒和失控的收割收割机，它们一见旅人就会发动攻击。暴风城没有在镇上驻军，毫无准备地进入月溪镇，很快就会引来多名协同行动、埋伏在暗处的窃贼。",al={"月溪镇安全吗","月溪镇的危险","月溪镇的威胁"}}},fp="9,275,13.561.0,17.406.1,27.252.0,42.229.1,41.266.0,40.245.0"}
P.entries["subzone:moonbrook-schoolhouse"] = {n="Moonbrook Schoolhouse",s="月溪镇校舍坐落在月溪镇的西北角，是一座显眼的建筑，外观酷似市政厅，后面还有一个小小的墓地。它最初是由校长斯塔文·密斯莱特建立的，旨在教导当地的孩子们。如今，随着迪菲亚潜行者占领了西部荒野，这里已然荒废。",h="月溪镇校舍坐落在月溪镇的西北角，是一座显眼的建筑，外观酷似市政厅，后面还有一个小小的墓地。它最初是由校长斯塔文·密斯莱特建立的，旨在教导当地的孩子们。如今，随着迪菲亚潜行者占领了西部荒野，这里已然荒废。",kw={"迪菲亚潜行者","足箱","校长","密斯莱特","月溪镇","校舍","斯塔文","西部荒野"},ang={["faction:Alliance"]="这座破败的校舍严酷地提醒着人们，西部荒野距离王国的庇护已有多远，曾经的学习中心如今沦为了法外之徒的藏身之所。"},sec={{t="坠入阴影的灯塔",b="在月溪镇陷入荒废与强盗的侵扰之前，社区曾集资兴建了这座宏伟的校舍，用于培养青少年。在斯塔文·密斯莱特开始辅导当地孩子后，镇长便委任他来经营这所学校。在那些美好的日子里，这里挤满了学生，而非窃贼，它是月溪镇曾经繁荣的证明。现在，这座校舍任由风雨侵蚀，还充斥着不法之徒，而后方墓地饱经风霜的墓碑则静静地注视着西部荒野的不断衰败。"},{t="地板下的秘密",b="虽然早已不再有学者在此，但校舍中却隐藏着一个残酷谜团的开端。在大厅遗留的一个旧足箱里，放着一封未寄出的信，讲述了斯塔文来到月溪镇的过程、他对当地孩子的辅导，以及镇长委任他建立新校舍的事宜。后来在闪金镇发现的另一封信则解释了区域动荡迫使他离开职位，转而寻求私人家庭教师的工作。"}},faq={{q="这座建筑最初是做什么用的？",a="它曾是月溪镇的校舍，专门为当地儿童提供正规教育而建造。其宽敞的设计（类似于市政厅）反映了该镇在衰落前所怀抱的抱负与自豪。",al={"建造原因","月溪镇学校用途","这是什么地方"}},{q="斯塔文·密斯莱特是谁？",a="斯塔文·密斯莱特是一位博学的学者，后来成为了这所校舍的校长。调查者可以顺着他留下的书信来进一步了解他的生平。",al={"斯塔文是谁","斯塔文·密斯莱特背景故事","学校校长"}},{q="为什么现在校舍被废弃了？",a="当月溪镇在经济困境下分崩离析，而迪菲亚潜行者占领了西部荒野南部时，镇上的公共机构便随之瓦解。校舍与镇上的其他地方一起被遗弃，现在已被强盗占领。",al={"为何荒废","月溪镇学校发生了什么","现在谁住在这里"}},{q="今天在校舍里能找到什么？",a="追踪斯塔文·密斯莱特的联盟调查员可以在一楼找到一个布满灰尘的旧足箱，里面装着一封未寄出的信。",al={"足箱位置","校舍里的战利品","内部的任务物品"}}},fx={["8f4dfb64"]={q="月溪镇校舍是什么地方？",a="月溪镇校舍是一座醒目的建筑，外形类似镇政厅，位于西部荒野南部月溪镇的西北部。它专为学者斯塔尔文·米斯特曼特尔修建，在月溪镇沦为废墟前曾是一所教授当地儿童的学堂。建筑后方静静地坐落着一座小墓地。",al={"月溪镇校舍是什么","月溪镇学校","西部荒野的校舍"}},["5cab6b72"]={q="月溪镇校舍发生过什么？",a="校舍建成后用于教育社区居民，由斯塔尔文·米斯特曼特尔担任校长。在任期间，斯塔尔文教导当地学生，也与朋友和官员通信。西部荒野陷入动乱、月溪镇被迪菲亚潜行者占据后，学校遭到废弃，只留下旧物和尘封箱子里被遗忘的信件。",al={"校舍历史","月溪镇校舍发生了什么","斯塔尔文与校舍的过往"}},eb59fad3={q="月溪镇校舍危险吗？",a="危险。校舍本身虽只是一座破败的礼堂，却位于月溪镇内，而镇上已被迪菲亚潜行者严密占据。亡命徒、匪徒和强盗在周边街道巡逻，还常在建筑入口附近逗留，让毫无防备的旅人此行危机四伏。",al={"月溪镇校舍危险吗","校舍的威胁","月溪镇校舍里的危险"}}},fp="21,293,27.531.0,26.431.1,43.225.0,27.165.0,37.236.0,47.133.0"}
P.entries["subzone:moonshrine-ruins"] = {n="Moonshrine Ruins",s="Moonshrine Ruins是位于黑暗深渊深处的一片被淹没的古老暗夜精灵建筑遗迹。这些正在崩塌的大厅曾用于供奉艾露恩，如今却遭到了暮光之锤教派的亵渎和占领。",h="Moonshrine Ruins是位于黑暗深渊深处的一片被淹没的古老暗夜精灵建筑遗迹。这些正在崩塌的大厅曾用于供奉艾露恩，如今却遭到了暮光之锤教派的亵渎和占领。",kw={"阿奎尼斯","黑暗深渊","moonshrine","遗迹","sanctum","瑟拉顿","暮光之锤"},ang={["class:Shaman"]="通过黑暗符文石束缚阿奎尼斯男爵这类水之精魂的行为，揭示了暮光之锤扭曲和奴役元素力量的程度有多深。",["race:NightElf"]="看到这些献给艾露恩的神圣大厅沦为被淹没、被教派蹂躏的废墟，对于任何踏入深渊的暗夜精灵来说，都是一种苦涩的悲哀。"},sec={{t="艾露恩的浸没大厅",b="穿过洞穴状的Pool of Ask'ar，便到了Moonshrine Ruins。这里是暗夜精灵在灰谷海岸悠久过去的凄凉见证。这些部分淹没在大厅里曾经回荡着赞美月亮女神艾露恩的圣歌，但大分裂摧毁了这座神殿，将其下层淹没在海水中。如今，浑浊的水域中翻涌着凶猛的水生野兽，从极具攻击性的螃蟹到蛇形的瑟拉顿，而暮光之锤教派则在这些石块间保持着活跃，沉迷于亵渎神殿神圣起源的黑暗仪式。"},{t="元素深处",b="这些遗迹连接着Forgotten Pool和Moonshrine Sanctum，是该教派进行召唤仪式的基地。在淹没的密室水面之下，坐落着一块与元素相连的古老符文石。通过这个水下聚焦点，暮光之锤操纵着深渊的水流，召唤出了阿奎尼斯男爵——一个受他们邪恶阴谋束缚的巨大水元素。"}},faq={{q="Moonshrine Ruins最初是用来做什么的？",a="这些遗迹最初是一个献给暗夜精灵女神艾露恩的宏伟地下神殿建筑群的一部分，在大分裂将古老大陆撕裂之前就已建成。",al={"moonshrine起源","谁建造了moonshrine ruins","这是什么地方"}},{q="现在是谁在控制Moonshrine Ruins？",a="遗迹中不仅出没着瑟拉顿和尖壳蟹等充满敌意的水生野兽，还有属于暮光之锤的邪教徒，他们已经彻底占领了整个沉没的建筑群。",al={"这里有什么人","moonshrine的怪物","黑暗深渊中的暮光之锤"}},{q="Moonshrine Ruins通向哪里？",a="遗迹位于Pool of Ask'ar之外的隧道深处。从Moonshrine Ruins出发，路径可以直接通向更深处的Moonshrine Sanctum，并提供前往Forgotten Pool的通道。",al={"moonshrine的出口","这里通向哪里","穿过遗迹的路径"}},{q="阿奎尼斯男爵是谁？",a="阿奎尼斯男爵是一个强大的水元素，可以通过触摸遗迹下方浑浊水域中隐藏的淹没符文石来召唤，他服务于暮光之锤的邪恶目的。",al={"阿奎尼斯男爵背景故事","moonshrine的水下首领","水中的元素"}}},fx={b0a2ccc3={q="月神殿遗迹是什么地方？",a="月神殿遗迹是黑暗深渊深处的一处水下洞窟群。这里曾是供奉艾露恩的古老暗夜精灵圣所，如今殿堂已部分淹没在地下水域中。堕落的教徒和凶猛的水生捕食者在残破的拱门与被水淹没的厅室间出没。",al={"月神殿遗迹是什么","月神殿遗迹传说","月神殿遗迹介绍"}},e8d3a9e3={q="月神殿遗迹为什么这么危险？",a="遗迹中盘踞着狂热的暮光之锤教徒和凶猛的水生生物。成群的螃蟹和巨大的钳嘴龙在被水淹没的通道中横行，随时准备把游泳者拖入水底；教徒则在阴影中举行黑暗仪式。",al={"月神殿遗迹危险吗","月神殿遗迹的危险","月神殿遗迹里的威胁"}},["9bba1602"]={q="为什么叫月神殿遗迹？",a="这处洞窟因古老的暗夜精灵神殿而得名，那些神殿最初是为了供奉月之女神艾露恩。天崩地裂之后，历经数百年荒废，这些昔日辉煌的圣地逐渐坍塌，变成了如今所见的残破水下石殿。",al={"为什么叫月神殿遗迹","月神殿遗迹名称","月神殿的含义"}}},fp="16,234,22.564.0,20.402.1,52.185.0,38.186.0,35.189.0,21.183.0"}
P.entries["subzone:moonshrine-sanctum"] = {n="Moonshrine Sanctum",s="Moonshrine Sanctum是深藏在黑暗深渊中的一座古老精灵神殿，现在是暮光之锤教派的内层堡垒。在梦游者克尔里斯的统治下，这座密室供奉着一座艾萨拉女王的原始雕像，并直接守卫着通往Aku'mai's Lair的封印入口。",h="Moonshrine Sanctum是深藏在黑暗深渊中的一座古老精灵神殿，现在是暮光之锤教派的内层堡垒。在梦游者克尔里斯的统治下，这座密室供奉着一座艾萨拉女王的原始雕像，并直接守卫着通往Aku'mai's...",kw={"阿库麦尔","艾萨拉","黑暗深渊","蜡烛","克尔里斯","moonshrine","密室","暮光之锤"},ang={["class:Priest"]="梦游者克尔里斯在这个密室中进行的扭曲仪式颠倒了神圣的崇拜，引导的是虚空的疯狂低语，而非恢复性的神圣祈祷。",["race:NightElf"]="看到一座由你的祖先在天崩地裂前开凿的古老神殿，沦为暮光之锤和纳迦的祭祀巢穴，这是灰谷阴影不断侵蚀的令人作呕的证明。"},sec={{t="一座被亵渎的神殿",b="Moonshrine Sanctum位于被淹没的Moonshrine Ruins之外，是黑暗深渊内邪教活动的核心枢纽。虽然这座大厅最初是暗夜精灵在数千年前为纪念月亮和他们的统治者而建的，但现在它已被暮光之锤玷污。有趣的是，邪教徒们小心翼翼地维护着艾萨拉女王的高大雕像，似乎对雕像所描绘的对象并不在意。在梦游者克尔里斯的注视下，幽暗的仪式在如洞穴般的石顶下日夜吟唱。"},{t="通往阿库麦尔的门槛",b="这座密室是Aku'mai's Lair前的最后一道防线。沉重的双扇石门封印着那头巨大的多头蛇，并由古老的结界咒语牢牢锁住。艾萨拉的中央雕像周围有四个仪式火盆，必须点燃它们才能解开封印。这样做会惊动神殿里沉睡的守护者——成群的巨型螃蟹、断颚海龟、披甲马库拉和被召唤来防御密室不受冒失闯入者侵扰的水元素。"}},faq={{q="Moonshrine Sanctum在哪里？",a="Moonshrine Sanctum位于灰谷佐拉姆海岸的黑暗深渊地下城深处。它就在被淹没的Moonshrine Ruins之后，紧邻多头蛇阿库麦尔的巢穴。",al={"moonshrine sanctum位置","moonshrine sanctum在哪里","黑暗深渊密室"}},{q="谁统治着Moonshrine Sanctum？",a="梦游者克尔里斯掌管着这座密室。他是暮光之锤教派中一位强大的织梦法师，负责主持仪式以向他们古老的虚空眷顾者致敬。",al={"谁是这里的首领","moonshrine sanctum的首领","谁管理密室"}},{q="为什么这里有一座完好无损的艾萨拉雕像？",a="该密室最初是一座古老的精灵神殿，在天崩地裂前供奉着艾萨拉女王。暮光之锤一直很好地维护着这座雕像，似乎对它所尊崇的女王毫无异议。",al={"艾萨拉雕像","为什么有艾萨拉雕像","黑暗深渊纳迦雕像"}},{q="如何打开密室后方的大门？",a="要解锁通往Aku'mai's Lair的大门，冒险者必须点燃艾萨拉雕像脚下的四支仪式蜡烛。点燃每一支蜡烛都会唤醒一波必须被击败的守护水生野兽和水元素。",al={"如何打开黑暗深渊大门","阿库麦尔大门开启","点燃黑暗深渊蜡烛"}}},fx={["6ea53622"]={q="月神殿圣所是什么地方？",a="月神殿圣所是黑暗深渊深处的一处古老殿堂。它曾供奉艾萨拉女王，如今则是当地暮光之锤教派的核心据点。教徒在纳迦女王完好的雕像前举行黑暗仪式。",al={"月神殿圣所是什么","月神殿圣所信息","月神殿圣所介绍"}},["67d36571"]={q="月神殿圣所发生了什么？",a="这处圣所最初是供奉艾萨拉女王的古老精灵神殿，在大分裂中沉入灰谷水下并得以留存。近来，暮光之锤教派发现了这座地下神殿，并将其据为最高据点，利用古老殿堂举行黑暗仪式。",al={"月神殿圣所历史","月神殿圣所发生了什么","月神殿圣所的历史"}},["99e9f82b"]={q="月神殿圣所危险吗？",a="这里极其危险。狂热的暮光之锤教徒在梦游者克尔里斯的带领下严密守卫着这处殿堂。此外，神殿本身还有危险的守护者镇守，而且它就位于通往Aku'mai's Lair的门槛之前。",al={"月神殿圣所有多危险","月神殿圣所安全吗","月神殿圣所的危险"}}},fp="18,295,19.539.0,24.469.1,32.213.0,38.179.0,46.222.0,59.240.0"}
P.entries["subzone:moonspray"] = {n="Moonspray",s="Moonspray是一艘隶属于卡多雷舰队的联盟运输船。它在将卡利姆多大陆与宏伟的世界之树泰达希尔隔开的水域上，提供了至关重要的海上通行服务。",h="Moonspray是一艘隶属于卡多雷舰队的联盟运输船。它在将卡利姆多大陆与宏伟的世界之树泰达希尔隔开的水域上，提供了至关重要的海上通行服务。",kw={"奥伯丁","船","黑海岸","渡轮","卡多雷舰队","moonspray","鲁瑟兰村","泰达希尔","运输"},ang={["faction:Alliance"]="Moonspray形成了连接联盟在卡利姆多北部的主要沿海枢纽与孤立的达纳苏斯首都之间的重要交通纽带。",["race:NightElf"]="对于离开泰达希尔去探索广阔世界的年轻暗夜精灵来说，Moonspray往往是载着他们第一次离开与世隔绝的家园前往大陆的那艘船。"},sec={{t="重要的岛屿渡轮",b="Moonspray是黑海岸奥伯丁码头与泰达希尔根部的鲁瑟兰村之间不可或缺的生命线。这艘运输船穿越薄雾之海，运送冒险者、信使和重要补给品，连接着世界之树树冠上与世隔绝的暗夜精灵庇护所与古老的卡利姆多大陆。"}},faq={{q="Moonspray往返于何处？",a="Moonspray往返于黑海岸的港口城镇奥伯丁与位于泰达希尔海上基地的鲁瑟兰村之间。",al={"moonspray航线","moonspray去哪里","moonspray目的地"}},{q="谁拥有并运营这艘船？",a="Moonspray是一艘暗夜精灵船只，隶属于卡多雷舰队，悬挂联盟旗帜航行。",al={"谁在驾驶moonspray","卡多雷舰队 moonspray","moonspray属于联盟吗"}},{q="为什么这条渡轮航线如此重要？",a="泰达希尔是一座坐落在卡利姆多西北海岸外海域高处的岛屿。像Moonspray这样的船只是将部队、补给和旅行者从海上运往大陆的主要交通工具。",al={"为什么要乘坐moonspray","泰达希尔船只"}}},fx={de38a5e0={q="Moonspray是什么？",a="Moonspray是一艘优雅的暗夜精灵运输船，隶属于卡多雷舰队。它往返于黑海岸奥伯丁的码头与泰达希尔山脚下的鲁瑟兰村之间，是一艘重要的海上渡船，将这棵宏伟的世界之树与卡利姆多大陆连接起来。",al={"moonspray是什么","moonspray船只","moonspray黑海岸"}},["6febef79"]={q="Moonspray的历史是怎样的？",a="Moonspray是暗夜精灵海上运输舰队的一员。泰达希尔成长起来后，它受命横渡海域，连通两岸。自奥伯丁和鲁瑟兰村建立以来，它一直运送旅客、补给和信使往返两地，让这座与世隔绝的首都与卡利姆多海岸保持联系。",al={"moonspray历史","moonspray怎么了","moonspray的历史"}},["9638ce15"]={q="Moonspray危险吗？",a="对联盟旅客来说并不危险。Moonspray是一艘由暗夜精灵水手安全运营的民用渡船，负责运送人员和补给。不过，任何试图登船的部落成员都会发现自己身处敌对领土，并遭到船员和港口码头驻守的暗夜精灵卫兵迅速反击。",al={"moonspray危险吗","moonspray的危险","moonspray上的威胁"}}},fp="9,203,20.354.0,32.139.0,32.120.0,34.218.0"}
P.entries["subzone:moonwell-ashenvale"] = {n="月亮井 (灰谷)",s="这座隐蔽的神龛，在暗夜精灵中被称为“纯净月井”，坐落在灰谷中部，伊瑞斯湖以东，林中树居以西。它那受祝福的井水汇聚了艾露恩的恩典，滋养着这片古老的森林，并净化着大地上蔓延的邪恶。追随莱恩·狼行者的研究的联盟旅人，常常会寻找在那宁静的池畔守望的莎尔蒂恩。",h="这座隐蔽的神龛，在暗夜精灵中被称为“纯净月井”，坐落在灰谷中部，伊瑞斯湖以东，林中树居以西。它那受祝福的井水汇聚了艾露恩的恩典，滋养着这片古老的森林，并净化着大地上蔓延的邪恶。追随莱恩·狼行者的研究的联盟旅人，常常会寻找...",kw={"灰谷","净化","艾露恩","伊瑞斯湖","月井","纯净月井","林中树居"},ang={["profession:Tailoring"]="裁缝可以利用聚集在水中的浓郁月亮能量，将恶魔布编织成纯净的月布。",["race:NightElf"]="对于卡多雷来说，每一口月井都是远在他乡的神圣家园，既是艾露恩恩典的精神源泉，也是抵御威胁着灰谷的恶魔腐蚀的前线堡垒。"},sec={{t="纯净圣所",b="这口月井藏在灰谷中部的树冠之下，是卡多雷的精神锚点。它那发光的井水汲取着自然的潜能与月之女神的光辉。随着周围的森林饱受萨特腐化、邪能污染以及伐木入侵的折磨，像这样的纯净神龛便成了那些试图治愈森林之人的重要生命线。"},{t="治愈森林",b="协助莱恩·狼行者的冒险者们来到这里寻找莎尔蒂恩，她知晓达图尔曾经制造的那根权杖。她会指引他们前往寻找散落的碎片，待碎片找齐后，她便会在月井旁重铸权杖。"}},faq={{q="这口特定的月井叫什么名字？",a="这个地点被称为纯净月井。它是灰谷各处的月井之一，位于伊瑞斯湖以东、林中树居以西。",al={"这是哪座月井","月井名称","纯净月井"}},{q="月井有什么用？",a="月井是供奉给艾露恩的神圣水池，融合了月亮力量与自然魔法。暗夜精灵利用它们来维持大地的生机、恢复精神力量，并净化被黑暗或恶魔力量污染的物品。",al={"月井的作用","月井用途","月井存在的意义"}},{q="为什么联盟冒险者会造访这座月井？",a="从阿斯特兰纳出发，追随莱恩·狼行者研究的联盟英雄们会来到这里寻找莎尔蒂恩，她会帮助他们找回达图尔权杖的碎片。",al={"莱恩的净化月井","为什么要来这里","在此净化权杖"}}},fp="20,397,19.380.0,16.219.1,38.151.0,28.225.0,48.161.0"}
P.entries["subzone:mor-shan-rampart"] = {n="莫尔杉壁垒",s="莫尔杉壁垒是部落位于贫瘠之地北界的一处重兵把守的防御工事，守卫着通往灰谷的入口。它主要由战歌氏族建造，既可以抵御暗夜精灵的反击，保护部落领土，也作为向森林深处进军的集结地。",h="莫尔杉壁垒是部落位于贫瘠之地北界的一处重兵把守的防御工事，守卫着通往灰谷的入口。它主要由战歌氏族建造，既可以抵御暗夜精灵的反击，保护部落领土，也作为向森林深处进军的集结地。",kw={"灰谷","贫瘠之地","黄金之路","莫尔杉壁垒","莫尔杉","战歌氏族"},ang={["faction:Alliance"]="联盟战士将莫尔杉壁垒视为一种侵略性的路障，认为它是部落为了保护掠夺的领土并向灰谷发起突袭而建立的。",["faction:Horde"]="对于部落而言，该壁垒是保护贫瘠之地心脏地带免受暗夜精灵入侵的主要陆路大门，同时也保证了通往灰谷伐木作业点的补给线畅通无阻。"},sec={{t="北门",b="Standing at the northern terminus of the Gold Road, the Mor'shan Rampart marks the transition between the arid plains of the Barrens and the ancient canopies of Ashenvale. Built from heavy timber, defensive palisades, and fortified watchtowers, this bulwark was raised to stem the retaliatory strikes of night elven forces outraged by the Horde's logging operations. It acts both as a shield securing the northern gate to Kalimdor's interior and as a forward staging post for raiding parties pushing north toward Astranaar."},{t="战歌前哨站",b="这里主要由隶属于战歌氏族的久经沙场的战士驻守，壁垒始终保持着高度的军事戒备。岗哨从城垛上监视着林线，寻找暗夜精灵斥候和弓箭手的踪迹，确保灰谷前线哨所与南部更广阔的部落定居点之间的补给线畅通。"}},faq={{q="莫尔杉壁垒是什么？",a="它是一个位于贫瘠之地与灰谷交界处的部落防御要塞。它的建造旨在阻止联盟的反击进入贫瘠之地，并守卫黄金之路的北端。",al={"莫尔杉壁垒","这是什么路障","贫瘠之地北门"}},{q="谁控制着这座防御工事？",a="该防御工事由部落驻守，具体来说是隶属于战歌氏族的战士和哨兵。他们在森林边界沿线维护着瞭望塔和栅栏。",al={"谁控制了莫尔杉","谁在守卫壁垒","莫尔杉守军"}},{q="为什么壁垒建在这里，而不是灰谷更深处？",a="它是黄金之路北端的支点，是连接贫瘠之地中部与灰谷的主要陆路通道。控制这个咽喉要道可以确保暗夜精灵的袭击无法轻易南下直抵部落控制领土的核心地带。",al={"为什么在这里建造壁垒","莫尔杉战略重要性"}},{q="联盟旅行者能安全通过壁垒吗？",a="不能。壁垒是部落的现役军事阵地。从灰谷或贫瘠之地接近的联盟旅行者会被驻守的卫兵发现并立即攻击。",al={"联盟可以通行吗","联盟通过莫尔杉"}}},fx={["5054dbd0"]={q="莫尔杉壁垒的历史是怎样的？",al={"莫尔杉壁垒的历史","莫尔杉壁垒的过往","莫尔杉为何建造"}},e2863b82={q="谁驻守莫尔杉壁垒？",a="壁垒由部落军队驻守，主要是隶属于战歌氏族的莫尔杉防御者和守望者。这些经验丰富的兽人战士常驻木制瞭望塔和栅栏之上，警戒边境道路，防范暗夜精灵巡逻队，同时保障部落向灰谷推进的后勤运输。",al={"谁住在莫尔杉壁垒","莫尔杉壁垒的防御者","谁守卫莫尔杉壁垒"}}},fp="16,318,17.523.0,15.337.0,29.205.0,32.173.0,55.251.0,55.172.0"}
P.entries["subzone:morgan-s-plot"] = {n="摩根墓场",s="摩根墓场是一片荒凉的墓地，坐落于逆风小径卡拉赞高塔后方，包含一座摇摇欲坠的礼拜堂。这里充斥着躁动不安的亡灵和令人窒息的死寂，埋藏着被遗忘的墓穴，以及那些曾经与麦迪文的领地有着千丝万缕联系的人们的长眠之地。",h="摩根墓场是一片荒凉的墓地，坐落于逆风小径卡拉赞高塔后方，包含一座摇摇欲坠的礼拜堂。这里充斥着躁动不安的亡灵和令人窒息的死寂，埋藏着被遗忘的墓穴，以及那些曾经与麦迪文的领地有着千丝万缕联系的人们的长眠之地。",kw={"墓穴","逆风小径","卡拉赞","麦迪文","摩根墓场"},ang={["class:Mage"]="达拉然的法师们对这个地方心存敬畏，因为他们知道这里埋葬着在麦迪文悲剧终局中丧生的人们。",["class:Priest"]="被亵渎的坟墓和游荡的不死居民，使摩根墓场成为了一种鲜明的警示，提醒人们守护者的黑暗命运所带来的腐蚀性污秽至今仍挥之不去。"},sec={{t="高塔阴影下的坟冢",b="摩根墓场紧靠卡拉赞后方陡峭的岩坡，是一片悲凉而杂草丛生的墓地，中心是一座破败的礼拜堂和地下墓穴。在这一带沦为逆风小径之前，这片庄园曾是高塔住户和附近区域的墓葬地。在最后的守护者麦迪文陨落后，黑暗能量渗入大地，将一切正常的秩序驱散。如今，躁动的不死生物在礼拜堂的地面上游荡，徘徊在仆从和历史人物的墓碑之间。"},{t="守护者与仆从的安息之所",b="这片墓地埋葬着与卡拉赞历史紧密相关的人物。麦迪文在摧毁高塔的悲剧发生后，曾被安葬于此。麦迪文后来复活，并于第三次战争期间回归。虽然地底墓穴中究竟还有什么依然是个谜，但这片土地本身就沉重地压抑着古老、久久未散的奥术气息和不安的灵魂。"}},faq={{q="摩根墓场位于何处？",a="摩根墓场位于逆风小径南部，坐落在卡拉赞高塔后方一个阴暗的低谷中。",al={"摩根墓场在哪里","摩根墓场位置","如何前往摩根墓场"}},{q="谁被安葬于此？",a="从历史上看，这片墓地和墓穴曾是卡拉赞的家族墓地。在麦迪文陨落后，这位守护者本人也被安葬在这里。",al={"谁埋在摩根墓场","麦迪文之墓","莫罗斯之墓","艾格文埋葬地"}},{q="摩根墓场有什么威胁？",a="礼拜堂及其周围区域徘徊着不死生物和躁动不安的灵魂，它们在墓碑和墓穴入口附近流连。",al={"摩根墓场的怪物","这里有什么敌人","礼拜堂怪物"}}},fp="13,271,34.529.0,39.380.1,31.117.0,19.130.0,43.155.0"}
P.entries["subzone:morgan-s-vigil"] = {n="摩根的岗哨",s="摩根的岗哨是坐落在燃烧平原东南部高地上的一处联盟废弃要塞。这里曾经是一个小村庄，如今其烧焦的房屋和崩塌的法师塔已成为监视黑石山山口的侦察兵们的简陋前哨站。它是联盟在这片由黑铁矮人和黑石兽人主宰、尘埃弥漫的土地上唯一的据点。",h="摩根的岗哨是坐落在燃烧平原东南部高地上的一处联盟废弃要塞。这里曾经是一个小村庄，如今其烧焦的房屋和崩塌的法师塔已成为监视黑石山山口的侦察兵们的简陋前哨站。它是联盟在这片由黑铁矮人和黑石兽人主宰、尘埃弥漫的土地上唯一的据点...",kw={"联盟哨所","黑石山","燃烧平原","狮鹫管理员","法师塔","摩根的岗哨","废墟"},ang={["faction:Alliance"]="这座饱经风霜的峭壁是你在这片燃烧平原上唯一的安全避难所，它不仅与暴风城有直接的飞行航线，还是组织对抗黑铁矮人和黑石兽人威胁的指挥中心。",["race:Human"]="守住这道山脊，就能防止黑石山下诞生的恐怖怪物肆无忌惮地涌入山口，危及脆弱的赤脊山山谷乃至暴风城的核心。"},sec={{t="平原上的最后一处炉火",b="摩根的岗哨坐落在俯瞰烈焰荒原的高耸岩石之上。在燃烧平原的恐怖灾难将其吞噬之前，这里曾是一个朴素的定居点。如今，烧焦的梁柱和破裂的法师塔遗迹成为了那场大劫难阴森的见证。幸存的守卫者们在满是煤灰的废墟中搭建起简陋的帆布帐篷，以此安身。尽管已成废墟，营地仍保留着一个狮鹫管理员，提供了一条跨越山脉直达暴风城的空中通道。对于在此奔波的侦察兵、指挥官和过往的冒险者们来说，这里是一处急需的避风港，让他们能在饱受下方掠夺成性的战帮骚扰之余，获得片刻的喘息。"},{t="漫长的守望",b="这个哨所的名字和存在目的源于对黑石山潜在威胁的警惕。随着黑铁部族深入钻研黑暗魔法，黑石兽人占据了周边的荒野，该营地便成为了前线集结地。守卫者们负责维持营地的防御，协调横跨灰烬的侦察行动，并确保通往南方赤脊山这一重要通道的安全。"}},faq={{q="这里的建筑发生了什么？",a="村里的房屋和其他结构都被烧成了平地，法师塔也残破不堪。幸存的居民在废墟中的帐篷里生活。造成破坏的元凶尚不明确。",al={"为什么摩根的岗哨被烧毁","摩根的岗哨遗迹","谁摧毁了摩根的岗哨"}},{q="摩根是谁？",a="摩根是这座岗哨以其命名的女性。她目前并不在驻守该营地的守卫者之列。",al={"摩根是谁","摩根的岗哨命名缘由","摩根在哪里"}},{q="联盟为什么要维持这个营地？",a="它是联盟在燃烧平原上唯一的防御性制高点，负责守卫通往赤脊山的北部山口，监视黑石山周边的部队动向，并直接从暴风城接收及时的补给和增援。",al={"联盟为何在此","摩根的岗哨的用途","为何要保留摩根的岗哨"}},{q="我该如何往返摩根的岗哨？",a="该哨所设有联盟狮鹫管理员，可直接飞往暴风城、湖畔镇、守望堡、跨过灼热峡谷的瑟银哨塔，以及河林的法霍德要塞。",al={"摩根的岗哨狮鹫管理员","如何前往摩根的岗哨","摩根的岗哨飞行路线"}},{q="摩根的岗哨免受攻击吗？",a="它有联盟岗哨严密防守，但营地外围始终暴露在游荡的野兽、烈焰元素和潜伏在山脊之外的袭击兽人面前。",al={"摩根的岗哨是否处于争夺中","部落能进入摩根的岗哨吗","安全区"}}},fp="14,374,30.620.0,14.408.0,36.238.0,14.114.0,41.259.0,44.194.0,35.171.0"}
P.entries["subzone:morlos-aran"] = {n="摩罗萨兰",s="摩罗萨兰是一处古老的暗夜精灵遗迹，坐落在费伍德森林的南部。在天崩地裂之前，它曾是一个繁荣而自豪的定居点，而今它已成为那个失落黄金时代的阴郁纪念碑，淹没在肆虐周边森林的恶魔枯萎病中。",h="摩罗萨兰是一处古老的暗夜精灵遗迹，坐落在费伍德森林的南部。在天崩地裂之前，它曾是一个繁荣而自豪的定居点，而今它已成为那个失落黄金时代的阴郁纪念碑，淹没在肆虐周边森林的恶魔枯萎病中。",kw={"亚米萨兰","巴莎兰","费伍德森林","卡多雷","摩罗萨兰","遗迹","天崩地裂"},ang={["class:Druid"]="废墟地基周围扭曲的土地展示了费伍德森林所遭受的严重破坏，这促使塞纳里奥议会致力于净化这片土地。",["race:NightElf"]="穿过摩罗萨兰是一个悲剧性的提醒，让人看到帝国曾经多么辉煌又如何陨落，神圣的祖传石雕如今已被军团邪恶的恶魔腐化所吞噬。"},sec={{t="黄金时代的余响",b="一万年前，天崩地裂之前，摩罗萨兰是古代卡多雷文明的一座宏伟城市中心。就像散布在北卡利姆多的姊妹定居点（如亚米萨兰、巴莎兰和Ordil'Aran）一样，它的大理石拱门和月光广场曾充满了精灵的生机与奥术。当永恒之井崩塌时，这座城市随之破碎，只留下残破的柱廊作为他们文明巅峰的纪念。"},{t="一处枯萎的遗迹",b="虽然黑海岸和灰谷的邻近遗迹陷入了衰败和荒野，但摩罗萨兰在第三次战争中遭遇了更为惨烈的命运。由于直接处于燃烧军团践踏的通道上，它仅存的地基被恶魔的腐化和有毒的泥沼所窒息。如今，遗迹中徘徊着野兽、堕落的元素以及滞留在费伍德森林的暗影势力残余。"}},faq={{q="摩罗萨兰最初是什么？",a="它是一座在天崩地裂之前繁荣昌盛的主要暗夜精灵定居点。它与古代卡利姆多各地的姊妹城市一起，构成了卡多雷黄金时代文明的核心部分，并在万年前沦为废墟。",al={"摩罗萨兰是什么","摩罗萨兰的历史","谁建造了摩罗萨兰"}},{q="为什么名字以“'Aran”结尾？",a="这个后缀的含义并无记载，但它出现在几座天崩地裂前的暗夜精灵城市中，包括黑海岸的亚米萨兰和巴莎兰、灰谷的Ordil'Aran，以及凄凉之地的Tethris'Aran。",al={"aran的含义","aran后缀","与亚米萨兰的联系"}},{q="摩罗萨兰具体位于何处？",a="它位于费伍德森林南部，靠近灰谷的边界入口。其坍塌的大理石建筑在主路旁那些腐化、枯萎的树木间清晰可见。",al={"摩罗萨兰的位置","摩罗萨兰在哪里","寻找摩罗萨兰"}},{q="如今有什么威胁徘徊在这些遗迹中？",a="堕落的野生动物、被污染的树人以及滞留的恶魔滋生在周边森林，使摩罗萨兰对于向北前往费伍德森林的过往旅人来说极其危险。",al={"摩罗萨兰里有什么","摩罗萨兰的怪物","摩罗萨兰的危险"}}},fp="11,274,24.437.0,16.413.0,32.242.0,33.205.0,37.193.0,38.185.0"}
P.entries["subzone:mortwake-s-tower"] = {n="Klaven's Tower",s="Klaven's Tower，也被称为迪菲亚之塔，是一座矗立在西部荒野东南部河岸边的加固瞭望塔。它由潜行者Klaven Mortwake指挥，是走私赃物跨越王国边界的关键中转站。",h="Klaven's Tower，也被称为迪菲亚之塔，是一座矗立在西部荒野东南部河岸边的加固瞭望塔。它由潜行者Klaven Mortwake指挥，是走私赃物跨越王国边界的关键中转站。",kw={"amber kearnen","匕首岭","迪菲亚之塔","klaven mortwake","klaven's tower","军情七处","巨魔毒药","西部荒野"},ang={["class:Rogue"]="对于在暴风城受训的潜行者新秀来说，Klaven's Tower是一个试炼之地：军情七处会指派特工潜入Mortwake的据点，测试他们的开锁和潜行技能，并掌握致命毒药的制作工艺。",["faction:Alliance"]="这座迪菲亚据点坐落在艾尔文、西部荒野和赤脊山的交界处，展示了迪菲亚潜行者对王国境内河道和贸易路线的渗透程度之深。"},sec={{t="走私者的据点",b="Klaven's Tower坐落在匕首岭北部的边界地带，是迪菲亚潜行者在西部荒野南部行动的重要枢纽。它与河对岸艾尔文森林的杰罗德码头遥相呼应，作为从赤脊山掠夺来的违禁品的接收点和集结地。凭借对水道的有利控制，迪菲亚潜行者可以避开王国的巡逻队，将物资运送过去，从而保护他们的后勤网络不被王室察觉。"},{t="毒雾与阴影",b="这座塔由Klaven Mortwake控制，他是一位沉迷于致命药剂的炼金术士兼潜行者。Mortwake在塔内花费大量时间酿造奇特的巨魔毒药，产生的浓厚毒烟充斥着塔楼上层。这些毒气虽然对入侵者来说是致命的，但也会削弱Mortwake手下卫兵的感官，从而为暴风城情报机构军情七处（SI:7）派出的潜行特工提供了可乘之机，他们在附近的丘陵上监视着这座建筑。"}},faq={{q="谁控制着这座塔？",a="这座塔由迪菲亚潜行者Klaven Mortwake把守，他负责监管走私行动并进行易挥发毒药的实验。在他指挥下，一支迪菲亚哨兵和巡逻队负责守卫这里。",al={"mortwake是谁","klaven是谁","谁住在塔里"}},{q="为什么这座塔对迪菲亚潜行者很重要？",a="它是运往西部荒野的赃物的主要后勤中转站。从赤脊山走私的货物穿过艾尔文森林，经由杰罗德码头，通过这座塔汇集，以支持迪菲亚潜行者更大规模的叛乱。",al={"迪菲亚之塔的目的","这座塔有什么用","为什么塔在这里"}},{q="为什么军情七处（SI:7）要监视这个地方？",a="在马迪亚斯·肖尔大师的领导下，暴风城情报部门一直对该地点保持严密监视，因为Mortwake制造的致命毒药以及该塔在迪菲亚潜行者补给线中的核心地位。像Amber Kearnen这样的特工在周边进行侦察，以评估迪菲亚潜行者的动向并获取有价值的情报。",al={"军情七处 mortwake 之塔","amber kearnen 之塔","为什么暴风城在监视"}},{q="塔内弥漫的烟雾是什么？",a="这些烟雾来自Klaven Mortwake进行的巨魔毒药实验。关于它们对塔内卫兵的影响，请参考受保护的章节。",al={"西部荒野 毒药之塔","塔内烟雾","klaven 毒药"}}},fx={["2b1660bb"]={q="Klaven's Tower是什么？",a="这座石制瞭望塔坐落在西部荒野东南边缘，靠近河流，位于匕首岭以北。迪菲亚潜行者早已夺取此地，并将其用作坚固据点和走私窝点，连接他们在西部荒野、艾尔文森林和赤脊山的行动。",al={"klaven's tower是什么","mortwake西部荒野之塔","西部荒野的迪菲亚之塔"}},d8588bd0={q="Klaven's Tower发生过什么事？",a="这座塔由叛逃的迪菲亚成员Klaven Mortwake及其追随者控制。迪菲亚潜行者将其改造成坚固的走私仓库，通过杰罗德码头转运违禁品。这引起了军情七处的密切关注，他们派出Amber Kearnen等间谍监视塔院，并设法应对Klaven的致命药剂。",al={"mortwake之塔的历史","klaven's tower的历史","塔里发生了什么"}},["6fe20dc9"]={q="Klaven's Tower危险吗？",a="这里极其危险。全副武装的迪菲亚哨兵和巡逻兵守卫着每个入口，改造过的无人机也潜伏在塔内。比起那些挥舞利刃的强盗，更阴险的是Klaven Mortwake炼金药剂留下的有毒烟雾；它们弥漫在空气中，威胁着毫无防备的闯入者。",al={"klaven's tower安全吗","mortwake之塔的威胁","mortwake之塔有多危险"}},["61b98615"]={q="为什么叫Klaven's Tower？",a="这座据点直接以Klaven Mortwake命名。他是迪菲亚的盗贼指挥官和毒药师，控制了这座建筑，并将其变成迪菲亚潜行者活动的中心。",al={"为什么叫mortwake之塔","mortwake是谁","为何叫klaven's tower"}}},fp="14,245,23.473.0,17.485.1,24.219.0,53.264.0,32.301.0,46.145.0"}
P.entries["subzone:mosh-ogg-ogre-mound"] = {n="莫什奥格食人魔山",s="莫什奥格食人魔山是一处位于荆棘谷北部的防御性洞穴建筑群，坐落在祖尔格拉布遗迹的正南方。这里是莫什奥格食人魔部落在丛林中的主要据点，由他们冷酷的食人魔巫师酋长玛兹索斯统治。",h="莫什奥格食人魔山是一处位于荆棘谷北部的防御性洞穴建筑群，坐落在祖尔格拉布遗迹的正南方。这里是莫什奥格食人魔部落在丛林中的主要据点，由他们冷酷的食人魔巫师酋长玛兹索斯统治。",kw={"玛兹索斯","心灵之眼","莫什奥格","山洞","食人魔","荆棘谷","祖尔格拉布"},ang={["class:Mage"]="食人魔巫师玛兹索斯在山洞深处挥舞着心灵之眼，拥有着对于粗野的食人魔来说非同寻常的原始奥术能量。"},sec={{t="食人魔的巢穴",b="莫什奥格食人魔山开凿在祖尔格拉布南部的崎岖丛林山脊中，到处是野蛮的莫什奥格殴打者、萨满祭司和战争使者。食人魔占据了这个洞穴网络，将其作为抵御敌对丛林巨魔和潜行野兽的理想堡垒。"},{t="玛兹索斯与心灵之眼",b="在山洞蜿蜒深处坐镇的是玛兹索斯，这位强大的双头食人魔巫师统领着莫什奥格氏族。他拥有心灵之眼，这是一件强大而危险的奥术圣物，增强了他对追随者的精神与法术控制力。玛兹索斯对魔法的掌控和纯粹的蛮力使得进入山洞深处对任何在荆棘谷北部探险的旅行者来说都是一场危机。"}},faq={{q="谁住在莫什奥格食人魔山？",a="这座山洞由莫什奥格食人魔部落居住，包括他们的战士、殴打者、萨满祭司和战争使者。他们受到藏在洞穴深处的双头食人魔巫师酋长玛兹索斯的统治。",al={"山洞里有什么人","莫什奥格居民","食人魔山怪物"}},{q="心灵之眼是什么？",a="心灵之眼是一件强大的魔法神器，由山洞内的食人魔巫师玛兹索斯持有。它奇异的奥术力量助长了他的巫术，并巩固了他对当地食人魔的领导地位。",al={"玛兹索斯拥有什么","心灵之眼圣物","心灵之眼"}},{q="山洞位于何处？",a="这座山洞位于荆棘谷北部，坐落在祖尔格拉布巨魔城市入口以南的山丘中。",al={"莫什奥格食人魔山在哪里","食人魔山位置","如何找到食人魔山"}}},fp="19,271,14.253.0,27.425.0,37.204.0,23.172.0,27.133.0"}
P.entries["subzone:mosshide-fen"] = {n="藓皮沼泽",s="藓皮沼泽是湿地东部一片沼泽遍布、充满危险的区域，被藓皮豺狼人部落所占据。这里遍布着原始的营地，对于那些偏离主要贸易道路的旅人来说，它是最危险的地区之一。",h="藓皮沼泽是湿地东部一片沼泽遍布、充满危险的区域，被藓皮豺狼人部落所占据。这里遍布着原始的营地，对于那些偏离主要贸易道路的旅人来说，它是最危险的地区之一。",kw={"格纳尔骨头","豺狼人","沼泽地","藓皮","藓皮沼泽","湿地"},ang={["race:Dwarf"]="铁炉堡的登山者必须时刻关注藓皮沼泽，因为这些充满侵略性的豺狼人狼群会威胁到在沼泽中搜寻物资的勘探者和守卫东部小径的侦察兵。"},sec={{t="狼群领地",b="藓皮沼泽横跨湿地东部昏暗的区域，是充满侵略性的藓皮豺狼人的主要领地。这里的沼泽稠密且杂乱，散布着简陋的棚屋和堆满骨头的营地。在像格纳尔骨头（Gnawbone）这样残暴的狼群首领的指挥下，豺狼人们极力守护着他们泥泞的领地，随时准备伏击并吞噬任何愚蠢到闯入他们猎场的旅人、侦察兵或勘探者。"}},faq={{q="什么是藓皮沼泽？",a="藓皮沼泽是位于湿地东部的一个子区域。它由完全被藓皮豺狼人占据和定居的湿透沼泽地组成。",al={"藓皮沼泽背景故事","这是什么地方","藓皮沼泽"}},{q="谁统治着藓皮沼泽？",a="藓皮豺狼人部落占据着这片沼泽，听命于像格纳尔骨头（Gnawbone）这样残暴的首领，他指挥着自己的狼群去捕获并吞噬任何闯入他们领地的外来者。",al={"谁在这里领导豺狼人","格纳尔骨头","藓皮首领"}},{q="为什么这个区域对旅人来说很危险？",a="藓皮沼泽的豺狼人以其侵略性和贪婪的食欲而臭名昭著。旅人如果偏离既定道路，或者在湿透的灌木丛中搜寻补给，就会面临游荡狩猎群的突袭。",al={"为什么它很危险","沼泽危险"}}},fx={f76be1cd={q="为什么叫藓皮沼泽？",a="这片沼泽地因占据湿地东部的藓皮豺狼人而得名。这些野蛮的野兽将潮湿的泥沼据为狩猎领地，扎营成群，并凶狠地捕食任何愚蠢到擅闯它们地盘的人。",al={"藓皮沼泽名称由来","为什么叫藓皮沼泽","藓皮沼泽是怎么得名的"}}},fp="12,228,21.449.0,21.144.0,23.179.0,40.222.0"}
P.entries["subzone:mystic-ward"] = {n="Mystic Ward",s="Mystic Ward是铁炉堡的西北区，是这座矮人主城用于精神信仰和奥术研究的宁静圣所。该区域以其凉爽、淡蓝色的旗帜和安静的大厅而闻名，与附近Great Forge那叮当作响的铁砧形成了鲜明对比。区内最宏伟的建筑Hall of Mysteries在巨大的石拱门下汇集了牧师、圣骑士和法师。",h="Mystic Ward是铁炉堡的西北区，是这座矮人主城用于精神信仰和奥术研究的宁静圣所。该区域以其凉爽、淡蓝色的旗帜和安静的大厅而闻名，与附近Great...",kw={"hall of mysteries","铁炉堡","longberrys reagents","maevas mystical apparel","法师训练师","mystic ward","牧师训练师","the fighting wizard"},ang={["class:Mage"]="对于联盟的施法者来说，Mystic Ward是卡兹莫丹除暴风城学院之外，获取奥术补给、法术书籍和进行进阶研究的首要中心。",["class:Priest"]="该区及其宏伟的Hall of Mysteries提供了一个宁静的避风港，矮人和到访的圣光修行者们在此聚集，进行祈祷、指导和交流。"},sec={{t="信仰与法术的圣所",b="虽然矮人以其在锻造和战场上的英勇而闻名于艾泽拉斯，但Mystic Ward却代表了该王国更安静的知识和精神追求。这个巨大的区域以淡蓝色纹章为标志，连接着熙熙攘攘的平民区以及Forlorn Cavern和Great Forge。在这一区域内，商人们为学者和施法者提供各式法袍、卷轴和炼金试剂，商店包括The Fighting Wizard和Maeva's Mystical Apparel。该区的主体是雄伟的Hall of Mysteries，圣光的修习与奥术魔法的实践在此交汇，为那些在联盟防御战中运用神秘力量的人们提供指导。"}},faq={{q="Mystic Ward的用途是什么？",a="Mystic Ward是铁炉堡专门用于奥术魔法、学术研究和精神崇拜的区域。它为圣骑士、牧师和法师提供施法者补给、试剂商店和训练场地。",al={"mystic ward的用途","这里发生了什么","mystic ward的作用"}},{q="Mystic Ward的主要建筑是什么？",a="该区域以Hall of Mysteries为中心，这是一个巨大的拱形大厅，容纳了主城的神圣和奥术施法者训练师，此外还有一个显眼的装饰性水池。",al={"hall of mysteries","大圣殿","mystic ward的建筑"}},{q="为什么这个区的旗帜是淡蓝色的？",a="铁炉堡使用独特的纹章来划分其城市区域。Military Ward飘扬着尚武的红色旗帜，Great Forge以火红色为特色，而Mystic Ward则展示淡蓝色旗帜，以象征沉思、智慧和魔法研究。",al={"铁炉堡的蓝色旗帜","为什么有蓝色旗帜"}},{q="Mystic Ward通向哪里？",a="该区位于城市的西北象限。通道向南连接平民区，向东南连接Great Forge，向东直接通往Forlorn Cavern。",al={"mystic ward的连接路径","如何前往mystic ward"}}},fx={["943c276c"]={q="Mystic Ward是什么？",a="Mystic Ward是铁炉堡西北部的城区，专供奥术与神圣技艺的研究和实践。这里远比热闹的Great Forge安静，设有魔法商人、试剂商店，以及宏伟的Hall of Mysteries。魔法使用者聚集在那里，在淡蓝色旗帜下学习和训练。",al={"铁炉堡mystic ward","mystic ward是什么"}},fa80dc8d={q="谁住在Mystic Ward，或由谁管理？",a="这片城区是矮人首都内学者、法师、圣骑士和牧师的庇护所。这里没有单独的总管，而是由Hall of Mysteries里的知名魔法导师和精神领袖，以及当地的奥术用品商和试剂店主组成。",al={"谁管理mystic ward","mystic ward的领袖","mystic ward里有哪些人"}},["95712a2a"]={q="Mystic Ward危险吗？",a="对铁炉堡的访客和盟友来说并不危险。Mystic Ward是联盟首都中一处宁静而安全的城区。这里的厅堂中虽有强大的魔法与神圣力量流动，但都由严谨的教师和学者严格掌控。",al={"mystic ward安全吗","mystic ward敌对吗"}},["5e418007"]={q="为什么叫Mystic Ward？",a="这片城区因专注于神秘技艺而得名。与工业气息浓厚的Great Forge或军事区Military Ward不同，这处区域完全致力于王国的奥术与神圣事业、试剂贸易和魔法教学。",al={"mystic ward名称由来","为什么叫mystic ward"}}},fp="11,406,32.715.0,33.214.0,45.179.0,43.248.0,32.174.0"}
P.entries["subzone:mystral-lake"] = {n="密斯特拉湖",s="密斯特拉湖是灰谷最大的水域，位于中南部森林，就在银风避难所下方。它深邃的水域吸引着来自联盟和部落的旅行者。",h="密斯特拉湖是灰谷最大的水域，位于中南部森林，就在银风避难所下方。它深邃的水域吸引着来自联盟和部落的旅行者。",kw={"灰谷","call of water","密斯特拉湖","银风避难所","水元素"},ang={["class:Shaman"]="密斯特拉湖湍急的深处是Call of Water任务中至关重要的一站，有志向的萨满必须在那里面对当地的灵魂，以掌握他们的元素技艺。",["race:NightElf"]="在银风避难所的注视下，这片灰谷最大的湖泊位于你们种族所保卫的森林中心。"},sec={{t="森林大湖",b="密斯特拉湖横跨银风避难所以南和Talondeep Vale以东的广阔区域，是灰谷最大的湖泊。暗夜精灵在北岸的银风避难所前哨站监视着这里，而来自部落和联盟的旅行者也经常会被吸引到湖畔。"},{t="精神的十字路口",b="密斯特拉湖吸引了各个阵营的关注。寻求元素沟通之道的部落萨满在试炼期间会前往其深邃的水域，以理解水的元素。湖泊中原始的共鸣使其成为那些学习束缚和敬畏潮汐之灵的人们必去的一处朝圣之地。"}},faq={{q="密斯特拉湖位于何处？",a="密斯特拉湖位于灰谷中南部。它直接坐落于银风避难所以南，Talondeep Vale以东，是森林中最大的开放水域。",al={"密斯特拉湖在哪里","密斯特拉湖位置","密斯特拉湖地图"}},{q="萨满为何要造访密斯特拉湖？",a="部落萨满在进行Call of Water的精神试炼时会被指引前往密斯特拉湖。该湖泊拥有深厚的元素共鸣，是理解并调和水之灵的重要地点。",al={"call of water 密斯特拉湖","萨满任务 密斯特拉湖"}},{q="谁控制着密斯特拉湖？",a="没有任何阵营对湖泊本身拥有直接的军事控制权。暗夜精灵在北岸的银风避难所前哨站对其进行监视。",al={"密斯特拉湖是部落还是联盟的","谁拥有密斯特拉湖"}}},fx={["25dbe280"]={q="密斯特拉湖是什么？",a="密斯特拉湖，也称Mystral Lake，是灰谷最大的水域。它坐落在森林中南部、银风避难所以南，宁静的湖水对旅人、寻求灵性指引者和当地各方势力而言都是重要的所在。",al={"密斯特拉湖是什么","密斯特拉湖的传说","mystral lake"}},aa377247={q="密斯特拉湖发生过什么事？",a="密斯特拉湖是灰谷最大的湖泊。暗夜精灵从湖泊北岸的银风避难所守望着它；湖水深处蕴含着强烈的元素共鸣，吸引部落萨满前来进行水之试炼。",al={"密斯特拉湖的历史","这里发生了什么","密斯特拉湖的腐化"}},be483818={q="密斯特拉湖危险吗？",a="与灰谷的大部分地区一样，这里的湖岸对粗心大意的人来说并不安全。湖泊位于争夺中的森林里，暗夜精灵哨兵和部落军队都在此活动，周围的树林中也有野兽出没。",al={"密斯特拉湖危险吗","密斯特拉湖的危险","密斯特拉湖的威胁"}}},fp="12,190,23.332.0,20.319.0,30.173.0,33.222.0,26.157.0"}
P.entries["subzone:nat-s-landing"] = {n="Nat's Landing",s="Nat's Landing是坐落在尘泥沼泽中尘泥海湾岸边的一处简朴钓鱼营地。它是纳特·帕格的私人营地和隐居之所，他被公认为艾泽拉斯最著名的钓鱼大师。来自世界各地的冒险者们都会寻访这个不起眼的码头，以磨练他们的钓鱼技艺。",h="Nat's Landing是坐落在尘泥沼泽中尘泥海湾岸边的一处简朴钓鱼营地。它是纳特·帕格的私人营地和隐居之所，他被公认为艾泽拉斯最著名的钓鱼大师。来自世界各地的冒险者们都会寻访这个不起眼的码头，以磨练他们的钓鱼技艺。",kw={"垂钓者","码头","尘泥海湾","尘泥沼泽","钓鱼","纳特·帕格","nat's landing","塞拉摩"},ang={["faction:Alliance"]="对于驻扎在塞拉摩的联盟公民来说，Nat's Landing只是沿海岸线走一小段宁静的路程，可以轻松拜访这位世界顶级的钓鱼大师。",["faction:Horde"]="从贫瘠之地穿越危险沼泽跋涉而来的部落垂钓者会发现，纳特对战争毫不关心，他只会根据垂钓者的抛竿技术来评判来访者。"},sec={{t="大师的避风港",b="Nat's Landing位于塞拉摩岛西南方，掩映在尘泥海湾浑浊的水域边，不过是一个饱经风霜的营地而已。这里只有一顶简单的帆布帐篷，挂满当天渔获的晾晒架，挂在树上的额外渔具，以及一座伸入海湾的摇摇欲坠的木质码头。尽管沼泽中迷雾缭绕、险象环生，但这段宁静的海岸线为传奇钓鱼大师纳特·帕格提供了一个可以远离尘世喧嚣、独自垂钓并享受宁静时光的地方。"},{t="钓鱼者的朝圣之旅",b="尽管乍看之下不起眼，但这个码头却是渴望进阶的钓鱼者必经的一站。那些已经学完了铁炉堡、奥格瑞玛或其他地方标准训练师所教知识的垂钓者，会被指引到这里向纳特证明自己的价值。帕格从不关心政治或阵营纷争；任何敢于冒着沼泽猛兽的危险来到他码头的垂钓者，都必须在世界上最危险的水域中展现出耐心和技巧，才能获得他最顶级的指导。"}},faq={{q="Nat's Landing在哪里？",a="Nat's Landing坐落在尘泥海湾沿岸的一处小型海岸岩礁上，位于尘泥沼泽东部，就在塞拉摩岛西南方。",al={"nat's landing在哪里","nat's landing位置","如何前往nat's landing"}},{q="谁住在Nat's Landing？",a="这个码头是著名人类钓鱼大师纳特·帕格的私人营地，他整天都在码头上拿着酒杯垂钓。",al={"nat's landing有什么人","nat's landing npc","谁住在这里"}},{q="为什么垂钓者要来这里？",a="当垂钓者掌握了主城中所有当地训练师能教给他们的知识后，他们就会被派往纳特·帕格那里。在向他们传授工匠级的指导之前，他会用世界各地极具挑战性的渔获来考验他们的专注力。",al={"为什么要来nat's landing","工匠级钓鱼训练师","纳特·帕格训练"}},{q="纳特·帕格欢迎联盟和部落吗？",a="是的。对于专注的垂钓者，纳特·帕格持中立态度，无论是来自塞拉摩的联盟旅行者，还是从贫瘠之地冒险而来的部落旅行者，他都表示欢迎，而不论其阵营效忠。",al={"nat's landing有敌意吗","部落可以和纳特交谈吗","纳特·帕格中立吗"}}},fp="13,320,16.503.0,26.473.0,31.167.0,27.139.0,27.229.0,47.184.0"}
P.entries["subzone:nek-mani-wellspring"] = {n="纳克迈尼圣泉",s="纳克迈尼圣泉高踞于南野人海岸上方的峭壁之上，泉中流淌着极其纯净的圣水。它是暮色森林以南唯一为人所知的未受污染的淡水源。然而，这个神圣的地点最近被充满敌意的娜迦探险者占领，它们严加防守着泉水。",h="纳克迈尼圣泉高踞于南野人海岸上方的峭壁之上，泉中流淌着极其纯净的圣水。它是暮色森林以南唯一为人所知的未受污染的淡水源。然而，这个神圣的地点最近被充满敌意的娜迦探险者占领，它们严加防守着泉水。",kw={"圣泉","圣水","娜迦","纳克迈尼","野人海岸","荆棘谷"},ang={["class:Priest"]="围绕纳克迈尼泉水神圣起源的各种说法使其成为牧师们好奇的对象，尽管关于它属于哪种信仰的争执仍是一场持久的学术纠纷。"},sec={{t="神圣之盆",b="纳克迈尼圣泉坐落在荆棘谷西部的崎岖海岸高地上。作为暮色森林以南唯一未受污染的淡水源，这处泉水被各方学者和朝圣者誉为圣水。由于不同文化和传统都声称这神圣的泉水是专为他们自己的族群所祝福，它依然是激烈神学争论的主题。尽管它享有属灵盛名，但在此进行宁静的沉思已不可能：一群凶残的娜迦最近占领了水盆，并防备着所有靠近泉水的人。"}},faq={{q="纳克迈尼圣泉有什么特别之处？",a="这处圣泉产出极其纯净的圣水，被公认为暮色森林以南荒野中唯一未受污染、完全新鲜的淡水源。许多宗教学者认为其泉水神圣，尽管不同信仰对于这泉水最初是为谁而造仍争论不休。",al={"纳克迈尼为何重要","什么是清澈圣水","荆棘谷圣泉"}},{q="圣泉具体位于何处？",a="它位于荆棘谷西岸，高踞在俯瞰南野人海岸的悬崖边上。",al={"纳克迈尼圣泉在哪里","如何找到纳克迈尼","纳克迈尼位置"}},{q="目前是谁控制着纳克迈尼圣泉？",a="一支充满敌意的娜迦探险队最近从海洋深入内陆，占领了这处神圣的水盆，并凶残地攻击任何靠近泉水的人。",al={"谁在纳克迈尼","纳克迈尼的怪物","纳克迈尼的娜迦"}},{q="为什么冒险者会被派往这处泉水？",a="旅行者和研究人员寻求圣泉的泉水用于强大的附魔、净化仪式和需要绝对纯净水的炼金配方。",al={"纳克迈尼任务","荆棘谷圣水任务","荆棘谷净水"}}},fp="19,322,14.571.0,43.288.0,40.121.0,47.153.0,40.168.0"}
P.entries["subzone:nesingwary-s-expedition"] = {n="奈辛瓦里远征队营地",s="奈辛瓦里远征队营地是一个质朴的狩猎营地，位于北荆棘谷，纳菲瑞提湖的正北面。该哨站由著名的矮人神射手赫米特·奈辛瓦里建立，旨在为那些想要在丛林中最凶猛的掠食者面前一试身手的猎人们提供一处集结地。",h="奈辛瓦里远征队营地是一个质朴的狩猎营地，位于北荆棘谷，纳菲瑞提湖的正北面。该哨站由著名的矮人神射手赫米特·奈辛瓦里建立，旨在为那些想要在丛林中最凶猛的掠食者面前一试身手的猎人们提供一处集结地。",kw={"营地","远征队","青山","赫米特","猎人","纳菲瑞提","奈辛瓦里","荆棘谷"},ang={["class:Hunter"]="对于神射手和兽王猎人来说，这个营地是一块试金石，你可以在这里磨练你的追踪技巧，挑战荆棘谷最致命的掠食者。",["race:Dwarf"]="看到赫米特·奈辛瓦里和卡兹莫丹的同僚登山者们在潮湿的热带荒野中开辟出一处繁荣的营地，这是矮人坚韧精神和狩猎热情的典型写照。"},sec={{t="丛林中的猎人哨站",b="这个偏远的营地坐落在纳菲瑞提湖北侧的河边，是大型狩猎者、追踪者和神射手们熙熙攘攘的避风港。赫米特·奈辛瓦里建立此营地是为了追踪荆棘谷的传奇野兽，他的周围聚集着诸如埃尔加丁爵士、艾耶克·罗欧克和巴尼尔·石罐等经验丰富的同僚。营地由雇佣神射手守卫，并由中立商人提供补给，无论阵营如何，这里欢迎任何懂得使用步枪或弓箭的人，将他们团结在追踪丛林中最致命掠食者的共同目标之下。"},{t="书页与掠食者",b="远征队营地的生活围绕着激烈的竞争和宏大的传奇故事展开。猎人们不断受到挑战，去精通追踪和猎杀丛林中原生的猎豹、迅猛龙和虎类，并最终挑战顶级猛兽。除了狩猎的快感外，营地还要应对其自身的一些小后勤灾难，最著名的是奈辛瓦里那份长篇手稿散落在荒野中，让营地的学者们急于找回每一章遗失的内容。"}},faq={{q="谁在管理奈辛瓦里远征队营地？",a="该营地由传奇的矮人大型野兽猎人赫米特·奈辛瓦里，协同几位资深神射手共同创立并领导。",al={"谁领导这个营地","奈辛瓦里营地领导者","谁负责这里"}},{q="为什么远征队会来到荆棘谷？",a="远征队前往荆棘谷是为了猎杀这片茂密丛林中最危险的野生动物，包括潜行的猎豹、极具攻击性的迅猛龙、凶猛的虎类，以及传奇的战利品野兽。",al={"他们在这里做什么","为什么奈辛瓦里在荆棘谷","营地目的"}},{q="奈辛瓦里远征队营地对联盟和部落都友好吗？",a="是的。该营地作为一个中立的狩猎组织运作。只要访客尊重营地，奈辛瓦里的雇佣枪手就会维持秩序，欢迎任何希望证明自己追踪技巧的联盟和部落猎人。",al={"奈辛瓦里是中立的吗","部落可以访问奈辛瓦里吗","联盟可以访问奈辛瓦里吗"}},{q="丢失的手稿书页背后的故事是什么？",a="赫米特·奈辛瓦里撰写了一部名为《荆棘谷的青山》的长篇狩猎回忆录。不幸的是，手稿的散页在荒野中遗失了，促使营地档案管理员巴尼尔·石罐招募旅人去寻回它们。",al={"荆棘谷的青山的故事","为什么书页会散落","巴尼尔·石罐的书"}}},fp="23,306,32.579.0,19.482.0,33.130.0,49.188.0,63.211.0,54.255.0"}
P.entries["subzone:nethander-stead"] = {n="奈杉德哨岗",s="奈杉德哨岗是一处位于希尔斯布莱德丘陵南海镇以东道路旁的废弃农场。这里曾是一座正常运作的人类农场，如今已沦为废墟，被泥头豺狼人部族完全占领。田野中长满了被称为“泥头花”的巨大白色蘑菇，这引起了被遗忘者炼金师的兴趣。",h="奈杉德哨岗是一处位于希尔斯布莱德丘陵南海镇以东道路旁的废弃农场。这里曾是一座正常运作的人类农场，如今已沦为废墟，被泥头豺狼人部族完全占领。田野中长满了被称为“泥头花”的巨大白色蘑菇，这引起了被遗忘者炼金师的兴趣。",kw={"泥头花","豺狼人","希尔斯布莱德","泥头","蘑菇","奈杉德","南海镇","哨岗"},ang={["faction:Alliance"]="这座被占领的农场令人不安地提醒着人们，南海镇的防线依然脆弱，野蛮的豺狼人就盘踞在东面的道路尽头。",["faction:Horde"]="需要潜入南海镇附近的这座农场，以收集皇家药剂师学会进行致命研究所需的泥头花。"},sec={{t="一处荒废的家园",b="奈杉德哨岗坐落在南海镇东部边界的视野之内，曾经是该地区农业带的重要组成部分。和东部丘陵的大部分地区一样，随着地区安全局势的恶化和野外部族的侵入，这座农场被废弃了。如今，这里是泥头豺狼人在丘陵地带唯一的栖息地。这些野兽居住在残破的篱笆和附属建筑之间，极其凶暴地驱赶着任何误入它们领地的旅行者。"},{t="泥头花",b="哨岗内无人打理的土壤为奇异真菌的生长提供了肥沃的温床。被称为“泥头花”的巨大苍白蘑菇覆盖了荒废的农田。这些真菌蕴含着强效的天然毒素，引起了塔伦米尔皇家药剂师学会的注意。药剂师们寻求直接从豺狼人领地采集的样本，用以蒸馏腐蚀性的药剂，这使得这个原本微不足道的农场成为了部落深入联盟领地进行秘密行动的目标。"}},faq={{q="奈杉德哨岗是什么？",a="奈杉德哨岗是位于希尔斯布莱德丘陵南海镇以东的一座废弃人类农场。它已经被一群充满敌意的泥头豺狼人完全占领。",al={"这个农场是什么","奈杉德哨岗信息","奈杉德哨岗在哪里"}},{q="现在是谁控制着奈杉德哨岗？",a="这座农场被泥头豺狼人部族所占据。这是希尔斯布莱德丘陵中该部族唯一的营地。",al={"谁住在这里","谁在奈杉德哨岗","这里有什么怪物"}},{q="田野里生长的巨大白色蘑菇是什么？",a="它们是泥头花，一种在哨岗荒废的土壤中茁壮成长的大型白色真菌。它们含有毒性成分，对于研究毒药的被遗忘者炼金师来说非常有价值。",al={"白色蘑菇","泥头蘑菇","泥头花"}},{q="为什么部落会关注这个荒废的农场？",a="塔伦米尔的药剂师林度恩需要生长在哨岗田野里的泥头花。它们强效的汁液是酿造痛苦药剂的重要试剂。",al={"部落为什么要来这里","被遗忘者的兴趣","部落奈杉德任务"}}},fx={a070b78c={q="奈杉德哨岗发生了什么？",a="奈杉德哨岗曾是一处宁静的人类农庄，为希尔斯布莱德和南海镇提供物资，后来泥嘴豺狼人入侵，这里便逐渐荒废。原来的人类农民不是被驱逐就是遭到杀害，田地无人照料，长满了奇异的菌类，豺狼人则将农庄据为己有。",al={"奈杉德哨岗的历史","奈杉德哨岗发生了什么","奈杉德哨岗为何被遗弃"}},["786285bb"]={q="奈杉德哨岗为什么被遗弃？",a="这座农场被泥嘴豺狼人部族占据。农民难以守住自己的土地，最终被这些凶悍的拾荒者赶走或屠杀，谷仓和房屋也在豺狼人占据期间逐渐腐朽。",al={"奈杉德哨岗为何荒废","农民为何离开奈杉德哨岗","是谁毁了奈杉德哨岗"}},b89e0e83={q="奈杉德哨岗危险吗？",a="危险。这里被泥嘴豺狼人占据，它们会凶狠地抵御外来者。任何人若离开南海镇以东的道路，进入这些杂草丛生的田地，都可能遭到凶暴豺狼人的围攻。",al={"奈杉德哨岗安全吗","奈杉德哨岗的危险","奈杉德哨岗的威胁"}}},fp="15,347,18.467.0,21.472.1,24.169.0,39.145.0,57.190.0,47.169.0"}
P.entries["subzone:nethergarde-keep"] = {n="守望堡",s="守望堡是一座防御森严的联盟据点，坐落于通往诅咒之地的道路高处的悬崖之上。它由联盟在第二次战争后建立，作为一名警惕的哨兵，守望着沉寂的黑暗之门以及弥漫在红色荒原上的混乱能量。如今，在暴风城的支持下，法师和驻军仍在此进行着孤独的守望，抵御着恶魔和挥之不去的腐蚀。",h="守望堡是一座防御森严的联盟据点，坐落于通往诅咒之地的道路高处的悬崖之上。它由联盟在第二次战争后建立，作为一名警惕的哨兵，守望着沉寂的黑暗之门以及弥漫在红色荒原上的混乱能量。如今，在暴风城的支持下，法师和驻军仍在此进行着孤...",kw={"诅咒之地","黑暗之门","堡垒","卡德加","肯瑞托","守望堡","暴风城"},ang={["class:Mage"]="对于奥术修行者来说，守望堡代表了肯瑞托数十年来对维度裂隙、裂隙封印以及阻挡邪能腐蚀熵增的研究成果。",["faction:Alliance"]="这座要塞是联盟最重要的前沿堡垒之一，它以鲜血和黄金为代价建立，以确保第一次和第二次战争的恐怖永远不会再次从传送门中倾泻而出。"},sec={{t="红色世界前的哨兵",b="第二次战争末期黑暗之门被毁后，大法师卡德加和洛丹伦联盟的领袖们意识到，艾泽拉斯绝不能再让这道裂隙处于无人看守的状态。建造者们辛勤劳作，在通往诅咒之地的峡谷通道沿线竖起了高耸的壁垒、营房和法师塔。这里由肯瑞托的法师驻守，其双重使命是持续监视这道破碎的传送门，并编织结界，防止焦土上的恶魔枯萎病向北蔓延进人类王国。"},{t="孤独的守望",b="当黑暗之门重新开启，联盟远征军冒险进入德拉诺时，卡德加和他的同伴们从背后封印了传送门，将守望堡留下来看守这片死寂的遗迹。二十年来，来自达拉然和法师区的学者们一直在分析传送门残留的能量、变异的当地动物以及恶魔入侵。随着达拉然在第三次战争中被毁，守望堡完全依赖来自暴风城的关键补给车队来供养其士兵和法师，让他们能够独自对抗萦绕在这片荒原上的恐怖。"}},faq={{q="守望堡为何而建？",a="它是在第二次战争后由大法师卡德加和洛丹伦联盟下令建造的，旨在防范来自德拉诺的另一次兽人入侵，并遏制诅咒之地不断蔓延的恶魔腐蚀。",al={"守望堡的目的","守望堡为何存在","守望堡历史"}},{q="谁建造了这座堡垒？",a="守望堡是在第二次战争后，在大法师卡德加的敦促下由洛丹伦联盟建立的，并主要由达拉然肯瑞托的巫师们驻守。",al={"谁建造了守望堡","守望堡建造者"}},{q="谁现在指挥和补给这座要塞？",a="该要塞最初由达拉然的肯瑞托负责维护，但在达拉然沦陷于天灾军团和燃烧军团之后，现在主要依靠暴风城王国提供军队、定期补给车队和后勤支持。",al={"谁在管理守望堡","守望堡补给","暴风城与守望堡"}},{q="要塞内的法师在研究什么？",a="来自法师区的研究人员正在研究黑暗之门的沉寂能量、困扰当地野生生物的奇怪突变，以及防御这片红色土地上挥之不去的邪能污染的方法。",al={"守望堡法师","法师区守望堡","他们在研究什么"}}},fp="16,406,32.543.0,16.556.0,31.211.0,25.173.0,43.223.0,44.205.0"}
P.entries["subzone:night-run"] = {n="夜道谷",s="夜道谷是灰谷中东部悬崖环绕的高地上的一处偏僻的小型萨特前哨站。这里栖息着恶魔化的邪鬃萨特，是一处在古老的精灵废墟中暗藏邪恶灵魂魔法的腐化营地。",h="夜道谷是灰谷中东部悬崖环绕的高地上的一处偏僻的小型萨特前哨站。这里栖息着恶魔化的邪鬃萨特，是一处在古老的精灵废墟中暗藏邪恶灵魂魔法的腐化营地。",kw={"灰谷","黑滩教派","弗伦河","邪鬃","夜道谷","萨特","灵魂宝石"},ang={["faction:Alliance"]="夜道谷坐落在林中树居的正北面，是一个时刻威胁着重要哨兵补给线的恶魔祸患。",["race:NightElf"]="夜道谷的沦陷是一道挥之不去的伤疤：这些古老的精灵遗迹如今成为了扭曲的邪鬃萨特的避难所。"},sec={{t="一处易守难攻的悬崖高地",b="夜道谷是灰谷三大萨特据点（另外两个是萨维亚和萨提纳尔）中规模最小、位置最偏远的一处。该定居点坐落在由陡峭且无法翻越的悬崖包围的高脊之上，掩映在崩塌的精灵石雕和断裂的柱子之间。前往此处需要沿着弗伦河绕行，经过萨维亚附近的水域，或者从林中树居上方的北侧险峻岩架穿行。尽管规模不大，但这一据点威胁巨大：居住于此的邪鬃萨特与阴影之中的黑滩教派勾结，通过将扭曲的灵魂宝石固定在这里，汇聚森林中的恶魔精华。"}},faq={{q="谁控制着夜道谷？",a="夜道谷由邪鬃萨特占领，这是一个隶属于黑滩教派、由腐化的暗夜精灵恶魔组成的阵营。",al={"居住在夜道谷的生物","夜道谷怪物","夜道谷有什么"}},{q="如何前往夜道谷？",a="因为它坐落在一处四周环绕着陡峭悬崖的高耸高地上，旅行者必须通过林中树居北侧的一条狭窄岩架，或者沿着弗伦河向萨维亚方向行进，然后向西攀上山脊。",al={"如何到达夜道谷","夜道谷路径","夜道谷入口"}},{q="黑滩教派在这里做什么？",a="该教派与萨特合作，在夜道谷内维护着一颗黑暗灵魂宝石，用于收割并引导恶魔能量在灰谷各地流转。",al={"黑滩教派夜道谷","灵魂宝石夜道谷"}}},fx={["3ed13181"]={q="什么是夜道谷？",a="夜道谷是灰谷中东部一处高耸岬角上的小型隐秘萨特营地。它坐落在林中树居和碎木岗哨之间，是森林里三大萨特据点中最小的一处，几乎只剩下破碎的暗夜精灵石柱和古老石块，如今这些遗迹已被邪恶的恶魔腐化侵蚀。",al={"夜道谷概况","灰谷的夜道谷是什么地方","夜道谷营地"}},c4f1d276={q="夜道谷为何沦为废墟？",a="和灰谷许多古老建筑一样，夜道谷的古典暗夜精灵石柱与地基早已在很久以前坍塌，只剩下摇摇欲坠的石墙，供萨特们充作简陋的藏身之所。",al={"夜道谷为何被毁","夜道谷遗迹","是什么毁了夜道谷"}},["2a13d550"]={q="夜道谷危险吗？",a="夜道谷对粗心的旅人来说极其危险。岬角由邪绒萨特严密看守，他们对所有外来者都抱有敌意，并与黑暗海岸教派阴险的暗影议员结盟。周围是险峻陡峭的悬崖，一旦遭遇恶魔魔法，几乎没有周旋的余地。",al={"夜道谷有多危险","夜道谷的威胁","夜道谷安全吗"}}},fp="9,235,26.643.0,23.130.0,27.228.0,47.138.0"}
P.entries["subzone:night-web-s-hollow"] = {n="夜行蜘蛛洞穴",s="夜行蜘蛛洞穴是一处位于提瑞斯法林地，丧钟镇西北方向的低洼地带和废弃金矿。这里充斥着蛛形纲生物，是新苏醒的被遗忘者进行试炼的场所，他们被派往此处清除害虫，以证明自己的战斗能力。",h="夜行蜘蛛洞穴是一处位于提瑞斯法林地，丧钟镇西北方向的低洼地带和废弃金矿。这里充斥着蛛形纲生物，是新苏醒的被遗忘者进行试炼的场所，他们被派往此处清除害虫，以证明自己的战斗能力。",kw={"丧钟镇","矿井","夜行蛛后","夜行蜘蛛洞穴","蜘蛛","提瑞斯法林地"},ang={["profession:Mining"]="虽然这些矿井最初是为了开采黄金而挖掘的，但由于致命的蛛形生物泛滥，这里的采矿作业早已停止。",["race:Undead"]="对于刚复活的被遗忘者来说，这处洞穴是你的首批试炼之一。猎杀这些蛛形生物可以证明你拥有效忠黑暗女王所需的专注与意志。"},sec={{t="被侵扰的矿坑",b="Tucked away in the northern hills of Deathknell, Night Web's Hollow was once an ordinary human gold mine before the plague swept through Lordaeron. In the aftermath of the kingdom's fall, the shafts were entirely abandoned to nature. Today, thick strands of webbing shroud the rock walls and suffocating shadows conceal a thriving colony of aggressive night web spiders. Freshly raised Forsaken are routinely dispatched into the hollow and its subterranean tunnels to cull the young and adult spiders so the Forsaken can regain access to the mine's gold."}},faq={{q="夜行蜘蛛洞穴是什么地方？",a="这是一座废弃的金矿，位于丧钟镇西北方的一处小型峡谷。这里蛛网丛生，游荡着大量具有攻击性的蜘蛛，是新兵被遗忘者最早的试炼场之一。",al={"夜行蜘蛛洞穴","丧钟镇蜘蛛矿洞","提瑞斯法蜘蛛洞"}},{q="为什么被遗忘者要清理这些蜘蛛？",a="被遗忘者需要矿井里的黄金，但只要蜘蛛占据着隧道，他们就无法进入。执行官阿伦人手不足，因此他要求新兵协助逐步清除这些虫害。",al={"为什么要杀蜘蛛","丧钟镇蜘蛛任务"}},{q="矿井深处有什么？",a="当幼年蜘蛛在洞穴外乱爬时，成年的夜行蜘蛛会在矿井隧道中潜行。在最深、最黑暗的洞室里，盘踞着整个虫群的母体——夜行蛛后。",al={"矿洞蜘蛛首领","夜行蛛后位置"}},{q="这里一直都是蜘蛛窝吗？",a="并不是。在洛丹伦陷落之前，这里是当地人类民众开采黄金的矿场。天灾军团摧毁了该地区后，矿井年久失修，蜘蛛便搬进了阴暗、隐蔽的隧道中。",al={"谁挖掘了矿井","丧钟镇矿井历史"}}},fx={["132bc2d1"]={q="夜行蜘蛛洞穴里住着谁？",a="这里没有文明种族居住。洞穴和古老矿道完全被凶猛的夜行蜘蛛占据。洞外，年幼的蜘蛛在阴暗的山谷中四处爬行；成年蜘蛛和体型庞大的母蜘蛛则在幽暗的矿井深处筑巢。",al={"夜行蜘蛛洞穴里住着谁","夜行蜘蛛洞穴的居民","夜行蜘蛛洞穴里有什么"}},["3ed77784"]={q="夜行蜘蛛洞穴里的矿井为何废弃了？",a="和提瑞斯法林地的许多地方一样，这座古老的金矿在第三次战争期间沦为废墟，当时天灾瘟疫蹂躏了洛丹伦王国。矿工或死或散，矿道就此荒废，当地蜘蛛趁机占据了洞穴，并在深处织起蛛网。",al={"夜行蜘蛛洞穴为何废弃","夜行蜘蛛矿井为何废弃","金矿发生了什么"}},["8db143d3"]={q="夜行蜘蛛洞穴危险吗？",a="这里对刚刚苏醒的被遗忘者确实构成威胁。路边落单的幼蛛尚可应付，但矿井内部挤满了带毒的成年蜘蛛，最深处还潜伏着凶残的母蜘蛛。",al={"夜行蜘蛛洞穴危险吗","夜行蜘蛛洞穴有多危险","夜行蜘蛛洞穴的危险"}},["2ca4d435"]={q="为什么叫夜行蜘蛛洞穴？",a="这座山谷直接以遍布洞穴和废弃矿井的夜行蜘蛛而得名，它们织下厚重阴暗的蛛网。蔓延开来的巢穴堵塞了整座山谷，也让这条荒凉的峡谷有了这个令人胆寒的名字。",al={"为何叫夜行蜘蛛洞穴","夜行蜘蛛洞穴名称由来","夜行蜘蛛洞穴是怎么得名的"}}},fp="18,266,17.554.0,27.197.0,46.197.0,39.208.0,29.221.0"}
P.entries["subzone:nighthaven"] = {n="永夜港",s="永夜港是坐落在月光林地月神湖北岸的一处隐秘定居点。作为塞纳里奥议会的心脏，这里是一处避风港，暗夜精灵和牛头人德鲁伊可以在此和平共处，潜心研习，远离艾泽拉斯的阵营战争。",h="永夜港是坐落在月光林地月神湖北岸的一处隐秘定居点。作为塞纳里奥议会的心脏，这里是一处避风港，暗夜精灵和牛头人德鲁伊可以在此和平共处，潜心研习，远离艾泽拉斯的阵营战争。",kw={"塞纳里奥议会","德鲁伊","月神湖","洛甘纳尔","春节","月光林地","永夜港","remulos"},ang={["class:Druid"]="永夜港是你远离家乡后的精神家园。通过“传送：月光林地”技能，你可以立即前往会见职业导师、进行动物形态试炼，并获得前往鲁瑟兰村或雷霆崖的独特飞行连接。",["profession:Herbalism"]="永夜港是一处宁静之地，你可以在月光林地静谧的树林间咨询草药学训练师。"},sec={{t="塞纳里奥议会的避难所",b="永夜港依傍着月神湖宁静的湖岸而建，采用了传统的暗夜精灵建筑风格，是一处远离尘世喧嚣的静谧休憩之所。在这里，月亮井为致力于维护自然平衡的林地和大厅洒下柔和的光辉。作为塞纳里奥议会的主要驻地，这里为德鲁伊学徒提供了导师、草药学训练师以及专业的供应商。该定居点保持着严格的中立，无论修行者效忠于联盟还是部落，这里都欢迎他们。"},{t="远古历史与神圣集会",b="永夜港的安宁在历史上曾多次受到考验。在上古之战结束后的几个世纪里，勇士们曾聚集于此对抗暴怒的半神欧门，将其驱逐至月神湖底。在春节期间，这座村庄也会敞开其隐秘的边界，欢迎来自艾泽拉斯各地的朝圣者，以缅怀先祖，并在艾露恩的注视下欢庆节日。"}},faq={{q="谁在统治或管理永夜港？",a="永夜港由塞纳里奥议会管理，在守护者Remulos和像洛甘纳尔这样的资深德鲁伊的指导下运作。它是一个独立、中立的避难所，而非暗夜精灵政府的领土。",al={"永夜港的管理者","永夜港的领袖","此处的负责人"}},{q="非德鲁伊可以访问永夜港吗？",a="可以。非德鲁伊可以通过木喉要塞的隧道到达月光林地，或者使用山谷中其他地方的公共飞行管理员，然后前往永夜港。村庄内的专属飞行管理员仅为德鲁伊提供服务。",al={"非德鲁伊能否进入永夜港","非德鲁伊如何到达这里"}},{q="为什么暗夜精灵和牛头人能在这里和平共处？",a="塞纳里奥议会致力于治愈自然和翡翠梦境，其重要性高于一切阵营政治。成员在月光林地内会宣誓保持中立，搁置联盟与部落的纷争，以平等的身份研习德鲁伊之道。",al={"为何此处禁止战斗","为什么允许牛头人在此","部落与联盟的和平"}},{q="从永夜港出发有哪些飞行路线？",a="塞纳里奥专属飞行管理员为德鲁伊提供直达旅程：角鹰兽为联盟提供返回鲁瑟兰村的交通，而双足飞龙则载着部落德鲁伊返回雷霆崖。",al={"永夜港的飞行管理员","此处可前往何处"}}},fp="10,253,34.541.0,37.385.0,33.224.0,32.202.0,63.228.0,49.198.0"}
P.entries["subzone:nightmare-vale"] = {n="噩梦谷",s="噩梦谷是位于提瑞斯法林地西南部的一处阴暗洼地，就在Crusader's Outpost的西面。这里曾经是一片郁郁葱葱的森林避风港，但如今树木已在枯萎的凋零之火下枯萎，凶猛的掠食者在扭曲的树干间游荡。",h="噩梦谷是位于提瑞斯法林地西南部的一处阴暗洼地，就在Crusader's Outpost的西面。这里曾经是一片郁郁葱葱的森林避风港，但如今树木已在枯萎的凋零之火下枯萎，凶猛的掠食者在扭曲的树干间游荡。",kw={"暗色猎犬","噩梦谷","缝补者雷桑","提瑞斯法林地","吸血蝙蝠"},ang={["class:Hunter"]="山谷中栖息着凶猛的暗色猎犬和吸血蝙蝠，其中包括稀有的白蝙蝠“缝补者”雷桑，这使其成为寻求可怕野兽的猎人们值得一去的试炼场。",["race:Undead"]="噩梦谷扭曲的野生动物提醒着人们瘟疫在提瑞斯法留下的持久印记，对离开布瑞尔冒险的被遗忘者旅行者构成了直接威胁。"},sec={{t="一片腐朽的荒野",b="在第三次战争之前，这片山谷是提瑞斯法乡村中一片青翠的地带，到处是鸣禽和常见的林地野味。在天灾军团的瘟疫之后，植被已经发黑腐烂。贪婪的暗色猎犬和巨大的吸血蝙蝠吞噬了当地的野生动物，将这片洼地变成了食腐动物和猛兽的阴森巢穴。"},{t="洼地的潜行者",b="在噩梦谷的阴影中潜伏着“缝补者”雷桑，这是一只体型异常巨大、通体苍白的吸血蝙蝠，在当地旅行者中臭名昭著。这片山谷夹在闹鬼的荒野和附近Crusader's Outpost狂热的哨兵之间，是一片冷酷无情的区域，粗心的冒险者很快就会成为猎物。"}},faq={{q="噩梦谷在哪里？",a="噩梦谷位于提瑞斯法林地的西南部边缘，藏在Crusader's Outpost的西面。",al={"噩梦谷位置","噩梦谷在哪里","寻找噩梦谷"}},{q="为什么这片山谷被称为噩梦谷？",a="这片山谷曾经是一片宁静、充满生机的森林，但在摧毁洛丹伦的瘟疫中彻底沦陷。它枯萎的树木和具有攻击性的掠食者——饥饿的暗色猎犬和嗜血的蝙蝠——使得经过这里的每一个人都仿佛置身于清醒的噩梦之中。",al={"为什么叫噩梦谷","噩梦谷背景故事"}},{q="什么生物在噩梦谷出没？",a="这片山谷里到处都是凶猛的暗色猎犬和巨大的吸血蝙蝠，它们已经驱逐或吞噬了当地的森林动物。罕见的白色吸血蝙蝠，“缝补者”雷桑，也在这个洼地中徘徊。",al={"噩梦谷怪物","噩梦谷里的怪物","这里的野兽"}},{q="“缝补者”雷桑是谁？",a="“缝补者”雷桑是一只稀有的、通体雪白的吸血蝙蝠，以在噩梦谷阴暗的天空和枯萎的树冠下潜行而闻名。",al={"雷桑","缝补者雷桑","提瑞斯法稀有蝙蝠"}}},fx={["5ff12c50"]={q="什么是噩梦谷？",a="噩梦谷是提瑞斯法林地西南部一片宽阔的荒芜山谷。这里曾是繁茂的森林，栖息着生机盎然的林地生物，如今却已彻底衰败。树木枯萎凋零，曾经宁静的林间空地变成了荒凉的猎场，贪婪的黑暗猎犬和巨型吸血蝙蝠在此出没。",al={"什么是噩梦谷","噩梦谷背景","介绍一下噩梦谷"}},["2fb13922"]={q="噩梦谷发生了什么？",a="和提瑞斯法林地的许多地方一样，噩梦谷也未能逃过席卷洛丹伦的毁灭性瘟疫与腐化。茂密的树冠在疫病侵袭下枯萎死去，本土野生动物也消失了，被腐化的捕食者取代或吞噬。如今，这里成了王国覆灭的凄凉见证。",al={"噩梦谷历史","噩梦谷是如何衰败的","这里发生了什么"}},["9de72d2c"]={q="噩梦谷危险吗？",a="是的，噩梦谷对独行旅人构成严重威胁。山谷里到处都是贪婪的黑暗猎犬和巨型吸血蝙蝠，它们会猎杀任何闯入这片枯林的生物。此外，臭名昭著的凶猛白蝙蝠“针刺者”雷萨恩也常在阴影中出没。",al={"噩梦谷有多危险","这里安全吗","噩梦谷的威胁"}}},fp="14,238,20.366.0,22.325.0,32.111.0,40.250.0,35.196.0,26.126.0"}
P.entries["subzone:nightsong-woods"] = {n="夜歌森林",s="夜歌森林构成了灰谷饱受战火蹂躏的东部广袤地带，从林中树居一直延伸至艾萨拉的边界。这里是守卫神圣森林的暗夜精灵与为部落采伐木材的战歌氏族之间的主要战场。在森林阴影笼罩的林间空地上，古老的丛林与设防的营地在挥之不去的恶魔腐蚀中激烈交锋。",h="夜歌森林构成了灰谷饱受战火蹂躏的东部广袤地带，从林中树居一直延伸至艾萨拉的边界。这里是守卫神圣森林的暗夜精灵与为部落采伐木材的战歌氏族之间的主要战场。在森林阴影笼罩的林间空地上，古老的丛林与设防的营地在挥之不去的恶魔腐蚀...",kw={"灰谷","弗伦河","夜歌森林","萨提纳尔","银翼要塞","碎木岗哨","战歌伐木营地"},ang={["faction:Horde"]="这条东部战线通过碎木岗哨获取至关重要的建筑木材和战略补给路线，因此必须时刻警惕哨兵的伏击和恶魔野兽。",["race:NightElf"]="夜歌森林是一片处于围困之中的神圣边境；保护其古老的丛林免受战歌氏族斧头的砍伐，并清除残存的萨特腐化，是卡多雷义不容辞的基本职责。"},sec={{t="饱经战火的森林",b="夜歌森林横跨灰谷向东延伸至艾萨拉，其特征是不断升级的暴力冲突。弗伦河横贯西部地区，在联盟定居点和部落的蚕食之间划出了一条动荡的边界。向东深入，森林在激烈的争夺中支离破碎，碎木岗哨在这里协调着部落针对银翼要塞的军事行动。兽人的斧头不断伐倒南部的丛林，以支持部落的扩张，留下的开垦痕迹让卡多雷愤怒不已。更糟糕的是，诸如萨提纳尔和萨维亚的萨特据点，以及屠魔峡谷和冥火岭中残存的恶魔势力，正在侵蚀着这片东部的林冠。"}},faq={{q="夜歌森林位于何处？",a="夜歌森林涵盖了灰谷的东半部。其边界从林中树居和通往费伍德森林的北路一直延伸到东侧未开发的艾萨拉边界。",al={"夜歌森林位置","夜歌森林在哪里","灰谷东部森林"}},{q="为什么灰谷的这一区域战斗如此频繁？",a="该地区处于银翼要塞与战歌氏族冲突的前线。部落严重依赖从南部树木中采伐的茂密木材来建造和维持他们的定居点，而暗夜精灵则奋力抵抗这种乱砍滥伐，并试图夺回他们祖先的土地。",al={"为什么夜歌森林有战斗","灰谷部落与联盟冲突","战歌氏族冲突"}},{q="谁控制着夜歌森林？",a="没有单一派系能统治这片森林。弗伦河大致将西部的联盟领土与东部以碎木岗哨和战歌伐木营地为核心的部落阵地分隔开来。森林中还有部分地区被萨提纳尔和萨维亚的堕落萨特，以及屠魔峡谷附近的军团势力所占据。",al={"谁拥有夜歌森林","夜歌森林派系控制权"}},{q="这里存在哪些恶魔威胁？",a="东部的荒野深受恶魔和腐化力量的影响。萨特居住在诸如萨提纳尔和萨维亚这样设防的古老遗迹中，而残留的燃烧军团爪牙则盘踞在冥火岭和屠魔峡谷深处。",al={"夜歌森林的恶魔","灰谷东部的萨特","冥火岭恶魔"}}},fx={["93727362"]={q="夜歌森林发生过什么？",a="夜歌森林曾是古老灰谷中一片未受侵扰的区域。第三次战争期间，战歌氏族开始砍伐这里的圣木，森林随之沦为惨烈的战场。附近的兽人饮下玛诺洛斯之血后，冲突又引发了恶魔腐化。燃烧军团战败后，森林依然未能恢复平静：战歌氏族在伐木营地永久驻扎，与银翼要塞不断发生冲突，战火至今仍在摧毁森林。",al={"夜歌森林的历史","夜歌森林背景","夜歌森林历史"}},["74998be0"]={q="夜歌森林危险吗？",a="这里或许是灰谷最危险的一片区域。除了部落的战歌先遣骑和联盟的银翼要塞守卫不断交战，萨特也盘踞在萨提纳尔和萨维亚等据点。更东边的冥火岭和屠魔峡谷仍有恶魔残党巡逻。任何夹在这些交战前线之间的旅人，都可能遭到任一阵营伏击，或被燃烧军团残留的爪牙毁灭。",al={"夜歌森林有多危险","夜歌森林的危险","夜歌森林安全吗"}}},fp="15,388,22.678.0,38.187.0,56.319.0,29.325.0,32.240.0"}
P.entries["subzone:nijel-s-point"] = {n="尼耶尔前哨站",s="尼耶尔前哨站是坐落在凄凉之地北部峭壁高处的一处联盟与塞纳里奥议会的防御据点。它远离下方被枯萎侵蚀的山谷，成为了联盟旅行者、研究人员和士兵在荒原中穿行时唯一的安全港湾。",h="尼耶尔前哨站是坐落在凄凉之地北部峭壁高处的一处联盟与塞纳里奥议会的防御据点。它远离下方被枯萎侵蚀的山谷，成为了联盟旅行者、研究人员和士兵在荒原中穿行时唯一的安全港湾。",kw={"安东修士","半人马","凄凉之地","玛兰蒂斯","玛拉顿","尼耶尔前哨站","前哨站","本迪加斯"},ang={["class:Druid"]="玛兰蒂斯守望者利用这处高山避难所，组织力量去回收玛拉顿内部腐化中滋生的扎尔塔遗骸。",["faction:Alliance"]="尼耶尔前哨站是你在凄凉之地唯一的防御避难所和飞行中转站，连接着石爪山脉、塞拉摩和菲拉斯之间的补给线。"},sec={{t="荒原之上的堡垒",b="尼耶尔前哨站开凿于毗邻石爪山脉的陡峭悬崖之中，高居于凄凉之地的灰色尘埃和四处劫掠的半人马部族之上。这处定居点由本迪加斯上尉率领的暴风城军队分遣队驻守，负责监视那些威胁到联盟在卡利姆多南部利益的激烈部族战争。其高海拔和狭窄的通路使其易守难攻，为往返于石爪峰、塞拉摩和羽月要塞之间的信使、斥候和狮鹫骑士提供了安全的补给中转站。"},{t="塞纳里奥与十字军的远征",b="除了暴风城的驻军外，这个前哨站还庇护着一些怀揣不同且危险目的的使者。玛兰蒂斯守望者和他的树妖们以此营地作为行动基地，深入玛拉顿对抗瑟莱德丝公主，试图寻回陨落的半神扎尔塔。就连血色十字军也在此地派驻了一名使者——安东修士，他致力于清除肆虐在谷底的亡灵。尽管士兵和德鲁伊们在这里往来穿梭，但“尼耶尔”究竟是谁，对于那些驻守在山脊上的人们来说，仍是一个被岁月遗忘的古老谜团。"}},faq={{q="为什么联盟会驻扎在凄凉之地？",a="本迪加斯上尉率领一支暴风城军队分遣队在此监视交战的半人马氏族。联盟担心，一旦某个氏族消灭了其他氏族，胜利的部落大军就会将其侵略目标转向邻近的领土和定居点，例如石爪山脉和菲拉斯。",al={"为什么联盟在这里","凄凉之地的暴风城军队","尼耶尔前哨站存在的原因"}},{q="尼耶尔是谁？",a="前哨站里似乎没人知道。他真实的过往早已湮没在历史长河中。",al={"谁是尼耶尔","尼耶尔背景故事","尼耶尔前哨站是以谁命名的"}},{q="塞纳里奥议会在尼耶尔前哨站做什么？",a="玛兰蒂斯守望者和他的树妖姐妹来到凄凉之地，目的是肃清玛拉顿，击杀瑟莱德丝公主，并寻回扎尔塔的遗骸，将其送回石爪山脉的神圣林地。",al={"尼耶尔前哨站的德鲁伊","玛兰蒂斯守望者的任务","为什么树妖在这里"}},{q="为什么血色十字军会在尼耶尔前哨站？",a="安东修士担任血色十字军的一名外派使者。暴风城的克罗雷修士会派遣联盟冒险者去见他，而他则会考验这些冒险者在对抗白骨之谷中肆虐的亡灵时的决心。",al={"安东修士与血色十字军","凄凉之地的血色十字军"}}},fp="13,281,26.564.0,32.548.0,42.271.0,14.76.0,51.202.0,44.216.0"}
P.entries["subzone:north-coast"] = {n="北部海岸",s="北部海岸是一片阴暗、雾气缭绕的海岸线，标志着提瑞斯法林地沿着无尽之海的北缘。在洛丹伦沦陷后，这里受到腐蚀，寒冷的沙滩上布满了腐烂的海洋生物，并由敌对的鱼人部落强力守卫。",h="北部海岸是一片阴暗、雾气缭绕的海岸线，标志着提瑞斯法林地沿着无尽之海的北缘。在洛丹伦沦陷后，这里受到腐蚀，寒冷的沙滩上布满了腐烂的海洋生物，并由敌对的鱼人部落强力守卫。",kw={"海滩","迪布","无尽之海","鱼人","北部海岸","提瑞斯法林地","邪鳍"},ang={["race:Undead"]="虽然被遗忘者的巡逻路线紧贴着穿过布瑞尔的道路，但清除北部海岸入侵的鱼人可以确保提瑞斯法林地的北侧保持相对安全。"},sec={{t="凋零的海岸线",b="在第三次战争之前，这些北方的水域和多石的沙滩曾是洛丹伦宁静的北边界。当亡灵天灾横扫整个大陆时，其腐蚀性的瘟疫渗下了悬崖，毒害了海岸。水域变得冰冷浑浊，冲刷着巨型海洋生物的尸体，如今这些尸体在终年不散的海岸迷雾中，在沙滩上腐烂。"},{t="邪鳍之岸",b="随着人类王国破碎，被遗忘者将注意力集中在布瑞尔和洛丹伦王城周围，海岸鱼人便占据了这片荒凉的沙滩。当地的邪鳍鱼人部落在浪花边搭建了小屋，并将附近的浅滩用作产卵地。成群结队的贪婪鱼人，包括像迪布这样的知名人物以及无数正在成长的幼体，暴力地守护着潮汐线，抵御任何地表生物。"}},faq={{q="北部海岸栖息着什么生物？",a="海滩主要被好斗的邪鳍鱼人、它们的幼体以及在从无尽之海冲刷上岸的腐烂海洋生物中觅食的食腐动物所占据。",al={"北部海岸怪物","北部海岸有什么生物"}},{q="迪布是谁？",a="迪布是一名鱼人个体，可以在北部海岸的海岸小屋和浅滩附近徘徊时找到他。",al={"迪布","鱼人迪布","迪布是谁"}},{q="为什么海岸上到处都是腐烂的尸体？",a="摧毁了洛丹伦的亡灵瘟疫渗入了沿海生态系统，毒害了周围的浅滩，导致死去的海洋巨兽被冲上岸，在被腐蚀的沙滩上腐烂。",al={"死去的海洋巨兽","提瑞斯法搁浅的鲸鱼","为什么有死去的生物"}},{q="北部海岸有任何主要派系争夺吗？",a="无论是被遗忘者还是联盟的残余势力，都没有在北部海岸驻军。它仍然是一片狂野、未被驯服的边缘地带，主要留给了鱼人和海洋害虫。",al={"谁拥有北部海岸","被遗忘者在北部海岸的驻扎情况"}}},fx={["8e1fe0f4"]={q="什么是北部海岸？",a="北部海岸是提瑞斯法林地北部边界沿岸的一片荒凉海滩，与无尽之海接壤。洛丹伦遭受亡灵瘟疫蹂躏时，这里也受到了污染；冰冷的海水将腐烂的海洋生物冲上岸，沙滩上散布着敌对沿岸鱼人的简陋棚屋。",al={"什么是北部海岸","北部海岸概况","北部海岸简介"}},bb9c4791={q="北部海岸发生了什么？",a="北部海岸曾是洛丹伦北部一处宁静的海滨，后来和王国其他地区一样，遭到了亡灵瘟疫的侵袭。疫病污染了海水和海洋生物，海滩上遍布死去的海兽，凶暴的鱼人部族则趁机占据了这片受污染的沙地。",al={"北部海岸历史","这里发生了什么","北部海岸背景"}},["5791ac67"]={q="北部海岸危险吗？",a="是的。海滩上到处都是凶残的鱼人，包括当地的邪鳍部族及其同族。他们会拼死守卫简陋的聚居地和附近的产卵场。这些凶悍的两栖生物成群出没，加上瘟疫残留的阴寒，粗心的旅人很快就会被包围并杀死。",al={"北部海岸危险吗","北部海岸的威胁","北部海岸的危险"}}},fp="11,272,20.385.0,18.410.0,39.165.0,12.119.0,46.192.0,51.162.0"}
P.entries["subzone:north-gate-outpost"] = {n="北门哨岗",s="北门哨岗是一座坚固的矮人营地，坐落在丹莫罗的北门小径高处。它扼守着铁炉堡冰雪覆盖的心脏地带与洛克莫丹之间崎岖的通道，驻扎在此的山地探险队员保护着过往的旅人，免受遍布于岩壁间的敌对野兽侵扰。",h="北门哨岗是一座坚固的矮人营地，坐落在丹莫罗的北门小径高处。它扼守着铁炉堡冰雪覆盖的心脏地带与洛克莫丹之间崎岖的通道，驻扎在此的山地探险队员保护着过往的旅人，免受遍布于岩壁间的敌对野兽侵扰。",kw={"丹莫罗","铁炉堡","洛克莫丹","山地探险队员","北门哨岗","北门小径"},ang={["race:Dwarf"]="这座哨岗展现了铁炉堡山地探险队员坚毅的职责，无论气候多么寒冷，亦或掠食者如何出没，他们始终坚守着这些严苛的高地隘口。",["race:Gnome"]="随着侏儒重新在丹莫罗各地定居，他们经常利用自己的智慧和枪法协助矮人驻军搜寻失踪的巡逻队。"},sec={{t="小径守卫",b="这个小型定居点位于北门小径中部，是丹莫罗的东北门户。驻扎在此的矮人山地探险队员负责清理通往洛克莫丹的山间隧道主干道上的野兽，并监视往来交通。恶劣的气候和陡峭的沟壑使巡逻任务变得十分危险，驻军经常请求过往旅人协助侦察周边山脊，寻找失踪的巡逻队和危险的掠食者。"}},faq={{q="北门哨岗的用途是什么？",a="它是一座山区军事检查站，负责保障北门小径的安全。北门小径是连接丹莫罗与洛克莫丹的北部通道。驻扎在这里的山地探险队员通过控制野兽数量，确保这条通道的贸易与通行顺畅。",al={"北门哨岗用途","北门哨岗的存在意义"}},{q="穿过小径的道路通往哪里？",a="向东穿过哨岗后的山间隧道可抵达气候温和的洛克莫丹山谷，向西则可通往卡拉诺斯和铁炉堡。",al={"北门小径通向哪里","穿过北门哨岗的道路"}},{q="为什么山地探险队员需要旅人的帮助？",a="积雪崖壁间的当地野生动物领地意识极强。几名山地探险队员在猎杀危险野兽时失踪于岩壁之中，迫使驻军不得不征召有能力的侦察者来查明他们的下落。",al={"北门哨岗任务","失踪的山地探险队员"}}},fx={c46f381d={q="什么是北门哨岗？",a="北门哨岗是丹莫罗最东北端的矮人聚居点。它坐落在北门小径的高处，位于连接西边丹莫罗和东边洛克莫丹山谷的重要山路旁，是为旅人和补给车队设立的设防检查站。",al={"什么是北门哨岗","北门哨岗背景","介绍一下北门哨岗"}},["650c30dc"]={q="谁住在北门哨岗，或负责管理这里？",a="哨岗由矮人山地斥候驻守，他们负责巡逻高山隘口，保障丹莫罗与洛克莫丹之间的通行安全。他们时刻警戒着冰封的道路，但恶劣天气和凶猛野兽不断威胁着这里，使人数不多的驻军疲于应对。",al={"北门哨岗有哪些人","谁管理北门哨岗","北门哨岗的居民"}},["5e6548b7"]={q="北门哨岗危险吗？",a="哨岗本身可以提供庇护，但周围的山道危机四伏。山地掠食者频频威胁哨岗外围，最近还有几名山地斥候在雪地中追踪出没于峭壁间的凶猛野兽时失踪了。",al={"北门小径危险吗","北门哨岗附近的危险","北门哨岗的威胁"}},aaf153dc={q="为什么叫北门哨岗？",a="哨岗以北门小径命名，这条北部山间通道正是它的守卫范围。哨岗位于这条交通要道的中央，是连接丹莫罗与洛克莫丹的北部关口。",al={"北门哨岗为何得名","北门哨岗名称","北门哨岗是怎么得名的"}}},fp="18,261,18.469.0,36.233.0,42.175.0,49.223.0"}
P.entries["subzone:north-gate-pass"] = {n="北门小径",s="北门小径是连接丹莫罗的雪山峻岭与洛克莫丹的起伏盆地的一条重要山间通道。它是卡兹莫丹群峰间的一条北部走廊，有一座坚固的矮人哨岗驻守于此。前往湿地北部低地的旅客经常会穿过这条高路。",h="北门小径是连接丹莫罗的雪山峻岭与洛克莫丹的起伏盆地的一条重要山间通道。它是卡兹莫丹群峰间的一条北部走廊，有一座坚固的矮人哨岗驻守于此。前往湿地北部低地的旅客经常会穿过这条高路。",kw={"丹莫罗","铁炉堡","洛克莫丹","山地探险队员","北门哨岗","北门小径","湿地"},ang={["faction:Alliance"]="这条隘口是连接矮人首都与前往湿地的北方联盟远征军的一条关键军事和补给走廊。",["race:Dwarf"]="对于往返于铁炉堡高大城门与洛克湖周边边境定居点之间的矮人来说，这条隘口是一个熟悉的、由岩石开凿而成的门槛，且有同僚山地探险队员在此驻守。"},sec={{t="群峰间的隘口",b="北门小径开凿在卡兹莫丹的陡峭岩壁之中，是连接丹莫罗高处冰封的山谷与洛克莫丹温带水域的北部动脉通道。旅客穿过陡峭的山间隧道，从西面走出，映入眼帘的便是洛克湖谷那广阔的景象。由于它位于通往湿地道路的必经之路上，这条隘口承担着大量矮人信使、商人和漫游冒险者的通行往来。它的战略价值由北门哨岗所保障，山地探险队员们在此保持警惕，防御穴居人和山地掠食者。"}},faq={{q="北门小径通向哪里？",a="这条隘口连接着丹莫罗东部和洛克莫丹西北部。沿着这条路继续向北绕过洛克湖，便可抵达通往湿地的山间隧道，这使得它成为了北方旅客的一个关键枢纽。",al={"北门小径通向哪里","北门小径目的地","穿越北门小径的路线"}},{q="什么在守卫这处隘口？",a="铁炉堡山地探险队直接在道路旁驻守着北门哨岗，监控过往旅客，并确保这条山路免受游荡的野兽和穴居人的骚扰。",al={"谁在守卫北门小径","北门小径守卫","北门矮人哨岗"}},{q="它与南门小径有何不同？",a="这两条隘口都通过开凿的隧道将丹莫罗与洛克莫丹连接起来，但北门小径位于北部，为前往湿地和北方领地的旅客提供了最直接的陆路通道。",al={"北门小径与南门小径的区别","北门与南门对比"}}},fx={c14f680d={q="什么是北门小径？",a="北门小径是穿过卡兹莫丹群峰的一条重要山道，连接西边丹莫罗的冰雪高地与东边洛克莫丹的低洼盆地。旅人和冒险者常走这条道路，前往下行通往湿地的山路。",al={"什么是北门小径","北门小径简介","北门小径信息"}},["8f6c351e"]={q="谁居住在北门小径，或负责管理这里？",a="北门哨岗驻扎的铁炉堡山地卫兵负责维护并守卫这条小径。这里没有常住的平民，但矮人守卫会巡逻并保护这条通道，确保盟友旅人能够往返于丹莫罗和洛克莫丹之间。",al={"谁控制北门小径","谁守卫北门小径","北门小径居民"}},a4ac9bea={q="为什么叫北门小径？",a="这条通道得名于北门哨岗。它的地理位置也使其成为穿越分隔丹莫罗与洛克莫丹的山脊的两条主要隧道中最北面的一条，与南面的南门小径相对。",al={"为什么叫北门小径","北门小径名称含义","北门之名的由来"}}},fp="15,332,25.629.0,32.231.0,21.178.0,42.212.0"}
P.entries["subzone:north-tide-s-hollow"] = {n="北流谷",s="北流谷是银松森林中一处崎岖的荒野凹地，位于瑟伯切尔正北面。这里被效忠于背叛者大法师阿鲁高的野性月怒狼人所盘踞，这片林间空地是这些潜伏在海岸丛林中的野兽的行动基地。",h="北流谷是银松森林中一处崎岖的荒野凹地，位于瑟伯切尔正北面。这里被效忠于背叛者大法师阿鲁高的野性月怒狼人所盘踞，这片林间空地是这些潜伏在海岸丛林中的野兽的行动基地。",kw={"阿鲁高","月怒","北流谷","瑟伯切尔","银松森林","狼人"},ang={["race:Undead"]="月怒狼人盘踞在北流谷，距离瑟伯切尔的位置近得令人不安，这对被遗忘者在银松森林的统治地位和后勤补给线构成了直接威胁。"},sec={{t="野性的立足点",b="北流谷隐藏在被遗忘者定居点瑟伯切尔以北的茂密树林中，被野蛮的月怒狼人所占据。这些通过大法师阿鲁高鲁莽的魔法被带入洛丹伦的野性狼人，在峡谷各处建立了简陋的营地。这些粗糙的庇护所仅由这些强悍野兽所需的最基本必需品构成，为它们提供了距离被遗忘者交通要道极近的前沿阵地。"},{t="影牙的阴影之下",b="与普通的丛林掠食者不同，北流谷的狼人听命于从影牙城堡散发出的邪恶意志。它们靠近西海岸线和穿过银松森林的主干道，对试图稳固该地区的被遗忘者信使和巡逻队构成了持续的威胁。"}},faq={{q="北流谷在哪里？",a="北流谷位于银松森林西部，就在被称为瑟伯切尔的被遗忘者前哨站北面，靠近海岸悬崖。",al={"北流谷位置","北流谷在哪里","峡谷位置"}},{q="北流谷里住着什么生物？",a="这片峡谷中到处都是月怒狼人，这些超自然的狼形野兽被束缚在大法师阿鲁高的疯狂意志之下。",al={"谁住在这里","北流谷的敌人","北流谷的怪物"}},{q="为什么狼人住在这里的简陋营地里？",a="尽管狼人凶残狂野，但月怒狼人仍保留了足够的狡诈来组织基础的营地。由于天生坚韧强悍，它们只需要最原始的避难所和生存必需品就能在洛丹伦的荒野中生存。",al={"狼人营地","为什么狼人有帐篷"}},{q="谁控制着该地区的狼人？",a="北流谷的月怒狼人效忠于大法师阿鲁高，是他将狼人召唤到了洛丹伦，并从影牙城堡指挥着它们。",al={"谁领导着狼人","狼人主人"}}},fx={["8d98927f"]={q="什么是北流谷？",a="北流谷是银松森林中的一处崎岖荒野谷地，位于瑟伯切尔以北。这里主要是凶暴的月怒狼人出没和扎营之地；在大法师阿鲁高的影响下，它们游荡于松林之间。",al={"什么是北流谷","北流谷信息","介绍北流谷"}},ebea75f3={q="北流谷危险吗？",a="危险，对独自行路的旅人来说尤其危险。谷中遍布凶残的月怒狼人，它们一见闯入者便会发动攻击。这些野兽在此地各处搭建了简陋的营地，使北流谷成为任何想要前往瑟伯切尔以北之地的旅人都必须谨慎面对的险境。",al={"北流谷安全吗","北流谷有多危险","北流谷的威胁"}}},fp="19,263,16.462.0,25.309.0,29.160.0,43.110.0,43.253.0,37.140.0"}
P.entries["subzone:north-tide-s-run"] = {n="北流海岸",s="北流海岸是银松森林西北部风起云涌的海岸线，紧邻无尽之海。这片沙滩上有一艘半沉的失事船只，是一处鲜为人知的隐秘试炼场，供寻求与水域和谐共处的旅行德鲁伊使用。",h="北流海岸是银松森林西北部风起云涌的海岸线，紧邻无尽之海。这片沙滩上有一艘半沉的失事船只，是一处鲜为人知的隐秘试炼场，供寻求与水域和谐共处的旅行德鲁伊使用。",kw={"水栖形态","德鲁伊试炼","无尽之海","北流海岸","沉船","银松森林"},ang={["class:Druid"]="对于牛头人德鲁伊来说，这片寒冷的海岸代表着一个至关重要的成人礼，这里存放着掌握海狮形态所必需的沉没试炼组件。",["race:Tauren"]="北流海岸远离莫高雷温暖的平原，是洛丹伦为数不多能让年轻牛头人在精神旅程早期前往的地方之一。"},sec={{t="孤寂之岸",b="北流海岸沿着银松森林的西北边缘延伸，由冰冷的沙滩、汹涌的浪潮和无尽之海的一角组成。这里最显眼的标志是浅滩上那艘半沉的失事船只，正摇摇欲坠地倾斜在水中。"},{t="海狮之水",b="尽管环境荒凉，但对于行走在塞纳留斯之道的部落新兵来说，北流海岸具有神圣的重要性。年轻的牛头人德鲁伊会被指引至此进行朝圣，找回被海浪卷走的沉没圣物，以此考验他们的肺活量和耐力，从而获得水栖形态的祝福。"}},faq={{q="什么是北流海岸？",a="它是银松森林的西北岸线和大陆架，毗邻无尽之海。其特征是沉船、潮汐水域以及荒凉、宁静的沙滩。",al={"北流海岸","北流海岸在哪里","这片海滩是什么"}},{q="为什么德鲁伊会来到北流海岸？",a="牛头人德鲁伊会在试炼期间前往此处朝圣，与海洋之灵交流。通过勇敢地潜入海岸附近的深处寻找遗失的坠饰碎片，他们可以获得变形为水栖形态的力量。",al={"银松森林海滩德鲁伊任务","银松森林水栖形态","为什么牛头人在这里"}},{q="水里的沉船是什么？",a="那艘失事船只是一艘半沉在沙滩外浅滩里的船骸。它的存在是为搜寻海岸的旅行者提供了一个导航标志。",al={"北流海岸沉船","银松森林海滩沉船","失事船只"}}},fx={["7c1c9724"]={q="北流海岸危险吗？",a="与银松森林闹鬼般的腹地相比，北流海岸相对平静，但绝非毫无危险。无尽之海冰冷的海水下暗藏深渊和危险的海洋生物，荒凉的海岸线上也有野兽徘徊。这里没有友善的庇护所，旅人只能暴露在北方海岸的种种险境之中。",al={"北流海岸安全吗","北流海岸的危险","北流海岸的威胁"}}},fp="16,260,14.260.0,22.304.0,25.178.0,39.219.0,37.164.0"}
P.entries["subzone:northdale"] = {n="北谷",s="北谷是位于东瘟疫之地圣光之愿礼拜堂以北，靠近奎尔萨拉斯边界的一处废墟定居点。这里曾经是一个繁荣的北方小镇，如今却已支离破碎，被女妖、暗影守望者和堕落的元素生物所占据。北谷最为人所知的身份，是泰兰·弗丁在此放弃白银之手骑士团，转而投向血色十字军狂热信仰的痛苦转折点。",h="北谷是位于东瘟疫之地圣光之愿礼拜堂以北，靠近奎尔萨拉斯边界的一处废墟定居点。这里曾经是一个繁荣的北方小镇，如今却已支离破碎，被女妖、暗影守望者和堕落的元素生物所占据。北谷最为人所知的身份，是泰兰·弗丁在此放弃白银之手骑士...",kw={"女妖","无眼守望者","弗丁","北谷","瘟疫之地","血色十字军","白银之手","泰兰"},ang={["class:Paladin"]="对于圣光的骑士来说，北谷是一座令人清醒的纪念碑，记录着信仰的丧失——这片土地，正是泰兰·弗丁为了追求复仇而抛弃白银之手的地方。",["race:Human"]="北谷烧焦的地基和游荡的女妖，代表了又一个被天灾军团屠戮并占领的洛丹伦社区。"},sec={{t="悲伤之镇",b="北谷坐落在圣光之愿礼拜堂以北的山丘之上，曾经是通往奎尔萨拉斯的北侧大道上一个宁静的社区。第三次战争使其化为残垣断壁，家园不再温存，居民也惨遭屠戮或流离失所。如今，哀嚎的女妖在破败的墙垣间游荡，隐形的无眼守望者潜伏在黑暗中，窥视着受诅咒的道路。就连附近的湖泊也未能幸免于瘟疫的侵蚀，水面上翻涌着扭曲且堕落的水元素。"},{t="被遗弃的誓言",b="在弗丁家族的悲剧史中，北谷有着黑暗的意义。洛丹伦陷落，白银之手骑士团解散后，年轻的泰兰·弗丁站在这些破碎的街道上，正式抛弃了他父亲的教诲。他认为白银之手的残部过于软弱，无法铲除亡灵天灾，于是放弃了自己的神圣职责，加入了激进的血色十字军——这一决定成为了血色十字军掌控壁炉谷的关键节点。"}},faq={{q="北谷发生了什么？",a="北谷在第三次战争中，当亡灵天灾横扫洛丹伦时被摧毁。这里的建筑被夷为平地，居民倒在了瘟疫之下，只留下一片石块堆砌的躯壳，如今被复仇的怨灵和堕落的元素所占据。",al={"北谷为什么会成为废墟","北谷历史","什么是北谷"}},{q="这里发生了什么重大事件？",a="泰兰·弗丁正是在这里宣布脱离白银之手骑士团。由于对洛丹伦的陷落感到绝望，他在此抛弃了圣骑士的誓言，并向新生的血色十字军宣誓效忠。",al={"泰兰·弗丁北谷","泰兰发生了什么","白银之手骑士团北谷"}},{q="如今有哪些生物在废墟中游荡？",a="城镇废墟中到处都是效忠于天灾军团的哀嚎女妖和肉眼不可见的无眼守望者。邻近的水域也遭到污染，充斥着堕落的水元素。",al={"北谷怪物","北谷敌人","北谷有什么"}},{q="北谷位于何处？",a="北谷位于东瘟疫之地的东北部，就在圣光之愿礼拜堂的北面，通往奎尔萨拉斯的萨拉斯小径东南方。",al={"北谷位置","北谷在哪里","寻找北谷"}}},fp="9,406,16.499.0,17.503.1,27.235.0,39.205.0,37.178.0,27.159.0"}
P.entries["subzone:northfold-manor"] = {n="诺斯弗德农场",s="诺斯弗德农场是一座破败的农业庄园，位于阿拉希高地的西北边缘。这里曾是激流堡陷落前一处繁荣的人类家园，而如今，辛迪加的犯罪分子占据了这片土地，并在进行着令人不安的黑暗勾当。",h="诺斯弗德农场是一座破败的农业庄园，位于阿拉希高地的西北边缘。这里曾是激流堡陷落前一处繁荣的人类家园，而如今，辛迪加的犯罪分子占据了这片土地，并在进行着令人不安的黑暗勾当。",kw={"阿拉希高地","血石","诺斯弗德农场","辛格","激流堡","辛迪加","托尔甘"},ang={["class:Shaman"]="笼罩在诺斯弗德农场上空的恶魔残余力量扰乱了自然元素，使靠近这里的萨满祭司感到精神不安并引发炽烈的怒火。",["faction:Horde"]="落锤镇的萨满祭司们密切注视着诺斯弗德农场，并派遣勇士去夺取辛迪加用来涉足恶魔召唤的血石护身符。"},sec={{t="强盗巢穴",b="诺斯弗德农场坐落在索拉丁之墙隘口附近起伏的高地上，曾经支撑着激流堡王国。在该王国分崩离析后的混乱时期，流离失所的奥特兰克贵族和辛迪加的歹徒们占据了这里的庄园主屋、谷仓和农田，将其作为行动基地。辛迪加的雇佣兵、拦路强盗和寻路者们不再耕种作物，而是利用这个农场在道路上伏击过往行人，并协调他们在阿拉希各地的势力。"},{t="恶魔的阴影",b="在日常的盗窃和武装对抗背后，诺斯弗德农场还隐藏着更险恶的企图。恶魔召唤的残留气息笼罩着整个农场，该地区的敏感施法者和萨满祭司对此有着强烈的感知。地面上散落着被丢弃的血石护身符——这是一种用于驱动黑暗咒语的强大护身符——这表明这里的辛迪加盗贼正纠缠于超越普通强盗勾当的恶魔魔法之中。"}},faq={{q="是谁控制了诺斯弗德农场？",a="这座庄园已落入辛迪加之手。辛迪加是一个由失势的奥特兰克贵族、强盗和流氓雇佣兵组成的组织，他们现在将此地作为武装营地。",al={"谁住在这里","谁拥有诺斯弗德","辛迪加农场"}},{q="这里在进行什么黑暗魔法仪式？",a="对魔法能量敏感的访客可以探测到恶魔召唤的残留痕迹。驻扎在庄园里的辛迪加部队持有血石护身符，这些护身符被用来引导和辅助危险的恶魔仪式。",al={"诺斯弗德的恶魔","血石","他们正在召唤什么"}},{q="部落为什么关心这个农场？",a="落锤镇的巨魔萨满祭司托尔甘察觉到高地上正在酝酿一种反常的干扰。对源头的调查直接将他引向了诺斯弗德农场，这促使部落开始调查辛迪加的邪教活动。",al={"部落对诺斯弗德的兴趣","托尔甘为什么关心"}},{q="辛格是谁？",a="辛格是一个难以捉摸的辛迪加人物，偶尔能看到他潜伏在诺斯弗德农场的主屋内，混迹在其他强盗之中。",al={"辛格","辛格稀有","辛格是谁"}}},fp="15,292,17.469.0,18.439.1,29.183.0,40.212.0,40.232.0,14.133.0"}
P.entries["subzone:northpass-tower"] = {n="北地哨塔",s="北地哨塔是一座位于东瘟疫之地北部，通往奎尔萨拉斯道路上的洛丹伦废弃侦查哨塔。它在第三次战争中被摧毁，但至今仍俯瞰着通往精灵领地的北方大道。",h="北地哨塔是一座位于东瘟疫之地北部，通往奎尔萨拉斯道路上的洛丹伦废弃侦查哨塔。它在第三次战争中被摧毁，但至今仍俯瞰着通往精灵领地的北方大道。",kw={"东瘟疫之地","洛丹伦","北地哨塔","奎尔萨拉斯","天灾军团","侦查哨塔"},ang={["faction:Alliance"]="北地哨塔是洛丹伦陷落的堡垒之一，也是通往精灵领地的道路上一座破碎的哨兵。",["faction:Horde"]="对于部落而言，像北地哨塔这样的废墟展现了天灾军团是如何彻底摧毁北方王国的防御体系的。"},sec={{t="北方哨兵",b="北地哨塔由洛丹伦王国建造，旨在守卫通往奎尔萨拉斯的重要通道。在天灾军团入侵期间，这座哨塔沦为残垣断壁。尽管石墙已然破碎，但其高处的地势依然具有巨大的战略价值，俯瞰着斯坦索姆受诅咒的郊区与遥远的精灵领地之间那条被瘟疫笼罩的边境。"},{t="无声的守望",b="如今哨塔内已无驻军。它破碎的墙体伫立在一条如今受天灾军团盘踞的道路旁，提醒着人们洛丹伦曾经对通往奎尔萨拉斯的道路所进行的守望。"}},faq={{q="北地哨塔最初是为何而建的？",a="它最初由洛丹伦王国建造，作为观察哨所，用于监视通往奎尔萨拉斯精灵王国的北方道路。",al={"什么是北地哨塔","北地哨塔历史","北地哨塔为何而建"}},{q="为什么北地哨塔会成为废墟？",a="它在第三次战争的天灾军团入侵中，连同洛丹伦北部其他的防御设施一起被摧毁，只留下了残破的砖石和脚手架。",al={"谁摧毁了北地哨塔","北地哨塔为何破碎"}},{q="现在有人占据北地哨塔吗？",a="没有。这座哨塔在天灾军团入侵时与洛丹伦的北部防御体系一同被毁，如今作为一座空旷的废墟伫立在通往北方的道路旁。",al={"为何争夺北地哨塔","谁控制着北地哨塔"}},{q="经过北地哨塔的道路通向哪里？",a="这条路向北直通萨拉斯边境和奎尔萨拉斯的南部领土。",al={"经过北地哨塔的道路","北方道路通向哪里"}}},fp="15,233,17.375.0,14.172.0,46.154.0,32.167.0,37.149.0,46.101.0"}
P.entries["subzone:northridge-lumber-camp"] = {n="北山伐木场",s="北山伐木场是一座活跃的锯木厂，坐落在西瘟疫之地北部靠近壁炉谷的山丘之中。目前由血色十字军占领并加固，它为维持周边据点提供了至关重要的木材。联盟和部落都将此设施视为削弱这些狂热者地区基础设施的首要目标。",h="北山伐木场是一座活跃的锯木厂，坐落在西瘟疫之地北部靠近壁炉谷的山丘之中。目前由血色十字军占领并加固，它为维持周边据点提供了至关重要的木材。联盟和部落都将此设施视为削弱这些狂热者地区基础设施的首要目标。",kw={"壁炉谷","莱文","木材","锯木厂","北山","瘟疫之地","血色十字军","白蚁"},ang={["faction:Alliance"]="虽然血色十字军声称要对抗亡灵，但他们极端的排外主义使他们成为联盟在洛丹伦北部进行侦察和地区行动的一大威胁。",["faction:Horde"]="对于被遗忘者及其部落盟友来说，扰乱十字军的伐木行动可以削弱壁炉谷，并将这些狂热者逼回他们的据点。"},sec={{t="为十字军供能",b="北山伐木场位于壁炉谷下方的道路旁，是血色十字军至关重要的后勤枢纽。尽管挥之不去的瘟疫正在扼杀周边的森林，伐木场仍在砍伐和加工当地的木材，以建造防御工事、维修瞭望塔，并为十字军在洛丹伦的战争行动提供物资。该锯木厂由狂热的劳工和卫兵重兵把守，严密防范天灾军团和外来入侵者。"},{t="破坏目标",b="由于壁炉谷极度依赖这些木材来维持其防御，外部势力正积极密谋对其进行破坏。联盟指挥官和部落侦察兵都意识到，对加固的十字军阵地进行公开突袭代价高昂。相反，特工们倾向于采取非常规的破坏手段——例如将贪婪的蛀木白蚁释放到锯木厂的木材储备中——从内部悄然腐蚀十字军的补给。"}},faq={{q="谁控制着北山伐木场？",a="血色十字军目前控制并运营着该伐木场，利用其卫兵和劳工为附近的壁炉谷采伐木材。",al={"谁在运营北山","谁控制着锯木厂","北山派系"}},{q="为什么这座锯木厂很重要？",a="它为维持血色十字军在西瘟疫之地北部的防御工事和哨所提供了必要的木材和建筑材料。",al={"为什么北山很重要","北山的意义","这个营地是做什么的"}},{q="为什么联盟和部落想要破坏它？",a="双方阵营都认为激进且狂热的血色十字军是瘟疫之地中一个危险的威胁。剥夺他们的木材供应可以在无需付出高昂代价进行直接入侵的情况下，削弱他们加固壁炉谷的能力。",al={"为什么袭击北山","白蚁任务","为什么要毁掉木材"}},{q="第三次战争前是谁在经营这家锯木厂？",a="在洛丹伦王国陷落于天灾军团之前，当地的平民家庭居住在这里，并以这家锯木厂为业，过着宁静的地区生活。",al={"谁拥有北山伐木场","北山锯木厂的历史"}}},fp="22,356,19.470.0,19.440.0,36.139.0,34.158.0,50.218.0,38.134.0"}
P.entries["subzone:northshire-abbey"] = {n="北郡修道院",s="北郡修道院是一座历史悠久的修道院，坐落在艾尔文森林北部的山脚下，掩映在北郡山谷之中。在第一次战争中被毁后，它经过重建，如今已成为北郡兄弟会的精神核心，也是响应暴风城王国号召的新兵们的首要训练中心。",h="北郡修道院是一座历史悠久的修道院，坐落在艾尔文森林北部的山脚下，掩映在北郡山谷之中。在第一次战争中被毁后，它经过重建，如今已成为北郡兄弟会的精神核心，也是响应暴风城王国号召的新兵们的首要训练中心。",kw={"修道院","兄弟会","教士","迪菲亚","艾尔文","法奥","北郡","山谷"},ang={["class:Paladin"]="北郡代表了大主教阿隆苏斯·法奥和早期教士们的遗产，正是他们的牺牲为白银之手骑士团奠定了基础。",["race:Human"]="对于暴风城的人类来说，北郡修道院是你旅程的起点，在这里，王国韧性与奉献的历史欢迎每一位拿起武器的新兵。"},sec={{t="信仰与废墟的传承",b="几个世纪前，来自洛丹伦的牧师们向南跋涉，进入暴风城王国传播圣光的信仰，并建立了北郡教士圣职会及其修道院。这座修道院很快成为王国生活的重要支柱，这里的人们不仅照料病患，甚至在守护者麦迪文陷入昏迷的那些年里，也由他们负责照顾。在第一次战争中，修道院屡遭强盗和兽人部落的袭击，最终被彻底夷为平地。第二次战争中，洛丹伦联盟收复了该地区，大主教阿隆苏斯·法奥帮助重建了这座圣所，并将这里的守卫者重新组建为北郡兄弟会。"},{t="训练场",b="如今，北郡修道院已成为志愿者、民兵新兵和希望保卫饱受战火蹂躏的暴风城的初学者的基地。修道院分为大厅、Hall of Arms和图书馆侧翼，这里驻扎着教导武艺、奥术和神圣艺术的导师，而侦察兵和潜行者则在外面的院子里进行训练。尽管有白银之手骑士团的警惕守护，此地的和平依然脆弱。狗头人在附近的矿井肆虐，凶猛的狼群在果园游荡，迪菲亚潜行者的特工们则在山谷的道路上潜伏，掠夺着修道院珍藏的古老卷轴和神圣典籍。"}},faq={{q="什么是北郡兄弟会？",a="北郡兄弟会是一个宗教组织，由以北郡修道院为基地的教士、牧师和圣骑士组成。它最初由几个世纪前来自洛丹伦的传教士创立，在第一次战争后由大主教阿隆苏斯·法奥重建，旨在训练忠诚的保卫者并保存神圣的经文。",al={"谁管理北郡修道院","北郡教士","北郡兄弟会背景故事"}},{q="为什么北郡修道院在第一次战争中被摧毁？",a="在第一次战争中，这座修道院对暴风城具有战略和精神上的双重重要性。兽人军队煽动人类强盗对其发动攻击，在半兽人迦罗娜被短暂囚禁于此后，兽人部落发起了一场大规模的猛攻，将这片圣地夷为平地。在整个战争期间，它一直处于废墟状态，直到联盟驱逐了兽人氏族并对其进行了重建。",al={"谁摧毁了北郡修道院","第一次战争与北郡","北郡发生了什么"}},{q="为什么修道院外会有迪菲亚强盗和狗头人？",a="暴风城的军队忙于保卫遥远的边境，导致周边地区防守薄弱。投机的狗头人侵占了当地的金矿，而迪菲亚潜行者则利用防守空虚的机会抢劫过往行人，骚扰当地葡萄园，并洗劫修道院的图书馆以窃取奥术典籍和圣物。",al={"为什么北郡遭到攻击","北郡的狗头人","北郡外的迪菲亚"}},{q="北郡修道院和死亡矿井之间有什么联系？",a="在第一次战争期间，一位名叫图洛克的食人魔酋长从北郡修道院偷走了神圣的《神圣之书》，并退守到了死亡矿井中。安度因·洛萨爵士率领一支远征队深入矿井夺回这本神圣经文，结果被困其中，直到一支皇家救援队将他救出，并把经文归还给了修道院妥善保管。",al={"北郡的神圣之书","北郡与死亡矿井背景","安度因·洛萨与死亡矿井"}}},fx={a3256ecc={q="什么是北郡修道院？",a="北郡修道院是一处备受尊崇的圣所，坐落在艾尔文森林北部宁静的山麓。数百年前，来自洛丹伦的虔诚教士创建了这里。它是北郡兄弟会的精神中心。第一次战争后，修道院重建，如今既是招募中心，也是守卫暴风王国的新晋勇士接受考验之地。修道院历史悠久的厅堂中设有神圣魔法、武艺和奥术知识的训练师。",al={"什么是北郡修道院","关于北郡修道院","北郡修道院概况"}},d8226933={q="北郡修道院危险吗？",a="圣骑士和城镇卫兵仍将修道院守卫得十分严密，但周围的山谷正变得日益危险。附近的回音山矿洞已被狗头人占据，凶猛的狼在果园和森林中出没，迪菲亚潜行者的强盗也公然潜伏在葡萄园附近。新手冒险者在庭院中很容易站稳脚跟，但若毫无准备地在山谷中游荡，就可能突然遭遇危险。",al={"北郡安全吗","北郡修道院的危险","北郡山谷危险吗"}}},fp="16,322,26.656.0,20.618.0,38.314.0,52.351.0,59.321.0,66.320.0"}
P.entries["subzone:northshire-valley"] = {n="北郡山谷",s="北郡山谷坐落在艾尔文森林的北部群山之中，是暴风城王国新兵的摇篮与训练场，环境静谧安宁。山谷四周被天然屏障环绕，这里坐落着历史悠久的北郡修道院、肥沃的农场以及资源丰富的回音山矿洞。尽管表面上一派祥和，但山谷正面临着越来越大的不安，到处游荡的劫匪、横行的狗头人以及流离失所的掠食者都威胁着这里的安全。",h="北郡山谷坐落在艾尔文森林的北部群山之中，是暴风城王国新兵的摇篮与训练场，环境静谧安宁。山谷四周被天然屏障环绕，这里坐落着历史悠久的北郡修道院、肥沃的农场以及资源丰富的回音山矿洞。尽管表面上一派祥和，但山谷正面临着越来越大...",kw={"修道院","迪菲亚潜行者","回音山矿洞","艾尔文森林","狗头人","玛克布莱德","北郡山谷","北郡农场","willem"},ang={["faction:Alliance"]="北郡是大联盟关键的新兵征召与恢复基地，训练着下一代保卫者，以稳定王国的核心区域。",["race:Human"]="对于暴风城的人类来说，北郡山谷是他们踏上旅程的起点，来到修道院的庭院中，响应王国的召唤。"},sec={{t="一处避世的圣所",b="北郡山谷四周被几乎无法逾越的山脊所包围，唯一的出路是一条向南通往闪金镇和艾尔文森林其他地区的公路，那里设有一座戒备森严的门楼。一条清澈的小河蜿蜒穿过牧场，最后汇入南边的水晶湖。在山谷中心矗立着北郡修道院，这是一座古老的圣所，人们在此传授圣光之道，新兵们则由白银之手骑士团和经验丰富的老兵进行训练。在修道院围墙之外，坐落着物产丰饶的北郡农场和回音山矿洞，它们构成了一个自给自足的暴风城领地，仿佛远离了外界战火的纷扰。"},{t="潜伏的威胁",b="即使是这处避风港，也感受到了暴风城兵力吃紧带来的压力。治安官玛克布莱德和他的暴风城卫兵分遣队竭尽全力试图维持山谷的秩序。成群的狼从受到污染的暮色森林北上，在周边的树林里徘徊；而如害虫般的狗头人则占领了回音山矿洞的隧道。更糟糕的是，效忠于迪菲亚潜行者的蒙面暴徒们公开骚扰农场，并威胁到修道院的地界，迫使当地指挥官不得不征召每一位抵达大门且身体健康的平民。"}},faq={{q="为什么北郡山谷有重兵把守？",a="山谷内拥有北郡修道院，它是暴风城军队关键的信仰中心和训练场，此外还有回音山矿洞和农场等重要的本地资源。由于暴风城的军事力量捉襟见肘，治安官玛克布莱德在南侧隘口维持着一座戒备森严的门楼，以防威胁在山谷与艾尔文森林大部之间蔓延。",al={"为什么要守卫北郡","北郡的门楼","谁在保卫北郡"}},{q="山谷里的狼是从哪儿来的？",a="维里副队长指出，最近成群的狼越过了河流，从南边阴暗的暮色森林逃入了山谷。暮色森林中蔓延的黑暗迫使野兽逃离了栖息地，闯入了原本宁静的牧场。",al={"为什么有这么多狼","狼群出没","来自暮色森林的狼"}},{q="为什么狗头人要攻击回音山矿洞？",a="狗头人是机会主义的掘洞生物，被地下的矿脉所吸引。随着王国巡逻队的兵力减少，一群狗头人趁机占领了回音山矿洞，觊觎那里的黄金和蜡烛，并强行将人类矿工驱逐出了隧道。",al={"回音山矿洞的狗头人","为什么北郡有狗头人","狗头人问题"}},{q="那些骚扰农场的强盗是谁？",a="在米莉·奥斯沃斯农场附近活动的盗贼是迪菲亚潜行者的走狗。他们潜伏在山谷边缘地带，旨在破坏物资供应、骚扰当地农民，并试探修道院的防御。",al={"农场的强盗","北郡的迪菲亚","红面罩暴徒"}},{q="第二次战争期间北郡发生了什么？",a="在第二次战争期间，北郡修道院曾落入敌手，并一度被古尔丹的暮光之锤氏族用作指挥部，直到后来联盟收复并修复了山谷。",al={"北郡与第二次战争","北郡的暮光之锤","北郡的古尔丹"}},{q="如何离开北郡山谷？",a="徒步离开的唯一通路是向南穿过设有门楼的公路。通过这道大门，旅行者将直接进入艾尔文森林中部，沿着主路前往闪金镇。",al={"离开北郡","前往闪金镇的道路","如何离开"}}},fx={["9b50c77b"]={q="什么是北郡山谷？",al={"北郡山谷在哪里","介绍北郡山谷","我在北郡的哪里"}},["3a470446"]={q="北郡山谷属于暴风城吗？",a="是的。北郡山谷位于艾尔文森林腹地，而艾尔文森林是暴风王国的核心领土。这里的驻军高举暴风城的旗帜，执行暴风城的法律，并直接听命于王国的军事体系。",al={"北郡属于暴风城吗","暴风城拥有北郡吗"}},["52057ec0"]={q="为什么所有新兵都在北郡山谷训练？",a="山谷四周高崖环绕，是一处受保护且与外界隔绝的避风港，非常适合作为集结之地。经验丰富的元帅、各职业导师，以及北郡兄弟会的精神力量都集中在修道院，为新兵做好准备、迎接他们在更广阔森林中面临的挑战提供了一切所需。",al={"为什么在这里训练","新兵为什么来北郡"}},["0f9fef82"]={q="作为一名新兵，我为什么会在北郡山谷？",a="你响应了王国急需守卫者的号召而来。暴风城的正规军分散在各处争议边境，兵力捉襟见肘，因此当局开放了北郡修道院，训练所有愿意宣誓效忠、守护王国的勇士。",al={"我为什么在这里","新兵为何在此","是什么带我来到这里"}},["0fbb181a"]={q="什么是北郡修道院？",a="北郡修道院是一处古老的圣地，也是北郡兄弟会的历史中心。这个教团由圣光教会的传教士于数百年前创立。除了履行宗教职责，修道院还设有图书馆、武器大厅，以及供新近宣誓效忠的联盟勇士训练的住所。",al={"介绍北郡修道院","什么是修道院"}},["385ef21f"]={q="谁管理北郡修道院？",a="教士负责修道院的精神事务，驻地守备部队则由道格拉斯·麦克布莱德元帅指挥；他代表暴风城军队统筹整个山谷的防务。",al={"谁领导修道院","修道院负责人"}},ac0d723b={q="为什么教堂外驻扎着一支军队？",a="近来发生的祸患迫使军队直接驻扎在修道院的领地内。强盗占据了附近的葡萄园，狗头人也钻进了周边矿洞，教士们已无力在没有军队直接介入的情况下守护这片圣地。",al={"为什么修道院有士兵","为什么教堂有驻军"}},["2babcb98"]={q="北郡山谷一带由谁负责？",a="道格拉斯·麦克布莱德元帅负责北郡山谷的防务。他驻扎在修道院内，指挥守备部队，招募前来报到的新兵，并协调各方力量击退侵入山谷的威胁。",al={"这里由谁负责","北郡指挥官","谁管理北郡"}},["5231335a"]={q="麦克布莱德元帅听命于谁？",a="麦克布莱德元帅是为王室效力的暴风城军官。他在北郡的驻军属于艾尔文森林防务的一部分，与驻扎在闪金镇的部队共同守卫这片森林。",al={"麦克布莱德的上级","谁是麦克布莱德的上司"}},["0040026b"]={q="“内忧”讲的是什么？",a="这个说法指的是王国自身疆界内治安状况的惊人恶化。暴风城面临的并非来自境外的军队进攻，而是内部颠覆、离群的窃贼，以及在神圣家园中滋生的害兽。",al={"内忧的含义","“内忧”任务是什么","内部有什么威胁"}},["3e58992c"]={q="什么是狗头人？",a="狗头人是一种生活在地下、形似鼠类的人形生物，以执着挖掘隧道和人少时的怯懦而闻名。它们在王国阴暗的角落搜寻矿物，并会竭力守护自己的地下巢穴，不让外人入侵。",al={"狗头人背景","什么是狗头人","狗头人是什么人"}},["1071f0ff"]={q="回音山矿洞是什么？以前是我们的吗？",a="直到不久以前，回音山矿洞还是王国经营的一处高产矿场。狗头人从周围的山丘涌入隧道，赶走了人类矿工，并将矿洞据为己有，建立起一处武装据点。",al={"谁拥有回音山矿洞","回音山矿洞是我们的吗","什么是回音山"}},ffddbb43={q="为什么我要杀那么多狗头人？它们到底做了什么？",a="狗头人占据回音山矿洞后，切断了宝贵资源的供应，还在修道院附近形成了一处危险的害兽巢穴。若不加以制止，它们的挖掘会危及山谷的稳定，还可能侵占附近的道路。",al={"为什么杀狗头人","为什么消灭狗头人"}},c35515fc={q="那些戴红头巾的家伙是谁？",a="他们是迪菲亚潜行者的成员，当地由Garrick Padfoot领导。他们曾是石匠协会里技艺娴熟的工匠和劳工，参与重建暴风城；在一次激烈的薪酬纠纷后，他们转而沦为盗匪，反抗王室。",al={"红头巾匪徒","谁戴红头巾","北郡的红面罩"}},c05e8af1={q="为什么迪菲亚匪徒会在离暴风城这么近的地方袭击？",a="王室军队被派往海外，国内驻军又资源匮乏，迪菲亚潜行者因此胆大起来，开始占据艾尔文森林各地的农场和果园。北郡的葡萄园能为他们提供食物、葡萄酒和据点，就在王室眼皮底下。",al={"为什么暴风城附近有匪徒","为什么北郡有迪菲亚潜行者"}},["660e62c8"]={q="修道院为什么会有术士训练师？",a="杜希拉·拉萨雷在北郡的墓地训练术士，远离修道院的牧师和圣骑士。她隐居于此，反映出虔诚信奉圣光的人们对邪能魔法的忧虑。",al={"修道院为什么有术士","这里为什么有术士训练师"}},["808e49f9"]={q="为什么大家都让我这个彻头彻尾的新手来做这些事？",a="暴风城卫兵已不堪重负。士兵们驻守重要边境，王室军队又不在国内，当地驻军根本没有足够人手清理每一座矿井或守卫每一片葡萄园，因此像你这样的新兵成了他们眼下最可靠的防线。",al={"为什么让我这个新手做","为什么所有活都让我干","为什么要找新兵"}},["99bf7d8e"]={q="我是怎么来到北郡山谷的？",a="你是来寻找北郡修道院的。这里是招募和训练愿意为暴风王国拿起武器之人的主要场所。这座宁静的山谷四面环绕着高山，由一处设防隘口守卫，是新晋防卫者最初集结的地点。无论你是穿过艾尔文森林徒步而来，还是响应王室征召前来充实新兵，治安官玛克布莱德和修道院的导师们都在等着热心之士前来报到。",al={"我是怎么来到这里的","我是怎么到这里来的","为什么我会来到北郡"}},bb6d78ec={q="我在北郡山谷应该做些什么？",a="你来此是为了在修道院训练师的指导下磨练武技或魔法，同时协助当地驻军。道格拉斯·玛克布莱德治安官和暴风城卫兵人手不足，急需新兵应对附近的威胁。你需要猎杀从林线附近侵扰而来的掠食性狼群，从入侵的狗头人手中夺回回音山矿洞，并保护米莉·奥斯沃思的葡萄园，免受潜伏在附近的迪菲亚潜行者匪徒侵扰，然后再向南进军，进入艾尔文森林。",al={"我在这里应该做什么","我在这里的目标是什么","我在北郡该做什么"}},["11801d7a"]={q="为什么人类新角色要从北郡山谷开始？",a="数百年来，北郡修道院一直是王国人类坚韧精神的重要支柱，也是北郡兄弟会的所在地和白银之手骑士团的集结地。暴风城的常备军力捉襟见肘，瓦里安·乌瑞恩国王又神秘失踪，渴望保卫家园的年轻人类便被引导至这处避世的圣所，开始正式训练、领取介绍信，并证明自己忠于王室。",al={"为什么人类从这里开始","为什么人类角色从北郡开始","为什么北郡是人类出生地"}}},fp="17,423,20.635.0,20.549.0,44.358.0,49.250.0,42.256.0,44.204.0,50.196.0,35.215.0"}
P.entries["subzone:northshire-vineyards"] = {n="北郡农场",s="北郡农场是位于北郡修道院以东的谷地避风盆地中的葡萄种植园。尽管这里曾经是牧师们安宁的葡萄酒产地，但现在这些农田已经落入迪菲亚潜行者及其当地匪徒的控制之中。",h="北郡农场是位于北郡修道院以东的谷地避风盆地中的葡萄种植园。尽管这里曾经是牧师们安宁的葡萄酒产地，但现在这些农田已经落入迪菲亚潜行者及其当地匪徒的控制之中。",kw={"迪菲亚","艾尔文","garrick padfoot","葡萄","milly osworth","北郡山谷","北郡农场"},ang={["faction:Alliance"]="这些宁静的葡萄园中的动荡表明，混乱已经深入到即使是暴风城王国受保护最严密的角落。",["race:Human"]="对于许多第一次闯荡世界的年轻人类来说，被占领的葡萄园是他们第一次直接接触到迪菲亚潜行者的险恶与势力。"},sec={{t="被掠夺的收成",b="北郡农场位于北郡修道院以东，隔溪相望，代表着山谷中宁静的农业生活。农田原本由像Milly Osworth这样的当地工人照料，但日益加剧的动乱使他们失去了保护。隶属于迪菲亚潜行者的强盗在名为Garrick Padfoot的亡命之徒的指挥下，占领了这些土地。这些窃贼不仅仅是进行破坏，他们占据农田是为了掠夺收成，剥夺当地农民的生计，并为迪菲亚潜行者的新招募人员提供了一个就在修道院眼皮底下的立足点。"}},faq={{q="现在是谁控制着北郡农场？",a="属于迪菲亚潜行者的窃贼和暴徒占领了农田。他们的当地首领是Garrick Padfoot，一个被通缉的潜行者，他指挥着对庄稼的掠夺，并恐吓着当地的工人。",al={"谁在葡萄园","谁占领了北郡农场","谁是garrick padfoot"}},{q="为什么修道院任由强盗在农田里横行霸道？",a="随着国王Varian Wrynn的失踪，暴风城的军事资源已经极度匮乏。修道院守卫撤回以保卫修道院本身并监视山谷道路，迫使当地农民不得不依靠新到的冒险者来找回被盗的物资。",al={"为什么没有暴风城守卫","为什么修道院不保卫葡萄园"}},{q="Milly Osworth是谁？",a="Milly Osworth是一位在葡萄园工作的当地农民。当迪菲亚强盗闯入并夺走葡萄收成时，她被赶走了，现在她正在寻找勇敢的旅行者进入田野，找回她被掠夺的板条箱。",al={"milly osworth","milly是谁"}}},fx={d5ec287a={q="什么是北郡农场？",al={"什么是北郡农场","北郡农场概况","关于北郡农场"}},["1ba8e301"]={q="北郡农场发生了什么事？",a="迪菲亚潜行者的成员突然袭来并控制了葡萄园。在匪徒Garrick Padfoot的带领下，他们驱逐了当地工人，偷走了包括米莉·奥斯沃思在内的居民所收获的作物，并在修道院门前建立了武装据点。",al={"北郡农场的历史","这里发生了什么","葡萄园的故事"}},af15433a={q="北郡农场危险吗？",a="危险。葡萄园田地里到处都是由Garrick Padfoot指挥的敌对迪菲亚匪徒和暴徒。任何没有武器就徘徊在葡萄藤间的人，都可能被这些占据土地的扒手和强盗当场袭击。",al={"这里安全吗","北郡农场的危险","葡萄园安全吗"}}},fp="20,269,19.577.0,48.206.0,59.276.0,21.227.0"}
P.entries["subzone:noxious-glade"] = {n="剧毒林地",s="剧毒林地位于圣光之愿礼拜堂以北的山丘中，是一处深藏于盆地中、弥漫着浓缩瘟疫的隐秘之地。这里充斥着有毒的绿色空气和变黑的土壤，是天灾军团在银色黎明眼皮底下建立的一处近距离堡垒。",h="剧毒林地位于圣光之愿礼拜堂以北的山丘中，是一处深藏于盆地中、弥漫着浓缩瘟疫的隐秘之地。这里充斥着有毒的绿色空气和变黑的土壤，是天灾军团在银色黎明眼皮底下建立的一处近距离堡垒。",kw={"枯萎病","东瘟疫之地","圣光之愿礼拜堂","剧毒林地","瘟疫锅","天灾军团","屠宰场","通灵塔"},ang={["class:Paladin"]="这片林地令人警惕地提醒着人们，天灾瘟疫正在以多近的距离蚕食着圣光之愿礼拜堂这片神圣的庇护所，并提供了大量亡灵缝合怪和通灵师供人净化。",["race:Undead"]="被遗忘者勇士会认出这里的屠宰场和瘟疫锅，它们是巫妖王控制下的典型工具，赤裸裸地展示了那些无法挣脱束缚者的下场。"},sec={{t="邪恶的立足点",b="当银色黎明在圣光之愿礼拜堂保持警戒时，一支天灾军团的营地正潜伏在礼拜堂北方的山丘之上。剧毒林地遭受的感染比周围大部分地区都要严重得多：空气中弥漫着浓厚的病态绿雾，土壤也已腐烂成深紫色。在这处凹地内，亡灵建造了通灵塔、一座用来拼凑缝合怪的屠宰场，以及一座不断向大气中喷吐瘟疫的瘟疫锅。"},{t="在黎明的注视下",b="由于其紧邻礼拜堂，这片林地对往来的旅客、信使以及在圣光之愿活动的圣职战士构成了持续的威胁。驻扎在此的天灾军队建造了邪恶的怪兽并酿造毒药，它们不惧阳光，借由周围天然山脊的掩护保持隐蔽，直到粗心的旅行者沿着小路直接闯入它们的核心地带。"}},faq={{q="剧毒林地位于何处？",a="剧毒林地坐落在圣光之愿礼拜堂正北方的山丘中，位于东瘟疫之地的东部地区。",al={"剧毒林地在哪里","剧毒林地位置","如何前往剧毒林地"}},{q="为什么这里的空气和地面颜色不同？",a="与瘟疫之地的其他区域相比，这片林地受到的枯萎病侵蚀极其严重。一个运作中的瘟疫锅和附近的天灾建筑不断向凹地中排放毒素，将大地染成了深紫色，并让这片林地笼罩在有毒的绿色烟雾中。",al={"为什么这里是绿色的","为什么地面是紫色的","剧毒林地枯萎病"}},{q="林地里有什么天灾建筑？",a="这片空地具有典型的天灾建筑风格，包括一座高耸的瘟疫锅、几座通灵塔，以及一座用于组装缝合怪等恐怖构造体的屠宰场。",al={"剧毒林地里有什么","剧毒林地建筑"}},{q="银色黎明知道这个地方吗？",a="知道，但由于他们不仅要防御瘟疫之地各处天灾军团的大规模猛攻，资源还被不断消耗，像剧毒林地这样的哨站仍然是礼拜堂周边地带危险的腐烂口袋。",al={"圣光之愿礼拜堂是否知晓","银色黎明 剧毒林地"}}},fp="13,268,15.527.0,21.374.0,35.134.0,49.257.0,41.186.0,43.224.0"}
P.entries["subzone:noxious-lair"] = {n="腐化之巢",s="腐化之巢是一处位于塔纳利斯西南部沙漠、毗邻安戈洛环形山的下沉式异种虫巢穴。这片区域曾经是一片水源充沛的青翠盆地，但现在已被穴居的森提帕尔虫群所侵扰，其重要资源被掠夺殆尽。如今，这里已成为一座充满酸液的繁殖地，到处都是成群的虫族和丰富的矿脉。",h="腐化之巢是一处位于塔纳利斯西南部沙漠、毗邻安戈洛环形山的下沉式异种虫巢穴。这片区域曾经是一片水源充沛的青翠盆地，但现在已被穴居的森提帕尔虫群所侵扰，其重要资源被掠夺殆尽。如今，这里已成为一座充满酸液的繁殖地，到处都是成群...",kw={"森提帕尔","巢穴","腐化之巢","沙掠者","异种虫","索里德","塔纳利斯"},ang={["class:Druid"]="该巢穴是大自然令人不安的扭曲产物，展示了入侵的异种虫如何能迅速将一片曾经有水的盆地抽干，变成荒芜的酸性荒原。",["profession:Mining"]="异种虫在盆地中的挖掘活动暴露了异常多样的矿石，让矿工们能在同一片区域采集铁矿、秘银、真银和瑟银矿脉。"},sec={{t="干涸的盆地",b="腐化之巢坐落在俯瞰安戈洛环形山的西侧山脊旁，占据着沙地中曾经是一处湖泊或浅河的低洼地带。当森提帕尔异种虫入侵时，它们消耗了沙漠中残留的地下水分，将这片盆地变成了一处不断扩张的殖民地。巨大的螯钳和抽动的肢体直接从沙丘中伸出，围绕着布满腐蚀性昆虫分泌物和成簇孵化卵的地下隧道。"},{t="森提帕尔虫群",b="地下隧道连接着地表的入口和沙层下潮湿、覆盖着酸液的繁殖室。森提帕尔工虫、掘地虫、黄蜂和巨大的沙掠者在周边巡逻，保护它们的巢穴免受外界威胁。除了生物危险外，异种虫挖掘所引起的剧变还挖掘出了深层的矿藏，创造了一片异常多样的狩猎和勘探地，地下矿石暴露在虫群出没的巢穴之中。"}},faq={{q="腐化之巢里居住着什么样的生物？",a="巢穴中居住着森提帕尔，这是一个异种虫聚居地。巢穴由工虫、掘地虫、飞行黄蜂和掠食性的沙掠者守卫，它们都在像吞噬者索里德这样的稀有巢穴恐兽的统治下受到保护。",al={"腐化之巢的怪物","腐化之巢的昆虫","森提帕尔异种虫"}},{q="在异种虫占据这里之前，这里有什么？",a="下沉的地形表明该地区曾经是一条河床或浅沙漠湖。抵达此地的异种虫在地底挖掘，耗尽了塔纳利斯西部的宝贵水源和自然资源，留下了一片荒凉、被酸液浸透的盆地。",al={"腐化之巢的历史","腐化之巢曾是湖泊吗","腐化之巢的水源"}},{q="为什么地精对这个巢穴感兴趣？",a="加基森的地精将这个巢穴视为沙漠贸易的危害，并派遣冒险者去调查这个巢穴以及异种虫的扩张。",al={"腐化之巢的地精任务","蒸汽浮空城与腐化之巢","雷霆竞技场的异种虫"}},{q="腐化之巢与沙漠中的其他虫巢有联系吗？",a="腐化之巢代表了森提帕尔巢穴，它是从南部荒原蔓延开来的数个虫族殖民地之一。虽然它在物理上与更南方的巢穴不同，但其隧道共享着同样的诡异地下建筑，并威胁着要扼杀整个塔纳利斯的生命。",al={"塔纳利斯的其它巢穴","森提帕尔巢穴的联系","异种虫扩张"}}},fp="12,359,15.475.0,19.467.0,48.244.0,44.252.0,40.140.0,66.279.0"}
P.entries["subzone:old-ironforge"] = {n="Old Ironforge",s="Old Ironforge，也被称为“领主大厅”，是一座古老的地下密室，位于铁炉堡High Seat的正下方。它深深地开凿在山脉根部、炽热的岩浆脉之上，是这座矮人首都的祖源中心。如今，位于皇家王座大厅的厚重入口大门依然紧闭，并有严密的守卫看守。",h="Old Ironforge，也被称为“领主大厅”，是一座古老的地下密室，位于铁炉堡High...",kw={"aegrim的研究室","领主大厅","high seat","铁炉堡","magni bronzebeard","old ironforge"},ang={["class:Rogue"]="High Seat的封闭大门受到国王麦格尼的卫兵严密监视，任何试图擅自闯入下方古老密室的人都将面临严厉的矮人正义制裁。",["race:Dwarf"]="对于矮人而言，Old Ironforge和领主大厅是与他们祖源的圣神纽带，保留了他们在山中王国黎明时期开凿出的最深处基石。"},sec={{t="领主大厅",b="在High Seat中国王麦格尼·铜须的王座之下，坐落着被称为Old Ironforge或领主大厅的巨大洞穴。在这些灼热的地下基石深处，蜿蜒的石桥横跨过地底熔岩池。早在Great Forge和公共区回荡着现代矮人商业繁荣的声音之前，早期的领主们就已聚集在这些深邃的洞穴中，商讨并治理着这座山中王国。"},{t="封闭的密室",b="目前，从王座大厅进入Old Ironforge的入口已被牢牢封锁。铁炉堡皇家卫队严密监视着通往旧地库的入口。"}},faq={{q="什么是Old Ironforge？",a="Old Ironforge，历史上被称为领主大厅，是直接开凿在现代城市铁炉堡下方的古老下层区域。它由巨大的大厅和熔岩管道组成。",al={"领主大厅","什么是old ironforge","地下铁炉堡"}},{q="玩家可以进入Old Ironforge吗？",a="无法通过王座大厅进入。High Seat的大门紧闭，由矮人皇家卫队看守，下方的密室对普通市民关闭。不过，这些深处并非完全寂静：黑铁矮人的地图显示，有隧道汇聚在铁炉堡正下方的某个点。",al={"如何进入old ironforge","old ironforge是否开放","old ironforge大门锁定"}},{q="入口在哪里？",a="入口直接位于High Seat内部，即国王麦格尼·铜须在铁炉堡城内接见臣民的皇家谒见厅。",al={"old ironforge入口在哪里","old ironforge位置"}},{q="为什么Old Ironforge对矮人历史如此重要？",a="它被称为领主大厅，在现代山中首都的上层环廊完全建成之前的早期时代，曾是矮人领袖和山丘之王们举行会议的古老场所。",al={"old ironforge历史","为什么被称为领主大厅"}}},fp="13,365,22.435.0,16.176.0,22.194.0,32.286.0,30.141.0,52.202.0"}
P.entries["subzone:old-port-authority"] = {n="Old Port Authority",s="Old Port Authority是位于藏宝海湾木栈道旁的一个熙熙攘攘、汇集了众多商贩的仓库。在它的屋檐下，旅客们可以浏览从异国宠物和火枪到丰盛口粮和精制武器等各种商品。",h="Old Port Authority是位于藏宝海湾木栈道旁的一个熙熙攘攘、汇集了众多商贩的仓库。在它的屋檐下，旅客们可以浏览从异国宠物和火枪到丰盛口粮和精制武器等各种商品。",kw={"黑水海盗","火枪进口","藏宝海湾","切伤-淤青","航海需求","old port authority","荆棘谷"},ang={["class:Hunter"]="东部火枪进口的商人们让这座建筑成为了一个可靠的补给站，在深入荆棘谷的丛林之前，可以在这里补充弹药和火药。",["profession:Cooking"]="烹饪旅行者可以顺便去美味佳肴摊位，购买过往商船带来的地区性烹饪原料和补给品。"},sec={{t="木栈道上的商业活动",b="Old Port Authority坐落在海盗避风港藏宝海湾内，是一个划分为不同摊位的室内市场，其内部繁忙的商业活动十分活跃。商人们向无赖和私掠船员兜售冒险补给品、火枪、弓箭、食物和武器。这里还拥有外来进口商品，向任何有钱的人提供从码头直接运来的色彩斑斓的鸟类和航海奇珍。"}},faq={{q="什么是Old Port Authority？",a="它是藏宝海湾内一个显眼的商业仓库，被隔断成几个市场摊位。冒险者和海盗们会来这里购买食物、弹药、武器和贸易杂货。",al={"这座建筑是什么","藏宝海湾仓库","藏宝海湾港务局"}},{q="里面有什么商店？",a="该仓库包含五个不同的商人摊位：航海需求、美味佳肴、迅捷飞行、东部火枪进口和切伤-淤青有限公司，涵盖了口粮、武器、宠物鸟和基本补给品。",al={"内部商贩","港务局内的商店","我可以在这里买什么"}},{q="这里可以买到宠物吗？",a="可以。在航海需求摊位，旅客可以获得异国情调的鸟类伙伴，如玄凤鹦鹉和塞内加尔鹦鹉，它们是当地水手和私掠船员中受欢迎的伙伴。",al={"藏宝海湾宠物商人","藏宝海湾鹦鹉","航海需求商人"}}},fp="18,225,25.411.0,31.186.0,28.212.0,22.171.0"}
P.entries["subzone:old-town"] = {n="Old Town",s="Old Town是Stormwind City最古老且最为粗犷的区域，在第一次战争的破坏中基本保持完整。这里没有闪闪发光的石砌广场，取而代之的是狭窄的巷道、风化的砖墙、工薪阶层的公寓以及熙熙攘攘的军事设施。它是王国军事Command Center以及SI:7秘密总部的所在地。",h="Old Town是Stormwind...",kw={"champions' hall","command center","第一次战争","mathias shaw","old town","pig and whistle","si:7","暴风城"},ang={["class:Rogue"]="Old Town是你在这座首都中的天然避难所；在普通的巷道背后隐藏着SI:7的总部，情报大师和秘密联络员们会在此提供指引。",["class:Warrior"]="Command Center和Champions' Hall使Old Town成为Stormwind中久经沙场的老兵们寻求装备和战斗训练的首选聚集地。"},sec={{t="旧王国的遗迹",b="虽然第一次战争后Stormwind的其余部分由石匠工会从零开始精心重建，但Old Town逃过了彻底的毁灭。由于它不需要大规模重建，这里从未像Trade District或Cathedral Square那样获得崭新的大理石外墙和宏伟的运河。相反，它依然保留着古朴、拥挤的样貌，是打工者、劳工和城中最贫困居民的居所。这里的鹅卵石街道比首都的其他地方更狭窄、更脏乱，但也更加混乱，然而它们保留了战前Stormwind最真实的氛围。"},{t="士兵、间谍与酒馆",b="在风化的公寓背后，Old Town充当着Alliance首都的军事支柱。Command Center设有Stormwind的军事官员、营房和战斗训练师，旁边则是Champions' Hall，联盟最精锐的战士们都聚集于此。在区域边缘隐藏着SI:7的秘密基地，这是由Master Mathias Shaw领导的王国秘密情报机构。下班的步兵和暗影特工们都会聚集在Pig and Whistle Tavern，在这个城市最热闹的酒馆之一把酒言欢。"}},faq={{q="为什么Old Town看起来比Stormwind的其他地方脏得多？",a="Old Town在第一次战争期间在很大程度上躲过了部落对Stormwind的摧毁。由于它没有被夷为平地，石匠工会没有对其进行重建，这意味着它错过了赋予城市其他区域的崭新石砌建筑和宏伟的建筑风格。",al={"为什么old town破旧","old town的贫困","为什么old town很脏"}},{q="SI:7是什么，它位于哪里？",a="SI:7是Stormwind和Alliance的秘密情报机构，由Master Mathias Shaw负责监管。他们的秘密总部隐藏在Old Town的深处，穿过训练场和军用马厩就能找到。",al={"si:7位置","什么是si:7","stormwind间谍"}},{q="Old Town的Command Center有什么用？",a="Command Center是Stormwind军队的主要驻地和总部。在它的院子内及周边，军官们负责协调城市防御，战士和猎人则在马厩管理员和骑术训练师的指导下进行训练。",al={"command center的用途","old town兵营","stormwind军事总部"}},{q="Old Town的酒馆在哪里？",a="当地的酒馆是Pig and Whistle Tavern，位于该区域的中心附近。它以接待饥肠辘辘的士兵、冒险者和寻找丰盛烹饪食谱的旅行者而闻名。",al={"old town旅店","pig and whistle位置","pig and whistle在哪里"}}},fx={ddeb3ebc={q="什么是Old Town？",a="Old Town是暴风城现存最古老的城区。与首都其他地方不同，第一场战争中兽人部落洗劫暴风城时，Old Town的大部分区域幸免于难。如今，这里是一个质朴而贫困的街区，居住着暴风城的底层民众、普通劳工和不法之徒，同时也设有重要军事设施，例如Command Center和军情七处总部。",al={"什么是old town","暴风城old town","关于old town"}},["70a73a68"]={q="第一场战争期间，Old Town发生了什么？",a="第一场战争末期，兽人部落夷平暴风城时，首都大部分地区都遭到摧毁。然而，Old Town没有彻底毁灭，也躲过了最猛烈的火势。由于这里的建筑大多完好无损，战后大规模重建时基本保持了原样；那场重建在城中其他地方建起了闪亮的石砌城区。",al={"old town的历史","old town发生了什么","old town是怎么幸存的"}},["73f1f985"]={q="谁住在Old Town？",a="Old Town是暴风城贫民的居所，包括劳工、乞丐、扒手和窃贼。不过，这里也是城市军事与安全部队的重要基地。暴风城军队以中央的Command Center为驻地，而马迪亚斯·肖尔则在藏于该区的总部指挥军情七处的秘密特工。",al={"谁住在old town","old town的居民","谁控制old town"}},["3b861739"]={q="Old Town危险吗？",a="虽然Old Town由城市卫兵守卫，还设有王国的军事Command Center，但这里也有阴暗的一面。扒手、窃贼和刺客潜伏在狭窄的小巷和昏暗的角落里，一些可疑的店铺还经营毒药和暗藏的利刃。正直的旅人穿行在拥挤的街道上时，最好牢牢看好自己的钱袋。",al={"old town危险吗","old town的危险","old town安全吗"}},["840898dc"]={q="为什么叫Old Town？",a="这个名字名副其实：它是暴风城最初的历史城区。由于这里的建筑没有在第一场战争中被彻底夷平，它们早于石匠们主持的现代重建，是整座城市现存最古老的部分。",al={"为什么叫old town","old town是怎么得名的","old town的名称"}}},fp="8,373,26.585.0,28.556.0,66.262.0,37.217.0,48.237.0,32.200.0"}
P.entries["subzone:olsen-s-farthing"] = {n="奥森农场",s="奥森农场曾是一处繁荣的农庄，坐落于银松森林的主干道旁。第三次战争后，农田荒废，被效忠于亡灵巫师图勒·鸦爪的复生奴仆所占据。",h="奥森农场曾是一处繁荣的农庄，坐落于银松森林的主干道旁。第三次战争后，农田荒废，被效忠于亡灵巫师图勒·鸦爪的复生奴仆所占据。",kw={"芬里斯岛","洛丹伦农场","奥森农场","鸦爪劫掠者","鸦爪奴仆","银松森林","图勒·鸦爪"},ang={["faction:Horde"]="清理奥森农场的劫掠者对于确保连接北部的瑟伯切尔和通往提瑞斯法林地的道路畅通至关重要。",["race:Undead"]="对于被遗忘者来说，像奥森农场这样的地方提醒着他们：天灾军团的威胁依然存在，他们试图奴役死者，而不是解放他们。"},sec={{t="被枯萎的农庄",b="在瘟疫吞噬洛丹伦之前，奥森农场是一处繁忙的农业据点，可以直通银松森林的主要贸易道路。如今，它的耕地已被杂草淹没，建筑破败不堪，曾经的农耕记忆早已被天灾军团的死灵法术抹去。在图勒·鸦爪指挥下被奴役为苦力和劫掠者的亡灵徘徊在这片荒凉的土地上，屠杀任何靠近的旅行者。"},{t="鸦爪的掌控",b="徘徊在奥森农场的蹒跚恐怖之物并非漫无目的的游荡者，而是听命于图勒·鸦爪的仆从。图勒·鸦爪是一位强大的亡灵巫师，盘踞在洛丹米尔湖中心的芬里斯岛上。他利用黑暗魔法唤醒并奴役了周围乡村的死者，他的魔爪延伸至奥森农场，对试图确保银松森林北部区域安全的被遗忘者构成了直接威胁。"}},faq={{q="第三次战争前，奥森农场是什么地方？",a="它曾是一处繁忙的路边农庄，支撑着银松森林主要贸易路线上的当地商业活动，在洛丹伦王国陷落于天灾军团之前，它曾为各定居点提供粮食。",al={"奥森农场历史","这个地方曾经是什么","谁曾住在奥森农场"}},{q="为什么这个农场会被亡灵侵扰？",a="该农场在第三次战争中被摧毁，其残骸被亡灵巫师图勒·鸦爪所占据，他将死者复活为奴仆和劫掠者，以此恐吓路上的旅行者。",al={"为什么这里有亡灵","谁控制了奥森农场的亡灵","鸦爪的奴仆 银松森林"}},{q="图勒·鸦爪是谁？",a="图勒·鸦爪是一位危险的亡灵巫师，他效忠于天灾军团，并从他在芬里斯岛的据点指挥着遍布银松森林的亡灵入侵。",al={"图勒·鸦爪是谁","图勒·鸦爪传说","谁指挥鸦爪劫掠者"}},{q="部落或被遗忘者在这里有驻军吗？",a="没有。农场已被忠于图勒·鸦爪的敌对亡灵完全占领，对于被遗忘者的侦察兵和部落旅行者来说，这里是一片充满敌意的土地。",al={"奥森农场属于部落吗","被遗忘者住在奥森农场吗","这里有任务中心吗"}}},fx={["332ece8e"]={q="什么是奥森农场？",a="奥森农场是一处废弃农庄，坐落在穿过银松森林的商道旁。这里曾是一片繁荣的乡间农田，却在第三次战争的浩劫后逐渐衰败，沦为废墟。",al={"什么是奥森农场","银松森林的奥森农场","奥森农庄"}},["1623e0db"]={q="谁住在奥森农场？",a="这里已没有活着的农夫。如今，这片土地被Ravenclaw亡灵占据并肆虐；他们是侍奉死灵法师Thule Ravenclaw的奴隶和掠袭者，而Thule Ravenclaw在附近的芬里斯岛指挥他们。",al={"谁控制奥森农场","奥森农场里有谁","奥森农场的居民"}},["60f4df25"]={q="奥森农场危险吗？",a="危险。这处农庄对沿路旅行的人构成严重威胁。受Thule Ravenclaw束缚的亡灵会疯狂袭击任何踏入废弃田地和摇摇欲坠的农舍的人。",al={"奥森农场安全吗","奥森农场的危险","奥森农场的威胁"}}},fp="16,270,20.455.0,22.434.1,47.192.0,37.190.0,23.163.1,50.150.0"}
P.entries["subzone:oneiros"] = {n="奥奈罗斯",s="奥奈罗斯是一片广袤的古老暗夜精灵遗迹，位于菲拉斯北部，加德米尔湖的南面。这片遗迹与附近通往伊瑟拉国度的传送门紧密相连，其布满苔藓的石碑由精英绿龙人把守。",h="奥奈罗斯是一片广袤的古老暗夜精灵遗迹，位于菲拉斯北部，加德米尔湖的南面。这片遗迹与附近通往伊瑟拉国度的传送门紧密相连，其布满苔藓的石碑由精英绿龙人把守。",kw={"龙裔","菲拉斯","绿龙军团","加德米尔湖","奥奈罗斯"},ang={["class:Druid"]="德鲁伊对奥奈罗斯怀有深深的敬畏与关切，因为他们认识到这里与伊瑟拉领域之间存在着空灵的联系，以及梦魇腐蚀带来的挥之不去的危险。",["race:NightElf"]="对于暗夜精灵来说，漫步在奥奈罗斯是提醒他们古老帝国版图以及绿龙军团警惕守护的一种庄严方式。"},sec={{t="梦境之下的遗迹",b="奥奈罗斯的残垣断壁和断柱碎片散布在菲拉斯北部的茂密森林地面上，暗示着这里曾是一处数千年前被废弃的卡多雷定居点。如今，大自然已经重新收复了这些建筑，巨大的树根和青翠的植被将其缠绕覆盖。绿龙军团的精英卫士无情地巡逻着阴凉的小径和破败的广场，阻止凡人接近这些古老的秘密。"},{t="回响与腐蚀",b="奥奈罗斯与翡翠梦境之间的精神纽带使该地区变得极不稳定。效忠于织梦者的龙人在此边界周围保持着警惕的守望，但面纱之外仍有黑暗在涌动。误入奥奈罗斯的凡人必须面对强大的龙裔，他们将任何闯入者视为对抑制腐蚀的脆弱结界的潜在威胁。"}},faq={{q="奥奈罗斯在哪里？",a="奥奈罗斯位于菲拉斯北部，直接位于加德米尔湖南面，森林主干道的北侧。它坐落在翡翠梦境传送门边缘的巨树附近。",al={"奥奈罗斯位置","奥奈罗斯在哪里","寻找奥奈罗斯"}},{q="奥奈罗斯有什么生物？",a="这片遗迹中有大量强大的绿龙裔和效忠于绿龙军团的龙人在巡逻。旅行者在靠近时应保持谨慎，因为这些哨兵是可怕的精英守卫。",al={"奥奈罗斯怪物","奥奈罗斯的敌人","谁住在奥奈罗斯"}},{q="为什么这里会有暗夜精灵遗迹？",a="奥奈罗斯是一处古老的暗夜精灵定居点，其历史可以追溯到大分裂之前。和大部分菲拉斯地区一样，这里的文明在万年前就已崩溃，留下的石柱廊和庭院如今已被大自然重新占据。",al={"为什么会有遗迹","菲拉斯的卡多雷遗迹","奥奈罗斯历史"}},{q="奥奈罗斯和翡翠梦境有什么联系？",a="它靠近连接卡利姆多与梦境国度的巨大枝干，导致物质世界与精神世界之间的界限变得模糊。",al={"奥奈罗斯翡翠梦境","菲拉斯梦境连接"}},{q="附近有安全的地方休息吗？",a="遗迹本身并不安全，因为这里属于绿龙人。联盟旅行者可以撤退到西海岸外的羽月要塞，而部落成员则可以在菲拉斯东部的莫沙彻营地寻求庇护。",al={"奥奈罗斯附近的营地","菲拉斯织梦者休憩处","奥奈罗斯友方枢纽"}}},fp="7,245,23.440.0,21.360.1,25.194.0,31.199.0,35.230.0,61.151.0,37.210.0"}
P.entries["subzone:onyxia-s-lair"] = {n="奥妮克希亚的巢穴",s="奥妮克希亚的巢穴是一处位于尘泥沼泽巨龙沼泽深处的地下洞穴。它不仅是黑龙军团的龙后奥妮克希亚的筑巢圣地，也是她的据点。在这闷热且布满岩浆的巢穴深处，这位伟大的巨龙守护着一窝又一窝的黑龙卵。",h="奥妮克希亚的巢穴是一处位于尘泥沼泽巨龙沼泽深处的地下洞穴。它不仅是黑龙军团的龙后奥妮克希亚的筑巢圣地，也是她的据点。在这闷热且布满岩浆的巢穴深处，这位伟大的巨龙守护着一窝又一窝的黑龙卵。",kw={"黑龙军团","龙后","黑龙谷","尘泥沼泽","巢穴","奥妮克希亚","雏龙","巨龙沼泽"},ang={["faction:Alliance"]="对于联盟的勇士来说，这个洞穴是一位黑龙龙后的巢穴，她不断壮大的后裔威胁着塞拉摩及沼泽周围的每一个定居点。",["faction:Horde"]="尘泥沼泽与贫瘠之地和莫高雷的部落领地接壤；让一位黑龙龙后在卡利姆多孵化出一支巨龙军队，对整个新部落构成了生存威胁。"},sec={{t="岩浆与废墟之穴",b="这处洞穴开凿在巨龙沼泽凶险的泥沼和石化木林之中，入口酷似一条巨龙张开的大嘴。走进洞内，沼泽的阴冷瞬间被炽热的火山热浪所取代。岩浆从黑曜石的裂缝中渗出，地下的震颤不时撼动着洞穴顶部。中央大厅是一个巨大的孵化场，数以百计的黑龙卵在灰烬和余火中被孵育，并由龙族近亲、龙人守卫以及奥妮克希亚亲自看管。"},{t="龙后的隐居之所",b="当奥妮克希亚的兄弟奈法利安在海对岸的黑石塔中密谋时，奥妮克希亚长期以来一直保持着这处位于卡利姆多的隐秘栖息地，以繁衍黑龙军团的下一代。当她错综复杂的政治阴谋败露时，这里便是她的堡垒。在这里，远离人类王国的宫廷，她可以褪去伪装，显露作为Deathwing之女的真正可怕形态。"}},faq={{q="奥妮克希亚的巢穴究竟在哪里？",a="该巢穴位于尘泥沼泽南部的巨龙沼泽内，黑龙谷以南。入口处有巨大的龙骨、冒烟的地形，以及把守着如同张开巨口的石缝的黑龙族守卫。",al={"奥妮克希亚在哪里","奥妮克希亚位置","如何找到奥妮克希亚的巢穴","黑龙谷洞穴"}},{q="巢穴里居住着哪些生物？",a="洞穴内几乎全部是黑龙军团的成员。龙后奥妮克希亚统领着深处的大厅，周围簇拥着成群刚孵化的雏龙、守护龙人和成年的黑龙。",al={"奥妮克希亚的巢穴怪物","谁住在奥妮克希亚的巢穴","里面有什么"}},{q="既然位于沼泽之中，为什么洞穴会如此炎热？",a="奥妮克希亚将她的巢穴深挖进卡利姆多的地壳，触及了地下的岩浆脉络。极端的火山热量提供了孵化黑龙卵所需的灼热环境，与上方尘泥沼泽冰冷的泥沼形成了鲜明对比。",al={"为什么尘泥沼泽里有熔岩","奥妮克希亚的巢穴火山"}},{q="奥妮克希亚为什么要躲在卡利姆多？",a="尘泥沼泽提供了隔绝与隐蔽。其浓重的雾气、阴郁的泥潭和危险的野生动物令凡人军队望而却步，使龙后能在不被打扰的情况下补充她军团的数量，同时在海外协调她的暗中干涉。",al={"为什么奥妮克希亚在这里","为什么是尘泥沼泽","奥妮克希亚卡利姆多"}}},fp="13,299,23.478.0,25.400.1,31.246.0,37.218.0,45.255.0,37.253.0"}
P.entries["subzone:oracle-glade"] = {n="神谕林地",s="神谕林地坐落在泰达希尔的西北部，是一片神圣的林地庇护所，也是奇妙的The Oracle Tree和世界之树首要月亮井的所在地。尽管这里作为交流和警觉的中心，环境宁静祥和，但这片林地却面临着血羽鹰身人不断侵扰的威胁。",h="神谕林地坐落在泰达希尔的西北部，是一片神圣的林地庇护所，也是奇妙的The Oracle Tree和世界之树首要月亮井的所在地。尽管这里作为交流和警觉的中心，环境宁静祥和，但这片林地却面临着血羽鹰身人不断侵扰的威胁。",kw={"血羽","范达尔·鹿盔","鹰身人","月亮井","神谕林地","the oracle tree","泰达希尔","涌泉湖"},ang={["class:Druid"]="对于荒野的德鲁伊来说，The Oracle Tree是护林工作中的活生生的伙伴，它直接从树皮上脱落书面记录，提供关于这片土地健康状况的信息。",["race:NightElf"]="神谕林地代表了培育泰达希尔使其繁茂所需的悉心照料，这里安置着王冠上最强大的月亮井，以及一位直接与塞纳里奥领导层对话的无声守望者。"},sec={{t="林地之心",b="神谕林地安静地栖身于达纳苏斯和涌泉湖之间，是暗夜精灵与自然沟通的重要枢纽。在它的中心矗立着The Oracle Tree，这是一株古老的树木，其巨大的枝桠勾勒出了一只雄鹰栖息在巨熊之上的轮廓。附近闪烁着泰达希尔第一口、也是最强的一口神圣月亮井，这是沐浴在艾露恩恩泽下的月亮魔法绿洲。与古树之环一起，The Oracle Tree守望着岛上的枝叶，并脱落刻字的树皮，这些树皮是向范达尔·鹿盔大德鲁伊传达关于世界之树健康状况的重要讯息。"},{t="受困的枝桠",b="林地的宁静十分脆弱。咄咄逼人的血羽鹰身人降临到了这片林地，在高高的树枝间筑巢，威胁着这棵圣树。从达纳苏斯派遣来的哨兵们努力想要根除这些禽类拾荒者，而这些鹰身人积极骚扰过往的德鲁伊，并玷污了月亮井的自然宁静。穿行于北部枝桠的旅者必须小心谨慎，因为鹰身人会迅速攻击任何靠近它们巢穴的人。"}},faq={{q="什么是The Oracle Tree？",a="The Oracle Tree是一棵古老且受到魔法滋养的树，外形如同一只雄鹰栖息在一头巨熊身上。它监测着泰达希尔的生长与健康，并脱落刻字的树皮，其中包含的详细报告由德鲁伊直接送交到达纳苏斯的范达尔·鹿盔大德鲁伊手中。",al={"the oracle tree是谁","the oracle tree背景故事","泰达希尔会说话的树"}},{q="为什么鹰身人要攻击神谕林地？",a="血羽氏族的鹰身人在林地的高处树冠筑巢，被这里原始的荒野和魔法活力所吸引。它们暴力地捍卫自己的巢穴并骚扰The Oracle Tree，迫使当地的哨兵必须将它们控制住。",al={"血羽鹰身人","为什么这里有鹰身人","神谕林地的敌人"}},{q="这片林地里的月亮井有什么重要性？",a="神谕林地中的水池是泰达希尔建立的第一口、也是最强大的一口月亮井。它引导着艾露恩的神圣能量，滋养着周围的森林，并供养着前来汲取井水的卡多雷德鲁伊和女祭司。",al={"神谕林地月亮井","第一口月亮井","泰达希尔第一口月亮井"}},{q="神谕林地在哪里？",a="它位于泰达希尔西北部，涌泉湖以西。一条南向的道路将林地与达纳苏斯城门外环绕的主路直接连接起来。",al={"神谕林地位置","神谕林地在哪里","如何前往神谕林地"}}},fx={["3401eeb2"]={q="什么是神谕林地？",a="神谕林地是一处神圣的圣所，坐落在泰达希尔西北部、达纳苏斯以北。这里是古老的神谕之树的家园，也有泰达希尔最早、最强大的月亮井。暗夜精灵对这片林地怀有深深的敬意，将其视为宁静的敬拜与亲近自然之地；德鲁伊和女祭司在此监测伟大世界之树的健康状况。",al={"什么是神谕林地","神谕林地的背景","泰达希尔的神谕林地"}},["808cde15"]={q="为什么叫神谕林地？",a="这片林地以矗立在中心的神秘神谕之树命名。这棵独特的树由强大的自然魔法催生，蕴含深邃智慧，并持续监测泰达希尔的活力。它会落下刻有超自然报告的树皮，将自己的洞见传达给大德鲁伊范达尔·鹿盔，成为卡多雷的活体神谕。",al={"为什么叫神谕林地","神谕林地名称的由来","神谕林地名称的含义"}},["80458d5a"]={q="神谕林地危险吗？",a="这片林地原本是一处宁静的圣地，如今却因血羽 harpy 成群出没而变得险恶。这些好斗的生物在树木和枝干间筑巢，威胁着圣洁的月亮井，甚至是神谕之树。暗夜精灵哨兵已派驻此地，阻止鹰身人肆虐并保护旅人。",al={"神谕林地安全吗","神谕林地的威胁","神谕林地的敌人"}}},fp="12,297,21.596.0,16.473.0,24.279.0,43.245.0,53.253.0,34.178.0"}
P.entries["subzone:orgrimmar"] = {n="奥格瑞玛",s="奥格瑞玛是新部落强大的战士之都，坐落于杜隆塔尔北部蜿蜒的红色峡谷之中。它由大酋长萨尔所建，得名于纪念奥格瑞姆·毁灭之锤，是兽人复兴和卡利姆多各部落生存的中心。",h="奥格瑞玛是新部落强大的战士之都，坐落于杜隆塔尔北部蜿蜒的红色峡谷之中。它由大酋长萨尔所建，得名于纪念奥格瑞姆·毁灭之锤，是兽人复兴和卡利姆多各部落生存的中心。",kw={"暗矛巨魔","毁灭之锤","杜隆塔尔","grommash hold","新部落","奥格瑞玛","牛头人","萨尔"},ang={["faction:Horde"]="作为部落领导权的最高所在地，奥格瑞玛是整个卡利姆多及更远地区军事行动、部落联盟和外交关系的中心集结地。",["race:Orc"]="对于兽人而言，奥格瑞玛是他们救赎的实现，在这里，他们抛弃了恶魔诅咒的遗产，建立起一个光荣、独立的未来。"},sec={{t="岩石中的堡垒",b="第三次战争结束后，在海加尔山取得胜利，大酋长萨尔带领幸存的族人向南迁徙，在杜隆塔尔建立了永久的家园。奥格瑞玛坐落于天然的崎岖山崖屏障之中，工程设计旨在抵御围攻，拥有带尖刺的木制栅栏、石砌瞭望塔和深凿入山的洞穴。这座堡垒由暗矛巨魔、牛头人石匠和地精工程师共同建造，将一片荒芜的荒野变成了坚不可摧的力量堡垒。"},{t="新部落之心",b="摆脱了曾经束缚他们的恶魔嗜血诅咒，兽人将奥格瑞玛建造为荣誉、社区与生存的灯塔。如今在ADP 25年，这座城市不仅容纳了兽人和暗矛巨魔，还迎接了来自莫高雷的牛头人使节以及新结盟的被遗忘者。在防御森严的峡谷内，萨满教导下一代如何保持先祖的平衡，而老兵们在角斗场中通过战斗磨练军队，守护着卡利姆多脆弱的和平。"}},faq={{q="奥格瑞玛是以谁的名字命名的？",a="大酋长萨尔以他的导师和前任——传奇的兽人大酋长奥格瑞姆·毁灭之锤的名字命名了这座城市。毁灭之锤在东部王国解放兽人收容所的战斗中牺牲，临终前将他标志性的战甲和战锤传给了萨尔。",al={"奥格瑞玛名字起源","为什么叫奥格瑞玛","奥格瑞玛命名来源"}},{q="谁帮助建造了这座城市？",a="这座首都是在兽人、暗矛巨魔、牛头人、受雇的地精工兵和工程师以及游荡的勇士雷克萨的共同努力下迅速建成的。其天然的石墙经过挖掘和加固，在杜隆塔尔严酷的地形中提供了快速且易守难攻的庇护所。",al={"谁建造了奥格瑞玛","奥格瑞玛建造方式","奥格瑞玛建设者"}},{q="哪些种族以奥格瑞玛为家？",a="奥格瑞玛主要居住着兽人和森金的暗矛巨魔，他们共同居住在各区。牛头人旅行者作为坚定的盟友经常在此居住，新近接纳的被遗忘者的使节也已开始在他们身边建立起一席之地。",al={"谁住在奥格瑞玛","奥格瑞玛居民","奥格瑞玛种族"}},{q="大酋长萨尔居住在哪里？",a="萨尔在奥格瑞玛智慧谷内的中心要塞Grommash Hold统领着新部落，该要塞以纪念他牺牲的朋友格罗姆·地狱咆哮而命名。",al={"萨尔在哪里","萨尔奥格瑞玛位置","大酋长驻地"}}},fx={["4128ed5a"]={q="奥格瑞玛是什么地方？",a="奥格瑞玛是强大的兽人首都，也是整个部落的主要权力中心。它深深凿筑在杜隆塔尔北部边境崎岖的红岩峡谷中，是一座令人望而生畏的战士要塞，四周有高耸的木制城墙、铁门和天然山脉屏障守卫。对于部落的旅人和英雄而言，这里是贸易、训练与领导的核心。",al={"奥格瑞玛是什么地方","关于奥格瑞玛","奥格瑞玛概况"}},["96f2b3eb"]={q="奥格瑞玛的建立有着怎样的历史？",a="第三次战争和海加尔山之战结束后，酋长萨尔率领兽人前往卡利姆多，开辟一片不受恶魔腐化侵扰的新家园。在牛头人、暗矛巨魔和雷克萨的帮助下，部落迅速在杜隆塔尔的岩石山谷中建起这座要塞城市。尽管与当地半人马、鹰身人和野猪人爆发过激烈冲突，这座据点仍屹立不倒，并让部落得以长久立足这片大陆。",al={"奥格瑞玛的历史","奥格瑞玛如何建立","奥格瑞玛的建立"}},["98ddc713"]={q="奥格瑞玛危险吗？",a="对于忠诚的部落成员而言，奥格瑞玛是一处安全而友善的避难所，由经验丰富的战士和库卡隆守卫严密把守。然而，任何胆敢靠近城门的联盟闯入者都会遭到追捕，并被当场击杀。在城墙之外，杜隆塔尔周围的峡谷也潜伏着敌对的野猪人、鹰身人和叛逃的邪教徒等威胁。",al={"奥格瑞玛危险吗","奥格瑞玛的威胁","奥格瑞玛有哪些威胁"}}},fp="9,274,25.514.0,22.488.0,29.268.0,26.292.0,32.271.0,34.176.0"}
P.entries["subzone:ortell-s-hideout"] = {n="奥泰尔藏身处",s="奥泰尔藏身处是坐落在希利苏斯东南部山脉中的一处简陋而隐秘的洞穴。这里是隐士奥泰尔的避难所，他是少数几个有足够勇气或愚勇，敢于独自在这片贫瘠荒原上生活的独行者之一。",h="奥泰尔藏身处是坐落在希利苏斯东南部山脉中的一处简陋而隐秘的洞穴。这里是隐士奥泰尔的避难所，他是少数几个有足够勇气或愚勇，敢于独自在这片贫瘠荒原上生活的独行者之一。",kw={"洞穴","隐士奥泰尔","奥泰尔藏身处","希利苏斯","希利苏斯东南部"},sec={{t="隐士的庇护所",b="奥泰尔藏身处隐蔽在希利苏斯东南部的崎岖峭壁之中，在肆虐的沙尘暴和充斥着这片荒原的异种虫群威胁下，它提供了一个极其简陋的避难所。这个洞穴仅由隐士奥泰尔一人居住，他是一个古怪的遁世者，远离文明世界和塞纳里奥要塞的坚固据点，在这里艰难地维持着生计。那些敢于冒险前往这个偏远角落的旅行者，通常是为了寻求他关于沙漠及其危险的独特见解。"}},faq={{q="奥泰尔藏身处在哪里？",a="这个藏身处是在希利苏斯东南边缘的山岩中开凿出来的，远离中央沙漠道路，深藏在边界的悬崖之下。",al={"奥泰尔在哪里","奥泰尔位置","如何找到奥泰尔洞穴"}},{q="隐士奥泰尔是谁？",a="隐士奥泰尔是一个独居者，生活在塞纳里奥议会的远征队和世界各方势力之外。他选择独自生活在希利苏斯的危险之中，只守着他那小小的洞穴。",al={"奥泰尔是谁","隐士奥泰尔背景故事"}},{q="奥泰尔藏身处没有异种虫吗？",a="虽然洞穴本身没有受到虫害，但它孤立地处在一个极度危险的区域，那里到处是虫群和暮光之锤的邪教徒。要到达这个藏身处，需要穿过险恶的地形。",al={"洞里有虫子吗","奥泰尔洞穴安全吗"}}},fp="16,236,18.475.0,26.163.0,21.201.0,43.208.0"}
P.entries["subzone:owl-wing-thicket"] = {n="枭翼树丛",s="枭翼树丛是冬泉谷南部一片由洞穴和岩石栖息地构成的崎岖区域。这里栖息着大量狂暴、受月光影响且疯狂的枭兽，它们在雪崖间四处徘徊。在深处，古老的暗夜精灵祭坛保存着关于这些生物起源，以及它们与月神艾露恩之间联系的神圣知识。",h="枭翼树丛是冬泉谷南部一片由洞穴和岩石栖息地构成的崎岖区域。这里栖息着大量狂暴、受月光影响且疯狂的枭兽，它们在雪崖间四处徘徊。在深处，古老的暗夜精灵祭坛保存着关于这些生物起源，以及它们与月神艾露恩之间联系的神圣知识。",kw={"艾露恩","艾露恩卫士","枭兽","受月光影响","枭翼树丛","ranshalla","冬泉谷"},ang={["class:Druid"]="德鲁伊认为枭兽形态是神圣的，这使得这片树丛成了一个令人警醒的地方，这些被赋予了月光亲和力的生物已经陷入了无法自控的疯狂。",["race:NightElf"]="对于卡多雷来说，枭翼树丛是已荒废的圣地，它在保存艾露恩恩泽早期记录的同时，也存在着那些失去了古老平衡的野性枭兽。"},sec={{t="枭兽圣所",b="枭翼树丛开凿在永望镇南部的雪山高地中，是冬泉谷野生枭兽最稠密的巢穴之一。很久以前，暗夜精灵守护者曾将这些生物尊为受到艾露恩祝福的神圣卫士。古老的神龛和月石祭坛至今仍隐藏在洞穴悬壁中，由艾露恩卫士的徘徊之魂守望着。然而，今天许多野兽已经陷入疯狂，攻击任何闯入它们神圣洞穴的旅行者。"},{t="枭兽传说",b="暗夜精灵学者和祭司会前往枭翼树丛寻求与艾露恩卫士沟通。在祭司Ranshalla的指引下，联盟的探寻者们点燃洞穴建筑群中的圣火，以唤醒古老的灵魂。这些卫士讲述了野生枭兽最初是如何由艾露恩创造出来，以守护纯净的自然圣所的传说，尽管它们现在变得野蛮且充满敌意，但这提供了关于这些野兽神圣血统的真相。"}},faq={{q="什么是枭翼树丛？",a="枭翼树丛是位于冬泉谷南部的一片雪崖和洞穴网络。这里因其栖息着大量的野生枭兽以及数座供奉暗夜精灵月神艾露恩的古老神龛而闻名。",al={"枭翼树丛","枭翼树丛在哪里","枭翼树丛传说"}},{q="为什么这里的枭兽如此具有攻击性？",a="虽然最初是被艾露恩祝福的自然守护者，但冬泉谷中许多枭兽已经陷入了暴力狂乱之中。在枭翼树丛中，它们作为疯狂、狂暴且受月光影响的野兽徘徊，攻击任何接近其巢穴的人。",al={"为什么枭兽会发狂","冬泉谷的疯狂枭兽","狂暴的枭兽"}},{q="Ranshalla是谁？",a="Ranshalla是一位前往枭翼树丛的艾露恩暗夜精灵祭司。她寻求古老的艾露恩卫士的指引，以发掘枭兽一族神圣的起源与历史。",al={"ranshalla","冬泉谷的ranshalla是谁","祭司ranshalla"}},{q="在树丛中发现的艾露恩卫士是什么？",a="艾露恩卫士是与洞穴内祭坛相连的古老暗夜精灵之魂。当通过重新点燃圣火将它们召唤出来时，它们会讲述枭兽是如何被创造出来以看守荒野和圣地的。",al={"艾露恩卫士","枭翼树丛中的灵魂","枭兽之魂"}}},fp="16,334,24.512.0,23.458.1,25.206.0,41.253.0,17.199.0,57.216.0"}
P.entries["subzone:palemane-rock"] = {n="白鬃石",s="白鬃石是坐落在莫高雷西部群山之中的一个洞穴和营地。它是具有侵略性的白鬃豺狼人部落的主要据点，对附近的血蹄村牛头人构成了持续的困扰和威胁。",h="白鬃石是坐落在莫高雷西部群山之中的一个洞穴和营地。它是具有侵略性的白鬃豺狼人部落的主要据点，对附近的血蹄村牛头人构成了持续的困扰和威胁。",kw={"血蹄","洞穴","豺狼人","莫高雷","白鬃","石头"},ang={["faction:Horde"]="确保莫高雷的边境免受像白鬃豺狼人这样的地方害虫骚扰，对于维持牛头人家园的安全与稳定至关重要。",["race:Tauren"]="占据这些西部洞穴的白鬃豺狼人是你们族人眼中挥之不去的顽疾，它们威胁着莫高雷草场上的猎物和粗心大意的旅人。"},sec={{t="豺狼人据点",b="白鬃石位于莫高雷大草原的西缘，由一个巨大的露天营地和一个深邃阴暗、开凿在山腰的洞穴组成。白鬃豺狼人占据了洞穴内部和外围的山麓，将其划为自己的领地。这些豺狼人充满敌意且领地意识极强，它们凶猛地保卫着自己的巢穴，攻击任何靠得太近的猎人、旅行者和斥候。"}},faq={{q="什么是白鬃石？",a="白鬃石是一个天然形成的洞穴，也是一个位于莫高雷西部悬崖处的豺狼人据点。",al={"白鬃石信息","白鬃洞穴","白鬃石在哪里"}},{q="谁住在白鬃石？",a="该洞穴及周边营地由白鬃氏族的豺狼人所占据。它们极具侵略性，防范着包括当地牛头人在内的外来者入侵其领地。",al={"这里住着谁","白鬃怪物","白鬃石的豺狼人"}},{q="为什么白鬃石对牛头人很重要？",a="白鬃石紧邻莫高雷中部和血蹄村，是一个充满敌意的掠夺者巢穴，牛头人猎人和勇士必须不断地对其进行压制。",al={"为什么牛头人很在意","血蹄村豺狼人","对莫高雷的威胁"}}},fx={e2adfd83={q="白鬃石危险吗？",a="是的，这里非常危险。白鬃石遍布白鬃氏族的好斗豺狼人。他们占据了外部营地，以及蜿蜒深入山腹的洞穴隧道，会猛烈攻击任何靠近其领地的人。",al={"白鬃石危险吗","白鬃石的危险","白鬃豺狼人有敌意吗"}},["3b0205a5"]={q="白鬃石为何得名？",a="洞穴及其周围的峭壁以占据此地为家的白鬃豺狼人氏族命名。",al={"白鬃石为何得名","白鬃石名称的由来","白鬃石为何如此命名"}}},fp="13,242,18.449.0,22.113.0,27.172.0,44.172.0"}
P.entries["subzone:park"] = {n="Park",s="暴风城位于Cathedral Square和Mage Quarter之间，其西侧边缘有一处名为“公园”的郁郁葱葱的避难所，这里充满绿意，是个安静沉思的好去处。在这座喧嚣的石砌都城中，它致力于自然与休闲，是前来造访的暗夜精灵的主要避风港，也是东部王国唯一的德鲁伊训练师所在地。",h="暴风城位于Cathedral Square和Mage...",kw={"德鲁伊","卡多雷","月亮井","娜拉·梅德隆","暗夜精灵","公园","暴风城"},ang={["class:Druid"]="这片宁静的飞地是你在整个东部王国进行训练和寻求建议的唯一避难所。",["race:NightElf"]="对于横跨大海旅行的暗夜精灵来说，公园提供了一种宾至如归的感觉，这里以发光的月亮井为中心，还有熟悉的艾露恩与荒野导师。"},sec={{t="石砌都城中的林地",b="暴风城的其他区域大多是鹅卵石铺就的人行道、高耸的石灰岩壁垒和拥挤的集市摊位，而公园则提供了一丝宁静的荒野气息。它最初是为市民建立的安静休闲场所，后来自然而然地转变成了暗夜精灵使者和从无尽之海远道而来的旅人的聚居地。在遮天蔽日的树冠下，围绕着中央的月亮井，该区域将卡利姆多神圣林地的一角带入了人类王国的心脏地带。"},{t="避难所与友谊",b="对于暗夜精灵来说，公园是他们在异国他乡的重要立足点。在这里，像娜拉·梅德隆这样的卡多雷牧师照料着前来朝圣的人们，德鲁伊导师也为那些献身荒野的人提供指导。该区域也是一处宁静的休憩之所，疲惫的冒险者可以在此从Trade District的喧嚣和Cathedral的神圣职责中获得片刻休息。"}},faq={{q="公园位于暴风城的什么位置？",a="公园坐落在暴风城的极西边缘。你可以从Cathedral Square向西南方向走，或者从Mage Quarter向西北方向走，就能到达它那绿意盎然的小径。",al={"公园在哪里","如何前往公园","公园位置"}},{q="为什么公园里有这么多暗夜精灵？",a="公园被前来造访的暗夜精灵视为避难所，他们在此寻求从暴风城高耸的石街中解脱出来。这里郁郁葱葱的林地和宁静的氛围让他们想起了家乡的森林，于是他们选择在此定居，甚至在广场上建立了一座月亮井。",al={"为什么有暗夜精灵","暴风城暗夜精灵区","卡多雷区"}},{q="我可以在这里训练德鲁伊技能吗？",a="可以。公园目前是东部王国中唯一有联盟德鲁伊训练师驻扎的地方，他们为远离卡利姆多的卡多雷修行者提供指导和训练。",al={"暴风城德鲁伊训练师","东部王国德鲁伊训练地点","公园德鲁伊训练"}},{q="公园中心那座发光的池塘是什么？",a="公园中间的池塘是一座神圣的暗夜精灵月亮井，由卡多雷访客建造，旨在人类城市中作为精神安宁与月神之力的神圣源泉。",al={"公园月亮井","公园发光的喷泉","公园里的水池"}}},fx={a403a5e6={q="公园是什么地方？",a="公园是暴风城西角的一片葱郁城区。这里最初主要供人休闲，如今则成为一处绿意盎然的避风港，为到访的暗夜精灵提供远离城中宽阔石板大道的休憩之所。宁静的林地间有一口圣洁的月亮井，以及东部王国唯一一处德鲁伊训练师聚集地。",al={"公园是什么地方","暴风城公园概况","公园属于什么城区"}},["7a811135"]={q="公园发生了什么变化？",a="这里原本只是供暴风城居民休闲的地方。第三次战争后，暗夜精灵与联盟结盟并来到首都，这片城区随之发生了变化。暗夜精灵在这里的树木与绿意间找到了慰藉，远离石砌街道，并在此建立了永久居所，举行仪式使一口发光的月亮井圣化，还将德鲁伊教义带到了人类的土地上。",al={"公园的历史","公园发生了什么"}},["83a38db8"]={q="公园危险吗？",a="不危险。公园是暴风城最宁静祥和的城区之一。这里有城市守卫把守，也有到访的暗夜精灵哨兵和德鲁伊守护，为人们提供远离首都繁忙贸易区和军事区的清静去处。",al={"公园安全吗","公园危险吗","公园里的威胁"}}},fp="4,338,28.525.0,24.376.0,39.170.0,46.264.0,33.196.0,51.186.0"}
P.entries["subzone:pestilent-scar"] = {n="瘟疫之痕",s="瘟疫之痕是一道深邃且受腐蚀的峡谷，切开了东瘟疫之地那片饱受蹂躏的大地。与天灾军团腐蚀造成的锯齿状裂痕不同，这道裂谷似乎是一处天然峡谷或干涸的湖床，后来遭到腐蚀并被贪婪的软泥怪所占据。",h="瘟疫之痕是一道深邃且受腐蚀的峡谷，切开了东瘟疫之地那片饱受蹂躏的大地。与天灾军团腐蚀造成的锯齿状裂痕不同，这道裂谷似乎是一处天然峡谷或干涸的湖床，后来遭到腐蚀并被贪婪的软泥怪所占据。",kw={"腐蚀","东瘟疫之地","峡谷","魔刃之痕","软泥怪","瘟疫之痕","软泥"},ang={["profession:Herbalism"]="峡谷边缘浸透了浓烈的腐败之物，有时会在悬崖边孕育出阿尔萨斯之泪和瘟疫花这类罕见的、适应了腐蚀的植物。",["race:Undead"]="被遗忘者的药剂师经常研究栖息在这些深邃裂缝中的软泥怪，以分离出天灾军团最恶毒毒素的不稳定变体。"},sec={{t="一道受腐蚀的裂谷",b="瘟疫之痕蜿蜒穿过东瘟疫之地的东部区域，在受腐蚀的地貌中形成了一道阴森的裂缝。虽然像魔刃之痕这样的附近裂缝是由亡灵瘟疫突然爆发所撕裂开的，但学者们指出，瘟疫之痕似乎起源于一种天然的地质构造。它很可能是一条深邃的河谷或天然湖泊，在天灾军团席卷洛丹伦时干涸，留下了一条荒芜的沟壑，并逐渐汇聚了有毒的径流和污秽的软泥。"},{t="软泥坑",b="这片洼地失去了纯净的水源，终日浸泡在持久的邪恶腐败之中，已成为变异酸性软泥怪和食腐害虫的滋生温床。在其摇摇欲坠的边缘附近行走十分危险；裂谷上方的空气中充斥着刺鼻的烟雾，且不稳定的土壤经常威胁着要将粗心大意的冒险者直接抛入下方翻滚的淤泥之中。"}},faq={{q="什么是瘟疫之痕？",a="瘟疫之痕是位于东瘟疫之地的一道下陷峡谷。在洛丹伦陷落期间受到腐蚀，峡谷中充满了污秽的径流、病变的土壤以及极具攻击性的软泥怪。",al={"瘟疫之痕背景故事","什么是瘟疫之痕","瘟疫之痕峡谷"}},{q="瘟疫之痕是如何形成的？",a="与天灾军团爆发所造成的非自然地表裂缝不同，瘟疫之痕似乎曾是一处天然山谷、湖泊或河谷，在亡灵瘟疫的腐蚀下干涸并枯萎了。",al={"瘟疫之痕是如何形成的","瘟疫之痕的起源","谁制造了瘟疫之痕"}},{q="它与魔刃之痕有何不同？",a="魔刃之痕是作为一种喷涌出纯粹魔法腐蚀物的非自然火山裂缝而被猛烈撕开的。瘟疫之痕则是一处更古老的天然地势洼地，在土地死后逐渐聚集了腐蚀物和径流。",al={"瘟疫之痕与魔刃之痕","魔刃之痕的区别"}},{q="瘟疫之痕里生活着什么生物？",a="裂谷底部主要是由瘟疫催生的酸性软泥怪和食腐害虫所占据，它们在底部聚集的有毒水潭和腐烂的有机物质中繁衍生息。",al={"瘟疫之痕的生物","瘟疫之痕中有什么生物"}}},fp="14,293,16.543.0,14.354.0,27.201.0,32.237.0,42.228.0,42.175.0"}
P.entries["subzone:petitioner-s-chamber"] = {n="Petitioner's Chamber",s="Petitioner's Chamber，也被称为请愿者大厅，是一个位于Stormwind Keep主入口坡道旁的前厅。它是贵族、教会要员以及寻求觐见国王的来访臣民的官方候见室。在此逗留的人们常常会在这里交谈、饮酒，或等待摄政王的召见。",h="Petitioner's Chamber，也被称为请愿者大厅，是一个位于Stormwind...",kw={"德拉维主教","caledra dawnbreeze","雷明顿·瑞治维尔伯爵","请愿者大厅","petitioners chamber","stormwind keep"},ang={["class:Priest"]="由于德拉维主教经常驻扎在这个前厅，该房间成为了圣光教会行政层级与皇室宫廷之间的交汇点。",["faction:Alliance"]="对于联盟的忠诚者来说，这个房间代表了Stormwind的行政瓶颈，国内的上诉、教会事务以及贵族的请求都在这里等待着皇家议会那少得可怜的关注。"},sec={{t="候见与权谋之室",b="Petitioner's Chamber位于登上Stormwind Keep后右侧。这里是国家大事与日常官僚事务交汇之处。雷明顿·瑞治维尔伯爵等贵族和德拉维主教等高级神职人员常常在此消磨时间，等待觐见安度因·乌瑞恩国王和伯瓦尔·弗塔根公爵。在宫廷礼仪那光鲜亮丽的表象之下，这里是城堡内进行闲谈、私下游说以及观察王国中谁才是真正掌权者的理想角落。"}},faq={{q="Petitioner's Chamber在哪里？",a="该房间位于Stormwind Keep内。当你沿着主入口坡道登上要塞时，它就在你右手边的第一个房间。",al={"petitioners chamber在哪里","如何找到petitioner chamber","petitioner room位置"}},{q="谁会聚集在这个房间里？",a="这里常有请愿者、宫廷随从和寻求觐见王室的贵族出没，其中包括雷明顿·瑞治维尔伯爵、Caledra Dawnbreeze以及圣光教会的德拉维主教等人物。",al={"谁在petitioners chamber","petitioner chamber里的npc","谁在这里等待"}},{q="为什么它也被称为请愿者大厅？",a="它的正式功能是接待那些已向王室提交正式请愿书的臣民。访客必须在此等待，直到摄政王、伯瓦尔·弗塔根公爵或皇家议会批准他们进入王座大厅。",al={"请愿者大厅","为什么叫请愿者大厅"}},{q="城市任务期间这里会发生什么？",a="造访该房间的主要目的是交付货物，或是与驻扎在要塞内的贵族及神职人员交谈，例如为等待宫廷事务处理而口渴的贵族提供波特酒等饮品。",al={"petitioner chamber任务","什么任务会指引到这里"}}},fx={["7fbb3fec"]={q="Petitioner's Chamber 是什么地方？",a="Petitioner's Chamber 是暴风城要塞的公共接待大厅，从通往宫殿的宏伟坡道上去后，它就在右侧。这里是官方等候室，供臣民、外国使节和到访的贵族等候觐见王室或宫廷。",al={"petitioner's chamber 是什么地方","暴风城请愿者大厅","这是什么房间"}},["7106fd20"]={q="Petitioner's Chamber 危险吗？",a="一点也不危险。这个大厅位于暴风城要塞戒备森严的殿堂之内，由皇家卫兵守护。只要你不把麻烦直接带进宫殿，这里就是王国中最安全、最宁静的前厅之一。",al={"petitioner's chamber 安全吗","petitioner's chamber 的危险","petitioner's chamber 里的威胁"}}},fp="20,373,31.524.0,42.151.0,25.219.0,46.222.0,37.226.0"}
P.entries["subzone:pig-and-whistle-tavern"] = {n="Pig and Whistle Tavern",s="Pig and Whistle Tavern是一家坐落在暴风城Old Town崎岖街区的热闹旅店。它是联盟旅客、当地工人和那些回忆着王国过往冲突的老兵们所钟爱的聚会场所。",h="Pig and Whistle Tavern是一家坐落在暴风城Old Town崎岖街区的热闹旅店。它是联盟旅客、当地工人和那些回忆着王国过往冲突的老兵们所钟爱的聚会场所。",kw={"烹饪","kendor kabonka","old town","pig and whistle","暴风城","旅店"},ang={["faction:Alliance"]="对于路过首都的联盟士兵和旅客来说，这家旅店提供了一个温馨、质朴的炉火，以及与王国早期战争老兵共叙友谊的机会。",["profession:Cooking"]="烹饪技艺大师们经常会前往这家旅店寻找Kendor Kabonka，他出售着来自艾泽拉斯各地的无与伦比的稀有烹饪食谱收藏。"},sec={{t="Old Town中的避风港",b="Pig and Whistle Tavern坐落在Old Town布满砂砾、蜿蜒曲折的小巷中，为那些行走在首都较粗犷街区的人们提供温暖、麦芽酒和住宿。当城中的贵族聚集在大教堂广场和云石广场时，这家店则为普通市民、劳动人民和刚从路途归来的旅客提供服务。在旅店内，顾客可以找到像著名的食谱商人Kendor Kabonka这样的商贩，还有那些一边啜饮着酒杯，一边交流着第一次和第二次战争回忆的饱经风霜的老兵。"}},faq={{q="Pig and Whistle Tavern位于何处？",a="Pig and Whistle Tavern坐落在暴风城的东部街区Old Town，那里以其军事营地、盗贼窝点和工人阶级居住区而闻名。",al={"pig and whistle在哪里","pig and whistle位置","old town旅店"}},{q="谁经常光顾这家旅店？",a="这家旅店在旅客、休班卫兵和交流第一次和第二次战争故事的老兵中很受欢迎，此外还有像烹饪食谱大师Kendor Kabonka这样的著名商人。",al={"pig and whistle里有什么人","pig and whistle常客"}},{q="这家旅店提供什么服务？",a="Pig and Whistle是一家旅店，疲惫的旅客可以在这里休息，购买食物、饮料和专业的烹饪食谱。",al={"pig and whistle是旅店吗","pig and whistle服务"}}},fx={["97956e92"]={q="Pig and Whistle Tavern 是什么地方？",a="Pig and Whistle Tavern 是暴风城 Old Town 区内一间温馨的酒馆。这里是疲惫的联盟旅人的异乡之家，提供温暖的炉火、醇酒和安全的庇护。老兵们常在酒馆内聚集饮酒，回忆第一次和第二次战争；旅人和当地居民也会在此相聚，远离繁忙的贸易区。",al={"pig and whistle tavern","pig and whistle","pig and whistle 是什么地方"}},["7bd4ea21"]={q="Pig and Whistle Tavern 危险吗？",a="完全不危险。这间酒馆处在暴风城卫兵的严密保护之下，是一处安宁的避风港。Old Town 的阴暗巷道里或许藏有见不得人的勾当，但在酒馆里，你只会遇见休息的旅人、讲述过往战役的老兵，以及喝着麦酒放松身心的当地商人。",al={"pig and whistle 危险吗","pig and whistle 的危险"}}},fp="22,246,20.527.0,44.158.0,25.203.0,38.122.0"}
P.entries["subzone:plaguemist-ravine"] = {n="毒雾峡谷",s="毒雾峡谷是一条狭窄的山间通道，连接着辛特兰郁郁葱葱的荒野和西瘟疫之地达隆米尔湖那受诅咒的湖岸。它因从北方滚滚而来的病态浓雾而得名，这条通道安静而荒凉，横跨了整个山脉。",h="毒雾峡谷是一条狭窄的山间通道，连接着辛特兰郁郁葱葱的荒野和西瘟疫之地达隆米尔湖那受诅咒的湖岸。它因从北方滚滚而来的病态浓雾而得名，这条通道安静而荒凉，横跨了整个山脉。",kw={"凯尔达隆","达隆米尔","辛特兰","山间通道","毒雾","毒雾峡谷","奎尔丹尼","西瘟疫之地"},ang={["class:Hunter"]="这条峡谷是一个宁静的过渡点，尽管由于缺乏猎物或林地野兽，对于向北进入瘟疫之地的追踪者来说，它是一条令人毛骨悚然的边界。",["faction:Alliance"]="这条通道为驻扎在奎尔丹尼小屋的联盟侦察兵提供了一条隐蔽的路线，使他们能够监视凯尔达隆周围受腐蚀的湖岸，而无需面对大路上的巡逻队。"},sec={{t="凋零的门槛",b="Tucked away in the mountains northwest of Quel'Danil Lodge, Plaguemist Ravine acts as a geographic threshold between two radically different realms. To the south lies the lush, untamed highland forest of the Hinterlands, while to the north the pass opens directly upon Caer Darrow and the blighted expanse of the Western Plaguelands. The ravine earned its name from the foul, unnatural vapors that creep southward out of the Plaguelands, creating a jarring contrast with the crisp mountain air of the neighboring wilderness."},{t="一条安静的通道",b="尽管这条峡谷直接切入了被天灾军团蹂躏的领土边缘，但峡谷本身却异常荒凉。旅行者在峡谷中既找不到野生猛兽，也看不到游荡的亡灵。由于这种令人毛骨悚然的宁静，这条蜿蜒的小路成为了大胆的信使和冒险者的便利（虽然有些不祥）捷径，他们希望借此绕过通往洛丹伦的重兵把守的公路和边境检查站。"}},faq={{q="毒雾峡谷通向哪里？",a="毒雾峡谷连接着辛特兰和西瘟疫之地。向北走可以到达靠近凯尔达隆岛屿要塞的达隆米尔湖岸，向南走则会进入奎尔丹尼小屋西北方的森林丘陵。",al={"毒雾峡谷通向哪里","毒雾峡谷路径","毒雾峡谷连接点"}},{q="为什么它被称为毒雾峡谷？",a="这条通道是最近才得名的，因为从西瘟疫之地向南漂移着弥漫的凋零浓雾。这种病态的空气与辛特兰特有的清新、未受腐蚀的大气形成了鲜明的对比。",al={"为什么叫毒雾峡谷","毒雾峡谷名字由来"}},{q="峡谷里有敌人或NPC吗？",a="没有。峡谷中完全没有任何敌对生物、野生动物或友好的非玩家角色，这使得它成为了两个活跃区域之间一条异常安静的通道。",al={"毒雾峡谷怪物","毒雾峡谷安全吗"}},{q="如何找到辛特兰的入口？",a="在辛特兰，入口位于奎尔丹尼小屋以西、拉普索迪·辛迪格营地以北的北侧山墙内。",al={"如何找到毒雾峡谷","毒雾峡谷入口"}}},fp="17,291,20.524.0,15.438.0,34.258.0,35.217.0,44.163.0,48.144.0"}
P.entries["subzone:plaguewood"] = {n="病木林",s="病木林曾经是一片名为“绿木林”的宁静林地，如今却成了一片位于斯坦索姆以南、充满了腐化与真菌的荒芜之地。这里爬满了天灾军团的建筑，还有四处巡逻的血色十字军，是东瘟疫之地最腐败的角落之一。",h="病木林曾经是一片名为“绿木林”的宁静林地，如今却成了一片位于斯坦索姆以南、充满了腐化与真菌的荒芜之地。这里爬满了天灾军团的建筑，还有四处巡逻的血色十字军，是东瘟疫之地最腐败的角落之一。",kw={"真菌","绿木林","病木林","天灾军团","屠宰场","斯坦索姆","恐惧谷","通灵塔"},ang={["class:Paladin"]="病木林中扭曲的树木和邪恶的大锅令人痛苦地回想起洛丹伦的陷落，任何圣光的勇士都必须在这里面对成群的憎恶和顽固的狂热分子。",["faction:Alliance"]="对于幸存的联盟成员来说，走在这些小径上意味着重走阿尔萨斯王子当年通往斯坦索姆的清洗之路，而如今这条路已经淹没在腐烂和疯狂的血色十字军教徒之中。"},sec={{t="从绿木林到腐朽",b="在第三次战争之前，这一地区被称为绿木林，是一片与葱郁的艾尔文森林不相上下的生机勃勃的林地。入口附近曾有一个简朴的村庄，农夫和士兵常来常往。但当从安多哈尔运来的被污染的粮食抵达后，这一切便化为乌有。如今，松软且腐烂的土壤取代了肥沃的土地，巨大的蘑菇遮蔽了枯死的树木，不断向林地表面喷吐着有害的褐色蒸汽。"},{t="死亡的堡垒",b="病木林现已完全被天灾军团占据，成为了环绕斯坦索姆的不死生物的阴森集结地。通灵塔和屠宰场星罗棋布地散落在腐朽的土地上，源源不断地制造出憎恶和邪教徒。更糟糕的是，狂热的血色十字军在通往斯坦索姆大门的道路上不分昼夜地巡逻，他们急于肃清天灾军团，并会残忍地屠杀遇到的任何活着的旅行者。"}},faq={{q="瘟疫发生前，这片森林叫什么名字？",a="在第三次战争之前，该地区被称为绿木林。它曾是一片繁茂的森林，入口处有一个小村庄，在美景和气候上与艾尔文森林非常相似。",al={"病木林旧称","绿木林背景知识","病木林是什么"}},{q="为什么这里到处长着巨大的蘑菇？",a="瘟疫从根本上扭曲了当地的生态系统。土壤变得松软，巨大的真菌在林地上疯狂生长，喷发出有害的褐色云雾，就像瘟疫大锅里冒出的蒸汽一样。",al={"病木林巨型蘑菇","病木林真菌","为什么有蘑菇"}},{q="如今谁控制着病木林？",a="这片森林几乎完全被天灾军团控制，其中包括亡灵法师、食尸鬼、通灵塔和屠宰场。此外，血色十字军的巡逻队经常在主干道上行进，攻击所见的不死生物和任何活着的旅行者。",al={"谁统治病木林","病木林敌人","谁住在病木林"}},{q="穿过森林的路通向哪里？",a="主路直接向北延伸，通往陷落的斯坦索姆城大门，而这片被瘟疫侵蚀的森林西部则向着废弃的恐惧谷延伸。",al={"病木林道路终点","小径通向何处","斯坦索姆之路"}}},fp="10,276,23.444.0,21.427.0,46.176.0,51.204.0,34.257.0,43.184.0"}
P.entries["subzone:plaguewood-tower"] = {n="Plaguewood Tower",s="Plaguewood Tower是一座洛丹伦的废弃哨塔，位于病木林北端，临近恐惧谷。在天灾军团入侵期间，它被摧毁殆尽，如今只剩下一片残垣断壁，矗立在这片被瘟疫侵蚀的森林中。",h="Plaguewood Tower是一座洛丹伦的废弃哨塔，位于病木林北端，临近恐惧谷。在天灾军团入侵期间，它被摧毁殆尽，如今只剩下一片残垣断壁，矗立在这片被瘟疫侵蚀的森林中。",kw={"东瘟疫之地","洛丹伦","哨站","病木林","plaguewood tower","天灾军团","恐惧谷","瞭望塔"},ang={["faction:Alliance"]="对于联盟军队来说，洛丹伦这些破碎的瞭望塔是一个痛苦的提醒，时刻警示着他们人类失守于天灾军团的领土。",["faction:Horde"]="对于部落来说，像Plaguewood Tower这样的废弃防御工事展示了天灾军团是如何彻底击垮北方王国的防御的。"},sec={{t="北方的废墟哨岗",b="Plaguewood Tower坐落在被瘟疫笼罩的病木林边缘，毗邻遭到腐蚀的城镇恐惧谷，曾经是洛丹伦王国重要的北方监视哨。当天灾军团席卷这片大地时，这座防御工事被夷为废墟，留下的残砖碎石被淹没在受腐蚀的真菌树冠之下。如今，这些破裂的石块依然俯瞰着北方的道路，无声地提醒着人们，洛丹伦曾经在这片土地上履行过守望的职责。"}},faq={{q="Plaguewood Tower最初的用途是什么？",a="Plaguewood Tower由洛丹伦王国建造，作为区域性的瞭望塔。在第三次战争之前，驻扎在此的卫兵负责守卫北方的森林、道路和像恐惧谷这样的定居点，直到天灾军团攻陷并摧毁了这处驻地。",al={"最初用途","谁建造了plaguewood tower","哨塔历史"}},{q="这座塔的具体位置在哪里？",a="它位于东瘟疫之地的北部区域，在病木林内，紧邻已成废墟的恐惧谷，位于斯坦索姆外围瘟疫区的南面。",al={"哨塔位置","plaguewood tower在哪里","地图位置"}}},fp="16,214,30.448.0,46.257.0,35.182.0"}
P.entries["subzone:pool-of-ask-ar"] = {n="Pool of Ask'ar",s="Pool of Ask'ar是一个广阔的淹没式洞穴湖泊，位于黑暗深渊的深处。这里挤满了水生野兽和邪恶的纳迦入侵者，其水下隐藏着古老的暗夜精灵建筑，以及蜿蜒深入这座堕落圣殿的隐秘通道。",h="Pool of Ask'ar是一个广阔的淹没式洞穴湖泊，位于黑暗深渊的深处。这里挤满了水生野兽和邪恶的纳迦入侵者，其水下隐藏着古老的暗夜精灵建筑，以及蜿蜒深入这座堕落圣殿的隐秘通道。",kw={"黑暗深渊","drowned sacellum","加摩拉","萨利维丝","洛迦里斯手稿","纳迦","pool of ask'ar"},ang={["faction:Alliance"]="必须穿过这些水路才能揭开银月守卫塞尔瑞德的命运，他为了执行对抗暮光之锤的神圣任务而冒险进入了这些洞穴深处。",["race:NightElf"]="水潭淹没了曾经神圣的艾露恩神殿区域，淹没了古老的建筑，并将洛迦里斯手稿等神圣遗物散落各处，任由纳迦搜刮。"},sec={{t="沉没洞穴的深处",b="Pool of Ask'ar位于Drowned Sacellum之外，填满了一个巨大的地下穹顶，水质浑浊而冰冷。天然洞穴和古老的石构建筑已成为大型鳄龟和深海蟹的筑巢地，由巨大的远古龟类加摩拉监视着。占据了神殿的纳迦将这个淹没的门槛用作防御集结地，守卫着通往建筑深处，前往萨利维丝和Moonshrine Ruins的积水通道。"},{t="水面之下的秘密",b="除了怪异的动物群和敌对巡逻队，水潭的水下还隐藏着神殿大分裂之前的珍贵遗物。沿着洞穴边缘的淹没岩架和隐蔽壁龛藏匿着失落的神器，包括铁炉堡的矮人学者葛利·硬骨所寻找的珍贵的洛迦里斯手稿。游过洪水泛滥的南部通道，旅行者将进入由邪恶鱼人和古神信徒守卫的干燥隧道，这使得水潭成为了黑暗深渊关键的水路十字路口。"}},faq={{q="Pool of Ask'ar是什么？",a="这是一个位于黑暗深渊内的巨大地下水潭，就在Drowned Sacellum的后面。这里主要由鳄龟、螃蟹和纳迦守卫占据。",al={"pool of askar","这是什么水潭","黑暗深渊水域"}},{q="谁居住在这个地下水潭里？",a="这个洞穴栖息着野生礁石生物，例如鳄龟和螃蟹，其中最引人注目的是巨大的龟类加摩拉。敌对的纳迦也巡逻着淹没的岸边和附近的房间。",al={"水潭怪物","pool of askar首领","水潭里有什么"}},{q="水下隧道通向哪里？",a="穿过洪水泛滥的南部通道，可以通向由萨利维丝和银月守卫塞尔瑞德占据的房间，并通往绕过格里哈斯特前往Moonshrine Ruins的道路。",al={"水潭隧道","水路通向哪里","pool of askar出口"}},{q="在这个水潭里可以找到什么值得注意的物品？",a="沿水潭边缘的淹没废墟中藏有洛迦里斯手稿，这是一份关于古神的古老文献，被铁炉堡的葛利·硬骨所垂涎。",al={"pool of askar遗物","洛迦里斯手稿","水潭掉落"}}},fx={["87a1a296"]={q="Pool of Ask'ar 危险吗？",a="深入这座被水淹没的洞穴极其危险。敌对纳迦在周围的废墟和通道中巡逻，凶猛的地下螃蟹和钳嘴龟则遍布漆黑的水域。更深的水下还潜伏着古老而庞大的巨兽，随时准备将疏忽大意的游泳者拖入令人窒息的深渊。",al={"pool of ask'ar 危险吗","pool of ask'ar 的危险","pool of ask'ar 里的威胁"}}},fp="14,275,27.526.0,27.525.0,27.158.0,36.192.0,37.194.0,44.152.0"}
P.entries["subzone:pool-of-tears"] = {n="泪水之池",s="泪水之池是一片广阔而浑浊的湖泊，占据了悲伤沼泽的东部区域。在它深邃的湖面之下，坐落着沉没的神庙（阿塔哈卡神庙），它由绿龙军团摧毁并沉入湖底，以封印其中的恐怖。如今，凶猛的狂乱鱼群巡游在浑浊的水中，古老的巨魔遗迹散落在被淹没的岸边。",h="泪水之池是一片广阔而浑浊的湖泊，占据了悲伤沼泽的东部区域。在它深邃的湖面之下，坐落着沉没的神庙（阿塔哈卡神庙），它由绿龙军团摧毁并沉入湖底，以封印其中的恐怖。如今，凶猛的狂乱鱼群巡游在浑浊的水中，古老的巨魔遗迹散落在被淹...",kw={"阿塔莱","狂乱鱼群","泪水之池","沉没的神庙","悲伤沼泽","阿塔哈卡神庙","伊瑟拉"},ang={["class:Druid"]="德鲁伊对这座湖泊怀有敬意，他们认为这是伊瑟拉和绿龙军团介入并遏制血神腐化的地方。",["race:Troll"]="对于暗矛巨魔来说，这片水池是一个严峻的警示，提醒他们如果巨魔一族沉迷于阿塔莱那样被禁的血魔法，会发生什么。"},sec={{t="一座被淹没的圣所",b="很久以前，狂热的阿塔莱巨魔为他们嗜血的神灵——“噬魂者”哈卡，建立了一座宏伟的阶梯金字塔。龙王伊瑟拉对其中发生的亵渎行为感到震惊，她震碎了建筑物下方的地面，将这座庞大的神庙沉入沼泽深处。现有的湖水淹没了神庙的废墟。虽然巨龙试图永远埋葬这份邪恶，但这座金字塔依然矗立在淤泥和波涛之下，绿龙幼龙依然在这一地区保持警惕，以封印其中的腐化。"},{t="危险之水",b="对于任何前往沉没大厅的冒险者来说，航行在这片浑浊的湖面上都是危机四伏的。食肉的狂乱鱼群出没在水中，而阿塔莱的神器和被淹没的石制建筑依然散落在泥泞的湖底。旅行者必须勇敢地面对这些充满敌意的浅滩，才能进入沉没神庙的上层通道，那里的邪教徒和徘徊的龙族守卫正在争夺这座黑暗圣所的控制权。"}},faq={{q="为什么它被称为泪水之池？",a="这个名字的由来并无记载。这座湖泊以阿塔哈卡神庙而闻名，伊瑟拉将其沉入水底，以阻止哈卡的召唤。",al={"泪水之池名字由来","为什么叫泪水之池","泪水之池的含义"}},{q="湖中心那座巨大的建筑是什么？",a="那是阿塔哈卡神庙，通常被称为沉没的神庙。它曾是一座高耸的阿塔莱阶梯金字塔，被伊瑟拉沉入水底，如今仍然部分淹没在湖泊的中心。",al={"泪水之池里的建筑","悲伤沼泽湖泊中的遗迹","沉没的神庙位置"}},{q="为什么水边会有绿龙？",a="伊瑟拉的族群来到这里摧毁了神庙，并淹没了它那邪恶的仪式。绿龙幼龙和龙人依然守护着这片湖泊，以确保阿塔莱邪教徒无法完成他们对血神的召唤。",al={"悲伤沼泽的绿龙","为什么这里有龙","伊瑟拉 神庙 湖泊"}},{q="游过这个湖泊安全吗？",a="不安全。湖中到处都是极具攻击性的食肉狂乱鱼群，它们会攻击任何游向神庙入口的人。",al={"泪水之池游泳","泪水之池的狂乱鱼群","悲伤沼泽的狂乱鱼群"}}},fp="13,329,19.521.0,15.403.0,35.157.0,55.197.0,45.206.0,35.128.0"}
P.entries["subzone:pools-of-arlithrien"] = {n="阿里斯瑞恩之池",s="阿里斯瑞恩之池是位于泰达希尔西部的一片隐秘泉水，就在达纳苏斯大门以南。这里曾经是一处以神圣月亮井为中心的静谧休憩之所，但如今却因当地野生生物和附近怀恨在心的棘木熊怪的侵扰，变得荒废且危险。",h="阿里斯瑞恩之池是位于泰达希尔西部的一片隐秘泉水，就在达纳苏斯大门以南。这里曾经是一处以神圣月亮井为中心的静谧休憩之所，但如今却因当地野生生物和附近怀恨在心的棘木熊怪的侵扰，变得荒废且危险。",kw={"阿里斯瑞恩","达纳苏斯","熊怪","棘木","月亮井","阿里斯瑞恩之池","泰达希尔"},ang={["class:Druid"]="研究泰达希尔失衡现象的德鲁伊们认为，这里桀骜不驯的野生生物和荒废的月亮井，是这棵巨树缺乏自然真正祝福的又一征兆。",["race:NightElf"]="在达纳苏斯附近废弃一座神圣月亮井，这对于暗夜精灵来说是一个令人不安的提醒，意味着腐化和混乱正在泰达希尔蔓延。"},sec={{t="一处困顿的圣所",b="阿里斯瑞恩之池掩映在达纳苏斯南部的阴凉树荫之下，最初本是一处充满自然和谐的宁静之地。其核心是一口石质月亮井，其中盛满了被艾露恩恩泽所灌注的井水。然而，尽管此处离暗夜精灵首都近在咫尺，却已变得危机四伏。焦躁的野兽在浅滩徘徊，加上流离失所的棘木熊怪持续不断的敌意，迫使暗夜精灵放弃了对该遗址的日常维护，使得这处宁静的奇迹笼罩在岛屿日益增长的不安阴影之下。"}},faq={{q="阿里斯瑞恩之池位于何处？",a="这些水池坐落在泰达希尔的西部边缘，位于通往首都达纳苏斯的主桥和入口以南。",al={"阿里斯瑞恩之池位置","阿里斯瑞恩在哪里","阿里斯瑞恩地图"}},{q="为什么这里的月亮井会被废弃？",a="由于危险日益增加，暗夜精灵撤出了对月亮井的日常照料。充满敌意的棘木熊怪在附近建立了威胁性的据点，而富有攻击性的森林野生生物也占领了周围的水域。",al={"为何废弃","阿里斯瑞恩月亮井废弃","空置的月亮井"}},{q="旅行者在水池会遇到什么威胁？",a="在水池附近徘徊的旅行者不仅要面对占领了水域的攻击性林地生物，还要提防附近极具领地意识的棘木熊怪所带来的威胁。",al={"阿里斯瑞恩怪物","阿里斯瑞恩之池小怪","水池处的敌人"}},{q="玩家还能使用阿里斯瑞恩之池的月亮井吗？",a="可以。尽管由于当地的危险，祭司和德鲁伊已经不再照料并废弃了这里，但月亮井本身依然保存着神圣的井水，仍然是月亮精华的有效来源。",al={"使用阿里斯瑞恩月亮井","月亮井是否可用","水池的水"}}},fx={["66076687"]={q="阿里斯瑞恩之池是什么地方？",a="阿里斯瑞恩之池是位于泰达希尔西部的一片宁静池塘群，就在通往达纳苏斯的大门以南。这里原本是一处以圣洁月亮井为中心的静谧圣地，如今却已荒废失序。",al={"阿里斯瑞恩之池的传说","阿里斯瑞恩之池是什么地方","关于阿里斯瑞恩之池"}},["3cd7c020"]={q="阿里斯瑞恩之池发生了什么？",a="这片圣地曾是供人沉思和礼拜的宁静去处，却难以抵御当地野生动物日益增强的敌意，以及 Gnarlpine 熊怪步步逼近的威胁。暗夜精灵看护者最终被迫撤离，任由池水无人照料。",al={"阿里斯瑞恩之池的历史","阿里斯瑞恩之池发生了什么"}}},fp="19,305,20.549.0,42.146.0,36.216.0,45.190.0,62.185.0"}
P.entries["subzone:pools-of-vision"] = {n="预见之池",s="预见之池是位于雷霆崖灵魂高地下方的一处地底洞穴。这里水面平静，光线昏暗，是一处隐蔽的地下空间，也是被遗忘者在牛头人主城内的主要聚集地。",h="预见之池是位于雷霆崖灵魂高地下方的一处地底洞穴。这里水面平静，光线昏暗，是一处隐蔽的地下空间，也是被遗忘者在牛头人主城内的主要聚集地。",kw={"污染者","被遗忘者","法师传送门","预见之池","灵魂高地","雷霆崖","亡灵聚集地"},ang={["class:Mage"]="该洞穴锚定了通往城市的奥术地脉连接；任何织入雷霆崖的传送法术都会将施法者直接传送到这些隐蔽的池水旁。",["race:Undead"]="对于穿越卡利姆多平原的被遗忘者来说，这处洞穴提供了一个熟悉且阴凉的避难所，配备了奥术资源、牧师指引和同伴情谊。"},sec={{t="台地之下的避难所",b="虽然雷霆崖阳光明媚的峰顶属于风、大地和天空，但预见之池却直通灵魂高地下方的幽暗深处。通过通往高地的桥梁旁一条不起眼的洞穴小径即可进入，这处地下石窟提供了一种与上方露天营地截然不同的幽静休憩之所。薄雾笼罩的池水在此汇聚，营造出一种隔绝的氛围，部落的施法者们聚集于此，远离了喧闹的中央台地。"},{t="亡灵前哨",b="在雷霆崖，预见之池实际上是被遗忘者的行动基地。来自东部王国的旅行者在这里能找到志同道合的同伴：练习暗影之道的亡灵牧师、施展奥术传送门的法师，以及为阿拉希高地的战事招募新兵的污染者特使。无论是出于牛头人的猜忌，还是被遗忘者自身对黑暗的偏好，这处安静的避难所连接起了洛丹伦的亡灵与他们在卡利姆多的盟友。"}},faq={{q="预见之池的入口在哪里？",a="入口位于灵魂高地上，就在穿过从下层台地通往高地的木制绳桥后，右侧即是。",al={"如何前往预见之池","预见之池入口","预见之池在哪里"}},{q="为什么被遗忘者住在这里？",a="这个洞穴是驻扎在雷霆崖的被遗忘者的中心枢纽。它提供了躲避卡利姆多强烈阳光的庇护所，并容纳了那些可能会让传统牛头人灵术士感到不安的修行活动。",al={"为什么亡灵在这里","为什么被遗忘者在洞穴里","雷霆崖亡灵"}},{q="在预见之池里可以找到哪些服务？",a="洞穴内有牧师和法师的训练师与修行者，还有为阿拉希高地战争招募士兵的污染者特使。",al={"预见之池训练师","预见之池有什么"}},{q="法师传送到雷霆崖时会到达哪里？",a="施放传送或开启通往雷霆崖的传送门的法师，会直接出现在灵魂高地下方预见之池那片隐蔽的水域中。",al={"法师传送雷霆崖位置","雷霆崖传送点"}}},fx={["746eaf51"]={q="预见之池是什么地方？",a="预见之池是一处地下洞穴和水淹溶洞，藏在灵魂高地的高崖之下。这里远离地面上的旷野之风和阳光平原，是一处潮湿的地下隐所，也是奥术技艺的据点，以及驻扎在雷霆崖的被遗忘者的主要聚集地。",al={"预见之池","预见之池是什么地方","关于预见之池"}},f71c91fd={q="预见之池里住着谁？",a="这里主要居住着到访雷霆崖或驻扎于此的被遗忘者。亡灵牧师和法师在此远离上方繁忙的高地修习技艺，也有代表污染者的使节等人来此，为阿拉希盆地的持续战事招募成员。",al={"谁住在预见之池","预见之池的居民","谁管理预见之池"}},["9510841e"]={q="预见之池危险吗？",a="不危险。尽管气氛阴暗沉郁，预见之池对部落成员及其盟友而言完全安全。它是雷霆崖境内的安全据点，容纳着训练师、学者和幽暗城的使节，而非敌对野兽或敌人。",al={"预见之池安全吗","预见之池里的危险","池中有敌意吗"}}},fp="15,238,24.459.0,18.509.0,45.158.0,38.217.0,54.169.0,58.151.0"}
P.entries["subzone:purgation-isle"] = {n="赎罪岛",s="赎罪岛是一座蜿蜒崎岖的岩石岛屿，位于希尔斯布莱德丘陵南部的海岸外。这座荒凉的礁石岛上矗立着一座墓地和一座荒废的侦察塔，它被诅咒所笼罩，到处都是人类和矮人死后不安、受谴责的灵魂。",h="赎罪岛是一座蜿蜒崎岖的岩石岛屿，位于希尔斯布莱德丘陵南部的海岸外。这座荒凉的礁石岛上矗立着一座墓地和一座荒废的侦察塔，它被诅咒所笼罩，到处都是人类和矮人死后不安、受谴责的灵魂。",kw={"被诅咒的阿拉多斯","希尔斯布莱德","法官塞尔格拉姆","科尔莫克","赎罪岛","灵魂"},ang={["class:Paladin"]="被诅咒的圣骑士和审判官在赎罪岛上游荡的悲惨景象，令人沉重地意识到，当神圣的保卫者堕落于黑暗诅咒并被拒绝永恒安息时，会发生什么。",["race:Dwarf"]="在墓地中游荡的受诅咒幽灵中，还有矮人的灵魂，将你的族人束缚在这块远离卡兹莫丹群山的孤独而多风的岩石上。"},sec={{t="一个闹鬼的避难所",b="赎罪岛从希尔斯布莱德以南的海面上突兀地升起，是一处阴森的地方，蜿蜒的小径穿过墓碑，通向一座废弃的瞭望塔。如今没有任何活着的国家宣称拥有它。相反，这座岛屿饱受受谴责的灵魂折磨——曾经的圣骑士、牧师、法师和法官在坟墓间游荡，无法在死亡中获得安宁。"},{t="黑暗关联",b="困在岛上的游魂使其成为了一个充满邪恶意味的地方。据说食人魔死灵法师科尔莫克（Kormok）等黑暗施法者很乐于利用岛上痛苦的死者，召唤这些灵魂为他们效命。"}},faq={{q="赎罪岛位于哪里？",a="赎罪岛是一座与世隔绝的岛屿，位于希尔斯布莱德丘陵南海岸外，坐落在大陆以南的海湾中。",al={"赎罪岛位置","赎罪岛在哪里","如何找到赎罪岛"}},{q="什么在岛上游荡？",a="岛上到处都是强大的受谴责灵魂，包括被诅咒的圣骑士、审判官、牧师、侍僧，以及人类和矮人后裔的痛苦法师。",al={"赎罪岛上有什么人","赎罪岛怪物","赎罪岛鬼魂"}},{q="科尔莫克是谁，他为什么关心这座岛屿？",a="科尔莫克是一位臭名昭著的食人魔死灵法师，他掌握了利用特制的黑暗神器召唤赎罪岛上受谴责的灵魂为他效劳的技巧。",al={"科尔莫克关联","召唤火盆鬼魂"}}},fx={["17b72096"]={q="赎罪岛是什么地方？",a="赎罪岛从希尔斯布莱德丘陵以南的海面上拔地而起，是一座盘旋而险峻的岩石岛屿，顶端矗立着杂草丛生的墓园和一座已成残垣的旧瞭望塔。这里早已沦为废墟，荒无人烟，与大陆隔绝，活着的水手都避而远之。",al={"赎罪岛是什么地方","赎罪岛","介绍赎罪岛"}},["6d7a3de4"]={q="赎罪岛危险吗？",a="这里极其危险。岛上遍布不得安息、饱受折磨的幽灵，他们生前是被判罪的圣骑士、牧师、法师和法官，会猛烈攻击任何登岸的活物。更黑暗的势力也企图利用他们；食人魔通灵师 Kormok 因将这些受折磨的灵魂束缚于自己的黑暗意志而臭名昭著。",al={"赎罪岛有多危险","赎罪岛安全吗","赎罪岛的危险"}}},fp="14,258,19.345.0,17.262.0,32.133.0,23.159.0,53.164.0"}
P.entries["subzone:pyrewood-village"] = {n="焚木村",s="焚木村是一座位于银松森林南部、影牙城堡下方的人类定居点。它原本属于吉尔尼斯，但在格雷迈恩之墙建立后被遗弃在墙外。如今，居住在这里的居民正深受疯狂大法师阿鲁高所降下的恐怖诅咒折磨。",h="焚木村是一座位于银松森林南部、影牙城堡下方的人类定居点。它原本属于吉尔尼斯，但在格雷迈恩之墙建立后被遗弃在墙外。如今，居住在这里的居民正深受疯狂大法师阿鲁高所降下的恐怖诅咒折磨。",kw={"阿鲁高","格雷迈恩之墙","月怒","焚木村","影牙城堡","银松森林"},ang={["faction:Alliance"]="这座村庄是洛丹伦幸存人类的一个悲剧缩影，他们白天愿意与旅人进行贸易，而每当黑夜降临，便会屈服于那恐怖的诅咒。",["faction:Horde"]="对于被遗忘者来说，焚木村是一处就在他们边境线上、由敌对人类和侍奉大法师阿鲁高的恐怖狼人所盘踞的据点。"},sec={{t="被切断的城镇",b="焚木村曾是一个繁荣的吉尔尼斯定居点。第二次战争结束后，吉恩·格雷迈恩国王决定将王国封锁在巨大的格雷迈恩之墙后，而焚木村却被留在了城墙北侧。随着天灾军团横扫洛丹伦，被切断了与故国联系的镇民在第三次战争中完全失去了防卫力量。尽管他们侥幸躲过了亡灵大军的第一波进攻，但真正的噩梦却在大法师阿鲁高占据了上方要塞后开始了。"},{t="月怒诅咒",b="大法师阿鲁高从影牙城堡的塔楼中向周围的土地释放了来自异界的野兽，最终诅咒了焚木村的所有活人。白昼之时，镇民看起来与普通人类无异，他们安分地维护着市政厅、铁匠铺和教堂，甚至还会与到访的联盟旅人进行贸易。然而一旦太阳落入地平线，恐怖的变身便会发生：每一位镇民都会转变为残暴嗜血的月怒狼人，并攻击任何不幸滞留在城墙内的生灵。"}},faq={{q="为什么焚木村在晚上会攻击我？",a="镇民们受到了影牙城堡的大法师阿鲁高所施加的黑暗诅咒。在白天，他们保留着人类的形态和正常的思维，但每当夜幕降临，他们就会变身为贪婪的月怒狼人，攻击所有见到的外来者。",al={"焚木村夜间敌对","焚木村狼人变身","为什么他们是狼人"}},{q="为什么焚木村在格雷迈恩之墙外？",a="第二次战争后，吉恩·格雷迈恩国王下令建造格雷迈恩之墙，将吉尔尼斯与外部世界隔绝开来。焚木村恰好位于围墙的另一侧，导致其居民不得不自谋生路。",al={"为什么在墙外","焚木村是吉尔尼斯的吗"}},{q="联盟玩家可以安全地访问焚木村吗？",a="可以，但必须是在白天。当太阳升起时，联盟旅人可以在镇民中行走，并与村里的商人们进行交易。然而，一旦夜幕降临，无论你的阵营为何，整个村庄都会变身为敌对的狼人。",al={"联盟在焚木村是否友好","联盟可以去焚木村吗","焚木村商人"}},{q="部落如何看待焚木村？",a="被遗忘者认为该村庄是对其南部边境无法容忍的威胁。在亡灵哨兵费雷亚等特工的指挥下，部落试图刺杀该村的议会成员，并切断焚木村与阿鲁高的联系。",al={"被遗忘者与焚木村","部落与焚木村敌对","亡灵哨兵费雷亚与焚木村"}}},fx={be6317a5={q="焚木村是什么地方？",a="焚木村是银松森林南部的一处人类聚居地，位于格雷迈恩之墙外，影牙城堡下方。它原属吉尔尼斯，格雷迈恩国王封锁边境后，村庄便与故土隔绝。在第三次战争期间，村庄奇迹般地躲过了天灾军团的侵袭，保住了市政厅、礼拜堂和铁匠铺。白天，坚韧的村民照常生活，也欢迎友善的联盟旅人；而上方城堡的黑暗魔法始终笼罩着他们。",al={"焚木村是什么","焚木村的背景故事","焚木村信息"}},["9ba6a911"]={q="焚木村发生了什么？",a="吉恩·格雷迈恩国王修筑起宏伟的城墙后，焚木村被留在吉尔尼斯境外，孤立无援。第三次战争期间，村庄挺过了天灾军团的进攻，成为洛丹伦仅存的几处人类据点之一。然而，真正的悲剧发生在大法师阿鲁高将召唤来的狼人释放到席瓦莱恩男爵附近的城堡之后。占据要塞后，阿鲁高给焚木村的幸存村民施加了可怕的诅咒，将他们的命运与自己的疯狂实验紧紧相连。",al={"焚木村历史","焚木村发生了什么"}},fda3e589={q="谁住在焚木村？",a="焚木村由幸存的吉尔尼斯人居民组成，并由当地统治议会管理。城墙关闭、吉尔尼斯与村庄隔绝后，村民只得在绝境中自治。可悲的是，他们真正的主人是从影牙城堡监视他们的大法师阿鲁高。白天，工匠、卫兵和议员以人类的模样维持村庄运转；夜幕降临后，他们却全都屈服于狼人的诅咒。",al={"谁领导焚木村","焚木村居民","谁控制焚木村"}}},fp="16,279,14.484.0,18.571.1,45.250.1,42.215.0,43.254.1,33.228.0"}
P.entries["subzone:quagmire"] = {n="泥潭沼泽",s="泥潭沼泽位于尘泥沼泽中央，是一片广阔而险恶的区域。它北接蕨墙村，南临黑龙谷，其积水的低地以难以通行而臭名昭著。敌对的野兽和贪婪的软泥怪使穿越这片中央湿地的旅程危机四伏。",h="泥潭沼泽位于尘泥沼泽中央，是一片广阔而险恶的区域。它北接蕨墙村，南临黑龙谷，其积水的低地以难以通行而臭名昭著。敌对的野兽和贪婪的软泥怪使穿越这片中央湿地的旅程危机四伏。",kw={"beezil","鳄鱼","尘泥","泥潭沼泽","塔贝萨"},ang={["class:Mage"]="在沼泽深处坐落着Tabetha's Farm，对于那些渴望远离肯瑞托视线、寻求神秘训练的有志法师来说，这里是一个至关重要的目的地。"},sec={{t="沼泽之心",b="泥潭沼泽占据了西起废弃哨塔，东至尘泥海湾的广阔地带，是整个沼泽的荒野核心。这里的地势极不稳定，坚实的土地常常会变成浑浊的水洼和粘稠的泥沼。旅行者不仅要提防潜伏在浮渣下的掠食性鳄鱼、筑巢于枯木丛中的凶猛蜘蛛，还要应对在污泥中渗透的诡异软泥怪。"},{t="逼近的冲突",b="除了自然险阻外，泥潭沼泽还是沼泽内各方势力争夺的变幻莫测的十字路口。在这片泥沼深处坐落着Tabetha's Farm，这是寻求隐士智慧的修行者在沼泽险境中唯一的避难所。"}},faq={{q="泥潭沼泽位于何处？",a="泥潭沼泽覆盖了尘泥沼泽的中心区域。它向西延伸至废弃哨塔，向东延伸至尘泥海湾，北至蕨墙村边界，南抵土地下沉的黑龙谷。",al={"泥潭沼泽位置","泥潭沼泽在哪里","泥潭沼泽地图"}}},fp="8,306,16.411.0,19.259.0,30.225.0"}
P.entries["subzone:quel-lithien-lodge"] = {n="奎尔林斯小屋",s="奎尔林斯小屋是一座与世隔绝的高等精灵狩猎小屋，坐落在东瘟疫之地北部森林覆盖的丘陵地带，靠近通往奎尔萨拉斯的入口。这里的远行者游侠们在枯萎的森林中坚守阵地，他们不仅被天灾军团包围，还遭到被遗忘者特工的猎杀，同时他们还在守护着古老的精灵档案。",h="奎尔林斯小屋是一座与世隔绝的高等精灵狩猎小屋，坐落在东瘟疫之地北部森林覆盖的丘陵地带，靠近通往奎尔萨拉斯的入口。这里的远行者游侠们在枯萎的森林中坚守阵地，他们不仅被天灾军团包围，还遭到被遗忘者特工的猎杀，同时他们还在守护...",kw={"远行者","高等精灵","玛瑞斯农场","奎尔林斯","奎尔萨拉斯名册"},ang={["class:Hunter"]="驻扎在此的远行者代表了几个世纪以来经典的萨拉斯射术，他们在完全与文明社会隔绝的恶劣荒野中维持着生存技能。",["faction:Horde"]="在玛瑞斯农场的纳萨诺斯·凋零者的指挥下，部落勇士被派往此处执行一项致命的任务，旨在通过武力强行夺取高等精灵的记录。"},sec={{t="枯萎之地中的游侠营地",b="在第三次战争之前，奎尔林斯小屋曾是通往奎尔萨拉斯的道路上的一个远行者营地，里面存放着游侠部队的精灵记录。在天灾军团横扫洛丹伦并入侵精灵王国后，这座小屋陷入了困境。如今，这里的游侠们依然在被腐蚀的森林中保持警惕，这是洛丹伦仅存的两处高等精灵主要聚集地之一。"},{t="瘟疫之地的猎物",b="游侠们沉默的守望并非无人知晓。在被污染的森林深处，纳萨诺斯·凋零者——这位曾经与这些精灵们共同训练的孤独人类游侠领主——已经指挥部落勇士潜入奎尔林斯小屋。纳萨诺斯意图夺取“奎尔萨拉斯名册”，这份官方记录记载了游侠部队的详细信息和精灵血统，他下令屠杀小屋的守卫以获取它。奎尔林斯小屋的游侠们发现自己正同时受到昔日盟友和周边亡灵的围攻。"}},faq={{q="为什么东瘟疫之地会有活着的高等精灵？",a="这座小屋长期以来一直是一个远行者营地。即使在天灾军团将该地区夷为平地之后，这里的高等精灵游侠依然留守于此，在靠近通往奎尔萨拉斯的道路上守护着洛丹伦最后的一处精灵据点。",al={"为什么这里有高等精灵","奎尔林斯住着谁","奎尔林斯精灵"}},{q="奎尔林斯小屋的精灵属于联盟吗？",a="不属于。虽然他们对联盟旅行者表现友好，并对部落公开敌视，但该小屋作为一个完全自治的高等精灵定居点运作，没有接受来自暴风城或铁炉堡的任何正式支持或指令。",al={"奎尔林斯精灵属于联盟吗","奎尔林斯阵营"}},{q="为什么纳萨诺斯·凋零者要针对这个小屋？",a="纳萨诺斯·凋零者派遣部落特工攻击该小屋，主要是为了获取“奎尔萨拉斯名册”，这是一份记录了精灵游侠人员和档案的重要历史文件，目前仍存放在小屋的档案库中。",al={"纳萨诺斯为什么要攻击奎尔林斯","游侠领主的命令","奎尔萨拉斯名册"}},{q="奎尔林斯小屋与奎尔丹尼小屋有什么区别？",a="两者都是历史悠久的高等精灵狩猎小屋，但奎尔丹尼小屋坐落在辛特兰，处于友好的蛮锤矮人的保护之下。而奎尔林斯小屋则孤立地坐落在东瘟疫之地的最前线，被困在枯萎的废墟和封闭的奎尔萨拉斯大门之间。",al={"奎尔丹尼与奎尔林斯对比","辛特兰小屋对比"}}},fp="18,308,27.366.0,25.526.1,59.209.0,57.224.0,48.234.0,51.277.0"}
P.entries["subzone:rage-scar-hold"] = {n="怒痕堡",s="怒痕堡是开凿在菲拉斯荒野中的一个洞穴，坐落于大陆之上，距离羽月要塞不远。这里因栖息着该地区最凶残的雪人而臭名昭著。奇怪的是，洞穴深处散落的书籍、符号以及暗夜精灵建筑的痕迹表明，在这些野兽占据此地之前，这个大兽穴曾有着更文明的用途。",h="怒痕堡是开凿在菲拉斯荒野中的一个洞穴，坐落于大陆之上，距离羽月要塞不远。这里因栖息着该地区最凶残的雪人而臭名昭著。奇怪的是，洞穴深处散落的书籍、符号以及暗夜精灵建筑的痕迹表明，在这些野兽占据此地之前，这个大兽穴曾有着更文...",kw={"古墓穴","羽月","菲拉斯","魔法书籍","怒痕堡","雪人"},ang={["class:Mage"]="洞穴深处存在奥术符号和被遗弃的典籍，这引发了关于谁在洞穴深处丧命的令人不安的问题。",["race:NightElf"]="肮脏的雪人亵渎了看似古老的古墓穴或圣所，这无情地提醒着人们，荒野的危险正在重新夺回卡多雷的历史领地。"},sec={{t="野兽的领地",b="怒痕堡开凿在菲拉斯崎岖的荒野之中，被一群凶猛的雪人所占据，它们会袭击任何靠近巢穴的人。这些生物让周围的森林小径对联盟哨兵和过往旅人都变得危险重重。虽然雪人在卡利姆多的未开发地区很常见，但怒痕堡的居民却因其原始的侵略性和领地凶猛性而格外引人注目。"},{t="过去的痕迹",b="在洞穴深暗的走廊里，隐藏着古老居住者留下的微妙线索。雕刻的石制品和暗夜精灵风格的建筑暗示这里曾是一个古墓穴或奥术圣所。被遗忘的典籍和神秘的符号残留在泥土和骸骨之间，让旅人们不禁猜测，是不幸的学者遭到了野兽的屠杀，还是雪人受到了此地残留魔法的吸引。"}},faq={{q="怒痕堡是什么地方？",a="怒痕堡是菲拉斯的一个地下洞穴网络，位于大陆上，距离羽月要塞不远。它目前被一群极具攻击性的野性雪人所占据。",al={"怒痕堡","这个洞穴是什么","菲拉斯雪人洞穴"}},{q="为什么雪人巢穴里会有书籍和符号？",a="堡垒内部遗弃着典籍、卷轴和奥术符号。虽然这些野蛮的生物不可能识字或研究法术，但这些遗迹表明，这个洞穴曾是那些不幸的施法者或暗夜精灵学者的家园，他们最终成了雪人的受害者。",al={"为什么雪人洞穴里有书","雪人在研究魔法吗","怒痕堡书籍"}},{q="这个洞穴是暗夜精灵建造的吗？",a="洞穴内部有着暗夜精灵的石刻，以及令人想起古墓穴的洞穴结构。内部已没有活着的卡多雷，这意味着最初的居住者要么很久以前就废弃了此地，要么在雪人迁入时被消灭了。",al={"暗夜精灵建筑","怒痕堡曾是精灵古墓穴吗","菲拉斯古墓穴"}},{q="这里的雪人与其他卡利姆多的雪人有什么不同吗？",a="当地旅人指出，怒痕堡的雪人是菲拉斯同类中最凶猛、最具攻击性的，它们以野蛮的暴力守护着它们夺来的地下家园。",al={"菲拉斯雪人","这些雪人有多危险","怒痕堡野兽"}}},fp="14,374,16.391.0,18.421.0,23.186.0,50.262.0,37.241.0,53.193.0"}
P.entries["subzone:ragefire-chasm"] = {n="怒焰裂谷",s="怒焰裂谷是一片位于部落主城奥格瑞玛地下的火山洞穴网络。可以通过大断崖进入，其岩浆照亮的隧道中潜藏着野蛮的穴居人，还有一个妄图从内部瓦解年轻兽人国度的影子议会秘密教派。",h="怒焰裂谷是一片位于部落主城奥格瑞玛地下的火山洞穴网络。可以通过大断崖进入，其岩浆照亮的隧道中潜藏着野蛮的穴居人，还有一个妄图从内部瓦解年轻兽人国度的影子议会秘密教派。",kw={"巴扎兰","cleft of shadow","祈求者耶戈什","奥格瑞玛","怒焰裂谷","灼热之刃","塔拉加曼","穴居人"},ang={["class:Warlock"]="灼热之刃及其恶魔主宰的存在，证明了萨尔的新部落正积极试图根除邪能魔法残留的腐蚀。",["faction:Horde"]="怒焰裂谷代表着主城心脏地带的一个严重安全危机，考验着年轻冒险者保护初生部落的决心。"},sec={{t="街道下的威胁",b="当萨尔在地面上努力巩固杜隆塔尔的同时，地下的危险正在奥格瑞玛的地基之下滋生。怒焰裂谷是一个由火山口和岩浆河组成的不稳定网络，如今已成了凶残的怒焰穴居人的巢穴。这些从隧道深处不明区域涌出的敌对生物，暴力地拒绝了玛加萨·野性图腾提出的外交提议。如果不加制止，它们庞大的数量将威胁到这座主城的根基并将其淹没。"},{t="灼热之刃",b="比穴居人更危险的是灼热之刃，这是一个在裂谷阴影中运作的恶魔影子议会的叛乱教派。在术士祈求者耶戈什、萨特巴扎兰，以及被称为饥饿者塔拉加曼的高大邪能卫士的指挥下，这些邪教徒密谋摧毁萨尔的部落。虽然尼鲁·火刃声称反对他们，但该教派正在积极地测试他们的力量，并试图从下方破坏兽人的新家园。"}},faq={{q="怒焰裂谷的入口在哪里？",a="入口位于奥格瑞玛深处的大断崖内，就在术士尼鲁·火刃的帐篷旁边。",al={"怒焰裂谷入口","如何前往怒焰裂谷","怒焰裂谷的位置"}},{q="谁住在怒焰裂谷里？",a="裂谷中充斥着极具攻击性的怒焰穴居人，并被灼热之刃占据，这是一个与影子议会有联系的邪教组织。他们的首领是术士祈求者耶戈什、萨特巴扎兰以及邪能卫士饥饿者塔拉加曼。",al={"怒焰怪物","怒焰裂谷里的敌人","谁控制了怒焰裂谷"}},{q="为什么萨尔没有清理这个裂谷？",a="部落在建立杜隆塔尔和防御外部威胁方面已捉襟见肘。大酋长萨尔依靠有能力的勇士深入洞穴，在穴居人突破城市街道之前消灭灼热之刃的领导层并控制穴居人的数量。",al={"为什么萨尔容忍怒焰裂谷存在","萨尔怒焰裂谷"}},{q="联盟玩家可以进入怒焰裂谷吗？",a="可以，但想要到达那里需要潜入奥格瑞玛的大门，并深入守卫森严的大断崖，这对联盟的冒险者来说是一项极其危险的任务。",al={"联盟可以打怒焰裂谷吗","联盟在怒焰裂谷"}}},fx={["1ca63580"]={q="怒焰裂谷是什么地方？",a="怒焰裂谷是位于部落首都奥格瑞玛正下方的地下火山洞穴网络。从暗影裂口深处即可进入，蜿蜒且充满熔岩的隧道延伸在城市街道下方，穴居人和危险的教徒就在大酋长脚下潜伏。",al={"怒焰是什么","怒焰裂谷简介","怒焰裂谷背景故事"}},["16537ee3"]={q="怒焰裂谷发生了什么？",a="深居地下的穴居人涌入熔岩隧道，残暴地拒绝了牛头人长者玛加萨·野性图腾的和平提议。一个名为火刃氏族的暗影议会分支趁此隐蔽之机，在隧道中站稳脚跟，利用火热的深处秘密策划反对奥格瑞玛的阴谋。",al={"怒焰裂谷历史","怒焰背景故事","怒焰发生了什么"}},["79d825b2"]={q="怒焰裂谷危险吗？",a="它对奥格瑞玛构成迫在眉睫的威胁。成群的暴虐穴居人随时可能涌上街头；而火刃氏族的教徒则在恶魔守卫饥饿者塔拉加曼、萨特巴扎兰和术士耶戈什的指挥下，积极从暗处密谋推翻萨尔的部落。",al={"怒焰有多危险","怒焰裂谷的威胁","怒焰危险吗"}}},fp="14,283,28.459.0,17.450.1,40.128.0,32.235.1,40.270.0,42.200.0"}
P.entries["subzone:ragefire-chasm-classic"] = {n="Ragefire Chasm (Classic)",s="怒焰裂谷是位于奥格瑞玛地下的一个广阔的火山隧道网，可以通过暗影裂口阴暗的深处进入。尽管位于部落主城的下方，这些灼热的洞穴中却爬满了敌对的穴居人，以及忠于暗影议会的阴谋邪教徒。",h="怒焰裂谷是位于奥格瑞玛地下的一个广阔的火山隧道网，可以通过暗影裂口阴暗的深处进入。尽管位于部落主城的下方，这些灼热的洞穴中却爬满了敌对的穴居人，以及忠于暗影议会的阴谋邪教徒。",kw={"巴扎兰","cleft of shadow","祈求者耶戈什","怒焰裂谷","灼热之刃","饥饿者塔拉加曼","穴居人"},ang={["faction:Horde"]="清理怒焰裂谷是保卫家园的一环，旨在保护杜隆塔尔的基石免受内部破坏，并铲除恶魔同谋者。",["race:Tauren"]="长者玛加萨·野性图腾曾派遣使节与入侵的穴居人求和；他们血腥的拒绝证明了面对这些地底野兽，外交是不可能的。"},sec={{t="潜藏的危机",b="在奥格瑞玛坚硬的街道和高耸的塔楼之下，坐落着怒焰裂谷，这是一片充满岩浆的险恶地下洞穴。最近，这些隧道被从深层地壳裂隙中涌出的野蛮的怒焰穴居人所占据。来自牛头人的玛加萨·野性图腾曾试图与这些生物进行和平外交，但她的提议遭到了暴力的拒绝。如果不加以遏制，穴居人将威胁要进一步挖掘，直到危及城市本身的地基。"},{t="灼热之刃",b="比那些毫无理智的穴居人更危险的是“灼热之刃”的存在，这是一个隶属于恶魔暗影议会的叛乱邪教。在魁梧的邪能卫士饥饿者塔拉加曼、兽人术士祈求者耶戈什以及堕落萨特巴扎兰的领导下，这些阴谋家企图瓦解萨尔的部落在杜隆塔尔建立的一切。大酋长萨尔并没有立即清理这些洞穴，而是保持对他们活动的监视，希望他们愚蠢的过度自信能暴露暗影议会高层的行踪。"}},faq={{q="怒焰裂谷的入口在哪里？",a="入口传送门位于奥格瑞玛深处，具体是在被称为暗影裂口的地下峡谷中。它靠近兽人术士尼鲁·火刃的帐篷。",al={"怒焰裂谷在哪里","怒焰裂谷入口","如何前往怒焰裂谷","怒焰裂谷位于何处"}},{q="为什么奥格瑞玛下面会有穴居人？",a="穴居人从杜隆塔尔下方古老而深邃的洞穴系统中浮出，直接进入了城市的火山地底。他们突然的入侵对主城构成了结构和物理上的危害，而且他们拒绝任何和平遏制的尝试。",al={"为什么这里有穴居人","怒焰穴居人","奥格瑞玛穴居人"}},{q="为什么萨尔允许邪教徒生活在主城下面？",a="大酋长萨尔完全知晓邪教在城下的存在。他没有发动可能会导致更广泛的网络四散奔逃的粗暴突袭，而是让他们在严密监视下活动，希望他们能无意中揭露暗影议会真正领导者的身份和下落。",al={"为什么萨尔不清理怒焰裂谷","萨尔 暗影议会","为什么灼热之刃在奥格瑞玛地下"}},{q="谁领导着裂谷里的邪教徒？",a="怒焰裂谷里的灼热之刃由三个人物指挥：可怕的邪能卫士饥饿者塔拉加曼；兽人术士祈求者耶戈什；以及背叛的萨特巴扎兰。",al={"怒焰裂谷首领","谁领导灼热之刃","怒焰裂谷领袖"}}},fx={["4401cb77"]={q="怒焰裂谷是什么地方？",al={"怒焰裂谷背景故事","怒焰是什么","怒焰裂谷简介"}},db99bdf4={q="怒焰裂谷发生了什么？",a="奥格瑞玛建立起来后，野蛮的穴居人开始从城市下方灼热的隧道中涌出。玛加萨·野性图腾试图与他们谈判求和，但穴居人只以暴力回应。崇拜恶魔的教徒趁地下混乱之际潜入火热的隧道，建立了一个隐秘据点；他们被称为火刃氏族。",al={"怒焰裂谷历史","怒焰发生了什么"}},["9f581f16"]={q="谁住在怒焰裂谷？",a="洞穴中充斥着野蛮的怒焰穴居人、四处游荡的元素生物和火刃氏族的教徒。这个暗影议会的秘密分支盘踞在更深处的隧道中，听命于术士祈求者耶戈什、萨特巴扎兰，以及名为饥饿者塔拉加曼的残暴召唤恶魔守卫。",al={"谁住在怒焰","怒焰裂谷的居民","怒焰裂谷里有哪些人"}},f1dd8474={q="怒焰裂谷危险吗？",a="危险。除了熔岩和沸腾的洞室，裂谷本身也对奥格瑞玛构成生死存亡的威胁。若不加以遏制，敌对的穴居人可能成群涌上地面；与此同时，火刃氏族正直接在萨尔的权力中心下方施展恶魔仪式与黑暗巫术，密谋毁灭部落的新家园。",al={"怒焰危险吗","怒焰裂谷的威胁","怒焰的危险"}}},fp="24,324,14.477.0,17.567.1,40.181.0,39.254.0,57.310.0,40.189.0"}
P.entries["subzone:raptor-grounds"] = {n="迅猛龙巢穴",s="迅猛龙巢穴位于南贫瘠之地尘土飞扬的丘陵深处，是一座被阳鳞迅猛龙占据的隐蔽山谷。与普通的野生野兽不同，这里的兽群展现出一种诡异、善于使用工具的狡黠，并且有一种强迫性地从附近定居点偷取闪亮饰品的冲动。",h="迅猛龙巢穴位于南贫瘠之地尘土飞扬的丘陵深处，是一座被阳鳞迅猛龙占据的隐蔽山谷。与普通的野生野兽不同，这里的兽群展现出一种诡异、善于使用工具的狡黠，并且有一种强迫性地从附近定居点偷取闪亮饰品的冲动。",kw={"北方城堡","迅猛龙巢穴","迅猛龙","被偷走的银币","阳鳞迅猛龙","贫瘠之地"},ang={["class:Hunter"]="阳鳞兽群不同寻常的狡黠、群体协调能力以及建造简易住所的能力，使其成为任何熟练追踪者眼中令人着迷的研究对象。",["faction:Horde"]="阳鳞迅猛龙对南贫瘠之地各处的部落车队和哨所构成了反复出现的威胁，促使人们针对被盗的财富发布悬赏并组织回收远征队。"},sec={{t="南部荒野的奇异野兽",b="迅猛龙巢穴位于北方城堡以西，是阳鳞迅猛龙的主要筑巢地。旅行者们很快就会发现，这些生物绝非毫无思想的掠食者：它们表现出非同寻常的智慧，会制造简陋的住所、组装原始工具，并协调进行狩猎。在对闪亮和奇异物品的执着驱使下，兽群经常袭击过往的车队和部落营地，将硬币、饰品和补给品拖回它们的峡谷巢穴中。"}},faq={{q="迅猛龙巢穴在哪里？",a="迅猛龙巢穴是南贫瘠之地南部的一座小型下沉式山谷，坐落在北方城堡以西的岩石丘陵中。",al={"迅猛龙巢穴位置","迅猛龙巢穴在哪里","迅猛龙巢穴地图"}},{q="为什么这里的迅猛龙与普通野兽不同？",a="阳鳞迅猛龙表现出非同寻常的智慧。它们不仅仅依赖野蛮的本能，还会组装原始工具并建造粗糙的小屋来庇护兽群并隐藏偷来的财物。",al={"阳鳞迅猛龙智慧","为什么迅猛龙会有小屋","贫瘠之地聪明的迅猛龙"}},{q="为什么迅猛龙会袭击车队并偷取物品？",a="兽群对闪闪发光或不同寻常的物体有着痴迷的吸引力。这种迷恋驱使它们伏击旅行者并洗劫部落定居点，将偷来的钱币和金属囤积在山谷深处。",al={"迅猛龙偷走的银币","为什么迅猛龙会偷东西","迅猛龙闪亮的东西"}},{q="谁控制着这个山谷？",a="没有任何阵营控制这个山谷。它依然是野生阳鳞迅猛龙未被驯服的狩猎和筑巢领地，它们会激烈地捍卫这里，抵御任何闯入者。",al={"谁拥有迅猛龙巢穴","迅猛龙巢穴属于部落吗"}}},fx={["5f1076b0"]={q="迅猛龙巢穴是什么地方？",al={"迅猛龙巢穴是什么","迅猛龙巢穴信息","迅猛龙巢穴简介"}},["7bb1fdc9"]={q="迅猛龙巢穴危险吗？",a="对不留神的旅人来说，这里极其危险。山谷里挤满了太阳鳞迅猛龙，它们表现出令人不安的协作能力和狡诈。它们并非只会捕猎的野兽，还会制作简陋的棚屋和工具，伏击路过的商队，并凶猛地抵御任何闯入者，守护自己的巢区。",al={"迅猛龙巢穴危险吗","迅猛龙巢穴的危险","迅猛龙巢穴有多危险"}},fd15f683={q="为什么叫迅猛龙巢穴？",a="这座山谷的名字直接源自其中大量栖居的太阳鳞迅猛龙。野兽们彻底占据了这片封闭的洼地，在此养育幼崽并建立简陋的群居营地，因此当地人干脆称这里为它们的巢穴。",al={"为什么叫迅猛龙巢穴","迅猛龙巢穴名称的含义","迅猛龙巢穴名称的由来"}}},fp="14,278,37.521.0,28.136.0,54.208.0,51.214.0,25.171.0"}
P.entries["subzone:raptor-ridge"] = {n="恐龙岭",s="恐龙岭是湿地东部一片高耸、崎岖的开阔地带，位于龙喉大门西北方。这里是成群凶猛的剃刀猛禽的主要狩猎和筑巢地，在洞穴深处由一只特别凶残的族群首领看守。",h="恐龙岭是湿地东部一片高耸、崎岖的开阔地带，位于龙喉大门西北方。这里是成群凶猛的剃刀猛禽的主要狩猎和筑巢地，在洞穴深处由一只特别凶残的族群首领看守。",kw={"龙喉大门","恐龙岭","剃刀猛禽","剃刀猛禽族母","湿地"},ang={["class:Hunter"]="山脊上凶猛的剃刀猛禽是任何猎人追求敏捷而顽强的沼泽伴侣时的强力选择。"},sec={{t="捕食者的巢穴",b="恐龙岭高耸于湿地东部的沼泽之上，是该地区最危险的荒野之一。凶猛的剃刀猛禽成群结队地徘徊在它的岩架和岩石小径上，使得卡兹莫丹山脚附近的旅行对漫游者来说危机四伏。山脊中心坐落着一个深邃的洞穴，由剃刀猛禽族母统治，其好斗的后代会猛烈地攻击任何入侵的掠食者，或是在龙喉大门附近徘徊的鲁莽旅人。"}},faq={{q="恐龙岭位于哪里？",a="恐龙岭位于湿地的最东端，正处于通往格瑞姆巴托的龙喉大门西北方。",al={"恐龙岭位置","恐龙岭在哪里","如何前往恐龙岭"}},{q="这里生活着哪些生物？",a="山脊上到处都是剃刀猛禽。在洞穴深处，旅行者还能发现正在看护巢穴和幼崽的剃刀猛禽族母。",al={"恐龙岭有哪些怪物","湿地的猛禽","恐龙岭野兽"}},{q="剃刀猛禽族母是谁？",a="剃刀猛禽族母是当地猛禽群中体型巨大且致命的领袖，它盘踞在山脊中央洞穴的巢穴中。",al={"剃刀猛禽族母","湿地猛禽族母","湿地猛禽首领"}},{q="为什么这个地区如此危险？",a="除了成群结队、速度极快且会围攻入侵者的猛禽外，山脊还处于山口附近敌对的龙喉兽人领地的阴影之下。",al={"恐龙岭是否危险","恐龙岭威胁"}}},fx={["26f8859b"]={q="恐龙岭是什么地方？",a="恐龙岭是湿地东部一片崎岖的高地，位于龙喉大门西北方。这里是当地凶猛的剃刀沼泽迅猛龙主要的筑巢地和巢穴；它们在周围的沼泽中猎食，并拼命守护自己的领地。",al={"恐龙岭是什么","恐龙岭概况","介绍一下恐龙岭"}},fcab0786={q="为什么叫恐龙岭？",a="恐龙岭的名字直截了当地源于占据这片高地的大量掠食性迅猛龙。成群的剃刀沼泽迅猛龙在山坡上徘徊，在嶙峋岩壁间筑巢，也藏身于洞穴般的巢穴中。",al={"为什么叫恐龙岭","恐龙岭名称的由来","恐龙岭是怎么得名的"}}},fp="12,284,18.515.0,30.145.0,25.151.0,30.137.0,41.177.0"}
P.entries["subzone:ratchet"] = {n="棘齿城",s="棘齿城是贫瘠之地东海岸的一座繁华中立港口城镇，由热砂港管理。它由总工程师加兹鲁维在协助建造奥格瑞玛后建立，是连接卡利姆多中部与东部王国的海上贸易枢纽。",h="棘齿城是贫瘠之地东海岸的一座繁华中立港口城镇，由热砂港管理。它由总工程师加兹鲁维在协助建造奥格瑞玛后建立，是连接卡利姆多中部与东部王国的海上贸易枢纽。",kw={"贫瘠之地","藏宝海湾","加兹鲁维","少女之爱号","棘齿城","热砂港","斯坦哈德·法尔杉"},ang={["class:Warlock"]="坐落在棘齿城上方悬崖上的高塔，是一个主要的训练场，来自各地的术士们在斯坦哈德·法尔杉和梅纳拉·沃伦德的带领下聚集于此，钻研高等恶魔召唤术。",["faction:Alliance"]="对于联盟冒险者来说，棘齿城提供了一个难得的安全落脚点，使他们得以深入危机四伏的贫瘠之地中心，并可以使用船运和飞行航线。"},sec={{t="无尽之海的十字路口",b="棘齿城坐落在杜隆塔尔与尘泥沼泽之间的干旱海岸线上，为所有携带金币的人提供安全的避风港。这座港口由创业家工程师加兹鲁维在第三次大战争后建立，兴起于各路走私者、流亡者和想要发掘卡利姆多边境财富的大胆商贩之中。它在热砂港的旗帜下运作，在部落与联盟之间保持严格的中立。像“少女之爱”号这样的船只定期横跨无尽之海，航行至藏宝海湾，在各大陆之间运输货物、雇佣兵和原材料。当地的打手们紧盯着码头，严厉打击任何胆敢挑起事端并扰乱商业活动的人。"},{t="码头上的阴影",b="尽管棘齿城表面上是一座充斥着码头、酒馆和工坊的喧闹商贸城镇，但它背后也潜藏着更黑暗的交易。在俯瞰海港的山丘上，坐落着一座隐蔽的高塔，被一个公开的术士集会占据，其中包括斯坦哈德·法尔杉和梅纳拉·沃伦德等人物。当镇民和水手们忙于处理货物清单和地精工程时，这些黑魔法的修行者们在此自由地聚会，与恶魔力量进行沟通，不受传统阵营主城道德约束的困扰。"}},faq={{q="谁统治棘齿城？",a="棘齿城由总工程师加兹鲁维监管，他代表着中立的热砂港进行运作。在因为指导建设奥格瑞玛的基础设施而从大酋长萨尔那里获得了丰厚的报酬后，加兹鲁维建立了这座城镇。",al={"棘齿城领导者","谁负责棘齿城","加兹鲁维 棘齿城"}},{q="联盟玩家可以安全访问棘齿城吗？",a="可以。棘齿城是一座中立的地精港口。只要你与热砂港保持非敌对声望，且不攻击城内的任何人，无论是联盟还是部落的旅行者，都可以使用这里的旅店、银行、商贩、飞行点和渡轮。",al={"棘齿城对联盟安全吗","联盟在棘齿城","联盟能去棘齿城吗"}},{q="棘齿城的船去哪里？",a="停靠在南码头的船只“少女之爱”号，会横跨无尽之海航行至荆棘谷南端的藏宝海湾。它是连接卡利姆多与东部王国的主要海上航线之一。",al={"棘齿城船只目的地","棘齿城的船去哪里","前往东部王国的船"}},{q="为什么镇子上方山丘里有术士？",a="俯瞰棘齿城的高塔内住着一个由斯坦哈德·法尔杉和梅纳拉·沃伦德等人领导的术士集会。热砂港对黑魔法的漠不关心使得这些施法者能够在这里运作、教导学徒并召唤恶魔，而不会受到宗教或民事当局的干扰。",al={"棘齿城术士","斯坦哈德·法尔杉之塔","棘齿城术士塔"}},{q="如果我在棘齿城挑起争斗会怎样？",a="棘齿城打手会立即介入，用沉重的木棒和网兜攻击挑衅者。在地精定居点中，扰乱商业活动是严格禁止的，在这里战斗会迅速降低你与热砂港的声望。",al={"棘齿城守卫","在棘齿城攻击玩家","棘齿城打手"}}},fx={["45ea181b"]={q="棘齿城是什么地方？",a="棘齿城是贫瘠之地东海岸一座繁忙的地精港口，位于奥格瑞玛和塞拉摩岛之间。它由热砂港经营，是卡利姆多首屈一指的中立港口，连接无尽之海上的商贸与旅客，并直通藏宝海湾。",al={"这个地方是什么","棘齿城概况","棘齿城简介"}},["0458c752"]={q="棘齿城发生了什么？",a="第三次战争结束后不久，加兹鲁维创立了棘齿城，资金来自他监督修建奥格瑞玛所得的丰厚报酬。在热砂港的经营下，这里发展成卡利姆多最繁忙的中立港口，部落和联盟的商人都能在此通行。",al={"棘齿城历史","棘齿城是如何建立的","谁建造了棘齿城"}},["42d2f24d"]={q="棘齿城危险吗？",a="在城镇范围内，加兹鲁维手下强横的地精打手会毫不留情地维持秩序；任何想保住牙齿的人都不该在此动武。然而，周边地区遍布敌对的野猪人、沿岸游荡的海盗，以及在附近山丘上施展黑暗法术的神秘术士团伙。",al={"这里安全吗","棘齿城的危险","棘齿城的威胁"}}},fp="7,272,31.707.0,23.547.0,18.248.0,42.248.0,34.239.0,51.291.0,43.248.0"}
P.entries["subzone:ravaged-caravan"] = {n="被破坏的货车",s="“被破坏的货车”是一处位于莫高雷石牛湖北岸、仍在冒烟的残骸。这支运输队曾是运往主管菲兹斯普罗克特采矿作业点的补给车队，后遭到当地牛头人的伏击并被摧毁，牛头人此举意在阻止地精对其家园的掠夺。",h="“被破坏的货车”是一处位于莫高雷石牛湖北岸、仍在冒烟的残骸。这支运输队曾是运往主管菲兹斯普罗克特采矿作业点的补给车队，后遭到当地牛头人的伏击并被摧毁，牛头人此举意在阻止地精对其家园的掠夺。",kw={"莫高雷","被破坏的货车","石牛湖","主管菲兹斯普罗克特","牛头人","荆棘谷地精","货车"},ang={["class:Druid"]="笼罩在石牛湖岸边的黑烟，时刻提醒着人们地精机械对自然平衡所造成的鲁莽破坏。",["race:Tauren"]="这些烧焦的货车代表了你们的人民对于外国工业辛迪加企图玷污莫高雷神圣草场行为的直接而果断的拒绝。"},sec={{t="石牛湖上的浓烟",b="“被破坏的货车”坐落在石牛湖上方的高地上，标志着血蹄村的牛头人与不断侵蚀领土的荆棘谷地精之间爆发的早期冲突。这支车队原定将采矿补给品、蓝图和设备运往主管菲兹斯普罗克特的挖掘现场，但在抵达目的地前就被牛头人防守者拦截并摧毁。尽管遭受了如此惨重的破坏，顽固的荆棘谷地精幸存者仍死守着损毁的货车和冒烟的板条箱，极力守护着仅存的微薄物资。"}},faq={{q="这辆货车发生了什么事？",a="这辆货车被当地的牛头人拦截并摧毁，他们发现了荆棘谷地精深入莫高雷的企图。为了阻止地精掠夺这片土地，牛头人在补给物资运达附近矿洞前就摧毁了整个车队。",al={"为什么货车会被烧毁","这里发生了什么","被破坏的货车背景故事"}},{q="这些损毁的货车属于谁？",a="这辆货车属于荆棘谷地精，这是一个毫无底线的地精采矿财团，正试图在莫高雷的山丘上进行未经许可的非法开采活动。",al={"这是谁的货车","谁拥有这辆货车","荆棘谷地精货车"}},{q="这辆货车原本要前往哪里？",a="它当时正运载着工具、机械和补给品向北行进，目的地是主管菲兹斯普罗克特，他负责指挥荆棘谷地精在风险投资公司矿洞的露天采矿作业。",al={"货车目的地","它要去哪里","菲兹斯普罗克特的补给品"}},{q="为什么还有荆棘谷地精的工人在残骸处徘徊？",a="幸存的荆棘谷地精雇佣兵和工人们对公司的财产有着强烈的保护欲。他们不仅没有放弃这些损失，反而死守在烧焦的货车周围，试图抢救出哪怕是一点点残余的设备。",al={"为什么地精还在这里","荆棘谷地精幸存者","谁在守卫残骸"}}},fx={["71a5a670"]={q="被破坏的货车是什么？",a="被破坏的货车是荆棘谷地精补给车队被焚毁后的残骸，停在石牛湖东北岸的一处土丘上。曾经运送新工具和补给的车队如今只剩冒烟的废墟，四周散落着倾覆的货车和货物。",al={"被破坏的货车是什么","莫高雷被破坏的货车","被破坏的货车"}},["9edfa574"]={q="被破坏的货车为何毁坏了？",a="这支商队遭到拦截，在与当地牛头人的激烈冲突中被摧毁。牛头人眼见一支不受欢迎的地精采矿队践踏他们神圣的祖地，便迅速瓦解了这支远征队，以免其采矿设备被调往莫高雷其他地方支援作业。",al={"货车为何被毁","谁袭击了货车","货车为何被摧毁"}},["0b83cd13"]={q="被破坏的货车危险吗？",a="危险。虽然运载工具已经毁坏，但荆棘谷地精的幸存劳工仍逗留在阴燃的残骸之间。他们拼命想保护货物中所剩无几的东西，会攻击任何靠近残骸的人。",al={"被破坏的货车安全吗","被破坏的货车危险吗","那些工人有敌意吗"}},["87f61f4b"]={q="为什么叫被破坏的货车？",a="这个地点因牛头人袭击后留下的惨烈破坏而得名。远征队仅剩一列破碎的货车、烧焦的补给品，以及升腾在石牛湖上空的滚滚黑烟。",al={"为何叫被破坏的货车","被破坏的货车名称由来","这个名字怎么来的"}}},fp="15,284,25.507.0,30.244.0,28.156.0,30.162.0,63.237.0"}
P.entries["subzone:ravaged-twilight-camp"] = {n="暮光营地废墟",s="暮光营地废墟隐匿在希利苏斯西北部偏远的水晶谷中，在耸立的矿石地层间残破不堪。这里是古怪的隐士德米提恩的孤立据点，他是一位逐风者的信徒。",h="暮光营地废墟隐匿在希利苏斯西北部偏远的水晶谷中，在耸立的矿石地层间残破不堪。这里是古怪的隐士德米提恩的孤立据点，他是一位逐风者的信徒。",kw={"水晶谷","德米提恩","暮光营地废墟","希利苏斯","thunderaan","雷霆之怒","暮光之锤"},ang={["class:Paladin"]="那些寻求古代传奇元素武器的人必须前往水晶谷寻找德米提恩，以解开Thunderaan王子的容器。",["class:Warrior"]="任何追寻传奇武器“雷霆之怒，逐风者的祝福之剑”传闻的勇士，最终都会发现他们的道路直接指向这座被遗弃营地中的德米提恩。"},sec={{t="谷中的隐士废墟",b="虽然暮光之锤在希利苏斯的沙地各处拥有许多活跃的前哨站，但水晶谷中这座破败的营地却有着不同的故事。营地远离教派的主要堡垒，除德米提恩外，大部分已沦为废墟且无人居住。作为Thunderaan的仆从，德米提恩徘徊在乱石之中，仿佛已被更广阔的暮光阶层所遗弃或脱离，独自沉思着元素束缚以及逐风者失落的力量。"}},faq={{q="暮光营地废墟是什么地方？",a="这是一座位于希利苏斯西北部水晶谷中残破的废墟前哨，因是德米提恩的私人居所而闻名。",al={"暮光营地废墟","希利苏斯暮光营地废墟","水晶谷营地"}},{q="谁住在这里？",a="这里唯一的著名居民是德米提恩，一个与元素传说及Thunderaan王子的束缚紧密相连的孤独人物。",al={"暮光营地废墟里有谁","德米提恩位置","营地npc"}},{q="为什么营地会变成废墟？",a="教派记录提到了该地点的废墟状态，但德米提恩依然留在残骸之中，与在希利苏斯活动的其余暮光之锤成员隔绝。",al={"为什么它成了废墟","是什么摧毁了营地","谁袭击了营地"}},{q="这里的暮光之锤是敌对的吗？",a="与希利苏斯南部和中部的喧闹暮光营地不同，这里缺乏具有攻击性的教派巡逻队，让德米提恩得以在宁静中沉思。",al={"教徒会在这里发起攻击吗","德米提恩是敌对的吗"}}},fp="21,246,27.486.0,34.146.0,15.135.0,23.159.0,38.150.0"}
P.entries["subzone:raven-hill"] = {n="乌鸦岭",s="乌鸦岭是暮色森林西部一座荒凉废弃的村庄，坐落在广阔的乌鸦岭墓地的长影之中。这里曾经是一个热闹的人类定居点，如今却已被废弃，只剩下少数几个惊恐的非法定居者和看不见的幽灵。",h="乌鸦岭是暮色森林西部一座荒凉废弃的村庄，坐落在广阔的乌鸦岭墓地的长影之中。这里曾经是一个热闹的人类定居点，如今却已被废弃，只剩下少数几个惊恐的非法定居者和看不见的幽灵。",kw={"废弃的城镇","bliztik","墓地","暮色森林","基特斯","乌鸦岭","unseen"},ang={["faction:Alliance"]="对于从西部荒野过桥而来的联盟旅人来说，乌鸦岭是迎接他们进入吞噬暮色森林西部噩梦的阴森前奏。",["race:Human"]="这些腐朽的小屋提醒着人们，暴风城王国已经因为蔓延的黑暗和疏于管理而失去了多少领土。"},sec={{t="一座被黑暗吞噬的城镇",b="乌鸦岭位于暮色森林西部通道沿线，腐草农场正北，它已沦为昔日繁荣景象的悲惨空壳。当黑暗魔法和亡灵恐怖横扫大汉姆雷特地区时，生者们向东撤离至夜色镇，或是彻底逃离了这片领地。如今，破败的木屋在永恒的阴暗中腐烂，避开了旅人们的足迹，他们既惧怕从邻近墓地游荡而下的The Restless Dead，也恐惧潜伏在残垣断壁间的隐形者Unseen。"},{t="留下的少数人",b="尽管名声惨淡，乌鸦岭并非完全无人居住。一位名叫基特斯的冒险者精神崩溃，躲在废弃的建筑群中，对徘徊在树林里的恐怖生物感到恐惧。在其中一间破旧的阁楼高处，一个名叫Bliztik的地精正通过向谨慎的过路人出售补给品，艰难地维持着独居生活。他们与被称为Unseen的隐形幽灵共享着这些废墟，在这片庞大墓地的边缘苟延残喘。"}},faq={{q="乌鸦岭为什么会被废弃？",a="当阴影笼罩暮色森林，带来亡灵恐怖、黑暗魔法和捕食野兽时，乌鸦岭被废弃了。由于该镇毗邻巨大的乌鸦岭墓地，使其极难防守，幸存的居民被迫向东逃往设防的定居点夜色镇。",al={"乌鸦岭发生了什么","为什么乌鸦岭变成了废墟","谁曾住在乌鸦岭"}},{q="现在还有谁住在村子里？",a="只有少数几个大胆或绝望的灵魂居住在这里。惊恐的人类基特斯躲在废墟地基中，饱受内疚和恐惧的折磨；而地精商人Bliztik则在楼上经营生意，与任何有胆量搜寻这些废弃建筑的人进行交易。",al={"谁在乌鸦岭","乌鸦岭npc","乌鸦岭的活人"}},{q="在乌鸦岭出没的Unseen是什么？",a="Unseen是徘徊在乌鸦岭和附近墓地中的隐形敌对幽灵。虽然肉眼无法看见，但对于任何探索这片荒凉城镇的大意旅人来说，它们的存在构成了突如其来的致命威胁。",al={"乌鸦岭的unseen","乌鸦岭的隐形怪物","乌鸦岭的鬼魂"}},{q="通往乌鸦岭的道路通向哪里？",a="经过乌鸦岭的道路向西连接通往西部荒野的河桥，向南通往腐草农场和荆棘谷的边界，向东穿过暮色森林的中心地带直达夜色镇。",al={"乌鸦岭的道路","道路通向哪里","前往乌鸦岭"}}},fx={["7c03a2db"]={q="乌鸦岭是什么地方？",a="乌鸦岭是暮色森林西部的一座废弃人类村庄，位于广阔的乌鸦岭墓地以南、腐草农场以北。它曾是宁静的大村庄的一处聚居地，在阴影笼罩这片地区之前，如今却在不断逼近的阴霾中变得荒凉破败。",al={"乌鸦岭是什么地方","乌鸦岭镇","介绍乌鸦岭"}},["5a9ec9d9"]={q="乌鸦岭发生了什么？",a="黑暗巫术与腐化势力侵袭大地时，乌鸦岭也遭遇了暮色森林其他地方同样的悲惨命运。恐怖之物纷纷出现，邻近墓地中的死者也开始躁动，镇民要么被赶走，要么遭到屠杀，只留下破败的房屋、四处游荡的掠食者，以及挥之不去的阴影。",al={"乌鸦岭的历史","乌鸦岭发生了什么","乌鸦岭是如何衰败的"}},["03463183"]={q="乌鸦岭危险吗？",a="非常危险。除了在西部森林中徘徊的野兽，废弃建筑里还藏着名为“无形者”的隐形幽灵，而附近墓地中可怕的亡灵不断威胁着要涌入空荡荡的街道。",al={"乌鸦岭有多危险","乌鸦岭的威胁","乌鸦岭安全吗"}}},fp="10,238,23.498.0,18.482.0,28.305.0,38.275.0,40.236.0,44.215.0"}
P.entries["subzone:raven-hill-cemetery"] = {n="乌鸦岭墓地",s="乌鸦岭墓地是一片广袤而受诅咒的墓园，横跨暮色森林的西部。这里曾是当地村落宁静的安息之地，如今却已被成群的行尸、食腐蜘蛛和冷酷的盗墓贼所占据。",h="乌鸦岭墓地是一片广袤而受诅咒的墓园，横跨暮色森林的西部。这里曾是当地村落宁静的安息之地，如今却已被成群的行尸、食腐蜘蛛和冷酷的盗墓贼所占据。",kw={"亚伯克隆比","暮色森林","荒弃鬼屋","盗墓贼","摩拉迪姆","摩本特·费尔","乌鸦岭墓地","骷髅"},ang={["class:Paladin"]="乌鸦岭墓地那无休止的腐化和被亵渎的坟墓，亟需圣光的净化。",["class:Priest"]="这座墓地隐藏着强大的暗影与残留悲伤的导管，作为一种凄凉的教训，警示着那些无法前往圣光的灵魂所遭受的悲剧。"},sec={{t="The Restless Dead之园",b="在黑暗吞噬黎明森林之前，乌鸦岭墓地是周边定居点主要的安息之所。随着黑暗魔法降临此地，死者无法继续安息于坟墓之中。骷髅、食尸鬼和蹒跚的恐怖生物从土壤中爬出，充斥着这座墓园阴森的边界。如今，它是暮色森林中最危险的灾祸之地之一。这里不仅有腐烂的憎恶和巨型蜘蛛徘徊，还有渴望洗劫祖先墓穴、且未受当地势力阻挠的绝望盗墓贼。"},{t="不安的灵魂与黑暗力量",b="乌鸦岭墓地的悲剧化身为摩拉迪姆，它是堕落骑士摩根·拉迪莫尔毫无理智的骷髅化身。他在疯狂与悲伤中结束了自己的生命，如今在墓碑间永无止境地徘徊。再往北，在荒弃鬼屋的高地上，黑暗通灵师摩本特·费尔利用坟墓中的邪恶能量来复活并奴役成群的亡灵。在更远处的东北边缘，坐落着隐士亚伯克隆比的偏僻小屋，他从迷雾边缘注视着这座墓园。"}},faq={{q="为什么乌鸦岭墓地里有这么多亡灵复生？",a="当暮色森林遭受凋零时，这座墓地陷入了黑暗的腐化，使得死灵法术的力量渗入了大地。潜伏在墓园边缘荒弃鬼屋的邪恶法师摩本特·费尔，正积极地扭曲这些能量，将尸体从坟墓中复活并加以控制。",al={"为什么这里有僵尸","为什么乌鸦岭闹鬼","是谁在乌鸦岭复活了死者"}},{q="摩拉迪姆是谁？",a="摩拉迪姆是一个致命的骷髅亡魂，他徘徊在墓园中并攻击旅人。他的身份和过去可以通过在夜色镇进行的调查得知。",al={"摩拉迪姆","在墓地徘徊的骷髅","摩根·拉迪莫尔"}},{q="摩本特·费尔在墓地里的什么位置？",a="摩本特·费尔居住在被称为荒弃鬼屋的小山上，位于乌鸦岭墓地的西北角。他住在一座俯瞰着墓碑的破旧房屋中，指挥着周围的亡灵。",al={"摩本特·费尔的位置","摩本特·费尔在哪里","荒弃鬼屋"}},{q="住在墓地边缘的隐士是谁？",a="这位隐士是亚伯克隆比，一个古怪而虚弱的老人，住在这座墓地东北边界附近的一间破烂小屋里。他经常请求路过的旅人为他收集奇怪的组件和材料，用于他那病态的个人研究。",al={"乌鸦岭的隐士","亚伯克隆比","乌鸦岭的小屋"}}},fx={["7e74b027"]={q="乌鸦岭墓地是什么地方？",a="乌鸦岭墓地是一片规模庞大、绵延广阔的墓地，位于暮色森林西部乌鸦岭镇的北面。它原本只是当地一处小型墓园，随着黑暗诅咒笼罩森林，规模不断扩张，如今已占据大片乡野。这里已无人居住，笼罩在迷雾中的墓地遍布躁动的食尸鬼、骷髅、有毒蜘蛛，以及在遭亵渎的墓碑和墓穴间搜刮财物的冷酷盗墓者。",al={"乌鸦岭墓地是什么地方","乌鸦岭墓地介绍","关于乌鸦岭墓地"}},["0b017ec9"]={q="乌鸦岭墓地发生了什么？",a="墓地最初是一处宁静的安息之地，但随着黑暗势力腐化暮色森林，这里迅速扩张。大地遭到污染，再也无人照料坟墓后，亡灵法师莫本特·费尔搬进了荒弃鬼屋的房子，施展邪恶的魔法，将死者从坟墓中唤醒。",al={"乌鸦岭墓地的传说","乌鸦岭墓地的历史","这里发生了什么"}},d27e3c55={q="乌鸦岭墓地为何被废弃？",a="暮色森林陷入黑暗、死者开始复生后，墓地也逐渐沦为废墟。无人再照料墓穴，而亡灵法师莫本特·费尔还在墓地各处积极复活尸体，普通人只得逃离此地，将它留给搜刮财物的盗墓者和贪婪的亡灵。",al={"乌鸦岭为何沦为废墟","墓地为何被废弃","是谁废弃了乌鸦岭墓地"}},["323c5989"]={q="乌鸦岭墓地危险吗？",a="这是暮色森林最危险的地方之一。墓地里爬满食尸鬼、瘟疫散播者、可怕的骷髅和致命的黑寡妇蜘蛛，冷酷的盗墓者也会攻击任何妨碍他们掠夺的人。更可怕的是莫拉迪姆那令人胆寒、四处游荡的幽魂。这只异常强大的亡灵怪物徘徊在墓碑之间，会让毫无防备的旅人迅速丧命。",al={"乌鸦岭墓地有多危险","乌鸦岭墓地安全吗","乌鸦岭墓地的威胁"}}},fp="19,251,29.579.0,32.497.1,53.274.0,17.161.1,45.206.0,53.252.0"}
P.entries["subzone:ravencrest-monument"] = {n="拉文凯斯雕像",s="拉文凯斯雕像耸立在艾萨拉南部的风蚀悬崖之上，是一座古老的暗夜精灵巨像破碎的残骸。这座雕像曾经是一座俯瞰无尽之海的高大纪念碑，如今早已破碎，只剩下高耸的双腿和散落的石块废墟，现在被敌对的毒皮纳迦所占据。",h="拉文凯斯雕像耸立在艾萨拉南部的风蚀悬崖之上，是一座古老的暗夜精灵巨像破碎的残骸。这座雕像曾经是一座俯瞰无尽之海的高大纪念碑，如今早已破碎，只剩下高耸的双腿和散落的石块废墟，现在被敌对的毒皮纳迦所占据。",kw={"艾萨拉","巨像","埃达拉斯","库塔洛斯·拉文凯斯","拉文凯斯","拉文凯斯雕像","毒皮","雕像"},ang={["class:Warrior"]="拉文凯斯这个名字在战斗指挥官中具有传奇般的份量，因为库塔洛斯·拉文凯斯是燃烧军团灾难性入侵期间凡人军队中最杰出的将军。",["race:NightElf"]="对于暗夜精灵来说，这座纪念碑是一个令人清醒的提醒，让人想起古老的卡多雷帝国和拉文凯斯的高贵血统，正是他们在上古之战中的英勇抵抗拯救了艾泽拉斯，使其免于被恶魔毁灭。"},sec={{t="巨像废墟",b="拉文凯斯雕像高耸于埃达拉斯废墟东南方的海洋之上，曾经是卡多雷石雕艺术的惊世杰作。今天，这座宏伟巨像剩下的只有那对深深扎根于石座之中的巨大断腿，而躯干和头部的残片则深埋在悬崖边的泥土中，或失落于下方的波涛之下。想要到达这处偏远的海岸岬角，需要穿过艾萨拉的陆地桥梁，因为陡峭的岩壁阻断了从海上接近的路线。"},{t="被遗忘的遗产",b="学者们常推测这座纪念碑是为了纪念库塔洛斯·拉文凯斯领主，这位著名的贵族在辛-艾萨里陷落后，于上古之战期间集结并领导了暗夜精灵军队。然而，由于它靠近大分裂之前的埃达拉斯城，且幸存的石雕风格暧昧不清，其真实的起源仍存在争议。如今，这里没有朝圣者或暗夜精灵看守，周边的悬崖已被蛇形的毒皮纳迦占据，它们以凶残的领地意识守护着这座倒塌的纪念碑。"}},faq={{q="拉文凯斯雕像是什么？",a="它是位于艾萨拉南部一处海岸岬角上的巨大暗夜精灵巨像的废墟基座。只有它巨大的石腿依然屹立不倒，而雕像的其他部分则破碎并散落在悬崖顶上。",al={"拉文凯斯雕像","这是什么雕像","艾萨拉的巨腿"}},{q="这座纪念碑是为了纪念谁而建的？",a="它带有拉文凯斯家族的名称，该家族因库塔洛斯·拉文凯斯领主而闻名，他是在上古之战期间领导凡人反抗燃烧军团的贵族指挥官。然而，由于它位于古老的埃达拉斯废墟附近，尚不清楚它是直接纪念库塔洛斯，还是纪念大分裂前的一位更早期的先祖。",al={"拉文凯斯是谁","这座雕像是谁的","库塔洛斯·拉文凯斯"}},{q="如何前往这座纪念碑？",a="由于悬崖峭壁林立，无法从海上攀爬或进入该纪念碑。旅行者必须通过陆路穿过艾萨拉南部，越过埃达拉斯废墟附近的石桥才能到达该岬角。",al={"如何前往拉文凯斯雕像","拉文凯斯路径","拉文凯斯入口"}},{q="如今有什么生物居住在纪念碑处？",a="悬崖顶部和周边的阶地被毒皮纳迦所占据，使得独行的旅行者探索这些古老废墟时险象环生。",al={"这里有什么生物","纪念碑的敌人","艾萨拉纳迦"}}},fp="19,325,19.535.0,18.527.0,32.240.0,36.358.0,30.213.0,42.152.0"}
P.entries["subzone:ravenholdt-manor"] = {n="拉文霍德庄园",s="拉文霍德庄园坐落在希尔斯布莱德丘陵上方的高山之中，是一座隐蔽的总部，也是被称为拉文霍德的盗贼与刺客公会的所在地。在乔拉齐·拉文霍德公爵的统领下，这处庄园为潜行大师们提供了一处远离世人与当局目光的隐秘避难所，让他们得以磨练自己的技艺。",h="拉文霍德庄园坐落在希尔斯布莱德丘陵上方的高山之中，是一座隐蔽的总部，也是被称为拉文霍德的盗贼与刺客公会的所在地。在乔拉齐·拉文霍德公爵的统领下，这处庄园为潜行大师们提供了一处远离世人与当局目光的隐秘避难所，让他们得以磨练...",kw={"奥特兰克","刺客","希尔斯布莱德","乔拉齐·拉文霍德","庄园","拉文霍德","潜行者公会","辛迪加","盗贼"},ang={["class:Rogue"]="拉文霍德庄园是贵职业的首选庇护所，提供严格的试炼、专业的训练以及深厚的地下联络网。",["profession:Engineering"]="眼光独到的工程师会特意穿过山口，从庄园的补给中获取稀有的侏儒隐形装置图纸。"},sec={{t="暗影中的庇护所",b="拉文霍德庄园隐藏在敦霍尔德城堡西北方的一条狭窄山口和蜿蜒洞穴之后，孤零零地矗立在奥特兰克山脉的边境地带。这处地产属于乔拉齐·拉文霍德公爵，他维持着一个纪律严明的盗贼、刺客和情报特工据点。庄园内设有一座宁静的花园和一处由像康恩大师这样的武术专家监督的露天训练场，为练习开锁、制作毒药和近身格斗提供了规范的场地。虽然庄园欢迎那些在诡计方面有天赋的人，但笨拙的外来者和不受欢迎的访客会受到庄园警卫冷漠的怀疑。"},{t="丘陵地带的苦涩恩怨",b="在第一次战争之前，庄园周围的土地曾是奥特兰克王国的一部分，庄园屋顶上风化的橙色瓦片便是明证。在奥特兰克沦陷后的动荡中，辛迪加的没落贵族试图控制该地区，这使他们与拉文霍德产生了直接冲突。对于乔拉齐的追随者来说，在希尔斯布莱德和奥特兰克发生的每一次冲突，都是为了维护他们这处主权避难所而进行的无声战争的一部分。"}},faq={{q="如何前往拉文霍德庄园？",a="若要前往庄园，请前往希尔斯布莱德丘陵中敦霍尔德城堡西北方的台地。在台地与北部山脉交界处附近，有一条不起眼的土路蜿蜒向上，穿过一个隐蔽的洞穴，最终直通庄园场地。",al={"拉文霍德庄园在哪里","如何去拉文霍德","拉文霍德路径"}},{q="谁拥有拉文霍德庄园？",a="这处庄园属于乔拉齐·拉文霍德公爵，他领导着一个被称为拉文霍德的精英盗贼与刺客兄弟会。他在艾泽拉斯的盗贼中享有崇高的威望。",al={"谁领导拉文霍德","拉文霍德公爵","庄园主"}},{q="拉文霍德为何憎恨辛迪加？",a="这两个派系都声称起源于支离破碎的奥特兰克。辛迪加的流亡贵族在丘陵各处诉诸强盗行径和无法无天之举，而拉文霍德则以严明的纪律运作，并积极致力于挫败辛迪加的野心。",al={"拉文霍德与辛迪加","辛迪加恩怨","为何对抗辛迪加"}},{q="任何人都可以参观庄园吗？",a="任何旅行者在物理上都可以走进庄园场地，但驻守在那里的警卫和刺客对局外人持有公开的敌意。潜行者和受信任的特工会受到热烈欢迎并获得深入的训练，而其他人则会收到令人不寒而栗的警告，要求他们离开。",al={"非潜行者在拉文霍德","局外人是否被允许进入拉文霍德"}}},fx={["1390ac44"]={q="拉文霍德庄园是什么地方？",a="拉文霍德庄园是拉文霍德公会隐秘的山间总部。该公会是一个神秘的盗贼与刺客团体。庄园隐匿于希尔斯布莱德与奥特兰克边境上方的高山之中，是一处避难所和训练场。潜行者在这里磨炼技艺、调制隐秘的毒药，并在联盟和部落窥探不到的地方策划秘密行动。",al={"这是什么地方","拉文霍德庄园的传说","拉文霍德是什么"}},bf7fa55a={q="拉文霍德庄园有何历史？",a="第一次战争之前，这片土地属于古老的人类王国奥特兰克，庄园传统的橙瓦屋顶便体现了这一点。如今，这里是乔拉齐·拉文霍德公爵的领地，长期以来一直是对抗无法无天的辛迪加的堡垒，也悄然收容着潜心钻研隐秘技艺的秘密人物。",al={"拉文霍德的历史","庄园的历史","谁建造了拉文霍德庄园"}},["258c293d"]={q="拉文霍德庄园危险吗？",a="这完全取决于你的身份。庄园设有坚固的防御工事，有警惕的哨兵、经验丰富的瞭望者，还有潜伏在阴影中的致命刺客。擅长潜行与暗影技艺的人可以在这里寻求指导，并受到容忍或欢迎；擅自闯入者，或是不知分寸、插手不该涉足之事的游荡者，则会很快发现阴影变得致命。",al={"拉文霍德安全吗","拉文霍德会攻击我吗","这里安全吗"}},["0f3cae48"]={q="为什么叫拉文霍德庄园？",a="庄园直接以其主人及其祖传贵族家族的名字命名，即乔拉齐·拉文霍德公爵。这里是拉文霍德公爵的私人庄园和领地中心，他的贵族名号与纹章也由此成为庄园内盗贼兄弟会的标志。",al={"拉文霍德庄园名称由来","为何叫拉文霍德","拉文霍德这个名字的由来"}}},fp="16,328,26.687.0,30.440.0,34.259.0,26.187.0,39.256.0,27.259.0"}
P.entries["subzone:raynewood-retreat"] = {n="林中树居",s="林中树居是一座古老的暗夜精灵哨站，坐落在灰谷中北部的一棵参天大树周围。它由树妖和塞纳里奥保护者守卫，作为一处警惕的圣所，监视着通往被腐蚀的费伍德森林的北部隘口。这里也是塞纳留斯之子、丛林守护者欧达努斯的避难所，他正受到邪恶外部势力的觊觎。",h="林中树居是一座古老的暗夜精灵哨站，坐落在灰谷中北部的一棵参天大树周围。它由树妖和塞纳里奥保护者守卫，作为一处警惕的圣所，监视着通往被腐蚀的费伍德森林的北部隘口。这里也是塞纳留斯之子、丛林守护者欧达努斯的避难所，他正受到邪...",kw={"灰谷","布莱林","塞纳留斯","费伍德森林","欢笑姐妹","欧达努斯","林中树居","避难所"},ang={["class:Druid"]="林中树居是塞纳留斯之子管辖下的神圣土地，是抵御恶魔和邪能腐蚀的堡垒。",["faction:Horde"]="对于部落来说，这个林中树居是一处亲近联盟的林地，其守护者丛林守护者欧达努斯是被秘密任务发布者列为清除目标的猎物。"},sec={{t="巨树堡垒",b="这座哨站坐落在莎尔蒂恩的月亮井和萨特出没的夜道谷废墟之间，由塞纳里奥保护者、精灵龙和欢笑姐妹严密守卫。她们共同保持着警惕，注视着从北面费伍德森林蔓延而来的腐蚀。"},{t="猎杀欧达努斯",b="在大树的枝头高处，居住着丛林守护者欧达努斯，他是塞纳留斯的长子之一。虽然树冠为他提供了庇护，但也成了黑暗阴谋的焦点。效忠于暗影议会残党的特工，特别是布莱林·火拳，企图谋害这位守护者。部落雇佣兵被派遣去强攻高处并取下他的首级，将这片本应宁静的林中圣所变成了战场。"}},faq={{q="林中树居是什么地方？",a="林中树居是一处位于灰谷中北部大树周围的暗夜精灵和塞纳里奥定居点。它作为一处支持联盟的圣所和瞭望哨，负责监控通往费伍德森林的入口。",al={"林中树居","这里是什么地方","林中树居大树"}},{q="谁居住在林中树居？",a="这座哨站由塞纳里奥保护者、被称为欢笑姐妹的树妖以及精灵龙防守。其最著名的居民是居住在大树高处的丛林守护者欧达努斯。",al={"这里有什么人","林中树居的怪物","谁在守卫林中树居"}},{q="丛林守护者欧达努斯是谁？",a="丛林守护者欧达努斯是一位强大的丛林守护者，也是半神塞纳留斯的长子之一。他负责管理这座圣所，但却发现自己正被敌对的渗透者猎杀。",al={"丛林守护者欧达努斯","欧达努斯是谁","欧达努斯背景故事"}},{q="为什么部落会攻击林中树居？",a="布莱林·火拳雇佣部落冒险者渗透进大树并寻找丛林守护者欧达努斯。她的动机和效忠对象会在任务中被揭露。",al={"部落的林中树居任务","为什么要杀欧达努斯","布莱林·火拳任务"}}},fx={["2822434d"]={q="林中树居危险吗？",a="这在很大程度上取决于你效忠于谁。林中树居是由暗夜精灵和塞纳留斯之子守卫的联盟据点，因此联盟旅人会在此受到欢迎，并得到庇护。然而，对于部落成员来说，这座前哨站充满敌意。塞纳留斯卫士、欢笑姐妹和精灵龙会猛烈守护林地及其守护者，抵御任何闯入者。",al={"林中树居危险吗","林中树居有敌意吗","林中树居的威胁"}},["16c0d3c5"]={q="为什么叫林中树居？",a="这座隐居地直接以林中树居本身命名，那是一棵古老的巨树，整个聚居地都围绕它建造。守护者奥丹努斯在这棵参天巨树的高大枝干间建立了自己的圣所，守望着灰谷的神圣森林。",al={"为何叫林中树居","林中树居名称由来","林中树居是谁"}}},fp="17,353,25.286.0,20.442.1,26.206.0,31.187.0,22.176.0,44.149.0"}
P.entries["subzone:razor-hill"] = {n="剃刀岭",s="剃刀岭是杜隆塔尔中部主要的部落定居点，坐落于连接试炼谷、贫瘠之地和奥格瑞玛的战略十字路口。它以一座显眼的坚固兵营为中心，是年轻的兽人和巨魔战士在严酷荒野中磨练意志的集结地和训练中心。",h="剃刀岭是杜隆塔尔中部主要的部落定居点，坐落于连接试炼谷、贫瘠之地和奥格瑞玛的战略十字路口。它以一座显眼的坚固兵营为中心，是年轻的兽人和巨魔战士在严酷荒野中磨练意志的集结地和训练中心。",kw={"兵营","火刃氏族","杜隆塔尔","加索克","库尔提拉斯","奥戈尼尔·魂痕","剃刀岭"},ang={["faction:Horde"]="作为离开训练场后遇到的第一个真正的城镇，剃刀岭是年轻的部落士兵证明他们对萨尔新国度忠诚的出发点。",["race:Orc"]="剃刀岭见证了兽人在杜隆塔尔开创的新生活，他们用恶魔的奴役换取了坚固的地洞和来之不易的生存。"},sec={{t="杜隆塔尔之心",b="剃刀岭建于重要的地理交汇处，连接着杜隆塔尔北部、南部的沿海定居点，以及怒水河对岸广阔的贫瘠之地平原。这座定居点在杜隆塔尔建立之初便已设立，其标志是石木结构的兵营和经典的兽人地洞。第三次大战后不久，来自库尔提拉斯的人类军队曾假借外交峰会的名义，在此引诱部落进入伏击圈；雷克萨代替萨尔赴会，挫败了这次袭击。如今，这座前哨站已严加设防，以应对后续的沿海入侵。"},{t="边境哨所",b="在加索克等资深军官的指挥下，剃刀岭负责协调针对多重威胁的当地防御。人类海军残部依然盘踞在东海岸的提拉加德城堡，而好战的野猪人和鹰身人部落则不断骚扰当地的补给线。更为阴险的是火刃氏族邪教的存在，他们在附近的岩架上进行黑暗仪式，其腐化的代理人正受到奥戈尼尔·魂痕等调查员的严密追踪和清剿。"}},faq={{q="剃刀岭在杜隆塔尔有什么作用？",a="剃刀岭是杜隆塔尔中部主要的行政和防御前哨站。它连接着南部的海岸和试炼谷，通往北方的奥格瑞玛和西方的贫瘠之地，同时也为年轻的冒险者提供补给和训练。",al={"剃刀岭为何建于此","剃刀岭的作用","剃刀岭简介"}},{q="库尔提拉斯入侵期间这里发生了什么？",a="第三次大战后，效忠于库尔提拉斯的军队提议在剃刀岭与大酋长萨尔举行和平峰会。勇士雷克萨怀疑其中有诈，便代替萨尔前往，揭穿了伏击并击败了人类刺客。",al={"库尔提拉斯伏击","雷克萨剃刀岭","剃刀岭峰会发生了什么"}},{q="谁在指挥这个定居点？",a="该定居点的驻军由兽人老兵加索克在镇内的兵营中指挥，负责监督针对人类残部和当地野生猛兽的巡逻。",al={"剃刀岭指挥官","谁管理剃刀岭","加索克"}},{q="火刃氏族在剃刀岭附近做什么？",a="这个阴暗的恶魔邪教已经渗透到了杜隆塔尔中部周围隐藏的岩架和峡谷中。在奥戈尼尔·魂痕的指挥下，部落侦察兵以剃刀岭为据点，搜寻他们的集会点并消除其影响。",al={"火刃氏族杜隆塔尔","奥戈尼尔·魂痕","剃刀岭附近的邪教徒"}}},fx={["77896146"]={q="剃刀岭是什么地方？",a="剃刀岭是杜隆塔尔中部主要的兽人聚居地。它建在一处重要的十字路口周围，连接着通往北方奥格瑞玛、南方森金村和试炼谷，以及西方贫瘠之地的道路。这里以坚固的军营和瞭望塔为中心，是一座设有防御工事的前哨站，既是当地兽人劳工和农夫繁荣的生活中心，也是守卫杜隆塔尔腹地的重要防线。",al={"关于剃刀岭","剃刀岭概况","剃刀岭是什么类型的城镇"}},["413cce6a"]={q="剃刀岭危险吗？",a="剃刀岭城墙之内有部落卫兵和警惕的步兵严密防守，是疲惫旅人的安全庇护所。然而，周边地区危机四伏。来自提拉加德城堡的人类海军斥候经常在道路附近侦察，火刃氏族的邪恶教徒潜伏在附近的峡谷里，蝎子和迅猛龙等有毒野兽则在镇外游荡。",al={"剃刀岭安全吗","剃刀岭面临的威胁","剃刀岭危险吗"}}},fp="10,337,16.588.0,21.469.0,40.259.0,49.233.0,28.164.0,48.210.0"}
P.entries["subzone:razor-hill-watchtower"] = {n="Razor Hill Watchtower",s="这座坚固的哨所矗立在俯瞰剃刀岭的红色石崖上，是杜隆塔尔中心地带的早期预警点。弗恩·凝眉时刻警惕地注视着尘土飞扬的平原和海岸线，保护着下方的定居点免受威胁的侵扰。",h="这座坚固的哨所矗立在俯瞰剃刀岭的红色石崖上，是杜隆塔尔中心地带的早期预警点。弗恩·凝眉时刻警惕地注视着尘土飞扬的平原和海岸线，保护着下方的定居点免受威胁的侵扰。",kw={"杜隆塔尔","瞭望","剃刀岭","razor hill watchtower","哨兵","哨塔"},ang={["class:Hunter"]="这个高处的制高点可以毫无阻挡地观察周围的岩壁，是观察员追踪猎物和监控杜隆塔尔各地野兽动向的理想位置。",["faction:Horde"]="对于从试炼谷走出的年轻战士和侦察兵来说，这座哨塔是一个令人安心的地标，象征着初生的部落的安全与力量。"},sec={{t="杜隆塔尔之眼",b="剃刀岭哨塔由厚实的木材和铁架建成，守卫着剃刀岭定居点及周边的峡谷。杜隆塔尔面临着来自东海岸库尔提拉斯海军陆战队、在灌木丛中潜行的野猪人袭击者，以及潜伏在附近岩壁中的火刃氏族邪教徒的无尽威胁。从山脊上这个高耸的制高点，哨兵可以在敌军到达定居点大门之前，很远就能发现逼近的战团、烟雾信号和入侵者。"}},faq={{q="剃刀岭哨塔的用途是什么？",a="这座哨塔是剃刀岭和杜隆塔尔中心地带的主要监视点。凭借其高海拔，侦察兵可以监控路径、观察野兽，并探测来自附近联盟营地或半人马袭击队的任何部队调动。",al={"为什么要有这个哨塔","哨塔用途","剃刀岭塔"}},{q="谁在守护这座哨塔？",a="上了年纪的兽人弗恩·凝眉在这里守望着入侵者，并在必要时吹响信号号角。随着杜隆塔尔逐渐安定下来，他开始为年轻的冒险者制作背包。",al={"谁在塔里","哨塔守卫"}},{q="在这里能看到什么威胁？",a="侦察兵主要留意来自剃刀鬃毛部族的暴躁野猪人、沿着东海岸从提拉加德城堡潜入的人类，以及在干旱峡谷中游荡的野兽。",al={"剃刀岭的威胁","他们在寻找什么"}}},fx={e22a9f25={q="剃刀岭瞭望塔是什么？",a="这座木制部落防御工事坐落在剃刀岭上方高耸的红色峭壁上，可以俯瞰杜隆塔尔的广阔景色。它是附近十字路口的预警哨站，哨兵在此监视尘土飞扬的峡谷道路、南部海岸线，以及任何从无尽之海沿岸向内陆潜行的敌对野猪人、半人马或联盟渗透者的动向。",al={"剃刀岭瞭望塔是什么","剃刀岭塔楼","剃刀岭瞭望塔"}},["9138eaa5"]={q="剃刀岭瞭望塔危险吗？",a="这座瞭望塔是剃刀岭上方的一处部落哨所。弗恩·凝眉负责监视入侵者，不过他说，随着杜隆塔尔逐渐安定下来，需要吹响警报号角的情况已经越来越少了。",al={"剃刀岭瞭望塔安全吗","剃刀岭瞭望塔危险吗"}}},fp="21,275,17.484.0,49.259.0,26.186.0,38.183.0"}
P.entries["subzone:razorfen-downs"] = {n="剃刀高地",s="剃刀高地是野猪人的祖先之都和神圣的埋骨迷宫，深深地嵌入在南贫瘠之地与千针石林交界处那巨大的荆棘丛中。这里曾是他们最神圣的避难所，如今却已落入亡灵天灾军团的魔掌，变成了一个散发着恶臭的死灵法术堡垒。",h="剃刀高地是野猪人的祖先之都和神圣的埋骨迷宫，深深地嵌入在南贫瘠之地与千针石林交界处那巨大的荆棘丛中。这里曾是他们最神圣的避难所，如今却已落入亡灵天灾军团的魔掌，变成了一个散发着恶臭的死灵法术堡垒。",kw={"阿迦玛甘","阿迦玛娜","寒冰之王","死灵法师黑棘","死亡之头","高地","野猪人","剃刀高地","天灾军团"},ang={["faction:Horde"]="野猪人一直是十字路口的心头大患，但一个盘踞在贫瘠之地边缘、直接效忠于巫妖王的据点，则是部落绝对无法忽视的生存威胁。",["race:Undead"]="对于被遗忘者来说，发现一个天灾军团的巫妖在卡利姆多秘密行动，这不禁让人回想起他们曾誓死反抗的那个主人，必须立即采取果断行动将其彻底铲除。"},sec={{t="一座被腐蚀的神圣城市",b="剃刀高地长期以来被视为野猪人种族的祖先之都和埋骨之地，坐落在从陨落的半神阿迦玛甘身上长出的巨大石化荆棘丛中。传说其拱形的入口正是直接从这位巨猪的嘴里开凿出来的。几个世纪以来，死亡之头氏族的高阶祭司们一直守护着这些深邃蜿蜒的洞穴，并祭奠他们受人敬仰的死者。然而，尽管这里在野猪人心中地位神圣，但这片骨头与荆棘组成的迷宫最近却遭遇了一场远比贫瘠之地的水源争夺更为黑暗的灾难。"},{t="天灾军团蔓延至卡利姆多",b="第三次战争的浩劫过后，亡灵天灾军团的触角悄然伸向了卡利姆多南部。在寒冰巫妖阿迦玛娜的率领下，死亡的爪牙渗透进这片荆棘迷宫，并策反了死亡之头氏族的祭司。野猪人们不再祭奠祖先，而是转而在他们神圣的栖息地中窝藏腐烂的食尸鬼、骷髅和死灵法师。此地的腐化正威胁着向外扩散至整个贫瘠之地，将野猪人最神圣的土地变成天灾军团在西方扩张野心的跳板。"}},faq={{q="什么是剃刀高地？",a="剃刀高地是野猪人种族的祖先之都和埋骨之地。它由陨落的远古之灵阿迦玛甘所形成的巨大荆棘丛生长而成，是野猪人文化的精神核心，也是他们的高阶祭司——死亡之头氏族的总部。",al={"什么是剃刀高地","剃刀高地背景故事","谁居住在剃刀高地"}},{q="为什么天灾军团会盘踞在剃刀高地？",a="巫妖阿迦玛娜在第三次战争后抵达此地，旨在为巫妖王建立一个卡利姆多的据点。通过腐化死亡之头氏族的祭司并复活野猪人的尸体，阿迦玛娜将这座迷宫般的荆棘之城变成了一个隐藏的死灵力量巢穴。",al={"为什么剃刀高地有亡灵","阿迦玛娜剃刀高地","剃刀高地的天灾军团"}},{q="剃刀高地与剃刀沼泽有何不同？",a="剃刀沼泽是野猪人的主要军事堡垒和聚居地，由妖婆卡尔加·刺肋直接统治。相比之下，剃刀高地则是他们传统的首都和神圣埋骨地，位于更南边，现已沦陷在死灵法术和天灾军团的控制之下。",al={"剃刀沼泽和剃刀高地的区别","剃刀高地与剃刀沼泽","剃刀沼泽还是剃刀高地"}},{q="入口在哪里？",a="剃刀高地坐落在贫瘠之地的最南端，俯瞰着通往千针石林的巨大断崖。其入口是一个嵌入高耸纠结荆棘丛中的天然拱形裂隙，神话传说称其是由阿迦玛甘张开的大嘴雕琢而成。",al={"剃刀高地入口","剃刀高地在哪里","如何进入剃刀高地"}}},fx={e1cd26cb={q="剃刀高地发生过什么？",a="剃刀高地曾是野猪人的骄傲都城和祖先墓地，由巨大的荆棘藤蔓构成。据说这些藤蔓是从半神阿迦玛甘的鲜血中生长出来的。然而，第三次战争后，城中降临了灾祸。天灾军团的爪牙潜入荆棘迷宫，散播致命瘟疫。在寒冰之王阿姆纳尔的带领下，亡灵奴役了许多亡首部族成员，将这片神圣故土变成了滋生亡灵的据点。",al={"剃刀高地历史","剃刀高地发生了什么","剃刀高地的历史传说"}},ac7f90f4={q="谁统治着剃刀高地？",a="这座要塞已落入阿姆纳尔·寒冰之王的铁腕统治之下。他是强大的天灾巫妖，被派往卡利姆多南部建立据点。在他麾下效力的是亡首部族的野猪人，他们腐化的高阶祭司已转而钻研通灵术；此外还有成群的无脑食尸鬼、骷髅和其他可怖亡灵。",al={"谁统治剃刀高地","谁领导剃刀高地","剃刀高地首领"}},["42eaec66"]={q="剃刀高地危险吗？",a="这里极其危险。与剃刀沼泽的野蛮部族不同，这里的守卫得到了天灾军团的冰冷魔法加持。染疫的野猪人、通灵师和成群复活的亡者在错综复杂的隧道中游荡。深处盘踞着阿姆纳尔·寒冰之王，他的存在威胁着要将亡灵瘟疫扩散至整个贫瘠之地和千针石林。",al={"剃刀高地有多危险","剃刀高地的威胁","剃刀高地安全吗"}}},fp="14,311,23.565.0,28.557.1,23.288.0,41.273.0,51.288.0,30.259.0"}
P.entries["subzone:razorfen-downs-classic"] = {n="Razorfen Downs (Classic)",s="剃刀高地是野猪人的祖先埋骨地和传统都城，坐落在南贫瘠之地巨大的荆棘丛深处。最近，由巫妖寒冰之王亚门纳尔领导的天灾军团特工夺取了这座迷宫的控制权，复活了死去的野猪人，并威胁要将其统治范围扩张到整个卡利姆多中部。",h="剃刀高地是野猪人的祖先埋骨地和传统都城，坐落在南贫瘠之地巨大的荆棘丛深处。最近，由巫妖寒冰之王亚门纳尔领导的天灾军团特工夺取了这座迷宫的控制权，复活了死去的野猪人，并威胁要将其统治范围扩张到整个卡利姆多中部。",kw={"阿迦玛甘","亚门纳尔","贫瘠之地","死亡之颅","野猪人","剃刀高地","rfd","天灾军团"},ang={["faction:Horde"]="在贫瘠之地南侧边境线上出现的这座天灾要塞，对部落的腹地和补给线构成了迫在眉睫的威胁。",["race:Undead"]="幽暗城的皇家药剂师学会和被遗忘者领导层非常渴望调查并清除这股在高地中滋生的敌对亡灵魔法。"},sec={{t="荆棘之都",b="剃刀高地和附近的剃刀沼泽一样，都是由高耸的石化藤蔓生长而成，这里是上古野猪半神阿迦玛甘在上古之战中倒下的地方。世世代代以来，这座荆棘迷宫一直是野猪人的神圣墓地和权力中心，由死亡之颅部族的秘法师严密守护。对野猪人而言，这些茂密的荆棘是神圣之地，浸透了他们神圣先祖的鲜血。"},{t="卡利姆多的天灾据点",b="随着天灾军团的特工渗入荆棘丛，高地的神圣性被打破了。寒冰之王亚门纳尔，一位侍奉巫妖王的强大巫妖，奴役了当地的死亡之颅部族野猪人，并将这座祖先的安息之地变成了天灾军团的要塞。复活的骷髅、蹒跚的尸体和尖叫的女妖现在徘徊在荆棘之环中。附近的贫瘠之地部落和暴风城光明大教堂的使者都认为，这个不断扩大的天灾势力据点对整个大陆构成了严重的威胁。"}},faq={{q="什么是剃刀高地？",a="剃刀高地是野猪人的祖先都城和墓地，开凿在南贫瘠之地的巨大荆棘丛中。它最近落入了天灾军团的控制之下。",al={"什么是rfd","剃刀高地背景故事","高地背景"}},{q="为什么野猪人的城市里会有亡灵？",a="一位名为寒冰之王亚门纳尔的天灾巫妖入侵了高地，奴役了当地的死亡之颅部族，并复活了死去的野猪人，以此在卡利姆多建立了一个亡灵滩头阵地。",al={"为什么天灾军团会在高地","为什么贫瘠之地会有亡灵","谁把天灾军团带到了这里"}},{q="剃刀高地和剃刀沼泽有什么区别？",a="这两座地下城都是从阿迦玛甘的荆棘中开凿出来的，但剃刀沼泽是由卡尔加·刺肋领导的野猪人居住要塞。而剃刀高地是他们的祖先埋骨地，目前被天灾军团所占领。",al={"高地对比沼泽","rfk对比rfd","高地和沼泽的区别"}},{q="谁目前统治着剃刀高地？",a="天灾军团的巫妖，寒冰之王亚门纳尔，在荆棘之环深处指挥着这座要塞。",al={"rfd最终首领","谁领导着剃刀高地","高地的首领"}}},fx={["537e8490"]={q="剃刀高地遭遇了什么？",a="剃刀高地长期以来一直是野猪人的都城和神圣墓地，由亡首部族的祭司守护。最近，天灾军团在巫妖阿姆纳尔·寒冰之王的带领下抵达卡利姆多。阿姆纳尔潜入这座荆棘要塞，腐化了野猪人祭司，并将他们受尊崇的死者复活成一支蹒跚前行的大军。神圣墓穴如今已被扭曲成一座戒备森严的亡灵墓地，幸存的野猪人被迫奋力夺回祖先的家园，以免亡灵瘟疫扩散至贫瘠之地。",al={"剃刀高地发生过什么","剃刀高地历史","剃刀高地的故事"}},["4edae968"]={q="剃刀高地有多危险？",a="这里极其危险。与贫瘠之地其他地方的野蛮野猪人不同，剃刀高地由亡灵天灾军团控制。你将面对狂热的亡首通灵师和地卜师，还要对抗成群复活的野猪人尸体、女妖和骷髅召唤师。深处的巫妖阿姆纳尔·寒冰之王掌控着侵染荆棘丛的黑暗魔法，威胁要以这座要塞为据点，让亡灵力量席卷卡利姆多中部。",al={"剃刀高地危险吗","剃刀高地的危险","剃刀高地的威胁"}}},fp="24,367,17.436.0,29.535.0,23.185.0,44.173.0,65.226.0,35.111.0"}
P.entries["subzone:razorfen-kraul-classic"] = {n="Razorfen Kraul (Classic)",s="剃刀沼泽是野猪人的祖居心脏地带，深入挖掘在野猪半神阿迦玛甘倒下后，其鲜血所化出的巨型荆棘丛中。这座防御森严的迷宫由冷酷的巫婆卡尔加·刺肋统治，是他们向南贫瘠之地发起血腥劫掠的集结地。",h="剃刀沼泽是野猪人的祖居心脏地带，深入挖掘在野猪半神阿迦玛甘倒下后，其鲜血所化出的巨型荆棘丛中。这座防御森严的迷宫由冷酷的巫婆卡尔加·刺肋统治，是他们向南贫瘠之地发起血腥劫掠的集结地。",kw={"阿迦玛甘","阿迦瑟洛斯","贫瘠之地","卡尔加·刺肋","野猪人","拉姆塔斯","剃刀沼泽","天灾军团"},ang={["faction:Horde"]="卡尔加·刺肋的侵略性劫掠直接威胁着南部的定居点和贸易路线，使得平定剃刀沼泽成为部落刻不容缓的安全要务。",["race:Tauren"]="牛头人猎人和萨满与野猪人有着深厚的历史宿怨，而有关邪恶的天灾腐蚀正在阿迦玛甘的神圣土地上扎根的传言，要求他们立即采取行动进行干预。"},sec={{t="野猪之神的鲜血",b="一万年前的上古之战期间，巨型野猪半神阿迦玛甘在对抗燃烧军团以拯救艾泽拉斯时不幸殒命。每当他那神圣的鲜血渗入卡利姆多南部的土地，巨大的、无法穿透的荆棘藤蔓就会从地底迸发而出。野猪人自认为是这位伟大的野猪之神的凡间后裔，他们聚集在这些茂密的荆棘丛中居住，并祭祀他的牺牲。被称为剃刀沼泽的这片密集丛林是他们最受尊崇的堡垒，里面布满了野猪人战士、野兽训练师和塑地萨满。"},{t="巫婆的野心",b="剃刀沼泽的控制权落在了年迈的地卜师卡尔加·刺肋手中。在她的铁腕统治下，剃刀野猪人部落对敌对的野猪人部族以及附近的部落营地发动了残酷的战争。然而，比单纯的领土劫掠更令人不寒而栗的是，警惕的斥候报告称，有人发现亡灵身影在荆棘丛周围徘徊。有传言称，卡尔加已经开始与天灾军团的代理人进行交易，这不仅危及了贫瘠之地，还可能为亡灵在卡利姆多打开一个险恶的立足点。"}},faq={{q="是什么造就了剃刀沼泽周围的巨型荆棘？",a="根据传说，一万年前的上古之战中，野猪半神阿迦玛甘的鲜血洒落在哪里，巨大的荆棘藤蔓就会在哪里萌发。",al={"这里为什么有荆棘","贫瘠之地巨型荆棘藤蔓","阿迦玛甘荆棘背景故事"}},{q="谁统治着剃刀沼泽？",a="剃刀沼泽由卡尔加·刺肋指挥，她是一位冷酷的野猪人巫婆兼地卜师，指挥着针对邻近部落和定居点的袭击。",al={"剃刀沼泽首领","谁领导剃刀沼泽","卡尔加·刺肋"}},{q="为什么沼泽附近有亡灵？",a="据报道，卡尔加·刺肋已经与天灾军团的代理人进行了秘密谈判，寻求结成邪恶的联盟，这可能会将亡灵的力量引入野猪人的部族中。",al={"剃刀沼泽的天灾军团","亡灵野猪人","为什么天灾军团在贫瘠之地"}},{q="剃刀沼泽位于哪里？",a="剃刀沼泽位于贫瘠之地的最南端，坐落在升降梯以北、巨型荆棘丛的西侧。",al={"剃刀沼泽在哪里","剃刀沼泽入口","剃刀沼泽位置"}}},fx={["6f44c4ee"]={q="什么是剃刀沼泽？",a="剃刀沼泽是野猪人的祖传家园和戒备森严的要塞，深藏在南贫瘠之地巨大的荆棘丛中。野猪人被认为是堕落的野猪半神阿迦玛甘在人世间的后裔，他们将茂密的荆棘视为圣地和理应属于自己的领地。",al={"什么是剃刀沼泽","剃刀沼泽传说","关于剃刀沼泽"}},["8546d87b"]={q="剃刀沼泽发生过什么？",a="一万年前的上古之战期间，野猪半神阿迦玛甘在与燃烧军团的战斗中陨落。他洒下的鲜血使大片遍布荆棘的灌木丛破土而出。野猪人将中央的荆棘丛据为祖传家园，但老巫婆卡尔加·刺肋最近夺取了剃刀沼泽的统治权，驱使守卫攻击敌对部族和附近的聚居地。",al={"剃刀沼泽的历史","剃刀沼泽历史","剃刀沼泽发生了什么"}},["2a3e9319"]={q="剃刀沼泽危险吗？",a="危险。除了凶悍的野猪人战士、驯服的野兽和地卜师会竭力守护他们的神圣荆棘丛外，在卡尔加·刺肋的命令下，剃刀沼泽也变得极具敌意。更令人担忧的是，有传闻称天灾军团的爪牙正在其中出没，这让人们担心邪恶势力正在卡利姆多扎根。",al={"剃刀沼泽安全吗","剃刀沼泽的危险","剃刀沼泽的威胁"}}},fp="24,306,21.566.0,20.529.1,52.176.0,25.152.0,36.179.1,32.159.0"}
P.entries["subzone:razormane-grounds"] = {n="钢鬃营地",s="钢鬃营地是钢鬃野猪人从贫瘠之地向东推进至杜隆塔尔中部的前进营地。这里长满了尖锐的荆棘，随处可见野生动物的骸骨，这座令人毛骨悚然的前哨站成为了野猪人与奥格瑞玛兽人之间无休止冲突的最前线。",h="钢鬃营地是钢鬃野猪人从贫瘠之地向东推进至杜隆塔尔中部的前进营地。这里长满了尖锐的荆棘，随处可见野生动物的骸骨，这座令人毛骨悚然的前哨站成为了野猪人与奥格瑞玛兽人之间无休止冲突的最前线。",kw={"平牙队长","杜隆塔尔","地卜师摩特尔","野猪人","拉格拉恩","钢鬃","钢鬃营地"},ang={["faction:Horde"]="压制钢鬃营地对于保障贫瘠之地与部落主城奥格瑞玛之间的交通和补给线至关重要。",["race:Orc"]="对于杜隆塔尔的兽人来说，钢鬃营地是威胁他们新家园心脏地带的顽疾，年轻的勇士们必须通过屠杀这些野猪人来证明自己的实力。"},sec={{t="杜隆塔尔的眼中钉",b="钢鬃营地坐落在杜隆塔尔中部的红岩悬崖之下，标志着野猪人从贫瘠之地向外扩张的最东端。这里荆棘丛生，到处散落着白骨，对往来怒水河的旅人构成了持续的威胁。营地由战斗卫士平牙队长和地卜师摩特尔等首领领导，他们策划对邻近的兽人定居点和过往的补给线发动袭击。尽管剃刀岭及附近的哨所经常派出巡逻队，但钢鬃部族补充兵力的速度极快，他们从荆棘丛中涌出的速度甚至超过了部落的清理速度。"}},faq={{q="钢鬃营地是什么？",a="它是位于杜隆塔尔中部的一个野猪人防御营地，是钢鬃部族从贫瘠之地向东扩张的前进基地。",al={"钢鬃营地","野猪人营地 杜隆塔尔","钢鬃在哪"}},{q="为什么野猪人要袭击杜隆塔尔？",a="钢鬃野猪人认为所有邻近的领土都理应属于他们，他们试图通过牺牲部落的新定居点来扩大自己的荆棘丛和狩猎场。",al={"野猪人为何攻击","钢鬃为何在此","野猪人入侵"}},{q="谁在领导钢鬃营地的野猪人？",a="营地由钢鬃战斗卫士的首领平牙队长，以及擅长塑地之术的地卜师摩特尔共同指挥。",al={"钢鬃首领","钢鬃营地指挥官","平牙队长"}},{q="为什么营地周围有这么多骨头？",a="钢鬃部族是极具攻击性的拾荒者和猎手，他们将当地野生动物的肉剔食殆尽来供养劫掠者，并将残骸留在原地以标记领地。",al={"营地白骨","钢鬃动物尸骸","死去的动物为何"}}},fx={cce0af6c={q="钢鬃营地发生过什么？",a="兽人建立杜隆塔尔后，钢鬃野猪人向东迁出贫瘠之地，扩张领地。钢鬃营地成了这场入侵的前线。兽人一直在奋力抵挡他们，不让他们进入杜隆塔尔腹地，但每当有野猪人在荆棘丛中被杀，似乎就会有更多人从灌木丛中涌出，继续发起猛攻。",al={"钢鬃营地历史","钢鬃营地发生了什么","钢鬃野猪人入侵杜隆塔尔"}},["8556a3c9"]={q="谁住在钢鬃营地？",a="这座营地是钢鬃野猪人一支凶悍的战团的据点，他们正不断向杜隆塔尔推进。营地由平牙队长指挥，他统领战卫；地卜师土之领主莫特尔则在荆棘丛中施展大地魔法。",al={"谁住在钢鬃营地","钢鬃营地的居民","钢鬃营地里有什么人"}},b58c6eb9={q="钢鬃营地危险吗？",a="危险。这里是活跃的前线军营，遍布敌对的野猪人战士和地卜师。钢鬃野猪人会凶残地屠杀闯入者和当地野生动物，留下遍地剔净的骸骨；茂密的荆棘丛也使撤退变得危机四伏。",al={"钢鬃营地危险吗","钢鬃营地的危险","钢鬃营地有多危险"}},a76ef142={q="为什么叫钢鬃营地？",a="这片营地以钢鬃野猪人部族命名。他们建立了这座广阔的营地，将其作为向杜隆塔尔扩张领土的前进据点。",al={"为什么叫钢鬃营地","钢鬃营地名称的含义","钢鬃营地的名字由来"}}},fp="17,305,25.653.0,30.148.0,39.180.0,48.140.0,44.174.0"}
P.entries["subzone:razorwind-canyon"] = {n="烈风峡谷",s="烈风峡谷是一条蜿蜒曲折的岩石深沟，横跨在剃刀岭与奥格瑞玛之间的主干道上。这里盘踞着极具攻击性的尘风鹰身人，对前往部落首府的旅人构成了持续的威胁。",h="烈风峡谷是一条蜿蜒曲折的岩石深沟，横跨在剃刀岭与奥格瑞玛之间的主干道上。这里盘踞着极具攻击性的尘风鹰身人，对前往部落首府的旅人构成了持续的威胁。",kw={"枯水谷","杜隆塔尔","尘风鹰身人","剃刀岭","烈风峡谷","托克雷农场"},ang={["faction:Horde"]="将尘风鹰身人从烈风峡谷中清理出去，对于确保剃刀岭与奥格瑞玛首府之间的主干道对信使和新兵的安全至关重要。",["race:Orc"]="盘踞在杜隆塔尔中央大道旁的鹰身人是对兽人家园安全的蔑视，必须派遣年轻的勇士去削减它们的数量。"},sec={{t="高路上的威胁",b="烈风峡谷毗邻连接剃刀岭与奥格瑞玛的交通大动脉，向东侧的峭壁和西侧通往托克雷农场的灌木丛延伸出数条路径。峡谷是尘风鹰身人的巢穴，这些领地意识极强的生物会毫不犹豫地袭击任何靠近其栖息地的旅人。由于它们盘踞在首府贸易路线附近，清理这些峡谷成为了杜隆塔尔守军的一项长期必要任务。"},{t="通道与沟壑",b="烈风峡谷不仅是鹰身人的巢穴，其错综复杂的路径也构成了穿过杜隆塔尔红岩丘陵的隐秘通道。东侧的分支深深地钻入岩壁，通过一个洞穴与枯水谷相连。由于鹰身人栖息在高处并成群俯冲攻击，大意的冒险者在穿越这些隘口时很容易陷入包围并遭到屠戮。"}},faq={{q="烈风峡谷位于何处？",a="烈风峡谷位于杜隆塔尔中部，横跨在剃刀岭与奥格瑞玛之间主干道的两侧。入口分布在剃刀岭北侧、托克雷农场附近，以及通过一个洞穴连接至枯水谷。",al={"烈风峡谷位置","烈风峡谷在哪里","如何找到烈风峡谷"}},{q="什么生物栖息在烈风峡谷？",a="峡谷中盘踞着大量的尘风鹰身人。这些极具攻击性的类鸟生物在峡谷和岩石突起处筑巢，并以毫无防备的旅人为食。",al={"烈风峡谷怪物","烈风峡谷生活着什么","杜隆塔尔鹰身人峡谷"}},{q="为什么部落对这条峡谷感到担忧？",a="烈风峡谷紧邻连接剃刀岭与奥格瑞玛的主要贸易和旅行路线。筑巢的鹰身人经常骚扰经过中央大道的信使、补给商队和旅人。",al={"为什么关注烈风峡谷","奥格瑞玛烈风峡谷威胁"}},{q="烈风峡谷是否与其他地区相连？",a="是的。除了通向主干道外，峡谷还提供向西前往托克雷农场的小径，以及一条通往枯水谷的东侧洞穴通道。",al={"峡谷连接处","烈风峡谷通向哪里"}}},fx={["8d215d8c"]={q="什么是烈风峡谷？",a="烈风峡谷是一道崎岖的峡谷，位于杜隆塔尔中部，沿着剃刀岭和奥格瑞玛之间的主路延伸。峡谷分为东、西两道沟壑，峭壁是凶猛的尘风鹰身人的主要巢穴，给往来于部落重要陆路的旅人带来持续威胁。",al={"烈风峡谷传说","关于烈风峡谷","什么是烈风"}},["851d9326"]={q="烈风峡谷危险吗？",a="危险，非常危险。烈风峡谷里挤满了好斗的尘风鹰身人，它们会竭力守护巢穴栖木。它们数量惊人，性情凶残，毫无防备的旅人或独行者只要离开道路深入峡谷，就很容易遭到围攻、制服并杀害。",al={"烈风危险吗","烈风峡谷的危险","烈风的危险"}}},fp="16,239,25.462.0,20.394.0,34.240.0,40.189.0,45.204.0,45.160.0"}
P.entries["subzone:rebel-camp"] = {n="反抗军营地",s="反抗军营地坐落在荆棘谷北部路边，是那些脱离库尔森上校指挥的联盟士兵的坚固避难所。在多伦上尉的领导下，这些士兵拒绝向控制其指挥官远征队的疯狂屈服，如今他们为生存而战，并致力于终结库尔森的暴政。",h="反抗军营地坐落在荆棘谷北部路边，是那些脱离库尔森上校指挥的联盟士兵的坚固避难所。在多伦上尉的领导下，这些士兵拒绝向控制其指挥官远征队的疯狂屈服，如今他们为生存而战，并致力于终结库尔森的暴政。",kw={"库尔森上校","doren","库尔森","库尔森的营地","mai'zoth","反抗军营地","荆棘谷"},ang={["faction:Alliance"]="当你从暮色森林过桥向南进入荆棘谷时，反抗军营地是你主要的集结地和最安全的避风港。",["race:Human"]="眼看着昔日的暴风城正规军在丛林中分崩离析令人感到清醒，多伦上尉急需王国的同胞帮助，以终结库尔森这支蒙羞的部队。"},sec={{t="对抗疯狂",b="当库尔森上校代表暴风城深入荆棘谷丛林时，局势迅速恶化。受到黑暗丛林魔法和食人魔巫师Mai'Zoth诅咒的影响，上校及其核心亲信陷入疯狂，变得残暴并开始蹂躏这片荒野。在多伦上尉的带领下，一小群神志清醒的士兵拒绝参与暴行。他们脱离了库尔森的营地，在北部建立了这个隐秘营地，对昔日的战友展开了绝望的游击战。"},{t="坚守阵线",b="反抗军营地危险地坐落在暮色森林边界附近，时刻面临着威胁。由于切断了来自暴风城的常规补给，多伦依靠秘密补给和防御武器——包括通过藏宝海湾运作的地精爆炸物——来守住防线，抵御库尔森突袭小队的进攻。对于向南冒险进入这片蛮荒丛林的联盟旅行者来说，这座营地是他们维持理智的重要落脚点。"}},faq={{q="反抗军营地的反抗军是谁？",a="他们是前暴风城士兵，曾是库尔森上校深入荆棘谷远征队的一员。当库尔森及其核心圈子陷入疯狂和暴政时，多伦上尉率领这部分人发动兵变，逃离并开始对抗他们。",al={"反抗军营地的居住者","这些士兵是谁","反抗军营地与联盟"}},{q="如果他们忠于暴风城，为什么还要叫它“反抗军营地”？",a="他们只是库尔森上校指挥体系下的“反抗军”。库尔森曾是他们的指挥官，因此违抗他的命令从技术上讲属于兵变，尽管他们仍然忠于联盟和暴风城。",al={"为什么叫反抗军营地","他们是叛徒吗","他们反抗谁"}},{q="该营地如何在没有暴风城官方支持的情况下生存？",a="由于远离官方补给线，多伦上尉依靠机智的非官方渠道，包括与远在藏宝海湾的克拉兹克等人进行交易，由他提供地雷和重要装备来加强营地的防御。",al={"反抗军营地的补给","他们的食物来源","反抗军营地的后勤"}},{q="库尔森上校在哪里？",a="库尔森及其疯癫的追随者占据着库尔森的营地，这是一座位于反抗军营地东南方向的坚固基地。",al={"库尔森的位置","库尔森在哪里","库尔森的营地"}}},fp="10,330,23.565.0,16.424.0,37.239.0,63.219.0,61.238.0,32.123.0"}
P.entries["subzone:red-rocks"] = {n="赤色石",s="赤色石是位于莫高雷东北部的一座高耸砂岩峭壁，是牛头人神圣的祖先墓地。这里安葬着最英勇的逝去勇士，年轻的勇士们也会前往那宁静的高处，寻求先辈的智慧。",h="赤色石是位于莫高雷东北部的一座高耸砂岩峭壁，是牛头人神圣的祖先墓地。这里安葬着最英勇的逝去勇士，年轻的勇士们也会前往那宁静的高处，寻求先辈的智慧。",kw={"刺鬃","墓地","大地母亲","莫高雷","野猪人","赤色石","智慧试炼","雷霆崖"},ang={["class:Shaman"]="风中承载着因野猪人的亵渎而不得安宁的灵魂的悲伤，呼唤着萨满仪式来恢复元素平衡和祖先的安宁。",["race:Tauren"]="对于你们的人民来说，赤色石是神圣的土地。肮脏的野猪人在你们受人尊敬的祖先墓地上挖掘，这是必须予以净化的公开暴行。"},sec={{t="神圣之石与祖先之墓",b="赤色石深红色的岩层高高耸立在莫高雷东北部的平原之上，标志着生者世界与死后世界之间神圣的界限。牛头人的传统将这片庄严的土地保留给他们最英勇的英雄——那些在建立和保卫雷霆崖的过程中献出生命的酋长、守卫者和勇士。他们荣耀地安息于此，与先辈的坟墓为伴。这里同样也是精神启程之地，年轻的牛头人会通过祭拜祖先墓地和与风沟通来完成他们的成年礼。"},{t="野猪人的亵渎",b="赤色石持久的宁静已被刺鬃野猪人打破。这些极具侵略性的食腐动物从巢穴中爬出，侵占了砂岩峭壁，并用污秽亵渎了祖先的坟墓。这种暴行深深冒犯了雷霆崖的精神传统。萨满祭司和博学者们现在正号召各方援助以净化这些岩架，驱逐刺鬃野猪人，并收复他们先人安息之地的神圣性。"}},faq={{q="赤色石的用途是什么？",a="赤色石是莫高雷牛头人最重要的祖先墓地和仪式祭坛。只有最英勇的逝去英雄才能安葬于此，年轻的牛头人也会在成年礼期间造访其高处，以此向逝者致敬。",al={"为什么赤色石很重要","赤色石的目的","赤色石发生了什么"}},{q="为什么赤色石会有野猪人？",a="刺鬃野猪人从他们的荆棘巢穴中涌出， overrun 了高原，玷污了墓冢。牛头人认为他们的入侵是对祖先安息之灵的亵渎，是不可容忍的罪行。",al={"赤色石的野猪人","谁在入侵赤色石","为什么刺鬃野猪人在这里"}},{q="谁被安葬在赤色石？",a="安葬在赤色石是一种荣耀，仅保留给最英勇的牛头人，包括曾与凯恩·血蹄并肩作战以确保莫高雷安全并建立雷霆崖的伟大战士，以及在为部落服务时牺牲的英雄。",al={"谁被火化于此","赤色石的死者","这是谁的坟墓"}},{q="这里会举行什么仪式？",a="除了安葬受人尊敬的英雄，这座峭壁还是“智慧试炼”的核心场所。年轻的牛头人勇士会在这里留下祭品，聆听风中传来的祖先之灵的指引。",al={"赤色石的仪式","牛头人在赤色石的仪式"}}},fx={dabb6ac9={q="什么是赤色石？",a="赤色石是莫高雷东北部一处显眼的红色砂岩地貌。对牛头人而言，这里是受尊崇的圣地，位于尘世的雷霆崖与远方的祖灵领域之间。牛头人青年会在此完成成年仪式，各部族也会在这里纪念最伟大的阵亡勇士。",al={"什么是赤色石","关于赤色石","赤色石概况"}},["281a060c"]={q="赤色石危险吗？",a="这里原本一直是宁静庄严的圣地，但如今因野蛮的刺背野猪人入侵而危机四伏。这些入侵者亵渎了墓地，还会主动攻击任何接近圣地的人。",al={"赤色石危险吗","赤色石的危险","赤色石的敌人"}},["63db11a0"]={q="为什么叫赤色石？",a="这个地方因独特的天然峭壁和鲜红的砂岩地貌而得名，与周围山谷起伏的绿色草原形成鲜明区别。",al={"为什么叫赤色石","赤色石名称的含义","为什么是赤色石"}}},fp="9,269,36.559.0,24.434.0,33.253.0,36.229.0,27.224.0,35.186.0"}
P.entries["subzone:refuge-pointe"] = {n="避难谷地",kw={"阿拉希高地","阿拉索","尼艾丝队长","阿拉索联军","避难谷地","激流堡","萨多尔大桥"},ang={["faction:Alliance"]="避难谷地是你身处阿拉希高地时唯一的军事避难所和飞行点，在这片由食人魔、辛迪加和部落争夺的危险领土上提供着至关重要的补给。",["race:Human"]="对于人类来说，避难谷地是激流堡昔日作为人类军事中心辉煌往事的一个凄凉缩影，那里坚定的保卫者拒绝在绝境中放弃他们的家园。"},sec={{t="激流堡残部的据点",b="第三次大战和激流堡的惨痛沦陷之后，激流堡的大部分幸存平民逃往了南方的安全地带。留下的人组成了一支坚定的先锋队，在尼艾丝队长的指挥下坚守在避难谷地。这个营地由久经沙场的激流堡士兵、阿拉索联军部队以及支援的联盟专家组成，代表着该王国在其故土上最后的有组织抵抗。"},{t="捉襟见肘",b="避难谷地一直处于岌岌可危的边缘。由于被位于落锤镇的被遗忘者和部落、枯木巨魔、辛迪加盗贼以及巨石食人魔团团包围，驻军没有丝毫预备队可供调遣。当位于受损严重的萨多尔大桥的矮人指挥官急切请求增援以击退黑铁矮人时，尼艾丝队长不得不予以拒绝。避难谷地的每一把剑、每一面盾牌和每一份补给都必须用于保卫高地，并为夺回激流堡的反攻做准备。"}},faq={{q="为什么联盟在这里的兵力如此薄弱？",a="激流堡王国在第三次大战后沦为废墟，迫使大多数幸存的平民向南撤离。避难谷地的部队是激流堡军队的一支陷入苦战的残部，并得到了联盟远征军的加强。由于补给极度匮乏，且四面受敌，他们勉强只能守住自己的防御营地。",al={"为什么避难谷地规模很小","为什么士兵这么少","阿拉希联盟兵力"}},{q="为什么避难谷地不派兵支援萨多尔大桥？",a="当矮人信使请求派兵保卫丹莫德和萨多尔大桥，以抵御黑铁矮人的进攻时，尼艾丝队长不得不拒绝。由于激流堡已经沦陷，且被敌对势力包围，职责和生存需求要求每一名士兵都必须留下来坚守高地并夺回他们沦陷的首都。",al={"为什么不支援丹莫德","尼艾丝队长萨多尔大桥","联盟的恳求任务"}},{q="谁在指挥这个营地？",a="尼艾丝队长指挥着避难谷地的驻军。她负责指导激流堡在高地各处的军事行动，协调侦察工作、针对辛迪加和食人魔的小规模战斗，以及沿着主干道的防御巡逻。",al={"避难谷地领导人","谁在这里负责","尼艾丝队长"}},{q="什么是阿拉索联军？",a="阿拉索联军是一个致力于收复阿拉希高地并保卫邻近阿拉希盆地重要资源的联盟组织。他们与避难谷地的激流堡残部并肩作战，抵御被遗忘者领导的污染者对这片肥沃山谷的控制。",al={"阿拉索联军","谁是阿拉索联军","阿拉希盆地联盟"}}},fp="13,302,35.464.0,22.557.0,43.337.0,66.329.0,22.238.0,30.295.0"}
P.entries["subzone:remtravel-s-excavation"] = {n="雷姆塔维尔挖掘场",s="雷姆塔维尔挖掘场是一处位于黑海岸南部的考古挖掘点。该探险队由矮人勘察员雷姆塔维尔建立，最近他们在挖掘古老的地下遗迹时，意外发掘出了充满敌意的石腭怪和石傀儡，这些生物很快就淹没了整个采石场。",h="雷姆塔维尔挖掘场是一处位于黑海岸南部的考古挖掘点。该探险队由矮人勘察员雷姆塔维尔建立，最近他们在挖掘古老的地下遗迹时，意外发掘出了充满敌意的石腭怪和石傀儡，这些生物很快就淹没了整个采石场。",kw={"黑海岸","挖掘","化石","傀儡","碎石","勘察员","雷姆塔维尔","石腭怪"},ang={["race:Dwarf"]="探险者协会的矮人探险家以寻求过去的秘密而闻名，尽管在异国土地上挖掘出危险的石腭怪往往会带来熟悉的麻烦。",["race:NightElf"]="卡多雷通常对联盟矮人这种深入的干预行为持怀疑态度，尤其是在这种粗心大意的挖掘惊动了黑海岸古老土地上的野生石腭怪时。"},sec={{t="被淹没的采石场",b="勘察员雷姆塔维尔来到黑海岸寻找遥远过去的遗物，他在远离奥伯丁安全区域的地方建立了一个雄心勃勃的挖掘点。当挖掘古老地层时，他的团队在地底之下发掘出了一群地下碎石石腭怪，以及笨重的石傀儡。该挖掘点瞬间从学术考古地变成了危险区，矿工们四散奔逃，雷姆塔维尔也只能匆忙撤离，试图抢回他最有价值的发现。"},{t="失踪的化石",b="在挖掘现场陷入混乱之前，雷姆塔维尔曾发现过一块散发着奇异神秘特性的稀有化石。在石腭怪突袭引发的恐慌中，再加上他那出了名的健忘，这位勘察员在混乱的土坑中弄丢了这件珍贵的遗物。深入挖掘点取回化石意味着必须同时面对凶恶的石腭怪和那些被镐头惊醒的古老自动机械。"}},faq={{q="雷姆塔维尔挖掘场是什么地方？",a="这是一处位于黑海岸南部的考古挖掘点，由勘察员雷姆塔维尔建立，他是一位寻找古老化石和地下遗物的探险家。",al={"这里是什么地方","黑海岸挖掘点","雷姆塔维尔挖掘场"}},{q="为什么这里会有石腭怪？",a="矮人矿工挖掘得太深，凿穿了地下洞穴，惊醒了当地的一个被称为碎石石腭怪的部落，同时也惊醒了沉睡的石傀儡。",al={"为什么黑海岸有石腭怪","碎石石腭怪","石腭怪来自哪里"}},{q="勘察员雷姆塔维尔是谁？",a="他是一位领导挖掘工作的矮人考古学家。他以对文物的敏锐眼光和健忘的性格而闻名，在挖掘场遭到袭击时，他弄丢了一块关键的化石。",al={"雷姆塔维尔是谁","勘察员雷姆塔维尔背景故事"}},{q="这里发现了什么样的遗物？",a="在石腭怪从深处涌出之前，雷姆塔维尔发现了一块蕴含着奇异、神秘特性的特殊化石。",al={"他们发现了什么","雷姆塔维尔的化石","神秘化石"}}},fx={f43c459f={q="雷姆塔维尔挖掘场危险吗？",a="对于没有接受过适当战斗训练的人来说，这里极其危险。露天矿坑和沟壑里到处都是凶暴的Gravelflint穴居人，以及被挖掘出来的庞大魔像；它们一发现入侵者就会发起攻击。",al={"雷姆塔维尔挖掘场有多危险","雷姆塔维尔挖掘场安全吗","雷姆塔维尔挖掘场的危险"}},["92ab137b"]={q="为什么叫雷姆塔维尔挖掘场？",a="这处挖掘场得名于勘察员雷姆塔维尔。这位著名的矮人考古学家曾在黑海岸主持发掘行动，寻找古代遗物。",al={"雷姆塔维尔挖掘场名称由来","为什么叫雷姆塔维尔","谁给雷姆塔维尔挖掘场命名"}},["6ff3d594"]={q="雷姆塔维尔挖掘场发生过什么？",a="勘察员雷姆塔维尔在黑海岸建立了这处考古挖掘场，并发掘出一块具有神秘力量的特殊化石。然而，他的挖掘打通了地下密室，惊醒了敌对的碎石穴居人和巨大的远古魔像。随着这些生物涌出，考察队失去了对现场的控制，而那个心不在焉的矮人也在混乱中弄丢了他珍爱的遗物。",al={"雷姆塔维尔挖掘场历史","挖掘地点发生了什么","雷姆塔维尔挖掘场的历史"}},["37fcd3a2"]={q="谁负责雷姆塔维尔挖掘场？",a="这处挖掘场由著名的矮人考古学家勘察员雷姆塔维尔建立并主持。然而，他不在场时，现场已没有和平的工人。敌对的碎石穴居人和活化的石魔像占据了挖掘沟，赶走研究人员并控制了挖掘场。",al={"谁控制雷姆塔维尔挖掘场","谁住在雷姆塔维尔挖掘场","雷姆塔维尔挖掘场的居民"}},["3a095efd"]={q="雷姆塔维尔挖掘场为什么被废弃？",a="挖掘工作打通了埋藏的洞穴，放出成群凶悍的碎石穴居人，也惊动了出土的石魔像，考察队因此不得不停止作业。挖掘者无力抵挡如此强大的力量，只能逃离现场，留下设备。",al={"雷姆塔维尔挖掘场为什么被废弃","雷姆塔维尔为什么离开挖掘场","是什么毁了雷姆塔维尔挖掘场"}}},fp="22,296,16.470.0,18.413.1,31.154.0,26.167.0,28.184.0,39.133.0"}
P.entries["subzone:render-s-rock"] = {n="撕裂者之石",s="撕裂者之石是一座隐藏在赤脊山西北角悬崖中的洞穴要塞，坐落在通往燃烧平原的高处山口附近。它由凶猛的黑石兽人控制，作为前进堡垒，是他们对下方山谷进行突袭的活跃集结地。",h="撕裂者之石是一座隐藏在赤脊山西北角悬崖中的洞穴要塞，坐落在通往燃烧平原的高处山口附近。它由凶猛的黑石兽人控制，作为前进堡垒，是他们对下方山谷进行突袭的活跃集结地。",kw={"黑石兽人","燃烧平原","基沙恩下士","基沙恩","赤脊山","撕裂者之石"},ang={["faction:Alliance"]="对于联盟战士来说，撕裂者之石代表了黑石氏族在赤脊山最根深蒂固的据点之一，清除它是营救基沙恩下士和保护湖畔镇的关键。"},sec={{t="高地上的黑石堡垒",b="撕裂者之石开凿于湖畔镇北部的崎岖高地，是入侵的黑石氏族的防御性洞穴系统。从这个靠近通往燃烧平原山口的易守难攻的堡垒出发，经验丰富的黑石兽人策划着针对赤脊山当地守军的进攻。这里阴影重重的深处戒备森严，对于那些试图切断兽人补给线或营救冲突中失踪战俘的人来说，任何深入其中的尝试都是极其危险的行动。"},{t="阴影中的人质",b="除了对兽人的战略价值外，撕裂者之石对湖畔镇的守军也具有严峻的重要性。赤脊山的受伤士兵基沙恩下士被囚禁在其深处。基沙恩身陷敌后，与同伴失散，他的被俘既体现了黑石氏族入侵的猖獗，也凸显了当地驻军为保卫山路畅通所付出的沉重代价。"}},faq={{q="撕裂者之石在哪里？",a="撕裂者之石位于赤脊山西北部的极远处山峰中，坐落在通往北方燃烧平原的小路旁。",al={"撕裂者之石位置","撕裂者之石在哪里","寻找撕裂者之石"}},{q="谁控制着撕裂者之石？",a="这个洞穴被强大的黑石兽人占据，他们将此峭壁作为堡垒来协调进攻，并监控着与燃烧平原接壤的山路。",al={"谁住在撕裂者之石","撕裂者之石的敌人","谁控制了撕裂者之石"}},{q="谁被关押在洞穴里？",a="联盟驻军的一名受伤老兵基沙恩下士被关押在撕裂者之石内，需要援助才能安全逃回湖畔镇。",al={"基沙恩位置","撕裂者之石俘虏","谁被困在撕裂者之石"}},{q="为什么这个洞穴对湖畔镇的防御很重要？",a="因为撕裂者之石在赤脊山谷上方窝藏了经验丰富的黑石战士，对湖畔镇构成了直接威胁，并使兽人得以在燃烧平原以南维持一个立足点。",al={"为什么要进攻撕裂者之石","撕裂者之石威胁","撕裂者之石的重要性"}}},fx={["4e201338"]={q="撕裂者之石是什么地方？",a="撕裂者之石是一处广阔而阴森的洞穴，开凿在赤脊山西北部崎岖的群山之中，靠近通往北方燃烧平原的山口。它并非普通的天然巢穴，而是从北方步步逼近的敌对黑石氏族所建的坚固据点和集结地。",al={"撕裂者之石是什么地方","撕裂者之石洞穴","介绍撕裂者之石"}},a0be54e2={q="撕裂者之石危险吗？",a="这里极其危险。洞穴深处盘踞着老练的黑石兽人老兵和劫掠者，他们已将此地加固成堡垒。毫无防备的旅行者一旦进入，就可能立刻被纪律严明、全副武装的战士包围。",al={"撕裂者之石安全吗","撕裂者之石有多危险","撕裂者之石的威胁"}}},fp="13,300,34.483.0,24.411.1,31.144.0,27.164.0,34.166.0,50.220.0"}
P.entries["subzone:render-s-valley"] = {n="撕裂者山谷",s="撕裂者山谷是位于赤脊山东南部的一处偏僻营地，由黑石兽人占据。相比起规模宏大的石堡要塞，这里的防御工事要薄弱得多，但它依然对附近的旅人构成了持续的威胁，并关押着从周边地区掠夺来的俘虏。",h="撕裂者山谷是位于赤脊山东南部的一处偏僻营地，由黑石兽人占据。相比起规模宏大的石堡要塞，这里的防御工事要薄弱得多，但它依然对附近的旅人构成了持续的威胁，并关押着从周边地区掠夺来的俘虏。",kw={"黑石兽人","赤脊山","撕裂者山谷","阿祖拉之塔的仆从","悲伤沼泽通道"},ang={["faction:Alliance"]="该营地是黑石氏族的一个次要劫掠前哨，威胁着赤脊山南部，因此铲除它对于保障湖畔镇的贸易与交通至关重要。",["profession:Tailoring"]="被关押在兽人营地的阿祖拉之塔仆从会向那些愿意杀出重围接近他的工匠提供独特的裁缝图纸和材料。"},sec={{t="东南方的一处立足点",b="撕裂者山谷坐落在止水湖东南方向的崎岖山脊之间，是黑石兽人在赤脊山活动的辅助营地。与北部悬崖上那些防御森严的堡垒和石塔不同，这座山谷仅由几顶简陋的战帐、旗帜和哨岗组成。尽管这里的兵力规模和武装程度都不如黑石氏族的核心部队，但他们依然不断劫掠当地的道路，骚扰过往行人，并将被捕的俘虏关押在简陋的笼子里严加看守。"},{t="秘密路径与被俘者",b="除了在土路上巡逻的战队外，这座山谷对于勇敢的侦察兵来说还有意想不到的发现。营地内偶尔能见到人类俘虏的身影，其中包括一名与阿祖拉之塔有关联的被俘仆从，他竟然在看守者的眼皮底下成功地交易了特种商品。此外，山谷后方高耸的南部峭壁上还有一些崎岖且未标记的小径，敢于冒险的探路者可以通过这些路径翻越边境，进入昏暗的悲伤沼泽。"}},faq={{q="谁控制着撕裂者山谷？",a="该山谷由黑石氏族占据，这是一个极具侵略性的兽人派系，他们从燃烧平原向南推进至赤脊山，意图征服领土并骚扰人类定居点。",al={"谁在撕裂者山谷","撕裂者山谷兽人","撕裂者山谷是什么氏族"}},{q="这里的兽人和石堡的兽人一样危险吗？",a="不。驻扎在撕裂者山谷的黑石战士通常比驻守在北部石堡要塞的精锐部队更年轻，战斗力也相对较弱。",al={"撕裂者山谷难度","这里的兽人有多强"}},{q="营地里关押的俘虏是谁？",a="一名与艾尔文森林的阿祖拉之塔有关联的仆从被黑石氏族俘获并关押在这里。那些有胆量接近他的人可以获得专业的裁缝用品。",al={"撕裂者山谷俘虏","赤脊山的阿祖拉之塔仆从","撕裂者山谷裁缝"}},{q="能从这里前往悲伤沼泽吗？",a="可以。在撕裂者山谷后方，有一条陡峭的非官方山路蜿蜒穿过南部的峭壁，这是一条直接通往悲伤沼泽北部荒野的隐藏捷径。",al={"通往悲伤沼泽的道路","撕裂者山谷山路","赤脊山到悲伤沼泽的捷径"}}},fx={["5cb67798"]={q="撕裂者山谷是什么地方？",al={"撕裂者山谷是什么地方","撕裂者山谷的背景","撕裂者山谷在哪里"}}},fp="15,279,27.484.0,25.498.0,29.186.0,57.188.0,37.197.0,45.187.0"}
P.entries["subzone:rethban-caverns"] = {n="瑞斯班洞穴",s="瑞斯班洞穴是一套隐藏在赤脊山西北侧悬崖中的庞大洞穴系统。这里盘踞着好斗的赤脊山豺狼人，它是瑞斯班矿石这种稀有矿产的唯一来源，因此而闻名。",h="瑞斯班洞穴是一套隐藏在赤脊山西北侧悬崖中的庞大洞穴系统。这里盘踞着好斗的赤脊山豺狼人，它是瑞斯班矿石这种稀有矿产的唯一来源，因此而闻名。",kw={"多诺·烂爪","烂爪","豺狼人","湖畔镇","赤脊山","瑞斯班","瑞斯班洞穴","瑞斯班矿石"},ang={["faction:Alliance"]="盘踞在洞穴内那群好斗的豺狼人对赤脊山北部的旅行者构成了持续的威胁，需要湖畔镇的守卫来确保断崖的安全。",["profession:Mining"]="这些洞穴因盛产瑞斯班矿石而闻名，这是一种当地豺狼人部落激烈争夺的矿产资源。"},sec={{t="豺狼人巢穴",b="瑞斯班洞穴深深地开凿在俯瞰止水湖的西北侧山脉中，是当地豺狼人的防御要塞。在狡诈的领袖多诺·烂爪的统领下，这群豺狼人凶猛地守卫着弯曲的通道和地底洞室，攻击任何靠近其山坡入口的游荡者。"},{t="瑞斯班的矿脉",b="这些洞穴以瑞斯班矿石而闻名，这是一种在岩壁中发现并被烂爪氏族所持有的独特矿物。湖畔镇的铁匠和研究者经常派遣旅行者进入危险且蜿蜒的隧道，以收集这种稀有的山脉矿石样本。"}},faq={{q="瑞斯班洞穴位于何处？",a="洞穴位于赤脊山西北部地区的参差断崖沿线，在通往湖畔镇主路的北面。",al={"瑞斯班洞穴位置","瑞斯班在哪里","如何找到瑞斯班洞穴"}},{q="什么生物栖息在瑞斯班洞穴中？",a="隧道中挤满了烂爪氏族的赤脊山豺狼人，他们听命于狡诈的酋长多诺·烂爪。",al={"瑞斯班怪物","谁住在瑞斯班洞穴","瑞斯班敌人"}},{q="为什么冒险者要进入这些洞穴？",a="来自湖畔镇的旅行者和镇民们为了寻找瑞斯班矿石而来，这是一种在洞穴深处发现并被盘踞在此的豺狼人所持有的稀有矿脉。",al={"瑞斯班洞穴任务","为什么去瑞斯班洞穴","瑞斯班矿石任务"}}},fx={b8930d83={q="瑞斯班洞穴是什么地方？",a="瑞斯班洞穴是一片庞大的洞穴系统，蜿蜒深入赤脊山西北部的群山。这里原本是天然的地下通道，如今却成了当地豺狼人的巢穴；它们在洞内开采并守护稀有的瑞斯班矿石。",al={"瑞斯班洞穴是什么地方","瑞斯班洞穴简介","瑞斯班洞穴的背景"}},["206356ed"]={q="瑞斯班洞穴危险吗？",a="是的，这里极其危险。洞穴里挤满了凶猛的豺狼人，它们听命于狡猾的首领Ardo Dirtpaw。任何深入地下的人都可能很快遭到围攻，困在黑暗之中。",al={"瑞斯班洞穴危险吗","瑞斯班的危险","瑞斯班洞穴有多危险"}}},fp="15,209,14.331.0,20.267.0,34.142.0,44.113.0,44.146.0"}
P.entries["subzone:ridgepoint-tower"] = {n="山巅之塔",s="山巅之塔是一座加固过的哨所，监视着艾尔文森林的东部边境。它由暴风城卫兵驻守，是防御王国中心地带免受敌对势力侵袭的一道预警屏障。哨所的卫兵们密切监视着通往邻近荒野的危险通道。",h="山巅之塔是一座加固过的哨所，监视着艾尔文森林的东部边境。它由暴风城卫兵驻守，是防御王国中心地带免受敌对势力侵袭的一道预警屏障。哨所的卫兵们密切监视着通往邻近荒野的危险通道。",kw={"迪菲亚","暮色森林","艾尔文森林","豺狼人","赤脊山","山巅之塔","暴风城卫兵","瞭望塔"},ang={["class:Warrior"]="无论是士兵还是雇佣兵，都会对这些在危机四伏的边境前哨坚守的卫兵们肃然起敬。",["faction:Alliance"]="对于联盟的旅行者来说，山巅之塔是一座令人心安的灯塔，代表着在穿越赤脊山危险山口或暮色森林闹鬼道路之前的安全与秩序。"},sec={{t="东部边境的哨兵",b="Standing sentinel on the high ground of eastern Elwynn Forest, Ridgepoint Tower marks the final bastion of direct Stormwind authority before the untamed wilds take over. The garrison stationed here keeps a constant watch over the surrounding valleys and roads. With tensions mounting across the continent, this stone watchtower ensures that encroaching threats are spotted and checked before they can endanger the farms and settlements closer to Northshire and Goldshire."},{t="地平线上的重重威胁",b="山巅之塔同时面临来自多个方向的压力。东面是赤脊山，那里有凶猛的豺狼人部族和黑石兽人袭击者不断试探人类的防御。穿过南方的河流，便是阴影笼罩的暮色森林，那里潜伏着亡灵恐怖。在更近的地方，迪菲亚潜行者的强盗们在荒野营地中四处游荡，急于利用守军防线上的任何空隙。"}},faq={{q="什么是山巅之塔？",a="山巅之塔是一座由暴风城卫兵在艾尔文森林东部运营的加固侦察塔。它作为前线哨所，负责警示并保护王国免受敌对入侵。",al={"山巅之塔 艾尔文","这座哨塔是什么","艾尔文东部塔楼"}},{q="谁控制并驻守这座塔？",a="这座塔由效忠于暴风城王国的卫兵和侦察兵把守并驻扎，并在暴风城卫兵的指挥下运作。",al={"谁在山巅之塔","谁拥有山巅之塔"}},{q="驻军在防范哪些威胁？",a="卫兵们防范着从赤脊山涌出的豺狼人和入侵的兽人，从暮色森林被亵渎的树林中穿行而来的亡灵，以及在附近隐秘林地营地活动的迪菲亚强盗。",al={"山巅之塔附近的敌人","是什么在攻击山巅之塔","为什么这里会有塔"}},{q="山巅之塔位于何处？",a="它矗立在艾尔文森林最东端的高地上，靠近艾尔文森林与赤脊山以及暮色森林的交界处。",al={"山巅之塔位置","山巅之塔在哪里"}}},fx={eff326af={q="山巅之塔危险吗？",a="塔楼本身由暴风城卫兵牢牢把守，十分安全，但周边地区危机四伏。这座哨塔位于战略边境，时刻受到来自赤脊山的豺狼人和兽人、从暮色森林向北游荡的不死生物，以及潜伏在附近营地的迪菲亚强盗的威胁。",al={"山巅之塔危险吗","山巅之塔安全吗","山巅之塔的威胁"}}},fp="16,309,30.471.0,24.421.0,25.209.0,32.143.0,45.206.0,34.155.0"}
P.entries["subzone:rocktusk-farm"] = {n="石牙农场",s="石牙农场是位于杜隆塔尔北部的一个小型养猪场，坐落在奥格瑞玛大门外的道路旁。该农场紧邻首都的防御工事，为城中居民供应必要的肉类和物资。",h="石牙农场是位于杜隆塔尔北部的一个小型养猪场，坐落在奥格瑞玛大门外的道路旁。该农场紧邻首都的防御工事，为城中居民供应必要的肉类和物资。",kw={"杜隆塔尔","部落补给","奥格瑞玛","养猪场","石牙农场","猪"},ang={["faction:Horde"]="农场坐落在首都郊外，这里饲养的猪只对于驻扎在奥格瑞玛的战士和劳工来说是至关重要的食物来源。",["profession:Cooking"]="农场里饲养的猪深受部落厨师的青睐，他们一直在寻找新鲜的猪肉、肋排和美味的肉块进行烧烤。"},sec={{t="首都的补给",b="石牙农场在杜隆塔尔干旱的土地上开辟而成，专门饲养能够适应粗砺沙漠气候的耐寒猪。由于杜隆塔尔的土地极其干旱且多石，耕种非常困难，因此家猪养殖场成为了维持奥格瑞玛日益增长的人口所需的基本生命线。农场坐落在首都坚固的防御圈附近，享有着在红色峡谷荒野中难得的安全保障。"}},faq={{q="石牙农场的用途是什么？",a="石牙农场是一个家猪养殖场。它饲养猪只，为邻近的奥格瑞玛首都供应鲜肉和物资，因为那里缺乏耕地。",al={"这是什么地方","石牙农场的作用","为什么这里有猪"}},{q="石牙农场位于哪里？",a="农场位于杜隆塔尔北部，就在奥格瑞玛正门西南方向的道路旁，依傍着岩石峭壁。",al={"石牙农场在哪里","石牙农场位置"}},{q="农场能避开野兽的威胁吗？",a="由于它紧邻奥格瑞玛且有部落巡逻队驻扎，相比杜隆塔尔其他偏远的农场要安全得多，尽管仍有一些野兽和徘徊的害虫出没在边缘地带。",al={"石牙农场安全吗","石牙农场的危险"}}},fx={["38585a5d"]={q="石牙农场是什么地方？",a="石牙农场是一处养猪庄园，坐落在杜隆塔尔奥格瑞玛城门外的西侧道路旁。农场位于首都防线的崎岖阴影之下，为日益壮大的部落饲养猪只，提供重要的食物和补给。",al={"石牙农场是什么地方","杜隆塔尔石牙农场","石牙农场简介"}}},fp="13,241,26.449.0,31.159.0,31.140.0,34.187.0"}
P.entries["subzone:roguefeather-den"] = {n="飞羽洞穴",s="飞羽洞穴是坐落在千针石林中南部的一处洞穴。这座洞穴里盘踞着凶猛尖叫的鹰身人，鹰身人将这里当作一处加固过的巢穴，并把搜刮来的补给藏在深处的阴暗角落里。",h="飞羽洞穴是坐落在千针石林中南部的一处洞穴。这座洞穴里盘踞着凶猛尖叫的鹰身人，鹰身人将这里当作一处加固过的巢穴，并把搜刮来的补给藏在深处的阴暗角落里。",kw={"洞穴","鹰身人","飞羽","飞羽洞穴","巢穴","千针石林"},ang={["faction:Horde"]="对于前往闪光平原的长途跋涉的部落旅行者来说，栖息在飞羽洞穴中的那群好斗的鹰身人构成了南部峡谷底部持续存在的空中威胁和伏击威胁。"},sec={{t="峡谷中的巢穴",b="飞羽洞穴开凿在千针石林南部的陡峭砂岩断崖上，是当地鹰身人那污秽的巢穴。鹰身人以其野蛮的尖叫和极强的领地意识而闻名，它们将这个洞穴既视为安全的避难所，也视为仓库，警惕地守卫着堆放在洞穴后方深处黑暗角落里的食物和Stolen Supplies。"}},faq={{q="飞羽洞穴是什么？",a="这是一处位于千针石林南侧峭壁上的小型洞穴，是具有领地意识的飞羽鹰身人的巢穴和补给仓库。",al={"这个洞穴是什么","飞羽洞穴信息","飞羽洞穴在哪里"}},{q="什么生物栖息在这个洞穴里？",a="洞穴里盘踞着充满敌意、不断尖叫的鹰身人，它们凶猛地保护着自己的巢穴和囤积的食物，抵御任何入侵者。",al={"谁住在飞羽洞穴里","飞羽洞穴里的怪物"}},{q="飞羽洞穴深处藏着什么？",a="在洞穴的最深处，鹰身人囤积着搜刮和窃取来的食物，并以无情的攻击性守护着它们。",al={"洞穴深处有什么","飞羽食物"}}},fx={["2910d8e2"]={q="飞羽洞穴危险吗？",a="是的，进入洞穴极其危险。洞内狭窄，盘踞着凶猛尖叫的 harpy，它们会拼命守护自己的领地。进入者可能在黑暗的隧道中遭到围攻，尤其是靠近洞穴深处时，那里的一群 harpy 会狂热地守护它们囤积的物资。",al={"飞羽洞穴危险吗","飞羽洞穴的危险","飞羽洞穴有多危险"}}},fp="16,246,22.378.0,25.157.0,32.138.0,42.133.0"}
P.entries["subzone:rogues-quarter"] = {n="Rogues' Quarter",s="Rogues' Quarter是幽暗城东南侧一个灯光昏暗的区域。这里是被遗忘者的斥候、刺客和地下活动人员的集结地，同时也聚集了支持他们的工匠。",h="Rogues' Quarter是幽暗城东南侧一个灯光昏暗的区域。这里是被遗忘者的斥候、刺客和地下活动人员的集结地，同时也聚集了支持他们的工匠。",kw={"工程学","被遗忘者","制皮","毒药商人","潜行者训练师","rogues' quarter","剥皮","幽暗城"},ang={["class:Rogue"]="对于被遗忘者和部落的刺客来说，这个区域是掌握潜行、学习战斗技巧和储备致命毒药试剂的首选中心。",["profession:Engineering"]="修补匠们来到Rogues' Quarter学习图纸，并制作隐秘特工所青睐的炸弹、小玩意和机械工具。"},sec={{t="幽暗城的阴影",b="Rogues' Quarter隐藏在地下都市的东南象限，聚集了被遗忘者中最狡诈、最致命的幸存者。生前，他们中的许多人曾是洛丹伦王国的盗贼、扒手或沉默的利刃；死后，他们在潜行、毒药和误导方面的专长被重新利用，用以保护这个新生的国家免受天灾军团和血色十字军的威胁。该区域充满了静谧的活动，提供了一个隐秘的避风港，特工们在这里磨砺匕首，酿造致命毒素，并磨练秘密技能。"},{t="生存工具",b="除了潜行和暗杀，Rogues' Quarter还是实现隐蔽生存的专业技能所在地。工匠们聚集在这里，教导旅行者学习制皮和剥皮，将生皮转化为轻便、静音的护甲。当工匠们组装小玩意时，工程学工作台的碰撞声在石厅中回荡，而战地医师和药剂师则提供急救指导，并出售隐秘行动所必需的致命毒药。"}},faq={{q="Rogues' Quarter位于哪里？",a="Rogues' Quarter位于幽暗城外环的东南部分，穿过Trade Quarter即可到达。",al={"rogues' quarter位置","rogues' quarter在哪里","幽暗城rogues' quarter地图"}},{q="这里有哪些训练师？",a="该区域设有潜行者训练师，以及制皮、剥皮、工程学和急救的导师。附近还驻扎有毒药商人以供应试剂。",al={"rogues' quarter训练师","幽暗城潜行者训练师","谁在rogues' quarter训练"}},{q="为什么被遗忘者要专门为潜行者保留一个区域？",a="被遗忘者被天灾军团和血色十字军等敌对势力包围，他们严重依赖间谍活动、暗杀和打了就跑的战术来保卫领土，这使得隐秘特工对他们的生存至关重要。",al={"为什么被遗忘者需要潜行者","被遗忘者刺客","幽暗城潜行者背景故事"}}},fx={["4d735fe6"]={q="Rogues' Quarter是什么地方？",a="Rogues' Quarter是幽暗城东南部的区域，开凿于洛丹伦地下的废墟之中。这里是被遗忘者盗贼公会及其秘密行动网络的地盘。除了从事间谍活动和潜行，这里还有专门的工匠、制毒师、制皮师、剥皮师和工程师，为被遗忘者的秘密行动提供支持。",al={"rogues' quarter是什么地方","幽暗城rogues' quarter","rogues' quarter简介"}},["8086d959"]={q="Rogues' Quarter危险吗？",a="如果你是被遗忘者和部落的盟友，在这里不会遭遇明显的直接威胁。然而，这里住着一群擅长欺诈和隐匿的刺客、盗贼与秘密特工。最好不要逗留太久，也不要打探公会制毒师和间谍的事务，因为这里的居民受过训练，能悄无声息地消灭威胁。",al={"rogues' quarter安全吗","rogues' quarter的危险","rogues' quarter的敌对势力"}},e71830ac={q="为什么叫Rogues' Quarter？",a="这个区域得名于在昏暗大厅中建立据点的盗贼公会。它将被遗忘者的斥候、渗透者和杀手聚集在一处，并为他们的致命行当提供导师、毒药商和工匠。",al={"为什么叫rogues' quarter","rogues' quarter名称由来","rogues' quarter的名称"}}},fp="15,226,24.540.0,18.454.0,37.114.0,32.181.0,61.226.0"}
P.entries["subzone:roland-s-doom"] = {n="罗兰之墓",s="罗兰之墓是一座荒废、阴影笼罩的矿井，坐落于暮色森林的东南部山区，就在烂果园的东边。这里曾是一处普通的挖掘点，如今却因被野蛮的狼人占领而成为了臭名昭著的危险巢穴。",h="罗兰之墓是一座荒废、阴影笼罩的矿井，坐落于暮色森林的东南部山区，就在烂果园的东边。这里曾是一处普通的挖掘点，如今却因被野蛮的狼人占领而成为了臭名昭著的危险巢穴。",kw={"噬骨者","基特斯","内法鲁","夜祸","罗兰之墓","烂果园","艾露恩之镰","维琳德·星歌"},ang={["profession:Mining"]="虽然这里曾经是一座运作中的采石场，但任何愚蠢到在这里挥动十字镐的勘探者都会很快发现，罗兰之墓里唯一的矿脉就是嗜血的狼人。",["race:NightElf"]="对失踪的女祭司维琳德·星歌和难以捉摸的艾露恩之镰的搜寻，使得罗兰之墓成为了那些调查族人命运的暗夜精灵们进行沉思的场所。"},sec={{t="阴影与野蛮的巢穴",b="罗兰之墓开凿在烂果园以东的山脊中，早已不再是运作中的矿井。它现在是夜祸狼人氏族的暴力聚集地，由噬骨者和内法鲁等野兽领导。阴暗的隧道中回荡着低沉的咆哮，弥漫着潮湿的泥土和血腥味，这使得它成为暮色森林对粗心大意的旅人而言最危险的角落之一。"},{t="维琳德·星歌的陨落",b="罗兰之墓真正的悲剧深埋在它的隧道之中。正是此地，暗夜精灵女祭司维琳德·星歌在携带艾露恩之镰——一件拥有强大且不稳定力量的远古神器——时走到了生命的尽头。矿井中被惊动的尘土依然能唤起维琳德残留的灵魂，诉说着她最后的时刻。后来，受惊的流浪者基特斯在挖掘点内偶然发现了这把镰刀，意外地导致野蛮狼人的数量激增，并将致命的黑暗骑士引到了暮色森林。"}},faq={{q="什么是罗兰之墓？",a="罗兰之墓是一座位于暮色森林东南部，烂果园东侧的废弃矿井。目前已被凶残的夜祸狼人所占领。",al={"罗兰之墓在哪里","这个矿井是什么"}},{q="为什么矿井里会有狼人？",a="在艾露恩之镰遗失后，这座矿井就被狼人所侵占。目前，包括内法鲁和噬骨者在内的夜祸狼人氏族强悍野兽，都在其潮湿的矿道中筑巢。",al={"为什么这里有狼人","谁住在罗兰之墓"}},{q="维琳德·星歌是谁，她为什么与这个地方有关？",a="维琳德·星歌是一位艾露恩的暗夜精灵女祭司，她曾挥舞艾露恩之镰与费伍德森林的恶魔战斗。她的旅程跨越重洋来到暮色森林，并在就在这座矿井中遇害，留下了那把镰刀。",al={"维琳德·星歌与罗兰之墓","谁死在这里"}},{q="基特斯在罗兰之墓的故事中扮演了什么角色？",a="基特斯进入了罗兰之墓，发现了埋藏于此的艾露恩之镰。他的插手无意间将更多的狼人释放到暮色森林，并将邪恶的黑暗骑士引向该地区，使这片森林陷入了更大的危险之中。",al={"基特斯与矿井","基特斯与镰刀"}}},fx={c3cc68a4={q="罗兰之墓发生过什么事？",a="这座废弃矿井成了暮色森林诅咒下的悲剧交汇点。暗夜精灵女祭司Velinde Starsong曾带着艾露恩之镰在此丧命。后来，一个名叫基特斯的惊恐男子在黑暗的隧道中发现了埋藏的神器。他的擅自行动释放了凶暴的狼人，使它们涌入周边山丘，并将黑暗力量引至此地，令暮色森林彻底坠入噩梦。",al={"罗兰之墓的历史","矿井里发生了什么","罗兰之墓的背景"}},["4c556f83"]={q="谁控制着罗兰之墓？",a="这座矿井已被夜嚎者狼群的野性狼人彻底占据。深处潜伏着Nefaru和Gutspill，这两头凶残的头狼统领着盘踞在地下矿道和附近烂果园里的狼群。",al={"谁住在罗兰之墓","谁领导罗兰之墓的势力","罗兰之墓的首领"}},fe4bd8ed={q="罗兰之墓危险吗？",a="这里极其危险。狭窄无光的隧道里到处都是凶猛的狼人，随时准备伏击闯入者。除了野兽本身，矿井还弥漫着与艾露恩之镰有关的黑暗巫术，那些死于此处的亡魂仍在阴影中徘徊。",al={"罗兰之墓有多危险","罗兰之墓的威胁"}}},fp="13,225,29.390.0,28.522.1,22.157.0,37.200.1,64.240.1,53.225.1"}
P.entries["subzone:rolling-plains"] = {n="草海平原",s="草海平原横跨莫高雷的南部区域，在血蹄村和贫瘠之地的边界之间延伸。这些风吹草动的草原是野生动物繁衍生息的家园，但由于游荡的半人马掠夺者和好斗的鹰身人，这里也时刻保持着警惕。",h="草海平原横跨莫高雷的南部区域，在血蹄村和贫瘠之地的边界之间延伸。这些风吹草动的草原是野生动物繁衍生息的家园，但由于游荡的半人马掠夺者和好斗的鹰身人，这里也时刻保持着警惕。",kw={"血蹄村","半人马","鹰身人","科多兽","莫高雷","草海平原","陆行鸟","狂风"},ang={["class:Hunter"]="草海平原拥有充足的科多兽、陆行鸟、狼和美洲狮群，是磨练追踪技巧、收集补给和驯服第一只动物伙伴的理想荒野。",["race:Tauren"]="草海平原为新统一的部落提供了重要的狩猎场，但古老的半人马宿敌在血蹄村附近出没，使得保卫这条南部走廊成了关乎部落生存的大事。"},sec={{t="莫高雷南部之心",b="草海平原从血蹄村向南延伸，直抵通往贫瘠之地的天然土质大门，体现了牛头人家园广阔开敞的地理特征。该地区拥有部落生存所需的各种野生猎物，包括草原狼、科多兽群、平原美洲狮和敏捷的陆行鸟。对于向长者证明自己价值的年轻猎人来说，这些广袤的草原是不可或缺的试炼场，在此处，追踪术、耐心和对大自然的敬畏都将经受考验。"},{t="迫近的危险",b="尽管莫高雷拥有天然的环形峭壁堡垒，但草海平原依然极易受到外部威胁。这是唯一一个半人马哨兵突破防御外围并骚扰过往旅行者和狩猎小队的边境地区。更糟糕的是，一群捕食性的狂风鹰身人栖息在东部的悬崖上，俯冲扑向落单的猎物和脆弱的游牧营地。"}},faq={{q="在草海平原可以找到哪些动物？",a="这片草原养育了种类丰富的本地动物群，包括漫步的野生科多兽群、敏捷的陆行鸟、游荡的草原狼和潜行的平原美洲狮。这些野兽为血蹄村的部落提供了重要的肉食、毛皮和筋腱。",al={"草海平原野生动物","草海平原生物","莫高雷平原动物"}},{q="为什么半人马会出现在莫高雷的这一区域？",a="草海平原与通往贫瘠之地的东部通道接壤，使其成为莫高雷唯一一个半人马掠夺者能够突破防线的区域。侵扰的哨兵不断侦察平原，试探牛头人的防御并威胁着落单的猎人。",al={"莫高雷的半人马","为什么草海平原有半人马","半人马哨兵"}},{q="还有哪些敌对生物威胁着这片平原？",a="除了游荡的半人马侦察兵之外，一群危险的狂风鹰身人也在该地区的东部悬崖边筑巢，捕食粗心的旅行者并骚扰当地的野生动物。",al={"草海平原的鹰身人","草海平原的危险"}},{q="草海平原的起止范围在哪里？",a="平原覆盖了莫高雷的大部分南部地区，从血蹄村一直延伸到与贫瘠之地接壤的山区边界。",al={"草海平原位置","草海平原在哪里","草海平原边界"}}},fx={["711c701d"]={q="草海平原是什么地方？",a="草海平原是莫高雷南部广阔的开阔草原，从血蹄村一直延伸到贫瘠之地的边界。这里是富饶的狩猎场，栖息着科多兽、 tallstrider、狼和美洲狮等野生动物，也是莫高雷南部牛头人领地的牧歌般腹地。",al={"草海平原是什么地方","草海平原的背景","草海平原简介"}},["8a6ccc31"]={q="草海平原危险吗？",a="草原虽是开阔的狩猎场，却并非毫无危险。除了四处游荡的美洲狮和狼，这里还是莫高雷唯一有半人马斥候侵入的区域，它们在开阔地带四处游荡。东部还有一处凶猛的风怒鹰身人巢穴，对旅行者和猎人构成额外威胁。",al={"草海平原有多危险","草海平原的危险","草海平原安全吗"}}},fp="14,296,25.493.0,19.418.0,48.256.0,53.268.0,49.179.0,42.122.0"}
P.entries["subzone:rotting-orchard"] = {n="烂果园",s="烂果园是一片位于暮色森林南部的荒废果林。它曾经是附近夜色镇居民的收成来源，如今已陷入一片颓败，并被一群被称为“夜行者”狼人的凶猛掠食者所占据。",h="烂果园是一片位于暮色森林南部的荒废果林。它曾经是附近夜色镇居民的收成来源，如今已陷入一片颓败，并被一群被称为“夜行者”狼人的凶猛掠食者所占据。",kw={"夜色镇","暮色森林","夜行者","烂果园","暗影编织者","狼人"},ang={["class:Hunter"]="扭曲的树木和损毁的外屋提供了绝佳的潜行场地，但夜行者狼人敏锐的掠食本能和法术，让这里随时都可能发生伏击。",["faction:Alliance"]="夜行者狼人对烂果园的侵占，对不远处的夜色镇本就脆弱的安全构成了直接的掠食威胁。"},sec={{t="夜行者巢穴",b="烂果园坐落在废弃的约根农场以东、静谧花园墓场以西，是暮色森林衰败的冷酷见证。果树上挂满了枯萎腐烂的果实，破败的谷仓和外屋则被夜行者狼人改造成了简陋的营地。夜行者潜行者在扭曲的灌木丛中徘徊，而被称为“暗影编织者”的黑暗施法者们则在腐朽的木材间编织着邪恶的魔法。这群狼人听命于凶猛的古斯皮尔和内法鲁，他们潜伏在附近的罗兰之墓矿井中。"}},faq={{q="烂果园里有哪些生物？",a="这片果园完全被夜行者狼人一族所盘踞。其中包括狡诈的潜行者——夜行者潜行者，以及被称为“夜行者暗影编织者”的黑暗施法者。",al={"烂果园怪物","谁住在烂果园","烂果园有什么"}},{q="烂果园在暮色森林的什么位置？",a="烂果园位于暮色森林南部，夜色镇西南方。它恰好坐落在西边的约根农场和东边的静谧花园墓场之间。",al={"烂果园位置","烂果园在哪里","如何找到烂果园"}},{q="谁在领导果园里的狼人？",a="这里的夜行者狼人由残暴的古斯皮尔和内法鲁领导，他们将巢穴设在果园东侧的罗兰之墓矿井中。",al={"烂果园首领","谁领导夜行者"}},{q="这个地方一直都被怪物占领吗？",a="并不是。像暮色森林周围的许多农舍一样，这里曾经是一个支持当地人类居民的丰饶农场和果林，直到黑暗诅咒和超自然恐怖笼罩了这片地区，迫使农民们背井离乡。",al={"果园历史","果园为何腐烂"}}},fx={a6a9a2a8={q="烂果园是什么地方？",a="烂果园是一处废弃而受诅咒的农场，位于暮色森林南部，坐落在约根农场与静谧花园墓场之间。这里曾是一片丰产的果园，如今已沦为荒凉废墟，夜嚎者狼群的贪婪狼人盘踞其间，在破败的谷仓和阴森的树木之间筑巢。",al={"烂果园是什么地方","暮色森林烂果园的背景","介绍烂果园"}},["144dad4c"]={q="烂果园危险吗？",a="这里极其危险。烂果园里到处都是凶暴的夜嚎者狼人。潜伏者隐匿在昏暗的阴影中，黑暗织法者则在营地中施展邪恶魔法。更糟的是，狼群残暴的首领Gutspill和Nefaru就潜伏在附近的罗兰之墓矿井中。",al={"烂果园安全吗","烂果园的危险","烂果园里的威胁"}}},fp="15,253,20.557.0,42.202.0,49.197.0,37.143.0,42.223.0"}
P.entries["subzone:royal-gallery"] = {n="Royal Gallery",s="Royal Gallery隐藏在Stormwind Keep的庭院花园之后，是一座静谧的纪念厅。厅内陈列着宏伟的雕像和精美的艺术品，用以纪念王国历史和Grand Alliance中的杰出人物。",h="Royal Gallery隐藏在Stormwind Keep的庭院花园之后，是一座静谧的纪念厅。厅内陈列着宏伟的雕像和精美的艺术品，用以纪念王国历史和Grand Alliance中的杰出人物。",kw={"daelin proudmoore","dena kennedy","llane wrynn","mara fordragon","royal gallery","雕像","stormwind keep"},ang={["faction:Alliance"]="这座展廊是Alliance牺牲精神的宁静丰碑，向Daelin Proudmoore和Llane国王等传奇领袖致敬。",["race:Human"]="对于Stormwind的人类来说，这座大厅纪念着Wrynn家族和Fordragon家族的遗产，将他们的皇家传承保留在要塞之中。"},sec={{t="英雄大厅",b="Royal Gallery毗邻Royal Library，就在Stormwind Keep郁郁葱葱的内花园之外。大厅内安放着塑造了这个王国的伟人雕像：Stormwind陨落的统治者Llane Wrynn国王；来自库尔提拉斯的Daelin Proudmoore海军上将；以及第一次战争后逃往Lordaeron的难民的守护者Mara Fordragon女士。它既是一座展示高贵传统的私人博物馆，也是Lady Dena Kennedy这样的宫廷访客寻求宁静的休憩之所。"}},faq={{q="Royal Gallery在哪里？",a="Royal Gallery位于Stormwind Keep内。穿过要塞，经过内部的小型庭院公园，就在Royal Library的旁边。",al={"royal gallery位置","如何前往royal gallery","它在哪里"}},{q="这里纪念了哪些历史人物？",a="展廊内陈列着宏伟的雕像，纪念Llane Wrynn国王、Daelin Proudmoore海军上将和Mara Fordragon，颂扬王国及其最亲密盟友的血统与英勇。",al={"royal gallery的雕像","雕像是谁","这里纪念谁"}},{q="谁会来参观这个展廊？",a="经常可以看到Lady Dena Kennedy在展廊内欣赏精美的艺术品，感受这里沉思般的氛围。",al={"谁在这里","royal gallery的npc","lady dena kennedy"}},{q="Royal Gallery和Royal Library有什么区别？",a="虽然它们在Stormwind Keep的皇家区紧挨着，但它们是不同的房间。图书馆收藏皇家档案并供学者使用，而展廊则专注于精美的艺术品和纪念雕塑。",al={"royal gallery与图书馆的区别","它是图书馆的一部分吗"}}},fx={["57ab90b0"]={q="皇家画廊是什么？",a="皇家画廊是坐落于暴风城堡内的一座雅致展览厅，位于小庭院公园的深处，毗邻皇家图书馆。这里是一处纪念展馆，陈列着精美的艺术品和宏伟的大理石雕像，以纪念联盟与暴风王国的杰出人物。",al={"皇家画廊是什么","暴风城皇家画廊","这个地方是什么"}},["0132543d"]={q="皇家画廊危险吗？",a="完全不危险。画廊位于暴风城堡的核心深处，由城市精锐的皇家卫兵严密守卫。这里始终是一处宁静安全的纪念大厅，贵族和宫廷成员可以在此追思王国最伟大的英雄，无须担心受到伤害。",al={"皇家画廊危险吗","皇家画廊的威胁","皇家画廊安全吗"}}},fp="13,249,16.482.0,35.155.0,47.187.0,38.105.0,71.221.0"}
P.entries["subzone:royal-library"] = {n="Royal Library",s="Royal Library坐落在Stormwind Keep石翼深处，保存着王国的集体记忆、编年史卷轴和论述。在首席图书管理员米尔顿·西弗的注视下，书架上陈列着关于古代战争、失落传说以及海外疆域的关键记录。",h="Royal Library坐落在Stormwind Keep石翼深处，保存着王国的集体记忆、编年史卷轴和论述。在首席图书管理员米尔顿·西弗的注视下，书架上陈列着关于古代战争、失落传说以及海外疆域的关键记录。",kw={"mathias shaw","米尔顿·西弗","royal library","stormwind keep","暴风城图书馆"},ang={["class:Mage"]="对于奥术学者来说，图书馆提供了关于提瑞斯法的过去、远古屠龙记以及最后守护者遗产的稀有原始资料。",["faction:Alliance"]="书架上保存的基础条约和战争编年史，将人类、矮人和精灵种族在历代冲突中紧密联系在了一起。"},sec={{t="王国的宝库",b="虽然Stormwind Keep里充满了全副武装的卫兵和宫廷阴谋，但其Royal Library却是一片宁静的学术绿洲。该馆由米尔顿·西弗监管，是南方人类历史的首要档案馆，不仅保存着第一次战争前的幸存文献，还有近期的军事编年史和找回的古籍。联盟的学者、牧师和旅行者可以自由查阅馆藏的开放论述，内容涵盖从最初洛丹伦联盟的组建到近期萨尔的部落在卡利姆多崛起等各类信息。"}},faq={{q="Royal Library位于哪里？",a="它位于Stormwind City东区的皇家要塞Stormwind Keep内。穿过要塞的大门厅，沿着走廊即可到达学者和档案馆区域。",al={"图书馆在哪里","暴风城图书馆位置","如何找到图书馆"}},{q="谁负责管理图书馆？",a="米尔顿·西弗担任首席图书管理员。他负责管理档案记录，并协助学者和冒险者寻找遗失的卷轴或特定的王国文献。",al={"谁是图书管理员","首席图书管理员","米尔顿·西弗"}},{q="这里可以读到什么种类的书？",a="参观者可以阅读涵盖洛丹伦联盟、提瑞斯法守护者、第二次战争余波，以及有关新部落的报告的历史著作，此外还有关于暴风城和奥特兰克的区域历史。",al={"图书馆里的书","可阅读的背景书籍","读什么"}},{q="谁可以使用图书馆？",a="来自联盟所有种族的冒险者都可以来到Royal Library，翻阅其广泛收藏的卷轴、古籍和关于各种主题的文献。",al={"我可以使用图书馆吗","谁能在图书馆阅读"}}},fx={["0be1be66"]={q="皇家图书馆是什么？",a="皇家图书馆是设于暴风城堡内的一座宏伟档案馆。馆内保存着大量历史典籍、古代卷轴，以及关于塑造世界诸多领域的学术论著。联盟各地的学者和冒险者都可以在此阅览藏书，探寻昔日王国的历史、奥术传说，以及艾泽拉斯的广袤疆域。",al={"皇家图书馆是什么","皇家图书馆简介","暴风城图书馆传说"}},c9a9445a={q="皇家图书馆危险吗？",a="完全不危险。图书馆位于戒备森严的暴风城堡核心深处，由王国皇家卫兵守护。这里十分平和，是学者、编年史学家和游历各地的冒险者安心研读的静谧之所。",al={"皇家图书馆安全吗","皇家图书馆里的危险","皇家图书馆的敌人"}},["45bbfcdd"]={q="为什么称为皇家图书馆？",a="它冠以皇家之名，是因为这里是乌瑞恩家族和暴风王国的官方宫廷图书馆。档案馆位于暴风城堡的王宫内，在王室资助下建立并维护，旨在保存王国的传统、法律和奥术知识。",al={"为何称为皇家图书馆","皇家图书馆名称由来","为什么叫皇家图书馆"}}},fp="13,302,25.545.0,35.204.0,21.167.0,37.222.0,24.164.0"}
P.entries["subzone:royal-quarter"] = {n="Royal Quarter",s="Royal Quarter是幽暗城内隐秘的权力中心，也是Sylvanas Windrunner女士的王座厅。在这里，女妖之王与她的恐惧魔王执行者瓦里玛萨斯共同指挥着被遗忘者，并由精锐的皇家恐惧卫士严密守卫。",h="Royal Quarter是幽暗城内隐秘的权力中心，也是Sylvanas Windrunner女士的王座厅。在这里，女妖之王与她的恐惧魔王执行者瓦里玛萨斯共同指挥着被遗忘者，并由精锐的皇家恐惧卫士严密守卫。",kw={"女妖之王","黑暗女王大厅","皇家恐惧卫士","royal quarter","sylvanas windrunner","王座厅","幽暗城","瓦里玛萨斯"},ang={["faction:Horde"]="前往Royal Quarter的部落使节通常以极度怀疑的眼光看待黑暗女王的那斯雷兹姆顾问，质疑在部落主城的核心地带信任一个恶魔是否明智。",["race:Undead"]="Royal Quarter代表了被遗忘者独立的核心，Sylvanas Windrunner和她的恐惧魔王副官在这里规划着他们解放后的人民的未来。"},sec={{t="黑暗女王的王座",b="Royal Quarter隐藏在高耸的拱门和阴影笼罩的走廊之后，也被称为黑暗女王大厅，是被遗忘者的政治和军事中枢。Sylvanas Windrunner在这间巨大的地下室中坐镇，筹划着她那拥有自由意志的亡灵的生存大计，以及摧毁天灾军团的方略。全副武装的皇家恐惧卫士在台座旁守卫，确保不速之客和刺客无法接近他们的女王。"},{t="危险的联盟",b="站在黑暗女王身边的是那斯雷兹姆瓦里玛萨斯，他是幽暗城中心一个出人意料且令人不安的存在。在洛丹伦废墟的内战期间，为了保命，他站在了Sylvanas一边，并向她的事业宣誓效忠。从Royal Quarter开始，他指挥着死亡卫士并协调着整个王国的防御行动。虽然他的战术狡诈对被遗忘者大有裨益，但他那恶魔的本性令许多部落盟友对他真实的忠诚度心存疑虑。"}},faq={{q="谁在Royal Quarter进行统治？",a="女妖之王Sylvanas Windrunner女士在Royal Quarter的王座上统治着被遗忘者。她的身边是那斯雷兹姆瓦里玛萨斯，他在收复洛丹伦期间向她宣誓效忠。",al={"royal quarter里的人","幽暗城王座厅领袖","谁统治幽暗城"}},{q="为什么王座厅里会站着一个恐惧魔王？",a="瓦里玛萨斯在收复洛丹伦王都期间向Sylvanas Windrunner投降，随后背叛了他的兄弟德瑟罗克和巴纳扎尔。他通过向Sylvanas宣誓效忠保住了性命，现在担任她的执行者和侦察兵大师。",al={"为什么瓦里玛萨斯在这里","幽暗城里的恐惧魔王","为什么恶魔在royal quarter"}},{q="什么是皇家恐惧卫士？",a="皇家恐惧卫士是专门挑选出来保卫Sylvanas女士和Royal Quarter的精锐被遗忘者护卫。他们是幽暗城中最训练有素且致命的防御者。",al={"恐惧卫士","幽暗城王座厅守卫","royal quarter守卫"}},{q="这间大厅还有什么其他用途？",a="除了作为黑暗女王和瓦里玛萨斯的主要接见大厅外，Royal Quarter还设有战场军官，负责协调部落战士参与艾泽拉斯各地的对外战役和战略冲突。",al={"royal quarter里还有什么","royal quarter用途","royal quarter战场军官"}}},fx={["8b23b6f3"]={q="皇家区是什么地方？",a="皇家区又称黑暗女王大厅，是幽暗城内的权力中心。它深藏于洛丹伦废墟之下，这座宽敞的王座大厅是指挥中心，希尔瓦娜斯·风行者女士在此领导被遗忘者，身旁环绕着她最信任的护卫和顾问。",al={"皇家区是什么","幽暗城皇家区","黑暗女王大厅"}},["698c5316"]={q="皇家区危险吗？",a="对部落勇士而言，这座大厅是安全的庇护所，有高大的皇家恐惧卫士严密把守。然而，擅闯此地的联盟入侵者将面临极大的危险，因为女妖之王本人和纳斯雷兹姆瓦里玛萨斯都严阵以待，会将任何胆敢威胁被遗忘者疆域核心的人彻底摧毁。",al={"皇家区安全吗","皇家区里的危险","皇家区是否敌对"}},["199248c7"]={q="为什么称为皇家区？",a="这片区域因其作为地下首都王权与最高指挥中心的地位而得名。在这里，希尔瓦娜斯·风行者女士以自由亡灵的君主身份统治她的王国，并将这座大厅作为自己的宫廷。",al={"为什么称为皇家区","皇家区名称含义","为什么叫皇家区"}}},fp="13,267,25.479.0,20.495.0,33.216.0,53.245.0,31.192.0,44.215.0"}
P.entries["subzone:ruined-reaches"] = {n="废墟海岸",s="废墟海岸构成了艾萨拉南部险峻的海岸线，靠近杜隆塔尔的边界。这里遍布着崩塌的古代遗迹、破碎的船只残骸和锯齿状的浅滩，整个海滩被充满攻击性的沿海掠食者所占据。在这一片荒凉之中，一个小型侏儒前哨站高踞于海浪之上的悬崖边。",h="废墟海岸构成了艾萨拉南部险峻的海岸线，靠近杜隆塔尔的边界。这里遍布着崩塌的古代遗迹、破碎的船只残骸和锯齿状的浅滩，整个海滩被充满攻击性的沿海掠食者所占据。在这一片荒凉之中，一个小型侏儒前哨站高踞于海浪之上的悬崖边。",kw={"艾萨拉","布利莫·加基斯普林","杜隆塔尔","锯齿暗礁","朱比·加基斯普林","娜迦","鱼人","废墟海岸"},ang={["profession:Engineering"]="布利莫和朱比·加基斯普林经营的孤独工坊为探索艾萨拉荒野的工程师们提供了宝贵的零件和补给。",["race:Gnome"]="在艾萨拉充满敌意的悬崖上发现一个繁荣的高科技侏儒家园，这提醒着人们，即便远离铁炉堡，侏儒依然足智多谋。"},sec={{t="饱受摧残的海岸",b="废墟海岸沿着艾萨拉的南部边界延伸，位于杜隆塔尔以北，是一个由岩石入口、悬崖峭壁和布满碎片的沙滩组成的迷宫。如同北边的锯齿暗礁一样，隐蔽的浅滩使得海上航行极其危险，导致无数破损的船只残骸散落在岸边。这里的水域和海滩充满了充满敌意的野生生物，包括领地意识极强的鱼人、凶猛的多头蛇和披甲的娜迦，使得陆路交通与航行一样危险。"},{t="加基斯普林前哨站",b="坐落在俯瞰海滩的西侧悬崖上，是一处意想不到的工匠文明据点：一个可以通过艾萨拉大陆一条陡峭小径到达的侏儒工坊。该前哨站由布利莫和朱比·加基斯普林经营，为路过的冒险者提供工程学组件和一般贸易商品。内部设有一部通往私人宿舍的电梯，里面有三张床位，不过那第三张床究竟属于谁——如果确实有人住的话——仍然是一个安静的家庭谜团。"}},faq={{q="废墟海岸位于哪里？",a="它们构成了艾萨拉最南端的海岸带，与杜隆塔尔的北缘接壤。该地区由沙滩、海岸入口和大陆悬崖下的峭壁组成。",al={"废墟海岸位置","废墟海岸在哪里","如何到达废墟海岸"}},{q="这段海岸有什么威胁？",a="海滩和浅水区栖息着敌对的野生动物，主要是充满攻击性的鱼人部落、多头蛇，以及潜伏在潮滩上的娜迦。",al={"废墟海岸的怪物","这里有什么生物","废墟海岸的生物"}},{q="谁住在悬崖上的侏儒建筑里？",a="布利莫和朱比·加基斯普林在那里生活和工作。他们经营着一家小店，为在荒凉海岸航行的旅行者提供工程学零件和贸易补给。",al={"废墟海岸的侏儒","加基斯普林住宅","谁住在侏儒房子里"}},{q="为什么这里有这么多沉船？",a="和邻近的锯齿暗礁一样，这里的沿海水域布满了礁石和隐蔽的危险，经常让毫无防备的船只触礁，并将它们撞得粉碎。",al={"艾萨拉的沉船","为什么船只在这里失事","废墟海岸的残骸"}}},fp="14,331,16.490.0,24.465.0,37.184.0,43.169.0,49.161.0,38.171.0"}
P.entries["subzone:ruins-of-aboraz"] = {n="阿博拉兹废墟",s="阿博拉兹废墟是坐落在荆棘谷东南部悬崖上的古老古拉巴什石制遗迹。这片摇摇欲坠的台地曾经是庞大的丛林巨魔帝国的一部分，如今却成了被放逐的巫医赞吉尔和他那受其奴役、神志不清的仆从们的隐秘堡垒。",h="阿博拉兹废墟是坐落在荆棘谷东南部悬崖上的古老古拉巴什石制遗迹。这片摇摇欲坠的台地曾经是庞大的丛林巨魔帝国的一部分，如今却成了被放逐的巫医赞吉尔和他那受其奴役、神志不清的仆从们的隐秘堡垒。",kw={"阿博拉兹","查基","朱布瓦尔","荆棘谷","巫医","耶尼库","赞吉尔"},ang={["faction:Alliance"]="联盟的私掠者和雇佣兵在追捕与藏宝海湾的地精和海盗有关的债务或赏金时，经常会撞上赞吉尔的势力。",["race:Troll"]="对于暗矛部族来说，阿博拉兹是一种侮辱：一个利用扭曲的巫毒术奴役同胞巨魔，并将年轻的耶尼库扣押在古拉巴什祖先领地上的流亡者。"},sec={{t="巫医的领地",b="阿博拉兹风化的砖石建筑坐落在朱布瓦尔废墟的东南方，水晶矿洞的南面，已经被改造成了一个炼金术的试验场。被放逐的巫医赞吉尔因受到当地部落和大陆居民的共同排斥，退居于此，酿造威力强大的致幻药水和毒性药剂。在这些石砌的庭院里，赞吉尔完全控制着一支令人不安的仆从大军，其中包括蹒跚的亡灵食尸鬼、被腐蚀的巨魔奴隶，甚至还有被俘虏的沿海娜迦。"},{t="棋子与囚徒",b="赞吉尔那诡异的药水不仅能毒害身体，更能摧毁意志。在那些来回踱步的迷失灵魂中，就有被奴役的暗矛部族青年耶尼库，他的意志至今仍被禁锢在赞吉尔的巫术之中。和他一同盲目徘徊的还有查基·“十指”，一个因躲避藏宝海湾的“海狼”麦金利讨债而逃亡的落魄海盗，如今也沦为了赞吉尔药剂下的一具无知守卫。"}},faq={{q="谁统治着阿博拉兹废墟？",a="这片废墟由被放逐的巫医赞吉尔控制，他因其暗黑炼金术和强大的精神控制药剂在整个荆棘谷臭名昭著。",al={"阿博拉兹的首领","阿博拉兹首领","阿博拉兹废墟里的生物"}},{q="为什么这里会有娜迦和食尸鬼聚集在一起？",a="赞吉尔独特的药剂使他能够支配思想并复活尸体。他强迫巨魔流亡者、起尸的丛林食尸鬼以及被诱捕的沿海娜迦成为其台地的无条件守卫。",al={"为什么这里有娜迦","阿博拉兹食尸鬼","阿博拉兹怪物"}},{q="阿博拉兹废墟位于哪里？",a="它们坐落在荆棘谷东南部的高耸悬崖上，位于水晶矿洞以南，朱布瓦尔废墟东南方向，俯瞰着东面的大海。",al={"阿博拉兹位置","阿博拉兹在哪里","如何前往阿博拉兹废墟"}}},fp="15,297,23.525.0,18.425.1,35.167.0,44.199.0,38.165.0"}
P.entries["subzone:ruins-of-alterac"] = {n="奥特兰克废墟",s="白雪覆盖的奥特兰克废墟是奥特兰克王国的曾经那座引以为傲的山中都城——奥特兰克城的遗迹。在第二次战争期间，由于国王艾登·匹瑞诺德的背叛，这座城市被逐出了联盟并被实施了军事管制。如今，这片破败的堡垒已被粗野的碎颅食人魔所占据。",h="白雪覆盖的奥特兰克废墟是奥特兰克王国的曾经那座引以为傲的山中都城——奥特兰克城的遗迹。在第二次战争期间，由于国王艾登·匹瑞诺德的背叛，这座城市被逐出了联盟并被实施了军事管制。如今，这片破败的堡垒已被粗野的碎颅食人魔所占据...",kw={"奥特兰克城","布洛金","碎颅","穆戈尔","匹瑞诺德","奥特兰克废墟","斯坦恩布莱德","辛迪加"},ang={["faction:Horde"]="这座沦陷的城市是旧部落曾经结盟的遗响，但如今它也为被遗忘者提供了从分心的碎颅食人魔手中搜寻魔法圣物的机会。",["race:Human"]="对于联盟的人类来说，这些废墟是对第二次战争中人类软弱与叛国行为的沉重提醒，匹瑞诺德的懦弱曾摧毁了七大王国之间的手足情谊。"},sec={{t="王国的背叛",b="奥特兰克曾是一个从古老的阿拉索帝国中分裂出来的人类独立王国，坐落于穿越群山的贸易路线高处。在第二次战争期间，由于畏惧入侵的旧部落会带来毁灭，国王艾登·匹瑞诺德秘密与兽人达成了协议。当凯尔达隆的战斗结束后，他的背叛行径被揭露，洛丹伦联盟迅速展开了报复。泰瑞纳斯·米奈希尔二世国王对该城实施了军事管制，并废黜了匹瑞诺德。随着民众的逃离或沦为法外之徒，这座宏伟的防御工事、教堂和宫殿也逐渐荒废。"},{t="食人魔的占领",b="虽然幸存的奥特兰克贵族和流亡士兵组成了辛迪加，试图从斯坦恩布莱德等城镇发起游击战，但他们彻底失去了祖辈的都城。今天，穆戈尔率领的碎颅食人魔居住在破碎的城墙、宫殿大厅和残破的弩炮之间。无论是辛迪加还是南海镇的人类防御者，都没能收复这座沦陷的城市，这使得其坍塌的塔楼和废弃的拱顶成为了宝藏猎人和拾荒者眼中的险地。"}},faq={{q="奥特兰克为何会被摧毁？",a="在第二次战争期间，国王艾登·匹瑞诺德为了保全王国，与入侵的兽人部落结盟。洛丹伦联盟发现了这一叛国行为，攻占了奥特兰克城，拆除了其防御设施，并对该王国实施了军事管制。",al={"奥特兰克为什么成为废墟","奥特兰克城发生了什么","奥特兰克的陨落"}},{q="现在是谁住在废墟里？",a="由穆戈尔领导的碎颅食人魔已经接管了宫殿、城墙和积雪的庭院。此外，一名足智多谋的地精炼金商人布洛金正静静地坐在北面的城墙上。",al={"谁控制了奥特兰克废墟","奥特兰克食人魔","谁在奥特兰克"}},{q="辛迪加与这个地方有什么联系？",a="辛迪加主要由失去领土的前奥特兰克贵族和士兵组成，他们在王国解体后失去了家园。尽管他们痛心地渴望收复奥特兰克，但他们已被碎颅食人魔赶出了都城，目前在斯坦恩布莱德等前哨站活动。",al={"辛迪加住在这里吗","辛迪加与奥特兰克的联系"}},{q="联盟的冒险者为什么要来这里？",a="来自南海镇的联盟士兵会对袭击道路的敌对碎颅食人魔发布悬赏，而南方的贵族，例如雷明顿·瑞治维尔伯爵，也会派遣代理人进入废墟，寻找失落的家族传家宝，比如匹瑞诺德王冠。",al={"奥特兰克废墟的联盟任务","碎颅悬赏"}},{q="为什么部落对这些废墟感兴趣？",a="希尔瓦娜斯·风行者和被遗忘者对散落在沦陷人类王国各处的文物有着浓厚的兴趣，他们派遣勇士进入这个被食人魔占据的堡垒，以夺取诸如意志之冠之类的强大圣物。",al={"奥特兰克废墟的部落任务","希尔瓦娜斯奥特兰克"}}},fx={["46d22466"]={q="奥特兰克废墟是什么地方？",a="这些被冰雪覆盖的石墙和残破的雉堞，是奥特兰克城仅存的遗迹。它曾是人类王国奥特兰克引以为傲的山地都城。阿拉索扩张之后数千年，这座城市建立起来，守护着蜿蜒穿过群山的重要贸易路线；直到国王的背叛在第二次战争期间招致了它的覆灭。",al={"奥特兰克废墟是什么","奥特兰克废墟概况","奥特兰克城"}},["967fd086"]={q="第二次战争期间奥特兰克城发生了什么？",a="第二次战争期间，艾登·匹瑞诺德国王与入侵的兽人部落秘密结盟，以保全自己的领土。当洛丹伦联盟发现奥特兰克的叛变后，联盟军队进军这座山地王国，夷平了都城，并对残存地区实行戒严。匹瑞诺德被废黜并遭到唾弃，随后入狱，王国也因此支离破碎、沦为废墟。",al={"奥特兰克城历史","奥特兰克发生了什么","奥特兰克的覆灭"}},fd0078c8={q="奥特兰克废墟有多危险？",a="对毫无准备的人来说极其危险。碎脊食人魔占据了积雪覆盖的街道和破败的大厅，凶狠地抵御任何闯入其领地的人。雪上加霜的是，冷酷无情的辛迪加和游荡的亡灵有时也会出现在废墟中，使山间隘口危机四伏，随时可能遭到伏击。",al={"奥特兰克废墟危险吗","奥特兰克废墟的威胁","奥特兰克城的危险"}},fbcb07c6={q="这个地方为什么叫奥特兰克废墟？",a="此地因曾经矗立于此的人类古王国及城市奥特兰克而得名。王国解体、都城在第二次战争期间遭到严重摧毁后，宏伟的首都只剩下开裂的石墙、破碎的大门和坍塌的高塔，昔日强盛的权力中心就此沦为一片废墟。",al={"为何称为奥特兰克废墟","奥特兰克废墟名称由来"}}},fp="16,313,20.584.0,19.495.0,26.242.0,27.204.0,49.291.0,38.248.0,43.234.0"}
P.entries["subzone:ruins-of-andorhal"] = {n="安多哈尔废墟",s="安多哈尔废墟曾是洛丹伦北部农业中心和谷物配送枢纽，如今位于西瘟疫之地的中心地带，是一座满目疮痍的亡灵天灾据点。在巫妖阿拉基的统治下，这座支离破碎的城镇中爬满了大批的亡灵憎恶、食尸鬼和幽灵。",h="安多哈尔废墟曾是洛丹伦北部农业中心和谷物配送枢纽，如今位于西瘟疫之地的中心地带，是一座满目疮痍的亡灵天灾据点。在巫妖阿拉基的统治下，这座支离破碎的城镇中爬满了大批的亡灵憎恶、食尸鬼和幽灵。",kw={"andorhal","阿拉基","克罗米","谷仓","天灾军团","时间寄生虫","西瘟疫之地"},ang={["class:Paladin"]="对于白银之手骑士团和联盟各地的圣骑士来说，安多哈尔是一片沦为梦魇的圣地——正是这里，受污染的谷物毒害了洛丹伦的粮仓，注定了北方王国的覆灭。",["race:Undead"]="被遗忘者旅行者以沉痛的心情看待这座废墟城市：今天许多行走在幽暗城中的人，曾经都是洛丹伦的公民，他们当年都曾食用过从这些周边田地收割的受污染谷物。"},sec={{t="瘟疫之心",b="安多哈尔是洛丹伦亡灵瘟疫最初的集结地，The Cult of the Damned在此包装受污染的谷物并分发到人类王国的各个角落。如今，这座废墟城市是天灾军团在西瘟疫之地的一座庞大堡垒。巫妖阿拉基坐镇废墟中央，周围环绕着食尸鬼、骸骨恐怖怪和高大的血肉傀儡。血色十字军的侦察小队会定期试探城市的边缘，但天灾军团依然牢牢控制着这些残破的街道。"},{t="时间的纠葛",b="Beyond the physical presence of the undead, Andorhal suffers from peculiar temporal anomalies. The town hall clock and discarded pocket watches scattered through the streets remain perpetually stopped at three o'clock. The bronze dragon Chromie, sheltering in the inn on the edge of the ruins, investigates temporal parasites nesting within the grain silos. Scourge forces appear to be meddling with the flow of time itself, attempting to alter the timeline of the city's tragic downfall."}},faq={{q="谁统治着安多哈尔废墟？",a="这座废墟由强大的巫妖阿拉基统治，他负责协调该地区天灾军团的行动。他居住在城市中心，身边有精锐的骸骨守卫和血肉构造体护卫。",al={"谁领导安多哈尔","安多哈尔首领","阿拉基"}},{q="为什么克罗米在废墟里？",a="克罗米化身为一名侏儒女性，正在调查时间线上的异常干扰。她怀疑城市粮仓周围存在干涉行为，并请求旅行者协助调查。",al={"克罗米在安多哈尔做什么","克罗米为什么在这里","克罗米 安多哈尔"}},{q="为什么所有的时钟都停在三点钟？",a="市政厅的时钟和在废墟中发现的个人怀表都停在了三点钟。这可能与安多哈尔的时间异常有关，但确切原因尚无法证实。",al={"三点钟的怀表","安多哈尔时钟冻结","为什么停在三点"}},{q="为什么血色十字军要攻击安多哈尔？",a="由血色医疗兵、猎人和祈求者组成的小型突击队试图渗透这座城市。狂热的十字军试图收复洛丹伦并消灭天灾军团，但他们对中心要塞的进犯鲜有成功。",al={"安多哈尔的血色十字军","血色巡逻队 安多哈尔"}}},fp="17,325,19.543.0,15.488.1,32.212.0,32.185.0,48.193.0,45.245.0"}
P.entries["subzone:ruins-of-constellas"] = {n="克斯特拉斯废墟",s="克斯特拉斯废墟是位于费伍德森林的一处古代暗夜精灵定居点的破碎残迹，坐落在海加尔山脚下。如今，这片曾经神圣的土地已被翡翠之火萨特占领，他们用邪恶的邪能魔法粗暴地亵渎了此地的月亮井。",h="克斯特拉斯废墟是位于费伍德森林的一处古代暗夜精灵定居点的破碎残迹，坐落在海加尔山脚下。如今，这片曾经神圣的土地已被翡翠之火萨特占领，他们用邪恶的邪能魔法粗暴地亵渎了此地的月亮井。",kw={"克斯特拉斯","费伍德森林","翡翠之火","月亮井","萨特","萨瓦里克","萨瓦瑟拉斯"},ang={["class:Druid"]="曾经神圣的月亮井如今却由恶魔照看，克斯特拉斯成为了德鲁伊誓言恢复费伍德森林平衡的一个鲜明提醒。",["race:NightElf"]="克斯特拉斯的亵渎及其受污染的月亮井是对艾露恩的极大冒犯，这要求暗夜精灵必须驱逐翡翠之火萨特。"},sec={{t="亵渎的圣所",b="克斯特拉斯那些古典的石拱门和崩塌的广场显示，这里曾经是一个田园诗般的暗夜精灵社区。第三次战争期间，燃烧军团进军费伍德森林，摧毁了这个避风港，使其暴露在挥之不去的恶魔腐蚀之下。现在，邪恶的翡翠之火萨特统治着这片废墟。在萨瓦瑟拉斯的领导下，他们积极照料着一口被亵渎的月亮井，为了他们的主人萨瓦里克领主，将纯净的井水转化成了散发着邪能之力的毒泉。"},{t="净化的抗争",b="克斯特拉斯的腐化让所有致力于治愈费伍德森林的人感到沉重。对于那些试图净化森林的人来说，萨瓦瑟拉斯和他的翡翠之火是最令人作呕的腐化者之一。萨特们在废墟的营帐中以及处于核心位置的被污染的月亮井旁严加防守，对抗任何试图终结他们恶行的人。"}},faq={{q="被腐化之前的克斯特拉斯是什么样的地方？",a="克斯特拉斯是海加尔山脚下的一处古代暗夜精灵定居点。其建筑风格和月亮井表明，在第三次战争期间燃烧军团入侵森林之前，这里曾是一个致力于供奉艾露恩与自然的宁静林地。",al={"克斯特拉斯历史","克斯特拉斯过去是什么","谁建造了克斯特拉斯"}},{q="现在谁控制着废墟？",a="废墟目前被翡翠之火萨特占据，由萨瓦瑟拉斯在当地负责指挥。在萨瓦里克领主的总体命令下，他们在这片区域培养着恶魔能量。",al={"谁居住在这里","谁统治克斯特拉斯","翡翠之火萨特克斯特拉斯"}},{q="克斯特拉斯的月亮井发生了什么？",a="月亮井被翡翠之火萨特夺取，并被邪能魔法腐蚀。它不再引导艾露恩的抚慰祝福，而是被扭曲成了一个由萨瓦瑟拉斯所培育的、充满邪能的毒源。",al={"费伍德森林受污染的月亮井","克斯特拉斯月亮井","为什么井是绿色的"}},{q="萨瓦里克是谁？",a="萨瓦里克是翡翠之火中另一名残暴的萨特，也是萨瓦瑟拉斯效忠的对象。克斯特拉斯被腐蚀的月亮井就是为了他而培育的。",al={"萨瓦里克","萨瓦瑟拉斯效忠于谁"}}},fp="19,281,19.479.0,26.313.0,42.240.0,27.172.0,44.210.0,15.143.0"}
P.entries["subzone:ruins-of-eldarath"] = {n="埃达拉斯废墟",s="埃达拉斯废墟是位于艾萨拉崎岖峭壁上的一座上古之战前的上层精灵城市，如今已是残垣断壁。它曾是卡多雷奥术研究的堡垒，而现在，它那坍塌的广场和破败的神殿已被充满敌意的纳迦所占据。学者和冒险者们勇敢地深入这片危险的海岸废墟，寻找着古代刻写的石板和遗失的远古圣物。",h="埃达拉斯废墟是位于艾萨拉崎岖峭壁上的一座上古之战前的上层精灵城市，如今已是残垣断壁。它曾是卡多雷奥术研究的堡垒，而现在，它那坍塌的广场和破败的神殿已被充满敌意的纳迦所占据。学者和冒险者们勇敢地深入这片危险的海岸废墟，寻找...",kw={"艾萨拉","艾索雷葛斯","埃达拉斯","探险者协会","上层精灵","卡多雷","纳迦","大分裂","石板"},ang={["class:Mage"]="埃达拉斯是一个神圣但又充满警示意义的研究场所：散布在广场上的石板记载了最有天赋的上层精灵法师在帝国覆灭前刻下的奥术基础理论。",["race:NightElf"]="这些被阳光晒白的废墟是对上层精灵傲慢和大分裂的痛苦提醒，它们长期被现代卡多雷所回避，如今又遭到了扭曲的纳迦的亵渎。"},sec={{t="破碎的上层精灵堡垒",b="在一万年前大分裂彻底摧毁古代卡利姆多之前，埃达拉斯曾是一座繁荣的暗夜精灵城市。著名的上层精灵法师们曾聚集于此，将他们最深奥的奥术见解和基础魔法准则刻在大型石板上，放置在公共广场供同僚们研习。大分裂使埃达拉斯的大部分沉入了风暴海湾。残留在东部悬崖上的部分在数千年来一直被现代暗夜精灵所摒弃，逐渐被蔓延的海盐喷雾和常春藤所侵蚀。"},{t="纳迦的统治与遗忘的圣物",b="近来，凶残的纳迦从海中涌出，夺取了埃达拉斯残破的街道，并在辛玛洛神殿等附近的圣所中由潜伏的军阀指挥。尽管蛇人构成了威胁，但废墟对外界来说仍然有着不可抗拒的吸引力。探险者协会已经派遣联盟冒险者进入断壁残垣的庭院，拓印埃达拉斯古老的奥术石板。关于失落宝藏和残留奥术能量的传言也吸引了蓝龙艾索雷葛斯来到周边的荒野，这进一步证实了巨大的力量之秘仍沉睡在废墟的碎石板之下。"}},faq={{q="埃达拉斯在化为废墟之前是什么样子？",a="在一万年前的大分裂之前，埃达拉斯是一座由上层精灵居住的宏伟暗夜精灵城市。在世界大分裂将其摧毁之前，它曾是奥术研究的中心和坚固的避风港。",al={"埃达拉斯是什么","埃达拉斯历史","埃达拉斯起源"}},{q="如今谁在控制埃达拉斯废墟？",a="充满敌意的纳迦已经彻底占领了这片废墟，利用坍塌的广场和附近的建筑（如辛玛洛神殿）作为海岸据点，并在像克雷利安军阀这样的头目指挥下进行活动。",al={"谁住在埃达拉斯","埃达拉斯里有什么","埃达拉斯怪物"}},{q="为什么学者和探险者要前往埃达拉斯？",a="学者们致力于寻找古代上层精灵法师留下的保存完好的石板。这些公共标记包含了奥术魔法的基础准则和失传已久的研究，其价值之高，使得矮人探险者协会等组织派遣侦察兵去获取这些文本的拓片。",al={"为什么要前往埃达拉斯","埃达拉斯任务","埃达拉斯有什么"}},{q="为什么蓝龙艾索雷葛斯会在废墟附近徘徊？",a="艾索雷葛斯被艾萨拉海岸边残留的极高浓度的远古奥术能量所吸引。有传言称，大分裂之前的强大圣物——甚至可能包括接触过远古永恒之井的瓶子——仍然隐藏在废墟之中或周围。",al={"为什么艾索雷葛斯在这里","艾索雷葛斯埃达拉斯","艾萨拉的蓝龙"}}},fp="17,377,29.520.0,30.642.0,44.225.0,41.200.0,49.275.0,55.266.0"}
P.entries["subzone:ruins-of-isildien"] = {n="伊斯迪尔废墟",s="伊斯迪尔废墟是菲拉斯西南部一座古老的暗夜精灵城市的庞大遗迹，在一万年前的大分裂期间被摧毁。如今，那些杂草丛生的石造建筑和开裂的神殿庭院已被残暴的戈杜尼食人魔所占据。",h="伊斯迪尔废墟是菲拉斯西南部一座古老的暗夜精灵城市的庞大遗迹，在一万年前的大分裂期间被摧毁。如今，那些杂草丛生的石造建筑和开裂的神殿庭院已被残暴的戈杜尼食人魔所占据。",kw={"艾露恩","菲拉斯","戈杜尼","伊斯迪尔","卡多雷","食人魔","大分裂","temple of the moon"},ang={["class:Priest"]="位于顶部的宏伟圆形大厅与艾露恩的高级圣所建筑布局相同，回荡着一万年前向白夫人献上的祈祷声。",["race:NightElf"]="走在伊斯迪尔，不仅能让人回想起分裂前帝国那令人痛苦的辉煌高度，如今它已沦为废墟，并被野蛮的戈杜尼食人魔所亵渎。"},sec={{t="一座陨落的卡多雷城市",b="一万年前，在世界破碎之前，伊斯迪尔是坐落在古代卡利姆多原始森林中的一座宏伟的暗夜精灵定居点。它优雅的大理石拱门和宏伟的露台曾是卡多雷文明和信仰的纪念碑。当永恒之井崩塌并将大陆撕裂时，伊斯迪尔陷入了荒废，被数千年来野蛮生长的丛林所覆盖。主宰着上层露台的是一座巨大的圆顶建筑，与达纳苏斯的Temple of the Moon惊人地相似，这表明这座城市曾经是一处供奉艾露恩的重要圣所。"},{t="戈杜尼要塞",b="在现代，伊斯迪尔优雅的石造建筑被用于远为粗鄙的用途。菲拉斯的戈杜尼食人魔已将这些庞大的露台和岩层据为己有，作为他们的主要定居点之一。食人魔加固了摇摇欲坠的走道，用粗糙的篝火、原始的障碍物和战旗亵渎了古老的广场，凶猛地保卫着他们窃取的家园，抵御任何胆敢靠近南部山丘的外来者。"}},faq={{q="伊斯迪尔最初是什么？",a="伊斯迪尔是一座重要的大型暗夜精灵城市，建于一万年前大分裂之前。在灾变使其成为废墟之前，它拥有宏大的石砌广场、多层露台和显赫的神殿。",al={"什么是伊斯迪尔","伊斯迪尔历史","谁建造了伊斯迪尔"}},{q="现在是谁控制着伊斯迪尔废墟？",a="这些废墟已被戈杜尼食人魔占领并加固，他们利用破败的大理石大厅和天然的地理优势，将其作为在菲拉斯南部的一处要塞。",al={"谁住在伊斯迪尔","伊斯迪尔的敌人","伊斯迪尔的食人魔"}},{q="楼梯顶部的大型圆形亭子是什么？",a="那座显眼的圆形亭子在建筑结构上与达纳苏斯的Temple of the Moon极为相似，这有力地表明上面的高台曾经是供奉艾露恩的圣洁殿堂。",al={"伊斯迪尔神殿","伊斯迪尔的圆形建筑","菲拉斯的艾露恩神殿"}},{q="废墟里有什么隐藏的东西吗？",a="在废墟东侧的悬崖上嵌有一个洞穴，当地的食人魔除了利用北部和南部的分散石质露台外，也会使用这个洞穴。",al={"伊斯迪尔洞穴","伊斯迪尔的秘密"}}},fp="17,260,29.600.0,23.441.0,29.214.0,39.159.0,61.207.0,42.170.0"}
P.entries["subzone:ruins-of-jubuwal"] = {n="朱布瓦尔废墟",s="朱布瓦尔废墟是古拉巴什帝国古老定居点的残垣断壁，位于荆棘谷的古拉巴什竞技场以东。这里曾是帝国和举行仪式的场所，如今却已被流亡巫医赞吉尔及其稀奇古怪的爪牙所控制。",h="朱布瓦尔废墟是古拉巴什帝国古老定居点的残垣断壁，位于荆棘谷的古拉巴什竞技场以东。这里曾是帝国和举行仪式的场所，如今却已被流亡巫医赞吉尔及其稀奇古怪的爪牙所控制。",kw={"古拉巴什","琼琼","朱布瓦尔","麦金利","瘸腿莫里","荆棘谷","赞吉尔"},ang={["class:Rogue"]="朱布瓦尔的阴影和破碎的砖石建筑为躲避来自藏宝海湾的赏金猎人的逃犯提供了绝佳的掩护。",["race:Troll"]="对于暗矛巨魔来说，朱布瓦尔既代表了古拉巴什文明悲剧性的崩溃，也代表了像赞吉尔这样的恶棍对祖传巫毒法术的扭曲和亵渎。"},sec={{t="流亡者的避难所",b="朱布瓦尔坐落在穿过荆棘谷的主干道旁，曾是宏伟的古拉巴什文明的一部分。如今，这里的石刻和藤蔓缠绕的砖石建筑已被赞吉尔占据。这位古怪的巫医以其强大的药剂和邪恶的巫毒法术而闻名。赞吉尔在废墟中聚集了一群非自然的追随者，包括被奴役的食尸鬼、被征服的纳迦以及背叛的巨魔。在石拱门之间还潜伏着绝望的逃亡者，例如“乌鸦”琼琼和“瘸腿”莫里，他们都是为了躲避藏宝海湾那位冷酷无情的债务催收人“海狼”麦金利而藏匿于此。"}},faq={{q="朱布瓦尔废墟在哪里？",a="这些废墟位于荆棘谷中部，古拉巴什竞技场以东，紧邻连接荆棘谷北部和南部的主要土路。",al={"朱布瓦尔废墟位置","朱布瓦尔在哪","朱布瓦尔地图"}},{q="谁控制着朱布瓦尔废墟？",a="废墟由流亡者赞吉尔及其爪牙把持。他那折中主义的追随者包括被洗脑的巨魔、复活的食尸鬼、结盟的纳迦以及各类寻求庇护以逃避外界法律制裁的恶棍。",al={"朱布瓦尔的居民","朱布瓦尔敌人","谁控制朱布瓦尔"}},{q="为什么食尸鬼和纳迦会在这里合作？",a="流亡者赞吉尔使用有毒的巫毒混合物和致幻药剂来征服并指挥周围的人。通过这些混合药剂，他将复活的亡灵、纳迦和巨魔束缚成一支听命于他的战斗力量。",al={"朱布瓦尔的食尸鬼","赞吉尔的爪牙"}},{q="为什么像琼琼和莫里这样的逃犯要躲在这里？",a="“乌鸦”琼琼和“瘸腿”莫里都逃到了朱布瓦尔，以躲避臭名昭著的债务催收人“海狼”麦金利的愤怒，麦金利就在藏宝海湾活动。",al={"乌鸦琼琼","瘸腿莫里","麦金利的债务人"}}},fp="16,299,23.628.0,39.172.0,34.203.0,46.208.0,51.167.0"}
P.entries["subzone:ruins-of-kel-theril"] = {n="凯斯利尔废墟",s="凯斯利尔废墟是古老暗夜精灵城市留下的破碎残骸，坐落于冬泉谷中心地带的凯斯利尔湖冰封湖畔。这座城市在万年前的大分裂中被摧毁，其冰冻的石柱和神庙至今仍被在大灾变中丧生的上层精灵那痛苦的灵魂所萦绕。",h="凯斯利尔废墟是古老暗夜精灵城市留下的破碎残骸，坐落于冬泉谷中心地带的凯斯利尔湖冰封湖畔。这座城市在万年前的大分裂中被摧毁，其冰冻的石柱和神庙至今仍被在大灾变中丧生的上层精灵那痛苦的灵魂所萦绕。",kw={"幽灵","上层精灵","凯斯利尔","凯斯利尔湖","废墟","大分裂","冬泉谷"},ang={["class:Mage"]="探索废墟的法师们会感受到那些古老而沉寂的奥术能量，这些能量曾经支撑着卡利姆多在大分裂前最引以为傲的魔法城市之一。",["race:NightElf"]="对于暗夜精灵来说，凯斯利尔是一个庄严的提醒，警示着古老上层精灵阶级的傲慢，以及他们因肆意使用奥术魔法所造成的可怕破坏。"},sec={{t="破碎的遗产",b="早在冬泉谷变成冰封高地之前，凯斯利尔曾是古老暗夜精灵帝国的一座宏伟定居点。当永恒之井在大分裂期间崩塌时，这座城市被炸成废墟，并埋葬在冰雪之下。这场灾难让当时居住于此的上层精灵猝不及防，将他们的灵魂束缚在冰冷的岩石上。如今，这些昔日施法者的灵魂徘徊在冰封的拱门之间，无休止地重温着他们生命中那灾难般的最后时刻。"},{t="雪中的回响",b="勇闯冬泉谷中心的旅行者经常会遇到在废墟湖畔游荡的、不安的幽灵上层精灵。这些幻影通常带有敌意，被数千年的孤独和撕裂了他们文明的狂暴魔法逼至疯狂。然而，少数悲伤的幽灵，例如悔恨的上层精灵，会寻找愿意倾听他们长久哀鸣并抚平他们被遗忘的往事的旅行者。"}},faq={{q="凯斯利尔城发生了什么事？",a="凯斯利尔在万年前的大分裂期间被摧毁。当永恒之井内爆并撕裂了古老的卡利姆多大陆时，这座城市坍塌成了瓦砾，并被随后笼罩冬泉谷的突如其来的严寒所吞没。",al={"凯斯利尔历史","凯斯利尔为何荒废","凯斯利尔如何陷落"}},{q="什么灵魂萦绕着这些废墟？",a="这些废墟被在大分裂中丧生的上层精灵暗夜精灵的幽灵所萦绕。他们的灵魂依然被束缚在倒塌的石头上，在痛苦中挣扎，徘徊在凯斯利尔湖的雪地边缘。",al={"凯斯利尔幽灵","谁在凯斯利尔游荡","凯斯利尔亡灵"}},{q="你能与这些幽灵交谈吗？",a="虽然大多数徘徊的灵魂都充满敌意且陷入疯狂，但在废墟中仍能找到一个孤独的悔恨的上层精灵，他愿意与那些试图了解这里悲惨往事的联盟旅行者交谈。",al={"友好的凯斯利尔幽灵","悔恨的上层精灵","凯斯利尔幽灵任务"}},{q="废墟位于何处？",a="凯斯利尔废墟位于凯斯利尔湖的岸边，这是一座坐落在冬泉谷中心地带的冰封湖泊。",al={"凯斯利尔位置","凯斯利尔在哪里","寻找凯斯利尔"}}},fp="19,341,18.488.0,18.422.0,40.267.0,31.226.0,37.216.0,28.133.0"}
P.entries["subzone:ruins-of-lordaeron"] = {n="洛丹伦废墟",s="洛丹伦废墟是王都地表上留下的残骸，这里曾是人类北方帝国光辉荣耀的核心。当阿尔萨斯王子弑父并释放天灾军团后，这里便遭到了毁灭，如今那被摧毁的庭院和大厅已成为下方幽暗城的防御门户。",h="洛丹伦废墟是王都地表上留下的残骸，这里曾是人类北方帝国光辉荣耀的核心。当阿尔萨斯王子弑父并释放天灾军团后，这里便遭到了毁灭，如今那被摧毁的庭院和大厅已成为下方幽暗城的防御门户。",kw={"阿尔萨斯","王都","闹鬼","洛丹伦","宫殿","天灾军团","sylvanas","泰瑞纳斯","大厅","幽暗城"},ang={["race:Human"]="站在这座大厅里，是对人类历史上最大背叛的痛苦提醒，阿尔萨斯王子摧毁了洛丹伦联盟，并将人类的明珠交到了亡者手中。",["race:Undead"]="这些破败的城墙是你的祖居之地。曾经孕育你的生者王国如今已成为守护幽暗城和女妖之王的圣地门户。"},sec={{t="陨落帝国的门户",b="王都曾是人类文明璀璨的巅峰，在泰瑞纳斯·米奈希尔二世国王的统治下统一了北方诸国。当阿尔萨斯王子带着被诅咒的符文剑“霜之哀伤”从诺森德归来时，庆祝仪式变成了屠宰场。阿尔萨斯在王座上杀死了他的父亲，这座大都市随之在天灾军团的统治下腐朽。在分裂天灾军团的内战之后，Sylvanas Windrunner占据了这座被摧毁的宫殿，在巩固地表防御的同时，将下方的地窖和地下城扩建为幽暗城。"},{t="背叛的回响",b="宫殿废墟因那场暴力的陷落而留下了心灵创伤。路过入口和庭院的旅行者常会听到庆祝钟声的幽灵回响、欢呼人群的低语，以及阿尔萨斯在弑父前与国王那令人毛骨悚然的对话。大厅的地面上仍留有血迹，而那些拥有魔法感知能力的人，可以看到幽灵般的市民在不断重现王子断送他们生命的那天下午。"}},faq={{q="为什么我在穿过入口时会听到钟声和低语？",a="泰瑞纳斯国王及其城市的突然屠杀在这些石头上留下了心灵印记。任何穿过外门和残破大厅的人都能听到跨越时空的幽灵钟声、虚幻的欢呼声，以及泰瑞纳斯与阿尔萨斯之间的最后对话。",al={"洛丹伦诡异声音","大厅低语","闹鬼城堡声音"}},{q="如今是谁统治着这些废墟？",a="地表废墟由Sylvanas Windrunner麾下的被遗忘者所占据和巡逻。尽管Sylvanas和她的廷臣居住在下方的幽暗城中，但上方的废墟仍是通往她地下国度的宏伟要塞入口。",al={"谁拥有洛丹伦废墟","谁控制洛丹伦废墟"}},{q="曾经居住在这里的人们发生了什么？",a="大多数居民在阿尔萨斯向城市释放天灾军团时被屠杀。许多人被复活为无脑的亡灵，后来挣脱束缚加入了Sylvanas成为被遗忘者，而另一些人的无形之魂依然在宫殿庭院中游荡。",al={"洛丹伦人民去了哪里","王都人类发生了什么"}},{q="大厅里的黑色污渍是什么？",a="标记在王座台阶上的深色干燥残留物是泰瑞纳斯·米奈希尔二世国王的鲜血，当王子将霜之哀伤刺入他心口时，这些鲜血从他体内流出。",al={"大厅地板上的血迹","洛丹伦大厅的污渍"}}},fx={d8b1c653={q="洛丹伦废墟是什么地方？",a="这些破碎的城墙和宏伟大厅，是首都城仅存的遗迹。首都城曾是已覆灭的人类王国洛丹伦的壮丽中心，也是第二次战争期间联盟的核心。王子阿尔萨斯·米奈希尔背叛王国、释放天灾军团后，这座城市便陷入崩塌。如今，地表宫殿已破败不堪、阴魂不散，成为通往庞大的被遗忘者地下都市——幽暗城的入口。",al={"洛丹伦废墟是什么","洛丹伦废墟概况","首都城废墟传说"}},b22541a4={q="洛丹伦为何沦为废墟？",a="洛丹伦毁于内部的背叛。王储阿尔萨斯·米奈希尔被受诅咒的霜之哀伤腐化后，以巫妖王的旗号从诺森德归来。他杀死父亲泰瑞纳斯国王后，与他的亡灵天灾军团屠杀了城中居民，摧毁了城市的防御。此后，恐惧魔王、幸存的联盟抵抗军以及希尔瓦娜斯·风行者领导的被遗忘者之间的冲突，彻底毁掉了这座地表城市。",al={"洛丹伦为何被毁","洛丹伦是如何被毁的","洛丹伦为何沦为废墟"}},e6ebc4a5={q="洛丹伦废墟危险吗？",a="对部落勇士而言，地表废墟十分安全，被遗忘者卫兵会巡逻庭院以及通往幽暗城的通道。然而，联盟旅者会发现这里敌意十足，到处都是被遗忘者哨兵。此地也阴气沉沉，回荡着悲惨的幽灵低语和被屠杀居民的无形鬼魂；周围的提瑞斯法林地还有邪恶的天灾生物和野兽四处出没。",al={"洛丹伦废墟的危险","洛丹伦废墟安全吗","洛丹伦废墟是否敌对"}},["39a2d118"]={q="为什么称为洛丹伦废墟？",a="此地最初是首都城，是洛丹伦王国的宏伟中心。天灾军团彻底毁灭王国并屠杀其人民后，只剩下开裂的大理石墙、破碎的王座大厅和坍塌的庭院。这个名称旨在铭记人类北方最强大王国昔日的辉煌及其悲惨覆灭。",al={"洛丹伦废墟名称由来","为何称为洛丹伦废墟","洛丹伦废墟名称从何而来"}}},fp="18,306,25.542.0,18.474.0,67.269.0,26.238.0,50.260.0,42.171.0"}
P.entries["subzone:ruins-of-mathystra"] = {n="玛塞斯特拉废墟",s="玛塞斯特拉废墟是一座古老暗夜精灵城市的残垣断壁，坐落于黑海岸的北岸。这座沿海废墟在一万年前的大分裂中被摧毁，如今已被充满敌意的风鳞娜迦所占据，并有难以捉摸的幽灵豹在此潜行。",h="玛塞斯特拉废墟是一座古老暗夜精灵城市的残垣断壁，坐落于黑海岸的北岸。这座沿海废墟在一万年前的大分裂中被摧毁，如今已被充满敌意的风鳞娜迦所占据，并有难以捉摸的幽灵豹在此潜行。",kw={"黑海岸","幽灵豹","大分裂","上层精灵","玛塞斯特拉","娜迦","玛塞斯特拉废墟","风鳞"},ang={["class:Hunter"]="在玛塞斯特拉的瓦砾中潜行的半透明幽灵豹，对于追求与灵魂世界有联系且外形引人注目的伙伴的兽王猎人来说，是著名的野兽。",["race:NightElf"]="玛塞斯特拉是古老上层精灵傲慢的阴沉纪念碑，他们鲁莽的魔法为自己宏伟的沿海定居点带来了毁灭性的灾难。"},sec={{t="一座沉入海底的城市",b="一万年前，玛塞斯特拉曾是一处繁华的暗夜精灵定居点，也是高阶上层精灵贵族的家园。当永恒之井在大分裂期间崩塌时，灾难性的巨浪摧毁了这座沿海城市，推倒了宏伟的大理石拱门，并将大部分石建筑冲入了海中。幸存的暗夜精灵放弃了这座残破的城市，转而前往更南方的林地村庄居住，将玛塞斯特拉沉没的庭院和破裂的地基留给了无情的海岸风化。"},{t="风鳞毒蛇与幽灵豹",b="在现代，玛塞斯特拉已成为风鳞娜迦统治的危险领地。这些蛇形怪物从深暗的海底爬出，凶狠地守卫着破碎的厅堂，驱逐任何越过奥萨拉克斯之塔向北冒险的旅行者。在破碎的石板间，古老的上层精灵遗物依然半埋在沙砾与海沫中。大胆的年轻暗夜精灵有时会冒着生命危险闯入娜迦的地盘，希望能寻回他们失落的遗产。他们不仅要面对蛇人的利刃，还要应对潜伏在破败街道上的幽灵豹。"}},faq={{q="在废墟之前这里是什么？",a="玛塞斯特拉是一座繁荣的暗夜精灵城市，兴建于古老上层精灵帝国鼎盛时期。一万年前，当永恒之井爆炸并撕裂卡利姆多大陆的大分裂期间，这座城市被摧毁并大部沉入水中。",al={"玛塞斯特拉历史","谁建造了玛塞斯特拉","玛塞斯特拉是什么"}},{q="现在是谁控制着玛塞斯特拉废墟？",a="这片废墟目前被风鳞娜迦占据，它们从海中涌出，占据了沉没的亭台楼阁和海岸线。它们会猛烈攻击任何侵入其领地的陆地居民。",al={"谁住在玛塞斯特拉","玛塞斯特拉怪物","玛塞斯特拉有哪些人"}},{q="什么是幽灵豹？",a="幽灵豹是一种虚幻且半透明的猫科生物，徘徊在玛塞斯特拉的残垣断壁间。猎人们经常在海岸边寻找它们，不过据称干扰该地区的古代雕像会将这些灵魂从阴影中引出。",al={"玛塞斯特拉幽灵豹","黑海岸发光的猫","幽灵豹"}},{q="为什么暗夜精灵今天会造访这些废墟？",a="年轻的暗夜精灵和学者偶尔会冒险进入废墟，寻找大分裂后遗留下的古代上层精灵遗物。然而，凶猛的风鳞娜迦的存在使得找回这些历史珍宝变得异常危险。",al={"玛塞斯特拉遗物","为什么要前往玛塞斯特拉"}}},fx={b3a23ce3={q="玛塞斯特拉废墟是什么地方？",a="玛塞斯特拉废墟是一座古老的暗夜精灵城市遗迹，坐落在黑海岸北部海岸线上，位于奥萨拉克斯之塔稍远处。这座城市曾是上层精灵文明的宏伟中心，如今只剩下饱经风霜的石质地基、破碎的石柱，以及被荒野吞没、长埋地下的遗物。",al={"玛塞斯特拉是什么","玛塞斯特拉废墟传说","玛塞斯特拉废墟简介"}},f1593a2d={q="玛塞斯特拉为何沦为废墟并被遗弃？",a="一万年前，永恒之井灾变性的崩塌撕裂了古代卡利姆多，玛塞斯特拉在大分裂期间遭到重创。这座城市被这场大灾变摧毁，幸存的暗夜精灵选择彻底放弃这片破碎的废墟，转而迁居到更南方的沿海避难所。",al={"玛塞斯特拉为何沦为废墟","是什么摧毁了玛塞斯特拉","玛塞斯特拉是如何被毁的"}},["2087f816"]={q="玛塞斯特拉废墟危险吗？",a="是的，在这些石块间行动时务必小心。风鳞纳迦牢牢占据着废墟，凶狠地抵御任何试图闯入其所占海岸的外来者。除了这些蛇形入侵者，飘忽的幽灵豹和古代上层精灵魔法的残余也徘徊在废墟各处。",al={"玛塞斯特拉安全吗","玛塞斯特拉的威胁","玛塞斯特拉废墟的危险"}}},fp="18,285,24.507.0,38.584.0,38.249.0,46.209.0,22.242.0,43.247.0"}
P.entries["subzone:ruins-of-ordil-aran"] = {n="奥迪拉兰废墟",s="奥迪拉兰废墟是位于灰谷西北部的一处古老暗夜精灵定居点的残垣断壁，坐落在迈斯特拉岗哨和巴斯兰鬼屋之间。这里曾是暗影教徒的隐秘堡垒，但如今这些倾颓的石块已被腐化的蓟皮熊怪占据。",h="奥迪拉兰废墟是位于灰谷西北部的一处古老暗夜精灵定居点的残垣断壁，坐落在迈斯特拉岗哨和巴斯兰鬼屋之间。这里曾是暗影教徒的隐秘堡垒，但如今这些倾颓的石块已被腐化的蓟皮熊怪占据。",kw={"灰谷","暗滩教派","心木","迈斯特拉岗哨","奥迪拉兰","废墟","蓟皮熊怪"},ang={["faction:Alliance"]="奥迪拉兰的那些好战占据者位于迈斯特拉岗哨以北，威胁着前往黑海岸的联盟侦察兵和旅行者。",["race:NightElf"]="这些废墟是卡利姆多帝国崩溃的又一个痛苦缩影，如今又遭到了腐化的熊怪和黑暗教徒的玷污。"},sec={{t="一处争议废墟",b="奥迪拉兰只剩下少量最初的卡多雷建筑，仅存风化的石柱、开裂的拱门和布满青苔的石雕。这片孤立的废墟曾一度成为暗滩教派的巢穴，他们潜伏在瓦砾之中，伏击灰谷西北道路上的旅行者。然而最近，凶残的蓟皮熊怪部落通过一场血腥的夺取行动将教徒们赶了出去。暗滩教派成员的尸体横尸遍地，而好战的熊怪则在四周巡逻，严密守卫着这处遗迹和生长在其中的古老心木。"}},faq={{q="奥迪拉兰最初是什么地方？",a="奥迪拉兰是一处大分裂之前的古老暗夜精灵定居点。和灰谷中许多其他的卡多雷前哨站一样，它在漫长的岁月中逐渐荒废，只留下了杂草丛生的石拱门和摇摇欲坠的砖石。",al={"奥迪拉兰历史","奥迪拉兰是什么","谁建造了奥迪拉兰"}},{q="为什么废墟里有死去的教徒？",a="暗滩教派此前曾将这些废墟用作行动基地。蓟皮熊怪发动了猛烈攻击并驱逐了他们，占领了这片废墟，留下了横尸遍地的教徒。",al={"死去的教徒","暗滩教派尸体","为什么教徒死在这里"}},{q="什么是心木？",a="心木是一棵生长在奥迪拉兰废墟内独特的古树。它的枝干和木材因其强大的魔法和自然属性而备受追捧。",al={"心木","心木任务","奥迪拉兰心木"}},{q="谁目前控制着这些废墟？",a="好战的蓟皮熊怪目前占据着这些废墟，他们杀死了或驱逐了之前居住在此处的暗滩教派教徒。",al={"谁住在这里","奥迪拉兰有什么人","奥迪拉兰怪物"}}},fx={["39060ab5"]={q="奥迪拉兰废墟是什么地方？",a="奥迪拉兰废墟是一处古老的暗夜精灵聚居地遗迹，位于灰谷西北部，迈斯特拉岗哨以北、巴斯兰鬼屋以南。这里曾是一座繁荣的城市，如今仅剩坍塌的石柱、杂草丛生的石砌建筑，以及矗立在遗址中的神秘心木树。",al={"奥迪拉兰废墟是什么","奥迪拉兰传说","奥迪拉兰废墟"}},c163d8f1={q="奥迪拉兰废墟发生了什么？",a="数千年前，这座古老的暗夜精灵城市沦为废墟，此后这处偏僻之地便成了阴险的暗滩教派的避难所。然而，最近蓟皮部族的凶暴熊怪侵入此地，引发了激烈冲突。他们屠杀了教徒，并占据了这片残垣断壁。",al={"奥迪拉兰历史","奥迪拉兰发生了什么","奥迪拉兰废墟的过往"}},["511b2ee8"]={q="奥迪拉兰废墟危险吗？",a="是的，那里极其危险。最近夺取废墟的蓟皮熊怪对所有外来者都怀有强烈敌意，会攻击任何靠近的人。此外，残留的黑暗魔法和黑暗教派的遗迹也让在这些古老石碑附近徘徊成为致命之举。",al={"奥迪拉兰危险吗","奥迪拉兰的威胁","奥迪拉兰的危险"}}},fp="19,291,16.608.0,31.233.0,51.224.0,23.172.0,33.149.0"}
P.entries["subzone:ruins-of-ravenwind"] = {n="鸦风废墟",s="鸦风废墟是坐落在菲拉斯北部的一座古代上层精灵城市的破碎遗迹。如今，这些摇摇欲坠的大理石建筑被凶残的北泉鹰身人所占据，并由沉思的龙人所守卫。",h="鸦风废墟是坐落在菲拉斯北部的一座古代上层精灵城市的破碎遗迹。如今，这些摇摇欲坠的大理石建筑被凶残的北泉鹰身人所占据，并由沉思的龙人所守卫。",kw={"羽月","菲拉斯","鹰身人","上层精灵","加德米尔","北泉","鸦风"},ang={["faction:Alliance"]="像羽月要塞这样的前哨站密切关注着鸦风废墟，并派遣勇敢的侦察兵去回收强大的魔法遗物，以免它们被野兽或更黑暗的力量所吞噬。",["race:NightElf"]="对于卡多雷而言，这些遗迹痛苦地提醒着他们，那个鲁莽的奥术帝国曾将古老的卡利姆多撕裂，而如今这里又被鹰身人和野兽所亵渎。"},sec={{t="上层精灵的回响",b="就像东部的宏伟城市厄运之槌一样，鸦风废墟是古代上层精灵文明在天崩地裂前达到巅峰与傲慢的庄严纪念碑。这处遗址早已被其最初的卡多雷建造者所遗弃，如今已沦为蔓生的野生植被、被遗忘的奥术祭坛以及北泉鹰身人巢穴的栖息地，这些鹰身人捕食着任何在破碎拱门下徘徊的生物。"},{t="野生危险的汇聚点",b="除了尖啸的鹰身人之外，鸦风废墟周边还存在着各种各样的领地威胁。被称为“加德米尔”的凶猛绿龙人盘旋在中央树林和水道上空，守护着古老的树木遗迹。与此同时，流浪的过客——从心不在焉的暗夜精灵探险家到附近徘徊的奇怪而孤独的豺狼人——经常发现自己陷入了遗迹残留的魔法和野生掠食者的交火之中。"}},faq={{q="是谁建造了鸦风废墟？",a="该定居点由数千年前的卡多雷文明贵族阶层——上层精灵所建造。在天崩地裂之后，它和厄运之槌以及菲拉斯各地的其他精灵古迹一样，沦为了废墟。",al={"谁建造了鸦风","鸦风历史","鸦风废墟起源"}},{q="目前是什么生物盘踞在废墟中？",a="废墟被北泉鹰身人所充斥，这些野蛮的鸟形野兽在破碎的石料间筑巢。此外，加德米尔龙人潜伏在周围的水域和中央树林中，凶猛地守卫着当地的植被。",al={"鸦风怪物","鸦风住着什么","鸦风鹰身人"}},{q="联盟为何要前往该地区？",a="驻扎在羽月要塞的联盟学者和哨兵派遣冒险者前往此地，发掘失落的奥术遗物，并与古老的祭坛互动，从而为艾奎尼克斯法杖等强大的神器充能。",al={"联盟鸦风任务","羽月鸦风"}}},fp="18,237,23.417.0,28.423.0,33.234.0,33.234.0,38.214.0"}
P.entries["subzone:ruins-of-stardust"] = {n="星尘废墟",s="星尘废墟是一座古老而破败的暗夜精灵圣所，坐落在灰谷西南部的一座湖心岛上。这里曾经是一处宁静的礼拜场所，但岛上的湖水和原生的沼泽兽却受到了从费伍德森林冲刷而下的恶魔腐蚀。尽管这种破坏无处不在，但发光的星尘灌木依然在残垣断壁间茁壮成长，保留着强大的恢复力量。",h="星尘废墟是一座古老而破败的暗夜精灵圣所，坐落在灰谷西南部的一座湖心岛上。这里曾经是一处宁静的礼拜场所，但岛上的湖水和原生的沼泽兽却受到了从费伍德森林冲刷而下的恶魔腐蚀。尽管这种破坏无处不在，但发光的星尘灌木依然在残垣断壁...",kw={"灰谷","沼泽兽","费伍德腐蚀","暗夜精灵废墟","星尘废墟","星尘灌木","水体腐蚀"},ang={["class:Shaman"]="在这里发现的未受腐蚀的星尘是精神试炼中的重要净化试剂，包括掌握恢复元素的关键试炼“Call of Water”。",["race:NightElf"]="看着这座曾经的圣所屈服于费伍德森林缓慢而腐烂的径流，这令人痛苦地提醒着人们，保护灰谷免受持续恶魔腐蚀的斗争仍在继续。"},sec={{t="一处被荒废的圣所",b="星尘废墟位于阿斯特兰纳南部的孤岛上，曾经是受人尊敬的暗夜精灵圣地。如今，一种怪异、病态的黄绿色调笼罩在水面上——这是从费伍德森林向南流下的恶魔腐臭造成的后果，就像附近的伊瑞斯湖一样。当地的植物已经扭曲成了敌对的沼泽兽，在倒塌的石砌建筑间徘徊，它们的性情也因这片受污染的湖水而变得狂暴。"},{t="不朽的星尘",b="尽管土壤和海岸线充斥着腐蚀，但这座岛屿仍拥有一种不屈的韧性。星尘灌木散布在废墟之中，绽放着未被恶魔污染的花朵。它们的叶片和花朵具有非凡的净化和治疗功效，吸引了寻求对抗灰谷不断蔓延的腐朽之法的萨满、草药师和当地的暗夜精灵保卫者。"}},faq={{q="星尘废墟最初的用途是什么？",a="在古代，这个地方是暗夜精灵照料的神圣土地。早在恶魔腐蚀在这个森林中扎根之前，这里经典的在大理石柱和湖畔环境就是一处宁静的崇拜之地。",al={"什么是废墟","星尘背景故事","谁建造了星尘"}},{q="为什么岛屿周围的水变色了？",a="恶魔腐蚀从费伍德森林那受损的山峰渗透到灰谷的水道中，污染了湖水，使水体呈现出浑浊的黄绿色，并破坏了自然平衡。",al={"为什么水是绿色的","为什么湖泊被腐蚀了","星尘之水"}},{q="是什么让星尘灌木如此特别？",a="尽管生长在浸透了恶魔径流的土壤中，星尘灌木依然保持着完全的纯净。它们抵御了环境污染，并拥有非凡的恢复和治疗特性，使它们成为净化仪式中极具价值的试剂。",al={"什么是星尘灌木","星尘植物","星尘灌木丛"}},{q="有什么生物在废墟中游荡？",a="岛上到处都是大型、被腐蚀的沼泽兽。湖泊受污染的水将这些自然元素生物从宁静的森林守护者变成了对任何穿越浅滩的人具有攻击性的沉重威胁。",al={"星尘怪物","这里有什么怪物","沼泽兽"}}},fx={dd3713f4={q="星尘废墟是什么地方？",a="星尘废墟位于灰谷西南部一处静谧湖泊的岛上，在阿斯特兰纳以南、石爪小径以西。这里曾是一处古老而神圣的暗夜精灵圣地，如今却在受费伍德森林恶魔腐化污染的湖水中日渐衰败。尽管腐化不断蔓延，石砌建筑也已残破，坚韧的星尘灌木仍在地面上茁壮生长。",al={"星尘废墟是什么地方","星尘废墟的背景","关于星尘废墟"}},["7e5a1a00"]={q="星尘废墟发生了什么？",a="这座岛最初由暗夜精灵奉为圣地。数千年过去，它最终逐渐荒废。第三次战争期间，恶魔腐化从费伍德森林向南渗透，污秽的腐化侵染了周围水域，使岛屿受到污染，当地野生动物也变异成了具有攻击性的沼泽兽。",al={"星尘废墟的历史","星尘废墟发生了什么","星尘废墟为何遭到腐化"}},["74a8e036"]={q="星尘废墟危险吗？",a="危险。周围水域受到恶魔腐化影响，变成了病态的黄绿色；岛上和岸边还游荡着体型庞大、极具攻击性的沼泽兽。若想抵达废墟，或采集那里生长的疗愈星尘灌木，你必须一路击退这些被腐化的生物。",al={"星尘废墟的危险","星尘废墟安全吗","星尘废墟的威胁"}},["68167cf8"]={q="为什么叫星尘废墟？",a="废墟因碎石间生长的独特星尘灌木而得名。尽管岛上的土壤和水域已遭恶魔腐化，这些光彩夺目的植物却丝毫未受侵染，叶片中蕴含着强大的疗愈力量。",al={"星尘废墟为何得名","星尘废墟的名称","星尘之名的由来"}}},fp="17,400,20.409.0,21.391.0,52.222.0,46.201.0,39.232.0,32.212.0"}
P.entries["subzone:ruins-of-thaurissan"] = {n="索瑞森废墟",s="索瑞森废墟是黑铁部族最初在燃烧平原上的地表首都留下的焦黑残骸。它曾是一座坐落在赤脊山北部郁郁葱葱的崇山峻岭中的辉煌城市，但在三锤之战中，当大巫师索瑞森无意间召唤出炎魔拉格纳罗斯时，这座城市化为了一片灰烬。",h="索瑞森废墟是黑铁部族最初在燃烧平原上的地表首都留下的焦黑残骸。它曾是一座坐落在赤脊山北部郁郁葱葱的崇山峻岭中的辉煌城市，但在三锤之战中，当大巫师索瑞森无意间召唤出炎魔拉格纳罗斯时，这座城市化为了一片灰烬。",kw={"阿克瑟努斯","燃烧平原","黑铁部族","拉格纳罗斯","索瑞森废墟","大巫师","索瑞森","三锤之战"},ang={["faction:Alliance"]="在铁炉堡皇家历史学家阿克瑟努斯的委托下，联盟的侦察兵和研究人员搜寻着这些仍在冒烟的地基，寻找揭示黑石山主人真相的遗物。",["race:Dwarf"]="对于铁炉堡的矮人来说，这些废墟是一座严酷的纪念碑，记录着黑铁部族在三锤之战中的傲慢，以及召唤元素力量所付出的惨痛代价。"},sec={{t="一个王国的覆灭",b="大约两个世纪前，在至高王莫迪姆斯·安威玛尔死后，黑铁部族被驱逐出铁炉堡，随后他们向南迁徙并建立了索瑞森城。在三锤之战的最紧要关头，面对铜须部族和蛮锤部族联军的全面围攻，大巫师索瑞森试图寻找一种终极武器来扭转局势。他与七名心腹法师深入地下，引导古老的魔法。他们的仪式并没有召唤出一个顺从的仆人，反而撕裂了一条通往元素位面的通道，并召唤出了炎魔拉格纳罗斯。这场灾难性的喷发震碎了周围的山脉，将翠绿的土地烧成了灰烬弥漫的燃烧平原，隆起了黑石山的火山，并将城市化为焦土。"},{t="灰烬中的回响",b="今天，破碎的砖石和倒塌的柱子散落在荒原上，这里盘踞着巡逻的黑铁部族残党和火元素。在铁炉堡皇家历史学家阿克瑟努斯的指引下，联盟派遣了探险队来发掘埋藏在灰烬下的古代遗物。触碰这些被附魔的遗物，会让人感受到那场灾难中鲜活而恐怖的记忆：八名矮人在绝望中吟唱的幻象、七具尸体散落在一名独自跪地的法师周围，以及一座巍峨的原始烈焰巨碑，它夺走了整个部族的灵魂与自由。"}},faq={{q="索瑞森城在被摧毁前是什么地方？",a="那是索瑞森城，黑铁部族引以为傲的地表首都。在至高王莫迪姆斯·安威玛尔死后，他们被驱逐出铁炉堡并建立了这座城市，在它彻底毁灭之前，这里曾是他们新兴王国的中心。",al={"索瑞森城背景","什么是索瑞森","索瑞森的建造者"}},{q="这座城市是如何被摧毁的？",a="为了在三锤之战中击败其他矮人部族，大巫师索瑞森孤注一掷，试图召唤一个强大的超自然仆从。仪式打破了束缚在地底的拉格纳罗斯的枷锁。炎魔的暴力降临引发了世界末日般的火山喷发，将城市及周边郁郁葱葱的山谷化为焦土废墟。",al={"索瑞森的焚毁原因","摧毁索瑞森的元凶","谁摧毁了索瑞森"}},{q="为什么废墟周围的地面是一片灰烬荒原？",a="燃烧平原曾经是赤脊山北部肥沃的绿色区域。拉格纳罗斯被召唤时引发的爆炸性灾难撕裂了大地，隆起了黑石山，并将整片广袤的土地烧成了一片干旱、灰烬弥漫的荒野。",al={"燃烧平原灰烬成因","此地发生了什么","与赤脊山的联系"}},{q="幸存的黑铁矮人去了哪里？",a="幸存者被拉格纳罗斯及其元素爪牙奴役。他们撤退到黑石山深处建造了暗炉城，抛弃了沦为荒原的故都，在为炎魔的效力中受尽苦难。",al={"黑铁部族的现状","暗炉城的起源"}}},fp="19,344,21.775.0,17.557.1,43.249.0,27.352.0,54.256.0,45.232.0"}
P.entries["subzone:ruins-of-uldum"] = {n="Ruins of Uldum",s="坐落在塔纳利斯南部守卫之谷的锯齿状悬崖中，Ruins of Uldum由一座守卫着封印的泰坦设施的古老石厅组成。巨大的石门保护着这里的秘密，使其免受盗墓者和好奇探险家的侵扰。",h="坐落在塔纳利斯南部守卫之谷的锯齿状悬崖中，Ruins of Uldum由一座守卫着封印的泰坦设施的古老石厅组成。巨大的石门保护着这里的秘密，使其免受盗墓者和好奇探险家的侵扰。",kw={"土灵","塔纳利斯","泰坦","奥丹姆","守卫之谷"},ang={["profession:Mining"]="奥丹姆的石雕和机械展现了泰坦的精湛工艺，历经数千年的构造压力和沙漠侵蚀依然屹立不倒。",["race:Dwarf"]="对于追溯血统至土灵的矮人来说，奥丹姆代表了最初的泰坦育婴室之一，他们的祖先在大分裂后曾在此地首次休憩。"},sec={{t="泰坦前厅",b="Ruins of Uldum深嵌在塔纳利斯南部的基岩之中，看起来像是通往一个更大、已封印的地下综合体的门厅或宏伟入口。其巨大的石门紧闭，拒绝外界的干扰，现代学者所知的任何机制或钥匙都无法将其打开。"},{t="生物圈的秘密",b="根据古代记录和天象观测者的说法，奥丹姆是由泰坦与奥达曼和奥杜尔等设施一同建立的，旨在研究、修改和监测艾泽拉斯生物圈的研究基地。当大分裂在万年前撕裂世界时，土灵感受到了世界的痛苦，并退回这些地下拱顶中进行休眠。若要获得通往遗迹封印的内部入口之后的完全访问权限，需要失落的奥丹姆石板，因此该设施的全部范围仍然对现代地表居民封闭。"}},faq={{q="Ruins of Uldum里面有什么？",a="没人能确定。这些遗迹是一座封印在巨大石门后的古老泰坦大厅，石门后的综合体至今仍未向现代探险家开放。",al={"奥丹姆里有什么","塔纳利斯的奥丹姆是什么","ruins of uldum内部"}},{q="玩家可以进入门后的主要设施吗？",a="不可以。大门仍然处于封闭状态。诺甘农的石卫士表示，只有携带失落的奥丹姆石板的人才被允许进入奥丹姆大院，而目前还没有人找到它们。",al={"可以打开奥丹姆的门吗","如何进入奥丹姆","打开奥丹姆大门"}},{q="奥丹姆是为什么而建的？",a="诺甘农的石卫士等泰坦构装体将奥丹姆描述为一个旨在研究、维持和增强艾泽拉斯生物圈的研究综合体，其起源与奥达曼和奥杜尔等地点类似。",al={"泰坦为什么要建造奥丹姆","奥丹姆的目的","奥丹姆背景故事"}}},fp="14,254,29.299.0,24.555.1,34.160.0,52.186.0,25.205.0"}
P.entries["subzone:ruins-of-zul-mamwe"] = {n="祖玛维废墟",s="祖玛维废墟隐匿在莫什奥格食人魔山以南的山区凹地中，是裂颅者巨魔部族的一座戒备森严的据点。这座古老的石制平台几乎四面环绕着陡峭的悬崖，在残暴的首领“冷酷的安纳塞克”的统治下，如今这里到处都是凶猛的丛林巨魔。",h="祖玛维废墟隐匿在莫什奥格食人魔山以南的山区凹地中，是裂颅者巨魔部族的一座戒备森严的据点。这座古老的石制平台几乎四面环绕着陡峭的悬崖，在残暴的首领“冷酷的安纳塞克”的统治下，如今这里到处都是凶猛的丛林巨魔。",kw={"安纳塞克","冷酷的安纳塞克","古拉巴什","丛林巨魔","裂颅者","荆棘谷","祖玛维"},ang={["race:Troll"]="对于效忠部落的暗矛巨魔来说，祖玛维是一个发人深省的提醒，时刻警示着那些拒绝放弃嗜血传统、无法适应更广阔世界的丛林亲族们，他们正走在野蛮而封闭的道路上。"},sec={{t="裂颅者的据点",b="祖玛维废墟是裂颅者部族在中部荆棘谷的主要权力中心之一。该遗址坐落于天然的环形山谷之中，仅有北部一条通路，使其成为了极其优越的防御堡垒。在那风化的金字塔和石质梯台之上，首领“冷酷的安纳塞克”指挥着他的战士和巫医，奋力捍卫领土，抵御着外来冒险者和敌对丛林巨魔部族的侵袭。"},{t="古代帝国的遗迹",b="正如点缀在丛林中的许多石制聚落一样，祖玛维是古老的古拉巴什帝国的遗迹，该帝国曾统治过这片大陆的南部疆域。虽然伟大的帝国早已分裂成互相争斗、敌对的派系，但现代的裂颅者部族仍在这些祖先的石刻间顽强地坚守，在杂草丛生的砖石和残破的巨石阵中延续着古老的部族仪式。"}},faq={{q="谁控制着祖玛维废墟？",a="这些废墟由裂颅者巨魔部族占据，他们是荆棘谷中两个主要且具有侵略性的丛林巨魔部族之一。他们在现场由其首领“冷酷的安纳塞克”指挥。",al={"这里住着谁","祖玛维巨魔","谁拥有祖玛维"}},{q="祖玛维位于哪里？",a="祖玛维位于中部荆棘谷，就在莫什奥格食人魔山的南边。这个营地几乎四面都被高耸的山脉环绕，主要通过北面的一条山谷通道进出。",al={"如何前往祖玛维","祖玛维位置","它在哪里"}},{q="为什么裂颅者会对旅行者充满敌意？",a="裂颅者部族极度排外且对外界怀有敌意，视所有其他种族和敌对的巨魔部族为闯入他们祖先领地的入侵者。在“冷酷的安纳塞克”的领导下，他们会攻击任何接近他们丛林圣地的人。",al={"巨魔为什么攻击","裂颅者敌意"}},{q="这些废墟背后的历史是什么？",a="祖玛维的石制结构可以追溯到古拉巴什帝国的鼎盛时期。在帝国崩溃并分裂成相互交战的派系后，裂颅者占据了这里作为内陆作战基地，并保留了其古老的石质梯台。",al={"废墟历史","谁建造了祖玛维","祖玛维背景故事"}}},fp="18,340,32.494.0,29.411.0,36.201.0,27.218.0,48.260.0,39.254.0"}
P.entries["subzone:rustmaul-dig-site"] = {n="锈锤挖掘场",s="锈锤挖掘场是位于闪光平原南端的一处废弃挖掘场。它最初由铁炉堡的探险者协会建立，旨在发掘古代遗迹，但在部落的一支战争小队屠杀了这里的矿工之后，这里便陷入了悲剧，随后地下涌出了异种虫群。如今，这里已被凡人遗弃，到处都是从地下洞穴中爬出的充满敌意的昆虫生物。",h="锈锤挖掘场是位于闪光平原南端的一处废弃挖掘场。它最初由铁炉堡的探险者协会建立，旨在发掘古代遗迹，但在部落的一支战争小队屠杀了这里的矿工之后，这里便陷入了悲剧，随后地下涌出了异种虫群。如今，这里已被凡人遗弃，到处都是从地下...",kw={"探险者协会","铁石营地","摩克塔·克林","锈锤挖掘场","闪光平原","异种虫","千针石林"},ang={["faction:Horde"]="尽管摩克塔·克林的战争小队声称战胜了矮人挖掘者，但在战斗结束后，一种古老而恐怖的异种虫威胁随之出现，如今正威胁着整个地区。",["race:Dwarf"]="对于铁炉堡的矮人来说，锈锤挖掘场是探险者协会所面临危险的悲剧性提醒，因为在大地本身塌陷向恐怖的昆虫之前，他们的学者就已经在此被屠杀。"},sec={{t="盐碱地上的屠杀",b="来自铁炉堡探险者协会的探矿者们建立了锈锤挖掘场，希望发掘出掩埋在盐碱平原下的遗忘神器。然而，随着摩克塔·克林率领的一支充满攻击性的部落战争小队突袭营地并屠杀了矮人挖掘者，他们的努力被残酷地打断了。然而，征服者们并没有享受到胜利。这场激烈的冲突似乎惊动了遗址下方休眠的洞穴网络，释放出了无穷无尽的异种虫群，迅速淹没并驱逐了伤痕累累的幸存者。"},{t="苏醒的虫群",b="如今，锈锤挖掘场对于地表种族而言已彻底沦陷。仅存的采矿设备和脚手架掩埋在爬行的节肢和异形的甲壳之下。摩克塔·克林战争小队的幸存者们向北撤退到了铁石营地，被袭击后涌出的无穷无尽的虫群吓破了胆。"}},faq={{q="什么是锈锤挖掘场？",a="它是位于千针石林闪光平原内的一处挖掘营地。矮人探险家最初在此建立它是为了发掘古代遗迹，但后来它被致命的异种虫群占领了。",al={"什么是锈锤","锈锤背景故事","闪光平原挖掘场"}},{q="过去是谁住在这里并在此工作？",a="来自矮人探险者协会的探矿者和挖掘工最初在此进行挖掘作业，发掘埋藏在盐碱平原下的文物和遗迹。",al={"谁挖掘了锈锤","谁拥有锈锤","在锈锤的矮人"}},{q="为什么挖掘场被遗弃且充满了虫子？",a="由摩克塔·克林率领的部落战争小队袭击了营地并屠杀了矮人。这场骚乱似乎惊动了矿洞内位于地下的异种虫巢穴，释放出的虫群驱散了幸存的袭击者。",al={"锈锤发生了什么","为什么锈锤有虫子","谁袭击了锈锤"}},{q="幸存的袭击者去了哪里？",a="摩克塔·克林的部落战争小队残部伤痕累累，向北逃过平原，撤退到铁石营地休整，信使们甚至将警告传回了奥格瑞玛。",al={"摩克塔·克林在哪里","锈锤的幸存者","铁石营地联系"}}},fx={["55b33fa4"]={q="锈锤挖掘场发生了什么？",a="探险者协会的矮人考古学家当时正在此处发掘古代遗迹，摩克塔·克林率领的一支部落军队突然袭击了他们，将现场的矮人全部屠杀。这场暴力冲突似乎惊动了洞穴深处的地下异种虫巢穴。一股势不可挡的虫群从深处涌出，击溃并赶走了伤痕累累的部落袭击者，占据了整个挖掘场。",al={"锈锤挖掘场的历史","锈锤发生了什么","锈锤屠杀事件"}},d4492c4a={q="锈锤挖掘场危险吗？",a="那里极其危险。贪婪的异种虫遍布挖掘沟壑，在中央洞穴中成群出没。任何进入其中的旅人都有被虫群包围并吞噬的危险，正如那些伤痕累累的幸存袭击者最终被虫群的数量压倒、赶走一样。",al={"锈锤危险吗","锈锤挖掘场的威胁","锈锤的危险"}}},fp="17,399,23.531.0,19.332.0,30.196.0,31.152.0,47.241.0,37.170.0"}
P.entries["subzone:rut-theran-village"] = {n="鲁瑟兰村",s="鲁瑟兰村是一个位于泰达希尔南麓的海滨避风港。它作为达纳苏斯的主要海运港口，通过渡轮和角鹰兽航线将与世隔绝的世界之树与卡利姆多大陆连接起来。",h="鲁瑟兰村是一个位于泰达希尔南麓的海滨避风港。它作为达纳苏斯的主要海运港口，通过渡轮和角鹰兽航线将与世隔绝的世界之树与卡利姆多大陆连接起来。",kw={"奥伯丁","黑海岸","达纳苏斯","码头","角鹰兽","moonspray","港口","鲁瑟兰","泰达希尔"},ang={["class:Druid"]="从神圣的月光林地避难所归来的德鲁伊可以乘坐塞纳里奥角鹰兽，从永夜港直接飞越卡利姆多北部抵达鲁瑟兰村。",["race:NightElf"]="对于离开泰达希尔去援助联盟的年轻暗夜精灵来说，鲁瑟兰村是他们在航向卡利姆多大陆前，对世界之树树冠的最后告别。"},sec={{t="通往世界之树的门户",b="Perched at the water's edge below the towering heights of Teldrassil, Rut'theran Village acts as the threshold between the night elven capital and the wider world. While Darnassus rests within the boughs high above, Rut'theran provides the logistical foundation required to sustain it. A mystical portal arches beneath the trees, whisking travelers between the shore and Darnassus in an instant. For journeys across the sea, ferry service runs from the village docks directly to Auberdine on the mainland of Darkshore, accompanied by flight masters tending dedicated roosts of trained hippogryphs."}},faq={{q="我该如何从这里前往达纳苏斯？",a="从码头沿着平缓的坡道向巨大的凉亭帐篷走去。踏上平台那闪烁着紫色光芒的传送门，你就能瞬间传送到位于达纳苏斯内部的神殿花园。",al={"前往达纳苏斯","通往达纳苏斯的传送门","如何到达达纳苏斯"}},{q="码头上的船去往哪里？",a="停靠在鲁瑟兰村的船只“Moonspray”号，提供穿过迷雾之海前往黑海岸沿岸奥伯丁镇的航线。",al={"船去哪里","鲁瑟兰渡轮","鲁瑟兰航线"}},{q="为什么这个村庄是在海平面而不是在树上？",a="泰达希尔的树冠太高，无法容纳常规帆船或进行海上贸易。鲁瑟兰村建立在其根部，旨在提供一个海平面的港口和栖息地，并通过永久的传送门与高处相连。",al={"为什么鲁瑟兰在海平面","为什么在泰达希尔底部"}},{q="我能从这里飞往任何地方吗？",a="是的。村庄的栖息地有一位角鹰兽训练师，提供飞越水域前往黑海岸的奥伯丁的飞行路线，而从月光林地归来的德鲁伊则会乘坐塞纳里奥议会从永夜港飞来的角鹰兽在这里降落。",al={"鲁瑟兰飞行点","角鹰兽能飞去哪里"}}},fx={["4018ea8f"]={q="鲁瑟兰村是什么地方？",a="鲁瑟兰村是坐落在泰达希尔山脚下的海滨港口聚落。达纳苏斯位于世界之树的枝干高处，因此这处海边避风港成为重要的海上门户，连接着暗夜精灵与卡利姆多大陆及更广阔的世界。",al={"这是什么地方","鲁瑟兰村","鲁瑟兰村概况"}},b57f91d4={q="鲁瑟兰村发生了什么？",a="第三次战争结束后，鲁瑟兰村伴随着泰达希尔的生长而建立。它为隐居的卡多雷提供了一处便于抵达的海平面港口，此后平静地发展成繁忙的入口，船夫、角鹰兽管理员和守卫在此忙碌，守护着巨树的根部。",al={"鲁瑟兰村的历史","鲁瑟兰村的过往","这里发生了什么"}},["2418ef2b"]={q="谁住在鲁瑟兰村？",a="聚落里住着暗夜精灵看护者、渔民和哨兵，他们负责守卫泰达希尔的根部。这里还有专门照料角鹰兽、护送旅客渡海的管理员，让达纳苏斯的枝干与黑海岸的大陆海岸紧密相连。",al={"谁住在这里","鲁瑟兰村居民","鲁瑟兰村人口"}},["854f3298"]={q="鲁瑟兰村危险吗？",a="不危险，这里是联盟一处宁静且守卫森严的庇护所。村庄藏在泰达希尔的树冠下，由卡多雷哨兵守护，访客可以安心休息、自由往来，无须担心村中有敌对野兽或潜伏的敌人。",al={"鲁瑟兰村危险吗","鲁瑟兰村的威胁","这里安全吗"}}},fp="18,232,25.597.0,36.205.0,37.144.0,64.242.0,29.225.0"}
P.entries["subzone:saldean-s-farm"] = {n="萨丁农场",s="萨丁农场是西部荒野中唯一没有被迪菲亚潜行者彻底占领并荒废的家园。在顽固的农夫萨丁和他妻子萨尔玛·萨丁的坚守下，这座农舍成为了该地区动荡局势中一处难得的避风港。",h="萨丁农场是西部荒野中唯一没有被迪菲亚潜行者彻底占领并荒废的家园。在顽固的农夫萨丁和他妻子萨尔玛·萨丁的坚守下，这座农舍成为了该地区动荡局势中一处难得的避风港。",kw={"农夫萨丁","收容所","收割傀儡","难民","萨丁","萨尔玛·萨丁","西部荒野"},ang={["faction:Alliance"]="萨丁农场代表了王国边境原始而颓败的一角，暴露了当暴风城的领导层心不在焉时，普通公民所遭受的苦难有多深。",["profession:Cooking"]="萨尔玛·萨丁因能将搜集来的西部荒野食材烹饪成如血牙野猪的肝馅饼这样热乎且能救命的菜肴，而在旅人中享有盛誉。"},sec={{t="尘土中的灯塔",b="当周边的土地沦陷于强盗劫掠和机械破坏时，萨丁一家拒绝放弃他们的土地。农夫萨丁和他的妻子萨尔玛·萨丁一直留守在他们的家园，为过往的旅人提供热食和一句温暖的话语。尽管他们十分坚韧，但农田依然饱受徘徊在平原上的失控收割傀儡之苦，迫使这一家人只能紧守在农舍围墙附近。"},{t="坚守阵线",b="由于暴风城王室在很大程度上忽视了西部荒野，这里的治安力量非常薄弱。虽然有少数来自哨兵岭和暴风城的卫兵在周边巡逻，但农场的生存主要靠的是坚韧不拔的毅力和过往旅行者的援助。对于萨丁一家来说，萨尔玛·萨丁著名的西部荒野炖肉、血牙野猪的肝馅饼以及农舍提供的庇护，都是对抗迪菲亚潜行者时刻威胁的小小慰藉。"}},faq={{q="为什么其他农场都陷落了，而这座农场还能屹立不倒？",a="当迪菲亚潜行者席卷西部荒野时，农夫萨丁和他的妻子只是拒绝收拾行囊逃离。尽管充满敌意的收割傀儡在他们的庄稼地里游荡，这一家人还是在过往民兵和冒险者的帮助下，顽强地保卫着农舍周边的区域。",al={"为什么没有被占领","萨丁农场的生存","农场是如何存活下来的"}},{q="聚集在房子周围的都是些什么人？",a="农场的常驻民是农夫萨丁和他的妻子萨尔玛·萨丁；你在那里发现的其他任何人都可能是过往的旅人，因为这对夫妇欢迎访客，也欢迎愿意帮助他们解决困扰农田威胁的冒险者。",al={"萨丁农场的难民","西部荒野的流浪者","农场的孤儿"}},{q="为什么机械傀儡会袭击农田？",a="迪菲亚潜行者将该地区的机械收割机和傀儡改造为了致命的哨兵。它们在田野间游荡，攻击任何试图耕作或清理土地的人。",al={"收割傀儡","为什么庄稼地里有机器人","机械稻草人"}},{q="暴风城军队在保护这座农场吗？",a="官方的军事力量几乎不存在。几名从哨兵岭和暴风城派来的零星守卫只能提供最低限度的警戒，王室在很大程度上将西部荒野的防御留给了当地人自行解决。",al={"暴风城军事存在","哨兵岭守卫在这里","守卫支持"}}},fx={a60e97c5={q="萨丁农场是什么地方？",a="萨丁农场是西部荒野仅存的几处尚未完全落入迪菲亚潜行者之手的农庄之一。周边土地满目疮痍或已被遗弃，这座顽强的农庄仍矗立在北部平原，在这片衰败之地中为人们提供持久的庇护。",al={"萨丁农场是什么地方","萨丁农场概况","萨丁农场背景"}},a483aabd={q="为什么叫萨丁农场？",a="农场以农夫萨丁和他的妻子萨尔玛·萨丁命名。西部荒野的大多数地主都在迪菲亚潜行者掌控局势后逃离了这里，萨丁一家却顽强地坚守家园，拒绝离开，并为路过的旅人提供食物和温言相待。",al={"谁给萨丁农场命名","萨丁农场名称的含义","萨丁农场为何得名"}}},fp="14,249,20.398.0,16.415.0,53.267.0,49.228.0,47.189.0,42.204.0"}
P.entries["subzone:saltspray-glen"] = {n="盐沫沼泽",s="盐沫沼泽是位于湿地西北部的一片广袤荒野，紧邻巴拉丁海湾。强劲的海风经常将咸涩的海水吹过这片长满苔藓的低地，而这里到处都是极具攻击性的野生迅猛龙。它构成了一条险峻的自然通道，连接着周围鱼人出没的沼泽和古老的矮人遗迹。",h="盐沫沼泽是位于湿地西北部的一片广袤荒野，紧邻巴拉丁海湾。强劲的海风经常将咸涩的海水吹过这片长满苔藓的低地，而这里到处都是极具攻击性的野生迅猛龙。它构成了一条险峻的自然通道，连接着周围鱼人出没的沼泽和古老的矮人遗迹。",kw={"巴拉丁海湾","蓝腮沼泽","铁须之墓","迅猛龙","盐沫沼泽","湿地"},ang={["class:Hunter"]="潜伏在沼泽湿润海草丛中的凶猛迅猛龙，为追踪海岸的猎人提供了丰厚的猎物，也是可靠而凶猛的野兽。"},sec={{t="咸盐与利爪",b="盐沫沼泽深藏在湿地的最西北角，这个名字来源于每当沿海大风刮起时，从巴拉丁海湾吹向内陆的海雾。它南临鱼人横行的蓝腮沼泽，东接铁须之墓静谧的悬崖，对于路过的旅人来说，这里几乎没有落脚之地。成群狡猾的野生迅猛龙在沼泽的草丛中筑巢，它们与来自附近恐龙岭和黑水沼泽的同类一起，在咸湿的平原上猎食。"}},faq={{q="为什么叫盐沫沼泽？",a="这片沼泽直接坐落在巴拉丁海湾的开阔海岸线上。每当猛烈的海上风从西北方横扫海湾时，海水就会化作浓重的咸雾，被吹向内陆的低洼地带。",al={"盐沫沼泽名字含义","为什么叫盐沫","名字起源"}},{q="盐沫沼泽里生活着什么生物？",a="这片沼泽里到处都是极具攻击性的野生迅猛龙，它们利用沿海的灌木丛和沼泽洼地作为理想的筑巢地。它们会毫不犹豫地伏击任何偏离大路的人。",al={"盐沫沼泽的怪物","盐沫迅猛龙","这里有什么"}},{q="盐沫沼泽通往哪里？",a="盐沫沼泽位于湿地西北部。它北临并西接巴拉丁海湾，南邻鱼人领地蓝腮沼泽，东接铁须之墓的岩石高地。",al={"盐沫沼泽位置","盐沫沼泽在哪里","边界"}}},fx={["4c44c0ba"]={q="盐沫沼泽是什么地方？",al={"盐沫沼泽是什么地方","湿地盐沫沼泽","盐沫沼泽在哪里"}}},fp="14,335,15.512.0,32.221.0,38.187.0,31.200.0"}
P.entries["subzone:salty-sailor-tavern"] = {n="Salty Sailor Tavern",s="Salty Sailor Tavern是藏宝海湾社交生活的核心，也是这座港口主要的旅店和休憩之所。它由地精旅店老板斯金德尔经营，欢迎来自两个阵营、寻求避开丛林险境的恶棍、雇佣兵和旅行者。",h="Salty Sailor Tavern是藏宝海湾社交生活的核心，也是这座港口主要的旅店和休憩之所。它由地精旅店老板斯金德尔经营，欢迎来自两个阵营、寻求避开丛林险境的恶棍、雇佣兵和旅行者。",kw={"黑水强盗","藏宝海湾旅店","守护石","salty sailor","斯金德尔"},ang={["class:Rogue"]="Salty Sailor Tavern拥挤而烟雾缭绕的大厅是交换传闻、聆听海盗闲聊，以及守护好你钱包的理想场所。"},sec={{t="丛林中的避风港",b="Salty Sailor Tavern坐落在藏宝海湾的木质阶梯之间，在黑水强盗的注视下提供温暖的床铺和烈酒。酒吧后面站着旅店老板斯金德尔，在各色海盗、商人和冒险者于这片中立之地交际时，他负责为客人们斟满酒杯。建筑外挂着一件巨大而奇特的古董——一块祖尔格拉布守护石——在这个繁忙的商业窝点中成为了一个奇怪的战利品。"}},faq={{q="是谁经营着Salty Sailor Tavern？",a="这家旅店及其相关服务由旅店老板斯金德尔管理，这位勤奋的地精专门为往来藏宝海湾的各色水手、雇佣兵和冒险者提供服务。",al={"旅店老板","谁是旅店老板","斯金德尔"}},{q="挂在旅店外面的那块大石头是什么？",a="建筑外悬挂着的是一块祖尔格拉布守护石，这是一件从丛林深处古老巨魔遗迹中带回的不祥遗物。",al={"外面的石头","祖尔格拉布之石","守护石"}},{q="联盟和部落的成员都能住在这里吗？",a="是的。和藏宝海湾的其他地方一样，Salty Sailor Tavern在热砂港的中立权威下运营。只要顾客遵守规矩且不拔出武器，联盟和部落的旅行者都可以自由地在这里休息。",al={"这里是中立的吗","允许联盟和部落进入","部落可以使用这家旅店吗"}}},fp="19,279,26.453.0,33.179.0,52.145.0,38.244.0"}
